localBoundaryHelpers.source:
function resolveInitWorkspaceRoot(ctx: CommandContext): string | null {
  const fromFlag = ctx.trimToNull(ctx.arg("--workspace"));
  try {
    return fromFlag ? resolveWorkspaceRoot(fromFlag) : resolveConfiguredWorkspaceRoot();
  } catch (error) {
    ctx.fatal(error instanceof Error ? error.message : String(error));
  }
}

function buildOnboardingLines(
  root: string,
  summary: CompanyOnboardingSummary,
  registration: WorkspaceAutoRegisterResult | null,
): string[] {
  const capitalisedMonth = MONTH_NAMES_DA[summary.fiscalYearStartMonth - 1];
  const monthName = capitalisedMonth ? decapitalize(capitalisedMonth) : `måned ${summary.fiscalYearStartMonth}`;
  const fiscalLabel = FISCAL_LABEL_DA[summary.fiscalYearLabelStrategy] ?? summary.fiscalYearLabelStrategy;
  const lines: string[] = [];

  lines.push("");
  lines.push(`Virksomheden '${summary.name}' er klar.`);
  lines.push("");
  lines.push("Oprettet:");
  lines.push(`  - Virksomhedsmappe: ${root}`);
  lines.push(`  - Hovedbog (ledger): ${companyPaths(root).db}`);
  lines.push(`  - Standardkontoplan: ${summary.accountCount} konti (resultat, balance, moms)`);
  if (registration?.status === "registered") {
    lines.push(`  - Registreret i Cockpit-workspacet som '${registration.slug}'`);
  } else if (registration?.status === "already-registered") {
    lines.push(`  - Allerede registreret i Cockpit-workspacet som '${registration.slug}'`);
  }

  // #241: the missing-payment-details warning used to live here too, but it is
  // now emitted to stderr by the dispatch handler so machine-consumers that
  // capture stdout never see it (and so a redirected stdout does not swallow
  // the warning). See buildPaymentDetailsWarningLines above.

  // A non-registered company carries `vatPeriod === null` — the onboarding
  // block surfaces "ikke momsregistreret" and points the owner at
  // 'company set-profile --vat-period <cadence>' should they later register.
  const isVatRegistered = summary.vatPeriod !== null;
  const vatLabel = isVatRegistered
    ? vatPeriodTypeLabelDa(summary.vatPeriod!)
    : "ikke momsregistreret";
  lines.push("");
  lines.push("Tjek disse indstillinger — de er svære at ændre senere:");
  lines.push(`  - Regnskabsår: starter 1. ${monthName} (${fiscalLabel})`);
  if (isVatRegistered) {
    lines.push(`  - Momsperiode: ${vatLabel}. Afregner du en anden momsperiode,`);
    lines.push(
      `    så kør 'init --vat-period month|quarter|half-year' (standard: quarter),`,
    );
    lines.push(
      `    eller 'init --no-vat' hvis virksomheden ikke er momsregistreret.`,
    );
  } else {
    lines.push(`  - Momsperiode: ${vatLabel}. Bliver virksomheden senere`);
    lines.push(
      `    momsregistreret, så sæt momsperioden med`,
    );
    lines.push(
      `    'company set-profile --vat-period month|quarter|half-year'.`,
    );
  }
  lines.push(`  - CVR: ${summary.cvr ?? "ikke sat — sæt det med 'init --cvr <DK########>'"}`);

  lines.push("");
  lines.push("Næste skridt:");
  if (!summary.cvr) {
    lines.push("  1. Sæt CVR-nummeret, så fakturaer og rapporter er korrekte.");
    lines.push("  2. Hent virksomhedens stamdata: 'rentemester company sync-cvr --company <sti>'.");
    lines.push("  3. Opret din første kunde: 'rentemester customer create --company <sti> ...'.");
    lines.push("  4. Bogfør dit første bilag, eller udsted din første faktura.");
  } else {
    lines.push("  1. Hent virksomhedens stamdata: 'rentemester company sync-cvr --company <sti>'.");
    lines.push("  2. Opret din første kunde: 'rentemester customer create --company <sti> ...'.");
    lines.push("  3. Bogfør dit første bilag, eller udsted din første faktura.");
  }
  lines.push("");
  lines.push("Se kontoplanen med: 'rentemester accounts list --company <sti>'.");

  return lines;
}

const FISCAL_LABEL_DA: Record<string, string> = {
  "end-year": "navngives efter slutåret",
  "start-year": "navngives efter startåret",
  span: "navngives som spænd (fx 2025/2026)",
};

export function buildPaymentDetailsWarningLines(): string[] {
  return [
    "ADVARSEL — ingen betalingsoplysninger:",
    "  Du har ikke angivet bank/IBAN. Fakturaer udstedt nu får INGEN",
    "  betalingsanvisning (BETALING-blok) på PDF'en — kunden kan ikke se,",
    "  hvor pengene skal hen. Sæt dem med 'rentemester company set-profile'",
    "  (--bank-name --bank-reg --bank-account --iban), før du sender fakturaer.",
  ];
}

domainFailurePredicatesAndEnvelopes.source:
export function resolveWorkspaceRoot(raw: string): string {
  if (raw.split(/[\\/]+/).includes("..")) {
    throw new Error("workspace root must not contain parent-directory ('..') segments");
  }
  const resolved = resolve(raw);
  if (!isAbsolute(resolved) || resolved.split(sep).includes("..")) {
    throw new Error("workspace root resolved to an unsafe path");
  }
  return resolved;
}

export function resolveConfiguredWorkspaceRoot(): string | null {
  const raw = process.env.RENTEMESTER_WORKSPACE;
  if (typeof raw !== "string" || raw.trim().length === 0) return null;
  return resolveWorkspaceRoot(raw.trim());
}

export function initialiseCompanyVolume(
  companyRoot: string,
  options: CompanyInitOptions = {},
): CompanyInitResult {
  if (options.fiscalYearStartMonth !== undefined && options.fiscalYearStartMonth !== null) {
    if (normalizeFiscalYearStartMonth(options.fiscalYearStartMonth) === null) {
      throw new Error("fiscalYearStartMonth must be an integer between 1 and 12");
    }
  }
  if (options.fiscalYearLabelStrategy !== undefined && options.fiscalYearLabelStrategy !== null) {
    if (normalizeFiscalYearLabelStrategy(options.fiscalYearLabelStrategy) === null) {
      throw new Error(
        "fiscalYearLabelStrategy must be one of end-year, start-year, span",
      );
    }
  }
  if (options.paymentTermsDays !== undefined && options.paymentTermsDays !== null) {
    if (normalizePaymentTermsDays(options.paymentTermsDays) === null) {
      throw new Error("paymentTermsDays must be an integer between 0 and 365");
    }
  }
  if (options.vatPeriodType !== undefined && options.vatPeriodType !== null) {
    if (normalizeVatPeriodType(options.vatPeriodType) === null) {
      throw new Error("vatPeriodType must be one of month, quarter, half-year, or null");
    }
  }

  const p = ensureCompanyDirs(companyRoot);
  const db = openDb(p.db);
  try {
    migrate(db);
    seedAccounts(db);
    // `migrate` runs before the chart exists in a freshly-created company, so
    // seed confirmed native control roles only after the chart is present.
    seedNativeAccountRoles(db);
    const cvr = normalizeCvr(options.cvr);
    const fiscalYearStartMonth =
      normalizeFiscalYearStartMonth(options.fiscalYearStartMonth) ?? 1;
    const fiscalYearLabelStrategy =
      normalizeFiscalYearLabelStrategy(options.fiscalYearLabelStrategy) ?? "end-year";
    const name = options.name?.trim() || DEFAULT_COMPANY_SETTINGS.name;
    const address = options.address?.trim() || null;
    const postalCode = options.postalCode?.trim() || null;
    const city = options.city?.trim() || null;
    const paymentTermsDays =
      normalizePaymentTermsDays(options.paymentTermsDays) ?? DEFAULT_PAYMENT_TERMS_DAYS;
    // `null` means "not VAT-registered" and is written through verbatim;
    // undefined (caller didn't pass anything) keeps the historical default
    // cadence so back-compat for callers who never specified vatPeriodType
    // is byte-identical to before.
    const vatPeriodType: VatPeriodType | null =
      options.vatPeriodType === null
        ? null
        : normalizeVatPeriodType(options.vatPeriodType) ?? DEFAULT_VAT_PERIOD_TYPE;
    db.query(
      `INSERT INTO companies (id, name, cvr, fiscal_year_start_month, fiscal_year_label_strategy,
                              address, postal_code, city, payment_terms_days, vat_period_type)
       VALUES (1, ?, ?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(id) DO UPDATE SET
         name = excluded.name,
         cvr = excluded.cvr,
         fiscal_year_start_month = excluded.fiscal_year_start_month,
         fiscal_year_label_strategy = excluded.fiscal_year_label_strategy,
         address = excluded.address,
         postal_code = excluded.postal_code,
         city = excluded.city,
         payment_terms_days = excluded.payment_terms_days,
         vat_period_type = excluded.vat_period_type`,
    ).run(
      name,
      cvr,
      fiscalYearStartMonth,
      fiscalYearLabelStrategy,
      address,
      postalCode,
      city,
      paymentTermsDays,
      vatPeriodType,
    );
    // #221: capture payment details once — create the primary bank account so
    // every customer-facing invoice PDF shows where to pay.
    if (hasPaymentInfo(options.payment)) {
      upsertPrimaryBankAccount(db, DEFAULT_COMPANY_SETTINGS.currency, options.payment);
    }
    const policy = join(p.config, "policy.yaml");
    if (!existsSync(policy)) {
      writeFileSync(policy, buildDefaultPolicyYaml(options.onboardingActor));
    }
    runSql(db,
      "INSERT INTO audit_log (event_type, entity_type, message) VALUES ('init','company','Company volume initialized')",
    );
  } finally {
    db.close();
  }
  return { companyRoot, dbPath: p.db };
}

const DEFAULT_COMPANY_SETTINGS: CompanySettings = {
  id: 1,
  name: "Rentemester company",
  country: "DK",
  currency: "DKK",
  cvr: null,
  fiscalYearStartMonth: 1,
  fiscalYearLabelStrategy: "end-year",
  address: null,
  postalCode: null,
  city: null,
  companyForm: null,
  industryCode: null,
  industryText: null,
  cvrStatus: null,
  auditWaived: null,
  cvrSyncedAt: null,
  paymentTermsDays: DEFAULT_PAYMENT_TERMS_DAYS,
  // Keep the module's eager default independent of the close/VAT graph.
  // `periods.ts` imports the close-readiness graph, which eventually reads
  // company settings.  The value is the same canonical default exported from
  // that module; using the literal here prevents an ESM initialization cycle
  // from observing its export before initialization.
  vatPeriodType: "quarter",
};

export function normalizeFiscalYearStartMonth(value?: number | string | null) {
  const month = typeof value === "string" ? Number(value) : value;
  if (!Number.isInteger(month) || (month ?? 0) < 1 || (month ?? 0) > 12) return null;
  return month;
}

export function normalizeFiscalYearLabelStrategy(value?: string | null): FiscalYearLabelStrategy | null {
  if (value === "end-year" || value === "start-year" || value === "span") return value;
  return null;
}

export function normalizePaymentTermsDays(value?: number | string | null): number | null {
  if (value === undefined || value === null || value === "") return null;
  const days = typeof value === "string" ? Number(value) : value;
  if (!Number.isInteger(days) || (days as number) < 0 || (days as number) > 365) return null;
  return days as number;
}

export function normalizeVatPeriodType(value?: string | null): VatPeriodType | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return VAT_PERIOD_TYPES.has(trimmed as VatPeriodType) ? (trimmed as VatPeriodType) : null;
}

export function seedAccounts(db: Database) {
  // The seeded chart of accounts covers what an ordinary Danish small business
  // (incl. a one-person ApS) actually needs (#226). Numbering keeps the Danish
  // kontoplan ranges already in use:
  //   1xxx  income + debtors + salgsmoms
  //   2xxx  bank
  //   3xxx  external operating expenses (driftsomkostninger) + staff costs
  //   4xxx  VAT settlement accounts (4000 Købsmoms, 4500 Momsafregning)
  //   5xxx  equity (incl. owner's draw/contribution) + fixed assets
  //   7xxx  short-term liabilities (creditors + payroll-related gæld + tax)
  const rows = [
    // --- Income (1xxx) ---
    ["1000", "Omsætning, ydelser", "income", "credit", null],
    ["1010", "Gebyr- og kompensationsindtægter", "income", "credit", null],
    // Realiseret valutakursgevinst på debitorer/kreditorer i fremmed valuta:
    // når en fordring/gæld indfries til en anden kurs end den, den blev bogført
    // til, er forskellen en finansiel gevinst (kredit) — modposten til 3320.
    ["1020", "Valutakursgevinst (realiseret)", "income", "credit", null],
    ["1100", "Debitorer", "asset", "debit", null],
    ["1200", "Salgsmoms", "vat", "credit", null],
    // Periodeafgrænsningspost: forudbetalte omkostninger (asset). A prepaid
    // expense already paid that belongs to a later period is parked here until
    // it is recognised period by period.
    ["1300", "Forudbetalte omkostninger", "asset", "debit", null],
    // --- Bank (2xxx) ---
    ["2000", "Bank", "asset", "debit", null],
    // --- External operating expenses (3xxx, 3000-3399) ---
    ["3000", "Software og SaaS", "expense", "debit", "DK_PURCHASE_25"],
    ["3010", "AI-værktøjer", "expense", "debit", "EU_SERVICE_REVERSE_CHARGE"],
    ["3020", "Hosting og cloud", "expense", "debit", "EU_SERVICE_REVERSE_CHARGE"],
    ["3050", "Rejse og transport", "expense", "debit", "DK_PURCHASE_25"],
    ["3055", "Kørselsgodtgørelse", "expense", "debit", null],
    ["3070", "Repræsentation", "expense", "debit", "REPRESENTATION_SPECIAL"],
    ["3080", "Tab på debitorer", "expense", "debit", "DK_BAD_DEBT_25"],
    ["3100", "Husleje", "expense", "debit", "DK_PURCHASE_25"],
    ["3110", "El, vand og varme", "expense", "debit", "DK_PURCHASE_25"],
    ["3120", "Hardware og udstyr", "expense", "debit", "DK_PURCHASE_25"],
    ["3130", "Kontorartikler og småanskaffelser", "expense", "debit", "DK_PURCHASE_25"],
    ["3140", "Telefon og internet", "expense", "debit", "DK_PURCHASE_25"],
    ["3150", "Forsikringer", "expense", "debit", null],
    ["3160", "Revisor og bogføring", "expense", "debit", "DK_PURCHASE_25"],
    ["3170", "Advokat og rådgivning", "expense", "debit", "DK_PURCHASE_25"],
    ["3180", "Markedsføring og annoncering", "expense", "debit", "DK_PURCHASE_25"],
    ["3190", "Kontingenter og abonnementer", "expense", "debit", "DK_PURCHASE_25"],
    ["3200", "Porto og fragt", "expense", "debit", "DK_PURCHASE_25"],
    ["3300", "Gebyrer, bank og betalingskort", "expense", "debit", null],
    ["3310", "Renteudgifter", "expense", "debit", null],
    // Realiseret valutakurstab på debitorer/kreditorer i fremmed valuta — det
    // finansielle modstykke til 1020. Bogføres når en fordring/gæld indfries
    // til en ringere kurs end bogføringskursen.
    ["3320", "Valutakurstab (realiseret)", "expense", "debit", null],
    // --- Staff costs (3xxx, 3500-3599) ---
    ["3500", "Lønninger", "expense", "debit", null],
    ["3510", "Pension", "expense", "debit", null],
    ["3520", "ATP og lovpligtige bidrag", "expense", "debit", null],
    ["3530", "Personaleomkostninger", "expense", "debit", "DK_PURCHASE_25"],
    // --- VAT settlement accounts (4xxx) ---
    ["4000", "Købsmoms", "vat", "debit", null],
    ["4500", "Momsafregning", "liability", "credit", null],
    // --- Equity + fixed assets (5xxx) ---
    ["5000", "Egenkapital", "equity", "credit", null],
    // Owner's draw / contribution (#249): for an enkeltmandsvirksomhed money
    // moved between the owner and the business is an equity movement, not an
    // expense or income. 5010 records hævninger (debit reduces equity), 5020
    // records indskud (credit increases equity).
    ["5010", "Privat hævning", "equity", "debit", null],
    ["5020", "Privat indskud", "equity", "credit", null],
    // Fixed-asset accounts (#124, #125), 5800-5899 range. 5800 capitalises
    // driftsmidler; 5810 is the contra-asset accumulated-depreciation account
    // (credit-normal); 5820 carries the period depreciation expense.
    ["5800", "Driftsmidler og inventar", "asset", "debit", null],
    ["5810", "Akkumulerede afskrivninger", "asset", "credit", null],
    ["5820", "Afskrivninger", "expense", "debit", null],
    // --- Short-term liabilities (7xxx): trade creditors + payroll gæld ---
    ["7000", "Leverandørgæld (kreditorer)", "liability", "credit", null],
    ["7100", "Skyldig A-skat", "liability", "credit", null],
    ["7110", "Skyldigt AM-bidrag", "liability", "credit", null],
    ["7120", "Skyldig ATP", "liability", "credit", null],
    ["7130", "Skyldig løn", "liability", "credit", null],
    // Tax payable / skattekonto (#249): the everyday account for tax owed to
    // SKAT — B-skat / restskat for an enkeltmandsvirksomhed, selskabsskat for
    // an ApS. Credit-normal short-term liability, alongside the payroll gæld.
    ["7200", "Skyldig skat (skattekonto)", "liability", "credit", null],
    // Periodeafgrænsningsposter på passivsiden. 7300 holds accrued expenses
    // (skyldige omkostninger): a cost that belongs to the period but is not yet
    // paid. 7310 holds deferred revenue (forudbetalt indtægt): cash received
    // for a service not yet delivered. Both are credit-normal liabilities that
    // unwind period by period as the cost/revenue is recognised.
    ["7300", "Skyldige omkostninger", "liability", "credit", null],
    ["7310", "Forudbetalt indtægt (udskudt omsætning)", "liability", "credit", null]
  ];
  const insert = db.prepare("INSERT OR IGNORE INTO accounts (account_no,name,type,normal_balance,default_vat_code) VALUES (?,?,?,?,?)");
  db.transaction(() => rows.forEach((r) => {
    insert.run(...r);
  })).immediate();
  seedNativeAccountRoles(db);
}

export function seedNativeAccountRoles(db: Database) {
  const nativeRoles: Array<[AccountRole, string]> = [["bank", "2000"], ["debtors", "1100"], ["creditors", "7000"], ["output_vat", "1200"], ["input_vat", "4000"], ["reverse_charge_vat", "1200"], ["vat_settlement", "4500"], ["operational_default", "3000"]];
  for (const [role, accountNo] of nativeRoles) {
    const history = db.query("SELECT 1 FROM account_role_mappings WHERE role = ? LIMIT 1").get(role);
    const proposal = db.query("SELECT 1 FROM account_role_proposals WHERE role = ? LIMIT 1").get(role);
    if (!history && !proposal) confirmAccountRole(db, role, accountNo, "system", "native-account-role-seed", "native_seed");
  }
}

export function normalizeCvr(value?: string | null): string | null {
  const trimmed = value?.trim();
  if (!trimmed) return null;
  const stripped = trimmed.toUpperCase().replace(/^DK/, "");
  if (!/^\d{8}$/.test(stripped)) {
    throw new Error(`CVR must be 8 digits (optionally prefixed with DK), got: ${value}`);
  }
  return `DK${stripped}`;
}

function hasPaymentInfo(payment?: CompanyPaymentInput): payment is CompanyPaymentInput {
  if (!payment) return false;
  return Boolean(
    payment.bankName?.trim() ||
      payment.registrationNo?.trim() ||
      payment.accountNo?.trim() ||
      payment.iban?.trim(),
  );
}

function upsertPrimaryBankAccount(db: Database, currency: string, payment: CompanyPaymentInput) {
  const existing = db
    .query("SELECT id FROM bank_accounts WHERE slug = 'primaer' LIMIT 1")
    .get() as { id: number } | null;
  if (existing) return;
  db.query(
    `INSERT INTO bank_accounts (slug, name, bank_name, registration_no, account_no, iban, currency)
     VALUES ('primaer', 'Driftskonto', ?, ?, ?, ?, ?)`,
  ).run(
    payment.bankName?.trim() || null,
    payment.registrationNo?.trim() || null,
    payment.accountNo?.trim() || null,
    payment.iban?.trim() || null,
    currency,
  );
}

function buildDefaultPolicyYaml(onboardingActor?: string | null): string {
  const userLines: string[] = ["    - user:ejer"];
  const agentLines: string[] = ["    - agent:rentemester-bookkeeper"];
  const systemLines: string[] = ["    - system:rentemester"];
  const actor = onboardingActor?.trim();
  if (actor && /^(user|agent|system):\S.+$/.test(actor)) {
    const [kind] = actor.split(":", 1) as [string];
    const line = `    - ${actor}`;
    if (kind === "agent") {
      if (!agentLines.includes(line)) agentLines.push(line);
    } else if (kind === "system") {
      if (!systemLines.includes(line)) systemLines.push(line);
    } else if (!userLines.includes(line)) {
      userLines.push(line);
    }
  }
  return (
    "company_policy:\n" +
    "  country: DK\n" +
    "  currency: DKK\n" +
    "  allow_direct_sql_write: false\n" +
    "  block_if_uncertain: true\n" +
    "\n" +
    "# Aktører der må køre muterende kommandoer.\n" +
    "# Hver muterende kommando kræver en actor — enten et eksplicit --actor-flag\n" +
    "# eller en afledt actor (OS-brugernavn via USER/LOGNAME, eller en\n" +
    "# agent-miljøvariabel). Begge holdes op mod denne liste. Tilføj din egen\n" +
    "# bruger/agent under den rette sektion nedenfor (linjen '    - user:dit-navn').\n" +
    "actor_allowlist:\n" +
    "  users:\n" +
    userLines.join("\n") + "\n" +
    "  agents:\n" +
    agentLines.join("\n") + "\n" +
    "  systems:\n" +
    systemLines.join("\n") + "\n"
  );
}

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[]
): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  bindings: SQLQueryBindings[],
): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[] | [SQLQueryBindings[]]
): ReturnType<Database["run"]> {
  const normalized = bindings.length === 1 && Array.isArray(bindings[0])
    ? bindings[0]
    : bindings as SQLQueryBindings[];
  return db.run(sql, normalized);
}

export function summariseCompanyVolume(companyRoot: string): CompanyOnboardingSummary {
  const dbPath = join(companyRoot, "data", "ledger.sqlite");
  const db = openDb(dbPath);
  try {
    const settings = getCompanySettings(db);
    const row = db.query("SELECT COUNT(*) AS n FROM accounts").get() as { n: number };
    return {
      name: settings.name,
      cvr: settings.cvr,
      fiscalYearStartMonth: settings.fiscalYearStartMonth,
      fiscalYearLabelStrategy: settings.fiscalYearLabelStrategy,
      vatPeriod: settings.vatPeriodType,
      accountCount: Number(row?.n ?? 0),
      // #241: an issued invoice's PDF carries a BETALING block only when a
      // payment account is configured. Reuse the invoice-side resolver so the
      // onboarding warning matches what the invoice would actually print.
      hasPaymentDetails: resolveCompanyPaymentDetails(db, settings.currency) !== undefined,
    };
  } finally {
    db.close();
  }
}

export function getCompanySettings(db: Database): CompanySettings {
  // #289: older ledgers (and the base schema.sql) may lack `vat_period_type`.
  // Read it only when present; absent → fall back to the quarterly default so
  // a pre-#289 company is unaffected.
  const vatColumn = hasVatPeriodColumn(db) ? "vat_period_type" : "NULL AS vat_period_type";
  const row = db.query(
    `SELECT id, name, country, currency, cvr, fiscal_year_start_month, fiscal_year_label_strategy,
            address, postal_code, city, company_form, industry_code, industry_text,
            cvr_status, audit_waived, cvr_synced_at, payment_terms_days, ${vatColumn}
       FROM companies
      ORDER BY id ASC
      LIMIT 1`
  ).get() as {
    id: number;
    name: string;
    country: string;
    currency: string;
    cvr: string | null;
    fiscal_year_start_month: number;
    fiscal_year_label_strategy: FiscalYearLabelStrategy;
    address: string | null;
    postal_code: string | null;
    city: string | null;
    company_form: string | null;
    industry_code: string | null;
    industry_text: string | null;
    cvr_status: string | null;
    audit_waived: number | null;
    cvr_synced_at: string | null;
    payment_terms_days: number | null;
    vat_period_type: string | null;
  } | null;

  if (!row) return DEFAULT_COMPANY_SETTINGS;
  return {
    id: row.id,
    name: row.name,
    country: row.country,
    currency: row.currency,
    cvr: normalizeCvr(row.cvr),
    fiscalYearStartMonth: normalizeFiscalYearStartMonth(row.fiscal_year_start_month) ?? 1,
    fiscalYearLabelStrategy: normalizeFiscalYearLabelStrategy(row.fiscal_year_label_strategy) ?? "end-year",
    address: row.address,
    postalCode: row.postal_code,
    city: row.city,
    companyForm: row.company_form,
    industryCode: row.industry_code,
    industryText: row.industry_text,
    cvrStatus: row.cvr_status,
    auditWaived: row.audit_waived === null ? null : row.audit_waived === 1,
    cvrSyncedAt: row.cvr_synced_at,
    paymentTermsDays:
      normalizePaymentTermsDays(row.payment_terms_days) ?? DEFAULT_PAYMENT_TERMS_DAYS,
    // `null` in the column = "not VAT-registered" — preserved verbatim. A
    // stored value that fails normalisation (corrupt cell) falls back to the
    // historical default so legacy ledgers stay readable.
    vatPeriodType:
      row.vat_period_type === null
        ? null
        : normalizeVatPeriodType(row.vat_period_type) ?? DEFAULT_VAT_PERIOD_TYPE,
  };
}

export function resolveCompanyPaymentDetails(
  db: Database,
  currency = "DKK",
): CompanyPaymentDetails | undefined {
  let rows: Array<{
    bank_name: string | null;
    registration_no: string | null;
    account_no: string | null;
    iban: string | null;
    currency: string | null;
  }> = [];
  try {
    rows = db
      .query(
        `SELECT bank_name, registration_no, account_no, iban, currency
           FROM bank_accounts
          WHERE active = 1
          ORDER BY id ASC`,
      )
      .all() as typeof rows;
  } catch {
    // The table may not exist in very old ledgers; payment block is optional.
    return undefined;
  }
  if (rows.length === 0) return undefined;
  const wanted = currency.trim().toUpperCase();
  const match =
    rows.find((row) => (row.currency ?? "").trim().toUpperCase() === wanted) ?? rows[0];
  const details: CompanyPaymentDetails = {
    bankName: match.bank_name?.trim() || null,
    registrationNo: match.registration_no?.trim() || null,
    accountNo: match.account_no?.trim() || null,
    iban: match.iban?.trim() || null,
  };
  if (!details.bankName && !details.registrationNo && !details.accountNo && !details.iban) {
    return undefined;
  }
  return details;
}

export function registerCompanyDirIntoWorkspace(
  workspaceRoot: string,
  companyRoot: string,
  options?: { name?: string; createdAt?: string },
): WorkspaceAutoRegisterResult {
  if (!isCompanyInsideWorkspace(workspaceRoot, companyRoot)) {
    return { status: "outside-workspace" };
  }
  const resolvedCompany = resolve(companyRoot);
  const slug = resolvedCompany.slice(resolvedCompany.lastIndexOf(sep) + 1);
  if (!isValidSlug(slug)) {
    // The directory name is not a usable slug — treat it like a non-member so
    // `init` is never blocked by a path the workspace model cannot index.
    return { status: "outside-workspace" };
  }
  if (findWorkspaceCompany(workspaceRoot, slug)) {
    return { status: "already-registered", slug };
  }
  if (!workspaceExists(workspaceRoot)) initWorkspace(workspaceRoot);
  const p = companyPaths(resolvedCompany);
  const name = options?.name ?? readCompanyName(p.db) ?? slug;
  registerWorkspaceCompany(workspaceRoot, {
    slug,
    name,
    createdAt: options?.createdAt ?? new Date().toISOString(),
    archived: false,
  });
  return { status: "registered", slug };
}

export function isCompanyInsideWorkspace(
  workspaceRoot: string,
  companyRoot: string,
): boolean {
  const ws = resolve(workspaceRoot);
  const company = resolve(companyRoot);
  const parent = company.slice(0, company.lastIndexOf(sep));
  return parent === ws && company !== ws;
}

export function isValidSlug(slug: string): boolean {
  return /^[a-z0-9][a-z0-9-]*$/.test(slug);
}

export function findWorkspaceCompany(
  workspaceRoot: string,
  slug: string,
): WorkspaceCompanyEntry | null {
  return listWorkspaceCompanies(workspaceRoot).find((c) => c.slug === slug) ?? null;
}

export function workspaceExists(workspaceRoot: string): boolean {
  return existsSync(manifestPath(workspaceRoot));
}

export function initWorkspace(workspaceRoot: string): WorkspaceManifest {
  mkdirSync(workspaceRoot, { recursive: true });
  if (workspaceExists(workspaceRoot)) return loadWorkspaceManifest(workspaceRoot);
  const manifest = emptyManifest();
  saveWorkspaceManifest(workspaceRoot, manifest);
  return manifest;
}

function readCompanyName(dbPath: string): string | null {
  try {
    // Lazy import keeps the module dependency-light for callers that only
    // need the pure manifest helpers.
    const { Database } = require("bun:sqlite") as typeof import("bun:sqlite");
    const db = new Database(dbPath, { readonly: true });
    try {
      const row = db.query("SELECT name FROM companies ORDER BY id ASC LIMIT 1").get() as
        | { name: string }
        | null;
      const name = row?.name?.trim();
      return name && name.length > 0 ? name : null;
    } finally {
      db.close();
    }
  } catch {
    return null;
  }
}

export function registerWorkspaceCompany(
  workspaceRoot: string,
  entry: WorkspaceCompanyEntry,
): WorkspaceCompanyEntry {
  assertValidSlug(entry.slug);
  const manifest = loadWorkspaceManifest(workspaceRoot);
  if (manifest.companies.some((c) => c.slug === entry.slug)) {
    throw new Error(`virksomheden med slug '${entry.slug}' er allerede registreret i workspacet`);
  }
  manifest.companies.push(entry);
  saveWorkspaceManifest(workspaceRoot, manifest);
  return entry;
}

export function decapitalize(value: string): string {
  return value.length === 0 ? value : value[0]!.toLowerCase() + value.slice(1);
}

export function vatPeriodTypeLabelDa(type: VatPeriodType): string {
  switch (type) {
    case "month":
      return "måned";
    case "half-year":
      return "halvår";
    case "quarter":
    default:
      return "kvartal";
  }
}

typeDeclarations.source:
export type CompanyOnboardingSummary = {
  /** Display name stored in the ledger. */
  name: string;
  cvr: string | null;
  /** Month (1-12) the fiscal year starts in. */
  fiscalYearStartMonth: number;
  fiscalYearLabelStrategy: FiscalYearLabelStrategy;
  /**
   * #289: the company's VAT settlement cadence — the canonical period-type
   * value (`month` / `quarter` / `half-year`), or `null` when the company is
   * not VAT-registered.
   */
  vatPeriod: VatPeriodType | null;
  /** Number of accounts seeded into the chart of accounts. */
  accountCount: number;
  /**
   * #241: true when the company has bank/payment details on file (a primary
   * bank account row). Without them an issued invoice's PDF carries no BETALING
   * block, so onboarding must warn the owner.
   */
  hasPaymentDetails: boolean;
};

export type CompanyInitOptions = {
  /** Display name stored in the ledger's `companies` row (id = 1). */
  name?: string;
  cvr?: string | null;
  fiscalYearStartMonth?: number | string | null;
  fiscalYearLabelStrategy?: string | null;
  /** #221: the company's own postal address — the seller address on invoices. */
  address?: string | null;
  postalCode?: string | null;
  city?: string | null;
  /** #221: default payment terms in days (issue date -> due date). */
  paymentTermsDays?: number | string | null;
  /**
   * #289: the company's VAT settlement cadence (`month` / `quarter` /
   * `half-year`). Defaults to `quarter` when omitted.
   */
  vatPeriodType?: string | null;
  /** #221: payment details; when any field is set a bank account is created. */
  payment?: CompanyPaymentInput;
  /**
   * #248: the canonical actor id (user:.../agent:.../system:...) of whoever is
   * running onboarding — seeded into the `actor_allowlist` so the person who
   * runs `init` can immediately mutate, whether they pass `--actor` explicitly
   * or rely on the derived OS username. Keeps the allowlist consistent: the
   * derived actor and an explicit `--actor` with the same id behave the same.
   */
  onboardingActor?: string | null;
};

export type CompanyPaymentInput = {
  bankName?: string | null;
  registrationNo?: string | null;
  accountNo?: string | null;
  iban?: string | null;
};

export type CompanyInitResult = {
  companyRoot: string;
  dbPath: string;
};

export type CompanySettings = {
  id: number;
  name: string;
  country: string;
  currency: string;
  cvr: string | null;
  fiscalYearStartMonth: number;
  fiscalYearLabelStrategy: FiscalYearLabelStrategy;
  /** CVR-register stamdata, last written by `company sync-cvr`. */
  address: string | null;
  postalCode: string | null;
  city: string | null;
  companyForm: string | null;
  industryCode: string | null;
  industryText: string | null;
  cvrStatus: string | null;
  auditWaived: boolean | null;
  /** ISO timestamp the CVR stamdata above was last synced; null when never. */
  cvrSyncedAt: string | null;
  /**
   * #221: the owner's own default payment terms — days from an invoice's issue
   * date to its due date. Captured once so every issued invoice inherits it.
   */
  paymentTermsDays: number;
  /**
   * #289: the VAT settlement cadence the company is registered for with SKAT
   * (`month` / `quarter` / `half-year`). Drives VAT period windows and their
   * filing deadlines. `null` means the company is NOT VAT-registered
   * (holding ApS, frivilligt momsfritaget, mikrovirksomhed under § 48); every
   * VAT-aware surface (dashboard, obligations, momsangivelse) gates on this.
   */
  vatPeriodType: VatPeriodType | null;
};

export type CompanyPaymentDetails = {
  bankName: string | null;
  registrationNo: string | null;
  accountNo: string | null;
  iban: string | null;
};

export type WorkspaceAutoRegisterResult =
  | { status: "registered"; slug: string }
  | { status: "already-registered"; slug: string }
  | { status: "outside-workspace" };

export type WorkspaceCompanyEntry = {
  /** Filesystem-safe identifier; the subdirectory name under the workspace. */
  slug: string;
  /** Human-readable display name. */
  name: string;
  /** ISO-8601 timestamp of when the entry was first registered. */
  createdAt: string;
  /** Soft-deletion flag; archived companies stay on disk. */
  archived: boolean;
};

export type WorkspaceManifest = {
  version: typeof MANIFEST_VERSION;
  companies: WorkspaceCompanyEntry[];
};

definition.handlerSpecificParsing:
(ctx) => {
    const root = ctx.companyRoot();
    const workspaceRoot = resolveInitWorkspaceRoot(ctx);

    // #248: seed whoever runs onboarding into the actor_allowlist so the
    // derived OS actor and an explicit --actor with the same id behave
    // consistently. An explicit --actor wins; otherwise the derived actor.
    const onboardingActor =
      ctx.trimToNull(ctx.arg("--actor")) ?? inferredMutationActor();

    // --no-vat (boolean) and --vat-period none both mean "register the
    // company as NOT VAT-registered" (null cadence). Combining --no-vat with
    // an explicit cadence is a user-input error — refuse before we touch the
    // ledger so the fatal message is the only failure mode.
    const noVatFlag = ctx.hasFlag("--no-vat");
    const vatPeriodRaw = ctx.arg("--vat-period");
    const explicitCadence =
      vatPeriodRaw !== undefined && vatPeriodRaw !== "none"
        ? vatPeriodRaw
        : undefined;
    if (noVatFlag && explicitCadence !== undefined) {
      ctx.fatal(
        "--no-vat kan ikke kombineres med --vat-period <cadence>: vælg enten en momsperiode (month/quarter/half-year) eller --no-vat for en ikke-momsregistreret virksomhed",
      );
    }
    const wantsNoVat = noVatFlag || vatPeriodRaw === "none";
    const vatPeriodOption: string | null | undefined = wantsNoVat
      ? null
      : explicitCadence;

    let summary: CompanyOnboardingSummary;
    try {
      initialiseCompanyVolume(root, {
        // #221: capture the company's own identity + payment details once, so
        // every issued invoice and its PDF inherit them without re-typing.
        name: ctx.trimToNull(ctx.arg("--name")) ?? undefined,
        cvr: ctx.arg("--cvr"),
        fiscalYearStartMonth: ctx.arg("--fiscal-year-start-month"),
        fiscalYearLabelStrategy: ctx.arg("--fiscal-year-label-strategy"),
        // #289: the company's VAT settlement cadence — month/quarter/half-year,
        // or `null` for a not-VAT-registered company.
        vatPeriodType: vatPeriodOption,
        address: ctx.trimToNull(ctx.arg("--address")) ?? undefined,
        postalCode: ctx.trimToNull(ctx.arg("--postal-code")) ?? undefined,
        city: ctx.trimToNull(ctx.arg("--city")) ?? undefined,
        paymentTermsDays: ctx.arg("--payment-terms"),
        payment: {
          bankName: ctx.trimToNull(ctx.arg("--bank-name")) ?? undefined,
          registrationNo: ctx.trimToNull(ctx.arg("--bank-reg")) ?? undefined,
          accountNo: ctx.trimToNull(ctx.arg("--bank-account")) ?? undefined,
          iban: ctx.trimToNull(ctx.arg("--iban")) ?? undefined,
        },
        onboardingActor,
      });
      summary = summariseCompanyVolume(root);
    } catch (error) {
      console.error(error instanceof Error ? error.message : String(error));
      process.exit(2);
    }

    // #216: when the company directory lives inside a configured workspace,
    // also register it in the workspace manifest so the Cockpit sees it.
    // registerCompanyDirIntoWorkspace never throws, so this can never break
    // `init` for a `--company` path that is not a workspace member.
    let registration: WorkspaceAutoRegisterResult | null = null;
    if (workspaceRoot) {
      registration = registerCompanyDirIntoWorkspace(workspaceRoot, root, {
        name: summary.name,
      });
    }

    ctx.emitResult({
      ok: true,
      message: `Rentemester-virksomhed oprettet i ${root}`,
      companyRoot: root,
      ledger: companyPaths(root).db,
      accountCount: summary.accountCount,
      cvr: summary.cvr,
      fiscalYearStartMonth: summary.fiscalYearStartMonth,
      fiscalYearLabelStrategy: summary.fiscalYearLabelStrategy,
      vatPeriod: summary.vatPeriod,
      // #241: agents (and the Cockpit) can surface the same payment-details
      // warning the human onboarding block prints.
      hasPaymentDetails: summary.hasPaymentDetails,
      workspace: workspaceRoot,
      workspaceRegistered: registration?.status === "registered",
      workspaceSlug:
        registration && registration.status !== "outside-workspace"
          ? registration.slug
          : undefined,
    });

    // The structured JSON above stays machine-stable for agents; the rich
    // onboarding block (#214) is human-output only.
    if (ctx.outputFormat === "human") {
      for (const line of buildOnboardingLines(root, summary, registration)) {
        console.log(line);
      }
    }

    // #241: warn loudly on stderr (in *any* output format) when no bank/IBAN
    // is set — issued invoices will have no BETALING block and become
    // unpayable. stderr keeps stdout machine-clean and survives `init > log`
    // redirection. Init itself still succeeds (exit 0); this is advisory.
    if (!summary.hasPaymentDetails) {
      for (const line of buildPaymentDetailsWarningLines()) {
        console.error(line);
      }
    }
  }

