export type CvrLookupOptions = {
  fetchImpl?: typeof fetch;
  /** Override the CVR Elasticsearch base URL (else RENTEMESTER_CVR_ENDPOINT). */
  endpoint?: string;
  username?: string;
  password?: string;
  /** Cache freshness window in days; default 30. */
  maxAgeDays?: number;
  /** Ignore a fresh cache entry and force a network fetch. */
  forceRefresh?: boolean;
  /** ISO timestamp treated as "now" — for deterministic tests. */
  asOf?: string;
  /** SEC-5: outgoing-request timeout in ms; default `DEFAULT_CVR_TIMEOUT_MS`. */
  timeoutMs?: number;
};

export type SyncCompanyFromCvrResult = {
  ok: boolean;
  /** The CVR number that was looked up (8 digits, no DK prefix). */
  cvr?: string;
  company?: CvrCompanyInfo;
  /** True when the snapshot came from the local cache, not a fresh fetch. */
  cached?: boolean;
  /** Names of the `companies` columns whose value actually changed. */
  updatedFields?: string[];
  /**
   * The fiscal-year start month as configured vs. as registered in CVR. Sync
   * never rewrites the fiscal year — it is a locked accounting setting — it
   * only reports a mismatch so the user can correct it deliberately.
   */
  fiscalYearStartMonth?: { current: number; cvr: number | null; matches: boolean };
  errors: string[];
};

export type CvrCompanyInfo = {
  /** CVR number, 8 digits, no DK prefix. */
  cvr: string;
  name: string;
  /** Street line of the registered address (vejnavn + husnummer). */
  address: string | null;
  postalCode: string | null;
  city: string | null;
  municipalityCode: number | null;
  /** Numeric company-form code (60 = A/S, 80 = ApS, ...). */
  companyFormCode: number | null;
  /** Short company form, e.g. "ApS". */
  companyFormShort: string | null;
  /** Long company form, e.g. "Anpartsselskab". */
  companyFormLong: string | null;
  /** Company status, e.g. "NORMAL", "UNDER KONKURS". */
  status: string | null;
  industryCode: string | null;
  industryText: string | null;
  email: string | null;
  phone: string | null;
  website: string | null;
  /** Incorporation date, YYYY-MM-DD. */
  startDate: string | null;
  /** Fiscal-year start as a gMonthDay string, e.g. "--01-01". */
  fiscalYearStart: string | null;
  /** Fiscal-year end as a gMonthDay string, e.g. "--12-31". */
  fiscalYearEnd: string | null;
  /** Fiscal-year start month (1-12) derived from `fiscalYearStart`. */
  fiscalYearStartMonth: number | null;
  /** Whether statutory audit is opted out (REVISION_FRAVALGT). */
  auditWaived: boolean | null;
  /** Registered share capital, in the currency of `shareCapitalCurrency`. */
  shareCapital: number | null;
  shareCapitalCurrency: string | null;
  /** Latest reported employee headcount; CVR lags 1-2 years. */
  employees: number | null;
  /** True when the company opted out of marketing contact (reklamebeskyttet). */
  advertisingProtected: boolean;
  management: CvrManagementMember[];
};

export type CvrManagementMember = {
  /** Person or company name of the management member. */
  name: string;
  /** Danish role label, e.g. "Direktion", "Bestyrelse", "FORMAND". */
  role: string;
};

export type CompanySettings = {
  id: number;
  name: string;
  country: string;
  currency: string;
  cvr: string | null;
  fiscalYearStartMonth: number;
  fiscalYearLabelStrategy: FiscalYearLabelStrategy;
  /** CVR-register stamdata, last written by `company sync-cvr`. */
  address: string | null;
  postalCode: string | null;
  city: string | null;
  companyForm: string | null;
  industryCode: string | null;
  industryText: string | null;
  cvrStatus: string | null;
  auditWaived: boolean | null;
  /** ISO timestamp the CVR stamdata above was last synced; null when never. */
  cvrSyncedAt: string | null;
  /**
   * #221: the owner's own default payment terms — days from an invoice's issue
   * date to its due date. Captured once so every issued invoice inherits it.
   */
  paymentTermsDays: number;
  /**
   * #289: the VAT settlement cadence the company is registered for with SKAT
   * (`month` / `quarter` / `half-year`). Drives VAT period windows and their
   * filing deadlines. `null` means the company is NOT VAT-registered
   * (holding ApS, frivilligt momsfritaget, mikrovirksomhed under § 48); every
   * VAT-aware surface (dashboard, obligations, momsangivelse) gates on this.
   */
  vatPeriodType: VatPeriodType | null;
};

export type CvrLookupResult = {
  ok: boolean;
  company?: CvrCompanyInfo;
  /** True when `company` was served from the local cache, not a fresh fetch. */
  cached: boolean;
  /** ISO timestamp the returned snapshot was fetched from CVR. */
  fetchedAt?: string;
  errors: string[];
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

