import { type OutputFormat, buildHumanError, printStructuredResult } from "./common";
import { renderVatReport, renderVatFiling, renderAnnualReport, renderTaxReturn } from "./vat";
import {
  renderInvoiceStatus,
  renderInvoiceInterest,
  renderInvoiceCompensation,
  renderInvoiceValidate,
  renderInvoiceCreate,
} from "./invoice";
import {
  renderBackupStatus,
  renderExceptionsList,
  renderTrialBalance,
  renderProfitAndLoss,
  renderBalanceSheet,
  renderRetentionStatus,
} from "./dashboard";
import { renderBankReconciliation } from "./bank";

// ===========================================================================
// HUMAN-READABLE REPORT RENDERING — DISPATCH (#211)
// ---------------------------------------------------------------------------
// Read/report commands emit deterministic JSON with English field names for
// agents. When a human runs them (`--format human` / a TTY) that JSON is
// unreadable. `renderHumanReport` renders the same payloads in clear Danish
// with money in kroner-og-øre. The `--format json` path is untouched: handlers
// keep calling `ctx.emitResult` for JSON and only branch into this renderer
// for the human format.
// ===========================================================================

/** Report kinds with a dedicated Danish human renderer. */
export type HumanReportKind =
  | "vat-report"
  | "vat-filing"
  | "report-annual"
  | "report-tax"
  | "invoice-status"
  | "invoice-interest"
  | "invoice-compensation"
  | "invoice-validate"
  | "exceptions-list"
  | "report-trial-balance"
  | "report-profit-loss"
  | "report-balance"
  | "retention-status"
  | "reconcile-bank"
  | "backup-status"
  // #177: `report annual --ixbrl-taxonomy` prints the bounded iXBRL subset.
  // No dedicated renderer — it falls back to the generic structured output.
  | "report-annual-ixbrl-taxonomy";

/**
 * Render a read/report `result` payload as Danish human-readable text.
 *
 * Returns `null` when there is no dedicated renderer for `kind` or the payload
 * does not look renderable, so callers can fall back to the generic
 * `printStructuredResult` rendering.
 */
export function renderHumanReport(
  kind: HumanReportKind,
  result: Record<string, unknown>,
): string | null {
  // `backup-status` reports `ok: false` when the weekly backup duty is NOT met
  // — that is a valid compliance status to render, not a command failure. Its
  // renderer handles both states, so it must run before the generic
  // ok-false-as-error path. (#240)
  if (kind === "backup-status") {
    return renderBackupStatus(result);
  }
  // `invoice validate` reports `ok: false` when the payload is INVALID — that
  // is a valid validation verdict to render in full (the figures and every
  // rejection reason), not a command crash. Its renderer covers both the
  // valid and invalid verdict, so it must run before the generic
  // ok-false-as-error path. (#250)
  if (kind === "invoice-validate") {
    return renderInvoiceValidate(result);
  }
  if (result.ok === false) {
    return buildHumanError(humanReportTitle(kind), result).join("\n");
  }
  switch (kind) {
    case "vat-report":
      return renderVatReport(result);
    case "vat-filing":
      return renderVatFiling(result);
    case "report-annual":
      return renderAnnualReport(result);
    case "report-tax":
      return renderTaxReturn(result);
    case "invoice-status":
      return renderInvoiceStatus(result);
    case "invoice-interest":
      return renderInvoiceInterest(result);
    case "invoice-compensation":
      return renderInvoiceCompensation(result);
    case "exceptions-list":
      return renderExceptionsList(result);
    case "report-trial-balance":
      return renderTrialBalance(result);
    case "report-profit-loss":
      return renderProfitAndLoss(result);
    case "report-balance":
      return renderBalanceSheet(result);
    case "retention-status":
      return renderRetentionStatus(result);
    case "reconcile-bank":
      return renderBankReconciliation(result);
    default:
      // `backup-status` and `invoice-validate` are handled before this switch
      // (their renderers cover the ok:false state too), so they never reach
      // here.
      return null;
  }
}

/**
 * Emit a read/report `result` either as the byte-stable agent JSON or as the
 * Danish human rendering, depending on `format`. The `--format json` path is
 * exactly `JSON.stringify(result, null, 2)` — unchanged from `emitResult` —
 * so agents see no difference. Only the human rendering is new.
 *
 * Returns the process exit code to apply (1 when `result.ok === false`).
 */
export function emitHumanReport(
  kind: HumanReportKind,
  result: Record<string, unknown>,
  format: OutputFormat,
): void {
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    const human = renderHumanReport(kind, result);
    if (human !== null) {
      if (result.ok === false) console.error(human);
      else console.log(human);
    } else {
      printStructuredResult(humanReportTitle(kind), result, format);
    }
  }
  if (result.ok === false) process.exitCode = 1;
}

function humanReportTitle(kind: HumanReportKind): string {
  switch (kind) {
    case "vat-report":
      return "Momsrapport";
    case "vat-filing":
      return "Momsangivelse";
    case "report-annual":
      return "Årsrapport";
    case "report-tax":
      return "Skattemæssig indkomst";
    case "invoice-status":
      return "Fakturastatus";
    case "invoice-interest":
      return "Morarente";
    case "invoice-compensation":
      return "Kompensation for sen betaling";
    case "invoice-validate":
      return "Fakturavalidering";
    case "exceptions-list":
      return "Undtagelser";
    case "report-trial-balance":
      return "Saldobalance";
    case "report-profit-loss":
      return "Resultatopgørelse";
    case "report-balance":
      return "Balance";
    case "retention-status":
      return "Opbevaringsstatus";
    case "reconcile-bank":
      return "Bankafstemning";
    case "backup-status":
      return "Backup-status";
    case "report-annual-ixbrl-taxonomy":
      return "iXBRL-taksonomi (afgrænset udsnit)";
  }
}

/** Write-command kinds with a dedicated Danish human renderer. (#266, #268) */
export type HumanWriteKind = "invoice-create";

/**
 * Emit a write-command `result` either as the byte-stable agent JSON or as a
 * Danish human rendering, depending on `format`. The `--format json` path is
 * exactly `JSON.stringify(result, null, 2)` — unchanged from `emitResult` — so
 * agents see no difference. Sets `process.exitCode = 1` on `ok: false`. (#268)
 */
export function emitHumanWrite(
  kind: HumanWriteKind,
  result: Record<string, unknown>,
  format: OutputFormat,
): void {
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    const human = kind === "invoice-create" ? renderInvoiceCreate(result) : null;
    if (human !== null) {
      if (result.ok === false) console.error(human);
      else console.log(human);
    } else {
      printStructuredResult(kind, result, format);
    }
  }
  if (result.ok === false) process.exitCode = 1;
}

definition.handler:
(ctx) => {
    const db = openCommandDb(ctx);
    migrate(db);
    const hasFlag = (name: string) => ctx.arg(name) !== undefined;
    const payment = {
      bankName: ctx.trimToNull(ctx.arg("--bank-name")) ?? undefined,
      registrationNo: ctx.trimToNull(ctx.arg("--bank-reg")) ?? undefined,
      accountNo: ctx.trimToNull(ctx.arg("--bank-account")) ?? undefined,
      iban: ctx.trimToNull(ctx.arg("--iban")) ?? undefined,
    };

    // #300: `--vat-period` changes the company's VAT settlement cadence
    // after init. `--no-vat` (or `--vat-period none`) marks the company as
    // NOT VAT-registered (null cadence). `setCompanyProfile` does not own
    // the `vat_period_type` column, so the change is written via the
    // periods-core helper. An unknown value is refused before any profile
    // field is touched.
    const vatPeriodRaw = ctx.arg("--vat-period");
    const noVatFlag = ctx.hasFlag("--no-vat");
    const explicitCadence =
      vatPeriodRaw !== undefined && vatPeriodRaw !== "none"
        ? vatPeriodRaw
        : undefined;
    if (noVatFlag && explicitCadence !== undefined) {
      ctx.emitResult({
        ok: false,
        errors: [
          "--no-vat kan ikke kombineres med --vat-period <cadence>: vælg enten en momsperiode (month/quarter/half-year) eller --no-vat for en ikke-momsregistreret virksomhed",
        ],
      });
      db.close();
      process.exit(1);
    }
    const wantsNoVat = noVatFlag || vatPeriodRaw === "none";
    const wantsCadenceChange = hasFlag("--vat-period") || noVatFlag;
    if (wantsCadenceChange) {
      let vatPeriod: ReturnType<typeof normalizeVatPeriodType> | null = null;
      if (!wantsNoVat) {
        vatPeriod = normalizeVatPeriodType(vatPeriodRaw);
        if (vatPeriod === null) {
          ctx.emitResult({
            ok: false,
            errors: [
              "--vat-period must be one of month, quarter, half-year, or 'none' (alias for --no-vat)",
            ],
          });
          db.close();
          process.exit(1);
        }
      }
      const vatResult = setCompanyVatPeriodType(db, vatPeriod);
      if (!vatResult.ok) {
        ctx.emitResult({ ok: false, errors: vatResult.errors });
        db.close();
        process.exit(1);
      }
    }

    const result = setCompanyProfile(db, {
      name: hasFlag("--name") ? ctx.arg("--name") : undefined,
      cvr: hasFlag("--cvr") ? ctx.arg("--cvr") : undefined,
      address: hasFlag("--address") ? ctx.arg("--address") : undefined,
      postalCode: hasFlag("--postal-code") ? ctx.arg("--postal-code") : undefined,
      city: hasFlag("--city") ? ctx.arg("--city") : undefined,
      paymentTermsDays: hasFlag("--payment-terms") ? ctx.arg("--payment-terms") : undefined,
      payment,
    });
    // Reflect the cadence on the result so the JSON output and human summary
    // show the live profile after the edit. `vatRegistered` is the derived
    // boolean clients can switch UI on without reasoning about a null cadence.
    const settings = getCompanySettings(db);
    const enriched = {
      ...result,
      vatPeriodType: settings.vatPeriodType,
      vatRegistered: settings.vatPeriodType !== null,
      ...(wantsCadenceChange && result.ok
        ? { updatedFields: [...(result.updatedFields ?? []), "vatPeriodType"] }
        : {}),
    };
    ctx.emitResult(enriched as unknown as Record<string, unknown>);
    db.close();
    if (!result.ok) process.exit(1);
  }

payloadTypes.source:
export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type VatAccountSemantics = {
  /** VAT amount accounts and whether their signed movement is output or input VAT. */
  amountSideByAccountNo: ReadonlyMap<string, VatAmountSide>;
  /** Output-VAT accounts dedicated to reverse charge rather than ordinary sales. */
  reverseChargeOutputAccountNos: ReadonlySet<string>;
  /** Settlement accounts move the net balance but are not themselves VAT amounts. */
  settlementAccountNos: ReadonlySet<string>;
};

export type VatPeriodWindow = {
  /** First day of the VAT period (YYYY-MM-DD). */
  start: string;
  /** Last day of the VAT period (YYYY-MM-DD). */
  end: string;
  /** SKAT filing/payment deadline for this cadence, shifted to a banking day. */
  filingDeadline: string;
  /** The cadence this window was computed for. */
  vatPeriodType: VatPeriodType;
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

export type SetCompanyProfileOptions = {
  name?: string | null;
  cvr?: string | null;
  address?: string | null;
  postalCode?: string | null;
  city?: string | null;
  paymentTermsDays?: number | string | null;
  payment?: CompanyPaymentInput;
};

export type CompanyPaymentInput = {
  bankName?: string | null;
  registrationNo?: string | null;
  accountNo?: string | null;
  iban?: string | null;
};

export type SetCompanyProfileResult = {
  ok: boolean;
  /** The company settings after the update (unchanged on failure). */
  settings?: CompanySettings;
  /** Names of the profile fields that actually changed. */
  updatedFields?: string[];
  errors: string[];
};

export type CompanySettings = {
  id: number;
  name: string;
  country: string;
  currency: string;
  cvr: string | null;
  fiscalYearStartMonth: number;
  fiscalYearLabelStrategy: FiscalYearLabelStrategy;
  /** CVR-register stamdata, last written by `company sync-cvr`. */
  address: string | null;
  postalCode: string | null;
  city: string | null;
  companyForm: string | null;
  industryCode: string | null;
  industryText: string | null;
  cvrStatus: string | null;
  auditWaived: boolean | null;
  /** ISO timestamp the CVR stamdata above was last synced; null when never. */
  cvrSyncedAt: string | null;
  /**
   * #221: the owner's own default payment terms — days from an invoice's issue
   * date to its due date. Captured once so every issued invoice inherits it.
   */
  paymentTermsDays: number;
  /**
   * #289: the VAT settlement cadence the company is registered for with SKAT
   * (`month` / `quarter` / `half-year`). Drives VAT period windows and their
   * filing deadlines. `null` means the company is NOT VAT-registered
   * (holding ApS, frivilligt momsfritaget, mikrovirksomhed under § 48); every
   * VAT-aware surface (dashboard, obligations, momsangivelse) gates on this.
   */
  vatPeriodType: VatPeriodType | null;
};

