export function normalizeVatPeriodType(value?: string | null): VatPeriodType | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return VAT_PERIOD_TYPES.has(trimmed as VatPeriodType) ? (trimmed as VatPeriodType) : null;
}

export function setCompanyVatPeriodType(
  db: Database,
  type: VatPeriodType | null,
  actor: ResolveActorInput = {},
): { ok: boolean; changed: boolean; errors: string[] } {
  if (type !== null && !VAT_PERIOD_TYPES.has(type)) {
    return {
      ok: false,
      changed: false,
      errors: ["vatPeriodType must be one of month, quarter, half-year, or null"],
    };
  }
  ensureNullableVatPeriodColumn(db);
  const before = db
    .query("SELECT vat_period_type AS t FROM companies WHERE id = 1")
    .get() as { t: string | null } | null;
  if (!before) {
    return {
      ok: false,
      changed: false,
      errors: ["company has not been initialised — run 'rentemester init' first"],
    };
  }
  const changed = before.t !== type;
  // A cadence is currently stored as one company-wide value, not as an
  // effective-dated registration history. Once VAT periods or VAT-classified
  // postings exist, changing to another non-null cadence would reinterpret
  // old activity and can make immutable closed periods overlap the new
  // windows. Refuse until an explicit effective-dated migration exists.
  if (changed && type !== null) {
    const existingVatPeriods = db
      .query(
        `SELECT id, period_start, period_end
           FROM accounting_periods
          WHERE kind IN ('vat_period', 'vat_quarter')`,
      )
      .all() as Array<{ id: number; period_start: string; period_end: string }>;
    const vatAccounts = loadVatAccountSemantics(db).amountSideByAccountNo;
    const postedLines = db
      .query(
        `SELECT a.account_no, jl.vat_code
           FROM journal_lines jl
           JOIN accounts a ON a.id = jl.account_id
           JOIN journal_entries je ON je.id = jl.journal_entry_id
          WHERE je.status = 'posted'`,
      )
      .all() as Array<{ account_no: string; vat_code: string | null }>;
    const hasVatActivity = postedLines.some((line) => {
      const code = typeof line.vat_code === "string" ? line.vat_code.trim() : "";
      return vatAccounts.has(line.account_no) || VAT_LINE_CODES.has(code);
    });
    const incompatibleRecoveryPeriod =
      before.t === null
        ? existingVatPeriods.find((period) => {
            const window = vatPeriodWindowFor(period.period_start, type);
            return (
              window.start !== period.period_start ||
              window.end !== period.period_end
            );
          })
        : undefined;
    const cannotRecoverPreviousCadence =
      before.t === null
        ? incompatibleRecoveryPeriod !== undefined ||
          (existingVatPeriods.length === 0 && hasVatActivity)
        : existingVatPeriods.length > 0 || hasVatActivity;
    if (cannotRecoverPreviousCadence) {
      return {
        ok: false,
        changed: false,
        errors: [
          incompatibleRecoveryPeriod
            ? `momsregistreringen kan ikke genaktiveres med ${type}: eksisterende momsperiode #${incompatibleRecoveryPeriod.id} ${incompatibleRecoveryPeriod.period_start}..${incompatibleRecoveryPeriod.period_end} følger en anden kadence`
            : "momsperiodens kadence kan ikke ændres, efter der er bogført momsaktivitet eller oprettet momsperioder; ændringen kræver en effective-dated kadencemigration, så historiske angivelser ikke omfortolkes eller strandes",
        ],
      };
    }
  }
  // Going from registered → not-registered must not silently strand posted
  // VAT activity (output VAT on a sale, deductible input VAT on a bilag).
  // Refuse when the ledger carries any posted entry on a `vat`-type account
  // whose date is NOT inside an EFFECTIVELY closed/reported VAT period — i.e.
  // any open VAT obligation that would otherwise lose its filing path. The
  // owner must close + indberette before deregistering.
  //
  // Coverage is judged by `effectivePeriodState`, NOT the period row's stored
  // status: a period that was closed and then reopened (#247) keeps its row at
  // `closed` while being effectively `open` again, so a raw `ap.status` check
  // would let a reopen→deregister sequence strand posted VAT activity — the
  // exact failure this guard exists to prevent. This mirrors the lens
  // `closeAccountingPeriod` / `validateJournalTransactionDate` already use.
  if (type === null && before.t !== null) {
    const vatAccounts = loadVatAccountSemantics(db).amountSideByAccountNo;
    const vatEntryDates = (db
      .query(
        `SELECT DISTINCT je.transaction_date AS d, a.account_no AS account_no
           FROM journal_lines jl
           JOIN accounts a ON a.id = jl.account_id
           JOIN journal_entries je ON je.id = jl.journal_entry_id
          WHERE je.status = 'posted'`,
      )
      .all() as Array<{ d: string; account_no: string }>)
      .filter((row) => vatAccounts.has(row.account_no));
    if (vatEntryDates.length > 0) {
      const vatPeriods = db
        .query(
          `SELECT id, period_start, period_end, status
             FROM accounting_periods
            WHERE kind IN ('vat_period', 'vat_quarter')`,
        )
        .all() as Array<{
        id: number;
        period_start: string;
        period_end: string;
        status: AccountingPeriodStatus;
      }>;
      const settledPeriods = vatPeriods.filter((p) => {
        const state = effectivePeriodState(db, p.id, p.status);
        return state === "closed" || state === "reported";
      });
      const hasOpenVatActivity = vatEntryDates.some(
        (entry) =>
          !settledPeriods.some(
            (p) => entry.d >= p.period_start && entry.d <= p.period_end,
          ),
      );
      if (hasOpenVatActivity) {
        return {
          ok: false,
          changed: false,
          errors: [
            "selskabet har bogført momsaktivitet i en åben momsperiode — luk og indberet perioden før selskabet markeres som ikke-momsregistreret: kør 'period close' for at lukke momsperioden, derefter 'vat momsangivelse' for den indberetningsklare angivelse, og indberet via TastSelv",
          ],
        };
      }
    }
  }
  db.query("UPDATE companies SET vat_period_type = ? WHERE id = 1").run(type);
  if (changed) {
    // Itemize the registration-state transition in the append-only audit_log
    // so deregistering (registered → not-registered), re-registering, or a
    // cadence change is attributable and visible in the company history —
    // not a silent UPDATE. A deregistration in particular ends the company's
    // VAT obligation and must leave a trail.
    const label = (t: string | null) => (t === null ? "ikke momsregistreret" : t);
    const eventType =
      type === null
        ? "company_vat_deregistered"
        : before.t === null
          ? "company_vat_registered"
          : "company_vat_period_changed";
    insertAuditLog(db, {
      ...actor,
      eventType,
      entityType: "company",
      entityId: 1,
      message: `Momsregistrering ændret: ${label(before.t)} → ${label(type)}`,
    });
  }
  return { ok: true, changed, errors: [] };
}

export function ensureNullableVatPeriodColumn(db: Database) {
  const cols = db.query("PRAGMA table_info(companies)").all() as Array<{
    name: string;
    type: string;
    notnull: number;
    dflt_value: string | null;
    pk: number;
  }>;
  const existing = cols.find((c) => c.name === "vat_period_type");
  if (!existing) {
    // `DEFAULT 'quarter'` is deliberate: an EXISTING company row (a pre-#289
    // ledger that never had this column) was implicitly a quarterly VAT filer,
    // so it must come back registered — never silently flip to NULL = "not
    // VAT-registered". NULL is reserved for an EXPLICIT deregistration write
    // (`init --no-vat`, `set-profile --no-vat`, the PATCH-profile endpoint); it
    // is never the byproduct of adding the column. The CHECK still permits NULL
    // so those explicit writes succeed.
    db.exec(
      "ALTER TABLE companies ADD COLUMN vat_period_type TEXT DEFAULT 'quarter' " +
        "CHECK(vat_period_type IS NULL OR vat_period_type IN ('month', 'quarter', 'half-year'));",
    );
    return;
  }
  if (existing.notnull === 0) return;

  // Older ledger: the column carries the legacy `NOT NULL DEFAULT 'quarter'`
  // definition. Relax it to nullable. We rebuild from the table's CANONICAL
  // CREATE SQL (sqlite_master) and rewrite ONLY the vat_period_type column —
  // PRAGMA table_info does NOT expose CHECK constraints, so reconstructing the
  // column list from PRAGMA would silently DROP the CHECKs on the other columns
  // (fiscal_year_start_month, fiscal_year_label_strategy, payment_terms_days).
  // DROP TABLE also drops the table's triggers + indexes (e.g. the
  // `companies_fiscal_lock` config guard), so we capture and re-create them in
  // the same transaction rather than leaving them gone until the next migrate().
  const tableSql = (
    db
      .query("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'companies'")
      .get() as { sql: string } | null
  )?.sql;
  if (!tableSql) return;
  // Drop only `NOT NULL` from the column, keeping its DEFAULT and CHECK. The
  // CHECK already admits NULL (`NULL IN (...)` is NULL, never FALSE, so a CHECK
  // passes), so relaxing nullability needs no CHECK change.
  const relaxedSql = tableSql.replace(
    /vat_period_type\s+TEXT\s+NOT\s+NULL\s+DEFAULT\s+'quarter'/i,
    "vat_period_type TEXT DEFAULT 'quarter'",
  );
  if (relaxedSql === tableSql) {
    // The expected legacy fragment was not found (unknown column shape). Bail
    // out rather than risk a malformed rebuild — the column stays as it is.
    return;
  }
  const rebuildSql = relaxedSql.replace(
    /CREATE TABLE\s+(?:IF NOT EXISTS\s+)?"?companies"?/i,
    "CREATE TABLE companies_vat_period_rebuild",
  );
  const triggers = db
    .query("SELECT sql FROM sqlite_master WHERE type = 'trigger' AND tbl_name = 'companies' AND sql IS NOT NULL")
    .all() as Array<{ sql: string }>;
  const indexes = db
    .query("SELECT sql FROM sqlite_master WHERE type = 'index' AND tbl_name = 'companies' AND sql IS NOT NULL")
    .all() as Array<{ sql: string }>;
  const columnList = cols.map((c) => c.name).join(", ");

  db.transaction(() => {
    db.exec("DROP TABLE IF EXISTS companies_vat_period_rebuild;");
    db.exec(rebuildSql);
    db.exec(
      `INSERT INTO companies_vat_period_rebuild (${columnList}) SELECT ${columnList} FROM companies;`,
    );
    db.exec("DROP TABLE companies;");
    db.exec("ALTER TABLE companies_vat_period_rebuild RENAME TO companies;");
    for (const t of triggers) db.exec(t.sql);
    for (const i of indexes) db.exec(i.sql);
  })();
}

export function loadVatAccountSemantics(db: Database): VatAccountSemantics {
  const rows = db
    .query("SELECT account_no, type, normal_balance, active FROM accounts")
    .all() as Array<{
    account_no: string;
    type: string;
    normal_balance: "debit" | "credit";
    active: number;
  }>;

  const amountSideByAccountNo = new Map<string, VatAmountSide>();
  for (const row of rows) {
    if (row.type === "vat") {
      amountSideByAccountNo.set(
        row.account_no,
        row.normal_balance === "debit" ? "input" : "output",
      );
      continue;
    }
    // `active` gates future posting, not historical interpretation. Explicit
    // type=vat above therefore remains meaningful after an account is retired;
    // number-based legacy compatibility below stays limited to active charts.
    if (row.active !== 1) continue;
    const dinero =
      DINERO_VAT_CONTROL_ACCOUNTS[
        row.account_no as keyof typeof DINERO_VAT_CONTROL_ACCOUNTS
      ];
    if (
      dinero &&
      // A 64060 liability is too ambiguous outside a verified historical
      // Dinero voucher. `buildVatReport` admits it only after checking the
      // matching 64040/64060 control pair and provenance.
      row.account_no !== "64060" &&
      row.type === "liability" &&
      row.normal_balance === dinero.normalBalance
    ) {
      amountSideByAccountNo.set(row.account_no, dinero.side);
    }
  }

  for (const [role, side] of [
    ["output_vat", "output"],
    ["reverse_charge_vat", "output"],
    ["input_vat", "input"],
  ] as const) {
    const resolution = resolveAccountRole(db, role);
    if (resolution.ok) amountSideByAccountNo.set(resolution.accountNo, side);
  }

  const reverseChargeOutputAccountNos = new Set<string>();
  // Dinero's exact 64040 control is source-native evidence of a dedicated
  // reverse-charge output account, even before its imported role proposal is
  // confirmed.
  if (amountSideByAccountNo.get("64040") === "output") {
    reverseChargeOutputAccountNos.add("64040");
  }
  const outputVat = resolveAccountRole(db, "output_vat");
  const reverseChargeVat = resolveAccountRole(db, "reverse_charge_vat");
  // A confirmed role is dedicated only when it is distinct from ordinary
  // output VAT. Native charts deliberately use 1200 for both, so those need
  // base-derived allocation at report time.
  if (
    reverseChargeVat.ok &&
    (!outputVat.ok || reverseChargeVat.accountNo !== outputVat.accountNo)
  ) {
    reverseChargeOutputAccountNos.add(reverseChargeVat.accountNo);
  }

  const settlementAccountNos = new Set<string>();
  const settlement = resolveAccountRole(db, "vat_settlement");
  if (settlement.ok) settlementAccountNos.add(settlement.accountNo);

  return {
    amountSideByAccountNo,
    reverseChargeOutputAccountNos,
    settlementAccountNos,
  };
}

const DINERO_VAT_CONTROL_ACCOUNTS = {
  "64000": { role: "output_vat", normalBalance: "credit", side: "output" },
  // Dinero's separate output-VAT control for foreign goods acquisitions.
  // Rentemester still does not infer the corresponding goods-purchase base,
  // but the source-posted VAT amount must remain identifiable during import,
  // reporting, and year-opening VAT consolidation.
  "64020": { role: "reverse_charge_vat", normalBalance: "credit", side: "output" },
  "64040": { role: "reverse_charge_vat", normalBalance: "credit", side: "output" },
  "64060": { role: "input_vat", normalBalance: "debit", side: "input" },
} as const satisfies Record<
  string,
  { role: AccountRole; normalBalance: "debit" | "credit"; side: VatAmountSide }
>;

export function vatPeriodWindowFor(isoDate: string, type: VatPeriodType): VatPeriodWindow {
  const year = Number(isoDate.slice(0, 4));
  const month = Number(isoDate.slice(5, 7)); // 1-based
  const span = vatPeriodMonthSpan(type);
  // The 1-based index of the period within the year, then its first month.
  const periodIndex = Math.floor((month - 1) / span);
  const startMonth = periodIndex * span + 1;
  const endMonth = startMonth + span - 1;
  // Day 0 of the next month is the last day of `endMonth`.
  const lastDay = new Date(Date.UTC(year, endMonth, 0)).getUTCDate();
  const end = `${year}-${pad2(endMonth)}-${pad2(lastDay)}`;
  return {
    start: `${year}-${pad2(startMonth)}-01`,
    end,
    filingDeadline: vatFilingDeadline(end, type)!,
    vatPeriodType: type,
  };
}

export function effectivePeriodState(
  db: Database,
  periodId: number,
  rowStatus: AccountingPeriodStatus,
): EffectivePeriodState {
  const events = db
    .query(
      `SELECT event_type
         FROM audit_log
        WHERE entity_type = 'accounting_period'
          AND entity_id = ?
        ORDER BY id ASC`,
    )
    .all(String(periodId)) as Array<{ event_type: string }>;

  let state: EffectivePeriodState = rowStatus;
  for (const ev of events) {
    // `reported` is TERMINAL (KODE-9): once a period has been submitted to the
    // authority (SKAT / Erhvervsstyrelsen) it can never be reopened — undoing
    // an authority filing is not a bookkeeping operation, and reopenAccounting-
    // Period already refuses it. A `period_reopen` event appended AFTER a
    // `period_report` (e.g. a raw audit_log INSERT bypassing that guard) must
    // therefore be ignored, so a reported period cannot be effectively reopened
    // and have new postings land in it.
    if (state === "reported") continue;
    if (ev.event_type === "period_report") state = "reported";
    else if (ev.event_type === "period_close") state = "closed";
    else if (ev.event_type === PERIOD_REOPEN_EVENT) state = "open";
  }
  return state;
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

export function setCompanyProfile(
  db: Database,
  options: SetCompanyProfileOptions,
): SetCompanyProfileResult {
  const errors: string[] = [];
  let cvr: string | null | undefined;
  if (options.cvr !== undefined) {
    try {
      cvr = normalizeCvr(options.cvr);
    } catch (error) {
      errors.push(error instanceof Error ? error.message : String(error));
    }
  }
  let paymentTermsDays: number | undefined;
  if (options.paymentTermsDays !== undefined && options.paymentTermsDays !== null) {
    const normalized = normalizePaymentTermsDays(options.paymentTermsDays);
    if (normalized === null) {
      errors.push("paymentTermsDays must be an integer between 0 and 365");
    } else {
      paymentTermsDays = normalized;
    }
  }
  if (errors.length > 0) return { ok: false, errors };

  const before = getCompanySettings(db);
  // A first `setCompanyProfile` before `init` ran would have no row; guard it.
  const exists = db.query("SELECT id FROM companies WHERE id = 1").get() as
    | { id: number }
    | null;
  if (!exists) {
    return {
      ok: false,
      errors: ["company has not been initialised — run 'rentemester init' first"],
    };
  }

  const result = db.transaction(() => {
    const name = options.name !== undefined ? options.name?.trim() || before.name : before.name;
    const nextCvr = options.cvr !== undefined ? cvr ?? null : before.cvr;
    const address =
      options.address !== undefined ? options.address?.trim() || null : before.address;
    const postalCode =
      options.postalCode !== undefined ? options.postalCode?.trim() || null : before.postalCode;
    const city = options.city !== undefined ? options.city?.trim() || null : before.city;
    const terms = paymentTermsDays ?? before.paymentTermsDays;

    db.query(
      `UPDATE companies SET
         name = ?, cvr = ?, address = ?, postal_code = ?, city = ?, payment_terms_days = ?
       WHERE id = 1`,
    ).run(name, nextCvr, address, postalCode, city, terms);

    if (hasPaymentInfo(options.payment)) {
      upsertPrimaryBankAccount(db, before.currency, options.payment);
    }

    insertAuditLog(db, {
      eventType: "company_profile_update",
      entityType: "company",
      entityId: 1,
      message: "Updated company profile (identity / payment details)",
    });
    return getCompanySettings(db);
  }).immediate();

  const updatedFields: string[] = [];
  const compare: Array<[string, unknown, unknown]> = [
    ["name", before.name, result.name],
    ["cvr", before.cvr, result.cvr],
    ["address", before.address, result.address],
    ["postalCode", before.postalCode, result.postalCode],
    ["city", before.city, result.city],
    ["paymentTermsDays", before.paymentTermsDays, result.paymentTermsDays],
  ];
  for (const [field, prev, next] of compare) {
    if (prev !== next) updatedFields.push(field);
  }
  if (hasPaymentInfo(options.payment)) updatedFields.push("payment");

  return { ok: true, settings: result, updatedFields, errors: [] };
}

export function normalizeCvr(value?: string | null): string | null {
  const trimmed = value?.trim();
  if (!trimmed) return null;
  const stripped = trimmed.toUpperCase().replace(/^DK/, "");
  if (!/^\d{8}$/.test(stripped)) {
    throw new Error(`CVR must be 8 digits (optionally prefixed with DK), got: ${value}`);
  }
  return `DK${stripped}`;
}

export function normalizePaymentTermsDays(value?: number | string | null): number | null {
  if (value === undefined || value === null || value === "") return null;
  const days = typeof value === "string" ? Number(value) : value;
  if (!Number.isInteger(days) || (days as number) < 0 || (days as number) > 365) return null;
  return days as number;
}

export function getCompanySettings(db: Database): CompanySettings {
  // #289: older ledgers (and the base schema.sql) may lack `vat_period_type`.
  // Read it only when present; absent → fall back to the quarterly default so
  // a pre-#289 company is unaffected.
  const vatColumn = hasVatPeriodColumn(db) ? "vat_period_type" : "NULL AS vat_period_type";
  const row = db.query(
    `SELECT id, name, country, currency, cvr, fiscal_year_start_month, fiscal_year_label_strategy,
            address, postal_code, city, company_form, industry_code, industry_text,
            cvr_status, audit_waived, cvr_synced_at, payment_terms_days, ${vatColumn}
       FROM companies
      ORDER BY id ASC
      LIMIT 1`
  ).get() as {
    id: number;
    name: string;
    country: string;
    currency: string;
    cvr: string | null;
    fiscal_year_start_month: number;
    fiscal_year_label_strategy: FiscalYearLabelStrategy;
    address: string | null;
    postal_code: string | null;
    city: string | null;
    company_form: string | null;
    industry_code: string | null;
    industry_text: string | null;
    cvr_status: string | null;
    audit_waived: number | null;
    cvr_synced_at: string | null;
    payment_terms_days: number | null;
    vat_period_type: string | null;
  } | null;

  if (!row) return DEFAULT_COMPANY_SETTINGS;
  return {
    id: row.id,
    name: row.name,
    country: row.country,
    currency: row.currency,
    cvr: normalizeCvr(row.cvr),
    fiscalYearStartMonth: normalizeFiscalYearStartMonth(row.fiscal_year_start_month) ?? 1,
    fiscalYearLabelStrategy: normalizeFiscalYearLabelStrategy(row.fiscal_year_label_strategy) ?? "end-year",
    address: row.address,
    postalCode: row.postal_code,
    city: row.city,
    companyForm: row.company_form,
    industryCode: row.industry_code,
    industryText: row.industry_text,
    cvrStatus: row.cvr_status,
    auditWaived: row.audit_waived === null ? null : row.audit_waived === 1,
    cvrSyncedAt: row.cvr_synced_at,
    paymentTermsDays:
      normalizePaymentTermsDays(row.payment_terms_days) ?? DEFAULT_PAYMENT_TERMS_DAYS,
    // `null` in the column = "not VAT-registered" — preserved verbatim. A
    // stored value that fails normalisation (corrupt cell) falls back to the
    // historical default so legacy ledgers stay readable.
    vatPeriodType:
      row.vat_period_type === null
        ? null
        : normalizeVatPeriodType(row.vat_period_type) ?? DEFAULT_VAT_PERIOD_TYPE,
  };
}

const DEFAULT_COMPANY_SETTINGS: CompanySettings = {
  id: 1,
  name: "Rentemester company",
  country: "DK",
  currency: "DKK",
  cvr: null,
  fiscalYearStartMonth: 1,
  fiscalYearLabelStrategy: "end-year",
  address: null,
  postalCode: null,
  city: null,
  companyForm: null,
  industryCode: null,
  industryText: null,
  cvrStatus: null,
  auditWaived: null,
  cvrSyncedAt: null,
  paymentTermsDays: DEFAULT_PAYMENT_TERMS_DAYS,
  // Keep the module's eager default independent of the close/VAT graph.
  // `periods.ts` imports the close-readiness graph, which eventually reads
  // company settings.  The value is the same canonical default exported from
  // that module; using the literal here prevents an ESM initialization cycle
  // from observing its export before initialization.
  vatPeriodType: "quarter",
};

function hasPaymentInfo(payment?: CompanyPaymentInput): payment is CompanyPaymentInput {
  if (!payment) return false;
  return Boolean(
    payment.bankName?.trim() ||
      payment.registrationNo?.trim() ||
      payment.accountNo?.trim() ||
      payment.iban?.trim(),
  );
}

function upsertPrimaryBankAccount(db: Database, currency: string, payment: CompanyPaymentInput) {
  const existing = db
    .query("SELECT id FROM bank_accounts WHERE slug = 'primaer' LIMIT 1")
    .get() as { id: number } | null;
  if (existing) return;
  db.query(
    `INSERT INTO bank_accounts (slug, name, bank_name, registration_no, account_no, iban, currency)
     VALUES ('primaer', 'Driftskonto', ?, ?, ?, ?, ?)`,
  ).run(
    payment.bankName?.trim() || null,
    payment.registrationNo?.trim() || null,
    payment.accountNo?.trim() || null,
    payment.iban?.trim() || null,
    currency,
  );
}

