export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type VatAccountSemantics = {
  /** VAT amount accounts and whether their signed movement is output or input VAT. */
  amountSideByAccountNo: ReadonlyMap<string, VatAmountSide>;
  /** Output-VAT accounts dedicated to reverse charge rather than ordinary sales. */
  reverseChargeOutputAccountNos: ReadonlySet<string>;
  /** Settlement accounts move the net balance but are not themselves VAT amounts. */
  settlementAccountNos: ReadonlySet<string>;
};

export type VatPeriodWindow = {
  /** First day of the VAT period (YYYY-MM-DD). */
  start: string;
  /** Last day of the VAT period (YYYY-MM-DD). */
  end: string;
  /** SKAT filing/payment deadline for this cadence, shifted to a banking day. */
  filingDeadline: string;
  /** The cadence this window was computed for. */
  vatPeriodType: VatPeriodType;
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

export type SetCompanyProfileOptions = {
  name?: string | null;
  cvr?: string | null;
  address?: string | null;
  postalCode?: string | null;
  city?: string | null;
  paymentTermsDays?: number | string | null;
  payment?: CompanyPaymentInput;
};

export type CompanyPaymentInput = {
  bankName?: string | null;
  registrationNo?: string | null;
  accountNo?: string | null;
  iban?: string | null;
};

export type SetCompanyProfileResult = {
  ok: boolean;
  /** The company settings after the update (unchanged on failure). */
  settings?: CompanySettings;
  /** Names of the profile fields that actually changed. */
  updatedFields?: string[];
  errors: string[];
};

export type CompanySettings = {
  id: number;
  name: string;
  country: string;
  currency: string;
  cvr: string | null;
  fiscalYearStartMonth: number;
  fiscalYearLabelStrategy: FiscalYearLabelStrategy;
  /** CVR-register stamdata, last written by `company sync-cvr`. */
  address: string | null;
  postalCode: string | null;
  city: string | null;
  companyForm: string | null;
  industryCode: string | null;
  industryText: string | null;
  cvrStatus: string | null;
  auditWaived: boolean | null;
  /** ISO timestamp the CVR stamdata above was last synced; null when never. */
  cvrSyncedAt: string | null;
  /**
   * #221: the owner's own default payment terms — days from an invoice's issue
   * date to its due date. Captured once so every issued invoice inherits it.
   */
  paymentTermsDays: number;
  /**
   * #289: the VAT settlement cadence the company is registered for with SKAT
   * (`month` / `quarter` / `half-year`). Drives VAT period windows and their
   * filing deadlines. `null` means the company is NOT VAT-registered
   * (holding ApS, frivilligt momsfritaget, mikrovirksomhed under § 48); every
   * VAT-aware surface (dashboard, obligations, momsangivelse) gates on this.
   */
  vatPeriodType: VatPeriodType | null;
};

