  }

async function command(text: string): Promise<{ lines: string[]; literals: string[] }> {
    tagCounter += 1;
    const tag = `A${String(tagCounter).padStart(4, "0")}`;
    socket!.write(`${tag} ${text}\r\n`, "binary");
