    }
    return { lines, literals };
  }

function quote(value: string): string {
  return `"${value.replace(/([\\"])/g, "\\$1")}"`;
}

export async function pollImapMailbox(
  db: Database,
  companyRoot: string,
  client: ImapClient,
  options: PollImapOptions = {},
): Promise<PollImapResult> {
  const empty: PollImapResult = {
    ok: true,
    messagesFetched: 0,
    messagesProcessed: 0,
    attachmentsIngested: 0,
    attachmentsSkipped: 0,
    exceptionsCreated: 0,
    documents: [],
    errors: [],
  };

  let messages: ImapMessage[];
  try {
    await client.connect();
    messages = await client.fetchSince(options.sinceUid);
  } catch (error) {
    try {
      await client.close();
    } catch {
      // close() failure after a fetch failure must not mask the root cause.
    }
    return {
      ...empty,
      ok: false,
      errors: [`IMAP poll failed: ${error instanceof Error ? error.message : String(error)}`],
    };
  }

  let dropDir: string | null = null;
  try {
    if (messages.length === 0) {
      return empty;
    }

    // Materialise fetched messages into a deterministic scratch maildrop:
    // filenames are zero-padded by UID so `ingestMailDrop`'s sorted-order
    // processing is stable, and the directory is removed in `finally`.
    dropDir = mkdtempSync(join(tmpdir(), "rentemester-imap-maildrop-"));
    const sorted = [...messages].sort((a, b) => a.uid - b.uid);
    for (const message of sorted) {
      const name = `imap-${String(message.uid).padStart(12, "0")}.eml`;
      const raw = typeof message.raw === "string" ? Buffer.from(message.raw, "utf8") : message.raw;
      writeFileSync(join(dropDir, name), raw);
    }

    const ingestOptions: IngestMailDropOptions = {
      metadata: options.metadata,
      metadataPerMessage: options.metadataPerMessage,
      ingestOptions: options.ingestOptions,
    };
    const result = ingestMailDrop(db, companyRoot, dropDir, ingestOptions);
    return { ...result, messagesFetched: messages.length };
  } finally {
    if (dropDir) removePathWithRetry(dropDir);
    try {
      await client.close();
    } catch {
      // A close() failure does not invalidate an otherwise-successful poll.
    }
  }
}

export function ingestMailDrop(
  db: Database,
  companyRoot: string,
  inputPath: string,
  options: IngestMailDropOptions = {},
): IngestMailDropResult {
  const result: IngestMailDropResult = {
    ok: true,
    messagesProcessed: 0,
    attachmentsIngested: 0,
    attachmentsSkipped: 0,
    exceptionsCreated: 0,
    documents: [],
    errors: [],
  };

  if (!existsSync(inputPath)) {
    return { ...result, ok: false, errors: [`mail intake source does not exist: ${inputPath}`] };
  }

  let emlFiles: string[];
  try {
    emlFiles = resolveEmlFiles(inputPath);
  } catch (error) {
    return { ...result, ok: false, errors: [error instanceof Error ? error.message : String(error)] };
  }

  const maxSize = options.maxEmlSizeBytes ?? DEFAULT_MAX_EML_SIZE_BYTES;
  // SEC-9: normalise the optional sender allowlist once (case-insensitive bare
  // addresses). An empty/undefined list disables the check entirely.
  const senderAllowlist = new Set(
    (options.senderAllowlist ?? [])
      .map((entry) => extractSenderAddress(entry) ?? entry.trim().toLowerCase())
      .filter((entry) => entry.length > 0),
  );
  const maxMessages =
    typeof options.maxMessagesPerRun === "number" && options.maxMessagesPerRun > 0
      ? options.maxMessagesPerRun
      : null;

  for (const emlFile of emlFiles) {
    // SEC-9: stop before processing more than the per-run quota; the remaining
    // files stay in the maildrop and are picked up on the next run.
    if (maxMessages !== null && result.messagesProcessed >= maxMessages) {
      result.quotaReached = true;
      break;
    }
    result.messagesProcessed += 1;
    const raw = readFileSync(emlFile);
    // #352 — refuse over-large mails BEFORE we parse them. A 200 MB
    // ".eml" is almost always a bug (giant signed-image attachment, or a
    // dump-of-everything) and parsing it can OOM the daemon.
    if (raw.length > maxSize) {
      const ex = recordException(db, {
        type: "MAIL_INTAKE_TOO_LARGE",
        severity: "medium",
        message: `Mail message in ${emlFile} is ${raw.length} bytes (> ${maxSize}); refused to parse`,
        requiredAction:
          "Forward only the receipt itself or raise the maxEmlSizeBytes limit.",
        sourceEvidence: {
          rule: MAIL_INTAKE_RULES.EXCEPTION,
          file: emlFile,
          rawByteSize: raw.length,
          maxEmlSizeBytes: maxSize,
        },
        postingPreview: { nextStep: "documents ingest" },
      });
      if (ex.ok && !ex.duplicate) result.exceptionsCreated += 1;
      continue;
    }
    const parsed = parseEml(raw);

    // SEC-9: when a sender allowlist is configured, refuse any message whose
    // From address is not on it BEFORE touching the attachment pipeline. The
    // raw sender is echoed back through `markUntrusted` (SEC-8) since it is
    // attacker-controlled.
    if (senderAllowlist.size > 0) {
      const senderAddress = extractSenderAddress(parsed.from);
      if (!senderAddress || !senderAllowlist.has(senderAddress)) {
        const ex = recordException(db, {
          type: "MAIL_INTAKE_SENDER_NOT_ALLOWED",
          severity: "medium",
          message: `Mail message in ${markUntrusted(emlFile)} is from a sender not on the intake allowlist (from: ${markUntrusted(parsed.from)})`,
          requiredAction:
            "Add the sender to the mail-intake allowlist, or ingest the attachment manually via 'documents ingest' after verifying it.",
          sourceEvidence: {
            rule: MAIL_INTAKE_RULES.EXCEPTION,
            file: emlFile,
            from: markUntrusted(parsed.from),
            subject: markUntrusted(parsed.subject),
          },
          postingPreview: { nextStep: "documents ingest" },
        });
        if (ex.ok && !ex.duplicate) result.exceptionsCreated += 1;
        continue;
      }
    }

    // Ambiguous metadata: without a stable message-id we cannot dedup.
    if (!parsed.messageId || parsed.messageId.trim().length === 0) {
      const ex = recordException(db, {
        type: "MAIL_INTAKE_AMBIGUOUS_METADATA",
        severity: "medium",
        message: `Mail message in ${markUntrusted(emlFile)} has no Message-ID and cannot be ingested deterministically`,
        requiredAction: "Add a Message-ID header to the .eml or ingest the attachment manually via 'documents ingest'.",
        sourceEvidence: {
          rule: MAIL_INTAKE_RULES.EXCEPTION,
          file: emlFile,
          // SEC-8: sender/subject are attacker-controlled — flag as untrusted.
          from: markUntrusted(parsed.from),
          subject: markUntrusted(parsed.subject),
          date: parsed.date,
          attachmentCount: parsed.attachments.length,
        },
        postingPreview: { nextStep: "documents ingest" },
      });
      if (ex.ok && !ex.duplicate) result.exceptionsCreated += 1;
      continue;
    }

    const messageId = parsed.messageId.trim();
    const usable = parsed.attachments.filter((att) =>
      SUPPORTED_ATTACHMENT_EXTENSIONS.has(extname(att.filename).toLowerCase()),
    );

    if (usable.length === 0) {
      const ex = recordException(db, {
        type: "MAIL_INTAKE_NO_ATTACHMENT",
        severity: "medium",
        message: `Mail message ${markUntrusted(messageId)} has no usable PDF/JPG/PNG attachment`,
        requiredAction: "Forward the message with the receipt attached, or ingest the document manually.",
        sourceEvidence: {
          rule: MAIL_INTAKE_RULES.EXCEPTION,
          file: emlFile,
          messageId,
          // SEC-8: sender/subject are attacker-controlled — flag as untrusted.
          from: markUntrusted(parsed.from),
          subject: markUntrusted(parsed.subject),
          date: parsed.date,
        },
        postingPreview: { nextStep: "documents ingest" },
      });
      if (ex.ok && !ex.duplicate) result.exceptionsCreated += 1;
      continue;
    }

    const metadata = options.metadataPerMessage?.[messageId] ?? options.metadata;

    for (const attachment of usable) {
      const alreadySeen = db
        .query("SELECT id FROM mail_intake_messages WHERE message_id = ? AND attachment_sha256 = ? LIMIT 1")
        .get(messageId, attachment.sha256) as { id: number } | null;
      if (alreadySeen) {
        result.attachmentsSkipped += 1;
        continue;
      }

      if (!metadata) {
        const ex = recordException(db, {
          type: "MAIL_INTAKE_AMBIGUOUS_METADATA",
          severity: "medium",
          message: `Mail message ${markUntrusted(messageId)} attachment ${markUntrusted(attachment.filename)} has no metadata for ingest`,
          requiredAction: "Provide --metadata (or per-message metadata) so the attachment can be booked.",
          sourceEvidence: {
            rule: MAIL_INTAKE_RULES.EXCEPTION,
            file: emlFile,
            messageId,
            // SEC-8: the attachment filename comes from the sender — untrusted.
            attachmentFilename: markUntrusted(attachment.filename),
            attachmentSha256: attachment.sha256,
          },
          postingPreview: { nextStep: "documents ingest" },
        });
        if (ex.ok && !ex.duplicate) result.exceptionsCreated += 1;
        continue;
      }

      const ingestResult = ingestAttachment(db, companyRoot, messageId, parsed, attachment, metadata, options.ingestOptions);
      if (ingestResult.ingested) {
        result.attachmentsIngested += 1;
        result.documents.push({
          messageId,
          documentNo: ingestResult.documentNo!,
          sha256: ingestResult.sha256!,
        });
      } else if (ingestResult.exceptionCreated) {
        result.exceptionsCreated += 1;
      }
    }
  }

  return result;
}

const MAIL_INTAKE_RULES = {
  TRANSPORT: "DK-MAIL-INTAKE-TRANSPORT-001",
  DEDUP: "DK-MAIL-INTAKE-DEDUP-001",
  EXCEPTION: "DK-MAIL-INTAKE-EXCEPTION-001",
} as const;

export function removePathWithRetry(path: string, options: RmOptions = { recursive: true, force: true }): void {
  retryTransientCleanup(() => rmSync(path, options));
}

export function describeStaticUiBuild(staticRoot: string | undefined): StaticUiBuildInfo {
  const indexPath = staticRoot ? join(staticRoot, "index.html") : null;
  if (!staticRoot || !indexPath || !existsSync(indexPath)) {
    return {
      present: false,
      staticRoot: staticRoot ?? null,
      hint: `Ingen bygget cockpit-UI fundet — kun JSON-API'et serveres. Byg UI'et med: ${REBUILD_COMMAND}`,
    };
  }
  return {
    present: true,
    staticRoot,
    builtAt: statSync(indexPath).mtime.toISOString(),
    rebuildHint: `Er UI-buildet ældre end seneste frontend-ændringer (app/src), så genbyg med: ${REBUILD_COMMAND}`,
  };
}

typeDeclarations.source:
export type ResolveServerConfigOptions = {
  /** Explicit overrides (e.g. from CLI flags) take precedence over env. */
  host?: string;
  port?: number;
  workspaceRoot?: string;
  /** Read environment from here instead of `process.env` (testability). */
  env?: Record<string, string | undefined>;
};

export type ServerConfig = {
  /** Explicit deployment boundary. `local` may never expose Better Auth. */
  deploymentProfile?: DeploymentProfile;
  /** Interface to bind. Defaults to 127.0.0.1 (localhost-only). */
  host: string;
  /** TCP port to listen on. */
  port: number;
  /** Workspace root the API serves. */
  workspaceRoot: string;
  /**
   * When true, the auth middleware enforces a shared-secret check via the
   * `RENTEMESTER_APP_TOKEN` env var. Phase 1 leaves this off (localhost-trusted)
   * — it exists so the seam can be exercised by tests and flipped on later.
   */
  authRequired: boolean;
  /** Optional shared secret consulted only when `authRequired` is true. */
  authToken: string | null;
  /** Present only for a validated hosted deployment; never serialised. */
  hostedBetterAuth?: HostedBetterAuthConfig;
  /** Hosted ingress policy and, when required, a validated provider config. */
  hostedDocumentScanning?: HostedDocumentScanningConfig;
  /** Runtime scanner seam. Local deployments intentionally leave this absent. */
  documentScanner?: DocumentScanner;
  documentScannerPolicy?: "off" | "required";
  /** Optional explicit extraction provider; absence means extraction is unavailable. */
  invoiceExtractor?: InvoiceExtractor;
  /**
   * Hosted identity provider. Its presence selects Better Auth sessions for
   * protected API routes; public routes remain anonymous. This is injected by
   * the serving composition root, never constructed from a fallback secret.
   */
  betterAuthProvider?: BetterAuthRequestProvider;
  /** Test/composition seam; production derives it from the validated hosted mail configuration. */
  authEmailSender?: AuthEmailSender;
  /** Test/composition seam for private invitation identity creation. */
  invitationIdentityService?: PrivateInvitationIdentityService;
  /**
   * Per-request authentication result. `handleRequest` creates an immutable
   * config copy carrying this value after its one auth evaluation; it is never
   * populated by environment/config resolution.
   */
  requestPrincipal?: Principal;
  /** Validated request correlation ID, attached only by the server edge. */
  requestId?: string;
  /** Test/provider seam; never resolved from environment and invoked only by the router. */
  authenticateRequest?: (request: Request, config: ServerConfig) => Principal | Promise<Principal>;
  /** Test/composition seam for allowlisted request-completion records. Never env-derived. */
  requestLogSink?: RequestLogSink;
  /** Test seam for deterministic, validated response correlation IDs. */
  requestIdFactory?: () => string;
  /** Test seam for deterministic request timestamps and durations. */
  requestLogClock?: () => number;
  /**
   * Absolute path to the built cockpit SPA (`app/dist`). When the directory
   * exists, the server serves it for every non-`/api` route. Resolved here so
   * the rest of the server stays pure. Optional: when absent the server is a
   * pure JSON API (the shape used by API-only tests).
   */
  staticRoot?: string;
};

export type HostedBetterAuthConfig = {
  /** Active key; never emit it in health, CLI, logs, or error responses. */
  secret: string;
  /** First entry is active, following entries are Better Auth decryption-only. */
  secrets: readonly BetterAuthVersionedSecret[];
  /** Only for Better Auth's pre-versioned payloads during a rotation window. */
  legacySecret?: string;
  baseURL: string;
  trustedOrigins: readonly string[];
  authEmail: HostedAuthEmailConfig;
  /** Single edge-owned header Better Auth may use for rate-limit IP keys. */
  rateLimitIpHeader: HostedRateLimitIpHeader;
};

export type BetterAuthVersionedSecret = {
  version: number;
  value: string;
};

export type HostedAuthEmailConfig = {
  provider: "http-json-v1";
  url: string;
  bearerToken: string;
  from: string;
};

export type HostedDocumentScanningConfig = {
  policy: "off" | "required";
  provider?: HttpJsonV1DocumentScannerConfig;
};

export type HttpJsonV1DocumentScannerConfig = {
  provider: "http-json-v1";
  url: string;
  bearerToken: string;
  timeoutMs: number;
};

export type DocumentScanner = {
  scan(input: { bytes: Buffer; sha256: string; mimeType: string; filename: string; signal: AbortSignal }): Promise<
    | { ok: true; scannerId: string; scannerVersion?: string; evidenceRef?: string }
    | { ok: false; error?: string }
  >;
};

export type BetterAuthRequestProvider = {
  getSession(request: Request): Promise<BetterAuthSession | null>;
  /**
   * Verifies the dedicated service-principal credential header.  This never
   * manufactures a browser session: callers receive an identity only after
   * the API-key plugin has checked hash, expiry and enabled state.
   */
  verifyServicePrincipal?(request: Request): Promise<BetterAuthServicePrincipalVerification>;
  handle(request: Request): Promise<Response>;
};

export type BetterAuthSession = {
  user: { id: string };
  session: { id: string; createdAt: Date | string };
};

export type BetterAuthServicePrincipalVerification =
  | { state: "absent" }
  | { state: "invalid" }
  | ({ state: "valid" } & BetterAuthServicePrincipal);

export type BetterAuthServicePrincipal = {
  userId: string;
  credentialId: string;
};

export interface AuthEmailSender {
  send(message: AuthEmailMessage): Promise<void>;
}

export type AuthEmailMessage = {
  kind: AuthEmailKind;
  recipient: string;
  url: string;
  token: string;
};

export type PrivateInvitationIdentityService = {
  createIdentity(input: {
    name: string;
    email: string;
    password: string;
  }): Promise<{ userId: string; created: boolean }>;
  resendVerification(email: string): Promise<void>;
};

export type Principal = {
  /** Canonical actor id, e.g. `system:localhost` or `user:<id>`. */
  id: string;
  /** How the principal was established — useful for audit + diagnostics. */
  via: "localhost-trusted" | "shared-secret" | "better-auth" | "service-principal";
  /** Trusted provider identity; never inferred from actor metadata. */
  userId?: string;
  /** Present only for a verified, live service principal. */
  serviceAccountId?: string;
  /** Better Auth API-key id, safe for security scope/audit but not a secret. */
  credentialId?: string;
  /** Present only for a Better Auth principal and safe to include in audit. */
  sessionId?: string;
  /** Session creation time is retained for append-only invalidation checks. */
  sessionCreatedAt?: Date;
};

export type RequestLogSink = {
  emit(event: RequestLogEvent): void;
};

export type RequestLogEvent = {
  timestamp: string;
  level: "info" | "warn" | "error";
  event: "http_request_complete";
  requestId: string;
  method: string;
  /** A fixed catalog template or fixed anonymous bucket, never raw URL/path. */
  pathTemplate: string;
  status: number;
  durationMs: number;
  deploymentProfile: DeploymentProfile;
};

export type WorkspaceManifest = {
  version: typeof MANIFEST_VERSION;
  companies: WorkspaceCompanyEntry[];
};

export type WorkspaceCompanyEntry = {
  /** Filesystem-safe identifier; the subdirectory name under the workspace. */
  slug: string;
  /** Human-readable display name. */
  name: string;
  /** ISO-8601 timestamp of when the entry was first registered. */
  createdAt: string;
  /** Soft-deletion flag; archived companies stay on disk. */
  archived: boolean;
};

export type CockpitServer = {
  server: BunServer;
  config: ServerConfig;
  /** Resolved `http://host:port` base URL. */
  url: string;
  stop: () => void;
};

export type WorkspaceBetterAuthRuntime = {
  auth: Auth<any>;
  /** Closes the workspace-control Bun SQLite connection exactly once. */
  close(): void;
};

export type BetterAuthRuntimeOptions = {
  /** Active signing/HMAC key. This module never reads an environment fallback. */
  secret: string;
  /** First key is active; following keys are Better Auth decryption-only keys. */
  secrets?: readonly BetterAuthVersionedSecret[];
  /** Optional old single key for Better Auth's pre-versioned legacy payloads. */
  legacySecret?: string;
  /** Explicit origin allow-list. Wildcards and implicit request origins are not used. */
  trustedOrigins: readonly string[];
  /** Absolute Better Auth base URL for links and callbacks. */
  baseURL: string;
  /** Hosted deployments must opt into Secure cookies explicitly. */
  deploymentMode?: BetterAuthDeploymentMode;
  useSecureCookies?: boolean;
  /** Disabled by default and only replaceable by a workspace-level provider. */
  emailSender?: AuthEmailSender;
  /**
   * Receives only fixed Better Auth diagnostic event names. Raw Better Auth
   * messages, arguments, errors and stacks are never forwarded.
   */
  operationalLogger?: BetterAuthOperationalLogger;
  /** Required for hosted rate limiting; proxy reachability remains a deployment gate. */
  rateLimitIpHeader?: HostedRateLimitIpHeader;
};

export type BetterAuthOperationalLogger = {
  emit(event: BetterAuthOperationalLogEvent): void;
};

export type BetterAuthOperationalLogEvent = {
  component: "better-auth";
  event: "better_auth_warning" | "better_auth_error";
  level: "warn" | "error";
};

export type AuthEmailHttpJsonV1Config = {
  url: string;
  bearerToken: string;
  from: string;
  /** Domain-separated HMAC key. The hosted Better Auth secret is injected here. */
  idempotencySecret: string;
};

export type AuthEmailHttpJsonV1Dependencies = {
  fetch?: (request: Request) => Promise<Response>;
  sleep?: (milliseconds: number, signal?: AbortSignal) => Promise<void>;
  clock?: () => number;
};

type ScannerResponse = {
  ok?: unknown;
  scannerId?: unknown;
  scannerVersion?: unknown;
  evidenceRef?: unknown;
};

export type BilagsmailImapConfig = {
  host: string;
  port: number;
  /** TLS on connect (IMAPS). Defaults to true. */
  secure?: boolean;
  username: string;
  /** Password is stored in plain text in the config file (0600). */
  password: string;
  mailbox?: string;
};

export type ImapConfig = {
  host: string;
  port: number;
  username: string;
  password: string;
  /** TLS on connect (IMAPS). Defaults to true. */
  tls?: boolean;
  /** Mailbox to select. Defaults to "INBOX". */
  mailbox?: string;
};

export type ImapClient = {
  /** Opens the connection, authenticates, and selects the target mailbox. */
  connect(): Promise<void>;
  /**
   * Returns the messages to consider for intake. `sinceUid` is an optional
   * lower bound a client MAY use to fetch only newer UIDs; correctness never
   * depends on it because dedup is content-keyed downstream — re-fetching an
   * already-ingested message is always safe.
   */
  fetchSince(sinceUid?: number): Promise<ImapMessage[]>;
  /** Closes the connection and releases the socket. */
  close(): Promise<void>;
};

export type ImapMessage = {
  /** Server-assigned UID — stable within a mailbox/uidvalidity window. */
  uid: number;
  /** Raw RFC-822 bytes of the message (headers + body). */
  raw: string | Buffer;
};

export type PollImapOptions = IngestMailDropOptions & {
  /** Optional UID lower bound forwarded to `ImapClient.fetchSince`. */
  sinceUid?: number;
};

export type IngestMailDropOptions = {
  /** Metadata applied to every ingested attachment. */
  metadata?: MailIntakeMetadataInput;
  /** Per-message metadata keyed on message-id; overrides `metadata`. */
  metadataPerMessage?: Record<string, MailIntakeMetadataInput>;
  /** Forwarded to ingestDocument for forced logical-duplicate scans. */
  ingestOptions?: IngestDocumentOptions;
  /**
   * #352 — Maks-størrelse pr. eml-fil i bytes. Default
   * `DEFAULT_MAX_EML_SIZE_BYTES`. Mails over grænsen får en
   * MAIL_INTAKE_TOO_LARGE-eksception i stedet for at blive parset.
   */
  maxEmlSizeBytes?: number;
  /**
   * SEC-9 (Audit 2026-06-11): OPTIONAL per-company sender allowlist. When
   * provided (and non-empty), a message whose `From:` address is not in the
   * list is refused with a `MAIL_INTAKE_SENDER_NOT_ALLOWED` exception instead of
   * being ingested — anyone who learns the company's intake address can no
   * longer drop arbitrary attachments into the ledger pipeline. Comparison is
   * case-insensitive on the bare `local@domain`. Default (undefined/empty) keeps
   * today's behaviour: every sender is accepted.
   */
  senderAllowlist?: string[];
  /**
   * SEC-9 (Audit 2026-06-11): OPTIONAL ceiling on how many messages a single
   * run will process. A flood of mail to the intake address cannot exhaust the
   * exception queue / disk in one pass; the remainder simply stay in the
   * maildrop for the next run. Default (undefined) keeps today's behaviour: the
   * whole maildrop is processed.
   */
  maxMessagesPerRun?: number;
};

export type DocumentMetadata = {
  source: string;
  documentType?: DocumentType;
  issueDate?: string;
  invoiceNo?: string;
  deliveryDescription?: string;
  amountIncVat?: number;
  currency?: string;
  sender?: { name?: string; address?: string; vatOrCvr?: string; countryCode?: string; identifierKind?: SupplierIdentifierKind };
  recipient?: { name?: string; address?: string; vatOrCvr?: string };
  vatAmount?: number;
  /** Purchase tax bases, retained verbatim with the voucher.  Omit for legacy uniform VAT documents. */
  purchaseVatLines?: PurchaseVatLine[];
  /** Human-confirmed invoice evidence required before a non-EU service can be
   * posted with automatic reverse-charge input-VAT deduction. */
  reverseChargeWordingConfirmed?: boolean;
  /** Explicit source fact: the issuer supplied a Danish simplified purchase invoice. */
  danishSimplifiedPurchaseInvoice?: boolean;
  paymentDetails?: string;
  exemptionCode?: DocumentExemptionCode;
  /** Imported bank row that is the immutable primary evidence for an internal voucher. */
  sourceBankTransactionId?: number;
  /** Human accounting explanation for why the internal voucher is booked. */
  accountingRationale?: string;
};

export type DocumentType =
  | "purchase_sale"
  | "cash_register_receipt"
  | "issued_invoice_pdf"
  | "internal_voucher";

export type IngestDocumentOptions = {
  forceDuplicateLogicalIdentity?: boolean;
  createdBy?: string;
  createdByProgram?: string;
  /** Internal bulk-import use only: the enclosing import writes one audit event. */
  suppressAudit?: boolean;
  /** Scanner policy is off unless a caller explicitly requires it. */
  scannerPolicy?: "off" | "required";
  /** Upper bound for a single scanner decision. Required scanners fail closed on expiry. */
  scannerTimeoutMs?: number;
  /** A vendor-neutral async seam. It receives immutable snapshot bytes only. */
  scanner?: DocumentScanner;
};

export type PollImapResult = IngestMailDropResult & {
  /** Number of raw messages fetched from the mailbox this poll. */
  messagesFetched: number;
};

export type IngestMailDropResult = {
  ok: boolean;
  messagesProcessed: number;
  attachmentsIngested: number;
  attachmentsSkipped: number;
  exceptionsCreated: number;
  documents: Array<{ messageId: string; documentNo: string; sha256: string }>;
  errors: string[];
  /**
   * SEC-9: true when processing stopped because `maxMessagesPerRun` was reached
   * before the maildrop was exhausted. Unprocessed messages remain for the next
   * run. Absent/false when no quota was configured or the whole drop fit.
   */
  quotaReached?: boolean;
};

export type StaticUiBuildInfo =
  | { present: true; staticRoot: string; builtAt: string; rebuildHint: string }
  | { present: false; staticRoot: string | null; hint: string };

definition.handlerSpecificParsing:
(ctx: CommandContext) => {
    const workspaceFlag = ctx.trimToNull(ctx.arg("--workspace"));
    const hostFlag = ctx.trimToNull(ctx.arg("--host")) ?? undefined;
    const portRaw = ctx.parseOptionalNumber("--port");
    if (!portRaw.ok) return ctx.fatal(portRaw.error);

    let workspaceRoot: string | undefined;
    if (workspaceFlag) {
      try {
        workspaceRoot = resolveWorkspaceRoot(workspaceFlag);
      } catch (error) {
        return ctx.fatal(error instanceof Error ? error.message : String(error));
      }
    }

    let config: ReturnType<typeof resolveServerConfig>;
    try {
      config = resolveServerConfig({
        host: hostFlag,
        port: portRaw.value,
        workspaceRoot,
      });
    } catch (error) {
      return ctx.fatal(error instanceof Error ? error.message : String(error));
    }

    try {
      prepareWorkspaceForServe(config.workspaceRoot, config.deploymentProfile);
    } catch (error) {
      return ctx.fatal(error instanceof Error ? error.message : String(error));
    }

    const cockpit = startCockpitServer(config);

    // #349 — periodisk IMAP-polling pr. virksomhed med en gemt config.
    // Intervallet styres af --imap-poll-interval-sec (eller miljø-variablen
    // RENTEMESTER_IMAP_POLL_INTERVAL_SEC); default er 0 = slået fra. En værdi
    // > 0 starter en setInterval der pr. tick løber alle virksomheders mail-
    // bokse i workspacet. Fejl pr. virksomhed lækker IKKE op — vi logger og
    // går videre, så et nedlukket IMAP ikke vælter serven.
    const pollIntervalArg = ctx.parseOptionalNumber("--imap-poll-interval-sec");
    if (!pollIntervalArg.ok) return ctx.fatal(pollIntervalArg.error);
    const envInterval = process.env.RENTEMESTER_IMAP_POLL_INTERVAL_SEC;
    const intervalSec =
      pollIntervalArg.value ??
      (envInterval ? Number(envInterval) : 0);
    let imapTimer: NodeJS.Timeout | undefined;
    if (Number.isFinite(intervalSec) && intervalSec > 0) {
      imapTimer = setInterval(
        async () => {
          for (const c of listWorkspaceCompanies(config.workspaceRoot)) {
            const companyRoot = companyRootForSlug(
              config.workspaceRoot,
              c.slug,
            );
            const imap = loadBilagsmailImapConfig(companyRoot);
            if (!imap) continue;
            const resolved = resolveImapConfig({
              host: imap.host,
              port: imap.port,
              username: imap.username,
              password: imap.password,
              tls: imap.secure ?? true,
              mailbox: imap.mailbox ?? "INBOX",
            });
            if (!resolved.ok) continue;
            try {
              const dbPath = companyPaths(companyRoot).db;
              const db = openDb(dbPath);
              try {
                migrate(db);
                const client = createImapClient(resolved.config);
                await pollImapMailbox(db, companyRoot, client, {});
              } finally {
                db.close();
              }
            } catch (err) {
              // Best-effort — log to stderr og gå videre. En død IMAP-mail-
              // server eller en sløv virksomhedsmappe må aldrig vælte serven.
              const message = err instanceof Error ? err.message : String(err);
              process.stderr.write(
                `[imap-poll] ${c.slug}: ${message}\n`,
              );
            }
          }
        },
        intervalSec * 1000,
      );
    }

    // A clean shutdown on Ctrl-C / SIGTERM so the socket is released.
    const shutdown = () => {
      if (imapTimer) clearInterval(imapTimer);
      cockpit.stop();
      process.exit(0);
    };
    process.on("SIGINT", shutdown);
    process.on("SIGTERM", shutdown);

    // EJER-5: say WHICH cockpit-UI build is served. `app/dist` is gitignored
    // and `serve` never rebuilds it, so without this the operator has no way
    // to see that the served UI is weeks older than `app/src`.
    const uiBuild = describeStaticUiBuild(config.staticRoot);
    if (uiBuild.present) {
      process.stderr.write(
        `[serve] Cockpit-UI: ${uiBuild.staticRoot} (bygget ${uiBuild.builtAt}). ${uiBuild.rebuildHint}\n`,
      );
    } else {
      process.stderr.write(`[serve] ${uiBuild.hint}\n`);
    }

    ctx.emitResult({
      ok: true,
      message: `Cockpit backend listening on ${cockpit.url}`,
      url: cockpit.url,
      host: config.host,
      port: cockpit.server.port,
      workspace: config.workspaceRoot,
      authRequired: config.authRequired,
      deploymentProfile: config.deploymentProfile,
      ui: uiBuild,
    });
    // `Bun.serve` keeps the process alive; the command intentionally does not
    // return until the process is signalled.
  }

definition.exactParser:
const BOOLEAN_FLAGS = new Set([
  "--force",
  "--help",
  "--example",
  "--json",
  "--sign-with-ed25519",
  "--archive",
  "--enrich-cvr",
  "--include-archived",
  "--ixbrl-taxonomy",
  "--after-retention-expiry",
  "--no-vat",
  "--no-open",
]);

export type ParsedCliArgs = {
  positionals: string[];
  flags: Map<string, string | true>;
  errors: string[];
};

export function parseCliArgs(argv: string[]): ParsedCliArgs {
  const tokens = argv.slice(2);
  const positionals: string[] = [];
  const flags = new Map<string, string | true>();
  const errors: string[] = [];

  let optionsTerminated = false;

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i]!;

    if (!optionsTerminated && token === "--") {
      optionsTerminated = true;
      continue;
    }

    if (optionsTerminated || !token.startsWith("--")) {
      positionals.push(token);
      continue;
    }

    // `--flag=value` form: value is attached, so it may begin with dashes
    // or be empty without being confused for a missing-value error.
    const eq = token.indexOf("=");
    if (eq !== -1) {
      const name = token.slice(0, eq);
      const value = token.slice(eq + 1);
      if (BOOLEAN_FLAGS.has(name)) {
        errors.push(`Flag ${name} does not take a value`);
        continue;
      }
      flags.set(name, value);
      continue;
    }

    if (BOOLEAN_FLAGS.has(token)) {
      const next = tokens[i + 1];
      if (next && next !== "--" && !next.startsWith("--")) {
        errors.push(`Flag ${token} does not take a value`);
        i += 1;
        continue;
      }
      flags.set(token, true);
      continue;
    }

    const value = tokens[i + 1];
    if (value === undefined || value === "--" || value.startsWith("--")) {
      errors.push(`Flag ${token} requires a value`);
      continue;
    }
    flags.set(token, value);
    i += 1;
  }

  return { positionals, flags, errors };
}

stdout.genericRenderer:
import { formatKronerDa } from "../core/money";

export type OutputFormat = "json" | "human";

export function resolveOutputFormat(flags: Map<string, string | true>): OutputFormat | null {
  if (flags.has("--json")) return "json";
  const format = flags.get("--format");
  if (format === undefined) return process.stdout.isTTY ? "human" : "json";
  if (format === "json" || format === "human") return format;
  return null;
}

export function printStructuredResult(commandLabel: string, result: Record<string, unknown>, format: OutputFormat) {
  const ok = result.ok !== false;
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  const lines = ok ? buildHumanSuccess(commandLabel, result) : buildHumanError(commandLabel, result);
  const text = lines.join("\n");
  if (ok) console.log(text);
  else console.error(text);
}

/**
 * A command's `description` in `cli-meta.ts` is a full sentence (often two)
 * meant for help text — never a heading. #268: a write command that falls
 * through to the generic human renderer used to print that whole description
 * as the `✔` heading. `headingFromLabel` collapses such a label to a short
 * heading: the first clause before an em dash / period, capped in length.
 */
function headingFromLabel(commandLabel: string): string {
  const firstClause = commandLabel.split(/\s+[—–-]\s+|\.\s/)[0]?.trim() ?? commandLabel;
  const short = firstClause.length > 0 ? firstClause : commandLabel;
  return short.length > 60 ? `${short.slice(0, 57).trimEnd()}…` : short;
}

function buildHumanSuccess(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✔ ${headingFromLabel(commandLabel)}`];
  for (const line of collectSummaryLines(result)) lines.push(`  ${line}`);
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  return lines;
}

export function buildHumanError(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✘ ${commandLabel} failed`];
  const errors = asStringArray(result.errors);
  if (errors.length > 0) {
    for (const error of errors) lines.push(`  → ${error}`);
  } else {
    lines.push("  → Kommandoen fejlede uden en specifik fejlbesked.");
  }
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  appendPeriodCloseGuidance(lines, errors);
  return lines;
}

/**
 * `vat momsangivelse` and `report annual` reject an unfinalised period with a
 * terse "... is not closed ... run 'period close' first". For an owner near a
 * deadline that is cryptic, so when we recognise that failure we append a
 * plain-Danish explanation of what closing a period means and the exact
 * command to run. (#227)
 */
function appendPeriodCloseGuidance(lines: string[], errors: string[]): void {
  const closeError = errors.find(
    (e) => /is not closed/i.test(e) && /period close/i.test(e),
  );
  if (!closeError) return;
  const range = closeError.match(/(\d{4}-\d{2}-\d{2})\.\.(\d{4}-\d{2}-\d{2})/);
  const isFiscalYear = /fiscal|regnskabsår|annual/i.test(closeError);
  const kind = isFiscalYear ? "fiscal_year" : "vat_period";
  const fromTo = range ? `--from ${range[1]} --to ${range[2]}` : "--from <YYYY-MM-DD> --to <YYYY-MM-DD>";
  lines.push("");
  lines.push("  Sådan kommer du videre:");
  lines.push(
    "    En momsangivelse/årsrapport kan kun bygges på en LUKKET periode — det sikrer,",
  );
  lines.push(
    "    at tallene ikke ændrer sig efter indberetning. Du lukker perioden med:",
  );
  lines.push(`      rentemester period close --company <path> ${fromTo} --kind ${kind}`);
  lines.push(
    "    Luk først perioden når alle bilag for perioden er bogført — en lukket periode",
  );
  lines.push(
    "    blokerer ny bogføring med dato i perioden. Brug --status reported i stedet for",
  );
  lines.push(
    "    standard 'closed', hvis du allerede har indberettet til SKAT/Erhvervsstyrelsen.",
  );
}

/**
 * Danish labels for the result keys a write command commonly returns. The
 * generic human fallback (`collectSummaryLines`) used to English-ify keys via
 * `humanizeKey` ("Invoice Number", "Document Id"); for a Danish-facing tool
 * that is wrong. Any key without an entry here keeps the humanized form, but
 * the common write-result fields are now translated. (#268)
 *
 * Round-2 review (Batch E-1) expanded the set so read commands that return
 * single objects (audit verify, company profile, gdpr export/forget,
 * customer create, invoice post) actually render meaningful content under
 * `--format human` instead of just echoing the command description.
 */
const WRITE_RESULT_LABEL_DA: Record<string, string> = {
  message: "Besked",
  invoiceNumber: "Fakturanummer",
  invoiceNo: "Fakturanummer",
  entryNo: "Posteringsnummer",
  entryNumber: "Posteringsnummer",
  documentId: "Bilags-id",
  journalEntryId: "Finanspostering-id",
  importBatchId: "Import-batch-id",
  imported: "Importeret",
  skippedDuplicates: "Sprunget over (dubletter)",
  backupId: "Backup-id",
  exportDir: "Eksportmappe",
  latestBackupId: "Seneste backup-id",
  expiredCount: "Udløbne",
  totalCount: "I alt",
  storedPath: "Gemt fil",
  pdfStoredPath: "PDF-fil",
  // Batch E-1: read-command friendly labels.
  entries: "Posteringer kontrolleret",
  chainOk: "Kæden er hel",
  erasedCount: "Anonymiseret",
  skippedCount: "Sprunget over",
  alreadyErasedCount: "Allerede anonymiseret",
  recordCount: "Rækker fundet",
  count: "Antal",
  total: "I alt",
  // Profile / contact fields (company profile, customer/vendor create).
  name: "Navn",
  cvr: "CVR",
  email: "E-mail",
  address: "Adresse",
  postalCode: "Postnummer",
  city: "By",
  country: "Land",
  currency: "Valuta",
  paymentTermsDays: "Betalingsfrist (dage)",
  vatPeriodType: "Momsperiode",
  vatPeriodLabel: "Momsstatus",
  vatRegistered: "Momsregistreret",
  companyForm: "Selskabsform",
  industryText: "Branche",
  cvrStatus: "CVR-status",
  auditWaived: "Revision fravalgt",
  fiscalYearStartMonth: "Regnskabsår starter (måned)",
  customerId: "Kunde-id",
  vendorId: "Leverandør-id",
  slug: "Slug",
};

/**
 * Top-level keys whose VALUE is a nested object that should be drilled into
 * — every scalar field inside becomes its own labelled line. Lets commands
 * like `company profile` (returns `{ ok, profile: {...} }`) emit each profile
 * field without per-command renderers. Batch E-1.
 */
const NESTED_DRILL_KEYS = new Set<string>([
  "profile",
  "customer",
  "vendor",
  "company",
  "settings",
  "depreciation",
  "writeOff",
  "reminder",
  "credit",
  "suggestion",
  "summary",
]);

function collectSummaryLines(result: Record<string, unknown>) {
  const preferredKeys = [
    "message",
    "invoiceNumber",
    "invoiceNo",
    "entryNo",
    "entryNumber",
    "documentId",
    "journalEntryId",
    "importBatchId",
    "imported",
    "skippedDuplicates",
    "backupId",
    "exportDir",
    "latestBackupId",
    "expiredCount",
    "totalCount",
    "entries",
    "chainOk",
    "erasedCount",
    "skippedCount",
    "alreadyErasedCount",
    "recordCount",
    "count",
    "total",
    "name",
    "cvr",
    "email",
    "address",
    "postalCode",
    "city",
    "country",
    "currency",
    "paymentTermsDays",
    "vatPeriodType",
    "vatPeriodLabel",
    "vatRegistered",
    "companyForm",
    "industryText",
    "cvrStatus",
    "auditWaived",
    "fiscalYearStartMonth",
    "customerId",
    "vendorId",
    "slug",
  ];
  const lines: string[] = [];
  const seen = new Set<string>();
  for (const key of preferredKeys) {
    if (seen.has(key)) continue;
    const value = result[key];
    const rendered = renderScalar(value);
    if (rendered === null) continue;
    // #268: never emit an English key on a Danish-facing tool — use the Danish
    // label when one exists, falling back to the humanized form otherwise.
    lines.push(
      `${WRITE_RESULT_LABEL_DA[key] ?? humanizeKey(key)}: ${translateValueForKey(key, rendered)}`,
    );
    seen.add(key);
  }
  // Batch E-1: drill one level into well-known nested-object keys. Lets
  // `company profile` (returns `{ ok, profile: {...} }`) actually render
  // each profile field instead of showing only "✔ <command description>".
  for (const [key, value] of Object.entries(result)) {
    if (!NESTED_DRILL_KEYS.has(key)) continue;
    if (value == null || typeof value !== "object" || Array.isArray(value)) continue;
    const inner = value as Record<string, unknown>;
    for (const [innerKey, innerValue] of Object.entries(inner)) {
      if (seen.has(innerKey)) continue;
      const rendered = renderScalar(innerValue);
      if (rendered === null) continue;
      lines.push(
        `${WRITE_RESULT_LABEL_DA[innerKey] ?? humanizeKey(innerKey)}: ${translateValueForKey(innerKey, rendered)}`,
      );
      seen.add(innerKey);
    }
  }
  return lines;
}

function renderScalar(value: unknown): string | null {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return null;
}

/**
 * Danish display values for the handful of enum-valued profile fields whose raw
 * stored form is an English token (e.g. `quarter`, `end-year`). #268 already
 * translates the key (label) into Danish; this translates the VALUE so an owner
 * never sees "Momsperiode: quarter". Keyed by field, then by raw value; unknown
 * fields/values pass through unchanged.
 */
const VALUE_LABEL_DA: Record<string, Record<string, string>> = {
  vatPeriodType: {
    month: "måned",
    quarter: "kvartal",
    "half-year": "halvår",
  },
  vatRegistered: {
    true: "Ja",
    false: "Nej",
  },
  fiscalYearLabelStrategy: {
    "end-year": "slutår",
    "start-year": "startår",
  },
};

function translateValueForKey(key: string, rendered: string): string {
  return VALUE_LABEL_DA[key]?.[rendered] ?? rendered;
}

function humanizeKey(key: string) {
  return key
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/_/g, " ")
    .replace(/^./, (c) => c.toUpperCase());
}

export function asStringArray(value: unknown) {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

/**
 * Format a DKK amount as Danish kroner-og-øre, e.g. 38.3 -> "38,30 kr.",
 * -1234.5 -> "-1.234,50 kr.". Non-finite/missing input yields "—".
 *
 * Thin re-export of the single canonical formatter `formatKronerDa` in
 * `core/money.ts` — kept under the historical name so the many call sites in
 * this file stay unchanged. (#314)
 */
export function formatKroner(value: unknown): string {
  return formatKronerDa(value);
}

/** Render an integer count, falling back to 0 for missing values. */
export function asCount(value: unknown): number {
  const num = typeof value === "number" ? value : Number(value);
  return Number.isFinite(num) ? num : 0;
}

export function asText(value: unknown, fallback = "—"): string {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  return fallback;
}

export function asArray(value: unknown): Array<Record<string, unknown>> {
  return Array.isArray(value)
    ? value.filter((item): item is Record<string, unknown> => typeof item === "object" && item !== null)
    : [];
}

/**
 * Format a percentage with Danish decimal comma, e.g. 8.05 -> "8,05 %".
 * Non-finite/missing input yields "—".
 */
export function formatPercent(value: unknown): string {
  const num = typeof value === "number" ? value : Number(value);
  if (value == null || value === "" || !Number.isFinite(num)) return "—";
  const text = (Math.round(num * 100) / 100)
    .toString()
    .replace(".", ",");
  return `${text} %`;
}

export function appendWarnings(lines: string[], result: Record<string, unknown>): void {
  const warnings = asStringArray(result.warnings);
  if (warnings.length === 0) return;
  lines.push("");
  lines.push("Advarsler:");
  for (const warning of warnings) lines.push(`  - ${warning}`);
}

