export function resolveWorkspaceRoot(raw: string): string {
  if (raw.split(/[\\/]+/).includes("..")) {
    throw new Error("workspace root must not contain parent-directory ('..') segments");
  }
  const resolved = resolve(raw);
  if (!isAbsolute(resolved) || resolved.split(sep).includes("..")) {
    throw new Error("workspace root resolved to an unsafe path");
  }
  return resolved;
}

export function workspaceExists(workspaceRoot: string): boolean {
  return existsSync(manifestPath(workspaceRoot));
}

export function loadWorkspaceManifest(workspaceRoot: string): WorkspaceManifest {
  const path = manifestPath(workspaceRoot);
  if (!existsSync(path)) return emptyManifest();
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(path, "utf8"));
  } catch {
    throw new Error(`workspace manifest at ${path} is not valid JSON`);
  }
  if (!parsed || typeof parsed !== "object" || !Array.isArray((parsed as any).companies)) {
    throw new Error(`workspace manifest at ${path} is malformed`);
  }
  if ((parsed as any).version !== MANIFEST_VERSION) {
    throw new Error(
      `workspace manifest at ${path} has unsupported version ${(parsed as any).version}; expected ${MANIFEST_VERSION}`,
    );
  }
  const companies: WorkspaceCompanyEntry[] = (parsed as any).companies.map((raw: any) => ({
    slug: String(raw.slug),
    name: String(raw.name),
    createdAt: String(raw.createdAt),
    archived: Boolean(raw.archived),
  }));
  return { version: MANIFEST_VERSION, companies };
}

export function initWorkspace(workspaceRoot: string): WorkspaceManifest {
  mkdirSync(workspaceRoot, { recursive: true });
  if (workspaceExists(workspaceRoot)) return loadWorkspaceManifest(workspaceRoot);
  const manifest = emptyManifest();
  saveWorkspaceManifest(workspaceRoot, manifest);
  return manifest;
}

function emptyManifest(): WorkspaceManifest {
  return { version: MANIFEST_VERSION, companies: [] };
}

export function saveWorkspaceManifest(
  workspaceRoot: string,
  manifest: WorkspaceManifest,
): void {
  mkdirSync(workspaceRoot, { recursive: true });
  const ordered = sortedManifest(manifest);
  assertLegacyWorkspaceActive(workspaceRoot);
  writeFileAtomic(manifestPath(workspaceRoot), `${JSON.stringify(ordered, null, 2)}\n`);
}

export function createCompany(
  workspaceRoot: string,
  options: CreateCompanyOptions,
): CreateCompanyResult {
  const name = options.name?.trim();
  if (!name) throw new Error("createCompany requires a non-empty name");
  const slug = options.slug?.trim() || slugifyCompanyName(name);
  if (!slug || !isValidSlug(slug)) {
    throw new Error(
      `cannot derive a valid slug from '${name}' — pass an explicit slug (lowercase letters, digits, dashes)`,
    );
  }
  const companyRoot = join(workspaceRoot, slug);
  if (existsSync(join(companyRoot, "data", "ledger.sqlite"))) {
    throw new Error(`a company already exists at ${companyRoot}`);
  }
  const init = initialiseCompanyVolume(companyRoot, {
    name,
    cvr: options.cvr,
    fiscalYearStartMonth: options.fiscalYearStartMonth,
    fiscalYearLabelStrategy: options.fiscalYearLabelStrategy,
    address: options.address,
    postalCode: options.postalCode,
    city: options.city,
    paymentTermsDays: options.paymentTermsDays,
    vatPeriodType: options.vatPeriodType,
    payment: options.payment,
    onboardingActor: options.onboardingActor,
  });
  // registerWorkspaceCompany throws on a duplicate slug, so the manifest and
  // the on-disk directory cannot drift apart silently.
  registerWorkspaceCompany(workspaceRoot, {
    slug,
    name,
    createdAt: new Date().toISOString(),
    archived: false,
  });
  return { ...init, slug, name };
}

export function isValidSlug(slug: string): boolean {
  return /^[a-z0-9][a-z0-9-]*$/.test(slug);
}

export function initialiseCompanyVolume(
  companyRoot: string,
  options: CompanyInitOptions = {},
): CompanyInitResult {
  if (options.fiscalYearStartMonth !== undefined && options.fiscalYearStartMonth !== null) {
    if (normalizeFiscalYearStartMonth(options.fiscalYearStartMonth) === null) {
      throw new Error("fiscalYearStartMonth must be an integer between 1 and 12");
    }
  }
  if (options.fiscalYearLabelStrategy !== undefined && options.fiscalYearLabelStrategy !== null) {
    if (normalizeFiscalYearLabelStrategy(options.fiscalYearLabelStrategy) === null) {
      throw new Error(
        "fiscalYearLabelStrategy must be one of end-year, start-year, span",
      );
    }
  }
  if (options.paymentTermsDays !== undefined && options.paymentTermsDays !== null) {
    if (normalizePaymentTermsDays(options.paymentTermsDays) === null) {
      throw new Error("paymentTermsDays must be an integer between 0 and 365");
    }
  }
  if (options.vatPeriodType !== undefined && options.vatPeriodType !== null) {
    if (normalizeVatPeriodType(options.vatPeriodType) === null) {
      throw new Error("vatPeriodType must be one of month, quarter, half-year, or null");
    }
  }

  const p = ensureCompanyDirs(companyRoot);
  const db = openDb(p.db);
  try {
    migrate(db);
    seedAccounts(db);
    // `migrate` runs before the chart exists in a freshly-created company, so
    // seed confirmed native control roles only after the chart is present.
    seedNativeAccountRoles(db);
    const cvr = normalizeCvr(options.cvr);
    const fiscalYearStartMonth =
      normalizeFiscalYearStartMonth(options.fiscalYearStartMonth) ?? 1;
    const fiscalYearLabelStrategy =
      normalizeFiscalYearLabelStrategy(options.fiscalYearLabelStrategy) ?? "end-year";
    const name = options.name?.trim() || DEFAULT_COMPANY_SETTINGS.name;
    const address = options.address?.trim() || null;
    const postalCode = options.postalCode?.trim() || null;
    const city = options.city?.trim() || null;
    const paymentTermsDays =
      normalizePaymentTermsDays(options.paymentTermsDays) ?? DEFAULT_PAYMENT_TERMS_DAYS;
    // `null` means "not VAT-registered" and is written through verbatim;
    // undefined (caller didn't pass anything) keeps the historical default
    // cadence so back-compat for callers who never specified vatPeriodType
    // is byte-identical to before.
    const vatPeriodType: VatPeriodType | null =
      options.vatPeriodType === null
        ? null
        : normalizeVatPeriodType(options.vatPeriodType) ?? DEFAULT_VAT_PERIOD_TYPE;
    db.query(
      `INSERT INTO companies (id, name, cvr, fiscal_year_start_month, fiscal_year_label_strategy,
                              address, postal_code, city, payment_terms_days, vat_period_type)
       VALUES (1, ?, ?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(id) DO UPDATE SET
         name = excluded.name,
         cvr = excluded.cvr,
         fiscal_year_start_month = excluded.fiscal_year_start_month,
         fiscal_year_label_strategy = excluded.fiscal_year_label_strategy,
         address = excluded.address,
         postal_code = excluded.postal_code,
         city = excluded.city,
         payment_terms_days = excluded.payment_terms_days,
         vat_period_type = excluded.vat_period_type`,
    ).run(
      name,
      cvr,
      fiscalYearStartMonth,
      fiscalYearLabelStrategy,
      address,
      postalCode,
      city,
      paymentTermsDays,
      vatPeriodType,
    );
    // #221: capture payment details once — create the primary bank account so
    // every customer-facing invoice PDF shows where to pay.
    if (hasPaymentInfo(options.payment)) {
      upsertPrimaryBankAccount(db, DEFAULT_COMPANY_SETTINGS.currency, options.payment);
    }
    const policy = join(p.config, "policy.yaml");
    if (!existsSync(policy)) {
      writeFileSync(policy, buildDefaultPolicyYaml(options.onboardingActor));
    }
    runSql(db,
      "INSERT INTO audit_log (event_type, entity_type, message) VALUES ('init','company','Company volume initialized')",
    );
  } finally {
    db.close();
  }
  return { companyRoot, dbPath: p.db };
}

const DEFAULT_COMPANY_SETTINGS: CompanySettings = {
  id: 1,
  name: "Rentemester company",
  country: "DK",
  currency: "DKK",
  cvr: null,
  fiscalYearStartMonth: 1,
  fiscalYearLabelStrategy: "end-year",
  address: null,
  postalCode: null,
  city: null,
  companyForm: null,
  industryCode: null,
  industryText: null,
  cvrStatus: null,
  auditWaived: null,
  cvrSyncedAt: null,
  paymentTermsDays: DEFAULT_PAYMENT_TERMS_DAYS,
  // Keep the module's eager default independent of the close/VAT graph.
  // `periods.ts` imports the close-readiness graph, which eventually reads
  // company settings.  The value is the same canonical default exported from
  // that module; using the literal here prevents an ESM initialization cycle
  // from observing its export before initialization.
  vatPeriodType: "quarter",
};

export function registerWorkspaceCompany(
  workspaceRoot: string,
  entry: WorkspaceCompanyEntry,
): WorkspaceCompanyEntry {
  assertValidSlug(entry.slug);
  const manifest = loadWorkspaceManifest(workspaceRoot);
  if (manifest.companies.some((c) => c.slug === entry.slug)) {
    throw new Error(`virksomheden med slug '${entry.slug}' er allerede registreret i workspacet`);
  }
  manifest.companies.push(entry);
  saveWorkspaceManifest(workspaceRoot, manifest);
  return entry;
}

export function companyRootForSlug(workspaceRoot: string, slug: string): string {
  assertValidSlug(slug);
  return join(workspaceRoot, slug);
}

function assertValidSlug(slug: string): void {
  if (!isValidSlug(slug)) {
    throw new Error(
      `invalid company slug '${slug}': use lowercase letters, digits and dashes`,
    );
  }
}

export function resolveServerConfig(
  options: ResolveServerConfigOptions = {},
): ServerConfig {
  const env = options.env ?? process.env;

  const host =
    options.host?.trim() ||
    (env.RENTEMESTER_APP_HOST?.trim() ?? "") ||
    DEFAULT_APP_HOST;

  const port =
    options.port ?? parsePort(env.RENTEMESTER_APP_PORT, DEFAULT_APP_PORT);
  const deploymentProfile = readDeploymentProfile(env);

  let workspaceRoot = options.workspaceRoot?.trim() || null;
  if (!workspaceRoot) {
    // resolveConfiguredWorkspaceRoot reads RENTEMESTER_WORKSPACE from
    // process.env; honour an injected env map for testability.
    const fromEnv = env.RENTEMESTER_WORKSPACE;
    if (typeof fromEnv === "string" && fromEnv.trim().length > 0) {
      const prev = process.env.RENTEMESTER_WORKSPACE;
      process.env.RENTEMESTER_WORKSPACE = fromEnv;
      try {
        workspaceRoot = resolveConfiguredWorkspaceRoot();
      } finally {
        if (prev === undefined) delete process.env.RENTEMESTER_WORKSPACE;
        else process.env.RENTEMESTER_WORKSPACE = prev;
      }
    } else {
      workspaceRoot = resolveConfiguredWorkspaceRoot();
    }
  }
  if (!workspaceRoot) {
    throw new Error(
      "no workspace configured: set RENTEMESTER_WORKSPACE or pass --workspace <dir>",
    );
  }

  const authToken = env.RENTEMESTER_APP_TOKEN?.trim() || null;
  const authRequired =
    (env.RENTEMESTER_APP_AUTH?.trim().toLowerCase() ?? "") === "required";

  if (deploymentProfile === "local" && !isLoopbackBindAddress(host)) {
    throw new Error(
      "local deployment profile may only bind a loopback address; use RENTEMESTER_DEPLOYMENT_PROFILE=hosted",
    );
  }
  if (deploymentProfile === "local-container" && host.trim() !== "0.0.0.0") {
    throw new Error(
      "local-container deployment profile must bind 0.0.0.0 inside the container and be published on host loopback only",
    );
  }
  const hostedBetterAuth = deploymentProfile === "hosted" ? resolveHostedBetterAuth(env) : undefined;
  const hostedDocumentScanning = deploymentProfile === "hosted" ? resolveHostedDocumentScanning(env) : undefined;
  if (deploymentProfile !== "hosted" && [
    HOSTED_AUTH_ENV.secret, HOSTED_AUTH_ENV.secrets, HOSTED_AUTH_ENV.baseURL, HOSTED_AUTH_ENV.trustedOrigins,
    HOSTED_AUTH_ENV.emailProvider, HOSTED_AUTH_ENV.emailUrl,
    HOSTED_AUTH_ENV.emailBearerToken, HOSTED_AUTH_ENV.emailFrom,
    HOSTED_AUTH_ENV.rateLimitIpHeader, HOSTED_AUTH_ENV.rateLimitProxyContract,
    DOCUMENT_SCANNER_ENV.policy, DOCUMENT_SCANNER_ENV.provider, DOCUMENT_SCANNER_ENV.url,
    DOCUMENT_SCANNER_ENV.bearerToken, DOCUMENT_SCANNER_ENV.timeoutMs,
  ].some((name) => Boolean(env[name]?.trim()))) {
    throw new Error("local deployment profiles must not configure Better Auth; use RENTEMESTER_DEPLOYMENT_PROFILE=hosted");
  }

  return {
    deploymentProfile,
    host,
    port,
    workspaceRoot,
    // Hosted access is Better Auth-only regardless of the legacy bearer flag.
    authRequired: deploymentProfile === "hosted" ? true : authRequired,
    authToken,
    hostedBetterAuth,
    hostedDocumentScanning,
    documentScannerPolicy: hostedDocumentScanning?.policy ?? "off",
    staticRoot: resolveStaticRoot(env),
  };
}

const DOCUMENT_SCANNER_ENV = {
  policy: "RENTEMESTER_DOCUMENT_SCANNER_POLICY",
  provider: "RENTEMESTER_DOCUMENT_SCANNER_PROVIDER",
  url: "RENTEMESTER_DOCUMENT_SCANNER_URL",
  bearerToken: "RENTEMESTER_DOCUMENT_SCANNER_BEARER_TOKEN",
  timeoutMs: "RENTEMESTER_DOCUMENT_SCANNER_TIMEOUT_MS",
} as const;

function parsePort(raw: string | undefined, fallback: number): number {
  if (raw === undefined || raw.trim().length === 0) return fallback;
  const port = Number(raw);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error(
      `RENTEMESTER_APP_PORT must be an integer between 1 and 65535, got: ${raw}`,
    );
  }
  return port;
}

function readDeploymentProfile(env: Record<string, string | undefined>): DeploymentProfile {
  const raw = (env[HOSTED_AUTH_ENV.profile] ?? "local").trim().toLowerCase();
  if ((DEPLOYMENT_PROFILES as readonly string[]).includes(raw)) return raw as DeploymentProfile;
  throw new Error(`${HOSTED_AUTH_ENV.profile} must be 'local', 'local-container', or 'hosted'`);
}

export function resolveConfiguredWorkspaceRoot(): string | null {
  const raw = process.env.RENTEMESTER_WORKSPACE;
  if (typeof raw !== "string" || raw.trim().length === 0) return null;
  return resolveWorkspaceRoot(raw.trim());
}

export function isLoopbackBindAddress(host: string): boolean {
  const normalized = host.trim().toLowerCase();
  return normalized === "localhost" ||
    normalized === "127.0.0.1" ||
    normalized === "::1" ||
    normalized === "[::1]" ||
    normalized === "0:0:0:0:0:0:0:1" ||
    normalized === "[0:0:0:0:0:0:0:1]";
}

function resolveHostedBetterAuth(env: Record<string, string | undefined>): HostedBetterAuthConfig {
  const secretConfig = parseVersionedHostedSecrets(env);
  const baseURL = parseHostedOrigin(env[HOSTED_AUTH_ENV.baseURL]?.trim() ?? "", HOSTED_AUTH_ENV.baseURL);
  const trustedOrigins = (env[HOSTED_AUTH_ENV.trustedOrigins] ?? "")
    .split(",")
    .map((origin) => origin.trim())
    .filter(Boolean)
    .map((origin) => parseHostedOrigin(origin, HOSTED_AUTH_ENV.trustedOrigins));
  if (trustedOrigins.length === 0) {
    throw new Error(`${HOSTED_AUTH_ENV.trustedOrigins} requires at least one explicit HTTPS origin`);
  }
  if (!trustedOrigins.includes(baseURL)) {
    throw new Error(`${HOSTED_AUTH_ENV.trustedOrigins} must include ${HOSTED_AUTH_ENV.baseURL}`);
  }
  const provider = (env[HOSTED_AUTH_ENV.emailProvider] ?? "disabled").trim().toLowerCase();
  if (provider !== "http-json-v1") {
    throw new Error(`${HOSTED_AUTH_ENV.emailProvider} must be 'http-json-v1' for hosted deployments`);
  }
  const authEmail: HostedAuthEmailConfig = {
    provider,
    url: env[HOSTED_AUTH_ENV.emailUrl]?.trim() ?? "",
    bearerToken: env[HOSTED_AUTH_ENV.emailBearerToken]?.trim() ?? "",
    from: env[HOSTED_AUTH_ENV.emailFrom]?.trim() ?? "",
  };
  // Validate before the app binds. Configuration errors name only fields, not values.
  validateAuthEmailHttpJsonV1Config({ ...authEmail, idempotencySecret: secretConfig.secret });
  return {
    ...secretConfig,
    baseURL,
    trustedOrigins: [...new Set(trustedOrigins)],
    authEmail,
    rateLimitIpHeader: parseHostedRateLimitIpHeader(env),
  };
}

function resolveHostedDocumentScanning(env: Record<string, string | undefined>): HostedDocumentScanningConfig {
  const policy = (env[DOCUMENT_SCANNER_ENV.policy] ?? "off").trim().toLowerCase();
  if (policy !== "off" && policy !== "required") {
    throw new Error(`${DOCUMENT_SCANNER_ENV.policy} must be 'off' or 'required'`);
  }
  const provider = (env[DOCUMENT_SCANNER_ENV.provider] ?? "disabled").trim().toLowerCase();
  if (policy === "off") {
    if (provider !== "disabled" || [DOCUMENT_SCANNER_ENV.url, DOCUMENT_SCANNER_ENV.bearerToken, DOCUMENT_SCANNER_ENV.timeoutMs].some((name) => Boolean(env[name]?.trim()))) {
      throw new Error(`${DOCUMENT_SCANNER_ENV.policy}=off must not configure a document scanner provider`);
    }
    return { policy: "off" };
  }
  if (provider !== "http-json-v1") {
    throw new Error(`${DOCUMENT_SCANNER_ENV.provider} must be 'http-json-v1' when scanning is required`);
  }
  let url: URL;
  try {
    url = new URL(env[DOCUMENT_SCANNER_ENV.url]?.trim() ?? "");
  } catch {
    throw new Error(`${DOCUMENT_SCANNER_ENV.url} must be an absolute HTTPS URL`);
  }
  if (url.protocol !== "https:" || isLoopbackHostname(url.hostname) || !url.hostname) {
    throw new Error(`${DOCUMENT_SCANNER_ENV.url} must be a non-loopback HTTPS URL`);
  }
  const bearerToken = env[DOCUMENT_SCANNER_ENV.bearerToken]?.trim() ?? "";
  if (!bearerToken) throw new Error(`${DOCUMENT_SCANNER_ENV.bearerToken} is required when scanning is required`);
  return {
    policy: "required",
    provider: {
      provider: "http-json-v1",
      url: url.toString(),
      bearerToken,
      timeoutMs: parseScannerTimeout(env[DOCUMENT_SCANNER_ENV.timeoutMs]),
    },
  };
}

function resolveStaticRoot(env: Record<string, string | undefined>): string {
  const override = env.RENTEMESTER_APP_STATIC?.trim();
  if (override) return override;
  const here = dirname(fileURLToPath(import.meta.url));
  return join(here, "..", "..", "app", "dist");
}

export function startCockpitServer(config: ServerConfig): CockpitServer {
  let authRuntime: WorkspaceBetterAuthRuntime | undefined;
  let runtimeConfig = config;
  // The provider is opt-in for every deployment profile. Configuration errors
  // stop startup; credentials are retained only in this runtime object.
  if (!runtimeConfig.invoiceExtractor) runtimeConfig = { ...runtimeConfig, invoiceExtractor: resolveConfiguredInvoiceExtractor() ?? undefined };
  const deploymentProfile = config.deploymentProfile ?? "local";
  if (deploymentProfile === "hosted") {
    if (!config.hostedBetterAuth) {
      throw new Error("hosted deployment requires validated Better Auth configuration");
    }
    if (config.hostedDocumentScanning?.policy === "required" && !config.hostedDocumentScanning.provider) {
      throw new Error("hosted deployment requires a document scanner provider when scanning is required");
    }
    authRuntime = openWorkspaceBetterAuth(config.workspaceRoot, {
      ...config.hostedBetterAuth,
      deploymentMode: "hosted",
      useSecureCookies: true,
      emailSender: createHttpJsonV1AuthEmailSender({
        ...config.hostedBetterAuth.authEmail,
        idempotencySecret: config.hostedBetterAuth.secret,
      }),
    });
    const scanning = config.hostedDocumentScanning;
    runtimeConfig = {
      ...runtimeConfig,
      authRequired: true,
      betterAuthProvider: createBetterAuthRequestProvider(authRuntime.auth),
      documentScannerPolicy: scanning?.policy ?? "off",
      ...(scanning?.provider ? { documentScanner: createHttpJsonV1DocumentScanner(scanning.provider) } : {}),
    };
  } else if (config.betterAuthProvider) {
    throw new Error("local deployment must not mount a Better Auth provider");
  }

  let server: BunServer;
  try {
    server = Bun.serve({
      hostname: runtimeConfig.host,
      port: runtimeConfig.port,
      fetch(request) {
        return observeRequest(request, runtimeConfig, handleRequest);
      },
    });
  } catch (error) {
    authRuntime?.close();
    throw error;
  }
  const host = config.host.includes(":") ? `[${config.host}]` : config.host;
  return {
    server,
    config: runtimeConfig,
    url: `http://${host}:${server.port}`,
    stop: () => {
      server.stop(true);
      authRuntime?.close();
    },
  };
}

export function resolveConfiguredInvoiceExtractor(env: Record<string, string | undefined> = process.env): InvoiceExtractor | null {
  const provider = (env[INVOICE_EXTRACTION_ENV.provider] ?? "disabled").trim().toLowerCase();
  if (provider === "disabled" || provider === "") return null;
  if (provider !== "http-json-v1") throw new Error(`${INVOICE_EXTRACTION_ENV.provider} must be 'http-json-v1' or 'disabled'`);
  const token = env[INVOICE_EXTRACTION_ENV.bearerToken]?.trim() ?? "";
  const rawUrl = env[INVOICE_EXTRACTION_ENV.url]?.trim() ?? "";
  let url: URL;
  try { url = new URL(rawUrl); } catch { throw new Error(`${INVOICE_EXTRACTION_ENV.url} must be an absolute HTTPS URL`); }
  if (url.protocol !== "https:" || !token) throw new Error("invoice extraction provider requires HTTPS URL and bearer token");
  const timeoutMs = Number(env[INVOICE_EXTRACTION_ENV.timeoutMs] ?? 15_000);
  if (!Number.isInteger(timeoutMs) || timeoutMs < 100 || timeoutMs > 120_000) throw new Error(`${INVOICE_EXTRACTION_ENV.timeoutMs} must be an integer between 100 and 120000`);
  return createHttpJsonV1InvoiceExtractor({ provider: "http-json-v1", url: url.toString(), bearerToken: token, timeoutMs });
}

const INVOICE_EXTRACTION_ENV = {
  provider: "RENTEMESTER_INVOICE_EXTRACTION_PROVIDER",
  url: "RENTEMESTER_INVOICE_EXTRACTION_URL",
  bearerToken: "RENTEMESTER_INVOICE_EXTRACTION_BEARER_TOKEN",
  timeoutMs: "RENTEMESTER_INVOICE_EXTRACTION_TIMEOUT_MS",
} as const;

export function openWorkspaceBetterAuth(
  workspaceRoot: string,
  options: BetterAuthRuntimeOptions,
): WorkspaceBetterAuthRuntime {
  const db = openWorkspaceControlDb(workspaceRoot);
  try {
    const auth = createBetterAuthRuntime(db, options);
    let closed = false;
    return {
      auth,
      close() {
        if (closed) return;
        closed = true;
        db.close();
      },
    };
  } catch (error) {
    db.close();
    throw error;
  }
}

export function createHttpJsonV1AuthEmailSender(
  config: AuthEmailHttpJsonV1Config,
  dependencies: AuthEmailHttpJsonV1Dependencies = {},
): AuthEmailSender {
  validateAuthEmailHttpJsonV1Config(config);
  const endpoint = parseGatewayUrl(config.url).toString();
  const doFetch = dependencies.fetch ?? ((request) => fetch(request));
  const sleep = dependencies.sleep ?? defaultSleep;
  const clock = dependencies.clock ?? Date.now;

  return {
    async send(message): Promise<void> {
      const deadline = clock() + TOTAL_DEADLINE_MS;
      const key = idempotencyKey(config, message);
      const content = subjectAndText(message.kind);
      const body = JSON.stringify({
        version: DELIVERY_VERSION,
        kind: message.kind,
        to: message.recipient,
        from: config.from.trim(),
        subject: content.subject,
        text: content.text,
        actionUrl: message.url,
      });

      for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
        const remaining = deadline - clock();
        if (remaining <= 0) throw new AuthEmailDeliveryError();
        const abort = new AbortController();
        const timeoutAbort = new AbortController();
        let timedOut = false;
        const timeout = sleep(remaining, timeoutAbort.signal).then(() => {
          timedOut = true;
          abort.abort();
          return null;
        });
        let response: Response | null = null;
        let retryable = false;
        try {
          response = await Promise.race([
            doFetch(new Request(endpoint, {
              method: "POST",
              headers: {
                authorization: `Bearer ${config.bearerToken}`,
                "content-type": "application/json",
                "idempotency-key": key,
                "x-rentemester-auth-event": message.kind,
              },
              body,
              signal: abort.signal,
            })),
            timeout,
          ]);
          timeoutAbort.abort();
          if (response && response.status >= 200 && response.status < 300) return;
          retryable = response?.status === 429 || (response?.status ?? 0) >= 500 || timedOut;
        } catch {
          timeoutAbort.abort();
          retryable = true;
        }
        if (!retryable || attempt === MAX_ATTEMPTS || deadline - clock() <= 0) {
          throw new AuthEmailDeliveryError();
        }
        const delay = Math.min(retryDelay(attempt), Math.max(0, deadline - clock()));
        if (delay <= 0) throw new AuthEmailDeliveryError();
        await sleep(delay);
      }
      throw new AuthEmailDeliveryError();
    },
  };
}

export function createBetterAuthRequestProvider(
  auth: Auth<any>,
): BetterAuthRequestProvider {
  return {
    async getSession(request) {
      return await auth.api.getSession({ headers: request.headers }) as BetterAuthSession | null;
    },
    async verifyServicePrincipal(request) {
      const key = request.headers.get(WORKSPACE_SERVICE_PRINCIPAL_HEADER)?.trim();
      if (!key) return { state: "absent" };
      try {
        const result = await (auth.api as any).verifyApiKey({
          body: { key, configId: WORKSPACE_SERVICE_PRINCIPAL_CONFIG_ID },
        }) as { valid?: boolean; key?: { id?: string; referenceId?: string } | null };
        const userId = result.key?.referenceId?.trim() ?? "";
        const credentialId = result.key?.id?.trim() ?? "";
        return result.valid === true && userId && credentialId
          ? { state: "valid", userId, credentialId }
          : { state: "invalid" };
      } catch {
        // Credential details, including whether a key was disabled or expired,
        // are intentionally non-disclosing at the HTTP boundary.
        return { state: "invalid" };
      }
    },
    async handle(request) {
      return await auth.handler(request);
    },
  };
}

export function createHttpJsonV1DocumentScanner(config: HttpJsonV1DocumentScannerConfig): DocumentScanner {
  return {
    async scan(input) {
      const response = await fetch(config.url, {
        method: "POST",
        headers: {
          authorization: `Bearer ${config.bearerToken}`,
          "content-type": "application/json",
          accept: "application/json",
        },
        body: JSON.stringify({
          sha256: input.sha256,
          mimeType: input.mimeType,
          filename: input.filename,
          // The core passes a scanner-only copy. This service must treat it as
          // untrusted input and return no sensitive diagnostic material.
          bytesBase64: input.bytes.toString("base64"),
        }),
        signal: input.signal,
      });
      if (!response.ok) return { ok: false };
      let body: ScannerResponse;
      try {
        body = await response.json() as ScannerResponse;
      } catch {
        return { ok: false };
      }
      if (body.ok !== true || typeof body.scannerId !== "string" || body.scannerId.trim().length === 0) {
        return { ok: false };
      }
      return {
        ok: true,
        scannerId: body.scannerId,
        ...(typeof body.scannerVersion === "string" ? { scannerVersion: body.scannerVersion } : {}),
        ...(typeof body.evidenceRef === "string" ? { evidenceRef: body.evidenceRef } : {}),
      };
    },
  };
}

export async function observeRequest(
  request: Request,
  config: ServerConfig,
  next: (request: Request, config: ServerConfig) => Promise<Response>,
): Promise<Response> {
  const now = config.requestLogClock ?? Date.now;
  const startedAt = now();
  const method = safeMethod(request.method);
  const id = requestId(request, config.requestIdFactory);
  const template = pathTemplate(method, request);
  let status = 500;
  try {
    const response = await next(request, { ...config, requestId: id });
    status = response.status;
    return addRequestId(response, id);
  } finally {
    const event: RequestLogEvent = {
      timestamp: new Date(startedAt).toISOString(),
      level: levelForStatus(status),
      event: "http_request_complete",
      requestId: id,
      method,
      pathTemplate: template,
      status,
      durationMs: Math.max(0, Math.round(now() - startedAt)),
      deploymentProfile: config.deploymentProfile ?? "local",
    };
    try {
      (config.requestLogSink ?? defaultRequestLogSink()).emit(event);
    } catch {
      // Logging never changes an HTTP response and has no raw fallback.
    }
  }
}

typeDeclarations.source:
export type WorkspaceManifest = {
  version: typeof MANIFEST_VERSION;
  companies: WorkspaceCompanyEntry[];
};

export type WorkspaceCompanyEntry = {
  /** Filesystem-safe identifier; the subdirectory name under the workspace. */
  slug: string;
  /** Human-readable display name. */
  name: string;
  /** ISO-8601 timestamp of when the entry was first registered. */
  createdAt: string;
  /** Soft-deletion flag; archived companies stay on disk. */
  archived: boolean;
};

export type CreateCompanyOptions = CompanyInitOptions & {
  /** Required: display name; also the basis for an auto-derived slug. */
  name: string;
  /** Optional explicit slug; auto-derived from `name` when omitted. */
  slug?: string;
};

export type CompanyInitOptions = {
  /** Display name stored in the ledger's `companies` row (id = 1). */
  name?: string;
  cvr?: string | null;
  fiscalYearStartMonth?: number | string | null;
  fiscalYearLabelStrategy?: string | null;
  /** #221: the company's own postal address — the seller address on invoices. */
  address?: string | null;
  postalCode?: string | null;
  city?: string | null;
  /** #221: default payment terms in days (issue date -> due date). */
  paymentTermsDays?: number | string | null;
  /**
   * #289: the company's VAT settlement cadence (`month` / `quarter` /
   * `half-year`). Defaults to `quarter` when omitted.
   */
  vatPeriodType?: string | null;
  /** #221: payment details; when any field is set a bank account is created. */
  payment?: CompanyPaymentInput;
  /**
   * #248: the canonical actor id (user:.../agent:.../system:...) of whoever is
   * running onboarding — seeded into the `actor_allowlist` so the person who
   * runs `init` can immediately mutate, whether they pass `--actor` explicitly
   * or rely on the derived OS username. Keeps the allowlist consistent: the
   * derived actor and an explicit `--actor` with the same id behave the same.
   */
  onboardingActor?: string | null;
};

export type CompanyPaymentInput = {
  bankName?: string | null;
  registrationNo?: string | null;
  accountNo?: string | null;
  iban?: string | null;
};

export type CreateCompanyResult = CompanyInitResult & {
  slug: string;
  name: string;
};

export type CompanyInitResult = {
  companyRoot: string;
  dbPath: string;
};

export type ResolveServerConfigOptions = {
  /** Explicit overrides (e.g. from CLI flags) take precedence over env. */
  host?: string;
  port?: number;
  workspaceRoot?: string;
  /** Read environment from here instead of `process.env` (testability). */
  env?: Record<string, string | undefined>;
};

export type ServerConfig = {
  /** Explicit deployment boundary. `local` may never expose Better Auth. */
  deploymentProfile?: DeploymentProfile;
  /** Interface to bind. Defaults to 127.0.0.1 (localhost-only). */
  host: string;
  /** TCP port to listen on. */
  port: number;
  /** Workspace root the API serves. */
  workspaceRoot: string;
  /**
   * When true, the auth middleware enforces a shared-secret check via the
   * `RENTEMESTER_APP_TOKEN` env var. Phase 1 leaves this off (localhost-trusted)
   * — it exists so the seam can be exercised by tests and flipped on later.
   */
  authRequired: boolean;
  /** Optional shared secret consulted only when `authRequired` is true. */
  authToken: string | null;
  /** Present only for a validated hosted deployment; never serialised. */
  hostedBetterAuth?: HostedBetterAuthConfig;
  /** Hosted ingress policy and, when required, a validated provider config. */
  hostedDocumentScanning?: HostedDocumentScanningConfig;
  /** Runtime scanner seam. Local deployments intentionally leave this absent. */
  documentScanner?: DocumentScanner;
  documentScannerPolicy?: "off" | "required";
  /** Optional explicit extraction provider; absence means extraction is unavailable. */
  invoiceExtractor?: InvoiceExtractor;
  /**
   * Hosted identity provider. Its presence selects Better Auth sessions for
   * protected API routes; public routes remain anonymous. This is injected by
   * the serving composition root, never constructed from a fallback secret.
   */
  betterAuthProvider?: BetterAuthRequestProvider;
  /** Test/composition seam; production derives it from the validated hosted mail configuration. */
  authEmailSender?: AuthEmailSender;
  /** Test/composition seam for private invitation identity creation. */
  invitationIdentityService?: PrivateInvitationIdentityService;
  /**
   * Per-request authentication result. `handleRequest` creates an immutable
   * config copy carrying this value after its one auth evaluation; it is never
   * populated by environment/config resolution.
   */
  requestPrincipal?: Principal;
  /** Validated request correlation ID, attached only by the server edge. */
  requestId?: string;
  /** Test/provider seam; never resolved from environment and invoked only by the router. */
  authenticateRequest?: (request: Request, config: ServerConfig) => Principal | Promise<Principal>;
  /** Test/composition seam for allowlisted request-completion records. Never env-derived. */
  requestLogSink?: RequestLogSink;
  /** Test seam for deterministic, validated response correlation IDs. */
  requestIdFactory?: () => string;
  /** Test seam for deterministic request timestamps and durations. */
  requestLogClock?: () => number;
  /**
   * Absolute path to the built cockpit SPA (`app/dist`). When the directory
   * exists, the server serves it for every non-`/api` route. Resolved here so
   * the rest of the server stays pure. Optional: when absent the server is a
   * pure JSON API (the shape used by API-only tests).
   */
  staticRoot?: string;
};

export type HostedBetterAuthConfig = {
  /** Active key; never emit it in health, CLI, logs, or error responses. */
  secret: string;
  /** First entry is active, following entries are Better Auth decryption-only. */
  secrets: readonly BetterAuthVersionedSecret[];
  /** Only for Better Auth's pre-versioned payloads during a rotation window. */
  legacySecret?: string;
  baseURL: string;
  trustedOrigins: readonly string[];
  authEmail: HostedAuthEmailConfig;
  /** Single edge-owned header Better Auth may use for rate-limit IP keys. */
  rateLimitIpHeader: HostedRateLimitIpHeader;
};

export type BetterAuthVersionedSecret = {
  version: number;
  value: string;
};

export type HostedAuthEmailConfig = {
  provider: "http-json-v1";
  url: string;
  bearerToken: string;
  from: string;
};

export type HostedDocumentScanningConfig = {
  policy: "off" | "required";
  provider?: HttpJsonV1DocumentScannerConfig;
};

export type HttpJsonV1DocumentScannerConfig = {
  provider: "http-json-v1";
  url: string;
  bearerToken: string;
  timeoutMs: number;
};

export type DocumentScanner = {
  scan(input: { bytes: Buffer; sha256: string; mimeType: string; filename: string; signal: AbortSignal }): Promise<
    | { ok: true; scannerId: string; scannerVersion?: string; evidenceRef?: string }
    | { ok: false; error?: string }
  >;
};

export type BetterAuthRequestProvider = {
  getSession(request: Request): Promise<BetterAuthSession | null>;
  /**
   * Verifies the dedicated service-principal credential header.  This never
   * manufactures a browser session: callers receive an identity only after
   * the API-key plugin has checked hash, expiry and enabled state.
   */
  verifyServicePrincipal?(request: Request): Promise<BetterAuthServicePrincipalVerification>;
  handle(request: Request): Promise<Response>;
};

export type BetterAuthSession = {
  user: { id: string };
  session: { id: string; createdAt: Date | string };
};

export type BetterAuthServicePrincipalVerification =
  | { state: "absent" }
  | { state: "invalid" }
  | ({ state: "valid" } & BetterAuthServicePrincipal);

export type BetterAuthServicePrincipal = {
  userId: string;
  credentialId: string;
};

export interface AuthEmailSender {
  send(message: AuthEmailMessage): Promise<void>;
}

export type AuthEmailMessage = {
  kind: AuthEmailKind;
  recipient: string;
  url: string;
  token: string;
};

export type PrivateInvitationIdentityService = {
  createIdentity(input: {
    name: string;
    email: string;
    password: string;
  }): Promise<{ userId: string; created: boolean }>;
  resendVerification(email: string): Promise<void>;
};

export type Principal = {
  /** Canonical actor id, e.g. `system:localhost` or `user:<id>`. */
  id: string;
  /** How the principal was established — useful for audit + diagnostics. */
  via: "localhost-trusted" | "shared-secret" | "better-auth" | "service-principal";
  /** Trusted provider identity; never inferred from actor metadata. */
  userId?: string;
  /** Present only for a verified, live service principal. */
  serviceAccountId?: string;
  /** Better Auth API-key id, safe for security scope/audit but not a secret. */
  credentialId?: string;
  /** Present only for a Better Auth principal and safe to include in audit. */
  sessionId?: string;
  /** Session creation time is retained for append-only invalidation checks. */
  sessionCreatedAt?: Date;
};

export type RequestLogSink = {
  emit(event: RequestLogEvent): void;
};

export type RequestLogEvent = {
  timestamp: string;
  level: "info" | "warn" | "error";
  event: "http_request_complete";
  requestId: string;
  method: string;
  /** A fixed catalog template or fixed anonymous bucket, never raw URL/path. */
  pathTemplate: string;
  status: number;
  durationMs: number;
  deploymentProfile: DeploymentProfile;
};

export type CockpitServer = {
  server: BunServer;
  config: ServerConfig;
  /** Resolved `http://host:port` base URL. */
  url: string;
  stop: () => void;
};

export type WorkspaceBetterAuthRuntime = {
  auth: Auth<any>;
  /** Closes the workspace-control Bun SQLite connection exactly once. */
  close(): void;
};

export type BetterAuthRuntimeOptions = {
  /** Active signing/HMAC key. This module never reads an environment fallback. */
  secret: string;
  /** First key is active; following keys are Better Auth decryption-only keys. */
  secrets?: readonly BetterAuthVersionedSecret[];
  /** Optional old single key for Better Auth's pre-versioned legacy payloads. */
  legacySecret?: string;
  /** Explicit origin allow-list. Wildcards and implicit request origins are not used. */
  trustedOrigins: readonly string[];
  /** Absolute Better Auth base URL for links and callbacks. */
  baseURL: string;
  /** Hosted deployments must opt into Secure cookies explicitly. */
  deploymentMode?: BetterAuthDeploymentMode;
  useSecureCookies?: boolean;
  /** Disabled by default and only replaceable by a workspace-level provider. */
  emailSender?: AuthEmailSender;
  /**
   * Receives only fixed Better Auth diagnostic event names. Raw Better Auth
   * messages, arguments, errors and stacks are never forwarded.
   */
  operationalLogger?: BetterAuthOperationalLogger;
  /** Required for hosted rate limiting; proxy reachability remains a deployment gate. */
  rateLimitIpHeader?: HostedRateLimitIpHeader;
};

export type BetterAuthOperationalLogger = {
  emit(event: BetterAuthOperationalLogEvent): void;
};

export type BetterAuthOperationalLogEvent = {
  component: "better-auth";
  event: "better_auth_warning" | "better_auth_error";
  level: "warn" | "error";
};

export type AuthEmailHttpJsonV1Config = {
  url: string;
  bearerToken: string;
  from: string;
  /** Domain-separated HMAC key. The hosted Better Auth secret is injected here. */
  idempotencySecret: string;
};

export type AuthEmailHttpJsonV1Dependencies = {
  fetch?: (request: Request) => Promise<Response>;
  sleep?: (milliseconds: number, signal?: AbortSignal) => Promise<void>;
  clock?: () => number;
};

type ScannerResponse = {
  ok?: unknown;
  scannerId?: unknown;
  scannerVersion?: unknown;
  evidenceRef?: unknown;
};

