producerDefinitions.source:
export async function verifyRemoteBackupPlacement(
  db: Database,
  companyRoot: string,
  input: VerifyRemoteBackupPlacementInput,
  adapter: RemoteBackupProviderAdapter | undefined,
): Promise<ConfirmBackupPlacementResult> {
  const backupId = trimOrNull(input.backupId);
  const placedAt = resolveAt(input.at);
  const errors: string[] = [];
  if (!backupId || !/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(backupId)) errors.push("backupId is invalid");
  const objectId = trimOrNull(input.remoteObjectId);
  if (!objectId) errors.push("remoteObjectId is required");
  if (!placedAt) errors.push("at must be a valid ISO-8601 datetime when provided");
  if (placedAt && Date.parse(placedAt) > Date.now() + 1_000) errors.push("at must not be in the future");
  if (errors.length > 0) return { ok: false, appliedRules: [BACKUP_RULE_ID], errors };

  const destination = getBackupDestination(companyRoot, input.destinationId);
  if (!destination) {
    return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: [`no backup destination with id: ${input.destinationId}`] };
  }
  if (destination.kind !== "google-drive") {
    return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: ["remote verification requires a google-drive destination"] };
  }
  const folder = googleDriveFolderId(destination.location);
  if (!folder) {
    return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: ["google-drive destination location must be google-drive://<folderId> or a Drive folder URL"] };
  }
  const backups = resolve(companyPaths(companyRoot).backups);
  const archivePath = resolve(backups, `${backupId}.tar`);
  const backupDir = resolve(backups, backupId!);
  if (!archivePath.startsWith(`${backups}/`) || !backupDir.startsWith(`${backups}/`) || !existsSync(archivePath) || !statSync(archivePath).isFile()) {
    return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: ["canonical local backup archive is missing"] };
  }
  if (!existsSync(backupDir) || !statSync(backupDir).isDirectory() || backupIdFromArchive(archivePath) !== backupId || !verifyArchivePayload(archivePath, backupId!, companyRoot, backupDir)) {
    return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: ["canonical archive and backup directory manifests do not match backupId"] };
  }
  const localSignature = verifyBackupSignature({ backupDir });
  if (!localSignature.ok || localSignature.backupId !== backupId) {
    return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: ["canonical backup directory failed manifest integrity verification"] };
  }
  const localHash = sha256File(archivePath);
  const sidecar = `${archivePath}.sha256`;
  let sidecarText: string;
  try { sidecarText = readFileSync(sidecar, "utf8").trim(); } catch {
    return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: ["canonical archive checksum sidecar is missing"] };
  }
  if (sidecarText !== `${localHash}  ${backupId}.tar`) {
    return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: ["canonical archive checksum sidecar does not match archive"] };
  }
  const expectedRemoteObject: ExpectedRemoteBackupObject = {
    provider: "google-drive", objectId: objectId!, name: `${backupId}.tar`, parentId: folder,
    sizeBytes: statSync(archivePath).size, checksumSha256: localHash,
  };
  if (!adapter) {
    return {
      ok: false,
      appliedRules: [BACKUP_RULE_ID],
      errors: ["remote backup provider is not configured; declared evidence cannot be upgraded"],
    };
  }

  const verified = await verifyRemoteBackupEvidence(adapter, {
    expected: expectedRemoteObject,
    // Verification happens now; `placedAt` describes the human placement and
    // may legitimately predate this provider observation.
    verifiedAt: new Date().toISOString(),
    maxMetadataAgeMs: input.maxMetadataAgeMs,
  });
  if (!verified.ok) return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: verified.errors };

  const placement: BackupPlacement = {
    backupId: backupId!,
    archiveSha256: expectedRemoteObject.checksumSha256,
    archiveSizeBytes: expectedRemoteObject.sizeBytes,
    placedAt: placedAt!,
    actor: trimOrNull(input.actor) ?? "system",
    actorKind: input.actorKind === "human" ? "human" : "agent",
    verified: true,
    verifyMethod: "remote-provider",
    remoteEvidence: verified.evidence,
    note: trimOrNull(input.note),
  };
  const appended = appendPlacement(db, companyRoot, destination.id, placement);
  if (!appended.ok) return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: appended.errors };
  return { ok: true, placement, appliedRules: [BACKUP_RULE_ID], errors: [] };
}

function trimOrNull(value: string | null | undefined): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function resolveAt(value?: string): string | null {
  const at = value ?? new Date().toISOString();
  if (Number.isNaN(Date.parse(at))) return null;
  return new Date(at).toISOString();
}

export function getBackupDestination(companyRoot: string, id: string): BackupDestination | undefined {
  return loadBackupDestinations(companyRoot).destinations.find((d) => d.id === id);
}

function googleDriveFolderId(location: string): string | null {
  const canonical = /^google-drive:\/\/([A-Za-z0-9_-]+)$/.exec(location.trim());
  if (canonical) return canonical[1]!;
  try {
    const url = new URL(location);
    if (url.hostname !== "drive.google.com") return null;
    const match = /^\/drive\/folders\/([A-Za-z0-9_-]+)\/?$/.exec(url.pathname);
    return match?.[1] ?? null;
  } catch { return null; }
}

function backupIdFromArchive(archivePath: string): string | null {
  let entries: ReturnType<typeof readTar>;
  try {
    entries = readTar(readFileSync(archivePath));
  } catch {
    return null;
  }
  const manifest = entries.find((e) => e.path === "manifest.json");
  if (!manifest) return null;
  try {
    const parsed = JSON.parse(Buffer.from(manifest.content).toString("utf8")) as { backupId?: string };
    return typeof parsed.backupId === "string" ? parsed.backupId : null;
  } catch {
    return null;
  }
}

function verifyArchivePayload(archivePath: string, backupId: string, companyRoot: string, backupDir: string): boolean {
  try {
    const archiveBytes = readFileSync(archivePath);
    const entries = readTar(archiveBytes);
    const expectedEntries = dirToTarEntries(backupDir);
    // The canonical packer is deterministic. Exact bytes also reject duplicate
    // entries, traversal shadows, extra entries and bytes after the tar trailer.
    if (!archiveBytes.equals(createTar(expectedEntries))) return false;
    if (entries.length !== expectedEntries.length || new Set(entries.map((entry) => entry.path)).size !== entries.length) return false;
    const expectedByPath = new Map(expectedEntries.map((entry) => [entry.path, entry]));
    if (!entries.every((entry) => {
      const expectedEntry = expectedByPath.get(entry.path);
      return expectedEntry && entry.content.byteLength === expectedEntry.content.byteLength &&
        createHash("sha256").update(entry.content).digest("hex") === createHash("sha256").update(expectedEntry.content).digest("hex");
    })) return false;
    const manifestEntry = entries.find((entry) => entry.path === "manifest.json");
    const signature = entries.find((entry) => entry.path === "manifest.json.hmac");
    if (!manifestEntry || !signature) return false;
    const key = readFileSync(backupManifestKeyPath(companyRoot), "utf8").trim();
    if (!/^[0-9a-f]{64}$/i.test(key)) return false;
    const actual = Buffer.from(Buffer.from(signature.content).toString("utf8").trim(), "hex");
    const expected = Buffer.from(createHmac("sha256", Buffer.from(key, "hex")).update(manifestEntry.content).digest("hex"), "hex");
    if (actual.length !== expected.length || !timingSafeEqual(actual, expected)) return false;
    const manifest = JSON.parse(Buffer.from(manifestEntry.content).toString("utf8")) as any;
    if (manifest?.backupId !== backupId) return false;
    const files = [manifest.dbSnapshot, ...(manifest.copiedFiles?.documentsOriginals ?? []), ...(manifest.copiedFiles?.invoicesIssued ?? []), ...(manifest.copiedFiles?.config ?? [])];
    if (!files.every((file: any) => file && typeof file.path === "string" && /^[0-9a-f]{64}$/i.test(file.sha256) && Number.isSafeInteger(file.sizeBytes))) return false;
    return files.every((file: any) => {
      const entry = entries.find((candidate) => candidate.path === file.path);
      return entry && entry.content.byteLength === file.sizeBytes && createHash("sha256").update(entry.content).digest("hex") === file.sha256;
    });
  } catch { return false; }
}

export function verifyBackupSignature(input: VerifyBackupSignatureInput): VerifyBackupSignatureResult {
  if (!input.backupDir || !existsSync(input.backupDir)) {
    return { ok: false, algorithms: [], trustLevel: "none", errors: [`backupDir does not exist: ${input.backupDir}`] };
  }
  const manifestText = readManifestText(input.backupDir);
  if (!manifestText) return { ok: false, algorithms: [], trustLevel: "none", errors: [`invalid or missing backup manifest in ${input.backupDir}`] };
  const manifest = readManifest(input.backupDir);
  if (!manifest) return { ok: false, algorithms: [], trustLevel: "none", errors: [`invalid or missing backup manifest in ${input.backupDir}`] };

  const algorithms: string[] = [];
  const errors: string[] = [];
  let sawOutOfBandAuthenticity = false;
  let sawIntegrity = false;

  // Ed25519 is the 3rd-party-friendly path. Try it first, but only if the
  // manifest advertises it. If the verifier only has a public key (no HMAC
  // key) and the manifest has no ed25519 signature, we cannot verify.
  if (manifest.asymmetricSignature) {
    const ed25519 = verifyManifestEd25519(input.backupDir, manifest, manifestText, input.publicKeyPath, input.publicKeyHint);
    if (ed25519 && "error" in ed25519) {
      errors.push(ed25519.error);
    } else if (ed25519) {
      algorithms.push("ed25519");
      // An ed25519 signature is third-party authenticity ONLY when the key
      // came from out-of-band. An in-backup key proves integrity only.
      if (ed25519.keySource === "out-of-band") sawOutOfBandAuthenticity = true;
      else sawIntegrity = true;
    }
  }

  // HMAC is verified when a key path is supplied or one can be inferred
  // (i.e. we are next to the source company root). Skipped silently for
  // pure 3rd-party verification where only the public key is held.
  const hasInferableHmacKey = input.verificationKeyPath || inferVerificationKeyPath(input.backupDir);
  if (hasInferableHmacKey) {
    const hmacError = verifyManifestHmac(input.backupDir, manifestText, input.verificationKeyPath);
    if (hmacError) {
      errors.push(hmacError);
    } else {
      algorithms.push("hmac-sha256");
      // HMAC is symmetric — the key can re-sign — so it is integrity-only,
      // never third-party authenticity (issue #131).
      sawIntegrity = true;
    }
  }

  if (algorithms.length === 0 && errors.length === 0) {
    errors.push(
      "no verifiable signature found: manifest has no asymmetricSignature block and no HMAC key was provided or inferable",
    );
  }

  // ALSO verify manifest file integrity claims (sha256/size) — a valid
  // signature over a manifest whose file hashes no longer match the on-disk
  // bytes is still a tamper-detection failure.
  const fileErrors = [
    ensureMatches(input.backupDir, manifest.dbSnapshot),
    ...manifest.copiedFiles.documentsOriginals.map((file) => ensureMatches(input.backupDir, file)),
    ...manifest.copiedFiles.invoicesIssued.map((file) => ensureMatches(input.backupDir, file)),
    ...manifest.copiedFiles.config.map((file) => ensureMatches(input.backupDir, file)),
  ].filter((value): value is string => Boolean(value));
  errors.push(...fileErrors);

  const ok = errors.length === 0 && algorithms.length > 0;
  // trustLevel reflects the STRONGEST guarantee that actually held. If
  // anything failed, the backup is not trustworthy at all -> "none".
  const trustLevel: BackupTrustLevel = !ok
    ? "none"
    : sawOutOfBandAuthenticity
      ? "third-party-authenticity"
      : sawIntegrity
        ? "integrity-only"
        : "none";

  return {
    ok,
    backupId: manifest.backupId,
    algorithms,
    trustLevel,
    publicKeyHint: manifest.asymmetricSignature?.publicKeyHint,
    hmacKeyHint: manifest.manifestSignature?.keyHint,
    errors,
  };
}

function sha256File(path: string): string {
  return createHash("sha256").update(readFileSync(path)).digest("hex");
}

export async function verifyRemoteBackupEvidence(
  adapter: RemoteBackupProviderAdapter,
  input: VerifyRemoteBackupEvidenceInput,
): Promise<VerifyRemoteBackupEvidenceResult> {
  const errors = validExpectedObject(input.expected);
  const verifiedAtMs = Date.parse(input.verifiedAt);
  if (Number.isNaN(verifiedAtMs)) errors.push("verifiedAt must be a valid ISO-8601 datetime");
  const maxMetadataAgeMs = input.maxMetadataAgeMs ?? 5 * 60 * 1000;
  if (!Number.isSafeInteger(maxMetadataAgeMs) || maxMetadataAgeMs < 0) {
    errors.push("maxMetadataAgeMs must be a non-negative integer");
  }
  if (adapter.provider !== input.expected.provider) {
    errors.push(`remote provider mismatch: expected ${input.expected.provider}, got ${adapter.provider}`);
  }
  if (errors.length > 0) return { ok: false, errors };

  let lookup: RemoteBackupObjectLookup;
  try {
    lookup = await adapter.getObject(input.expected.objectId);
  } catch {
    return { ok: false, errors: ["remote provider error while reading backup metadata"] };
  }
  if (!lookup.ok) {
    const message = lookup.failure === "revoked"
      ? "remote provider access has been revoked"
      : lookup.failure === "missing"
        ? "remote backup object is missing"
        : "remote provider error while reading backup metadata";
    return { ok: false, errors: [message] };
  }

  const { metadata } = lookup;
  const observedAtMs = Date.parse(metadata.observedAt);
  const observationSkewMs = 1_000;
  if (Number.isNaN(observedAtMs) || verifiedAtMs - observedAtMs > maxMetadataAgeMs || observedAtMs > verifiedAtMs + observationSkewMs) {
    return { ok: false, errors: ["remote backup metadata is stale or has an invalid observation time"] };
  }
  const expected = input.expected;
  if (
    metadata.objectId !== expected.objectId ||
    metadata.name !== expected.name ||
    metadata.parentId !== expected.parentId ||
    metadata.sizeBytes !== expected.sizeBytes ||
    metadata.checksumSha256.toLowerCase() !== expected.checksumSha256.toLowerCase()
  ) {
    return { ok: false, errors: ["remote backup metadata does not match the expected object"] };
  }

  let content: Uint8Array;
  try {
    content = await adapter.readObjectContent(expected.objectId);
  } catch {
    return { ok: false, errors: ["remote provider error while reading backup content"] };
  }
  const contentChecksum = createHash("sha256").update(content).digest("hex");
  if (content.byteLength !== expected.sizeBytes || contentChecksum !== expected.checksumSha256.toLowerCase()) {
    return { ok: false, errors: ["remote backup content does not match the expected size and checksum"] };
  }

  return {
    ok: true,
    evidence: {
      provider: expected.provider,
      objectId: expected.objectId,
      name: expected.name,
      parentId: expected.parentId,
      sizeBytes: expected.sizeBytes,
      checksumSha256: expected.checksumSha256.toLowerCase(),
      metadataObservedAt: new Date(observedAtMs).toISOString(),
      verifiedAt: new Date(Math.max(verifiedAtMs, observedAtMs)).toISOString(),
    },
  };
}

function appendPlacement(
  db: Database,
  companyRoot: string,
  destinationId: string,
  placement: BackupPlacement,
): { ok: boolean; errors: string[] } {
  const file = loadBackupDestinations(companyRoot);
  const destination = file.destinations.find((d) => d.id === destinationId);
  if (!destination) return { ok: false, errors: [`no backup destination with id: ${destinationId}`] };
  destination.placements.push(placement);
  destination.placements.sort((a, b) => (a.placedAt < b.placedAt ? -1 : a.placedAt > b.placedAt ? 1 : 0));
  saveBackupDestinations(companyRoot, file);
  insertAuditLog(db, {
    eventType: "backup_placed",
    entityType: "company",
    entityId: 1,
    message:
      `Recorded placement of backup ${placement.backupId} at destination '${destination.label}' ` +
      `(${destination.id}); verified=${placement.verified} (${placement.verifyMethod}), ` +
      `actor=${placement.actor} (${placement.actorKind}); ` +
      `destination attested §4-compliant=${isCompliantDestination(destination)} ` +
      "(human attestation — verified means the archive bytes were re-read, not that the server is in the EU/EEA)",
  });
  return { ok: true, errors: [] };
}

export function defaultRemoteBackupProviderResolver(fetcher?: GoogleDriveFetch): RemoteBackupProviderResolver {
  return {
    resolve(_companyRoot, provider) {
      if (provider !== "google-drive") return undefined;
      const api = new NativeGoogleDriveBackupApi(async () => process.env.RENTEMESTER_GOOGLE_DRIVE_ACCESS_TOKEN, fetcher);
      return new GoogleDriveRemoteBackupProvider(api);
    },
  };
}

