    const db = openCommandDb(ctx);
    migrate(db);
    const result = configureBackupLock(db, ctx.companyRoot(), {
      enforced,
      graceDays: graceDays.value,
      at: ctx.arg("--at"),
      actor: resolveActorId(ctx),
    });
    ctx.emitResult(result as Record<string, unknown>);
    db.close();
  }

