export function getBackupGovernanceStatus(
  db: Database,
  companyRoot: string,
  asOf?: string,
): BackupGovernanceStatus {
  const compliance = getBackupComplianceStatus(db, companyRoot, asOf);
  const lock = evaluateBackupLock(db, companyRoot, asOf);
  const destinations = listBackupDestinations(companyRoot);
  const compliant = destinations.filter(isCompliantDestination);
  const checkedAtMs = Date.parse(compliance.checkedAt);

  let latestBackupPlacementCount = 0;
  let latestBackupPlacedOffsite = false;
  if (compliance.latestBackupId) {
    for (const destination of destinations) {
      for (const placement of destination.placements) {
        if (placement.backupId !== compliance.latestBackupId) continue;
        const placedAtMs = Date.parse(placement.placedAt);
        if (!Number.isFinite(placedAtMs) || placedAtMs > checkedAtMs) continue;
        if (placement.verifyMethod === "remote-provider") {
          const verifiedAtMs = placement.remoteEvidence ? Date.parse(placement.remoteEvidence.verifiedAt) : Number.NaN;
          if (!Number.isFinite(verifiedAtMs) || verifiedAtMs > checkedAtMs) continue;
        }
        latestBackupPlacementCount += 1;
        if (placement.verified && isCompliantDestination(destination)) {
          latestBackupPlacedOffsite = true;
        }
      }
    }
  }

  // "ok" means: no backup is overdue, AND if a backup exists it sits
  // verified at a §4-compliant destination.
  const ok =
    compliance.errors.length === 0 &&
    !compliance.backupDue &&
    (compliance.latestBackupId === null || latestBackupPlacedOffsite);

  return {
    ok,
    appliedRules: [BACKUP_RULE_ID],
    compliance,
    lock,
    destinations,
    destinationCount: destinations.length,
    compliantDestinationCount: compliant.length,
    hasCompliantDestination: compliant.length > 0,
    latestBackupPlacedOffsite,
    latestBackupPlacementCount,
    checkedAt: compliance.checkedAt,
    errors: compliance.errors,
  };
}

export function getBackupComplianceStatus(db: Database, companyRoot: string, asOf?: string): BackupComplianceStatus {
  const checkedAt = resolveCreatedAt(asOf);
  if (!checkedAt) {
    return {
      ok: false,
      appliedRules: [BACKUP_RULE_ID],
      latestBackupAt: null,
      latestBackupId: null,
      backupDue: false,
      hasActivitySinceBackup: false,
      daysSinceLatestBackup: null,
      requiredBy: null,
      checkedAt: asOf ?? "",
      backupsFound: 0,
      evidence: { latestJournalEntryAt: null, latestDocumentAt: null, latestBankImportAt: null },
      errors: ["asOf must be a valid ISO-8601 datetime when provided"],
    };
  }

  const manifests = listBackupManifests(companyRoot);
  const latest = manifests.at(-1) ?? null;
  const evidence = latestActivityTimestamps(db);
  const latestBackupAt = latest?.createdAt ?? null;
  const latestBackupId = latest?.backupId ?? null;

  const activityMoments = [evidence.latestJournalEntryAt, evidence.latestDocumentAt, evidence.latestBankImportAt]
    .filter((value): value is string => Boolean(value))
    .map((value) => parseActivityMoment(value))
    .filter((value) => Number.isFinite(value));

  const latestBackupMs = latestBackupAt ? new Date(latestBackupAt).getTime() : null;
  const checkedAtMs = new Date(checkedAt).getTime();
  const latestActivityMs = activityMoments.length > 0 ? Math.max(...activityMoments) : null;
  const hasActivitySinceBackup = latestBackupMs === null ? activityMoments.length > 0 : latestActivityMs !== null && latestActivityMs > latestBackupMs;
  // money-allowed: days-since-backup math, not currency
  const daysSinceLatestBackup = latestBackupMs === null ? null : Number(((checkedAtMs - latestBackupMs) / (24 * 60 * 60 * 1000)).toFixed(2));
  const backupDue = latestBackupMs === null ? hasActivitySinceBackup : hasActivitySinceBackup && (checkedAtMs - latestBackupMs > BACKUP_INTERVAL_MS);
  const requiredBy = latestBackupMs === null ? (hasActivitySinceBackup ? checkedAt : null) : hasActivitySinceBackup ? new Date(latestBackupMs + BACKUP_INTERVAL_MS).toISOString() : null;

  return {
    ok: !backupDue,
    appliedRules: [BACKUP_RULE_ID],
    latestBackupAt,
    latestBackupId,
    backupDue,
    hasActivitySinceBackup,
    daysSinceLatestBackup,
    requiredBy,
    checkedAt,
    backupsFound: manifests.length,
    evidence,
    errors: [],
  };
}

export function evaluateBackupLock(
  db: Database,
  companyRoot: string,
  asOf?: string,
): BackupLockEvaluation {
  const config = loadBackupLockConfig(companyRoot);
  const status = getBackupComplianceStatus(db, companyRoot, asOf);
  const checkedAt = status.checkedAt;

  if (status.errors.length > 0 || !checkedAt) {
    return {
      enforced: config.enforced,
      locked: false,
      backupDue: false,
      graceDays: config.graceDays,
      latestBackupAt: status.latestBackupAt,
      daysSinceLatestBackup: status.daysSinceLatestBackup,
      lockAt: null,
      checkedAt: checkedAt ?? "",
      reason: status.errors[0] ?? "backup status could not be evaluated",
      errors: status.errors,
    };
  }

  if (!config.enforced) {
    return {
      enforced: false,
      locked: false,
      backupDue: status.backupDue,
      graceDays: config.graceDays,
      latestBackupAt: status.latestBackupAt,
      daysSinceLatestBackup: status.daysSinceLatestBackup,
      lockAt: null,
      checkedAt,
      reason: "backup lock is not enforced (opt-in)",
      errors: [],
    };
  }

  if (!status.backupDue) {
    return {
      enforced: true,
      locked: false,
      backupDue: false,
      graceDays: config.graceDays,
      latestBackupAt: status.latestBackupAt,
      daysSinceLatestBackup: status.daysSinceLatestBackup,
      lockAt: null,
      checkedAt,
      reason: status.hasActivitySinceBackup
        ? "backup is recent enough"
        : "no bookkeeping activity since the last backup — no backup is due",
      errors: [],
    };
  }

  const checkedAtMs = new Date(checkedAt).getTime();
  const graceMs = config.graceDays * DAY_MS;
  // The lock deadline runs from the last backup, or — for a company that
  // never backed up — from its earliest bookkeeping activity. The null
  // branch is defensive only: backupDue is true here, which already implies
  // activity exists, so earliestActivityMs cannot realistically be null.
  let anchorMs: number | null = null;
  if (status.latestBackupAt) {
    anchorMs = new Date(status.latestBackupAt).getTime();
  } else {
    anchorMs = earliestActivityMs(db);
  }
  const lockAtMs = anchorMs === null ? checkedAtMs : anchorMs + WEEK_MS + graceMs;
  const locked = checkedAtMs >= lockAtMs;

  return {
    enforced: true,
    locked,
    backupDue: true,
    graceDays: config.graceDays,
    latestBackupAt: status.latestBackupAt,
    daysSinceLatestBackup: status.daysSinceLatestBackup,
    lockAt: new Date(lockAtMs).toISOString(),
    checkedAt,
    reason: locked
      ? "bookkeeping is locked: a weekly backup (BEK 205/2024 §4) is overdue past the grace window"
      : "a backup is due — bookkeeping will lock when the grace window lapses",
    errors: [],
  };
}

export function listBackupDestinations(companyRoot: string): BackupDestination[] {
  return loadBackupDestinations(companyRoot).destinations;
}

export function isCompliantDestination(destination: BackupDestination): boolean {
  return (
    destination.regionAttestation.inEeaOrEu === true &&
    destination.nonRelatedParty === true &&
    destination.itSecurityAttestation?.meetsRecognisedStandards === true
  );
}

export function getCompanySettings(db: Database): CompanySettings {
  // #289: older ledgers (and the base schema.sql) may lack `vat_period_type`.
  // Read it only when present; absent → fall back to the quarterly default so
  // a pre-#289 company is unaffected.
  const vatColumn = hasVatPeriodColumn(db) ? "vat_period_type" : "NULL AS vat_period_type";
  const row = db.query(
    `SELECT id, name, country, currency, cvr, fiscal_year_start_month, fiscal_year_label_strategy,
            address, postal_code, city, company_form, industry_code, industry_text,
            cvr_status, audit_waived, cvr_synced_at, payment_terms_days, ${vatColumn}
       FROM companies
      ORDER BY id ASC
      LIMIT 1`
  ).get() as {
    id: number;
    name: string;
    country: string;
    currency: string;
    cvr: string | null;
    fiscal_year_start_month: number;
    fiscal_year_label_strategy: FiscalYearLabelStrategy;
    address: string | null;
    postal_code: string | null;
    city: string | null;
    company_form: string | null;
    industry_code: string | null;
    industry_text: string | null;
    cvr_status: string | null;
    audit_waived: number | null;
    cvr_synced_at: string | null;
    payment_terms_days: number | null;
    vat_period_type: string | null;
  } | null;

  if (!row) return DEFAULT_COMPANY_SETTINGS;
  return {
    id: row.id,
    name: row.name,
    country: row.country,
    currency: row.currency,
    cvr: normalizeCvr(row.cvr),
    fiscalYearStartMonth: normalizeFiscalYearStartMonth(row.fiscal_year_start_month) ?? 1,
    fiscalYearLabelStrategy: normalizeFiscalYearLabelStrategy(row.fiscal_year_label_strategy) ?? "end-year",
    address: row.address,
    postalCode: row.postal_code,
    city: row.city,
    companyForm: row.company_form,
    industryCode: row.industry_code,
    industryText: row.industry_text,
    cvrStatus: row.cvr_status,
    auditWaived: row.audit_waived === null ? null : row.audit_waived === 1,
    cvrSyncedAt: row.cvr_synced_at,
    paymentTermsDays:
      normalizePaymentTermsDays(row.payment_terms_days) ?? DEFAULT_PAYMENT_TERMS_DAYS,
    // `null` in the column = "not VAT-registered" — preserved verbatim. A
    // stored value that fails normalisation (corrupt cell) falls back to the
    // historical default so legacy ledgers stay readable.
    vatPeriodType:
      row.vat_period_type === null
        ? null
        : normalizeVatPeriodType(row.vat_period_type) ?? DEFAULT_VAT_PERIOD_TYPE,
  };
}

const DEFAULT_COMPANY_SETTINGS: CompanySettings = {
  id: 1,
  name: "Rentemester company",
  country: "DK",
  currency: "DKK",
  cvr: null,
  fiscalYearStartMonth: 1,
  fiscalYearLabelStrategy: "end-year",
  address: null,
  postalCode: null,
  city: null,
  companyForm: null,
  industryCode: null,
  industryText: null,
  cvrStatus: null,
  auditWaived: null,
  cvrSyncedAt: null,
  paymentTermsDays: DEFAULT_PAYMENT_TERMS_DAYS,
  // Keep the module's eager default independent of the close/VAT graph.
  // `periods.ts` imports the close-readiness graph, which eventually reads
  // company settings.  The value is the same canonical default exported from
  // that module; using the literal here prevents an ESM initialization cycle
  // from observing its export before initialization.
  vatPeriodType: "quarter",
};

function hasVatPeriodColumn(db: Database): boolean {
  const cols = db.query("PRAGMA table_info(companies)").all() as Array<{ name: string }>;
  return cols.some((col) => col.name === "vat_period_type");
}

export function normalizeCvr(value?: string | null): string | null {
  const trimmed = value?.trim();
  if (!trimmed) return null;
  const stripped = trimmed.toUpperCase().replace(/^DK/, "");
  if (!/^\d{8}$/.test(stripped)) {
    throw new Error(`CVR must be 8 digits (optionally prefixed with DK), got: ${value}`);
  }
  return `DK${stripped}`;
}

export function normalizeFiscalYearStartMonth(value?: number | string | null) {
  const month = typeof value === "string" ? Number(value) : value;
  if (!Number.isInteger(month) || (month ?? 0) < 1 || (month ?? 0) > 12) return null;
  return month;
}

export function normalizeFiscalYearLabelStrategy(value?: string | null): FiscalYearLabelStrategy | null {
  if (value === "end-year" || value === "start-year" || value === "span") return value;
  return null;
}

export function normalizePaymentTermsDays(value?: number | string | null): number | null {
  if (value === undefined || value === null || value === "") return null;
  const days = typeof value === "string" ? Number(value) : value;
  if (!Number.isInteger(days) || (days as number) < 0 || (days as number) > 365) return null;
  return days as number;
}

export function normalizeVatPeriodType(value?: string | null): VatPeriodType | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return VAT_PERIOD_TYPES.has(trimmed as VatPeriodType) ? (trimmed as VatPeriodType) : null;
}

