export type VerifyBackupSignatureInput = {
  backupDir: string;
  verificationKeyPath?: string;
  publicKeyPath?: string;
  // Out-of-band public-key hint. When set, an ed25519 key resolved from inside
  // the backup must match it or verification fails closed (issue #132).
  publicKeyHint?: string;
};

export type VerifyBackupSignatureResult = {
  ok: boolean;
  backupId?: string;
  algorithms: string[];
  trustLevel: BackupTrustLevel;
  publicKeyHint?: string;
  hmacKeyHint?: string;
  errors: string[];
};

export type BackupManifestV1 = BackupManifestBody & {
  manifestVersion?: 1;
  provenance?: never;
};

type BackupManifestBody = {
  backupId: string;
  createdAt: string;
  ruleIds: string[];
  manifestSignature: {
    algorithm: "hmac-sha256";
    keyHint: string;
    signaturePath: string;
  };
  asymmetricSignature?: BackupAsymmetricSignature;
  dbSnapshot: ManifestFile;
  copiedFiles: {
    documentsOriginals: ManifestFile[];
    invoicesIssued: ManifestFile[];
    config: ManifestFile[];
  };
  ledgerStats: {
    journalEntries: number;
    documents: number;
    bankTransactions: number;
  };
};

export type BackupAsymmetricSignature = {
  algorithm: "ed25519";
  publicKeyHint: string;
  publicKeyPath: string;
  signaturePath: string;
};

export type BackupManifestV2 = BackupManifestBody & {
  manifestVersion: 2;
  provenance: ReleaseProvenance;
};

export type ReleaseProvenance = {
  product: ReturnType<typeof getBuildIdentity>;
  schema: {
    version: number;
    baselineChecksum: string;
  };
  rules: {
    digest: string;
  };
};

type Ed25519VerifyResult =
  | { error: string }
  // keySource distinguishes a key the verifier supplied out-of-band (genuine
  // 3rd-party authenticity) from one resolved inside the backup itself. An
  // in-backup key only proves the backup is internally self-consistent — a
  // local actor who re-signs with a fresh keypair would also pass — so it is
  // INTEGRITY-ONLY, never authenticity (issue #132).
  | { ok: true; keySource: "out-of-band" | "in-backup"; publicKeyHint: string };

