producerDefinitions.source:
export async function customerInputFromCvr(
  db: Database,
  cvrInput: string,
  base: Partial<CreateCustomerInput>,
  options: CvrLookupOptions = {},
): Promise<CvrAutofillResult<CreateCustomerInput>> {
  const lookup = await lookupCvrCompany(db, cvrInput, options);
  if (!lookup.ok || !lookup.company) return { ok: false, errors: lookup.errors };
  const company = lookup.company;
  return {
    ok: true,
    company,
    input: {
      ...base,
      name: trimToNull(base.name) ?? company.name,
      address: trimToNull(base.address) ?? cvrFullAddress(company),
      vatOrCvr: trimToNull(base.vatOrCvr) ?? `DK${company.cvr}`,
      email: trimToNull(base.email) ?? company.email ?? undefined,
      phone: trimToNull(base.phone) ?? company.phone ?? undefined,
      website: trimToNull(base.website) ?? company.website ?? undefined,
    },
  };
}

export async function lookupCvrCompany(
  db: Database,
  cvrInput: string | null | undefined,
  options: CvrLookupOptions = {},
): Promise<CvrLookupResult> {
  const cvrNumber = normalizeCvrNumber(cvrInput);
  if (!cvrNumber) {
    return {
      ok: false,
      cached: false,
      errors: ["cvr skal være et 8-cifret CVR-nummer (evt. med DK-præfiks)"],
    };
  }

  const asOf = options.asOf ?? new Date().toISOString();
  const maxAgeDays = options.maxAgeDays ?? DEFAULT_TTL_DAYS;
  const cached = getCachedCvrLookup(db, cvrNumber);

  if (cached && !options.forceRefresh && !isExpired(cached.expiresAt, asOf)) {
    return {
      ok: true,
      company: cached.company,
      cached: true,
      fetchedAt: cached.fetchedAt,
      errors: [],
    };
  }

  const username = options.username ?? process.env.CVR_USERNAME;
  const password = options.password ?? process.env.CVR_PASSWORD;
  if (!username || !password) {
    if (cached) {
      // No credentials, but a stale snapshot is still better than nothing.
      return {
        ok: true,
        company: cached.company,
        cached: true,
        fetchedAt: cached.fetchedAt,
        errors: [],
      };
    }
    return {
      ok: false,
      cached: false,
      errors: [
        "CVR-opslag kræver miljøvariablerne CVR_USERNAME og CVR_PASSWORD — opret system-til-system-adgang på virk.dk (log ind → Min profil → System-til-system-adgang/Serviceaftaler) og sæt de to variabler i dit miljø",
      ],
    };
  }

  const baseUrl =
    options.endpoint ?? process.env.RENTEMESTER_CVR_ENDPOINT ?? DEFAULT_CVR_BASE_URL;
  const fetched = await fetchCvrCompany(cvrNumber, {
    fetchImpl: options.fetchImpl ?? fetch,
    baseUrl,
    username,
    password,
    timeoutMs: options.timeoutMs ?? DEFAULT_CVR_TIMEOUT_MS,
  });

  if (!fetched.ok) {
    if (cached) {
      // The network failed — fall back to the stale snapshot rather than error.
      return {
        ok: true,
        company: cached.company,
        cached: true,
        fetchedAt: cached.fetchedAt,
        errors: [],
      };
    }
    return { ok: false, cached: false, errors: [fetched.error] };
  }

  const company = mapVirksomhed(fetched.entity, cvrNumber);
  storeCvrLookup(db, company, {
    rawResponse: JSON.stringify(fetched.entity),
    fetchedAt: asOf,
    expiresAt: addDaysToTimestamp(asOf, maxAgeDays),
  });

  return {
    ok: true,
    company,
    cached: false,
    fetchedAt: asOf,
    errors: [],
  };
}

export function trimToNull(value: unknown) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function cvrFullAddress(company: CvrCompanyInfo): string | undefined {
  const cityLine = [company.postalCode, company.city].filter(Boolean).join(" ");
  const full = [company.address, cityLine].filter((part) => part && part.length > 0).join(", ");
  return full.length > 0 ? full : undefined;
}

export function createCustomer(db: Database, input: Partial<CreateCustomerInput>) {
  const name = trimToNull(input.name);
  if (!name) return { ok: false, errors: ["name is required"] };
  const vatOrCvr = trimToNull(input.vatOrCvr);
  const rawEanNumber = trimToNull(input.eanNumber);
  const eanNumber = rawEanNumber ? normalizeEanNumber(rawEanNumber) : null;
  if (rawEanNumber && !eanNumber) return { ok: false, errors: ["eanNumber must be 13 digits"] };
  // EJER-3: no explicit frist → store NULL so the invoice inherits the
  // COMPANY profile's payment terms at invoice time (previously a silent,
  // hardcoded 30 that overrode the owner's own standard without a word).
  // Backward compat: customers created before this change carry a stored 30
  // that cannot be told apart from a deliberate 30 — they keep their 30, and
  // the deviation note in invoice create makes it visible.
  let paymentTermsDays: number | null = null;
  if (input.paymentTermsDays !== undefined && input.paymentTermsDays !== null) {
    const value = Number(input.paymentTermsDays);
    if (!Number.isInteger(value) || value <= 0) {
      return { ok: false, errors: ["paymentTermsDays must be a positive integer"] };
    }
    paymentTermsDays = value;
  }
  const defaultCurrency = normalizeCurrency(input.defaultCurrency);
  if (!/^[A-Z]{3}$/.test(defaultCurrency)) return { ok: false, errors: ["defaultCurrency must be a 3-letter ISO code"] };

  const inserted = db.transaction(() => {
    const row = db.query(
      `INSERT INTO customers (name, address, vat_or_cvr, email, phone, website, ean_number, payment_terms_days, default_currency, notes)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
       RETURNING id, created_at`
    ).get(
      name,
      trimToNull(input.address),
      vatOrCvr,
      trimToNull(input.email),
      trimToNull(input.phone),
      trimToNull(input.website),
      eanNumber,
      paymentTermsDays,
      defaultCurrency,
      trimToNull(input.notes),
    ) as { id: number; created_at: string };

    strengthenGdprErasureAliasesForIdentity(db, {
      name,
      cvr: vatOrCvr,
    });

    insertAuditLog(db, {
      eventType: "customer_create",
      entityType: "customer",
      entityId: row.id,
      message: `Created customer ${name}`,
    });

    return row;
  }).immediate();

  return { ok: true, customerId: inserted.id, appliedRules: ["DK-MASTER-DATA-CUSTOMER-001"], errors: [] };
}

export function normalizeEanNumber(value: unknown) {
  const trimmed = trimToNull(value);
  if (!trimmed) return null;
  const digitsOnly = trimmed.replace(/\s+/g, "");
  return /^\d{13}$/.test(digitsOnly) ? digitsOnly : null;
}

function normalizeCurrency(value: string | null | undefined) {
  return (trimToNull(value) ?? "DKK").toUpperCase();
}

export function strengthenGdprErasureAliasesForIdentity(
  db: Database,
  identity: { name?: string | null; cvr?: string | null },
): void {
  const subject = resolveSubject(identity);
  if (!subject.name || !subject.cvr) return;
  const nameReference = subjectAuditReference(`name:${subject.name}`);
  const priorNameErasure = db
    .query(
      `SELECT 1
         FROM gdpr_erasures
        WHERE subject_key IN (?, ?)
        LIMIT 1`,
    )
    .get(nameReference, subject.name);
  if (!priorNameErasure) return;

  const scopeResolution = resolveSubjectScope(db, subject);
  if (!scopeResolution.ok) return;
  const erasures = loadErasures(
    db,
    // The name may already have become ambiguous. It is safe to inspect its
    // old hash here because strengthenErasureAliases still requires exact CVR
    // evidence on each source row before creating a stable binding.
    [...scopeResolution.scope.erasureSubjectKeys, nameReference],
  );
  const rows = collectSourceRows(db, scopeResolution.scope);
  strengthenErasureAliases(db, scopeResolution.scope, rows, erasures);
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

