async (ctx) => {
    const db = openCommandDb(ctx);
    migrate(db);
    const base: CreateVendorInput = {
      name: ctx.arg("--name") ?? "",
      address: ctx.arg("--address") ?? undefined,
      vatOrCvr: ctx.arg("--cvr") ?? undefined,
