export function resolveInvoiceMasterData(
  db: Database,
  payload: InvoicePayload,
  options: { customerId?: number | null },
): { ok: true; payload: InvoicePayload; notes?: string[] } | { ok: false; errors: string[] } {
  if (!options.customerId) return { ok: true, payload };
  const customer = getCustomerById(db, options.customerId);
  if (!customer || customer.archived) return { ok: false, errors: [`customer ${options.customerId} does not exist`] };

  // EJER-3: only an EXPLICIT kundefrist sets the due date here. A customer
  // stored with NULL has no own frist — the due date is left unset so
  // issueInvoice's enrichInvoiceFromCompany fills it from the company
  // profile's payment terms (the owner's own standard).
  const explicitDueDate = trimToNull(payload.dueDate);
  const customerTerms = customer.payment_terms_days;
  const dueDate =
    explicitDueDate ??
    (trimToNull(payload.issueDate) && customerTerms != null && customerTerms > 0
      ? addDays(payload.issueDate!, customerTerms)
      : undefined);

  // EJER-3: when the kundekort's explicit frist (not the company standard)
  // decides the due date AND deviates from the profile, say so out loud —
  // the owner must never discover a silently different betalingsfrist.
  const notes: string[] = [];
  if (!explicitDueDate && dueDate !== undefined && customerTerms != null) {
    const companyTerms = companyDefaultPaymentTermsDays(db);
    if (companyTerms != null && companyTerms !== customerTerms) {
      notes.push(
        `Betalingsfrist ${customerTerms} dage fra kundekortet — virksomhedens standard er ${companyTerms} dage.`,
      );
    }
  }

  return {
    ok: true,
    payload: {
      ...payload,
      buyer: {
        name: trimToNull(payload.buyer?.name) ?? customer.name,
        address: trimToNull(payload.buyer?.address) ?? customer.address ?? undefined,
        vatOrCvr: trimToNull(payload.buyer?.vatOrCvr) ?? customer.vat_or_cvr ?? undefined,
        eanNumber: normalizeEanNumber(payload.buyer?.eanNumber) ?? customer.ean_number ?? undefined,
        publicRecipient: payload.buyer?.publicRecipient ?? Boolean(normalizeEanNumber(payload.buyer?.eanNumber) ?? customer.ean_number),
      },
      currency: trimToNull(payload.currency) ?? customer.default_currency,
      dueDate,
    },
    ...(notes.length > 0 ? { notes } : {}),
  };
}

export function getCustomerById(db: Database, id: number) {
  return db.query(
    `SELECT id, name, address, vat_or_cvr, email, phone, website, ean_number, payment_terms_days, default_currency, notes, archived, created_at
     FROM customers WHERE id = ? LIMIT 1`
  ).get(id) as {
    id: number; name: string; address: string | null; vat_or_cvr: string | null; email: string | null; phone: string | null; website: string | null; ean_number: string | null; payment_terms_days: number | null; default_currency: string; notes: string | null; archived: number; created_at: string;
  } | null;
}

export function trimToNull(value: unknown) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

export function addDays(isoDate: string, days: number): string {
  const date = new Date(`${isoDate}T00:00:00.000Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

function companyDefaultPaymentTermsDays(db: Database): number | null {
  try {
    const row = db.query(`SELECT payment_terms_days FROM companies ORDER BY id ASC LIMIT 1`).get() as
      | { payment_terms_days: number | null }
      | null;
    if (!row) return null;
    const days = Number(row.payment_terms_days);
    return Number.isInteger(days) && days >= 0 && days <= 365 ? days : null;
  } catch {
    return null;
  }
}

export function normalizeEanNumber(value: unknown) {
  const trimmed = trimToNull(value);
  if (!trimmed) return null;
  const digitsOnly = trimmed.replace(/\s+/g, "");
  return /^\d{13}$/.test(digitsOnly) ? digitsOnly : null;
}

export function issueInvoice(
  db: Database,
  companyRoot: string,
  rawPayload: InvoicePayload,
  actor: ResolveActorInput = {},
): IssueInvoiceResult {
  // #221: fill the seller identity + due date from the stored company profile
  // before validation, so the owner never re-types their own master data.
  const payload = enrichInvoiceFromCompany(db, rawPayload);
  const validation = validateInvoice(payload);
  const appliedRules = [...new Set([...(validation.appliedRules ?? []), RULE_ID, LOCK_RULE_ID])];
  if (!validation.ok) return { ok: false, appliedRules, errors: validation.errors };

  // #221: resolve the company's payment details once, so the customer-facing
  // PDF built at issue time always carries the BETALING block (where to pay).
  const invoiceCurrency = (payload.currency ?? "DKK").trim().toUpperCase();
  const paymentDetails = resolveCompanyPaymentDetails(db, invoiceCurrency);

  let viesValidation: ReturnType<typeof requireCachedViesValidation>["validation"] | undefined;
  if (payload.vatTreatment === "foreign_reverse_charge") {
    const viesCheck = requireCachedViesValidation(db, payload.buyer?.vatOrCvr, "buyer.vatOrCvr");
    if (!viesCheck.ok) return { ok: false, appliedRules: [...new Set([...appliedRules, ...viesCheck.appliedRules])], errors: viesCheck.errors };
    viesValidation = viesCheck.validation;
  }

  const explicitInvoiceNumber = payload.invoiceNumber?.trim();
  if (explicitInvoiceNumber) {
    const scopeError = validateManualInvoiceNumberScope(db, payload.issueDate!, explicitInvoiceNumber);
    if (scopeError) return { ok: false, appliedRules, errors: [scopeError] };
  }
  const paths = companyPaths(companyRoot);
  mkdirSync(paths.invoicesIssued, { recursive: true });

  let tempPath: string | undefined;
  let storedPath: string | undefined;
  let pdfTempPath: string | undefined;
  let pdfStoredPath: string | undefined;
  let storedPathPromoted = false;
  let pdfStoredPathPromoted = false;

  // Calculate advisory-only output before any irreversible publication. A
  // warning lookup failure must never make a committed legal document look as
  // though issuance failed to its caller.
  const warnings = closedPeriodIssueWarnings(db, payload.issueDate);

  try {
    const result = db.transaction(() => {
      let invoiceNumber: InvoiceNumber;
      if (explicitInvoiceNumber !== undefined) {
        const reserved = reserveManualInvoiceNumber(db, payload.issueDate!, explicitInvoiceNumber);
        if (!reserved.ok) return { ok: false as const, error: reserved.error };
        // #251: use the canonicalised four-digit number, not the verbatim
        // input, so the persisted snapshot, PDF and documents row all carry the
        // same consistent format as an auto-numbered invoice.
        invoiceNumber = asInvoiceNumber(reserved.invoiceNumber);
      } else {
        invoiceNumber = nextIssuedInvoiceNumber(db, payload.issueDate!);
      }

      const issuedAt = new Date().toISOString();
      const issuedPayload = {
        ...payload,
        invoiceNumber,
        issuedAt,
        status: "issued",
        ...(viesValidation ? { viesValidation } : {}),
        // #221: persist the resolved payment details into the snapshot so the
        // at-issue PDF — and any later `invoice render` — show where to pay.
        ...(paymentDetails ? { payment: paymentDetails } : {}),
      };
      const serialized = JSON.stringify(issuedPayload, null, 2);
      const hash = sha256(serialized);
      const pdfBytes = buildIssuedInvoicePdf(issuedPayload);
      const pdfHash = createHash("sha256").update(pdfBytes).digest("hex");
      storedPath = join(paths.invoicesIssued, `${invoiceNumber}.json`);
      pdfStoredPath = join(paths.invoicesIssued, `${invoiceNumber}.pdf`);
      tempPath = writeTempFileFor(storedPath, serialized);
      pdfTempPath = writeTempFileFor(pdfStoredPath, pdfBytes);

      const grossAmount = payload.totals?.grossAmount ?? null;
      const vatAmount = payload.totals?.vatAmount ?? null;
      const inserted = db.query(
      `INSERT INTO documents (
        document_no, source, original_filename, stored_path, mime_type, sha256_hash,
        supplier_name, invoice_no, invoice_date, amount_inc_vat, currency, status,
        document_type, delivery_description, sender_name, sender_address, sender_vat_cvr,
        recipient_name, recipient_address, recipient_vat_cvr, vat_amount, payment_details, exemption_code, payload_json, retain_until
      ) VALUES (?, 'rentemester', ?, ?, 'application/json', ?, ?, ?, ?, ?, ?, 'issued', 'issued_invoice', ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?)
      RETURNING id`
    ).get(
      invoiceNumber,
      `${invoiceNumber}.json`,
      storedPath,
      hash,
      payload.seller?.name ?? null,
      invoiceNumber,
      payload.issueDate ?? null,
      grossAmount,
      invoiceCurrency,
      deliveryDescription(payload),
      payload.seller?.name ?? null,
      payload.seller?.address ?? null,
      payload.seller?.vatOrCvr ?? null,
      payload.buyer?.name ?? null,
      payload.buyer?.address ?? null,
      payload.buyer?.vatOrCvr ?? null,
      vatAmount,
      payload.reverseChargeBasis ?? null,
      serialized,
      retainUntilForDate(db, payload.issueDate!),
    ) as { id: number };

      const pdfInserted = db.query(
      `INSERT INTO documents (
        document_no, source, original_filename, stored_path, mime_type, sha256_hash,
        supplier_name, invoice_no, invoice_date, amount_inc_vat, currency, status,
        document_type, sender_name, sender_address, sender_vat_cvr,
        recipient_name, recipient_address, recipient_vat_cvr, vat_amount, payload_json, retain_until
      ) VALUES (?, 'rentemester', ?, ?, 'application/pdf', ?, ?, ?, ?, ?, ?, 'issued', 'issued_invoice_pdf', ?, ?, ?, ?, ?, ?, ?, ?, ?)
      RETURNING id`
    ).get(
      `${invoiceNumber}-pdf`,
      `${invoiceNumber}.pdf`,
      pdfStoredPath,
      pdfHash,
      payload.seller?.name ?? null,
      invoiceNumber,
      payload.issueDate ?? null,
      grossAmount,
      invoiceCurrency,
      payload.seller?.name ?? null,
      payload.seller?.address ?? null,
      payload.seller?.vatOrCvr ?? null,
      payload.buyer?.name ?? null,
      payload.buyer?.address ?? null,
      payload.buyer?.vatOrCvr ?? null,
      vatAmount,
      serialized,
      retainUntilForDate(db, payload.issueDate!),
      ) as { id: number };

      strengthenGdprErasureAliasesForIdentity(db, {
        name: payload.seller?.name,
        cvr: payload.seller?.vatOrCvr,
      });
      strengthenGdprErasureAliasesForIdentity(db, {
        name: payload.buyer?.name,
        cvr: payload.buyer?.vatOrCvr,
      });

      insertAuditLog(db, {
        eventType: "invoice_issue",
        entityType: "document",
        entityId: inserted.id,
        message: `Issued invoice ${invoiceNumber}`,
        createdBy: actor.createdBy,
        createdByProgram: actor.createdByProgram,
      });
      insertAuditLog(db, {
        eventType: "invoice_render_pdf",
        entityType: "document",
        entityId: pdfInserted.id,
        message: `Rendered invoice PDF ${invoiceNumber}`,
        createdBy: actor.createdBy,
        createdByProgram: actor.createdByProgram,
      });

      // Publish both immutable artifacts while the database transaction is
      // still open. A publication failure throws and rolls every document,
      // audit, and sequence row back. If COMMIT itself then fails, the outer
      // catch removes the already-published paths.
      promoteTempFileExclusive(tempPath!, storedPath!);
      storedPathPromoted = true;
      promoteTempFileExclusive(pdfTempPath!, pdfStoredPath!);
      pdfStoredPathPromoted = true;

      return { ok: true as const, documentId: asDocumentId(inserted.id), invoiceNumber, sha256: hash, pdfDocumentId: asDocumentId(pdfInserted.id), pdfSha256: pdfHash };
    }).immediate();

    if (!result.ok) return { ok: false, appliedRules, errors: [result.error] };
    return {
      ok: true,
      documentId: result.documentId,
      invoiceNumber: result.invoiceNumber,
      storedPath,
      sha256: result.sha256,
      pdfDocumentId: result.pdfDocumentId,
      pdfStoredPath,
      pdfSha256: result.pdfSha256,
      appliedRules,
      errors: [],
      ...(warnings.length > 0 ? { warnings } : {}),
    };
  } catch (error) {
    if (tempPath) removeIfExists(tempPath);
    if (pdfTempPath) removeIfExists(pdfTempPath);
    if (
      pdfStoredPathPromoted &&
      pdfStoredPath &&
      hasCommittedDocumentAtPath(db, pdfStoredPath) === false
    ) removeIfExists(pdfStoredPath);
    if (
      storedPathPromoted &&
      storedPath &&
      hasCommittedDocumentAtPath(db, storedPath) === false
    ) removeIfExists(storedPath);
    throw error;
  }
}

function enrichInvoiceFromCompany(db: Database, payload: InvoicePayload): InvoicePayload {
  let settings: ReturnType<typeof getCompanySettings>;
  let companyRowExists = false;
  try {
    settings = getCompanySettings(db);
    companyRowExists =
      (db.query("SELECT id FROM companies WHERE id = 1").get() as { id: number } | null) !== null;
  } catch {
    // Older ledgers without the profile columns: leave the payload untouched.
    return payload;
  }
  const companyAddress = companyAddressLine(settings);
  const seller = {
    name: hasText(payload.seller?.name) ? payload.seller!.name : settings.name || undefined,
    address: hasText(payload.seller?.address)
      ? payload.seller!.address
      : companyAddress ?? undefined,
    vatOrCvr: hasText(payload.seller?.vatOrCvr)
      ? payload.seller!.vatOrCvr
      : settings.cvr ?? undefined,
  };
  // The due date only defaults from the company's payment terms when the
  // company profile actually exists — a never-initialised ledger keeps the
  // payload's (possibly absent) due date untouched.
  const dueDate =
    hasText(payload.dueDate)
      ? payload.dueDate
      : companyRowExists && hasText(payload.issueDate) && settings.paymentTermsDays >= 0
        ? addDays(payload.issueDate!, settings.paymentTermsDays)
        : payload.dueDate;
  return { ...payload, seller, ...(dueDate !== undefined ? { dueDate } : {}) };
}

export function validateInvoice(payload: InvoicePayload): InvoiceValidationResult {
  const errors: string[] = [];
  const invoiceType = payload.invoiceType;
  const vatTreatment = payload.vatTreatment ?? "standard";
  const currency = normalizedCurrency(payload);
  const taxProjection = projectVatLines(payload.lines, vatTreatment, payload.totals?.vatRate);
  const appliedRules: string[] = [invoiceType === "simplified" ? RULES.SIMPLIFIED : RULES.FULL, RULES.ARITHMETIC];

  if (!looksLikeIsoDate(payload.issueDate)) errors.push("issueDate must be present in YYYY-MM-DD format");
  if (payload.dueDate !== undefined && !looksLikeIsoDate(payload.dueDate)) errors.push("dueDate must be YYYY-MM-DD when present");
  if (looksLikeIsoDate(payload.issueDate) && looksLikeIsoDate(payload.dueDate) && payload.dueDate < payload.issueDate) {
    errors.push("dueDate cannot be earlier than issueDate");
  }
  appliedRules.push(RULES.DELIVERY_DATE);
  if (payload.deliveryDate !== undefined && !looksLikeIsoDate(payload.deliveryDate)) {
    errors.push("deliveryDate must be YYYY-MM-DD when present");
  }
  if (payload.deliveryPeriodStart !== undefined && !looksLikeIsoDate(payload.deliveryPeriodStart)) {
    errors.push("deliveryPeriodStart must be YYYY-MM-DD when present");
  }
  if (payload.deliveryPeriodEnd !== undefined && !looksLikeIsoDate(payload.deliveryPeriodEnd)) {
    errors.push("deliveryPeriodEnd must be YYYY-MM-DD when present");
  }
  const hasDeliveryPeriodStart = payload.deliveryPeriodStart !== undefined;
  const hasDeliveryPeriodEnd = payload.deliveryPeriodEnd !== undefined;
  if (hasDeliveryPeriodStart !== hasDeliveryPeriodEnd) {
    errors.push("deliveryPeriodStart and deliveryPeriodEnd must be provided together");
  }
  if (payload.deliveryDate !== undefined && (hasDeliveryPeriodStart || hasDeliveryPeriodEnd)) {
    errors.push("use either deliveryDate or deliveryPeriodStart/deliveryPeriodEnd, not both");
  }
  if (looksLikeIsoDate(payload.deliveryPeriodStart) && looksLikeIsoDate(payload.deliveryPeriodEnd) && payload.deliveryPeriodEnd < payload.deliveryPeriodStart) {
    errors.push("deliveryPeriodEnd cannot be earlier than deliveryPeriodStart");
  }
  if (payload.invoiceNumber !== undefined && !hasText(payload.invoiceNumber)) errors.push("invoiceNumber must not be blank when present");
  if (!hasText(payload.seller?.name)) errors.push("seller.name is required");
  if (!hasText(payload.seller?.address)) errors.push("seller.address is required");
  if (!hasText(payload.seller?.vatOrCvr)) errors.push("seller.vatOrCvr is required");
  if (!hasLineDescriptions(payload.lines)) errors.push("lines must contain at least one described good or service");
  if (!hasPositiveNumber(payload.totals?.grossAmount)) errors.push("totals.grossAmount is required");

  if (invoiceType === "full") {
    if (!hasText(payload.buyer?.name)) errors.push("buyer.name is required for full invoices");
    if (!hasText(payload.buyer?.address)) errors.push("buyer.address is required for full invoices");
    if (!hasPositiveNumber(payload.totals?.netAmount)) errors.push("totals.netAmount is required for full invoices");
  }

  const buyerEanNumber = normalizeEanNumber(payload.buyer?.eanNumber);
  const publicRecipient = payload.buyer?.publicRecipient === true || buyerEanNumber !== null;
  if (publicRecipient) {
    appliedRules.push(RULES.PUBLIC_RECIPIENT);
    if (invoiceType !== "full") {
      errors.push("public-recipient invoices must use invoiceType full");
    }
    if (!buyerEanNumber) {
      errors.push("public-recipient invoices must include buyer.eanNumber as 13 digits");
    }
  }

  if (invoiceType === "simplified") {
    if ((payload.totals?.grossAmount ?? Number.POSITIVE_INFINITY) > 3000) {
      errors.push("simplified invoices are only allowed up to DKK 3,000 gross");
    }
    const hasVatAmount = hasPositiveNumber(payload.totals?.vatAmount) && (payload.totals?.vatAmount ?? 0) > 0;
    const has20PctBasis = payload.totals?.vatComputationBasis === "VAT_20_OF_GROSS";
    if (!hasVatAmount && !has20PctBasis) {
      errors.push("simplified invoices must include vatAmount or VAT_20_OF_GROSS computation basis");
    }
  }

  const hasExplicitTaxLines = Boolean(payload.lines?.some((line) => line.taxClassification));
  if (vatTreatment === "standard" && !hasExplicitTaxLines) {
    appliedRules.push(RULES.VAT_SEPARATE_AMOUNT);
    if (!hasPositiveNumber(payload.totals?.vatRate) || (payload.totals?.vatRate ?? 0) <= 0) {
      errors.push("standard VAT invoices must include totals.vatRate");
    }
    if (!hasPositiveNumber(payload.totals?.vatAmount) || (payload.totals?.vatAmount ?? 0) <= 0) {
      errors.push("standard VAT invoices must include totals.vatAmount");
    }
  }

  if (vatTreatment === "domestic_reverse_charge" || vatTreatment === "foreign_reverse_charge") {
    appliedRules.push(RULES.REVERSE_CHARGE, RULES.REVERSE_CHARGE_BASIS);
    if (!hasText(payload.reverseChargeBasis)) {
      errors.push("reverse-charge invoices must include reverseChargeBasis");
    }
    if (payload.totals?.vatRate !== undefined) {
      errors.push("reverse-charge invoices must not include totals.vatRate");
    }
    if (payload.totals?.vatAmount !== undefined) {
      errors.push("reverse-charge invoices must not include totals.vatAmount");
    }
    if (vatTreatment === "foreign_reverse_charge") {
      if (!hasText(payload.buyer?.vatOrCvr)) {
        errors.push("foreign reverse-charge invoices must include buyer.vatOrCvr");
      }
      if (hasText(payload.reverseChargeBasis) && !FOREIGN_REVERSE_CHARGE_BASES.includes(payload.reverseChargeBasis)) {
        errors.push(`reverseChargeBasis ${payload.reverseChargeBasis} is not valid for foreign reverse-charge invoices`);
      }
    }
    if (vatTreatment === "domestic_reverse_charge" && hasText(payload.reverseChargeBasis) && !DOMESTIC_REVERSE_CHARGE_BASES.includes(payload.reverseChargeBasis)) {
      errors.push(`reverseChargeBasis ${payload.reverseChargeBasis} is not valid for domestic reverse-charge invoices`);
    }
  }

  if (Array.isArray(payload.lines)) {
    for (const [index, line] of payload.lines.entries()) {
      const qty = line.quantity;
      const unit = line.unitPriceExVat;
      const total = line.lineTotalExVat;
      if (typeof qty === "number" && typeof unit === "number" && typeof total === "number") {
        const expected = roundDkk(qty * unit);
        if (roundDkk(total) !== expected) {
          errors.push(`lines[${index}].lineTotalExVat must equal quantity * unitPriceExVat (${expected})`);
        }
      }
    }
  }
  errors.push(...taxProjection.errors);

  const lineSum = Array.isArray(payload.lines)
    ? sumDkk(payload.lines.map((line) => line.lineTotalExVat))
    : 0;
  const netAmount = roundDkk(Number(payload.totals?.netAmount ?? 0));
  const vatAmount = roundDkk(Number(payload.totals?.vatAmount ?? 0));
  const grossAmount = roundDkk(Number(payload.totals?.grossAmount ?? 0));
  const fxRateToDkk = roundRate6(Number(payload.totals?.fxRateToDkk ?? 0));
  const netAmountDkk = roundDkk(Number(payload.totals?.netAmountDkk ?? 0));
  const vatAmountDkk = roundDkk(Number(payload.totals?.vatAmountDkk ?? 0));
  const grossAmountDkk = roundDkk(Number(payload.totals?.grossAmountDkk ?? 0));

  if (invoiceType === "full" && Array.isArray(payload.lines) && payload.lines.every((line) => typeof line.lineTotalExVat === "number")) {
    if (netAmount !== lineSum) errors.push(`totals.netAmount must equal sum of lineTotalExVat (${lineSum})`);
  }
  // Standard VAT is calculated per rounded line, not from a document-level
  // multiplication. This makes both mixed rates and øre boundaries auditable:
  // the rounded taxable bases, VAT amounts, and gross must all reconcile to
  // their supplied document totals.
  const hasCompleteLineAmounts = Array.isArray(payload.lines) && payload.lines.every((line) => typeof line.lineTotalExVat === "number");
  if (vatTreatment === "standard" && hasCompleteLineAmounts) {
    // A simplified invoice may omit a document-level net amount. When its
    // line amounts are complete, the line projection is the authoritative
    // net basis; requiring a redundant total here would reject an otherwise
    // fully auditable invoice. A supplied net amount remains strict.
    if (payload.totals?.netAmount !== undefined && netAmount !== taxProjection.netAmount) errors.push(`totals.netAmount must equal rounded VAT line bases (${taxProjection.netAmount})`);
    if (vatAmount !== taxProjection.vatAmount) errors.push(`totals.vatAmount must equal rounded VAT line amounts (${taxProjection.vatAmount})`);
    if (grossAmount !== taxProjection.grossAmount) errors.push(`totals.grossAmount must equal rounded VAT line totals (${taxProjection.grossAmount})`);
  } else if (hasExplicitTaxLines) {
    if (netAmount !== taxProjection.netAmount) errors.push(`totals.netAmount must equal explicit VAT line bases (${taxProjection.netAmount})`);
    if (vatAmount !== taxProjection.vatAmount) errors.push(`totals.vatAmount must equal explicit VAT line amounts (${taxProjection.vatAmount})`);
    if (grossAmount !== taxProjection.grossAmount) errors.push(`totals.grossAmount must equal explicit VAT line totals (${taxProjection.grossAmount})`);
  }

  // Reverse-charge documents carry zero seller VAT, but their net and gross
  // still have to reconcile to the same line-level evidence as a standard
  // invoice. In particular, old payloads without explicit classifications
  // default to reverse_charge lines; do not let that legacy shape bypass the
  // arithmetic trust boundary.
  if (
    (vatTreatment === "domestic_reverse_charge" || vatTreatment === "foreign_reverse_charge") &&
    hasCompleteLineAmounts
  ) {
    if (netAmount !== taxProjection.netAmount) errors.push(`totals.netAmount must equal rounded reverse-charge line bases (${taxProjection.netAmount})`);
    if (taxProjection.vatAmount !== 0) errors.push("reverse-charge invoice lines must not include VAT");
    if (grossAmount !== taxProjection.grossAmount) errors.push(`totals.grossAmount must equal rounded reverse-charge line totals (${taxProjection.grossAmount})`);
  }

  if (vatTreatment === "standard" && !hasExplicitTaxLines && (invoiceType === "full" || payload.totals?.netAmount !== undefined)) {
    const expectedGross = roundDkk(netAmount + vatAmount);
    if (grossAmount !== expectedGross) {
      errors.push(`totals.grossAmount must equal totals.netAmount + totals.vatAmount (${expectedGross})`);
    }
  }

  // A simplified standard-VAT invoice normally omits totals.netAmount, so the
  // gross = net + vat cross-check above is skipped and an internally
  // impossible vatAmount (e.g. 999 on a 1.000 kr gross) would otherwise be
  // accepted and booked verbatim as output VAT. When an explicit vatAmount is
  // given, derive the implied net (gross − vat) and require the VAT to be
  // consistent with the declared rate, so a nonsensical figure is rejected
  // before it ever reaches the ledger. (A basis-only simplified invoice with
  // VAT_20_OF_GROSS and no explicit vatAmount computes its VAT downstream and
  // cannot be inconsistent, so it is left untouched.)
  if (
    vatTreatment === "standard" &&
    invoiceType === "simplified" &&
    payload.totals?.netAmount === undefined &&
    hasPositiveNumber(payload.totals?.vatAmount)
  ) {
    const vatRate = roundRate6(Number(payload.totals?.vatRate ?? 0));
    if (!(grossAmount > vatAmount)) {
      errors.push("totals.vatAmount must be less than totals.grossAmount");
    } else if (vatRate > 0) {
      // The VAT CONTAINED in a gross-inclusive amount is `gross * rate/(1+rate)`
      // (= 20% of gross at the 25% rate — exactly the VAT_20_OF_GROSS basis a
      // forenklet faktura uses), NOT `(gross − vat) * rate`. The net-first
      // round-trip double-rounds and wrongly rejects ~20% of legitimate
      // simplified invoices at the øre boundary (e.g. gross 100,07 → correct
      // VAT 20,01). Accept any vatAmount within one øre of the canonical
      // figure; a nonsensical VAT (e.g. 999 on a 1.000 gross) is still far
      // outside the tolerance and rejected.
      const expectedVat = roundDkk((grossAmount * vatRate) / (1 + vatRate));
      if (roundDkk(Math.abs(vatAmount - expectedVat)) > 0.01) {
        errors.push(
          `totals.vatAmount must be the VAT contained in totals.grossAmount at totals.vatRate (≈ ${expectedVat})`,
        );
      }
    }
  }

  if ((vatTreatment === "domestic_reverse_charge" || vatTreatment === "foreign_reverse_charge") && payload.totals?.netAmount !== undefined) {
    if (grossAmount !== netAmount) {
      errors.push(`reverse-charge invoices must have totals.grossAmount equal totals.netAmount (${netAmount})`);
    }
  }

  if (currency.length !== 3) {
    errors.push("currency must be a 3-letter ISO code when present");
  }

  if (currency !== "DKK") {
    if (!(fxRateToDkk > 0)) errors.push("non-DKK invoices must include totals.fxRateToDkk");
    if (!hasPositiveNumber(payload.totals?.netAmountDkk)) errors.push("non-DKK invoices must include totals.netAmountDkk");
    if (vatTreatment === "standard" && !hasPositiveNumber(payload.totals?.vatAmountDkk)) errors.push("non-DKK invoices must include totals.vatAmountDkk for standard VAT");
    if (!hasPositiveNumber(payload.totals?.grossAmountDkk)) errors.push("non-DKK invoices must include totals.grossAmountDkk");

    if (fxRateToDkk > 0) {
      if (payload.totals?.netAmountDkk !== undefined) {
        const expectedNetDkk = roundDkk(netAmount * fxRateToDkk);
        if (netAmountDkk !== expectedNetDkk) errors.push(`totals.netAmountDkk must equal totals.netAmount * totals.fxRateToDkk (${expectedNetDkk})`);
      }
      if (payload.totals?.vatAmountDkk !== undefined) {
        const expectedVatDkk = roundDkk(vatAmount * fxRateToDkk);
        if (vatAmountDkk !== expectedVatDkk) errors.push(`totals.vatAmountDkk must equal totals.vatAmount * totals.fxRateToDkk (${expectedVatDkk})`);
      }
      if (payload.totals?.grossAmountDkk !== undefined) {
        const expectedGrossDkk = roundDkk(grossAmount * fxRateToDkk);
        if (grossAmountDkk !== expectedGrossDkk) errors.push(`totals.grossAmountDkk must equal totals.grossAmount * totals.fxRateToDkk (${expectedGrossDkk})`);
      }
    }

    if (vatTreatment === "standard" && (payload.totals?.netAmountDkk !== undefined || payload.totals?.vatAmountDkk !== undefined || payload.totals?.grossAmountDkk !== undefined)) {
      const expectedGrossDkk = roundDkk(netAmountDkk + vatAmountDkk);
      if (grossAmountDkk !== expectedGrossDkk) {
        errors.push(`totals.grossAmountDkk must equal totals.netAmountDkk + totals.vatAmountDkk (${expectedGrossDkk})`);
      }
    }

    if ((vatTreatment === "domestic_reverse_charge" || vatTreatment === "foreign_reverse_charge") && payload.totals?.netAmountDkk !== undefined) {
      if (grossAmountDkk !== netAmountDkk) {
        errors.push(`reverse-charge invoices must have totals.grossAmountDkk equal totals.netAmountDkk (${netAmountDkk})`);
      }
    }
  }

  return {
    ok: errors.length === 0,
    invoiceType,
    vatTreatment,
    appliedRules,
    errors,
  };
}

const RULES = {
  FULL: "DK-INVOICE-FULL-001",
  SIMPLIFIED: "DK-INVOICE-SIMPLIFIED-001",
  REVERSE_CHARGE: "DK-INVOICE-REVERSE-CHARGE-001",
  REVERSE_CHARGE_BASIS: "DK-INVOICE-REVERSE-CHARGE-BASIS-001",
  DELIVERY_DATE: "DK-INVOICE-DELIVERY-DATE-001",
  ARITHMETIC: "DK-INVOICE-ARITHMETIC-001",
  VAT_SEPARATE_AMOUNT: "DK-VAT-SEPARATE-AMOUNT-001",
  PUBLIC_RECIPIENT: "DK-INVOICE-PUBLIC-RECIPIENT-001",
} as const;

const FOREIGN_REVERSE_CHARGE_BASES: ReverseChargeBasis[] = [
  "DK_MOMSLOVEN_§46_STK_1_NR_3",
  "EU_MOMSDIREKTIV_ART_196",
  "EU_MOMSDIREKTIV_ART_199",
];

const DOMESTIC_REVERSE_CHARGE_BASES: ReverseChargeBasis[] = [
  "DK_MOMSLOVEN_§46_STK_1_NR_6",
  "DK_MOMSLOVEN_§46_STK_1_NR_7",
];

export function resolveCompanyPaymentDetails(
  db: Database,
  currency = "DKK",
): CompanyPaymentDetails | undefined {
  let rows: Array<{
    bank_name: string | null;
    registration_no: string | null;
    account_no: string | null;
    iban: string | null;
    currency: string | null;
  }> = [];
  try {
    rows = db
      .query(
        `SELECT bank_name, registration_no, account_no, iban, currency
           FROM bank_accounts
          WHERE active = 1
          ORDER BY id ASC`,
      )
      .all() as typeof rows;
  } catch {
    // The table may not exist in very old ledgers; payment block is optional.
    return undefined;
  }
  if (rows.length === 0) return undefined;
  const wanted = currency.trim().toUpperCase();
  const match =
    rows.find((row) => (row.currency ?? "").trim().toUpperCase() === wanted) ?? rows[0];
  const details: CompanyPaymentDetails = {
    bankName: match.bank_name?.trim() || null,
    registrationNo: match.registration_no?.trim() || null,
    accountNo: match.account_no?.trim() || null,
    iban: match.iban?.trim() || null,
  };
  if (!details.bankName && !details.registrationNo && !details.accountNo && !details.iban) {
    return undefined;
  }
  return details;
}

export function requireCachedViesValidation(db: Database, vatOrCvr: string | null | undefined, label: string, asOfIso?: string): ValidateVatResult {
  const parsed = normalizeEuVatNumber(vatOrCvr);
  if (!parsed) {
    return { ok: false, appliedRules: [RULE_ID], errors: [`${label} must be a plausible EU VAT number`] };
  }
  const cached = lookupCachedViesValidation(db, parsed.normalized);
  if (!cached) {
    return {
      ok: false,
      appliedRules: [RULE_ID],
      errors: [
        `VIES lookup not yet performed for ${label} (${parsed.normalized}) — ` +
          `validate the VAT number against VIES first ` +
          `(CLI: \`customer validate-vat\`; MCP: \`customer_validate_vat\`).`,
      ],
    };
  }
  if (!cached.valid) {
    return { ok: false, appliedRules: [RULE_ID], errors: [`${label} ${parsed.normalized} is not a valid EU VAT number per cached VIES result from ${cached.validatedAt}`] };
  }
  if (isExpired(cached.expiresAt, asOfIso)) {
    return { ok: false, appliedRules: [RULE_ID], errors: [`VIES validation for ${label} ${parsed.normalized} expired at ${cached.expiresAt} — re-run validation`] };
  }
  return { ok: true, validation: cached, appliedRules: [RULE_ID], errors: [] };
}

function validateManualInvoiceNumberScope(db: Database, issueDate: string, invoiceNumber: string) {
  const { scope } = invoiceSequenceState(db, issueDate);
  const match = MANUAL_INVOICE_NUMBER_RE.exec(invoiceNumber);
  if (!match) {
    return `manual invoiceNumber ${invoiceNumber} must be of the form <scope>-<number>`;
  }
  if (match[1] !== scope) {
    return `manual invoiceNumber ${invoiceNumber} does not match current fiscal scope ${scope}`;
  }
  return null;
}

function closedPeriodIssueWarnings(db: Database, issueDate: string | undefined): string[] {
  if (!issueDate) return [];
  return validateJournalTransactionDate(db, issueDate)
    .filter((message) => message.includes("period"))
    .map((message) => `Fakturadato ${issueDate} ligger i en lukket periode: ${message}. Fakturaen er udstedt, men bogføringen vil blive afvist af periodelåsen.`);
}

function reserveManualInvoiceNumber(db: Database, issueDate: string, invoiceNumber: string) {
  const { scope, currentFloor, sequenceScope } = invoiceSequenceState(db, issueDate);
  const match = MANUAL_INVOICE_NUMBER_RE.exec(invoiceNumber);
  if (!match || match[1] !== scope) {
    return { ok: false as const, error: `manual invoiceNumber ${invoiceNumber} must be of the form <scope>-<number>` };
  }
  const requestedValue = Number(match[2]);
  const reserved = reserveSequenceValue(db, "issued_invoice", sequenceScope, requestedValue, currentFloor);
  if (!reserved.ok) {
    return {
      ok: false as const,
      error: `manual invoiceNumber ${invoiceNumber} exceeds næste fortløbende nummer ${canonicalInvoiceNumber(scope, reserved.expectedValue)}`,
    };
  }
  // #251: store the canonical four-digit form, never the verbatim manual
  // string, so the issued series stays one consistent format regardless of how
  // the number was supplied.
  return { ok: true as const, invoiceNumber: canonicalInvoiceNumber(scope, requestedValue) };
}

export function asInvoiceNumber(value: string): InvoiceNumber {
  return value as InvoiceNumber;
}

function nextIssuedInvoiceNumber(db: Database, issueDate: string) {
  const { scope, currentFloor, sequenceScope } = invoiceSequenceState(db, issueDate);
  const nextValue = nextSequenceValue(db, "issued_invoice", sequenceScope, currentFloor);
  return canonicalInvoiceNumber(scope, nextValue);
}

function sha256(text: string) {
  return createHash("sha256").update(text).digest("hex");
}

export function buildIssuedInvoicePdf(payload: IssuedInvoicePdfPayload) {
  const pages = layoutInvoice(payload);
  const issueDate = compact(payload.issueDate) ?? "1970-01-01";
  const pdfDate = `D:${issueDate.replace(/-/g, "")}000000Z`;
  const producer = "Rentemester deterministic invoice renderer";
  const title = `Faktura ${compact(payload.invoiceNumber) ?? ""}`.trim();

  // Object layout: 1 Catalog, 2 Pages, then per page a Page + Contents object,
  // then the two Font objects (F1, F2) and the Info object.
  const pageCount = pages.length;
  const pageObjectNos = pages.map((_, i) => 3 + i * 2);
  const fontRegularNo = 3 + pageCount * 2;
  const fontBoldNo = fontRegularNo + 1;
  const infoObjectNo = fontBoldNo + 1;

  const objects: string[] = [
    "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n",
    `2 0 obj\n<< /Type /Pages /Count ${pageCount} /Kids [${pageObjectNos.map((n) => `${n} 0 R`).join(" ")}] >>\nendobj\n`,
  ];
  pages.forEach((page, i) => {
    const pageNo = pageObjectNos[i];
    const contentNo = pageNo + 1;
    // ASCII separator (#225): a non-ASCII bullet/middle-dot in the footer
    // rendered as a broken glyph in some PDF viewers ("Faktura 2026-0001 <?>
    // Side 1"). A plain hyphen is safe in every viewer and font.
    const footer = `${title} - Side ${i + 1} af ${pageCount}`;
    const content = pageContentStream(page, footer);
    objects.push(
      `${pageNo} 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_WIDTH} ${PAGE_HEIGHT}] ` +
        `/Resources << /Font << /F1 ${fontRegularNo} 0 R /F2 ${fontBoldNo} 0 R >> >> /Contents ${contentNo} 0 R >>\nendobj\n`,
    );
    objects.push(
      `${contentNo} 0 obj\n<< /Length ${Buffer.byteLength(content, "binary")} >>\nstream\n${content}endstream\nendobj\n`,
    );
  });
  objects.push(
    `${fontRegularNo} 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>\nendobj\n`,
  );
  objects.push(
    `${fontBoldNo} 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>\nendobj\n`,
  );
  objects.push(
    `${infoObjectNo} 0 obj\n<< /Producer (${escapePdfText(producer)}) /Title (${escapePdfText(title)}) ` +
      `/CreationDate (${pdfDate}) /ModDate (${pdfDate}) >>\nendobj\n`,
  );

  let pdf = "%PDF-1.4\n%\xE2\xE3\xCF\xD3\n";
  const offsets: number[] = [0];
  for (const object of objects) {
    offsets.push(Buffer.byteLength(pdf, "binary"));
    pdf += object;
  }
  const xrefOffset = Buffer.byteLength(pdf, "binary");
  pdf += `xref\n0 ${objects.length + 1}\n`;
  pdf += "0000000000 65535 f \n";
  for (let i = 1; i < offsets.length; i += 1) {
    pdf += `${String(offsets[i]).padStart(10, "0")} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R /Info ${infoObjectNo} 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`;
  return Buffer.from(pdf, "binary");
}

export function writeTempFileFor(finalPath: string, content: string | Uint8Array) {
  // Retry on the (vanishingly rare) random-name collision; never follow or
  // clobber an existing entry.
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const tempPath = randomTempPath(finalPath);
    let fd: number;
    try {
      fd = openSync(tempPath, EXCL_CREATE_FLAGS, 0o600);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "EEXIST") continue;
      throw error;
    }
    try {
      writeAllSync(fd, content);
      // KODE-7: flush the file's data+metadata to stable storage BEFORE close,
      // so a power loss after the subsequent rename cannot resurrect a
      // zero-length or partially-written file. Without this, write()+rename()
      // only orders the operations in the page cache — the bytes may still be
      // in flight when the crash hits, leaving an empty manifest/signature/tar.
      fsyncSync(fd);
    } finally {
      closeSync(fd);
    }
    return tempPath;
  }
  throw new Error(`failed to create exclusive temp file for ${finalPath}`);
}

function deliveryDescription(payload: InvoicePayload) {
  if (payload.deliveryDate) return `Delivery date ${payload.deliveryDate}`;
  if (payload.deliveryPeriodStart && payload.deliveryPeriodEnd) {
    return `Delivery period ${payload.deliveryPeriodStart}..${payload.deliveryPeriodEnd}`;
  }
  return payload.lines?.map((l) => l.description).filter(Boolean).join('; ') ?? null;
}

export function retainUntilForDate(db: Database, dateText: string) {
  if (!isValidIsoDate(dateText)) throw new Error(`invalid ISO date: ${dateText}`);
  const basis = dateText.trim();
  const company = getCompanySettings(db);
  const startMonth = company.fiscalYearStartMonth;
  const year = Number(basis.slice(0, 4));
  const month = Number(basis.slice(5, 7));
  const targetYear = year + (startMonth !== 1 && month >= startMonth ? 1 : 0) + 5;
  if (targetYear > 9999) throw new Error("retention deadline exceeds YYYY-MM-DD range");
  const endMonth = startMonth === 1 ? 12 : startMonth - 1;
  // Compute the last day in the TARGET year: adding five to a leap-day string
  // can otherwise create an impossible deadline. setUTCFullYear avoids the
  // Date.UTC remapping of years 0–99 to 1900–1999.
  const end = new Date(0);
  end.setUTCFullYear(targetYear, endMonth, 0);
  return end.toISOString().slice(0, 10);
}

export function strengthenGdprErasureAliasesForIdentity(
  db: Database,
  identity: { name?: string | null; cvr?: string | null },
): void {
  const subject = resolveSubject(identity);
  if (!subject.name || !subject.cvr) return;
  const nameReference = subjectAuditReference(`name:${subject.name}`);
  const priorNameErasure = db
    .query(
      `SELECT 1
         FROM gdpr_erasures
        WHERE subject_key IN (?, ?)
        LIMIT 1`,
    )
    .get(nameReference, subject.name);
  if (!priorNameErasure) return;

  const scopeResolution = resolveSubjectScope(db, subject);
  if (!scopeResolution.ok) return;
  const erasures = loadErasures(
    db,
    // The name may already have become ambiguous. It is safe to inspect its
    // old hash here because strengthenErasureAliases still requires exact CVR
    // evidence on each source row before creating a stable binding.
    [...scopeResolution.scope.erasureSubjectKeys, nameReference],
  );
  const rows = collectSourceRows(db, scopeResolution.scope);
  strengthenErasureAliases(db, scopeResolution.scope, rows, erasures);
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

export function promoteTempFileExclusive(tempPath: string, finalPath: string) {
  linkSync(tempPath, finalPath);
  removeIfExists(tempPath);
  fsyncDir(finalPath);
}

export function asDocumentId(value: number): DocumentId {
  return value as DocumentId;
}

export function removeIfExists(path: string) {
  try {
    unlinkSync(path);
  } catch {
    // best effort cleanup
  }
}

function hasCommittedDocumentAtPath(db: Database, storedPath: string): boolean | null {
  try {
    return db.query("SELECT 1 AS present FROM documents WHERE stored_path = ? LIMIT 1").get(storedPath) != null;
  } catch {
    // An ambiguous COMMIT/I/O failure must retain a possibly authoritative
    // legal artifact. A recoverable orphan is safer than a committed row whose
    // file was deleted merely because database state could not be re-read.
    return null;
  }
}

