domainFailurePredicatesAndEnvelopes.source:
export function computeInvoiceAmounts(
  lines: InvoiceLineInput[],
  vatRatePercent: number,
): ComputeInvoiceAmountsResult {
  const errors: string[] = [];
  if (!Array.isArray(lines) || lines.length === 0) {
    errors.push("at least one invoice line is required");
  }
  if (!Number.isFinite(vatRatePercent) || vatRatePercent < 0) {
    errors.push("vatRatePercent must be a number greater than or equal to 0");
  }

  const computed: ComputedInvoiceLine[] = [];
  (lines ?? []).forEach((line, index) => {
    const description = typeof line.description === "string" ? line.description.trim() : "";
    if (description.length === 0) {
      errors.push(`lines[${index}].description must not be blank`);
    }
    if (!Number.isFinite(line.quantity) || line.quantity <= 0) {
      errors.push(`lines[${index}].quantity must be a number greater than 0`);
    }
    if (!Number.isFinite(line.unitPriceExVat) || line.unitPriceExVat < 0) {
      errors.push(`lines[${index}].unitPriceExVat must be a number greater than or equal to 0`);
    }
    computed.push({
      description,
      quantity: line.quantity,
      unitPriceExVat: line.unitPriceExVat,
      lineTotalExVat: roundDkk(Number(line.quantity) * Number(line.unitPriceExVat)),
    });
  });

  if (errors.length > 0) return { ok: false, lines: computed, errors };

  const netAmount = roundDkk(computed.reduce((sum, line) => sum + line.lineTotalExVat, 0));
  const vatRate = roundRate6(vatRatePercent / 100);
  const vatAmount = roundDkk(netAmount * vatRate);
  const grossAmount = roundDkk(netAmount + vatAmount);

  return {
    ok: true,
    lines: computed,
    totals: { vatRate, netAmount, vatAmount, grossAmount },
    errors: [],
  };
}

export function roundDkk(value: number) {
  return Number.isFinite(value) ? fromScaledInt(scaledInt(value, 2), 2) : NaN;
}

export function roundRate6(value: number) {
  return Number.isFinite(value) ? fromScaledInt(scaledInt(value, 6), 6) : NaN;
}

export function resolveInvoiceMasterData(
  db: Database,
  payload: InvoicePayload,
  options: { customerId?: number | null },
): { ok: true; payload: InvoicePayload; notes?: string[] } | { ok: false; errors: string[] } {
  if (!options.customerId) return { ok: true, payload };
  const customer = getCustomerById(db, options.customerId);
  if (!customer || customer.archived) return { ok: false, errors: [`customer ${options.customerId} does not exist`] };

  // EJER-3: only an EXPLICIT kundefrist sets the due date here. A customer
  // stored with NULL has no own frist — the due date is left unset so
  // issueInvoice's enrichInvoiceFromCompany fills it from the company
  // profile's payment terms (the owner's own standard).
  const explicitDueDate = trimToNull(payload.dueDate);
  const customerTerms = customer.payment_terms_days;
  const dueDate =
    explicitDueDate ??
    (trimToNull(payload.issueDate) && customerTerms != null && customerTerms > 0
      ? addDays(payload.issueDate!, customerTerms)
      : undefined);

  // EJER-3: when the kundekort's explicit frist (not the company standard)
  // decides the due date AND deviates from the profile, say so out loud —
  // the owner must never discover a silently different betalingsfrist.
  const notes: string[] = [];
  if (!explicitDueDate && dueDate !== undefined && customerTerms != null) {
    const companyTerms = companyDefaultPaymentTermsDays(db);
    if (companyTerms != null && companyTerms !== customerTerms) {
      notes.push(
        `Betalingsfrist ${customerTerms} dage fra kundekortet — virksomhedens standard er ${companyTerms} dage.`,
      );
    }
  }

  return {
    ok: true,
    payload: {
      ...payload,
      buyer: {
        name: trimToNull(payload.buyer?.name) ?? customer.name,
        address: trimToNull(payload.buyer?.address) ?? customer.address ?? undefined,
        vatOrCvr: trimToNull(payload.buyer?.vatOrCvr) ?? customer.vat_or_cvr ?? undefined,
        eanNumber: normalizeEanNumber(payload.buyer?.eanNumber) ?? customer.ean_number ?? undefined,
        publicRecipient: payload.buyer?.publicRecipient ?? Boolean(normalizeEanNumber(payload.buyer?.eanNumber) ?? customer.ean_number),
      },
      currency: trimToNull(payload.currency) ?? customer.default_currency,
      dueDate,
    },
    ...(notes.length > 0 ? { notes } : {}),
  };
}

export function getCustomerById(db: Database, id: number) {
  return db.query(
    `SELECT id, name, address, vat_or_cvr, email, phone, website, ean_number, payment_terms_days, default_currency, notes, archived, created_at
     FROM customers WHERE id = ? LIMIT 1`
  ).get(id) as {
    id: number; name: string; address: string | null; vat_or_cvr: string | null; email: string | null; phone: string | null; website: string | null; ean_number: string | null; payment_terms_days: number | null; default_currency: string; notes: string | null; archived: number; created_at: string;
  } | null;
}

export function trimToNull(value: unknown) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

export function addDays(isoDate: string, days: number): string {
  const date = new Date(`${isoDate}T00:00:00.000Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

function companyDefaultPaymentTermsDays(db: Database): number | null {
  try {
    const row = db.query(`SELECT payment_terms_days FROM companies ORDER BY id ASC LIMIT 1`).get() as
      | { payment_terms_days: number | null }
      | null;
    if (!row) return null;
    const days = Number(row.payment_terms_days);
    return Number.isInteger(days) && days >= 0 && days <= 365 ? days : null;
  } catch {
    return null;
  }
}

export function normalizeEanNumber(value: unknown) {
  const trimmed = trimToNull(value);
  if (!trimmed) return null;
  const digitsOnly = trimmed.replace(/\s+/g, "");
  return /^\d{13}$/.test(digitsOnly) ? digitsOnly : null;
}

export function issueInvoice(
  db: Database,
  companyRoot: string,
  rawPayload: InvoicePayload,
  actor: ResolveActorInput = {},
): IssueInvoiceResult {
  // #221: fill the seller identity + due date from the stored company profile
  // before validation, so the owner never re-types their own master data.
  const payload = enrichInvoiceFromCompany(db, rawPayload);
  const validation = validateInvoice(payload);
  const appliedRules = [...new Set([...(validation.appliedRules ?? []), RULE_ID, LOCK_RULE_ID])];
  if (!validation.ok) return { ok: false, appliedRules, errors: validation.errors };

  // #221: resolve the company's payment details once, so the customer-facing
  // PDF built at issue time always carries the BETALING block (where to pay).
  const invoiceCurrency = (payload.currency ?? "DKK").trim().toUpperCase();
  const paymentDetails = resolveCompanyPaymentDetails(db, invoiceCurrency);

  let viesValidation: ReturnType<typeof requireCachedViesValidation>["validation"] | undefined;
  if (payload.vatTreatment === "foreign_reverse_charge") {
    const viesCheck = requireCachedViesValidation(db, payload.buyer?.vatOrCvr, "buyer.vatOrCvr");
    if (!viesCheck.ok) return { ok: false, appliedRules: [...new Set([...appliedRules, ...viesCheck.appliedRules])], errors: viesCheck.errors };
    viesValidation = viesCheck.validation;
  }

  const explicitInvoiceNumber = payload.invoiceNumber?.trim();
  if (explicitInvoiceNumber) {
    const scopeError = validateManualInvoiceNumberScope(db, payload.issueDate!, explicitInvoiceNumber);
    if (scopeError) return { ok: false, appliedRules, errors: [scopeError] };
  }
  const paths = companyPaths(companyRoot);
  mkdirSync(paths.invoicesIssued, { recursive: true });

  let tempPath: string | undefined;
  let storedPath: string | undefined;
  let pdfTempPath: string | undefined;
  let pdfStoredPath: string | undefined;
  let storedPathPromoted = false;
  let pdfStoredPathPromoted = false;

  // Calculate advisory-only output before any irreversible publication. A
  // warning lookup failure must never make a committed legal document look as
  // though issuance failed to its caller.
  const warnings = closedPeriodIssueWarnings(db, payload.issueDate);

  try {
    const result = db.transaction(() => {
      let invoiceNumber: InvoiceNumber;
      if (explicitInvoiceNumber !== undefined) {
        const reserved = reserveManualInvoiceNumber(db, payload.issueDate!, explicitInvoiceNumber);
        if (!reserved.ok) return { ok: false as const, error: reserved.error };
        // #251: use the canonicalised four-digit number, not the verbatim
        // input, so the persisted snapshot, PDF and documents row all carry the
        // same consistent format as an auto-numbered invoice.
        invoiceNumber = asInvoiceNumber(reserved.invoiceNumber);
      } else {
        invoiceNumber = nextIssuedInvoiceNumber(db, payload.issueDate!);
      }

      const issuedAt = new Date().toISOString();
      const issuedPayload = {
        ...payload,
        invoiceNumber,
        issuedAt,
        status: "issued",
        ...(viesValidation ? { viesValidation } : {}),
        // #221: persist the resolved payment details into the snapshot so the
        // at-issue PDF — and any later `invoice render` — show where to pay.
        ...(paymentDetails ? { payment: paymentDetails } : {}),
      };
      const serialized = JSON.stringify(issuedPayload, null, 2);
      const hash = sha256(serialized);
      const pdfBytes = buildIssuedInvoicePdf(issuedPayload);
      const pdfHash = createHash("sha256").update(pdfBytes).digest("hex");
      storedPath = join(paths.invoicesIssued, `${invoiceNumber}.json`);
      pdfStoredPath = join(paths.invoicesIssued, `${invoiceNumber}.pdf`);
      tempPath = writeTempFileFor(storedPath, serialized);
      pdfTempPath = writeTempFileFor(pdfStoredPath, pdfBytes);

      const grossAmount = payload.totals?.grossAmount ?? null;
      const vatAmount = payload.totals?.vatAmount ?? null;
      const inserted = db.query(
      `INSERT INTO documents (
        document_no, source, original_filename, stored_path, mime_type, sha256_hash,
        supplier_name, invoice_no, invoice_date, amount_inc_vat, currency, status,
        document_type, delivery_description, sender_name, sender_address, sender_vat_cvr,
        recipient_name, recipient_address, recipient_vat_cvr, vat_amount, payment_details, exemption_code, payload_json, retain_until
      ) VALUES (?, 'rentemester', ?, ?, 'application/json', ?, ?, ?, ?, ?, ?, 'issued', 'issued_invoice', ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?)
      RETURNING id`
    ).get(
      invoiceNumber,
      `${invoiceNumber}.json`,
      storedPath,
      hash,
      payload.seller?.name ?? null,
      invoiceNumber,
      payload.issueDate ?? null,
      grossAmount,
      invoiceCurrency,
      deliveryDescription(payload),
      payload.seller?.name ?? null,
      payload.seller?.address ?? null,
      payload.seller?.vatOrCvr ?? null,
      payload.buyer?.name ?? null,
      payload.buyer?.address ?? null,
      payload.buyer?.vatOrCvr ?? null,
      vatAmount,
      payload.reverseChargeBasis ?? null,
      serialized,
      retainUntilForDate(db, payload.issueDate!),
    ) as { id: number };

      const pdfInserted = db.query(
      `INSERT INTO documents (
        document_no, source, original_filename, stored_path, mime_type, sha256_hash,
        supplier_name, invoice_no, invoice_date, amount_inc_vat, currency, status,
        document_type, sender_name, sender_address, sender_vat_cvr,
        recipient_name, recipient_address, recipient_vat_cvr, vat_amount, payload_json, retain_until
      ) VALUES (?, 'rentemester', ?, ?, 'application/pdf', ?, ?, ?, ?, ?, ?, 'issued', 'issued_invoice_pdf', ?, ?, ?, ?, ?, ?, ?, ?, ?)
      RETURNING id`
    ).get(
      `${invoiceNumber}-pdf`,
      `${invoiceNumber}.pdf`,
      pdfStoredPath,
      pdfHash,
      payload.seller?.name ?? null,
      invoiceNumber,
      payload.issueDate ?? null,
      grossAmount,
      invoiceCurrency,
      payload.seller?.name ?? null,
      payload.seller?.address ?? null,
      payload.seller?.vatOrCvr ?? null,
      payload.buyer?.name ?? null,
      payload.buyer?.address ?? null,
      payload.buyer?.vatOrCvr ?? null,
      vatAmount,
      serialized,
      retainUntilForDate(db, payload.issueDate!),
      ) as { id: number };

      strengthenGdprErasureAliasesForIdentity(db, {
        name: payload.seller?.name,
        cvr: payload.seller?.vatOrCvr,
      });
      strengthenGdprErasureAliasesForIdentity(db, {
        name: payload.buyer?.name,
        cvr: payload.buyer?.vatOrCvr,
      });

      insertAuditLog(db, {
        eventType: "invoice_issue",
        entityType: "document",
        entityId: inserted.id,
        message: `Issued invoice ${invoiceNumber}`,
        createdBy: actor.createdBy,
        createdByProgram: actor.createdByProgram,
      });
      insertAuditLog(db, {
        eventType: "invoice_render_pdf",
        entityType: "document",
        entityId: pdfInserted.id,
        message: `Rendered invoice PDF ${invoiceNumber}`,
        createdBy: actor.createdBy,
        createdByProgram: actor.createdByProgram,
      });

      // Publish both immutable artifacts while the database transaction is
      // still open. A publication failure throws and rolls every document,
      // audit, and sequence row back. If COMMIT itself then fails, the outer
      // catch removes the already-published paths.
      promoteTempFileExclusive(tempPath!, storedPath!);
      storedPathPromoted = true;
      promoteTempFileExclusive(pdfTempPath!, pdfStoredPath!);
      pdfStoredPathPromoted = true;

      return { ok: true as const, documentId: asDocumentId(inserted.id), invoiceNumber, sha256: hash, pdfDocumentId: asDocumentId(pdfInserted.id), pdfSha256: pdfHash };
    }).immediate();

    if (!result.ok) return { ok: false, appliedRules, errors: [result.error] };
    return {
      ok: true,
      documentId: result.documentId,
      invoiceNumber: result.invoiceNumber,
      storedPath,
      sha256: result.sha256,
      pdfDocumentId: result.pdfDocumentId,
      pdfStoredPath,
      pdfSha256: result.pdfSha256,
      appliedRules,
      errors: [],
      ...(warnings.length > 0 ? { warnings } : {}),
    };
  } catch (error) {
    if (tempPath) removeIfExists(tempPath);
    if (pdfTempPath) removeIfExists(pdfTempPath);
    if (
      pdfStoredPathPromoted &&
      pdfStoredPath &&
      hasCommittedDocumentAtPath(db, pdfStoredPath) === false
    ) removeIfExists(pdfStoredPath);
    if (
      storedPathPromoted &&
      storedPath &&
      hasCommittedDocumentAtPath(db, storedPath) === false
    ) removeIfExists(storedPath);
    throw error;
  }
}

function enrichInvoiceFromCompany(db: Database, payload: InvoicePayload): InvoicePayload {
  let settings: ReturnType<typeof getCompanySettings>;
  let companyRowExists = false;
  try {
    settings = getCompanySettings(db);
    companyRowExists =
      (db.query("SELECT id FROM companies WHERE id = 1").get() as { id: number } | null) !== null;
  } catch {
    // Older ledgers without the profile columns: leave the payload untouched.
    return payload;
  }
  const companyAddress = companyAddressLine(settings);
  const seller = {
    name: hasText(payload.seller?.name) ? payload.seller!.name : settings.name || undefined,
    address: hasText(payload.seller?.address)
      ? payload.seller!.address
      : companyAddress ?? undefined,
    vatOrCvr: hasText(payload.seller?.vatOrCvr)
      ? payload.seller!.vatOrCvr
      : settings.cvr ?? undefined,
  };
  // The due date only defaults from the company's payment terms when the
  // company profile actually exists — a never-initialised ledger keeps the
  // payload's (possibly absent) due date untouched.
  const dueDate =
    hasText(payload.dueDate)
      ? payload.dueDate
      : companyRowExists && hasText(payload.issueDate) && settings.paymentTermsDays >= 0
        ? addDays(payload.issueDate!, settings.paymentTermsDays)
        : payload.dueDate;
  return { ...payload, seller, ...(dueDate !== undefined ? { dueDate } : {}) };
}

export function validateInvoice(payload: InvoicePayload): InvoiceValidationResult {
  const errors: string[] = [];
  const invoiceType = payload.invoiceType;
  const vatTreatment = payload.vatTreatment ?? "standard";
  const currency = normalizedCurrency(payload);
  const taxProjection = projectVatLines(payload.lines, vatTreatment, payload.totals?.vatRate);
  const appliedRules: string[] = [invoiceType === "simplified" ? RULES.SIMPLIFIED : RULES.FULL, RULES.ARITHMETIC];

  if (!looksLikeIsoDate(payload.issueDate)) errors.push("issueDate must be present in YYYY-MM-DD format");
  if (payload.dueDate !== undefined && !looksLikeIsoDate(payload.dueDate)) errors.push("dueDate must be YYYY-MM-DD when present");
  if (looksLikeIsoDate(payload.issueDate) && looksLikeIsoDate(payload.dueDate) && payload.dueDate < payload.issueDate) {
    errors.push("dueDate cannot be earlier than issueDate");
  }
  appliedRules.push(RULES.DELIVERY_DATE);
  if (payload.deliveryDate !== undefined && !looksLikeIsoDate(payload.deliveryDate)) {
    errors.push("deliveryDate must be YYYY-MM-DD when present");
  }
  if (payload.deliveryPeriodStart !== undefined && !looksLikeIsoDate(payload.deliveryPeriodStart)) {
    errors.push("deliveryPeriodStart must be YYYY-MM-DD when present");
  }
  if (payload.deliveryPeriodEnd !== undefined && !looksLikeIsoDate(payload.deliveryPeriodEnd)) {
    errors.push("deliveryPeriodEnd must be YYYY-MM-DD when present");
  }
  const hasDeliveryPeriodStart = payload.deliveryPeriodStart !== undefined;
  const hasDeliveryPeriodEnd = payload.deliveryPeriodEnd !== undefined;
  if (hasDeliveryPeriodStart !== hasDeliveryPeriodEnd) {
    errors.push("deliveryPeriodStart and deliveryPeriodEnd must be provided together");
  }
  if (payload.deliveryDate !== undefined && (hasDeliveryPeriodStart || hasDeliveryPeriodEnd)) {
    errors.push("use either deliveryDate or deliveryPeriodStart/deliveryPeriodEnd, not both");
  }
  if (looksLikeIsoDate(payload.deliveryPeriodStart) && looksLikeIsoDate(payload.deliveryPeriodEnd) && payload.deliveryPeriodEnd < payload.deliveryPeriodStart) {
    errors.push("deliveryPeriodEnd cannot be earlier than deliveryPeriodStart");
  }
  if (payload.invoiceNumber !== undefined && !hasText(payload.invoiceNumber)) errors.push("invoiceNumber must not be blank when present");
  if (!hasText(payload.seller?.name)) errors.push("seller.name is required");
  if (!hasText(payload.seller?.address)) errors.push("seller.address is required");
  if (!hasText(payload.seller?.vatOrCvr)) errors.push("seller.vatOrCvr is required");
  if (!hasLineDescriptions(payload.lines)) errors.push("lines must contain at least one described good or service");
  if (!hasPositiveNumber(payload.totals?.grossAmount)) errors.push("totals.grossAmount is required");

  if (invoiceType === "full") {
    if (!hasText(payload.buyer?.name)) errors.push("buyer.name is required for full invoices");
    if (!hasText(payload.buyer?.address)) errors.push("buyer.address is required for full invoices");
    if (!hasPositiveNumber(payload.totals?.netAmount)) errors.push("totals.netAmount is required for full invoices");
  }

  const buyerEanNumber = normalizeEanNumber(payload.buyer?.eanNumber);
  const publicRecipient = payload.buyer?.publicRecipient === true || buyerEanNumber !== null;
  if (publicRecipient) {
    appliedRules.push(RULES.PUBLIC_RECIPIENT);
    if (invoiceType !== "full") {
      errors.push("public-recipient invoices must use invoiceType full");
    }
    if (!buyerEanNumber) {
      errors.push("public-recipient invoices must include buyer.eanNumber as 13 digits");
    }
  }

  if (invoiceType === "simplified") {
    if ((payload.totals?.grossAmount ?? Number.POSITIVE_INFINITY) > 3000) {
      errors.push("simplified invoices are only allowed up to DKK 3,000 gross");
    }
    const hasVatAmount = hasPositiveNumber(payload.totals?.vatAmount) && (payload.totals?.vatAmount ?? 0) > 0;
    const has20PctBasis = payload.totals?.vatComputationBasis === "VAT_20_OF_GROSS";
    if (!hasVatAmount && !has20PctBasis) {
      errors.push("simplified invoices must include vatAmount or VAT_20_OF_GROSS computation basis");
    }
  }

  const hasExplicitTaxLines = Boolean(payload.lines?.some((line) => line.taxClassification));
  if (vatTreatment === "standard" && !hasExplicitTaxLines) {
    appliedRules.push(RULES.VAT_SEPARATE_AMOUNT);
    if (!hasPositiveNumber(payload.totals?.vatRate) || (payload.totals?.vatRate ?? 0) <= 0) {
      errors.push("standard VAT invoices must include totals.vatRate");
    }
    if (!hasPositiveNumber(payload.totals?.vatAmount) || (payload.totals?.vatAmount ?? 0) <= 0) {
      errors.push("standard VAT invoices must include totals.vatAmount");
    }
  }

  if (vatTreatment === "domestic_reverse_charge" || vatTreatment === "foreign_reverse_charge") {
    appliedRules.push(RULES.REVERSE_CHARGE, RULES.REVERSE_CHARGE_BASIS);
    if (!hasText(payload.reverseChargeBasis)) {
      errors.push("reverse-charge invoices must include reverseChargeBasis");
    }
    if (payload.totals?.vatRate !== undefined) {
      errors.push("reverse-charge invoices must not include totals.vatRate");
    }
    if (payload.totals?.vatAmount !== undefined) {
      errors.push("reverse-charge invoices must not include totals.vatAmount");
    }
    if (vatTreatment === "foreign_reverse_charge") {
      if (!hasText(payload.buyer?.vatOrCvr)) {
        errors.push("foreign reverse-charge invoices must include buyer.vatOrCvr");
      }
      if (hasText(payload.reverseChargeBasis) && !FOREIGN_REVERSE_CHARGE_BASES.includes(payload.reverseChargeBasis)) {
        errors.push(`reverseChargeBasis ${payload.reverseChargeBasis} is not valid for foreign reverse-charge invoices`);
      }
    }
    if (vatTreatment === "domestic_reverse_charge" && hasText(payload.reverseChargeBasis) && !DOMESTIC_REVERSE_CHARGE_BASES.includes(payload.reverseChargeBasis)) {
      errors.push(`reverseChargeBasis ${payload.reverseChargeBasis} is not valid for domestic reverse-charge invoices`);
    }
  }

  if (Array.isArray(payload.lines)) {
    for (const [index, line] of payload.lines.entries()) {
      const qty = line.quantity;
      const unit = line.unitPriceExVat;
      const total = line.lineTotalExVat;
      if (typeof qty === "number" && typeof unit === "number" && typeof total === "number") {
        const expected = roundDkk(qty * unit);
        if (roundDkk(total) !== expected) {
          errors.push(`lines[${index}].lineTotalExVat must equal quantity * unitPriceExVat (${expected})`);
        }
      }
    }
  }
  errors.push(...taxProjection.errors);

  const lineSum = Array.isArray(payload.lines)
    ? sumDkk(payload.lines.map((line) => line.lineTotalExVat))
    : 0;
  const netAmount = roundDkk(Number(payload.totals?.netAmount ?? 0));
  const vatAmount = roundDkk(Number(payload.totals?.vatAmount ?? 0));
  const grossAmount = roundDkk(Number(payload.totals?.grossAmount ?? 0));
  const fxRateToDkk = roundRate6(Number(payload.totals?.fxRateToDkk ?? 0));
  const netAmountDkk = roundDkk(Number(payload.totals?.netAmountDkk ?? 0));
  const vatAmountDkk = roundDkk(Number(payload.totals?.vatAmountDkk ?? 0));
  const grossAmountDkk = roundDkk(Number(payload.totals?.grossAmountDkk ?? 0));

  if (invoiceType === "full" && Array.isArray(payload.lines) && payload.lines.every((line) => typeof line.lineTotalExVat === "number")) {
    if (netAmount !== lineSum) errors.push(`totals.netAmount must equal sum of lineTotalExVat (${lineSum})`);
  }
  // Standard VAT is calculated per rounded line, not from a document-level
  // multiplication. This makes both mixed rates and øre boundaries auditable:
  // the rounded taxable bases, VAT amounts, and gross must all reconcile to
  // their supplied document totals.
  const hasCompleteLineAmounts = Array.isArray(payload.lines) && payload.lines.every((line) => typeof line.lineTotalExVat === "number");
  if (vatTreatment === "standard" && hasCompleteLineAmounts) {
    // A simplified invoice may omit a document-level net amount. When its
    // line amounts are complete, the line projection is the authoritative
    // net basis; requiring a redundant total here would reject an otherwise
    // fully auditable invoice. A supplied net amount remains strict.
    if (payload.totals?.netAmount !== undefined && netAmount !== taxProjection.netAmount) errors.push(`totals.netAmount must equal rounded VAT line bases (${taxProjection.netAmount})`);
    if (vatAmount !== taxProjection.vatAmount) errors.push(`totals.vatAmount must equal rounded VAT line amounts (${taxProjection.vatAmount})`);
    if (grossAmount !== taxProjection.grossAmount) errors.push(`totals.grossAmount must equal rounded VAT line totals (${taxProjection.grossAmount})`);
  } else if (hasExplicitTaxLines) {
    if (netAmount !== taxProjection.netAmount) errors.push(`totals.netAmount must equal explicit VAT line bases (${taxProjection.netAmount})`);
    if (vatAmount !== taxProjection.vatAmount) errors.push(`totals.vatAmount must equal explicit VAT line amounts (${taxProjection.vatAmount})`);
    if (grossAmount !== taxProjection.grossAmount) errors.push(`totals.grossAmount must equal explicit VAT line totals (${taxProjection.grossAmount})`);
  }

  // Reverse-charge documents carry zero seller VAT, but their net and gross
  // still have to reconcile to the same line-level evidence as a standard
  // invoice. In particular, old payloads without explicit classifications
  // default to reverse_charge lines; do not let that legacy shape bypass the
  // arithmetic trust boundary.
  if (
    (vatTreatment === "domestic_reverse_charge" || vatTreatment === "foreign_reverse_charge") &&
    hasCompleteLineAmounts
  ) {
    if (netAmount !== taxProjection.netAmount) errors.push(`totals.netAmount must equal rounded reverse-charge line bases (${taxProjection.netAmount})`);
    if (taxProjection.vatAmount !== 0) errors.push("reverse-charge invoice lines must not include VAT");
    if (grossAmount !== taxProjection.grossAmount) errors.push(`totals.grossAmount must equal rounded reverse-charge line totals (${taxProjection.grossAmount})`);
  }

  if (vatTreatment === "standard" && !hasExplicitTaxLines && (invoiceType === "full" || payload.totals?.netAmount !== undefined)) {
    const expectedGross = roundDkk(netAmount + vatAmount);
    if (grossAmount !== expectedGross) {
      errors.push(`totals.grossAmount must equal totals.netAmount + totals.vatAmount (${expectedGross})`);
    }
  }

  // A simplified standard-VAT invoice normally omits totals.netAmount, so the
  // gross = net + vat cross-check above is skipped and an internally
  // impossible vatAmount (e.g. 999 on a 1.000 kr gross) would otherwise be
  // accepted and booked verbatim as output VAT. When an explicit vatAmount is
  // given, derive the implied net (gross − vat) and require the VAT to be
  // consistent with the declared rate, so a nonsensical figure is rejected
  // before it ever reaches the ledger. (A basis-only simplified invoice with
  // VAT_20_OF_GROSS and no explicit vatAmount computes its VAT downstream and
  // cannot be inconsistent, so it is left untouched.)
  if (
    vatTreatment === "standard" &&
    invoiceType === "simplified" &&
    payload.totals?.netAmount === undefined &&
    hasPositiveNumber(payload.totals?.vatAmount)
  ) {
    const vatRate = roundRate6(Number(payload.totals?.vatRate ?? 0));
    if (!(grossAmount > vatAmount)) {
      errors.push("totals.vatAmount must be less than totals.grossAmount");
    } else if (vatRate > 0) {
      // The VAT CONTAINED in a gross-inclusive amount is `gross * rate/(1+rate)`
      // (= 20% of gross at the 25% rate — exactly the VAT_20_OF_GROSS basis a
      // forenklet faktura uses), NOT `(gross − vat) * rate`. The net-first
      // round-trip double-rounds and wrongly rejects ~20% of legitimate
      // simplified invoices at the øre boundary (e.g. gross 100,07 → correct
      // VAT 20,01). Accept any vatAmount within one øre of the canonical
      // figure; a nonsensical VAT (e.g. 999 on a 1.000 gross) is still far
      // outside the tolerance and rejected.
      const expectedVat = roundDkk((grossAmount * vatRate) / (1 + vatRate));
      if (roundDkk(Math.abs(vatAmount - expectedVat)) > 0.01) {
        errors.push(
          `totals.vatAmount must be the VAT contained in totals.grossAmount at totals.vatRate (≈ ${expectedVat})`,
        );
      }
    }
  }

  if ((vatTreatment === "domestic_reverse_charge" || vatTreatment === "foreign_reverse_charge") && payload.totals?.netAmount !== undefined) {
    if (grossAmount !== netAmount) {
      errors.push(`reverse-charge invoices must have totals.grossAmount equal totals.netAmount (${netAmount})`);
    }
  }

  if (currency.length !== 3) {
    errors.push("currency must be a 3-letter ISO code when present");
  }

  if (currency !== "DKK") {
    if (!(fxRateToDkk > 0)) errors.push("non-DKK invoices must include totals.fxRateToDkk");
    if (!hasPositiveNumber(payload.totals?.netAmountDkk)) errors.push("non-DKK invoices must include totals.netAmountDkk");
    if (vatTreatment === "standard" && !hasPositiveNumber(payload.totals?.vatAmountDkk)) errors.push("non-DKK invoices must include totals.vatAmountDkk for standard VAT");
    if (!hasPositiveNumber(payload.totals?.grossAmountDkk)) errors.push("non-DKK invoices must include totals.grossAmountDkk");

    if (fxRateToDkk > 0) {
      if (payload.totals?.netAmountDkk !== undefined) {
        const expectedNetDkk = roundDkk(netAmount * fxRateToDkk);
        if (netAmountDkk !== expectedNetDkk) errors.push(`totals.netAmountDkk must equal totals.netAmount * totals.fxRateToDkk (${expectedNetDkk})`);
      }
      if (payload.totals?.vatAmountDkk !== undefined) {
        const expectedVatDkk = roundDkk(vatAmount * fxRateToDkk);
        if (vatAmountDkk !== expectedVatDkk) errors.push(`totals.vatAmountDkk must equal totals.vatAmount * totals.fxRateToDkk (${expectedVatDkk})`);
      }
      if (payload.totals?.grossAmountDkk !== undefined) {
        const expectedGrossDkk = roundDkk(grossAmount * fxRateToDkk);
        if (grossAmountDkk !== expectedGrossDkk) errors.push(`totals.grossAmountDkk must equal totals.grossAmount * totals.fxRateToDkk (${expectedGrossDkk})`);
      }
    }

    if (vatTreatment === "standard" && (payload.totals?.netAmountDkk !== undefined || payload.totals?.vatAmountDkk !== undefined || payload.totals?.grossAmountDkk !== undefined)) {
      const expectedGrossDkk = roundDkk(netAmountDkk + vatAmountDkk);
      if (grossAmountDkk !== expectedGrossDkk) {
        errors.push(`totals.grossAmountDkk must equal totals.netAmountDkk + totals.vatAmountDkk (${expectedGrossDkk})`);
      }
    }

    if ((vatTreatment === "domestic_reverse_charge" || vatTreatment === "foreign_reverse_charge") && payload.totals?.netAmountDkk !== undefined) {
      if (grossAmountDkk !== netAmountDkk) {
        errors.push(`reverse-charge invoices must have totals.grossAmountDkk equal totals.netAmountDkk (${netAmountDkk})`);
      }
    }
  }

  return {
    ok: errors.length === 0,
    invoiceType,
    vatTreatment,
    appliedRules,
    errors,
  };
}

const RULES = {
  FULL: "DK-INVOICE-FULL-001",
  SIMPLIFIED: "DK-INVOICE-SIMPLIFIED-001",
  REVERSE_CHARGE: "DK-INVOICE-REVERSE-CHARGE-001",
  REVERSE_CHARGE_BASIS: "DK-INVOICE-REVERSE-CHARGE-BASIS-001",
  DELIVERY_DATE: "DK-INVOICE-DELIVERY-DATE-001",
  ARITHMETIC: "DK-INVOICE-ARITHMETIC-001",
  VAT_SEPARATE_AMOUNT: "DK-VAT-SEPARATE-AMOUNT-001",
  PUBLIC_RECIPIENT: "DK-INVOICE-PUBLIC-RECIPIENT-001",
} as const;

const FOREIGN_REVERSE_CHARGE_BASES: ReverseChargeBasis[] = [
  "DK_MOMSLOVEN_§46_STK_1_NR_3",
  "EU_MOMSDIREKTIV_ART_196",
  "EU_MOMSDIREKTIV_ART_199",
];

const DOMESTIC_REVERSE_CHARGE_BASES: ReverseChargeBasis[] = [
  "DK_MOMSLOVEN_§46_STK_1_NR_6",
  "DK_MOMSLOVEN_§46_STK_1_NR_7",
];

export function resolveCompanyPaymentDetails(
  db: Database,
  currency = "DKK",
): CompanyPaymentDetails | undefined {
  let rows: Array<{
    bank_name: string | null;
    registration_no: string | null;
    account_no: string | null;
    iban: string | null;
    currency: string | null;
  }> = [];
  try {
    rows = db
      .query(
        `SELECT bank_name, registration_no, account_no, iban, currency
           FROM bank_accounts
          WHERE active = 1
          ORDER BY id ASC`,
      )
      .all() as typeof rows;
  } catch {
    // The table may not exist in very old ledgers; payment block is optional.
    return undefined;
  }
  if (rows.length === 0) return undefined;
  const wanted = currency.trim().toUpperCase();
  const match =
    rows.find((row) => (row.currency ?? "").trim().toUpperCase() === wanted) ?? rows[0];
  const details: CompanyPaymentDetails = {
    bankName: match.bank_name?.trim() || null,
    registrationNo: match.registration_no?.trim() || null,
    accountNo: match.account_no?.trim() || null,
    iban: match.iban?.trim() || null,
  };
  if (!details.bankName && !details.registrationNo && !details.accountNo && !details.iban) {
    return undefined;
  }
  return details;
}

export function requireCachedViesValidation(db: Database, vatOrCvr: string | null | undefined, label: string, asOfIso?: string): ValidateVatResult {
  const parsed = normalizeEuVatNumber(vatOrCvr);
  if (!parsed) {
    return { ok: false, appliedRules: [RULE_ID], errors: [`${label} must be a plausible EU VAT number`] };
  }
  const cached = lookupCachedViesValidation(db, parsed.normalized);
  if (!cached) {
    return {
      ok: false,
      appliedRules: [RULE_ID],
      errors: [
        `VIES lookup not yet performed for ${label} (${parsed.normalized}) — ` +
          `validate the VAT number against VIES first ` +
          `(CLI: \`customer validate-vat\`; MCP: \`customer_validate_vat\`).`,
      ],
    };
  }
  if (!cached.valid) {
    return { ok: false, appliedRules: [RULE_ID], errors: [`${label} ${parsed.normalized} is not a valid EU VAT number per cached VIES result from ${cached.validatedAt}`] };
  }
  if (isExpired(cached.expiresAt, asOfIso)) {
    return { ok: false, appliedRules: [RULE_ID], errors: [`VIES validation for ${label} ${parsed.normalized} expired at ${cached.expiresAt} — re-run validation`] };
  }
  return { ok: true, validation: cached, appliedRules: [RULE_ID], errors: [] };
}

function validateManualInvoiceNumberScope(db: Database, issueDate: string, invoiceNumber: string) {
  const { scope } = invoiceSequenceState(db, issueDate);
  const match = MANUAL_INVOICE_NUMBER_RE.exec(invoiceNumber);
  if (!match) {
    return `manual invoiceNumber ${invoiceNumber} must be of the form <scope>-<number>`;
  }
  if (match[1] !== scope) {
    return `manual invoiceNumber ${invoiceNumber} does not match current fiscal scope ${scope}`;
  }
  return null;
}

function closedPeriodIssueWarnings(db: Database, issueDate: string | undefined): string[] {
  if (!issueDate) return [];
  return validateJournalTransactionDate(db, issueDate)
    .filter((message) => message.includes("period"))
    .map((message) => `Fakturadato ${issueDate} ligger i en lukket periode: ${message}. Fakturaen er udstedt, men bogføringen vil blive afvist af periodelåsen.`);
}

function reserveManualInvoiceNumber(db: Database, issueDate: string, invoiceNumber: string) {
  const { scope, currentFloor, sequenceScope } = invoiceSequenceState(db, issueDate);
  const match = MANUAL_INVOICE_NUMBER_RE.exec(invoiceNumber);
  if (!match || match[1] !== scope) {
    return { ok: false as const, error: `manual invoiceNumber ${invoiceNumber} must be of the form <scope>-<number>` };
  }
  const requestedValue = Number(match[2]);
  const reserved = reserveSequenceValue(db, "issued_invoice", sequenceScope, requestedValue, currentFloor);
  if (!reserved.ok) {
    return {
      ok: false as const,
      error: `manual invoiceNumber ${invoiceNumber} exceeds næste fortløbende nummer ${canonicalInvoiceNumber(scope, reserved.expectedValue)}`,
    };
  }
  // #251: store the canonical four-digit form, never the verbatim manual
  // string, so the issued series stays one consistent format regardless of how
  // the number was supplied.
  return { ok: true as const, invoiceNumber: canonicalInvoiceNumber(scope, requestedValue) };
}

export function asInvoiceNumber(value: string): InvoiceNumber {
  return value as InvoiceNumber;
}

function nextIssuedInvoiceNumber(db: Database, issueDate: string) {
  const { scope, currentFloor, sequenceScope } = invoiceSequenceState(db, issueDate);
  const nextValue = nextSequenceValue(db, "issued_invoice", sequenceScope, currentFloor);
  return canonicalInvoiceNumber(scope, nextValue);
}

function sha256(text: string) {
  return createHash("sha256").update(text).digest("hex");
}

export function buildIssuedInvoicePdf(payload: IssuedInvoicePdfPayload) {
  const pages = layoutInvoice(payload);
  const issueDate = compact(payload.issueDate) ?? "1970-01-01";
  const pdfDate = `D:${issueDate.replace(/-/g, "")}000000Z`;
  const producer = "Rentemester deterministic invoice renderer";
  const title = `Faktura ${compact(payload.invoiceNumber) ?? ""}`.trim();

  // Object layout: 1 Catalog, 2 Pages, then per page a Page + Contents object,
  // then the two Font objects (F1, F2) and the Info object.
  const pageCount = pages.length;
  const pageObjectNos = pages.map((_, i) => 3 + i * 2);
  const fontRegularNo = 3 + pageCount * 2;
  const fontBoldNo = fontRegularNo + 1;
  const infoObjectNo = fontBoldNo + 1;

  const objects: string[] = [
    "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n",
    `2 0 obj\n<< /Type /Pages /Count ${pageCount} /Kids [${pageObjectNos.map((n) => `${n} 0 R`).join(" ")}] >>\nendobj\n`,
  ];
  pages.forEach((page, i) => {
    const pageNo = pageObjectNos[i];
    const contentNo = pageNo + 1;
    // ASCII separator (#225): a non-ASCII bullet/middle-dot in the footer
    // rendered as a broken glyph in some PDF viewers ("Faktura 2026-0001 <?>
    // Side 1"). A plain hyphen is safe in every viewer and font.
    const footer = `${title} - Side ${i + 1} af ${pageCount}`;
    const content = pageContentStream(page, footer);
    objects.push(
      `${pageNo} 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_WIDTH} ${PAGE_HEIGHT}] ` +
        `/Resources << /Font << /F1 ${fontRegularNo} 0 R /F2 ${fontBoldNo} 0 R >> >> /Contents ${contentNo} 0 R >>\nendobj\n`,
    );
    objects.push(
      `${contentNo} 0 obj\n<< /Length ${Buffer.byteLength(content, "binary")} >>\nstream\n${content}endstream\nendobj\n`,
    );
  });
  objects.push(
    `${fontRegularNo} 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>\nendobj\n`,
  );
  objects.push(
    `${fontBoldNo} 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>\nendobj\n`,
  );
  objects.push(
    `${infoObjectNo} 0 obj\n<< /Producer (${escapePdfText(producer)}) /Title (${escapePdfText(title)}) ` +
      `/CreationDate (${pdfDate}) /ModDate (${pdfDate}) >>\nendobj\n`,
  );

  let pdf = "%PDF-1.4\n%\xE2\xE3\xCF\xD3\n";
  const offsets: number[] = [0];
  for (const object of objects) {
    offsets.push(Buffer.byteLength(pdf, "binary"));
    pdf += object;
  }
  const xrefOffset = Buffer.byteLength(pdf, "binary");
  pdf += `xref\n0 ${objects.length + 1}\n`;
  pdf += "0000000000 65535 f \n";
  for (let i = 1; i < offsets.length; i += 1) {
    pdf += `${String(offsets[i]).padStart(10, "0")} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R /Info ${infoObjectNo} 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`;
  return Buffer.from(pdf, "binary");
}

export function writeTempFileFor(finalPath: string, content: string | Uint8Array) {
  // Retry on the (vanishingly rare) random-name collision; never follow or
  // clobber an existing entry.
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const tempPath = randomTempPath(finalPath);
    let fd: number;
    try {
      fd = openSync(tempPath, EXCL_CREATE_FLAGS, 0o600);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "EEXIST") continue;
      throw error;
    }
    try {
      writeAllSync(fd, content);
      // KODE-7: flush the file's data+metadata to stable storage BEFORE close,
      // so a power loss after the subsequent rename cannot resurrect a
      // zero-length or partially-written file. Without this, write()+rename()
      // only orders the operations in the page cache — the bytes may still be
      // in flight when the crash hits, leaving an empty manifest/signature/tar.
      fsyncSync(fd);
    } finally {
      closeSync(fd);
    }
    return tempPath;
  }
  throw new Error(`failed to create exclusive temp file for ${finalPath}`);
}

function deliveryDescription(payload: InvoicePayload) {
  if (payload.deliveryDate) return `Delivery date ${payload.deliveryDate}`;
  if (payload.deliveryPeriodStart && payload.deliveryPeriodEnd) {
    return `Delivery period ${payload.deliveryPeriodStart}..${payload.deliveryPeriodEnd}`;
  }
  return payload.lines?.map((l) => l.description).filter(Boolean).join('; ') ?? null;
}

export function retainUntilForDate(db: Database, dateText: string) {
  if (!isValidIsoDate(dateText)) throw new Error(`invalid ISO date: ${dateText}`);
  const basis = dateText.trim();
  const company = getCompanySettings(db);
  const startMonth = company.fiscalYearStartMonth;
  const year = Number(basis.slice(0, 4));
  const month = Number(basis.slice(5, 7));
  const targetYear = year + (startMonth !== 1 && month >= startMonth ? 1 : 0) + 5;
  if (targetYear > 9999) throw new Error("retention deadline exceeds YYYY-MM-DD range");
  const endMonth = startMonth === 1 ? 12 : startMonth - 1;
  // Compute the last day in the TARGET year: adding five to a leap-day string
  // can otherwise create an impossible deadline. setUTCFullYear avoids the
  // Date.UTC remapping of years 0–99 to 1900–1999.
  const end = new Date(0);
  end.setUTCFullYear(targetYear, endMonth, 0);
  return end.toISOString().slice(0, 10);
}

export function strengthenGdprErasureAliasesForIdentity(
  db: Database,
  identity: { name?: string | null; cvr?: string | null },
): void {
  const subject = resolveSubject(identity);
  if (!subject.name || !subject.cvr) return;
  const nameReference = subjectAuditReference(`name:${subject.name}`);
  const priorNameErasure = db
    .query(
      `SELECT 1
         FROM gdpr_erasures
        WHERE subject_key IN (?, ?)
        LIMIT 1`,
    )
    .get(nameReference, subject.name);
  if (!priorNameErasure) return;

  const scopeResolution = resolveSubjectScope(db, subject);
  if (!scopeResolution.ok) return;
  const erasures = loadErasures(
    db,
    // The name may already have become ambiguous. It is safe to inspect its
    // old hash here because strengthenErasureAliases still requires exact CVR
    // evidence on each source row before creating a stable binding.
    [...scopeResolution.scope.erasureSubjectKeys, nameReference],
  );
  const rows = collectSourceRows(db, scopeResolution.scope);
  strengthenErasureAliases(db, scopeResolution.scope, rows, erasures);
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

export function promoteTempFileExclusive(tempPath: string, finalPath: string) {
  linkSync(tempPath, finalPath);
  removeIfExists(tempPath);
  fsyncDir(finalPath);
}

export function asDocumentId(value: number): DocumentId {
  return value as DocumentId;
}

export function removeIfExists(path: string) {
  try {
    unlinkSync(path);
  } catch {
    // best effort cleanup
  }
}

function hasCommittedDocumentAtPath(db: Database, storedPath: string): boolean | null {
  try {
    return db.query("SELECT 1 AS present FROM documents WHERE stored_path = ? LIMIT 1").get(storedPath) != null;
  } catch {
    // An ambiguous COMMIT/I/O failure must retain a possibly authoritative
    // legal artifact. A recoverable orphan is safer than a committed row whose
    // file was deleted merely because database state could not be re-read.
    return null;
  }
}

typeDeclarations.source:
export type InvoiceLineInput = {
  description: string;
  quantity: number;
  unitPriceExVat: number;
};

export type ComputeInvoiceAmountsResult =
  | { ok: true; lines: ComputedInvoiceLine[]; totals: ComputedInvoiceTotals; errors: [] }
  | { ok: false; lines: ComputedInvoiceLine[]; totals?: undefined; errors: string[] };

export type ComputedInvoiceLine = {
  description: string;
  quantity: number;
  unitPriceExVat: number;
  lineTotalExVat: number;
};

export type ComputedInvoiceTotals = {
  /** VAT rate as a 0..1 fraction, ready for totals.vatRate. */
  vatRate: number;
  netAmount: number;
  vatAmount: number;
  grossAmount: number;
};

export type InvoicePayload = {
  invoiceType: InvoiceType;
  vatTreatment?: VatTreatment;
  issueDate?: string;
  invoiceNumber?: string;
  seller?: { name?: string; address?: string; vatOrCvr?: string };
  buyer?: InvoiceBuyer;
  /**
   * Peppol cbc:InvoicedQuantity/@unitCode (UN/ECE Rec 20). Defaults to H87
   * ("piece") in the e-invoice export; set per payload to override.
   */
  unitCode?: string;
  lines?: Array<{ description?: string; quantity?: number; unitPriceExVat?: number; lineTotalExVat?: number; unitCode?: string; taxClassification?: VatLineClassification; vatRate?: number; reverseChargeBasis?: string }>;
  totals?: {
    netAmount?: number;
    vatRate?: number;
    vatAmount?: number;
    grossAmount?: number;
    fxRateToDkk?: number;
    netAmountDkk?: number;
    vatAmountDkk?: number;
    grossAmountDkk?: number;
    vatComputationBasis?: "VAT_20_OF_GROSS" | string;
  };
  reverseChargeBasis?: ReverseChargeBasis;
  reverseChargeNote?: string;
  currency?: string;
  dueDate?: string;
  deliveryDate?: string;
  deliveryPeriodStart?: string;
  deliveryPeriodEnd?: string;
};

export type InvoiceBuyer = {
  name?: string;
  address?: string;
  vatOrCvr?: string;
  eanNumber?: string;
  publicRecipient?: boolean;
  /**
   * Peppol BIS 3.0 cbc:BuyerReference (BT-10). Mandatory for a public-recipient
   * e-invoice (PEPPOL-EN16931-R003) — the public authority's own reference
   * (often an "EAN-/ordrereference"). Without it the access point rejects the
   * invoice.
   */
  buyerReference?: string;
  /** Optional Peppol cac:OrderReference/cbc:ID (BT-13), the buyer's order id. */
  orderReference?: string;
};

export type ReverseChargeBasis =
  | "DK_MOMSLOVEN_§46_STK_1_NR_3"
  | "DK_MOMSLOVEN_§46_STK_1_NR_6"
  | "DK_MOMSLOVEN_§46_STK_1_NR_7"
  | "EU_MOMSDIREKTIV_ART_196"
  | "EU_MOMSDIREKTIV_ART_199";

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type IssueInvoiceResult = {
  ok: boolean;
  documentId?: DocumentId;
  invoiceNumber?: InvoiceNumber;
  storedPath?: string;
  sha256?: string;
  pdfDocumentId?: DocumentId;
  pdfStoredPath?: string;
  pdfSha256?: string;
  appliedRules: string[];
  errors: string[];
  // EJER-6: non-blocking advisories. Currently surfaces the case where the
  // invoice's issue date falls in an already-closed/reported accounting period
  // — the invoice document is fine, but the journal entry that books it will be
  // rejected by the period lock, so the owner is warned up front.
  warnings?: string[];
};

export type InvoiceValidationResult = {
  ok: boolean;
  invoiceType: InvoiceType;
  vatTreatment: VatTreatment;
  appliedRules: string[];
  errors: string[];
};

export type CompanyPaymentDetails = {
  bankName: string | null;
  registrationNo: string | null;
  accountNo: string | null;
  iban: string | null;
};

export type ValidateVatResult = {
  ok: boolean;
  validation?: ViesValidationRecord;
  appliedRules: string[];
  errors: string[];
};

export type ViesValidationRecord = NormalizedEuVat & {
  valid: boolean;
  name: string | null;
  address: string | null;
  validatedAt: string;
  expiresAt: string;
  rawResponse: string | null;
};

export type NormalizedEuVat = {
  countryCode: string;
  vatNumber: string;
  normalized: string;
};

export type IssuedInvoicePdfPayload = InvoicePayload & {
  invoiceNumber?: string;
  issuedAt?: string;
  status?: string;
  /** Payment instructions; injected from ledger bank-account data on render. */
  payment?: InvoicePaymentDetails;
  /**
   * Lightweight brand mark. A short text string is rendered as a styled word
   * mark in the header. This is a deliberate minimal seam: an image-based logo
   * can be added later without changing the call sites.
   */
  logoText?: string | null;
};

export type InvoicePaymentDetails = {
  bankName?: string | null;
  /** Danish 4-digit bank registration number (registreringsnummer). */
  registrationNo?: string | null;
  /** Danish bank account number (kontonummer). */
  accountNo?: string | null;
  iban?: string | null;
  /** Optional SWIFT/BIC for foreign transfers. */
  bic?: string | null;
  accountOwner?: string | null;
  customerNo?: string | null;
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

definition.handlerSpecificParsing:
(ctx) => {
    const issueDate = ctx.arg("--issue-date");
    if (!issueDate) {
      console.error("Missing required --issue-date <YYYY-MM-DD>");
      process.exit(2);
    }

    const parsedLines = parseHumanInvoiceLines(ctx.arg("--line"));
    if (!parsedLines.ok) {
      ctx.emitResult({ ok: false, appliedRules: [], errors: parsedLines.errors });
      process.exit(1);
    }

    const vatRateArg = ctx.arg("--vat-rate", "25");
    const vatRatePercent = Number(vatRateArg);
    if (!Number.isFinite(vatRatePercent)) {
      console.error("--vat-rate must be a number (percent, e.g. 25)");
      process.exit(2);
    }

    const computed = computeInvoiceAmounts(parsedLines.lines, vatRatePercent);
    if (!computed.ok) {
      ctx.emitResult({ ok: false, appliedRules: [], errors: computed.errors });
      process.exit(1);
    }

    const customerIdRaw = ctx.arg("--customer-id");
    const customerId = customerIdRaw === undefined ? undefined : Number(customerIdRaw);
    const hasCustomerRow = Number.isInteger(customerId) && (customerId as number) > 0;

    // The human gives buyer details either via a stored --customer-id (master
    // data fills name/address) or by typing them directly. Without either,
    // validation will reject the invoice with a clear message.
    const buyer: InvoicePayload["buyer"] = {};
    const buyerName = ctx.trimToNull(ctx.arg("--buyer-name") ?? null);
    const buyerAddress = ctx.trimToNull(ctx.arg("--buyer-address") ?? null);
    const buyerVat = ctx.trimToNull(ctx.arg("--buyer-vat") ?? null);
    if (buyerName) buyer.name = buyerName;
    if (buyerAddress) buyer.address = buyerAddress;
    if (buyerVat) buyer.vatOrCvr = buyerVat;

    const payload: InvoicePayload = {
      invoiceType: "full",
      vatTreatment: "standard",
      issueDate,
      ...(ctx.trimToNull(ctx.arg("--invoice-number") ?? null)
        ? { invoiceNumber: ctx.trimToNull(ctx.arg("--invoice-number") ?? null)! }
        : {}),
      seller: {
        name: ctx.trimToNull(ctx.arg("--seller-name") ?? null) ?? undefined,
        address: ctx.trimToNull(ctx.arg("--seller-address") ?? null) ?? undefined,
        vatOrCvr: ctx.trimToNull(ctx.arg("--seller-vat") ?? null) ?? undefined,
      },
      buyer,
      lines: computed.lines,
      totals: {
        netAmount: computed.totals.netAmount,
        vatRate: computed.totals.vatRate,
        vatAmount: computed.totals.vatAmount,
        grossAmount: computed.totals.grossAmount,
      },
      currency: ctx.trimToNull(ctx.arg("--currency") ?? null) ?? "DKK",
      ...(ctx.trimToNull(ctx.arg("--due-date") ?? null)
        ? { dueDate: ctx.trimToNull(ctx.arg("--due-date") ?? null)! }
        : {}),
    };

    const root = ctx.companyRoot();
    const db = openDb(companyPaths(root).db);
    migrate(db);
    const resolved = resolveInvoiceMasterData(db, payload, {
      customerId: hasCustomerRow ? customerId : undefined,
    });
    if (!resolved.ok) {
      ctx.emitResult(resolved as Record<string, unknown>);
      db.close();
      process.exit(1);
    }
    const result = issueInvoice(db, root, resolved.payload!);
    // Surface the computed amounts so a human can see exactly what Rentemester
    // worked out from their input. The core result fields stay untouched, so
    // `--format json` consumers keep a stable shape. EJER-3: master-data
    // notes (afvigende kundefrist vs. virksomhedens standard) ride along so
    // the betalingsfrist is never silently different from the profile.
    const createNotes = (resolved as { notes?: string[] }).notes;
    const enriched = {
      ...result,
      ...(result.ok && createNotes && createNotes.length > 0 ? { notes: createNotes } : {}),
      computed: {
        lines: computed.lines,
        netAmount: computed.totals.netAmount,
        vatRate: computed.totals.vatRate,
        vatRatePercent,
        vatAmount: computed.totals.vatAmount,
        grossAmount: computed.totals.grossAmount,
      },
    };
    // #268: write commands had useless `--format human` output (the command
    // description as heading, English labels, no figures). #266: the output
    // never said the invoice still needs `invoice post`. `emitHumanWrite`
    // renders both in Danish; `--format json` stays byte-identical.
    emitHumanWrite("invoice-create", enriched as Record<string, unknown>, ctx.outputFormat);
    db.close();
  }

definition.exactParser:
const BOOLEAN_FLAGS = new Set([
  "--force",
  "--help",
  "--example",
  "--json",
  "--sign-with-ed25519",
  "--archive",
  "--enrich-cvr",
  "--include-archived",
  "--ixbrl-taxonomy",
  "--after-retention-expiry",
  "--no-vat",
  "--no-open",
]);

export type ParsedCliArgs = {
  positionals: string[];
  flags: Map<string, string | true>;
  errors: string[];
};

export function parseCliArgs(argv: string[]): ParsedCliArgs {
  const tokens = argv.slice(2);
  const positionals: string[] = [];
  const flags = new Map<string, string | true>();
  const errors: string[] = [];

  let optionsTerminated = false;

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i]!;

    if (!optionsTerminated && token === "--") {
      optionsTerminated = true;
      continue;
    }

    if (optionsTerminated || !token.startsWith("--")) {
      positionals.push(token);
      continue;
    }

    // `--flag=value` form: value is attached, so it may begin with dashes
    // or be empty without being confused for a missing-value error.
    const eq = token.indexOf("=");
    if (eq !== -1) {
      const name = token.slice(0, eq);
      const value = token.slice(eq + 1);
      if (BOOLEAN_FLAGS.has(name)) {
        errors.push(`Flag ${name} does not take a value`);
        continue;
      }
      flags.set(name, value);
      continue;
    }

    if (BOOLEAN_FLAGS.has(token)) {
      const next = tokens[i + 1];
      if (next && next !== "--" && !next.startsWith("--")) {
        errors.push(`Flag ${token} does not take a value`);
        i += 1;
        continue;
      }
      flags.set(token, true);
      continue;
    }

    const value = tokens[i + 1];
    if (value === undefined || value === "--" || value.startsWith("--")) {
      errors.push(`Flag ${token} requires a value`);
      continue;
    }
    flags.set(token, value);
    i += 1;
  }

  return { positionals, flags, errors };
}

stdout.genericRenderer:
import { formatKronerDa } from "../core/money";

export type OutputFormat = "json" | "human";

export function resolveOutputFormat(flags: Map<string, string | true>): OutputFormat | null {
  if (flags.has("--json")) return "json";
  const format = flags.get("--format");
  if (format === undefined) return process.stdout.isTTY ? "human" : "json";
  if (format === "json" || format === "human") return format;
  return null;
}

export function printStructuredResult(commandLabel: string, result: Record<string, unknown>, format: OutputFormat) {
  const ok = result.ok !== false;
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  const lines = ok ? buildHumanSuccess(commandLabel, result) : buildHumanError(commandLabel, result);
  const text = lines.join("\n");
  if (ok) console.log(text);
  else console.error(text);
}

/**
 * A command's `description` in `cli-meta.ts` is a full sentence (often two)
 * meant for help text — never a heading. #268: a write command that falls
 * through to the generic human renderer used to print that whole description
 * as the `✔` heading. `headingFromLabel` collapses such a label to a short
 * heading: the first clause before an em dash / period, capped in length.
 */
function headingFromLabel(commandLabel: string): string {
  const firstClause = commandLabel.split(/\s+[—–-]\s+|\.\s/)[0]?.trim() ?? commandLabel;
  const short = firstClause.length > 0 ? firstClause : commandLabel;
  return short.length > 60 ? `${short.slice(0, 57).trimEnd()}…` : short;
}

function buildHumanSuccess(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✔ ${headingFromLabel(commandLabel)}`];
  for (const line of collectSummaryLines(result)) lines.push(`  ${line}`);
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  return lines;
}

export function buildHumanError(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✘ ${commandLabel} failed`];
  const errors = asStringArray(result.errors);
  if (errors.length > 0) {
    for (const error of errors) lines.push(`  → ${error}`);
  } else {
    lines.push("  → Kommandoen fejlede uden en specifik fejlbesked.");
  }
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  appendPeriodCloseGuidance(lines, errors);
  return lines;
}

/**
 * `vat momsangivelse` and `report annual` reject an unfinalised period with a
 * terse "... is not closed ... run 'period close' first". For an owner near a
 * deadline that is cryptic, so when we recognise that failure we append a
 * plain-Danish explanation of what closing a period means and the exact
 * command to run. (#227)
 */
function appendPeriodCloseGuidance(lines: string[], errors: string[]): void {
  const closeError = errors.find(
    (e) => /is not closed/i.test(e) && /period close/i.test(e),
  );
  if (!closeError) return;
  const range = closeError.match(/(\d{4}-\d{2}-\d{2})\.\.(\d{4}-\d{2}-\d{2})/);
  const isFiscalYear = /fiscal|regnskabsår|annual/i.test(closeError);
  const kind = isFiscalYear ? "fiscal_year" : "vat_period";
  const fromTo = range ? `--from ${range[1]} --to ${range[2]}` : "--from <YYYY-MM-DD> --to <YYYY-MM-DD>";
  lines.push("");
  lines.push("  Sådan kommer du videre:");
  lines.push(
    "    En momsangivelse/årsrapport kan kun bygges på en LUKKET periode — det sikrer,",
  );
  lines.push(
    "    at tallene ikke ændrer sig efter indberetning. Du lukker perioden med:",
  );
  lines.push(`      rentemester period close --company <path> ${fromTo} --kind ${kind}`);
  lines.push(
    "    Luk først perioden når alle bilag for perioden er bogført — en lukket periode",
  );
  lines.push(
    "    blokerer ny bogføring med dato i perioden. Brug --status reported i stedet for",
  );
  lines.push(
    "    standard 'closed', hvis du allerede har indberettet til SKAT/Erhvervsstyrelsen.",
  );
}

/**
 * Danish labels for the result keys a write command commonly returns. The
 * generic human fallback (`collectSummaryLines`) used to English-ify keys via
 * `humanizeKey` ("Invoice Number", "Document Id"); for a Danish-facing tool
 * that is wrong. Any key without an entry here keeps the humanized form, but
 * the common write-result fields are now translated. (#268)
 *
 * Round-2 review (Batch E-1) expanded the set so read commands that return
 * single objects (audit verify, company profile, gdpr export/forget,
 * customer create, invoice post) actually render meaningful content under
 * `--format human` instead of just echoing the command description.
 */
const WRITE_RESULT_LABEL_DA: Record<string, string> = {
  message: "Besked",
  invoiceNumber: "Fakturanummer",
  invoiceNo: "Fakturanummer",
  entryNo: "Posteringsnummer",
  entryNumber: "Posteringsnummer",
  documentId: "Bilags-id",
  journalEntryId: "Finanspostering-id",
  importBatchId: "Import-batch-id",
  imported: "Importeret",
  skippedDuplicates: "Sprunget over (dubletter)",
  backupId: "Backup-id",
  exportDir: "Eksportmappe",
  latestBackupId: "Seneste backup-id",
  expiredCount: "Udløbne",
  totalCount: "I alt",
  storedPath: "Gemt fil",
  pdfStoredPath: "PDF-fil",
  // Batch E-1: read-command friendly labels.
  entries: "Posteringer kontrolleret",
  chainOk: "Kæden er hel",
  erasedCount: "Anonymiseret",
  skippedCount: "Sprunget over",
  alreadyErasedCount: "Allerede anonymiseret",
  recordCount: "Rækker fundet",
  count: "Antal",
  total: "I alt",
  // Profile / contact fields (company profile, customer/vendor create).
  name: "Navn",
  cvr: "CVR",
  email: "E-mail",
  address: "Adresse",
  postalCode: "Postnummer",
  city: "By",
  country: "Land",
  currency: "Valuta",
  paymentTermsDays: "Betalingsfrist (dage)",
  vatPeriodType: "Momsperiode",
  vatPeriodLabel: "Momsstatus",
  vatRegistered: "Momsregistreret",
  companyForm: "Selskabsform",
  industryText: "Branche",
  cvrStatus: "CVR-status",
  auditWaived: "Revision fravalgt",
  fiscalYearStartMonth: "Regnskabsår starter (måned)",
  customerId: "Kunde-id",
  vendorId: "Leverandør-id",
  slug: "Slug",
};

/**
 * Top-level keys whose VALUE is a nested object that should be drilled into
 * — every scalar field inside becomes its own labelled line. Lets commands
 * like `company profile` (returns `{ ok, profile: {...} }`) emit each profile
 * field without per-command renderers. Batch E-1.
 */
const NESTED_DRILL_KEYS = new Set<string>([
  "profile",
  "customer",
  "vendor",
  "company",
  "settings",
  "depreciation",
  "writeOff",
  "reminder",
  "credit",
  "suggestion",
  "summary",
]);

function collectSummaryLines(result: Record<string, unknown>) {
  const preferredKeys = [
    "message",
    "invoiceNumber",
    "invoiceNo",
    "entryNo",
    "entryNumber",
    "documentId",
    "journalEntryId",
    "importBatchId",
    "imported",
    "skippedDuplicates",
    "backupId",
    "exportDir",
    "latestBackupId",
    "expiredCount",
    "totalCount",
    "entries",
    "chainOk",
    "erasedCount",
    "skippedCount",
    "alreadyErasedCount",
    "recordCount",
    "count",
    "total",
    "name",
    "cvr",
    "email",
    "address",
    "postalCode",
    "city",
    "country",
    "currency",
    "paymentTermsDays",
    "vatPeriodType",
    "vatPeriodLabel",
    "vatRegistered",
    "companyForm",
    "industryText",
    "cvrStatus",
    "auditWaived",
    "fiscalYearStartMonth",
    "customerId",
    "vendorId",
    "slug",
  ];
  const lines: string[] = [];
  const seen = new Set<string>();
  for (const key of preferredKeys) {
    if (seen.has(key)) continue;
    const value = result[key];
    const rendered = renderScalar(value);
    if (rendered === null) continue;
    // #268: never emit an English key on a Danish-facing tool — use the Danish
    // label when one exists, falling back to the humanized form otherwise.
    lines.push(
      `${WRITE_RESULT_LABEL_DA[key] ?? humanizeKey(key)}: ${translateValueForKey(key, rendered)}`,
    );
    seen.add(key);
  }
  // Batch E-1: drill one level into well-known nested-object keys. Lets
  // `company profile` (returns `{ ok, profile: {...} }`) actually render
  // each profile field instead of showing only "✔ <command description>".
  for (const [key, value] of Object.entries(result)) {
    if (!NESTED_DRILL_KEYS.has(key)) continue;
    if (value == null || typeof value !== "object" || Array.isArray(value)) continue;
    const inner = value as Record<string, unknown>;
    for (const [innerKey, innerValue] of Object.entries(inner)) {
      if (seen.has(innerKey)) continue;
      const rendered = renderScalar(innerValue);
      if (rendered === null) continue;
      lines.push(
        `${WRITE_RESULT_LABEL_DA[innerKey] ?? humanizeKey(innerKey)}: ${translateValueForKey(innerKey, rendered)}`,
      );
      seen.add(innerKey);
    }
  }
  return lines;
}

function renderScalar(value: unknown): string | null {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return null;
}

/**
 * Danish display values for the handful of enum-valued profile fields whose raw
 * stored form is an English token (e.g. `quarter`, `end-year`). #268 already
 * translates the key (label) into Danish; this translates the VALUE so an owner
 * never sees "Momsperiode: quarter". Keyed by field, then by raw value; unknown
 * fields/values pass through unchanged.
 */
const VALUE_LABEL_DA: Record<string, Record<string, string>> = {
  vatPeriodType: {
    month: "måned",
    quarter: "kvartal",
    "half-year": "halvår",
  },
  vatRegistered: {
    true: "Ja",
    false: "Nej",
  },
  fiscalYearLabelStrategy: {
    "end-year": "slutår",
    "start-year": "startår",
  },
};

function translateValueForKey(key: string, rendered: string): string {
  return VALUE_LABEL_DA[key]?.[rendered] ?? rendered;
}

function humanizeKey(key: string) {
  return key
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/_/g, " ")
    .replace(/^./, (c) => c.toUpperCase());
}

export function asStringArray(value: unknown) {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

/**
 * Format a DKK amount as Danish kroner-og-øre, e.g. 38.3 -> "38,30 kr.",
 * -1234.5 -> "-1.234,50 kr.". Non-finite/missing input yields "—".
 *
 * Thin re-export of the single canonical formatter `formatKronerDa` in
 * `core/money.ts` — kept under the historical name so the many call sites in
 * this file stay unchanged. (#314)
 */
export function formatKroner(value: unknown): string {
  return formatKronerDa(value);
}

/** Render an integer count, falling back to 0 for missing values. */
export function asCount(value: unknown): number {
  const num = typeof value === "number" ? value : Number(value);
  return Number.isFinite(num) ? num : 0;
}

export function asText(value: unknown, fallback = "—"): string {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  return fallback;
}

export function asArray(value: unknown): Array<Record<string, unknown>> {
  return Array.isArray(value)
    ? value.filter((item): item is Record<string, unknown> => typeof item === "object" && item !== null)
    : [];
}

/**
 * Format a percentage with Danish decimal comma, e.g. 8.05 -> "8,05 %".
 * Non-finite/missing input yields "—".
 */
export function formatPercent(value: unknown): string {
  const num = typeof value === "number" ? value : Number(value);
  if (value == null || value === "" || !Number.isFinite(num)) return "—";
  const text = (Math.round(num * 100) / 100)
    .toString()
    .replace(".", ",");
  return `${text} %`;
}

export function appendWarnings(lines: string[], result: Record<string, unknown>): void {
  const warnings = asStringArray(result.warnings);
  if (warnings.length === 0) return;
  lines.push("");
  lines.push("Advarsler:");
  for (const warning of warnings) lines.push(`  - ${warning}`);
}

stdout.reportDispatch:
import { type OutputFormat, buildHumanError, printStructuredResult } from "./common";
import { renderVatReport, renderVatFiling, renderAnnualReport, renderTaxReturn } from "./vat";
import {
  renderInvoiceStatus,
  renderInvoiceInterest,
  renderInvoiceCompensation,
  renderInvoiceValidate,
  renderInvoiceCreate,
} from "./invoice";
import {
  renderBackupStatus,
  renderExceptionsList,
  renderTrialBalance,
  renderProfitAndLoss,
  renderBalanceSheet,
  renderRetentionStatus,
} from "./dashboard";
import { renderBankReconciliation } from "./bank";

// ===========================================================================
// HUMAN-READABLE REPORT RENDERING — DISPATCH (#211)
// ---------------------------------------------------------------------------
// Read/report commands emit deterministic JSON with English field names for
// agents. When a human runs them (`--format human` / a TTY) that JSON is
// unreadable. `renderHumanReport` renders the same payloads in clear Danish
// with money in kroner-og-øre. The `--format json` path is untouched: handlers
// keep calling `ctx.emitResult` for JSON and only branch into this renderer
// for the human format.
// ===========================================================================

/** Report kinds with a dedicated Danish human renderer. */
export type HumanReportKind =
  | "vat-report"
  | "vat-filing"
  | "report-annual"
  | "report-tax"
  | "invoice-status"
  | "invoice-interest"
  | "invoice-compensation"
  | "invoice-validate"
  | "exceptions-list"
  | "report-trial-balance"
  | "report-profit-loss"
  | "report-balance"
  | "retention-status"
  | "reconcile-bank"
  | "backup-status"
  // #177: `report annual --ixbrl-taxonomy` prints the bounded iXBRL subset.
  // No dedicated renderer — it falls back to the generic structured output.
  | "report-annual-ixbrl-taxonomy";

/**
 * Render a read/report `result` payload as Danish human-readable text.
 *
 * Returns `null` when there is no dedicated renderer for `kind` or the payload
 * does not look renderable, so callers can fall back to the generic
 * `printStructuredResult` rendering.
 */
export function renderHumanReport(
  kind: HumanReportKind,
  result: Record<string, unknown>,
): string | null {
  // `backup-status` reports `ok: false` when the weekly backup duty is NOT met
  // — that is a valid compliance status to render, not a command failure. Its
  // renderer handles both states, so it must run before the generic
  // ok-false-as-error path. (#240)
  if (kind === "backup-status") {
    return renderBackupStatus(result);
  }
  // `invoice validate` reports `ok: false` when the payload is INVALID — that
  // is a valid validation verdict to render in full (the figures and every
  // rejection reason), not a command crash. Its renderer covers both the
  // valid and invalid verdict, so it must run before the generic
  // ok-false-as-error path. (#250)
  if (kind === "invoice-validate") {
    return renderInvoiceValidate(result);
  }
  if (result.ok === false) {
    return buildHumanError(humanReportTitle(kind), result).join("\n");
  }
  switch (kind) {
    case "vat-report":
      return renderVatReport(result);
    case "vat-filing":
      return renderVatFiling(result);
    case "report-annual":
      return renderAnnualReport(result);
    case "report-tax":
      return renderTaxReturn(result);
    case "invoice-status":
      return renderInvoiceStatus(result);
    case "invoice-interest":
      return renderInvoiceInterest(result);
    case "invoice-compensation":
      return renderInvoiceCompensation(result);
    case "exceptions-list":
      return renderExceptionsList(result);
    case "report-trial-balance":
      return renderTrialBalance(result);
    case "report-profit-loss":
      return renderProfitAndLoss(result);
    case "report-balance":
      return renderBalanceSheet(result);
    case "retention-status":
      return renderRetentionStatus(result);
    case "reconcile-bank":
      return renderBankReconciliation(result);
    default:
      // `backup-status` and `invoice-validate` are handled before this switch
      // (their renderers cover the ok:false state too), so they never reach
      // here.
      return null;
  }
}

/**
 * Emit a read/report `result` either as the byte-stable agent JSON or as the
 * Danish human rendering, depending on `format`. The `--format json` path is
 * exactly `JSON.stringify(result, null, 2)` — unchanged from `emitResult` —
 * so agents see no difference. Only the human rendering is new.
 *
 * Returns the process exit code to apply (1 when `result.ok === false`).
 */
export function emitHumanReport(
  kind: HumanReportKind,
  result: Record<string, unknown>,
  format: OutputFormat,
): void {
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    const human = renderHumanReport(kind, result);
    if (human !== null) {
      if (result.ok === false) console.error(human);
      else console.log(human);
    } else {
      printStructuredResult(humanReportTitle(kind), result, format);
    }
  }
  if (result.ok === false) process.exitCode = 1;
}

function humanReportTitle(kind: HumanReportKind): string {
  switch (kind) {
    case "vat-report":
      return "Momsrapport";
    case "vat-filing":
      return "Momsangivelse";
    case "report-annual":
      return "Årsrapport";
    case "report-tax":
      return "Skattemæssig indkomst";
    case "invoice-status":
      return "Fakturastatus";
    case "invoice-interest":
      return "Morarente";
    case "invoice-compensation":
      return "Kompensation for sen betaling";
    case "invoice-validate":
      return "Fakturavalidering";
    case "exceptions-list":
      return "Undtagelser";
    case "report-trial-balance":
      return "Saldobalance";
    case "report-profit-loss":
      return "Resultatopgørelse";
    case "report-balance":
      return "Balance";
    case "retention-status":
      return "Opbevaringsstatus";
    case "reconcile-bank":
      return "Bankafstemning";
    case "backup-status":
      return "Backup-status";
    case "report-annual-ixbrl-taxonomy":
      return "iXBRL-taksonomi (afgrænset udsnit)";
  }
}

/** Write-command kinds with a dedicated Danish human renderer. (#266, #268) */
export type HumanWriteKind = "invoice-create";

/**
 * Emit a write-command `result` either as the byte-stable agent JSON or as a
 * Danish human rendering, depending on `format`. The `--format json` path is
 * exactly `JSON.stringify(result, null, 2)` — unchanged from `emitResult` — so
 * agents see no difference. Sets `process.exitCode = 1` on `ok: false`. (#268)
 */
export function emitHumanWrite(
  kind: HumanWriteKind,
  result: Record<string, unknown>,
  format: OutputFormat,
): void {
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    const human = kind === "invoice-create" ? renderInvoiceCreate(result) : null;
    if (human !== null) {
      if (result.ok === false) console.error(human);
      else console.log(human);
    } else {
      printStructuredResult(kind, result, format);
    }
  }
  if (result.ok === false) process.exitCode = 1;
}

specializedFormatters.src/cli-format/invoice.ts:
import { invoiceStatusDa, FALLBACK_UKENDT } from "../core/messages";
import {
  asArray,
  asCount,
  asText,
  appendWarnings,
  buildHumanError,
  asStringArray,
  formatKroner,
  formatPercent,
} from "./common";

// --- Invoice status --------------------------------------------------------

export function renderInvoiceStatus(result: Record<string, unknown>): string {
  const lines: string[] = [];
  const number = asText(result.invoiceNumber);
  lines.push(`Status for faktura ${number}`);
  lines.push("");

  const statusCode = typeof result.status === "string" ? result.status : "";
  const statusDa = invoiceStatusDa(statusCode) ?? FALLBACK_UKENDT;
  const open = typeof result.openBalance === "number" ? result.openBalance : Number(result.openBalance);

  if (statusCode === "paid") {
    lines.push("Fakturaen er fuldt betalt.");
  } else if (statusCode === "credited") {
    lines.push("Fakturaen er krediteret.");
  } else if (statusCode === "refunded") {
    lines.push("Fakturaen er refunderet.");
  } else if (statusCode === "written_off") {
    lines.push("Fakturaen er afskrevet som tab på debitorer.");
  } else if (statusCode === "overpaid") {
    lines.push(`Fakturaen er overbetalt med ${formatKroner(Number.isFinite(open) ? -open : open)}.`);
  } else if (Number.isFinite(open) && open > 0) {
    lines.push(`Der mangler at blive betalt ${formatKroner(open)} på fakturaen.`);
  } else {
    lines.push(`Fakturaen er ${statusDa}.`);
  }

  if (result.isOverdue === true) {
    const days = asCount(result.overdueDays);
    lines.push(`Fakturaen er forfalden — ${days} dage over forfaldsdato.`);
  }

  // One decisive bottom-line: an invoice may be part-paid, part-credited and
  // part-refunded at once, and the owner cannot read "still owes anything" off
  // four separate amounts. claimOpenBalance is the total still outstanding,
  // including reminder fees / interest / compensation. (#233)
  const claimOpen =
    typeof result.claimOpenBalance === "number"
      ? result.claimOpenBalance
      : Number(result.claimOpenBalance);
  const outstanding = Number.isFinite(claimOpen) ? claimOpen : open;
  if (Number.isFinite(outstanding) && outstanding > 0) {
    lines.push(`→ Udestående i alt: ${formatKroner(outstanding)} — kunden skylder stadig.`);
  } else if (Number.isFinite(outstanding) && outstanding < 0) {
    lines.push(`→ Afsluttet — kunden har ${formatKroner(-outstanding)} til gode.`);
  } else {
    lines.push("→ Afsluttet — intet udestående.");
  }

  lines.push("");
  lines.push(`  Fakturabeløb (inkl. moms):     ${formatKroner(result.grossAmount)}`);
  if (asCount(result.creditedAmount) !== 0) {
    lines.push(`  Krediteret:                    ${formatKroner(result.creditedAmount)}`);
  }
  lines.push(`  Betalt:                        ${formatKroner(result.paidAmount)}`);
  lines.push(`  Åben saldo:                    ${formatKroner(result.openBalance)}`);
  if (asCount(result.claimOpenBalance) !== 0) {
    lines.push(`  Åben saldo på krav (gebyrer):  ${formatKroner(result.claimOpenBalance)}`);
  }
  lines.push("");
  lines.push(`  Status:                        ${statusDa}`);
  if (result.effectiveDueDate) {
    lines.push(`  Forfaldsdato:                  ${asText(result.effectiveDueDate)}`);
  }
  if (result.asOfDate) {
    lines.push(`  Opgjort pr.:                   ${asText(result.asOfDate)}`);
  }

  const payments = asArray(result.payments);
  if (payments.length > 0) {
    lines.push("");
    lines.push(`Indbetalinger (${payments.length}):`);
    for (const payment of payments) {
      lines.push(
        `  - ${asText(payment.paymentDate)}: ${formatKroner(payment.amount)}` +
          (payment.note ? ` (${asText(payment.note)})` : ""),
      );
    }
  }

  const creditNotes = asArray(result.creditNotes);
  if (creditNotes.length > 0) {
    lines.push("");
    lines.push(`Kreditnotaer (${creditNotes.length}):`);
    for (const note of creditNotes) {
      lines.push(
        `  - ${asText(note.creditNoteNumber)} (${asText(note.issueDate)}): ${formatKroner(note.amount)}`,
      );
    }
  }

  const reminders = asArray(result.reminders);
  if (reminders.length > 0) {
    lines.push("");
    lines.push(`Rykkere (${reminders.length}):`);
    for (const reminder of reminders) {
      lines.push(
        `  - ${asText(reminder.reminderDate)}: gebyr ${formatKroner(reminder.feeAmount)}`,
      );
    }
  }
  appendWarnings(lines, result);
  return lines.join("\n");
}

// --- Invoice late interest (morarente) -------------------------------------

/**
 * Render an `invoice interest` / `invoice claim-interest` payload as Danish
 * human text. The payload is the `CalculateInvoiceLateInterestResult` from
 * `calculateInvoiceLateInterest` (optionally with the `claimId` /
 * `claimOpenBalance` registration fields). Shows the reference rate, the
 * statutory annual rate, the overdue window and the computed interest amount
 * — the figures that previously only appeared under `--format json`. (#250)
 */
export function renderInvoiceInterest(result: Record<string, unknown>): string {
  const lines: string[] = [];
  lines.push(`Morarente for faktura ${asText(result.invoiceNumber)}`);
  lines.push("");

  const overdueDays = asCount(result.overdueDays);
  const claimableDays = asCount(result.claimableDays);
  const interest =
    typeof result.accruedInterestAmount === "number"
      ? result.accruedInterestAmount
      : Number(result.accruedInterestAmount);
  const prior =
    typeof result.priorClaimedInterest === "number"
      ? result.priorClaimedInterest
      : Number(result.priorClaimedInterest);
  const hasPrior = Number.isFinite(prior) && prior > 0;
  const registered = result.claimId != null;

  if (overdueDays > 0 && Number.isFinite(interest) && interest > 0) {
    if (hasPrior) {
      // A later claim: pair the AMOUNT with the incremental day-count it covers,
      // never the full overdue window (which would imply a wrong daily rate).
      lines.push(
        `Fakturaen er ${overdueDays} dage forfalden. Ny morarente for de ${claimableDays} dage siden sidste krav (fra ${asText(result.interestFromDate)}): ${formatKroner(interest)}.`,
      );
    } else {
      lines.push(
        `Fakturaen er ${overdueDays} dage forfalden — der er påløbet ${formatKroner(interest)} i morarente.`,
      );
    }
  } else if (overdueDays > 0) {
    if (hasPrior) {
      lines.push(
        `Fakturaen er ${overdueDays} dage forfalden. Der er ingen ny morarente at opkræve — renten er allerede opgjort til og med ${asText(result.interestFromDate)}.`,
      );
    } else {
      lines.push(
        `Fakturaen er ${overdueDays} dage forfalden, men der er ingen morarente at opkræve` +
          " (ingen åben saldo at forrente).",
      );
    }
  } else {
    lines.push("Fakturaen er ikke forfalden — der er ingen morarente at opkræve.");
  }
  lines.push("");

  lines.push(`  Forfaldsdato:                  ${asText(result.effectiveDueDate)}`);
  lines.push(`  Opgjort pr.:                   ${asText(result.asOfDate)}`);
  lines.push(`  Antal forfaldne dage:          ${overdueDays}`);
  lines.push(`  Åben hovedstol:                ${formatKroner(result.principalOpenBalance)}`);
  lines.push(`  Referencesats (Nationalbanken): ${formatPercent(result.referenceRatePercent)}`);
  lines.push(
    `  Morarentesats (reference + 8 %): ${formatPercent(result.annualInterestRatePercent)}`,
  );
  lines.push(`  Påløbet morarente:             ${formatKroner(result.accruedInterestAmount)}`);

  // When an earlier claim already exists, the figure above is the INCREMENTAL
  // interest for the period since that claim (renteloven § 3, § 5: no day is
  // billed twice). Show the breakdown so the cumulative total is never hidden.
  if (hasPrior) {
    lines.push(
      `  Dage i dette krav (siden ${asText(result.interestFromDate)}): ${claimableDays}`,
    );
    lines.push(
      `  Allerede registreret morarente: ${formatKroner(result.priorClaimedInterest)}`,
    );
    lines.push(
      `  Morarente i alt til dato:      ${formatKroner(result.totalInterestToDate)}`,
    );
  }

  // A back-dated balance reduction can leave already-issued (immutable) claims
  // exceeding the now-lawful interest. Surface it so a correcting credit can be
  // considered — never silently buried.
  const overClaimed =
    typeof result.overClaimedInterest === "number"
      ? result.overClaimedInterest
      : Number(result.overClaimedInterest);
  if (Number.isFinite(overClaimed) && overClaimed > 0) {
    lines.push("");
    lines.push(
      `  OBS: tidligere rentekrav overstiger den nu lovlige rente med ${formatKroner(result.overClaimedInterest)}`,
    );
    lines.push(
      "       (en bagud-dateret betaling/kreditnota har sænket saldoen) — overvej en korrektions-kreditnota.",
    );
  }

  if (registered) {
    lines.push("");
    lines.push(`Morarentekravet er registreret (krav-id ${asText(result.claimId)}).`);
    if (result.claimDate) {
      lines.push(`  Kravdato:                      ${asText(result.claimDate)}`);
    }
    if (result.claimOpenBalance !== undefined) {
      lines.push(`  Åben saldo på krav:            ${formatKroner(result.claimOpenBalance)}`);
    }
  }
  appendWarnings(lines, result);
  return lines.join("\n");
}

// --- Invoice late compensation (kompensationsbeløb) ------------------------

/**
 * Render an `invoice compensation` / `invoice claim-compensation` payload as
 * Danish human text. The payload is the `CalculateInvoiceLateCompensationResult`
 * from `calculateInvoiceLateCompensation` (optionally with the registration
 * fields). Shows whether the invoice is eligible for the statutory fixed
 * compensation for late commercial payment, the amount and a clear reason
 * — figures that previously only appeared under `--format json`. (#250)
 */
export function renderInvoiceCompensation(result: Record<string, unknown>): string {
  const lines: string[] = [];
  lines.push(`Kompensation for sen betaling — faktura ${asText(result.invoiceNumber)}`);
  lines.push("");

  const eligible = result.eligible === true;
  const amount =
    typeof result.compensationAmountDkk === "number"
      ? result.compensationAmountDkk
      : Number(result.compensationAmountDkk);
  const registered = result.claimId != null;

  if (eligible && Number.isFinite(amount) && amount > 0) {
    lines.push(
      `Fakturaen er berettiget til ${formatKroner(amount)} i fast kompensation for sen betaling.`,
    );
  } else {
    lines.push("Fakturaen er IKKE berettiget til kompensation for sen betaling.");
    lines.push(`  Årsag: ${reasonInDanish(result.reason)}`);
  }
  lines.push("");

  lines.push(`  Forfaldsdato:                  ${asText(result.effectiveDueDate)}`);
  lines.push(`  Opgjort pr.:                   ${asText(result.asOfDate)}`);
  lines.push(`  Antal forfaldne dage:          ${asCount(result.overdueDays)}`);
  lines.push(`  Åben hovedstol:                ${formatKroner(result.principalOpenBalance)}`);
  lines.push(
    `  Erhvervshandel (CVR/VAT):      ${result.isCommercialTransaction === true ? "ja" : "nej"}`,
  );
  lines.push(`  Berettiget:                    ${eligible ? "ja" : "nej"}`);
  lines.push(`  Kompensationsbeløb:            ${formatKroner(result.compensationAmountDkk)}`);

  if (registered) {
    lines.push("");
    lines.push(`Kompensationskravet er registreret (krav-id ${asText(result.claimId)}).`);
    if (result.claimDate) {
      lines.push(`  Kravdato:                      ${asText(result.claimDate)}`);
    }
    if (result.claimOpenBalance !== undefined) {
      lines.push(`  Åben saldo på krav:            ${formatKroner(result.claimOpenBalance)}`);
    }
  }
  appendWarnings(lines, result);
  return lines.join("\n");
}

/**
 * Translate the machine-readable `reason` from the compensation core into a
 * plain-Danish explanation for the human renderer. Falls back to the raw
 * reason string for any reason without a dedicated translation.
 */
function reasonInDanish(reason: unknown): string {
  const text = typeof reason === "string" ? reason : "";
  if (text === "eligible" || text === "registered") {
    return "fakturaen er berettiget";
  }
  if (/commercial transaction not proven/i.test(text)) {
    return "købers CVR/VAT-nummer mangler — handlen kan ikke dokumenteres som erhvervshandel";
  }
  if (/no collectible open balance/i.test(text)) {
    return "fakturaen har ingen åben saldo at opkræve kompensation for";
  }
  if (/not overdue/i.test(text)) {
    return "fakturaen er ikke forfalden på den valgte dato";
  }
  if (/predates statutory compensation start date/i.test(text)) {
    return "fakturaen ligger før den lovbestemte ikrafttrædelsesdato for kompensation (1. marts 2013)";
  }
  return text.length > 0 ? text : "ukendt";
}

// --- Invoice payload validation --------------------------------------------

/**
 * Render an `invoice validate` payload as Danish human text. The payload is
 * the `InvoiceValidationResult` from `validateInvoice`. Both verdicts are
 * rendered in full: a valid payload states it plainly, an invalid payload
 * lists every concrete rejection reason — instead of a blank command
 * description with no result. (#250)
 */
export function renderInvoiceValidate(result: Record<string, unknown>): string {
  const lines: string[] = [];
  const valid = result.ok !== false;
  lines.push("Fakturavalidering");
  lines.push("");

  if (valid) {
    lines.push("Fakturaen er gyldig og kan udstedes.");
  } else {
    const errors = asStringArray(result.errors);
    lines.push(
      `Fakturaen er IKKE gyldig — ${errors.length} ${errors.length === 1 ? "fejl" : "fejl"} skal rettes:`,
    );
    if (errors.length === 0) {
      lines.push("  → Valideringen fejlede uden en specifik fejlbesked.");
    } else {
      for (const error of errors) lines.push(`  → ${error}`);
    }
  }
  lines.push("");

  const invoiceTypeDa =
    result.invoiceType === "simplified"
      ? "forenklet faktura"
      : result.invoiceType === "full"
        ? "fuld faktura"
        : asText(result.invoiceType);
  const vatTreatmentDa = VAT_TREATMENT_DA[String(result.vatTreatment)] ?? asText(result.vatTreatment);
  lines.push(`  Fakturatype:                   ${invoiceTypeDa}`);
  lines.push(`  Momsbehandling:                ${vatTreatmentDa}`);

  const rules = asStringArray(result.appliedRules);
  if (rules.length > 0) {
    lines.push(`  Anvendte regler:               ${rules.join(", ")}`);
  }
  appendWarnings(lines, result);
  return lines.join("\n");
}

/** Danish labels for the invoice VAT treatments. */
const VAT_TREATMENT_DA: Record<string, string> = {
  standard: "standardmoms",
  domestic_reverse_charge: "omvendt betalingspligt (indenlandsk)",
  foreign_reverse_charge: "omvendt betalingspligt (udenlandsk)",
};

// --- Invoice create (write command, guided path) ---------------------------

/**
 * Render an `invoice create` result as Danish human text. The payload is the
 * `IssueInvoiceResult` enriched with `computed` (line totals, net, VAT, gross)
 * from `src/cli/invoice.ts`. (#266, #268)
 *
 * Two bugs are addressed here:
 *  - #268: the write command used to fall through to the generic renderer,
 *    which printed the long command DESCRIPTION as the heading and English
 *    field labels ("Invoice Number", "Document Id") and dropped the figures.
 *    This renderer gives a short Danish heading, Danish labels and the
 *    amounts/VAT/dates/paths that matter.
 *  - #266: `invoice create` builds and issues the invoice but does NOT post it
 *    to the ledger — no revenue / output-VAT posting. The output must make
 *    that gap impossible to miss, so it states plainly that `invoice post` is
 *    still required.
 */
export function renderInvoiceCreate(result: Record<string, unknown>): string {
  if (result.ok === false) {
    return buildHumanError("Faktura kunne ikke udstedes", result).join("\n");
  }
  const computed = (typeof result.computed === "object" && result.computed !== null
    ? result.computed
    : {}) as Record<string, unknown>;
  const number = asText(result.invoiceNumber);
  const lines: string[] = [];
  lines.push(`Faktura ${number} er udstedt`);
  lines.push("");

  lines.push(`  Fakturanummer:                 ${number}`);
  if (result.documentId != null) {
    lines.push(`  Bilags-id:                     ${asText(result.documentId)}`);
  }
  lines.push(`  Nettobeløb (ekskl. moms):      ${formatKroner(computed.netAmount)}`);
  const ratePercent = computed.vatRatePercent ?? computed.vatRate;
  if (ratePercent != null) {
    const pct =
      typeof computed.vatRatePercent === "number"
        ? computed.vatRatePercent
        : typeof computed.vatRate === "number"
          ? computed.vatRate * 100
          : Number(ratePercent);
    lines.push(`  Momssats:                      ${formatPercent(pct)}`);
  }
  lines.push(`  Momsbeløb:                     ${formatKroner(computed.vatAmount)}`);
  lines.push(`  Fakturabeløb (inkl. moms):     ${formatKroner(computed.grossAmount)}`);
  if (result.storedPath) {
    lines.push(`  Gemt faktura (JSON):           ${asText(result.storedPath)}`);
  }
  if (result.pdfStoredPath) {
    lines.push(`  Faktura-PDF:                   ${asText(result.pdfStoredPath)}`);
  }
  lines.push("");
  // #266: the decisive line — the invoice is issued but NOT yet booked.
  lines.push(
    `Fakturaen er udstedt, men endnu IKKE bogført — kør \`invoice post ${number}\``,
  );
  lines.push(
    "for at få den i regnskabet (salgsindtægt og udgående moms). Indtil da indgår",
  );
  lines.push("den ikke i din moms eller dit resultat.");
  appendWarnings(lines, result);
  return lines.join("\n");
}

