export function renderIssuedInvoicePdf(db: Database, companyRoot: string, input: RenderIssuedInvoicePdfInput): RenderIssuedInvoicePdfResult {
  const invoice = db.query(
    `SELECT id, invoice_no, invoice_date, payload_json, status, retain_until
     FROM documents WHERE id = ? AND document_type = 'issued_invoice'`
  ).get(input.invoiceDocumentId) as {
    id: number;
    invoice_no: string | null;
    invoice_date: string | null;
    payload_json: string | null;
    status: string | null;
    retain_until: string | null;
  } | null;

  if (!invoice) return { ok: false, appliedRules: [RULE_ID], errors: [`invoice document ${input.invoiceDocumentId} does not exist or is not an issued invoice`] };
  if (!invoice.payload_json) return { ok: false, appliedRules: [RULE_ID], errors: [`invoice ${invoice.invoice_no ?? input.invoiceDocumentId} is missing payload_json`] };

  // A normal issued invoice has its sequential number in the immutable row.
  // Do not parse the render payload merely to serve an existing PDF: the PDF
  // remains independently verifiable evidence even if unrelated legacy JSON
  // has become unreadable.
  let payload: IssuedInvoicePdfPayload | undefined;
  let invoiceNumber = compact(invoice.invoice_no);
  if (!invoiceNumber) {
    try {
      payload = JSON.parse(invoice.payload_json) as IssuedInvoicePdfPayload;
      invoiceNumber = compact(payload.invoiceNumber);
    } catch {
      return { ok: false, appliedRules: [RULE_ID], errors: [`invoice ${input.invoiceDocumentId} has invalid payload_json`] };
    }
  }
  if (!invoiceNumber) return { ok: false, appliedRules: [RULE_ID], errors: ["issued invoice is missing invoice number"] };

  const paths = companyPaths(companyRoot);
  const storedPath = join(paths.invoicesIssued, `${invoiceNumber}.pdf`);

  // An issued PDF is accounting evidence, not a view derived from today's
  // master data.  In particular, a later bank-account or payment-term change
  // must never replace the bytes the customer received.  Look it up before
  // building anything: the successful path below is deliberately read-only.
  const existing = db.query(
    `SELECT id, sha256_hash, stored_path, payload_json FROM documents
       WHERE document_type = ? AND invoice_no = ?
       ORDER BY id ASC`,
  ).all(PDF_DOCUMENT_TYPE, invoiceNumber) as Array<{ id: number; sha256_hash: string; stored_path: string | null; payload_json: string | null }>;

  if (existing.length > 1) {
    return {
      ok: false,
      appliedRules: [RULE_ID],
      errors: [`issued invoice PDF evidence for ${invoiceNumber} is ambiguous; refusing to render or replace it`],
    };
  }

  if (existing.length === 1) {
    const evidence = existing[0]!;
    if (evidence.payload_json !== invoice.payload_json) {
      return {
        ok: false,
        appliedRules: [RULE_ID],
        errors: [`issued invoice PDF evidence for ${invoiceNumber} is not bound to the immutable invoice snapshot; refusing to repair it`],
      };
    }
    try {
      const existing = snapshotRegisteredDocumentEvidence(companyRoot, {
        storedPath: evidence.stored_path ?? "",
        expectedSha256: evidence.sha256_hash,
        documentType: PDF_DOCUMENT_TYPE,
      });
      if (!existing.bytes.subarray(0, 5).equals(Buffer.from("%PDF-"))) {
        return {
          ok: false,
          appliedRules: [RULE_ID],
          errors: [`issued invoice PDF evidence for ${invoiceNumber} is missing or fails integrity verification; refusing to repair it`],
        };
      }
      return {
        ok: true,
        renderDocumentId: evidence.id,
        invoiceNumber,
        storedPath,
        sha256: evidence.sha256_hash,
        appliedRules: [RULE_ID],
        errors: [],
      };
    } catch {
      return {
        ok: false,
        appliedRules: [RULE_ID],
        errors: [`issued invoice PDF evidence for ${invoiceNumber} is missing or fails integrity verification; refusing to repair it`],
      };
    }
  }

  // Older ledgers can contain an issued invoice without a PDF evidence row.
  // That is the only case in which this command may create one.  It publishes
  // to an absent path exclusively and never replaces an existing file.
  mkdirSync(paths.invoicesIssued, { recursive: true });
  if (!payload) {
    try {
      payload = JSON.parse(invoice.payload_json) as IssuedInvoicePdfPayload;
    } catch {
      return { ok: false, appliedRules: [RULE_ID], errors: [`invoice ${invoiceNumber} has invalid payload_json`] };
    }
  }
  // Payment details from the payload win; otherwise pull them from the ledger.
  const currency = (payload.currency ?? "DKK").trim().toUpperCase();
  const payment = payload.payment ?? resolvePaymentDetails(db, currency);
  const bytes = buildIssuedInvoicePdf({
    ...payload,
    invoiceNumber,
    status: payload.status ?? invoice.status ?? "issued",
    ...(payment ? { payment } : {}),
  });
  const hash = sha256(bytes);
  let tempPath: string | undefined;

  try {
    const result = db.transaction(() => {
      const concurrentEvidence = db.query(
        `SELECT id FROM documents WHERE document_type = ? AND invoice_no = ? ORDER BY id ASC`,
      ).all(PDF_DOCUMENT_TYPE, invoiceNumber) as Array<{ id: number }>;
      if (concurrentEvidence.length > 0) {
        throw new Error(`issued invoice PDF evidence for ${invoiceNumber} appeared concurrently; retry to verify it`);
      }

      tempPath = writeTempFileFor(storedPath, bytes);

      const inserted = db.query(
        `INSERT INTO documents (
          document_no, source, original_filename, stored_path, mime_type, sha256_hash,
          supplier_name, invoice_no, invoice_date, amount_inc_vat, currency, status,
          document_type, sender_name, sender_address, sender_vat_cvr,
          recipient_name, recipient_address, recipient_vat_cvr, vat_amount, payload_json, retain_until
        ) VALUES (?, 'rentemester', ?, ?, 'application/pdf', ?, ?, ?, ?, ?, ?, 'issued', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        RETURNING id`
      ).get(
        `${invoiceNumber}-pdf`,
        `${invoiceNumber}.pdf`,
        storedPath,
        hash,
        payload.seller?.name ?? null,
        invoiceNumber,
        invoice.invoice_date ?? payload.issueDate ?? null,
        payload.totals?.grossAmount ?? null,
        payload.currency ?? "DKK",
        PDF_DOCUMENT_TYPE,
        payload.seller?.name ?? null,
        payload.seller?.address ?? null,
        payload.seller?.vatOrCvr ?? null,
        payload.buyer?.name ?? null,
        payload.buyer?.address ?? null,
        payload.buyer?.vatOrCvr ?? null,
        payload.totals?.vatAmount ?? null,
        invoice.payload_json,
        invoice.retain_until ?? null,
      ) as { id: number };

      strengthenGdprErasureAliasesForIdentity(db, {
        name: payload.seller?.name,
        cvr: payload.seller?.vatOrCvr,
      });
      strengthenGdprErasureAliasesForIdentity(db, {
        name: payload.buyer?.name,
        cvr: payload.buyer?.vatOrCvr,
      });

      insertAuditLog(db, {
        eventType: "invoice_render_pdf",
        entityType: "document",
        entityId: inserted.id,
        message: `Rendered invoice PDF ${invoiceNumber}`,
      });

      return { renderDocumentId: inserted.id };
    }).immediate();

    promoteTempFileExclusive(tempPath!, storedPath);
    return { ok: true, renderDocumentId: result.renderDocumentId, invoiceNumber, storedPath, sha256: hash, appliedRules: [RULE_ID], errors: [] };
  } catch (error) {
    if (tempPath) removeIfExists(tempPath);
    return { ok: false, appliedRules: [RULE_ID], errors: [String(error)] };
  }
}

function compact(value: string | null | undefined) {
  const trimmed = value?.trim();
  return trimmed ? trimmed : null;
}

export function snapshotRegisteredDocumentEvidence(
  companyRoot: string,
  input: RegisteredDocumentEvidenceInput,
): RegisteredDocumentSnapshot {
  const expectedSha256 = input.expectedSha256.trim().toLowerCase();
  if (!/^[a-f0-9]{64}$/.test(expectedSha256) || !input.documentType) {
    throw new DocumentEvidenceError("invalid_metadata");
  }
  const relativeStore = isIssuedDocumentEvidence(input.documentType)
    ? (["invoices", "issued"] as const)
    : (["documents", "originals"] as const);
  const parts = evidencePathParts(input.storedPath, relativeStore);
  const filename = parts.at(-1)!;
  const maxBytes = input.maxBytes ?? DOCUMENT_EVIDENCE_MAX_BYTES;
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 1) {
    throw new DocumentEvidenceError("invalid_metadata");
  }

  try {
    const lexicalRoot = resolve(companyRoot);
    const rootInfo = lstatSync(lexicalRoot);
    if (!rootInfo.isDirectory()) throw new DocumentEvidenceError("unsafe_store");
    const canonicalRoot = realpathSync(lexicalRoot);
    let lexicalStore = lexicalRoot;
    for (const segment of relativeStore) {
      lexicalStore = join(lexicalStore, segment);
      const info = lstatSync(lexicalStore);
      if (info.isSymbolicLink() || !info.isDirectory()) {
        throw new DocumentEvidenceError("unsafe_store");
      }
    }
    const canonicalStore = realpathSync(lexicalStore);
    if (!contained(canonicalRoot, canonicalStore)) {
      throw new DocumentEvidenceError("unsafe_store");
    }

    const candidate = join(canonicalStore, filename);
    const candidateInfo = lstatSync(candidate);
    if (candidateInfo.isSymbolicLink() || !candidateInfo.isFile()) {
      throw new DocumentEvidenceError("unsafe_file");
    }
    if (candidateInfo.size <= 0 || candidateInfo.size > maxBytes) {
      throw new DocumentEvidenceError("invalid_size");
    }
    const canonicalCandidate = realpathSync(candidate);
    if (!contained(canonicalStore, canonicalCandidate) || !contained(canonicalRoot, canonicalCandidate)) {
      throw new DocumentEvidenceError("unsafe_file");
    }

    let snapshot: DocumentSnapshot;
    try {
      snapshot = snapshotDocumentSource(candidate, maxBytes);
    } catch {
      throw new DocumentEvidenceError("unavailable");
    }
    if (snapshot.sha256 !== expectedSha256) {
      throw new DocumentEvidenceError("hash_mismatch");
    }
    return { ...snapshot, path: candidate };
  } catch (error) {
    if (error instanceof DocumentEvidenceError) throw error;
    throw new DocumentEvidenceError("unavailable");
  }
}

function resolvePaymentDetails(db: Database, currency: string): InvoicePaymentDetails | undefined {
  let rows: Array<{
    bank_name: string | null;
    registration_no: string | null;
    account_no: string | null;
    iban: string | null;
    bic: string | null;
    account_owner: string | null;
    customer_no: string | null;
    currency: string | null;
  }> = [];
  try {
    rows = db
      .query(
        `SELECT bank_name, registration_no, account_no, iban, bic, account_owner, customer_no, currency
           FROM bank_accounts
          WHERE active = 1
          ORDER BY id ASC`,
      )
      .all() as typeof rows;
  } catch {
    // The table may not exist in very old ledgers; payment block is optional.
    return undefined;
  }
  if (rows.length === 0) return undefined;
  const wanted = currency.trim().toUpperCase();
  const match =
    rows.find((row) => (row.currency ?? "").trim().toUpperCase() === wanted) ?? rows[0];
  const details: InvoicePaymentDetails = {
    bankName: match.bank_name,
    registrationNo: match.registration_no,
    accountNo: match.account_no,
    iban: match.iban,
    bic: match.bic,
    accountOwner: match.account_owner,
    customerNo: match.customer_no,
  };
  // Only return a block if at least one field carries real payment information.
  if (!compact(details.bankName) && !compact(details.registrationNo) && !compact(details.accountNo) && !compact(details.iban) && !compact(details.bic) && !compact(details.accountOwner) && !compact(details.customerNo)) {
    return undefined;
  }
  return details;
}

export function buildIssuedInvoicePdf(payload: IssuedInvoicePdfPayload) {
  const pages = layoutInvoice(payload);
  const issueDate = compact(payload.issueDate) ?? "1970-01-01";
  const pdfDate = `D:${issueDate.replace(/-/g, "")}000000Z`;
  const producer = "Rentemester deterministic invoice renderer";
  const title = `Faktura ${compact(payload.invoiceNumber) ?? ""}`.trim();

  // Object layout: 1 Catalog, 2 Pages, then per page a Page + Contents object,
  // then the two Font objects (F1, F2) and the Info object.
  const pageCount = pages.length;
  const pageObjectNos = pages.map((_, i) => 3 + i * 2);
  const fontRegularNo = 3 + pageCount * 2;
  const fontBoldNo = fontRegularNo + 1;
  const infoObjectNo = fontBoldNo + 1;

  const objects: string[] = [
    "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n",
    `2 0 obj\n<< /Type /Pages /Count ${pageCount} /Kids [${pageObjectNos.map((n) => `${n} 0 R`).join(" ")}] >>\nendobj\n`,
  ];
  pages.forEach((page, i) => {
    const pageNo = pageObjectNos[i];
    const contentNo = pageNo + 1;
    // ASCII separator (#225): a non-ASCII bullet/middle-dot in the footer
    // rendered as a broken glyph in some PDF viewers ("Faktura 2026-0001 <?>
    // Side 1"). A plain hyphen is safe in every viewer and font.
    const footer = `${title} - Side ${i + 1} af ${pageCount}`;
    const content = pageContentStream(page, footer);
    objects.push(
      `${pageNo} 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_WIDTH} ${PAGE_HEIGHT}] ` +
        `/Resources << /Font << /F1 ${fontRegularNo} 0 R /F2 ${fontBoldNo} 0 R >> >> /Contents ${contentNo} 0 R >>\nendobj\n`,
    );
    objects.push(
      `${contentNo} 0 obj\n<< /Length ${Buffer.byteLength(content, "binary")} >>\nstream\n${content}endstream\nendobj\n`,
    );
  });
  objects.push(
    `${fontRegularNo} 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>\nendobj\n`,
  );
  objects.push(
    `${fontBoldNo} 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>\nendobj\n`,
  );
  objects.push(
    `${infoObjectNo} 0 obj\n<< /Producer (${escapePdfText(producer)}) /Title (${escapePdfText(title)}) ` +
      `/CreationDate (${pdfDate}) /ModDate (${pdfDate}) >>\nendobj\n`,
  );

  let pdf = "%PDF-1.4\n%\xE2\xE3\xCF\xD3\n";
  const offsets: number[] = [0];
  for (const object of objects) {
    offsets.push(Buffer.byteLength(pdf, "binary"));
    pdf += object;
  }
  const xrefOffset = Buffer.byteLength(pdf, "binary");
  pdf += `xref\n0 ${objects.length + 1}\n`;
  pdf += "0000000000 65535 f \n";
  for (let i = 1; i < offsets.length; i += 1) {
    pdf += `${String(offsets[i]).padStart(10, "0")} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R /Info ${infoObjectNo} 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`;
  return Buffer.from(pdf, "binary");
}

function sha256(buffer: Uint8Array) {
  return createHash("sha256").update(buffer).digest("hex");
}

export function writeTempFileFor(finalPath: string, content: string | Uint8Array) {
  // Retry on the (vanishingly rare) random-name collision; never follow or
  // clobber an existing entry.
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const tempPath = randomTempPath(finalPath);
    let fd: number;
    try {
      fd = openSync(tempPath, EXCL_CREATE_FLAGS, 0o600);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "EEXIST") continue;
      throw error;
    }
    try {
      writeAllSync(fd, content);
      // KODE-7: flush the file's data+metadata to stable storage BEFORE close,
      // so a power loss after the subsequent rename cannot resurrect a
      // zero-length or partially-written file. Without this, write()+rename()
      // only orders the operations in the page cache — the bytes may still be
      // in flight when the crash hits, leaving an empty manifest/signature/tar.
      fsyncSync(fd);
    } finally {
      closeSync(fd);
    }
    return tempPath;
  }
  throw new Error(`failed to create exclusive temp file for ${finalPath}`);
}

export function strengthenGdprErasureAliasesForIdentity(
  db: Database,
  identity: { name?: string | null; cvr?: string | null },
): void {
  const subject = resolveSubject(identity);
  if (!subject.name || !subject.cvr) return;
  const nameReference = subjectAuditReference(`name:${subject.name}`);
  const priorNameErasure = db
    .query(
      `SELECT 1
         FROM gdpr_erasures
        WHERE subject_key IN (?, ?)
        LIMIT 1`,
    )
    .get(nameReference, subject.name);
  if (!priorNameErasure) return;

  const scopeResolution = resolveSubjectScope(db, subject);
  if (!scopeResolution.ok) return;
  const erasures = loadErasures(
    db,
    // The name may already have become ambiguous. It is safe to inspect its
    // old hash here because strengthenErasureAliases still requires exact CVR
    // evidence on each source row before creating a stable binding.
    [...scopeResolution.scope.erasureSubjectKeys, nameReference],
  );
  const rows = collectSourceRows(db, scopeResolution.scope);
  strengthenErasureAliases(db, scopeResolution.scope, rows, erasures);
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

export function promoteTempFileExclusive(tempPath: string, finalPath: string) {
  linkSync(tempPath, finalPath);
  removeIfExists(tempPath);
  fsyncDir(finalPath);
}

export function removeIfExists(path: string) {
  try {
    unlinkSync(path);
  } catch {
    // best effort cleanup
  }
}

typeDeclarations.source:
type InvoiceResolution =
  | { kind: "found"; documentId: number }
  | { kind: "no-flag" }
  | { kind: "not-found"; flag: "--document-id" | "--invoice-number"; value: string };

export type RenderIssuedInvoicePdfInput = {
  invoiceDocumentId: number;
};

export type RenderIssuedInvoicePdfResult = {
  ok: boolean;
  renderDocumentId?: number;
  invoiceNumber?: string;
  storedPath?: string;
  sha256?: string;
  appliedRules: string[];
  errors: string[];
};

export type IssuedInvoicePdfPayload = InvoicePayload & {
  invoiceNumber?: string;
  issuedAt?: string;
  status?: string;
  /** Payment instructions; injected from ledger bank-account data on render. */
  payment?: InvoicePaymentDetails;
  /**
   * Lightweight brand mark. A short text string is rendered as a styled word
   * mark in the header. This is a deliberate minimal seam: an image-based logo
   * can be added later without changing the call sites.
   */
  logoText?: string | null;
};

export type InvoicePayload = {
  invoiceType: InvoiceType;
  vatTreatment?: VatTreatment;
  issueDate?: string;
  invoiceNumber?: string;
  seller?: { name?: string; address?: string; vatOrCvr?: string };
  buyer?: InvoiceBuyer;
  /**
   * Peppol cbc:InvoicedQuantity/@unitCode (UN/ECE Rec 20). Defaults to H87
   * ("piece") in the e-invoice export; set per payload to override.
   */
  unitCode?: string;
  lines?: Array<{ description?: string; quantity?: number; unitPriceExVat?: number; lineTotalExVat?: number; unitCode?: string; taxClassification?: VatLineClassification; vatRate?: number; reverseChargeBasis?: string }>;
  totals?: {
    netAmount?: number;
    vatRate?: number;
    vatAmount?: number;
    grossAmount?: number;
    fxRateToDkk?: number;
    netAmountDkk?: number;
    vatAmountDkk?: number;
    grossAmountDkk?: number;
    vatComputationBasis?: "VAT_20_OF_GROSS" | string;
  };
  reverseChargeBasis?: ReverseChargeBasis;
  reverseChargeNote?: string;
  currency?: string;
  dueDate?: string;
  deliveryDate?: string;
  deliveryPeriodStart?: string;
  deliveryPeriodEnd?: string;
};

export type InvoiceBuyer = {
  name?: string;
  address?: string;
  vatOrCvr?: string;
  eanNumber?: string;
  publicRecipient?: boolean;
  /**
   * Peppol BIS 3.0 cbc:BuyerReference (BT-10). Mandatory for a public-recipient
   * e-invoice (PEPPOL-EN16931-R003) — the public authority's own reference
   * (often an "EAN-/ordrereference"). Without it the access point rejects the
   * invoice.
   */
  buyerReference?: string;
  /** Optional Peppol cac:OrderReference/cbc:ID (BT-13), the buyer's order id. */
  orderReference?: string;
};

export type ReverseChargeBasis =
  | "DK_MOMSLOVEN_§46_STK_1_NR_3"
  | "DK_MOMSLOVEN_§46_STK_1_NR_6"
  | "DK_MOMSLOVEN_§46_STK_1_NR_7"
  | "EU_MOMSDIREKTIV_ART_196"
  | "EU_MOMSDIREKTIV_ART_199";

export type InvoicePaymentDetails = {
  bankName?: string | null;
  /** Danish 4-digit bank registration number (registreringsnummer). */
  registrationNo?: string | null;
  /** Danish bank account number (kontonummer). */
  accountNo?: string | null;
  iban?: string | null;
  /** Optional SWIFT/BIC for foreign transfers. */
  bic?: string | null;
  accountOwner?: string | null;
  customerNo?: string | null;
};

export type RegisteredDocumentEvidenceInput = {
  storedPath: string;
  expectedSha256: string;
  documentType: string;
  maxBytes?: number;
};

export type DocumentSnapshot = {
  bytes: Buffer;
  sha256: string;
  filename: string;
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

