async (ctx) => {
    if ((ctx.arg("--confirm") ?? "").trim().toLowerCase() !== "yes") {
      ctx.emitResult({ ok: false, errors: ["--confirm yes required to transmit an e-invoice via Digisense"] });
      process.exit(1);
    }
    const root = ctx.companyRoot();
    const db = openDb(companyPaths(root).db);
    migrate(db);
    const documentId = resolveInvoiceDocumentId(db, ctx);
    const resolved = resolveDigisenseTransmitter(db, root, {
      companyKey: ctx.trimToNull(ctx.arg("--digisense-company-key") ?? null) ?? undefined,
    });
    if (!resolved.ok) {
      ctx.emitResult({ ok: false, appliedRules: [], errors: resolved.errors });
      db.close();
      process.exit(1);
    }
    // For Digisense ER access point'et Digisense selv (routing på companyKey +
    // license-key); transmitteren ignorerer accessPoint helt. Vi syntetiserer en
    // FAST, deterministisk access-point-identitet keyed på companyKey, så
    // gentaget transmit af samme faktura giver samme idempotency-nøgle og
    // kollapser på den eksisterende acknowledged-række i stedet for at levere
    // dobbelt. INTET --access-point skal opfindes af brugeren.
    const accessPoint: PeppolAccessPointConfig = digisenseAccessPointIdentity(resolved.companyKey);
    const result = await transmitPublicEInvoicePeppol(
      db,
      { invoiceDocumentId: documentId, accessPoint },
      resolved.transmitter,
    );
    ctx.emitResult(result as unknown as Record<string, unknown>);
    db.close();
    if (!result.ok || result.status === "failed" || result.status === "uncertain") process.exit(1);
  }

localBoundaryHelpers.source:
export function resolveInvoiceDocumentId(db: Db, ctx: CommandContext): number {
  const resolution = resolveInvoiceDocument(db, ctx);
  if (resolution.kind === "found") return resolution.documentId;
  if (resolution.kind === "no-flag") {
    console.error("Missing required --document-id <n> or --invoice-number <no>");
    db.close();
    process.exit(2);
  }
  // not-found: the call was well-formed; the invoice simply does not exist.
  const label =
    resolution.flag === "--invoice-number"
      ? `No issued invoice has invoice number ${resolution.value}`
      : `No issued invoice has document id ${resolution.value}`;
  ctx.emitResult({
    ok: false,
    appliedRules: [],
    errors: [`${label} — check the value with 'invoice list' or 'invoice find'`],
  });
  db.close();
  process.exit(1);
}

function resolveInvoiceDocument(db: Db, ctx: CommandContext): InvoiceResolution {
  const documentIdRaw = ctx.arg("--document-id");
  if (documentIdRaw !== undefined) {
    const documentId = Number(documentIdRaw);
    if (Number.isInteger(documentId) && documentId > 0) {
      const row = db
        .query(`SELECT id FROM documents WHERE document_type = 'issued_invoice' AND id = ? LIMIT 1`)
        .get(documentId) as { id: number } | null;
      if (row) return { kind: "found", documentId: row.id };
    }
    return { kind: "not-found", flag: "--document-id", value: String(documentIdRaw) };
  }
  const invoiceNumber = ctx.arg("--invoice-number")?.trim();
  if (invoiceNumber) {
    const row = db
      .query(
        `SELECT id FROM documents WHERE document_type = 'issued_invoice' AND invoice_no = ? LIMIT 1`,
      )
      .get(invoiceNumber) as { id: number } | null;
    if (row) return { kind: "found", documentId: row.id };
    return { kind: "not-found", flag: "--invoice-number", value: invoiceNumber };
  }
  return { kind: "no-flag" };
}

payloadTypes.source:
type InvoiceResolution =
  | { kind: "found"; documentId: number }
  | { kind: "no-flag" }
  | { kind: "not-found"; flag: "--document-id" | "--invoice-number"; value: string };

export type ResolveDigisenseTransmitter =
  | { ok: true; transmitter: PeppolTransmitter; companyKey: string }
  | { ok: false; errors: string[] };

export type PeppolTransmitter = (input: {
  oioublXml: string;
  oioublSha256: string;
  receiverEndpointId: string;
  accessPoint: PeppolAccessPointConfig;
}) => Promise<PeppolTransmissionOutcome> | PeppolTransmissionOutcome;

export type PeppolAccessPointConfig = {
  accessPointId: string;
  endpointUrl: string;
  senderEndpointId: string;
};

export type PeppolTransmissionOutcome =
  | { ok: true; transmissionId: string; transmittedAt: string }
  | {
      ok: false;
      error: string;
      /** A remote id proves provider acceptance and permanently forbids re-delivery. */
      acceptedDocumentId?: string;
      /** Provider status observed for the accepted document. */
      acceptedStatus?: string;
      /** Delivery POST completed ambiguously without a trustworthy remote id. */
      deliveryUncertain?: boolean;
