export function resolveDigisenseTransmitter(
  db: Database,
  companyRoot: string,
  options: { companyKey?: string; ksefEnvironment?: KsefEnvironment } = {},
): ResolveDigisenseTransmitter {
  const secret = loadDigisenseSecretConfig(companyRoot);
  if (!secret) {
    return { ok: false, errors: [digisenseNotConfiguredError("sendes")] };
  }

  const companyKey = resolveBoundDigisenseCompanyKey(db, options.companyKey);
  if (!companyKey.ok) return { ok: false, errors: companyKey.errors };

  const client = createDigisenseClient({
    apiLicenseKey: secret.apiLicenseKey,
    environment: secret.environment,
  });

  // KSeF uses PROD (not "PRODUCTION") as its production environment value.
  // hvis ikke eksplicit sat — så test-credentials aldrig rammer prod-routing.
  const ksefEnvironment =
    options.ksefEnvironment ?? (secret.environment === "production" ? "PROD" : "TEST");

  const transmitter = createDigisenseTransmitter(client, {
    companyKey: companyKey.value,
    ksefEnvironment,
  });
  return { ok: true, transmitter, companyKey: companyKey.value };
}

export function loadDigisenseSecretConfig(
  companyRoot: string,
): DigisenseSecretConfig | null {
  const path = digisenseConfigPath(companyRoot);
  if (!existsSync(path)) return null;
  const raw = readFileSync(path, "utf8");
  return JSON.parse(raw) as DigisenseSecretConfig;
}

function digisenseNotConfiguredError(action: string): string {
  return (
    `Digisense er ikke konfigureret: gem en API license-key først med ` +
    `\`rentemester efaktura konfigurer --company <path> --api-license-key <secret> ` +
    `--environment test|production\` (eller MCP-tool'et efaktura_konfigurer). Det skriver ` +
    `config/digisense.json (0600) før der kan ${action} e-fakturaer.`
  );
}

export function resolveBoundDigisenseCompanyKey(
  db: Database,
  explicit?: string,
): { ok: true; value: string } | { ok: false; errors: string[] } {
  const identity = resolveDigisenseIdentity(db);
  if (!identity.ok) return identity;
  const own = getDigisenseCompanyByParticipantId(db, identity.value.cvr);
  const key = explicit?.trim();
  if (key) {
    if (!own || own.companyKey !== key) return { ok: false, errors: ["The supplied DigiSense companyKey is not bound to this ledger's profile CVR."] };
    return { ok: true, value: key };
  }
  if (own) return { ok: true, value: own.companyKey };
  const count = listDigisenseCompanies(db).length;
  return { ok: false, errors: [count ? "DigiSense company state belongs to a different legal company; registration is required for this profile CVR." : "No DigiSense company is registered for this ledger's profile CVR." ] };
}

export function createDigisenseClient(
  config: DigisenseClientConfig,
  deps: DigisenseClientDeps = {},
): DigisenseClient {
  if (!config.apiLicenseKey?.trim()) {
    throw new Error("digisense client: apiLicenseKey is required");
  }
  const baseUrl = digisenseBaseUrl(config.environment);
  const httpFetch = deps.fetch ?? defaultHttpFetch();

  // Fælles headers. Authorization bærer license-key'en (én nøgle pr. licens).
  function authHeaders(contentType?: string): Record<string, string> {
    const headers: Record<string, string> = {
      Authorization: config.apiLicenseKey,
      Accept: "application/json",
    };
    if (contentType) headers["Content-Type"] = contentType;
    return headers;
  }

  // Udfør et kald og parse JSON-svaret. Ikke-2xx mappes til en tydelig
  // DigisenseError; transport-/parse-fejl bliver status 0 så kaldere altid får
  // et Result i stedet for en throw der lækker stack-traces til envelopen.
  async function requestJson<T>(request: HttpRequest): Promise<DigisenseResult<T>> {
    let response: HttpResponse;
    try {
      response = await httpFetch(request);
    } catch (error) {
      return {
        ok: false,
        error: {
          status: 0,
          message: `digisense transport error: ${error instanceof Error ? error.message : String(error)}`,
        },
      };
    }

    const rawBody = await response.text();

    if (response.status < 200 || response.status >= 300) {
      return {
        ok: false,
        error: {
          status: response.status,
          message: `digisense responded ${response.status}`,
          body: rawBody,
        },
      };
    }

    if (rawBody.trim().length === 0) {
      // Tomt 2xx-svar => tomt objekt (fx endpoints der kun signalerer succes).
      return { ok: true, status: response.status, data: {} as T };
    }

    try {
      return { ok: true, status: response.status, data: JSON.parse(rawBody) as T };
    } catch (error) {
      return {
        ok: false,
        error: {
          status: response.status,
          message: `digisense returned unparseable JSON: ${error instanceof Error ? error.message : String(error)}`,
          body: rawBody,
        },
      };
    }
  }

  return {
    validateAuth() {
      return requestJson<ValidateAuthResponse>({
        method: "GET",
        url: `${baseUrl}/validate-auth`,
        headers: authHeaders(),
      });
    },

    registerCompany(body) {
      return requestJson<RegisterCompanyResponse>({
        method: "POST",
        url: `${baseUrl}/register-company`,
        headers: authHeaders("application/json"),
        body: JSON.stringify(body),
      });
    },

    registerParticipant(network, body) {
      return requestJson<RegisterParticipantResponse>({
        method: "POST",
        // v1 is deprecated. v2 remains under the configured REST base URL.
        url: `${baseUrl}/v2/register-participant/${network}`,
        headers: authHeaders("application/json"),
        body: JSON.stringify(body),
      });
    },

    validateDocument(xml) {
      // Schematron-validering: XML-body som string, application/xml.
      return requestJson<ValidateDocumentResponse>({
        method: "POST",
        url: `${baseUrl}/validate-document`,
        headers: authHeaders("application/xml"),
        body: xml,
      });
    },

    lookupParticipant(query) {
      return requestJson<LookupParticipantResponse>({
        method: "GET",
        url: `${baseUrl}/lookup-participant${buildQuery({
          networkType: query.networkType,
          documentType: query.documentType,
          participantScheme: query.participantScheme,
          participantValue: query.participantValue,
        })}`,
        headers: authHeaders(),
      });
    },

    deliverDocument(xml, query) {
      // XML-faktura (<=10MB). companyKey + valgfrit ksefEnvironment i query.
      return requestJson<DeliverDocumentResponse>({
        method: "POST",
        url: `${baseUrl}/deliver-document${buildQuery({
          companyKey: query.companyKey,
          ksefEnvironment: query.ksefEnvironment,
        })}`,
        headers: authHeaders("application/xml"),
        body: xml,
      });
    },

    documentStatus(documentId, companyKey) {
      return requestJson<DocumentStatusResponse>({
        method: "GET",
        url: `${baseUrl}/document-status/${encodeURIComponent(documentId)}${buildQuery({ companyKey })}`,
        headers: authHeaders(),
      });
    },

    listReceivedDocuments(query) {
      return requestJson<ListReceivedDocumentsResponse>({
        method: "GET",
        url: `${baseUrl}/list-received-documents${buildQuery({
          limit: query.limit,
          offset: query.offset,
          maxTimestamp: query.maxTimestamp,
          companyKey: query.companyKey,
          networkType: query.networkType,
          participantType: query.participantType,
          participantId: query.participantId,
        })}`,
        headers: authHeaders(),
      });
    },
  };
}

export function createDigisenseTransmitter(
  client: DigisenseClient,
  deps: DigisenseTransmitterDeps,
): PeppolTransmitter {
  const companyKey = deps.companyKey?.trim();
  if (!companyKey) {
    throw new Error("digisense transmitter: companyKey is required");
  }
  const clock = deps.clock ?? defaultClock;
  const sleep = deps.sleep ?? defaultSleep;
  const pollIntervalMs = deps.pollIntervalMs ?? DEFAULT_POLL_INTERVAL_MS;
  const maxPollAttempts = deps.maxPollAttempts ?? DEFAULT_MAX_POLL_ATTEMPTS;

  return async (input): Promise<PeppolTransmissionOutcome> => {
    const xml = input.oioublXml;

    // 1. Schematron-gate. Afvis ved success=false — uden at røre deliver.
    const validation = await client.validateDocument(xml);
    if (!validation.ok) {
      return { ok: false, error: `digisense validate-document failed: ${validation.error.message}`, retryableBeforeDelivery: true };
    }
    if (!validation.data.success) {
      return {
        ok: false,
        error: `digisense schematron rejected the invoice: ${formatValidationErrors(validation.data.errors ?? [])}`,
        retryableBeforeDelivery: true,
      };
    }

    // 2. Lever dokumentet. companyKey + valgfrit ksefEnvironment scoper kaldet.
    const delivered = await client.deliverDocument(xml, {
      companyKey,
      ksefEnvironment: deps.ksefEnvironment,
    });
    if (!delivered.ok) {
      return {
        ok: false,
        error: `digisense deliver-document failed: ${safeDeliveryError(delivered.error)}`,
        // The POST may have reached DigiSense even when its response was lost,
        // timed out, failed 5xx, or could not be parsed. Without a trustworthy
        // document id, automatic retry would risk duplicate delivery.
        deliveryUncertain: true,
      };
    }

    const { documentId, documentStatus, statusCode } = delivered.data;
    if (!documentId || !documentStatus || !Number.isFinite(statusCode)) {
      return {
        ok: false,
        error: "digisense deliver-document returned an incomplete response after the delivery POST",
        deliveryUncertain: true,
      };
    }

    // 200/delivered => kvitteret med det samme; documentId er transmissionId'et.
    if (documentStatus === "delivered") {
      return { ok: true, transmissionId: documentId, transmittedAt: clock() };
    }

    // En terminal fejl-status allerede ved deliver (fx 4xx i body) afvises.
    if (TERMINAL_FAILURE_STATUSES.has(documentStatus)) {
      return {
        ok: false,
        error: `digisense delivery rejected (${documentStatus}) for document ${documentId}: ${delivered.data.message}`,
        acceptedDocumentId: documentId,
        acceptedStatus: documentStatus,
      };
    }

    // 3. 202/queued (eller transient): poll document-status til terminal.
    if (statusCode !== 202 && documentStatus !== "queued-for-delivery") {
      // Ukendt ikke-terminal tilstand uden 202 — behandl konservativt som fejl
      // i stedet for at poll'e i blinde.
      return {
        ok: false,
        error: `digisense delivery returned an unexpected status (${documentStatus}, code ${statusCode}) for document ${documentId}`,
        queuedDocumentId: documentId,
      };
    }

    try {
      for (let attempt = 0; attempt < maxPollAttempts; attempt += 1) {
        await sleep(pollIntervalMs);
        const status = await client.documentStatus(documentId, companyKey);
        if (!status.ok) {
          return { ok: false, error: `digisense document-status failed: ${status.error.message}`, queuedDocumentId: documentId };
        }
        const current = status.data.documentStatus;
        if (current === "delivered") {
          return { ok: true, transmissionId: documentId, transmittedAt: clock() };
        }
        if (TERMINAL_FAILURE_STATUSES.has(current)) {
          return {
            ok: false,
            error: `digisense delivery failed (${current}) for document ${documentId}: ${status.data.message}`,
            acceptedDocumentId: documentId,
            acceptedStatus: current,
          };
        }
        // queued-for-delivery / temporary-upstream-error => prøv igen.
      }
    } catch (error) {
      return {
        ok: false,
        error: `digisense document-status failed: ${error instanceof Error ? error.message : String(error)}`,
        queuedDocumentId: documentId,
      };
    }

    // Budget brugt op uden terminal status. Dokumentet er ACCEPTERET af
    // Digisense (202/queued) og leveres sandsynligvis asynkront — så en blind
    // retry der kalder deliver IGEN ville levere fakturaen TO gange. Vi bærer
    // documentId med som queuedDocumentId, så transmit-laget kan persistere en
    // ikke-terminal `prepared`-række og afvise re-deliver ved en senere kørsel
    // (den skal i stedet poll'e status på dette EKSISTERENDE documentId).
    return {
      ok: false,
      error: `digisense delivery timed out after ${maxPollAttempts} status polls for document ${documentId} (still queued, not yet delivered)`,
      queuedDocumentId: documentId,
    };
  };
}

const TERMINAL_FAILURE_STATUSES: ReadonlySet<DigisenseDocumentStatus> = new Set([
  "document-not-valid",
  "unable-to-deliver",
  "unknown-server-error",
]);

export function digisenseAccessPointIdentity(companyKey: string): PeppolAccessPointConfig {
  const key = companyKey.trim();
  return {
    accessPointId: "digisense",
    endpointUrl: "digisense:access-point",
    senderEndpointId: key,
  };
}

export async function transmitPublicEInvoicePeppol(
  db: Database,
  input: TransmitPublicEInvoicePeppolInput,
  transmitter: PeppolTransmitter,
): Promise<SubmitPublicEInvoicePeppolResult> {
  const configErrors = validateAccessPointConfig(input.accessPoint);
  if (configErrors.length > 0) {
    return { ok: false, appliedRules: [PEPPOL_SUBMIT_RULE_ID], errors: configErrors };
  }

  // Reuse the shipped OIOUBL handoff slice as the validated transport payload;
  // its own validation surfaces missing public-recipient metadata.
  const oioubl = exportPublicEInvoiceOioUbl(db, { invoiceDocumentId: input.invoiceDocumentId });
  if (!oioubl.ok || !oioubl.sha256 || !oioubl.xml) {
    return {
      ok: false,
      invoiceNumber: oioubl.invoiceNumber,
      appliedRules: [PEPPOL_SUBMIT_RULE_ID, ...oioubl.appliedRules],
      errors:
        oioubl.errors.length > 0
          ? oioubl.errors
          : ["PEPPOL transmission could not generate the required OIOUBL handoff artifact"],
    };
  }

  const { invoiceNumber, receiver, idempotencyKey } = deriveSubmissionIdentity(
    oioubl,
    input.invoiceDocumentId,
    input.accessPoint,
  );
  const oioublSha256 = oioubl.sha256;

  // Reserve the stable key in SQLite before yielding to any external transport.
  // The append-only event tells a concurrent caller whether it is in progress,
  // retryable after a pre-acceptance failure, or already queued at Digisense.
  const reservation = db.transaction(() => {
    const reference = `PEPPOL-${invoiceNumber}-${idempotencyKey.slice(0, 12)}`;
    const envelope = buildPeppolSubmissionEnvelope({ submissionReference: reference, idempotencyKey, invoiceNumber, accessPoint: input.accessPoint, receiverEndpointId: receiver, oioublSha256, status: "prepared" });
    runSql(db,
      `INSERT OR IGNORE INTO peppol_submissions
         (invoice_document_id, invoice_no, idempotency_key, submission_reference, access_point_id, receiver_endpoint_id, oioubl_sha256, envelope_sha256, envelope_xml, status, transmission_id, acknowledged_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'prepared', NULL, NULL)`,
      input.invoiceDocumentId, invoiceNumber, idempotencyKey, reference, input.accessPoint.accessPointId.trim(), receiver,
      oioublSha256, createHash("sha256").update(envelope).digest("hex"), envelope,
    );
    const row = db.query(
      `SELECT id, invoice_document_id, invoice_no, idempotency_key, submission_reference, access_point_id, receiver_endpoint_id, oioubl_sha256, envelope_sha256, envelope_xml, status, transmission_id, acknowledged_at FROM peppol_submissions WHERE idempotency_key = ?`,
    ).get(idempotencyKey) as PeppolSubmissionRow;
    const effective = effectiveAcknowledgement(db, row);
    if (row.status === "acknowledged" || effective) return { row, action: "acknowledged" as const, documentId: effective?.document_id ?? row.transmission_id };
    const latest = latestSubmissionEvent(db, row.id);
    const queued = queuedSubmissionEvent(db, row.id);
    if (queued && hasText(queued.document_id)) {
      const acceptedStatus = latest?.event_type === "status_observed" ? latest.status : queued.status;
      return { row, action: "accepted" as const, documentId: queued.document_id, acceptedStatus };
    }
    if (latest?.event_type === "delivery_failed" && latest.status !== "pre-acceptance-failed") {
      return { row, action: "uncertain" as const };
    }
    if (latest?.event_type === "delivery_reserved") return { row, action: "in_progress" as const };
    // A delivery_failed event proves the prior reservation never obtained a
    // remote id, so it is safe to create a new attempt rather than deadlock it.
    recordSubmissionEvent(db, row.id, "delivery_reserved", { message: "Reserved deterministic PEPPOL delivery attempt" });
    return { row, action: "deliver" as const };
  }).immediate();
  if (reservation.action === "acknowledged") return { ...rowToSubmissionResult(db, reservation.row, invoiceNumber, true), status: "acknowledged", transmissionId: reservation.documentId ?? undefined };
  if (reservation.action === "accepted") return { ok: true, invoiceNumber, submissionReference: reservation.row.submission_reference, idempotencyKey, status: isTerminalAcceptedFailure(reservation.acceptedStatus) ? "failed" : "prepared", duplicate: true, transmissionId: reservation.documentId, appliedRules: [PEPPOL_SUBMIT_RULE_ID], errors: [] };
  if (reservation.action === "uncertain") return { ok: true, invoiceNumber, submissionReference: reservation.row.submission_reference, idempotencyKey, status: "uncertain", duplicate: true, appliedRules: [PEPPOL_SUBMIT_RULE_ID], errors: [] };
  if (reservation.action === "in_progress") return { ok: false, invoiceNumber, submissionReference: reservation.row.submission_reference, idempotencyKey, status: "prepared", appliedRules: [PEPPOL_SUBMIT_RULE_ID], errors: [`PEPPOL transmission is already in progress for invoice ${invoiceNumber}; retry later or poll its queued status.`] };

  // Perform the transport. A thrown error is treated as a failed attempt.
  let outcome: PeppolTransmissionOutcome;
  try {
    outcome = await transmitter({
      oioublXml: oioubl.xml,
      oioublSha256: oioubl.sha256,
      receiverEndpointId: receiver,
      accessPoint: input.accessPoint,
    });
  } catch (error) {
    // A transmitter throw does not reveal whether its delivery POST reached
    // the provider. Fail closed: persist an uncertain result and forbid an
    // automatic second delivery.
    outcome = {
      ok: false,
      error: error instanceof Error ? error.message : String(error),
      deliveryUncertain: true,
    };
  }

  if (!outcome.ok) {
    insertAuditLog(db, {
      eventType: "public_einvoice_peppol_transmission",
      entityType: "document",
      entityId: input.invoiceDocumentId,
      message:
        `PEPPOL transmission failed for invoice ${invoiceNumber} ` +
        `via access point ${input.accessPoint.accessPointId.trim()}: ${outcome.error}`,
    });
    const acceptedDocumentId = outcome.acceptedDocumentId ?? outcome.queuedDocumentId;
    if (acceptedDocumentId) {
      const acceptedStatus = outcome.acceptedStatus ?? "queued-for-delivery";
      recordSubmissionEvent(db, reservation.row.id, "queued", { documentId: acceptedDocumentId, status: acceptedStatus, message: outcome.error });
      insertAuditLog(db, {
        eventType: "public_einvoice_peppol_transmission",
        entityType: "document",
        entityId: input.invoiceDocumentId,
        message:
          `PEPPOL transmission for invoice ${invoiceNumber} was accepted by the access point ` +
          `(documentId ${acceptedDocumentId}, status ${acceptedStatus}); recorded accepted evidence to prevent a re-deliver. ` +
          `Observe only the existing documentId; never retry transmit.`,
      });
      return {
        // The provider assigned a remote identity. Persisted state is the
        // authority: callers reload into queued or terminal-failed mode.
        ok: true,
        invoiceNumber,
        submissionReference: reservation.row.submission_reference,
        idempotencyKey,
        status: isTerminalAcceptedFailure(acceptedStatus) ? "failed" : "prepared",
        transmissionId: acceptedDocumentId,
        appliedRules: [PEPPOL_SUBMIT_RULE_ID],
        errors: [],
      };
    }
    if (outcome.deliveryUncertain || !outcome.retryableBeforeDelivery) {
      recordSubmissionEvent(db, reservation.row.id, "delivery_failed", {
        status: "delivery-uncertain",
        message: outcome.error,
      });
      insertAuditLog(db, {
        eventType: "public_einvoice_peppol_transmission",
        entityType: "document",
        entityId: input.invoiceDocumentId,
        message: `PEPPOL delivery outcome is uncertain for invoice ${invoiceNumber}; automatic re-delivery is blocked pending manual provider reconciliation.`,
      });
      return {
        ok: true,
        invoiceNumber,
        submissionReference: reservation.row.submission_reference,
        idempotencyKey,
        status: "uncertain",
        appliedRules: [PEPPOL_SUBMIT_RULE_ID],
        errors: [],
      };
    }
    recordSubmissionEvent(db, reservation.row.id, "delivery_failed", {
      status: "pre-acceptance-failed",
      message: outcome.error,
    });
    return {
      ok: false,
      invoiceNumber,
      appliedRules: [PEPPOL_SUBMIT_RULE_ID],
      errors: [`PEPPOL transmission failed: ${outcome.error}`],
    };
  }

  // `peppol_submissions` is immutable: delivery is represented by an event.
  recordSubmissionEvent(db, reservation.row.id, "delivered", { documentId: outcome.transmissionId, status: "delivered", observedAt: outcome.transmittedAt, message: "Delivery acknowledged by access point" });
  const submitted = { ...rowToSubmissionResult(db, reservation.row, invoiceNumber, false), status: "acknowledged" as const };
  insertAuditLog(db, {
    eventType: "public_einvoice_peppol_transmission",
    entityType: "document",
    entityId: input.invoiceDocumentId,
    message:
      `Transmitted invoice ${invoiceNumber} via access point ${input.accessPoint.accessPointId.trim()} ` +
      `(transmission ${outcome.transmissionId}, status ${submitted.status})`,
  });
  return { ...submitted, transmissionId: outcome.transmissionId };
}

function validateAccessPointConfig(config: PeppolAccessPointConfig | undefined): string[] {
  const errors: string[] = [];
  if (!config) {
    errors.push("PEPPOL submission requires access-point config (accessPointId, endpointUrl, senderEndpointId)");
    return errors;
  }
  if (!hasText(config.accessPointId)) errors.push("PEPPOL submission requires a non-empty access-point id");
  if (!hasText(config.endpointUrl)) errors.push("PEPPOL submission requires a non-empty access-point endpointUrl");
  if (!hasText(config.senderEndpointId)) errors.push("PEPPOL submission requires a non-empty access-point senderEndpointId");
  return errors;
}

export function exportPublicEInvoiceOioUbl(
  db: Database,
  input: ExportPublicEInvoiceInput,
): ExportPublicEInvoiceResult {
  const row = loadExportedInvoice(db, input);

  if (!row) {
    return { ok: false, appliedRules: [OIOUBL_RULE_ID], errors: [`invoice ${input.invoiceDocumentId} was not found`] };
  }
  if (row.document_type !== "issued_invoice") {
    return { ok: false, appliedRules: [OIOUBL_RULE_ID], errors: [`document ${input.invoiceDocumentId} is not an issued invoice`] };
  }
  if (!row.payload_json) {
    return { ok: false, appliedRules: [OIOUBL_RULE_ID], errors: [`invoice ${row.invoice_no ?? input.invoiceDocumentId} is missing payload_json`] };
  }

  const payload = JSON.parse(row.payload_json) as InvoicePayload & { invoiceNumber?: string };
  const invoiceNumber = payload.invoiceNumber ?? row.invoice_no ?? String(input.invoiceDocumentId);
  const eanNumber = normalizeEanNumber(payload.buyer?.eanNumber);

  if (payload.buyer?.publicRecipient !== true && !eanNumber) {
    return {
      ok: false,
      appliedRules: [OIOUBL_RULE_ID],
      errors: [`invoice ${invoiceNumber} is not marked as a public-recipient e-invoice`],
    };
  }

  const normalizedPayload: InvoicePayload = {
    ...payload,
    currency: (payload.currency ?? "DKK").trim().toUpperCase(),
    buyer: {
      ...payload.buyer,
      eanNumber: eanNumber ?? undefined,
      publicRecipient: true,
    },
  };

  const errors = validateOioUblPayload(invoiceNumber, normalizedPayload, eanNumber);
  if (errors.length > 0) {
    return {
      ok: false,
      appliedRules: [OIOUBL_RULE_ID],
      errors,
    };
  }

  const xml = buildPublicEInvoiceOioUblXml(invoiceNumber, normalizedPayload);
  const sha256 = createHash("sha256").update(xml).digest("hex");
  if (input.outPath) writeFileSync(input.outPath, xml);
  insertAuditLog(db, {
    eventType: "public_einvoice_oioubl_export",
    entityType: "document",
    entityId: row.id,
    message: `Generated public OIOUBL handoff artifact for invoice ${invoiceNumber} (sha256 ${sha256})`,
  });

  return {
    ok: true,
    invoiceNumber,
    outPath: input.outPath,
    sha256,
    xml,
    appliedRules: [OIOUBL_RULE_ID],
    errors: [],
  };
}

function deriveSubmissionIdentity(
  oioubl: ExportPublicEInvoiceResult,
  invoiceDocumentId: number,
  accessPoint: PeppolAccessPointConfig,
) {
  const invoiceNumber = oioubl.invoiceNumber ?? String(invoiceDocumentId);
  const endpointMatch = oioubl.xml?.match(
    new RegExp(`<cbc:EndpointID schemeID="${BUYER_ENDPOINT_SCHEME_ID}">([^<]+)</cbc:EndpointID>`),
  );
  const endpointValue = endpointMatch?.[1];
  const receiver = endpointValue
    ? `${BUYER_ENDPOINT_SCHEME_ID}:${endpointValue}`
    : `${BUYER_ENDPOINT_SCHEME_ID}:unknown`;
  const idempotencyKey = createHash("sha256")
    .update(
      [
        invoiceNumber,
        oioubl.sha256 ?? "",
        accessPoint.accessPointId.trim(),
        accessPoint.senderEndpointId.trim(),
        receiver,
      ].join("|"),
    )
    .digest("hex");
  return { invoiceNumber, receiver, idempotencyKey };
}

function buildPeppolSubmissionEnvelope(args: {
  submissionReference: string;
  idempotencyKey: string;
  invoiceNumber: string;
  accessPoint: PeppolAccessPointConfig;
  receiverEndpointId: string;
  oioublSha256: string;
  status: "prepared" | "acknowledged";
  acknowledgement?: PeppolTransportAcknowledgement;
}) {
  // The envelope is fully derived from deterministic inputs (no timestamps,
  // no random ids) so re-running on identical inputs yields an identical
  // artifact. It references the OIOUBL handoff by hash rather than embedding
  // (and thus risking mutation of) the original invoice payload.
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    `<PeppolSubmission xmlns="urn:${PEPPOL_ENVELOPE_VERSION}">`,
    xmlTag("SubmissionReference", args.submissionReference, "  "),
    xmlTag("IdempotencyKey", args.idempotencyKey, "  "),
    xmlTag("Status", args.status, "  "),
    "  <Document>",
    xmlTag("InvoiceNumber", args.invoiceNumber, "    "),
    xmlTag("Format", OIOUBL_CUSTOMIZATION_ID, "    "),
    xmlTag("Profile", OIOUBL_PROFILE_ID, "    "),
    xmlTag("HandoffArtifactSha256", args.oioublSha256, "    "),
    "  </Document>",
    "  <AccessPoint>",
    xmlTag("AccessPointId", args.accessPoint.accessPointId, "    "),
    xmlTag("EndpointUrl", args.accessPoint.endpointUrl, "    "),
    xmlTag("SenderEndpointId", args.accessPoint.senderEndpointId, "    "),
    xmlTag("ReceiverEndpointId", args.receiverEndpointId, "    "),
    "  </AccessPoint>",
    args.acknowledgement
      ? [
          "  <Acknowledgement>",
          xmlTag("TransmissionId", args.acknowledgement.transmissionId, "    "),
          xmlTag("AcknowledgedAt", args.acknowledgement.acknowledgedAt, "    "),
          "  </Acknowledgement>",
        ].join("\n")
      : "",
    "</PeppolSubmission>",
    "",
  ].filter((line) => line !== "").join("\n");
}

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[]
): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  bindings: SQLQueryBindings[],
): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[] | [SQLQueryBindings[]]
): ReturnType<Database["run"]> {
  const normalized = bindings.length === 1 && Array.isArray(bindings[0])
    ? bindings[0]
    : bindings as SQLQueryBindings[];
  return db.run(sql, normalized);
}

function effectiveAcknowledgement(
  db: Database,
  row: PeppolSubmissionRow,
): { document_id: string; observed_at: string } | null {
  const event = db.query(
    `SELECT document_id, observed_at FROM peppol_submission_events
     WHERE submission_id = ? AND event_type = 'delivered' ORDER BY id DESC LIMIT 1`,
  ).get(row.id) as PeppolSubmissionEventRow | null;
  if (event) return event;

  // Databases created before the append-only event migration stored the
  // acknowledgement on the immutable submission row. Preserve that evidence
  // as a read-only fallback so an upgrade can never make a delivered invoice
  // appear unsent (and therefore tempt a duplicate delivery).
  if (row.status === "acknowledged" && row.transmission_id) {
    return {
      document_id: row.transmission_id,
      observed_at: row.acknowledged_at ?? "",
    };
  }
  return null;
}

function latestSubmissionEvent(db: Database, submissionId: number): PeppolSubmissionEventRow | null {
  return db.query(
    `SELECT event_type, document_id, observed_at, status
       FROM peppol_submission_events WHERE submission_id = ? ORDER BY id DESC LIMIT 1`,
  ).get(submissionId) as PeppolSubmissionEventRow | null;
}

function queuedSubmissionEvent(db: Database, submissionId: number): PeppolSubmissionEventRow | null {
  return db.query(
    `SELECT event_type, document_id, observed_at, status
       FROM peppol_submission_events
      WHERE submission_id = ? AND event_type = 'queued'
      ORDER BY id DESC LIMIT 1`,
  ).get(submissionId) as PeppolSubmissionEventRow | null;
}

function hasText(value: string | null | undefined): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function recordSubmissionEvent(
  db: Database,
  submissionId: number,
  eventType: PeppolSubmissionEventRow["event_type"],
  args: { documentId?: string; status?: string; observedAt?: string; message?: string; publicUrl?: string | null } = {},
): void {
  runSql(db,
    `INSERT INTO peppol_submission_events
       (submission_id, event_type, document_id, status, observed_at, message, public_url)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    submissionId, eventType, args.documentId ?? null, args.status ?? null,
    args.observedAt ?? new Date().toISOString(), args.message ?? "", args.publicUrl ?? null,
  );
}

function rowToSubmissionResult(
  db: Database,
  row: PeppolSubmissionRow,
  invoiceNumber: string,
  duplicate: boolean,
  outPath?: string,
): SubmitPublicEInvoicePeppolResult {
  const acknowledgement = effectiveAcknowledgement(db, row);
  if (outPath) writeFileSync(outPath, row.envelope_xml);
  return {
    ok: true,
    invoiceNumber,
    submissionReference: row.submission_reference,
    idempotencyKey: row.idempotency_key,
    oioublSha256: row.oioubl_sha256,
    envelopeSha256: row.envelope_sha256,
    envelope: row.envelope_xml,
    status: acknowledgement ? "acknowledged" : "prepared",
    duplicate,
    outPath,
    transmissionId: acknowledgement?.document_id,
    appliedRules: [PEPPOL_SUBMIT_RULE_ID],
    errors: [],
  };
}

function isTerminalAcceptedFailure(status: string | null | undefined): boolean {
  return Boolean(status && TERMINAL_ACCEPTED_FAILURE_STATUSES.has(status));
}

const TERMINAL_ACCEPTED_FAILURE_STATUSES = new Set([
  "document-not-valid",
  "unable-to-deliver",
  "unknown-server-error",
]);

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

typeDeclarations.source:
type InvoiceResolution =
  | { kind: "found"; documentId: number }
  | { kind: "no-flag" }
  | { kind: "not-found"; flag: "--document-id" | "--invoice-number"; value: string };

export type ResolveDigisenseTransmitter =
  | { ok: true; transmitter: PeppolTransmitter; companyKey: string }
  | { ok: false; errors: string[] };

export type PeppolTransmitter = (input: {
  oioublXml: string;
  oioublSha256: string;
  receiverEndpointId: string;
  accessPoint: PeppolAccessPointConfig;
}) => Promise<PeppolTransmissionOutcome> | PeppolTransmissionOutcome;

export type PeppolAccessPointConfig = {
  accessPointId: string;
  endpointUrl: string;
  senderEndpointId: string;
};

export type PeppolTransmissionOutcome =
  | { ok: true; transmissionId: string; transmittedAt: string }
  | {
      ok: false;
      error: string;
      /** A remote id proves provider acceptance and permanently forbids re-delivery. */
      acceptedDocumentId?: string;
      /** Provider status observed for the accepted document. */
      acceptedStatus?: string;
      /** Delivery POST completed ambiguously without a trustworthy remote id. */
      deliveryUncertain?: boolean;
      /** Explicit proof that failure happened before any delivery POST. */
      retryableBeforeDelivery?: boolean;
      /** @deprecated Compatibility alias for acceptedDocumentId. */
      queuedDocumentId?: string;
    };

export type DigisenseSecretConfig = {
  /** API license-key — én nøgle for hele licensen. Aldrig i ledgeren. */
  apiLicenseKey: string;
  /** prod/test base-URL switch. Default 'test' når udeladt ved skrivning. */
  environment: DigisenseEnvironment;
};

export type DigisenseClientConfig = {
  /** API license-key — sendes i Authorization-header. Aldrig i ledgeren. */
  apiLicenseKey: string;
  /** prod/test base-URL switch. */
  environment: DigisenseEnvironment;
};

export type DigisenseClientDeps = {
  /** Injicérbar transport. Default wrapper om global fetch når udeladt. */
  fetch?: HttpFetch;
};

export type HttpRequest = {
  method: "GET" | "POST";
  url: string;
  headers: Record<string, string>;
  body?: string;
};

export type HttpResponse = {
  status: number;
  /** Rå svar-body (JSON eller XML som tekst). */
  text(): Promise<string>;
};

export type DigisenseClient = {
  validateAuth(): Promise<DigisenseResult<ValidateAuthResponse>>;
  registerCompany(
    body: RegisterCompanyRequest,
  ): Promise<DigisenseResult<RegisterCompanyResponse>>;
  registerParticipant(
    network: DigisenseNetwork,
    body: RegisterParticipantRequest,
  ): Promise<DigisenseResult<RegisterParticipantResponse>>;
  /** Schematron-validér FØR send. XML-body som string. */
  validateDocument(
    xml: string,
  ): Promise<DigisenseResult<ValidateDocumentResponse>>;
  lookupParticipant(
    query: LookupParticipantQuery,
  ): Promise<DigisenseResult<LookupParticipantResponse>>;
  /** Lever XML-faktura. XML-body som string. 202 => poll status. */
  deliverDocument(
    xml: string,
    query: DeliverDocumentQuery,
  ): Promise<DigisenseResult<DeliverDocumentResponse>>;
  documentStatus(
    documentId: string,
    companyKey: string,
  ): Promise<DigisenseResult<DocumentStatusResponse>>;
  listReceivedDocuments(
    query: ListReceivedDocumentsQuery,
  ): Promise<DigisenseResult<ListReceivedDocumentsResponse>>;
};

export type DigisenseResult<T> =
  | { ok: true; status: number; data: T }
  | { ok: false; error: DigisenseError };

export type DigisenseError = {
  /** HTTP-status fra access point (eller 0 ved transport-/parse-fejl). */
  status: number;
  /** Kort, sikker besked egnet til at lægge i en envelope. */
  message: string;
  /** Rå svar-body, hvis tilgængelig (til diagnostik/audit). */
  body?: string;
};

export type ValidateAuthResponse = {
  apiLicenseKey: string;
  label: string;
  /** UUID — HMAC-secret til webhook-signaturer. */
  signatureSecret: string;
  testGlnNumber: string;
  /** Begrænsning på companyKey, eller null hvis ubegrænset. */
  companyKeyConstraint: string | null;
};

export type RegisterCompanyRequest = {
  companyType: DigisenseCompanyType;
  companyName: string;
};

export type DigisenseCompanyType =
  | { type: "DK:CVR"; id: string }
  | { type: "NIP"; id: string };

export type RegisterCompanyResponse = {
  /** base64url — scoper næsten alle efterfølgende kald. */
  companyKey: string;
  message: string;
};

export type RegisterParticipantRequest = {
  direction: ParticipantDirection;
  participantType: ParticipantType;
  participantId: string;
  companyKey: string;
  /** null => ingen webhook; man poller selv (bekræftet designvalg). */
  webhookUrl: string | null;
  documentProfiles: string;
};

export type RegisterParticipantResponse = {
  registeredOnNetwork: boolean;
  webhookRegistered: boolean;
};

export type ValidateDocumentResponse = {
  statusCode: number;
  success: boolean;
  errors: ValidateDocumentError[];
};

export type ValidateDocumentError = {
  context: string;
  pattern: string;
  description: string;
  xpath: string;
  type: "error" | "warning";
};

export type LookupParticipantQuery = {
  networkType: LookupNetworkType;
  documentType?: string;
  /** fx "DK:CVR", "0184", "0088", "GLN". */
  participantScheme: string;
  participantValue: string;
};

export type LookupParticipantResponse = {
  participantAbleToReceive: boolean;
  matchedServiceEndpointUrls: string[];
  matchedDocumentTypes: string[];
};

export type DeliverDocumentQuery = {
  companyKey: string;
  ksefEnvironment?: KsefEnvironment;
};

export type DeliverDocumentResponse = {
  /** 200 delivered | 202 queued | 4xx/5xx. */
  statusCode: number;
  documentStatus: DigisenseDocumentStatus;
  documentId: string;
  message: string;
  publicUrl: string;
};

export type DocumentStatusResponse = {
  statusCode: number;
