export function issueCreditNote(db: Database, companyRoot: string, input: IssueCreditNoteInput): IssueCreditNoteResult {
  const errors: string[] = [];
  if (!Number.isInteger(input.originalInvoiceDocumentId) || input.originalInvoiceDocumentId <= 0) errors.push("originalInvoiceDocumentId must be a positive integer");
  if (!looksLikeIsoDate(input.issueDate)) errors.push("issueDate must be YYYY-MM-DD");
  if (typeof input.reason !== "string" || input.reason.trim().length === 0) errors.push("reason is required");
  if (errors.length > 0) return { ok: false, appliedRules: [RULE_ID], errors };

  const original = db.query(
    `SELECT id, invoice_no, amount_inc_vat, currency, vat_amount, payload_json, document_type
     FROM documents WHERE id = ?`
  ).get(input.originalInvoiceDocumentId) as any | null;
  if (!original) return { ok: false, appliedRules: [RULE_ID], errors: [`invoice document ${input.originalInvoiceDocumentId} does not exist`] };
  if (original.document_type !== "issued_invoice") return { ok: false, appliedRules: [RULE_ID], errors: [`document ${input.originalInvoiceDocumentId} is not an issued invoice`] };

  const payload = original.payload_json ? JSON.parse(original.payload_json) : null;
  const originalGrossAmount = roundDkk(Number(original.amount_inc_vat ?? payload?.totals?.grossAmount ?? 0));
  const originalVatAmount = roundDkk(Number(original.vat_amount ?? payload?.totals?.vatAmount ?? 0));
  const explicitCreditNoteNumber = input.creditNoteNumber?.trim();
  if (explicitCreditNoteNumber) {
    const scopeError = validateManualCreditNoteNumberScope(db, input.issueDate, explicitCreditNoteNumber);
    if (scopeError) return { ok: false, appliedRules: [RULE_ID], errors: [scopeError] };
  }
  const paths = companyPaths(companyRoot);
  mkdirSync(paths.invoicesIssued, { recursive: true });
  let tempPath: string | undefined;
  let storedPath: string | undefined;
  let storedPathPromoted = false;

  try {
    const result = db.transaction(() => {
      // Booking/reversal state and the cumulative credit cap are mutable. Read
      // and validate them only after BEGIN IMMEDIATE so concurrent issuers
      // cannot both consume the same remaining invoice amount.
      const originalBooking = resolveInvoiceReceivableAccount(db, {
        invoiceDocumentId: original.id,
      });
      if (!originalBooking.ok) {
        return {
          ok: false as const,
          error: `invoice ${original.invoice_no} must have explicit active invoice-posting evidence before a credit note can be issued: ${originalBooking.error}`,
        };
      }
      const priorEvidence = validateInvoiceCreditNoteEvidence(db, {
        invoiceDocumentId: original.id,
      });
      if (!priorEvidence.ok) {
        return { ok: false as const, error: priorEvidence.errors.join("; ") };
      }
      const creditedTotals = db.query(
        `SELECT COALESCE(SUM(c.amount_inc_vat), 0) AS total,
                COALESCE(SUM(c.vat_amount), 0) AS vat_total
           FROM documents c
           JOIN credit_note_postings p ON p.credit_note_document_id = c.id
          WHERE c.document_type = 'credit_note'
            AND p.original_invoice_document_id = ?`,
      ).get(original.id) as { total: number; vat_total: number };
      const creditedSoFar = roundDkk(Number(creditedTotals.total ?? 0));
      const creditedVatSoFar = roundDkk(Number(creditedTotals.vat_total ?? 0));
      const remainingGrossAmount = roundDkk(originalGrossAmount - creditedSoFar);
      if (remainingGrossAmount <= 0) {
        return { ok: false as const, error: `invoice ${original.invoice_no} is already fully credited` };
      }
      const grossAmount = roundDkk(input.grossAmount ?? remainingGrossAmount);
      if (!Number.isFinite(grossAmount) || grossAmount <= 0) {
        return { ok: false as const, error: "grossAmount must be a positive number when present" };
      }
      if (grossAmount > remainingGrossAmount) {
        return { ok: false as const, error: `credit amount ${grossAmount} exceeds remaining creditable amount ${remainingGrossAmount}` };
      }

      const creditedDkkSoFar = roundDkk(Number((db.query(
        `SELECT COALESCE(SUM(booked_gross_dkk), 0) AS total
           FROM credit_note_postings
          WHERE original_invoice_document_id = ?`,
      ).get(original.id) as { total: number }).total ?? 0));
      const cumulativeForeignCredit = roundDkk(creditedSoFar + grossAmount);
      const cumulativeVatCredit = cumulativeForeignCredit === originalGrossAmount
        ? originalVatAmount
        : roundDkk((originalVatAmount * cumulativeForeignCredit) / originalGrossAmount);
      const vatAmount = roundDkk(cumulativeVatCredit - creditedVatSoFar);
      const netAmount = roundDkk(grossAmount - vatAmount);
      const cumulativeDkkRelief = cumulativeForeignCredit === originalGrossAmount
        ? originalBooking.bookedGrossDkk
        : roundDkk((originalBooking.bookedGrossDkk * cumulativeForeignCredit) / originalGrossAmount);
      const bookedCreditDkk = roundDkk(cumulativeDkkRelief - creditedDkkSoFar);
      if (!(bookedCreditDkk > 0)) {
        return { ok: false as const, error: `invoice ${original.invoice_no} credit note has no positive remaining DKK receivable relief` };
      }
      const originalJournalLines = creditNoteLinesFromOriginalJournal(
        db,
        original.id,
        originalBooking.bookingJournalEntryId,
        originalGrossAmount,
        cumulativeForeignCredit,
        originalBooking.accountNo,
        cumulativeDkkRelief,
      );
      if (!originalJournalLines) {
        return { ok: false as const, error: `invoice ${original.invoice_no} booking cannot be reversed into an exact credit-note journal` };
      }
      const actualBookedCreditDkk = roundDkk(originalJournalLines.reduce((sum, line) => {
        if (line.accountNo !== originalBooking.accountNo) return sum;
        return sum + Number(line.creditAmount ?? 0) - Number(line.debitAmount ?? 0);
      }, 0));
      if (actualBookedCreditDkk !== bookedCreditDkk) {
        return { ok: false as const, error: `invoice ${original.invoice_no} credit note does not reduce its booked receivable account` };
      }

      let creditNoteNumber = explicitCreditNoteNumber;
      if (creditNoteNumber) {
        const reserved = reserveManualCreditNoteNumber(db, input.issueDate, creditNoteNumber);
        if (!reserved.ok) return { ok: false as const, error: reserved.error };
      } else {
        creditNoteNumber = nextCreditNoteNumber(db, input.issueDate);
      }

      const creditPayload = {
        type: "credit_note",
        creditNoteNumber,
        originalInvoiceNumber: original.invoice_no,
        originalInvoiceDocumentId: original.id,
        issueDate: input.issueDate,
        reason: input.reason.trim(),
        grossAmount,
        vatAmount,
        netAmount,
        creditedSoFar,
        remainingAfterThisCredit: roundDkk(remainingGrossAmount - grossAmount),
        issuedAt: new Date().toISOString(),
      };
      const serialized = JSON.stringify(creditPayload, null, 2);
      const hash = sha256(serialized);
      storedPath = join(paths.invoicesIssued, `${creditNoteNumber}.json`);
      tempPath = writeTempFileFor(storedPath, serialized);

      const doc = db.query(
        `INSERT INTO documents (
          document_no, source, original_filename, stored_path, mime_type, sha256_hash,
          supplier_name, invoice_no, invoice_date, amount_inc_vat, currency, status,
          document_type, delivery_description, sender_name, sender_address, sender_vat_cvr,
          recipient_name, recipient_address, recipient_vat_cvr, vat_amount, payment_details, exemption_code, payload_json, retain_until
        ) VALUES (?, 'rentemester', ?, ?, 'application/json', ?, ?, ?, ?, ?, ?, 'issued', 'credit_note', ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?)
        RETURNING id`
      ).get(
        creditNoteNumber,
        `${creditNoteNumber}.json`,
        storedPath,
        hash,
        payload?.seller?.name ?? null,
        creditNoteNumber,
        input.issueDate,
        grossAmount,
        original.currency ?? 'DKK',
        `Credit note for ${original.invoice_no}: ${input.reason.trim()}`,
        payload?.seller?.name ?? null,
        payload?.seller?.address ?? null,
        payload?.seller?.vatOrCvr ?? null,
        payload?.buyer?.name ?? null,
        payload?.buyer?.address ?? null,
        payload?.buyer?.vatOrCvr ?? null,
        vatAmount,
        original.invoice_no,
        serialized,
        retainUntilForDate(db, input.issueDate),
      ) as { id: number };

      strengthenGdprErasureAliasesForIdentity(db, {
        name: payload?.seller?.name,
        cvr: payload?.seller?.vatOrCvr,
      });
      strengthenGdprErasureAliasesForIdentity(db, {
        name: payload?.buyer?.name,
        cvr: payload?.buyer?.vatOrCvr,
      });

      const journal = postJournalEntry(db, {
        transactionDate: input.issueDate,
        text: `Credit note ${creditNoteNumber} for invoice ${original.invoice_no}`,
        documentId: doc.id,
        currency: (original.currency ?? "DKK").trim().toUpperCase() === "DKK"
          ? undefined
          : (original.currency ?? "DKK").trim().toUpperCase(),
        amountForeign: (original.currency ?? "DKK").trim().toUpperCase() === "DKK"
          ? undefined
          : grossAmount,
        amountDkk: (original.currency ?? "DKK").trim().toUpperCase() === "DKK"
          ? undefined
          : bookedCreditDkk,
        fxRateToDkk: (original.currency ?? "DKK").trim().toUpperCase() === "DKK"
          ? undefined
          : bookedCreditDkk / grossAmount,
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
        lines: originalJournalLines,
      });
      if (!journal.ok) throw new TransactionRejectionError({ appliedRules: journal.appliedRules, errors: journal.errors });

      const receivableAccount = db.query(
        "SELECT id FROM accounts WHERE account_no = ?",
      ).get(originalBooking.accountNo) as { id: number } | null;
      if (!receivableAccount || journal.entryId == null) {
        throw new Error(`credit note ${creditNoteNumber} cannot persist its receivable posting evidence`);
      }
      runSql(db,
        `INSERT INTO credit_note_postings
           (credit_note_document_id, original_invoice_document_id, journal_entry_id,
            receivable_account_id, booked_gross_dkk)
         VALUES (?, ?, ?, ?, ?)`,
        doc.id,
        original.id,
        journal.entryId,
        receivableAccount.id,
        bookedCreditDkk,
      );
      const evidence = validateInvoiceCreditNoteEvidence(db, {
        invoiceDocumentId: original.id,
      });
      if (!evidence.ok) {
        throw new TransactionRejectionError({ appliedRules: [RULE_ID], errors: evidence.errors });
      }

      insertAuditLog(db, {
        eventType: "credit_note_issue",
        entityType: "document",
        entityId: doc.id,
        message: `Issued credit note ${creditNoteNumber} for ${original.invoice_no}`,
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
      });

      // Keep the legal snapshot and its financial evidence atomic from the
      // caller's perspective: a destination/promotion failure aborts the DB
      // transaction, while a later COMMIT failure removes the published file.
      promoteTempFileExclusive(tempPath!, storedPath!);
      storedPathPromoted = true;

      const treatment = payload?.vatTreatment ?? "standard";
      return { ok: true as const, docId: doc.id, creditNoteNumber, sha256: hash, journal, isReverseCharge: treatment === "domestic_reverse_charge" || treatment === "foreign_reverse_charge" };
    }).immediate();

    if (!result.ok) return { ok: false, appliedRules: [RULE_ID], errors: [result.error] };
    return {
      ok: true,
      documentId: result.docId,
      creditNoteNumber: result.creditNoteNumber,
      originalInvoiceNumber: original.invoice_no,
      storedPath,
      sha256: result.sha256,
      journalEntryId: result.journal.entryId,
      journalEntryNo: result.journal.entryNo,
      appliedRules: [...new Set([RULE_ID, ...(result.journal.appliedRules ?? []), ...(result.isReverseCharge ? [REVERSE_RULE_ID] : [])])],
      errors: [],
    };
  } catch (error) {
    if (tempPath) removeIfExists(tempPath);
    if (
      storedPathPromoted &&
      storedPath &&
      hasCommittedDocumentAtPath(db, storedPath) === false
    ) removeIfExists(storedPath);
    const parsed = decodeTransactionRejection(error);
    return {
      ok: false,
      appliedRules: [...new Set([RULE_ID, ...(parsed?.appliedRules ?? [])])],
      errors: parsed?.errors ?? [String(error)],
    };
  }
}

export function isValidIsoDate(value: unknown): value is string {
  if (typeof value !== "string") return false;
  const trimmed = value.trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return false;
  const date = new Date(`${trimmed}T00:00:00Z`);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === trimmed;
}

export function roundDkk(value: number) {
  return Number.isFinite(value) ? fromScaledInt(scaledInt(value, 2), 2) : NaN;
}

function validateManualCreditNoteNumberScope(db: Database, issueDate: string, creditNoteNumber: string) {
  const { scope } = creditNoteSequenceState(db, issueDate);
  const genericCanonical = /^CN-(\d{4})-(\d{4})$/.exec(creditNoteNumber);
  if (genericCanonical && genericCanonical[1] !== scope) {
    return `manual creditNoteNumber ${creditNoteNumber} does not match current fiscal scope ${scope}`;
  }
  return null;
}

export function resolveInvoiceReceivableAccount(
  db: Database,
  input: { invoiceDocumentId: number; beforeJournalEntryId?: number },
): InvoiceReceivableAccountResult {
  const cutoff = input.beforeJournalEntryId ?? null;
  const booking = db.query(
    `SELECT p.journal_entry_id AS id, p.booked_gross_dkk,
            p.receivable_account_id, a.account_no, a.type AS account_type,
            a.normal_balance, j.document_id, j.status, j.currency,
            j.transaction_date, j.source_bank_transaction_id,
            j.amount_foreign, j.amount_dkk, j.fx_rate_to_dkk,
            (SELECT reversal.id
               FROM journal_entries reversal
              WHERE reversal.reversal_of_entry_id = j.id
                AND (? IS NULL OR reversal.id < ?)
              ORDER BY reversal.id ASC
              LIMIT 1) AS reversed_by_entry_id
       FROM issued_invoice_postings p
       JOIN journal_entries j ON j.id = p.journal_entry_id
       JOIN accounts a ON a.id = p.receivable_account_id
      WHERE p.invoice_document_id = ?
        AND (? IS NULL OR j.id < ?)`,
  ).get(
    cutoff,
    cutoff,
    input.invoiceDocumentId,
    cutoff,
    cutoff,
  ) as {
    id: number;
    booked_gross_dkk: number;
    receivable_account_id: number;
    account_no: string;
    account_type: string;
    normal_balance: string;
    document_id: number | null;
    status: string;
    currency: string | null;
    transaction_date: string;
    source_bank_transaction_id: number | null;
    amount_foreign: number | null;
    amount_dkk: number | null;
    fx_rate_to_dkk: number | null;
    reversed_by_entry_id: number | null;
  } | null;
  if (!booking) {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} has no active ledger booking before settlement` };
  }

  const invoice = db.query(
    `SELECT invoice_date, amount_inc_vat, vat_amount, currency, payload_json, document_type
       FROM documents
      WHERE id = ?`,
  ).get(input.invoiceDocumentId) as {
    invoice_date: string | null;
    amount_inc_vat: number | null;
    vat_amount: number | null;
    currency: string | null;
    payload_json: string | null;
    document_type: string;
  } | null;
  if (!invoice || invoice.document_type !== "issued_invoice") {
    return { ok: false, error: `invoice posting link ${booking.id} does not reference an issued invoice document` };
  }
  let payload: any;
  try {
    payload = invoice.payload_json ? JSON.parse(invoice.payload_json) : null;
  } catch {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} has invalid booking payload JSON` };
  }
  const currency = normalizeCurrency(invoice.currency);
  const grossForeign = roundDkk(Number(invoice.amount_inc_vat ?? 0));
  const expectedGrossDkk = currency === "DKK"
    ? grossForeign
    : roundDkk(Number(payload?.totals?.grossAmountDkk ?? 0));
  const expectedVatDkk = currency === "DKK"
    ? roundDkk(Number(invoice.vat_amount ?? payload?.totals?.vatAmount ?? 0))
    : roundDkk(Number(payload?.totals?.vatAmountDkk ?? 0));
  const expectedNetDkk = currency === "DKK"
    ? roundDkk(expectedGrossDkk - expectedVatDkk)
    : roundDkk(Number(payload?.totals?.netAmountDkk ?? 0));
  const expectedFxRate = currency === "DKK" ? null : Number(payload?.totals?.fxRateToDkk ?? 0);
  if (!(grossForeign > 0) || !(expectedGrossDkk > 0)) {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} has no positive gross booking basis` };
  }
  if (!(expectedNetDkk > 0) || compareDkk(expectedNetDkk + expectedVatDkk, expectedGrossDkk) !== 0) {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} has inconsistent immutable DKK booking totals` };
  }
  if (booking.document_id !== input.invoiceDocumentId || booking.status !== "posted" || booking.reversed_by_entry_id != null) {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} booking ${booking.id} is not active, posted, and linked to the invoice` };
  }
  if (booking.transaction_date !== invoice.invoice_date || booking.source_bank_transaction_id != null) {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} booking ${booking.id} has invalid invoice-date or bank-source context` };
  }
  if (booking.account_type !== "asset" || booking.normal_balance !== "debit") {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} booking account ${booking.account_no} is not a debit-normal asset` };
  }
  if (compareDkk(Number(booking.booked_gross_dkk), expectedGrossDkk) !== 0) {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} booking ${booking.id} gross ${booking.booked_gross_dkk} DKK does not match invoice gross ${expectedGrossDkk} DKK` };
  }
  if (normalizeCurrency(booking.currency) !== currency) {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} booking ${booking.id} currency does not match the invoice` };
  }
  if (
    currency !== "DKK" &&
    (compareDkk(Number(booking.amount_foreign ?? 0), grossForeign) !== 0 ||
      compareDkk(Number(booking.amount_dkk ?? 0), expectedGrossDkk) !== 0)
  ) {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} booking ${booking.id} foreign/DKK metadata does not match the invoice` };
  }
  if (
    currency !== "DKK" &&
    (expectedFxRate == null || !Number.isFinite(expectedFxRate) || !(expectedFxRate > 0) ||
      Math.abs(Number(booking.fx_rate_to_dkk ?? 0) - expectedFxRate) > 0.0000005)
  ) {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} booking ${booking.id} FX rate metadata does not match the invoice` };
  }

  const totals = db.query(
    `SELECT COALESCE(SUM(debit_amount), 0) AS debit_dkk,
            COALESCE(SUM(credit_amount), 0) AS credit_dkk
       FROM journal_lines
      WHERE journal_entry_id = ?`,
  ).get(booking.id) as { debit_dkk: number; credit_dkk: number };
  if (
    compareDkk(Number(totals.debit_dkk), expectedGrossDkk) !== 0 ||
    compareDkk(Number(totals.credit_dkk), expectedGrossDkk) !== 0
  ) {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} booking ${booking.id} total debits/credits do not equal ${expectedGrossDkk} DKK` };
  }

  const candidates = db.query(
    `SELECT a.account_no,
            SUM(jl.debit_amount) - SUM(jl.credit_amount) AS amount_dkk
       FROM journal_lines jl
       JOIN accounts a ON a.id = jl.account_id
      WHERE jl.journal_entry_id = ?
        AND a.type = 'asset'
        AND a.normal_balance = 'debit'
      GROUP BY a.account_no
     HAVING ROUND(SUM(jl.debit_amount) - SUM(jl.credit_amount), 2) <> 0
      ORDER BY a.account_no ASC`,
  ).all(booking.id) as Array<{ account_no: string; amount_dkk: number }>;
  if (
    candidates.length !== 1 ||
    candidates[0]!.account_no !== booking.account_no ||
    compareDkk(Number(candidates[0]!.amount_dkk), expectedGrossDkk) !== 0
  ) {
    return {
      ok: false,
      error: `invoice document ${input.invoiceDocumentId} booking ${booking.id} does not debit exactly ${expectedGrossDkk} DKK to its linked receivable account`,
    };
  }

  const vatTreatment = payload?.vatTreatment ?? "standard";
  const projection = projectVatLines(payload?.lines, vatTreatment, payload?.totals?.vatRate);
  if (!projection.ok || projection.lines.length === 0 || !(projection.netAmount > 0)) {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} has no valid immutable VAT-line basis for booking ${booking.id}` };
  }
  const isDomesticReverseCharge = vatTreatment === "domestic_reverse_charge";
  const reverseChargeVatCode = isDomesticReverseCharge
    ? "DOMESTIC_REVERSE_CHARGE_EXEMPT"
    : "REVERSE_CHARGE_EXEMPT";
  const baseScale = expectedNetDkk / projection.netAmount;
  const expectedRevenueLines = projection.lines.map((line) => ({
    vatCode: line.taxClassification === "taxable"
      ? "DK_SALE_25"
      : line.taxClassification === "reverse_charge"
        ? reverseChargeVatCode
        : "VAT_EXEMPT",
    amountDkk: roundDkk(line.vatBase * baseScale),
  }));
  const roundedRevenue = roundDkk(expectedRevenueLines.reduce((sum, line) => sum + line.amountDkk, 0));
  if (expectedRevenueLines.length > 0 && compareDkk(roundedRevenue, expectedNetDkk) !== 0) {
    const last = expectedRevenueLines[expectedRevenueLines.length - 1]!;
    last.amountDkk = roundDkk(last.amountDkk + expectedNetDkk - roundedRevenue);
  }
  const expectedRevenueByVatCode = new Map<string, number>();
  for (const line of expectedRevenueLines) {
    expectedRevenueByVatCode.set(
      line.vatCode,
      roundDkk((expectedRevenueByVatCode.get(line.vatCode) ?? 0) + line.amountDkk),
    );
  }

  const counterLines = db.query(
    `SELECT a.type AS account_type, a.normal_balance,
            jl.debit_amount, jl.credit_amount, jl.vat_code
       FROM journal_lines jl
       JOIN accounts a ON a.id = jl.account_id
      WHERE jl.journal_entry_id = ?
        AND jl.account_id <> ?
      ORDER BY jl.id ASC`,
  ).all(booking.id, booking.receivable_account_id) as Array<{
    account_type: string;
    normal_balance: string;
    debit_amount: number;
    credit_amount: number;
    vat_code: string | null;
  }>;
  const actualRevenueByVatCode = new Map<string, number>();
  let actualVatDkk = 0;
  for (const line of counterLines) {
    if (line.account_type === "income" && line.normal_balance === "credit" && line.debit_amount === 0 && line.credit_amount > 0 && line.vat_code) {
      actualRevenueByVatCode.set(
        line.vat_code,
        roundDkk((actualRevenueByVatCode.get(line.vat_code) ?? 0) + Number(line.credit_amount)),
      );
      continue;
    }
    if (line.account_type === "vat" && line.normal_balance === "credit" && line.debit_amount === 0 && line.credit_amount > 0 && line.vat_code == null) {
      actualVatDkk = roundDkk(actualVatDkk + Number(line.credit_amount));
      continue;
    }
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} booking ${booking.id} contains an unsupported revenue/VAT counter-line` };
  }
  if (compareDkk(actualVatDkk, expectedVatDkk) !== 0) {
    return { ok: false, error: `invoice document ${input.invoiceDocumentId} booking ${booking.id} output VAT does not match ${expectedVatDkk} DKK` };
  }
  const revenueCodes = new Set([...expectedRevenueByVatCode.keys(), ...actualRevenueByVatCode.keys()]);
  for (const vatCode of revenueCodes) {
    if (compareDkk(actualRevenueByVatCode.get(vatCode) ?? 0, expectedRevenueByVatCode.get(vatCode) ?? 0) !== 0) {
      return { ok: false, error: `invoice document ${input.invoiceDocumentId} booking ${booking.id} revenue for VAT code ${vatCode} does not match immutable invoice lines` };
    }
  }
  return {
    ok: true,
    accountNo: booking.account_no,
    bookingJournalEntryId: booking.id,
    bookedGrossDkk: expectedGrossDkk,
  };
}

export function validateInvoiceCreditNoteEvidence(
  db: Database,
  input: { invoiceDocumentId: number },
): InvoiceCreditNoteEvidenceResult {
  const invoice = db.query(
    `SELECT invoice_no, amount_inc_vat, vat_amount, currency, document_type
       FROM documents
      WHERE id = ?`,
  ).get(input.invoiceDocumentId) as {
    invoice_no: string | null;
    amount_inc_vat: number | null;
    vat_amount: number | null;
    currency: string | null;
    document_type: string;
  } | null;
  if (!invoice || invoice.document_type !== "issued_invoice" || !invoice.invoice_no) {
    return { ok: false, errors: [`invoice document ${input.invoiceDocumentId} is not an issued invoice with a number`] };
  }
  const rows = db.query(
    `SELECT c.id, c.amount_inc_vat, c.vat_amount, c.currency, c.invoice_date,
            c.payload_json,
            p.original_invoice_document_id, p.journal_entry_id,
            p.receivable_account_id, p.booked_gross_dkk,
            j.document_id AS journal_document_id, j.status AS journal_status,
            j.transaction_date AS journal_date, j.currency AS journal_currency,
            j.amount_foreign AS journal_amount_foreign,
            j.amount_dkk AS journal_amount_dkk,
            j.fx_rate_to_dkk AS journal_fx_rate_to_dkk,
            j.source_bank_transaction_id,
            (SELECT reversal.id
               FROM journal_entries reversal
              WHERE reversal.reversal_of_entry_id = j.id
              ORDER BY reversal.id ASC
              LIMIT 1) AS reversed_by_entry_id,
            a.account_no, a.type AS account_type, a.normal_balance
       FROM documents c
       LEFT JOIN credit_note_postings p ON p.credit_note_document_id = c.id
       LEFT JOIN journal_entries j ON j.id = p.journal_entry_id
       LEFT JOIN accounts a ON a.id = p.receivable_account_id
      WHERE c.document_type = 'credit_note'
        AND c.payment_details = ?
      ORDER BY CASE WHEN p.journal_entry_id IS NULL THEN 1 ELSE 0 END,
               p.journal_entry_id ASC, c.id ASC`,
  ).all(invoice.invoice_no) as Array<{
    id: number;
    amount_inc_vat: number | null;
    vat_amount: number | null;
    currency: string | null;
    invoice_date: string | null;
    payload_json: string | null;
    original_invoice_document_id: number | null;
    journal_entry_id: number | null;
    receivable_account_id: number | null;
    booked_gross_dkk: number | null;
    journal_document_id: number | null;
    journal_status: string | null;
    journal_date: string | null;
    journal_currency: string | null;
    journal_amount_foreign: number | null;
    journal_amount_dkk: number | null;
    journal_fx_rate_to_dkk: number | null;
    source_bank_transaction_id: number | null;
    reversed_by_entry_id: number | null;
    account_no: string | null;
    account_type: string | null;
    normal_balance: string | null;
  }>;
  const errors: string[] = [];
  const orphanLinks = db.query(
    `SELECT p.credit_note_document_id
       FROM credit_note_postings p
       JOIN documents c ON c.id = p.credit_note_document_id
      WHERE p.original_invoice_document_id = ?
        AND (c.document_type <> 'credit_note' OR c.payment_details IS NOT ?)
      ORDER BY p.credit_note_document_id ASC`,
  ).all(input.invoiceDocumentId, invoice.invoice_no) as Array<{ credit_note_document_id: number }>;
  for (const orphan of orphanLinks) {
    errors.push(`credit note posting ${orphan.credit_note_document_id} does not identify invoice ${invoice.invoice_no}`);
  }
  if (rows.length === 0) {
    return errors.length > 0
      ? { ok: false, errors: [...new Set(errors)] }
      : { ok: true };
  }

  const booking = resolveInvoiceReceivableAccount(db, input);
  if (!booking.ok) return { ok: false, errors: [booking.error] };
  const originalGross = roundDkk(Number(invoice.amount_inc_vat ?? 0));
  if (!(originalGross > 0)) {
    return { ok: false, errors: [`invoice document ${input.invoiceDocumentId} has no positive credit-note basis`] };
  }
  let cumulativeForeignCredit = 0;
  let cumulativeForeignVat = 0;
  let cumulativeDkkRelief = 0;
  const originalCounterLines = db.query(
    `SELECT a.account_no, a.type AS account_type, a.normal_balance,
            jl.debit_amount, jl.credit_amount, jl.vat_code
       FROM journal_lines jl
       JOIN accounts a ON a.id = jl.account_id
      WHERE jl.journal_entry_id = ?
        AND a.account_no <> ?
      ORDER BY jl.id ASC`,
  ).all(booking.bookingJournalEntryId, booking.accountNo) as Array<{
    account_no: string;
    account_type: string;
    normal_balance: string;
    debit_amount: number;
    credit_amount: number;
    vat_code: string | null;
  }>;
  type CreditCounterTarget = {
    accountNo: string;
    accountType: string;
    normalBalance: string;
    vatCode: string | null;
    originalDkk: number;
  };
  const originalCounterByKey = new Map<string, CreditCounterTarget>();
  for (const line of originalCounterLines) {
    const key = JSON.stringify([line.account_no, line.account_type, line.normal_balance, line.vat_code]);
    const existing = originalCounterByKey.get(key);
    if (existing) {
      existing.originalDkk = roundDkk(existing.originalDkk + Number(line.credit_amount));
    } else {
      originalCounterByKey.set(key, {
        accountNo: line.account_no,
        accountType: line.account_type,
        normalBalance: line.normal_balance,
        vatCode: line.vat_code,
        originalDkk: roundDkk(Number(line.credit_amount)),
      });
    }
  }
  const priorActualCounters = new Map<string, number>();
  for (const row of rows) {
    const label = `credit note document ${row.id}`;
    if (
      row.journal_entry_id == null ||
      row.original_invoice_document_id !== input.invoiceDocumentId ||
      row.journal_document_id !== row.id
    ) {
      errors.push(`${label} has no explicit journal evidence linked to invoice document ${input.invoiceDocumentId}`);
      continue;
    }
    if (row.journal_status !== "posted" || row.reversed_by_entry_id != null) {
      errors.push(`${label} journal ${row.journal_entry_id} is not active and posted`);
    }
    const invoiceCurrency = normalizeCurrency(invoice.currency);
    if (normalizeCurrency(row.currency) !== invoiceCurrency) {
      errors.push(`${label} currency does not match invoice ${invoice.invoice_no}`);
    }
    if (row.account_no !== booking.accountNo || row.account_type !== "asset" || row.normal_balance !== "debit") {
      errors.push(`${label} does not reduce the invoice's linked receivable account ${booking.accountNo}`);
      continue;
    }
    const creditForeign = roundDkk(Number(row.amount_inc_vat ?? 0));
    const nextCumulativeForeign = roundDkk(cumulativeForeignCredit + creditForeign);
    const originalVatForeign = roundDkk(Number(invoice.vat_amount ?? 0));
    const nextCumulativeVat = nextCumulativeForeign === originalGross
      ? originalVatForeign
      : roundDkk((originalVatForeign * nextCumulativeForeign) / originalGross);
    const expectedVatForeign = roundDkk(nextCumulativeVat - cumulativeForeignVat);
    const nextCumulativeDkk = nextCumulativeForeign === originalGross
      ? booking.bookedGrossDkk
      : roundDkk((booking.bookedGrossDkk * nextCumulativeForeign) / originalGross);
    const expectedDkk = roundDkk(nextCumulativeDkk - cumulativeDkkRelief);
    cumulativeForeignCredit = nextCumulativeForeign;
    cumulativeForeignVat = nextCumulativeVat;
    cumulativeDkkRelief = nextCumulativeDkk;
    if (compareDkk(cumulativeForeignCredit, originalGross) > 0) {
      errors.push(`${label} makes cumulative credit notes exceed invoice gross ${originalGross}`);
      continue;
    }
    if (!(creditForeign > 0) || !(expectedDkk > 0) || compareDkk(Number(row.booked_gross_dkk ?? 0), expectedDkk) !== 0) {
      errors.push(`${label} booked DKK amount does not match its cumulative invoice principal reduction`);
      continue;
    }
    let creditPayload: any;
    try {
      creditPayload = row.payload_json ? JSON.parse(row.payload_json) : null;
    } catch {
      creditPayload = null;
    }
    if (
      compareDkk(Number(row.vat_amount ?? 0), expectedVatForeign) !== 0 ||
      !creditPayload ||
      compareDkk(Number(creditPayload.grossAmount ?? 0), creditForeign) !== 0 ||
      compareDkk(Number(creditPayload.vatAmount ?? 0), expectedVatForeign) !== 0 ||
      compareDkk(Number(creditPayload.netAmount ?? 0), roundDkk(creditForeign - expectedVatForeign)) !== 0
    ) {
      errors.push(`${label} immutable gross/VAT/net amounts do not match its cumulative credit share`);
      continue;
    }
    const journalContextInvalid = row.journal_date !== row.invoice_date || row.source_bank_transaction_id != null ||
      normalizeCurrency(row.journal_currency) !== invoiceCurrency ||
      (invoiceCurrency === "DKK"
        ? row.journal_amount_foreign != null || row.journal_amount_dkk != null || row.journal_fx_rate_to_dkk != null
        : compareDkk(Number(row.journal_amount_foreign ?? 0), creditForeign) !== 0 ||
          compareDkk(Number(row.journal_amount_dkk ?? 0), expectedDkk) !== 0 ||
          !(Number(row.journal_fx_rate_to_dkk) > 0) ||
          compareDkk(
            roundDkk(creditForeign * Number(row.journal_fx_rate_to_dkk)),
            expectedDkk,
          ) !== 0);
    if (journalContextInvalid) {
      errors.push(`${label} journal ${row.journal_entry_id} has invalid date, currency, FX, or bank context`);
    }
    const journalTotals = db.query(
      `SELECT COALESCE(SUM(debit_amount), 0) AS debit_dkk,
              COALESCE(SUM(credit_amount), 0) AS credit_dkk
         FROM journal_lines
        WHERE journal_entry_id = ?`,
    ).get(row.journal_entry_id) as { debit_dkk: number; credit_dkk: number };
    if (
      compareDkk(Number(journalTotals.debit_dkk), expectedDkk) !== 0 ||
      compareDkk(Number(journalTotals.credit_dkk), expectedDkk) !== 0
    ) {
      errors.push(`${label} journal ${row.journal_entry_id} total debits/credits do not equal ${expectedDkk} DKK`);
      continue;
    }
    const effects = db.query(
      `SELECT a.account_no,
              SUM(jl.debit_amount) - SUM(jl.credit_amount) AS effect_dkk
         FROM journal_lines jl
         JOIN accounts a ON a.id = jl.account_id
        WHERE jl.journal_entry_id = ?
          AND a.type = 'asset'
          AND a.normal_balance = 'debit'
        GROUP BY a.account_no
       HAVING ROUND(SUM(jl.debit_amount) - SUM(jl.credit_amount), 2) <> 0
        ORDER BY a.account_no ASC`,
    ).all(row.journal_entry_id) as Array<{ account_no: string; effect_dkk: number }>;
    if (
      effects.length !== 1 ||
      effects[0]!.account_no !== booking.accountNo ||
      compareDkk(Number(effects[0]!.effect_dkk), -expectedDkk) !== 0
    ) {
      errors.push(`${label} journal ${row.journal_entry_id} does not credit exactly ${expectedDkk} DKK from receivable ${booking.accountNo}`);
      continue;
    }

    const desiredCumulativeByKey = new Map<string, number>();
    for (const [key, target] of originalCounterByKey) {
      desiredCumulativeByKey.set(
        key,
        cumulativeForeignCredit === originalGross
          ? target.originalDkk
          : roundDkk((target.originalDkk * cumulativeForeignCredit) / originalGross),
      );
    }
    const desiredDebit = roundDkk([...desiredCumulativeByKey.values()].reduce((sum, amount) => sum + amount, 0));
    const residual = roundDkk(desiredDebit - cumulativeDkkRelief);
    if (residual !== 0) {
      const carrierEntry = [...originalCounterByKey.entries()]
        .filter(([, target]) => target.accountType === "income" && target.vatCode != null)
        .sort((left, right) => (desiredCumulativeByKey.get(right[0]) ?? 0) - (desiredCumulativeByKey.get(left[0]) ?? 0))[0];
      if (!carrierEntry) {
        errors.push(`${label} cannot reproduce the original booking's credit-note rounding`);
        continue;
      }
      const carrierAmount = roundDkk((desiredCumulativeByKey.get(carrierEntry[0]) ?? 0) - residual);
      if (carrierAmount < 0) {
        errors.push(`${label} cannot reproduce the original booking's credit-note rounding`);
        continue;
      }
      desiredCumulativeByKey.set(carrierEntry[0], carrierAmount);
    }
    const expectedByKey = new Map<string, number>();
    for (const [key, desiredCumulative] of desiredCumulativeByKey) {
      expectedByKey.set(key, roundDkk(desiredCumulative - (priorActualCounters.get(key) ?? 0)));
    }
    const actualCounters = db.query(
      `SELECT a.account_no, a.type AS account_type, a.normal_balance,
              jl.debit_amount, jl.credit_amount, jl.vat_code
         FROM journal_lines jl
         JOIN accounts a ON a.id = jl.account_id
        WHERE jl.journal_entry_id = ?
          AND a.account_no <> ?
        ORDER BY jl.id ASC`,
    ).all(row.journal_entry_id, booking.accountNo) as Array<{
      account_no: string;
      account_type: string;
      normal_balance: string;
      debit_amount: number;
      credit_amount: number;
      vat_code: string | null;
    }>;
    const actualByKey = new Map<string, number>();
    let invalidCounter = false;
    for (const line of actualCounters) {
      if (!(Number(line.debit_amount) > 0) || Number(line.credit_amount) !== 0) {
        invalidCounter = true;
        break;
      }
      const key = JSON.stringify([line.account_no, line.account_type, line.normal_balance, line.vat_code]);
      actualByKey.set(key, roundDkk((actualByKey.get(key) ?? 0) + Number(line.debit_amount)));
    }
    const counterKeys = new Set([...expectedByKey.keys(), ...actualByKey.keys()]);
    if (
      invalidCounter ||
      [...counterKeys].some((key) => compareDkk(actualByKey.get(key) ?? 0, expectedByKey.get(key) ?? 0) !== 0)
    ) {
      errors.push(`${label} journal ${row.journal_entry_id} is not the exact scaled inverse of invoice booking ${booking.bookingJournalEntryId}`);
    }
    for (const [key, amount] of actualByKey) {
      priorActualCounters.set(key, roundDkk((priorActualCounters.get(key) ?? 0) + amount));
    }
  }

  return errors.length > 0
    ? { ok: false, errors: [...new Set(errors)] }
    : { ok: true };
}

function creditNoteLinesFromOriginalJournal(
  db: Database,
  originalInvoiceDocumentId: number,
  originalJournalEntryId: number,
  originalGrossAmount: number,
  cumulativeGrossAmount: number,
  receivableAccountNo: string,
  cumulativeReceivableReliefDkk: number,
) {
  if (!(originalGrossAmount > 0)) return null;

  const originalLines = db.query(
    `SELECT a.account_no, jl.debit_amount, jl.credit_amount, jl.vat_code, jl.text
       FROM journal_lines jl
       JOIN accounts a ON a.id = jl.account_id
      WHERE jl.journal_entry_id = ?
      ORDER BY jl.id ASC`
  ).all(originalJournalEntryId) as Array<{
    account_no: string;
    debit_amount: number;
    credit_amount: number;
    vat_code: string | null;
    text: string | null;
  }>;
  if (originalLines.length === 0) return null;
  const receivableOrigins = originalLines.filter(
    (line) => line.account_no === receivableAccountNo && line.debit_amount > 0 && line.credit_amount === 0,
  );
  if (receivableOrigins.length !== 1 || !(cumulativeReceivableReliefDkk > 0)) return null;

  type Counter = {
    accountNo: string;
    vatCode?: string;
    text?: string;
    originalDkk: number;
    desiredCumulativeDkk: number;
  };
  const counterByKey = new Map<string, Counter>();
  for (const line of originalLines) {
    if (line === receivableOrigins[0]) continue;
    if (!(line.credit_amount > 0) || line.debit_amount !== 0) return null;
    const key = JSON.stringify([line.account_no, line.vat_code]);
    const existing = counterByKey.get(key);
    if (existing) {
      existing.originalDkk = roundDkk(existing.originalDkk + Number(line.credit_amount));
    } else {
      counterByKey.set(key, {
        accountNo: line.account_no,
        vatCode: line.vat_code ?? undefined,
        text: line.text ?? undefined,
        originalDkk: roundDkk(Number(line.credit_amount)),
        desiredCumulativeDkk: 0,
      });
    }
  }
  if (counterByKey.size === 0) return null;

  const isFinalCredit = cumulativeGrossAmount === originalGrossAmount;
  for (const counter of counterByKey.values()) {
    counter.desiredCumulativeDkk = isFinalCredit
      ? counter.originalDkk
      : roundDkk((counter.originalDkk * cumulativeGrossAmount) / originalGrossAmount);
  }
  // Balance the cumulative target, not each note independently. Any one-øre
  // residual lives on the largest revenue line now and is automatically
  // corrected by the next note; a full credit lands exactly on every original
  // revenue/VAT account.
  const desiredDebitOre = [...counterByKey.values()].reduce(
    (sum, counter) => sum + toOre(counter.desiredCumulativeDkk),
    0n,
  );
  const residualOre = desiredDebitOre - toOre(cumulativeReceivableReliefDkk);
  if (residualOre !== 0n) {
    const carrier = [...counterByKey.values()]
      .filter((counter) => counter.vatCode !== undefined)
      .sort((left, right) => right.desiredCumulativeDkk - left.desiredCumulativeDkk)[0];
    if (!carrier) return null;
    const adjusted = fromOre(toOre(carrier.desiredCumulativeDkk) - residualOre);
    if (!(adjusted >= 0)) return null;
    carrier.desiredCumulativeDkk = adjusted;
  }

  const priorRows = db.query(
    `SELECT a.account_no, jl.vat_code,
            SUM(jl.debit_amount) - SUM(jl.credit_amount) AS amount_dkk
       FROM credit_note_postings p
       JOIN journal_lines jl ON jl.journal_entry_id = p.journal_entry_id
       JOIN accounts a ON a.id = jl.account_id
      WHERE p.original_invoice_document_id = ?
        AND a.account_no <> ?
      GROUP BY a.account_no, jl.vat_code`,
  ).all(originalInvoiceDocumentId, receivableAccountNo) as Array<{
    account_no: string;
    vat_code: string | null;
    amount_dkk: number;
  }>;
  const priorByKey = new Map(
    priorRows.map((row) => [JSON.stringify([row.account_no, row.vat_code]), roundDkk(Number(row.amount_dkk))] as const),
  );

  const currentReceivableRelief = roundDkk(
    cumulativeReceivableReliefDkk -
      Number((db.query(
        `SELECT COALESCE(SUM(booked_gross_dkk), 0) AS total
           FROM credit_note_postings
          WHERE original_invoice_document_id = ?`,
      ).get(originalInvoiceDocumentId) as { total: number }).total ?? 0),
  );
  if (!(currentReceivableRelief > 0)) return null;
  const reversedLines: Array<{
    accountNo: string;
    debitAmount?: number;
    creditAmount?: number;
    vatCode?: string;
    text?: string;
  }> = [{
    accountNo: receivableAccountNo,
    creditAmount: currentReceivableRelief,
    text: receivableOrigins[0]!.text ?? undefined,
  }];
  for (const [key, counter] of counterByKey) {
    const current = roundDkk(counter.desiredCumulativeDkk - (priorByKey.get(key) ?? 0));
    if (current < 0) return null;
    if (current === 0) continue;
    reversedLines.push({
      accountNo: counter.accountNo,
      debitAmount: current,
      vatCode: counter.vatCode,
      text: counter.text,
    });
  }
  const debitOre = reversedLines.reduce((sum, line) => sum + toOre(line.debitAmount ?? 0), 0n);
  if (debitOre !== toOre(currentReceivableRelief)) return null;
  return reversedLines;
}

function reserveManualCreditNoteNumber(db: Database, issueDate: string, creditNoteNumber: string) {
  const { scope, currentFloor, sequenceScope } = creditNoteSequenceState(db, issueDate);
  const match = new RegExp(`^CN-${scope.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}-([0-9]{4})$`).exec(creditNoteNumber);
  if (!match) return { ok: true as const };
  const requestedValue = Number(match[1]);
  const reserved = reserveSequenceValue(db, "credit_note", sequenceScope, requestedValue, currentFloor);
  if (!reserved.ok) {
    return { ok: false as const, error: `manual creditNoteNumber ${creditNoteNumber} exceeds næste fortløbende nummer CN-${scope}-${String(reserved.expectedValue).padStart(4, "0")}` };
  }
  return { ok: true as const };
}

function nextCreditNoteNumber(db: Database, issueDate: string) {
  const { scope, currentFloor, sequenceScope } = creditNoteSequenceState(db, issueDate);
  const nextValue = nextSequenceValue(db, "credit_note", sequenceScope, currentFloor);
  return `CN-${scope}-${String(nextValue).padStart(4, "0")}`;
}

function sha256(text: string) {
  return createHash("sha256").update(text).digest("hex");
}

export function writeTempFileFor(finalPath: string, content: string | Uint8Array) {
  // Retry on the (vanishingly rare) random-name collision; never follow or
  // clobber an existing entry.
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const tempPath = randomTempPath(finalPath);
    let fd: number;
    try {
      fd = openSync(tempPath, EXCL_CREATE_FLAGS, 0o600);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "EEXIST") continue;
      throw error;
    }
    try {
      writeAllSync(fd, content);
      // KODE-7: flush the file's data+metadata to stable storage BEFORE close,
      // so a power loss after the subsequent rename cannot resurrect a
      // zero-length or partially-written file. Without this, write()+rename()
      // only orders the operations in the page cache — the bytes may still be
      // in flight when the crash hits, leaving an empty manifest/signature/tar.
      fsyncSync(fd);
    } finally {
      closeSync(fd);
    }
    return tempPath;
  }
  throw new Error(`failed to create exclusive temp file for ${finalPath}`);
}

export function retainUntilForDate(db: Database, dateText: string) {
  if (!isValidIsoDate(dateText)) throw new Error(`invalid ISO date: ${dateText}`);
  const basis = dateText.trim();
  const company = getCompanySettings(db);
  const startMonth = company.fiscalYearStartMonth;
  const year = Number(basis.slice(0, 4));
  const month = Number(basis.slice(5, 7));
  const targetYear = year + (startMonth !== 1 && month >= startMonth ? 1 : 0) + 5;
  if (targetYear > 9999) throw new Error("retention deadline exceeds YYYY-MM-DD range");
  const endMonth = startMonth === 1 ? 12 : startMonth - 1;
  // Compute the last day in the TARGET year: adding five to a leap-day string
  // can otherwise create an impossible deadline. setUTCFullYear avoids the
  // Date.UTC remapping of years 0–99 to 1900–1999.
  const end = new Date(0);
  end.setUTCFullYear(targetYear, endMonth, 0);
  return end.toISOString().slice(0, 10);
}

export function strengthenGdprErasureAliasesForIdentity(
  db: Database,
  identity: { name?: string | null; cvr?: string | null },
): void {
  const subject = resolveSubject(identity);
  if (!subject.name || !subject.cvr) return;
  const nameReference = subjectAuditReference(`name:${subject.name}`);
  const priorNameErasure = db
    .query(
      `SELECT 1
         FROM gdpr_erasures
        WHERE subject_key IN (?, ?)
        LIMIT 1`,
    )
    .get(nameReference, subject.name);
  if (!priorNameErasure) return;

  const scopeResolution = resolveSubjectScope(db, subject);
  if (!scopeResolution.ok) return;
  const erasures = loadErasures(
    db,
    // The name may already have become ambiguous. It is safe to inspect its
    // old hash here because strengthenErasureAliases still requires exact CVR
    // evidence on each source row before creating a stable binding.
    [...scopeResolution.scope.erasureSubjectKeys, nameReference],
  );
  const rows = collectSourceRows(db, scopeResolution.scope);
  strengthenErasureAliases(db, scopeResolution.scope, rows, erasures);
}

export function postJournalEntry(db: Database, payload: JournalEntryInput): JournalPostResult {
  return postJournalEntryWithPolicy(db, payload, MANUAL_POSTING_POLICY);
}

const MANUAL_POSTING_POLICY: JournalPostingPolicy = {
  historicalImport: false,
  allowUncodedVatControl: false,
};

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[]
): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  bindings: SQLQueryBindings[],
): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[] | [SQLQueryBindings[]]
): ReturnType<Database["run"]> {
  const normalized = bindings.length === 1 && Array.isArray(bindings[0])
    ? bindings[0]
    : bindings as SQLQueryBindings[];
  return db.run(sql, normalized);
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

export function promoteTempFileExclusive(tempPath: string, finalPath: string) {
  linkSync(tempPath, finalPath);
  removeIfExists(tempPath);
  fsyncDir(finalPath);
}

export function removeIfExists(path: string) {
  try {
    unlinkSync(path);
  } catch {
    // best effort cleanup
  }
}

function hasCommittedDocumentAtPath(db: Database, storedPath: string): boolean | null {
  try {
    return db.query("SELECT 1 AS present FROM documents WHERE stored_path = ? LIMIT 1").get(storedPath) != null;
  } catch {
    return null;
  }
}

export function decodeTransactionRejection(error: unknown): TransactionRejection | null {
  if (error instanceof TransactionRejectionError) return error.rejection;
  if (typeof error !== "object" || error === null || !("message" in error)) return null;
  try {
    const parsed: unknown = JSON.parse(String(error.message));
    if (typeof parsed !== "object" || parsed === null) return null;
    const stringArray = (value: unknown): value is string[] =>
      Array.isArray(value) && value.every(item => typeof item === "string");
    return {
      ...("appliedRules" in parsed && stringArray(parsed.appliedRules) ? { appliedRules: parsed.appliedRules } : {}),
      ...("errors" in parsed && stringArray(parsed.errors) ? { errors: parsed.errors } : {}),
    };
  } catch {
    return null;
  }
}

