  invoiceDocumentId: number;
  bankTransactionId?: number;
  bankTransactionReference?: string;
  paymentDate?: string;
  amount?: number;
  bankAccountNo?: string;
  receivableAccountNo?: string;
  createdBy?: string;
  createdByProgram?: string;
};

export type SettleInvoiceFromBankResult = JournalPostResult & {
  paymentId?: number;
  claimPaymentId?: number;
  principalAmount?: number;
  claimAmount?: number;
  invoiceNumber?: string;
  openBalance?: number;
  claimOpenBalance?: number;
};

export type JournalPostResult = {
  ok: boolean;
  entryId?: JournalEntryId;
  entryNo?: string;
  entryHash?: string;
  appliedRules: string[];
  errors: string[];
};

export type InvoiceStatusResult = {
  ok: boolean;
  invoiceDocumentId?: number;
  invoiceNumber?: string;
  grossAmount?: number;
  creditedAmount?: number;
  paidAmount?: number;
  openBalance?: number;
  claimOpenBalance?: number;
  asOfDate?: string;
  dueDate?: string;
  effectiveDueDate?: string;
  isOverdue?: boolean;
  overdueDays?: number;
  status?: "open" | "paid" | "credited" | "refunded" | "overpaid" | "written_off";
  payments?: Array<{
    paymentId: number;
    paymentDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  creditNotes?: Array<{
    documentId: number;
    creditNoteNumber: string;
    amount: number;
    issueDate: string | null;
  }>;
  refunds?: Array<{
    refundId: number;
    refundDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  claimPayments?: Array<{
    claimPaymentId: number;
    paymentDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  badDebtWriteOffs?: Array<{
    writeOffId: number;
    writeOffDate: string;
    grossAmount: number;
    netAmount: number;
    vatAmount: number;
    journalEntryId: number;
    note: string | null;
  }>;
  reminders?: Array<{
    reminderId: number;
    reminderDate: string;
    feeAmount: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  compensationClaims?: Array<{
    claimId: number;
    claimDate: string;
    amountDkk: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  interestClaims?: Array<{
    claimId: number;
    claimDate: string;
    amountDkk: number;
    referenceRatePercent: number;
    annualInterestRatePercent: number;
    overdueDays: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  interestCorrections?: Array<{
    correctionId: number;
    correctionDate: string;
    amountDkk: number;
    journalEntryId: number;
  }>;
  totalReminderFees?: number;
  totalCompensationClaims?: number;
  totalInterestClaims?: number;
  totalInterestCorrections?: number;
  totalClaimPayments?: number;
  totalBadDebtWrittenOff?: number;
  errors: string[];
};

export type InvoiceReceivableAccountResult =
  | { ok: true; accountNo: string; bookingJournalEntryId: number; bookedGrossDkk: number }
  | { ok: false; error: string };

export type ClaimReceivableResult =
  | { ok: true; balances: ClaimReceivableBalance[]; totalDkk: number }
  | { ok: false; errors: string[] };

export type ClaimReceiptAllocationResult =
  | { ok: true; credits: ClaimReceivableBalance[] }
  | { ok: false; error: string };

export type SettlementBankAccountResult =
  | { ok: true; accountNo: string; source: "bank-account" | "explicit" | "role" }
  | { ok: false; error: string };

export type JournalEntryInput = {
  transactionDate: string;
  text: string;
  documentId?: number;
  sourceBankTransactionId?: number;
  currency?: string;
  amountForeign?: number;
  amountDkk?: number;
  fxRateToDkk?: number;
  createdBy?: string;
  createdByProgram?: string;
  lines: JournalLineInput[];
};

export type JournalLineInput = {
  accountNo: string;
  debitAmount?: number;
  creditAmount?: number;
  vatCode?: string;
  text?: string;
};

export type InvoiceJournalApplicationCandidate = {
  kind: InvoiceJournalApplicationKind;
  invoiceDocumentId: number;
  bankTransactionId: number | null;
  journalEntryId: number | null;
  effectiveDate: string;
  amount: number;
  currency: string;
};

type InvoiceJournalApplication = InvoiceJournalApplicationCandidate & {
  applicationId: number | null;
};

type JournalEvidence = {
  id: number;
  document_id: number | null;
  source_bank_transaction_id: number | null;
  transaction_date: string;
  registration_datetime: string;
  currency: string | null;
  amount_foreign: number | null;
  amount_dkk: number | null;
  status: string;
  reversed_by_entry_id: number | null;
};

type BankEvidence = {
  id: number;
  amount: number;
  currency: string | null;
  amount_dkk: number | null;
  bank_account_id: number | null;
  bank_account_currency: string | null;
  ledger_account_no: string | null;
};

type JournalLineEvidence = {
  account_no: string;
  debit_amount: number;
  credit_amount: number;
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type ApplyInvoicePaymentInput = {
  invoiceDocumentId: number;
  paymentDate: string;
  amount: number;
  bankTransactionId?: number;
  journalEntryId?: number;
  bankAccountNo?: string;
  receivableAccountNo?: string;
  createdBy?: string;
  createdByProgram?: string;
  note?: string;
};

export type ApplyInvoicePaymentResult = {
  ok: boolean;
  paymentId?: number;
  journalEntryId?: number;
  invoiceDocumentId?: number;
  invoiceNumber?: string;
  openBalance?: number;
  appliedRules: string[];
  errors: string[];
};

