export function resolveInvoiceDocumentId(db: Db, ctx: CommandContext): number {
  const resolution = resolveInvoiceDocument(db, ctx);
  if (resolution.kind === "found") return resolution.documentId;
  if (resolution.kind === "no-flag") {
    console.error("Missing required --document-id <n> or --invoice-number <no>");
    db.close();
    process.exit(2);
  }
  // not-found: the call was well-formed; the invoice simply does not exist.
  const label =
    resolution.flag === "--invoice-number"
      ? `No issued invoice has invoice number ${resolution.value}`
      : `No issued invoice has document id ${resolution.value}`;
  ctx.emitResult({
    ok: false,
    appliedRules: [],
    errors: [`${label} — check the value with 'invoice list' or 'invoice find'`],
  });
  db.close();
  process.exit(1);
}

function resolveInvoiceDocument(db: Db, ctx: CommandContext): InvoiceResolution {
  const documentIdRaw = ctx.arg("--document-id");
  if (documentIdRaw !== undefined) {
    const documentId = Number(documentIdRaw);
    if (Number.isInteger(documentId) && documentId > 0) {
      const row = db
        .query(`SELECT id FROM documents WHERE document_type = 'issued_invoice' AND id = ? LIMIT 1`)
        .get(documentId) as { id: number } | null;
      if (row) return { kind: "found", documentId: row.id };
    }
    return { kind: "not-found", flag: "--document-id", value: String(documentIdRaw) };
  }
  const invoiceNumber = ctx.arg("--invoice-number")?.trim();
  if (invoiceNumber) {
    const row = db
      .query(
        `SELECT id FROM documents WHERE document_type = 'issued_invoice' AND invoice_no = ? LIMIT 1`,
      )
      .get(invoiceNumber) as { id: number } | null;
    if (row) return { kind: "found", documentId: row.id };
    return { kind: "not-found", flag: "--invoice-number", value: invoiceNumber };
  }
  return { kind: "no-flag" };
}

payloadTypes.source:
type InvoiceResolution =
  | { kind: "found"; documentId: number }
  | { kind: "no-flag" }
  | { kind: "not-found"; flag: "--document-id" | "--invoice-number"; value: string };

export type PostInvoiceReminderToLedgerInput = {
  invoiceDocumentId: number;
  reminderId?: number;
  transactionDate?: string;
  receivableAccountNo?: string;
  reminderIncomeAccountNo?: string;
  createdBy?: string;
  createdByProgram?: string;
};

export type PostInvoiceReminderToLedgerResult = JournalPostResult & {
  reminderId?: number;
  invoiceDocumentId?: number;
  invoiceNumber?: string;
  reminderDate?: string;
  feeAmount?: number;
  claimOpenBalance?: number;
};

export type JournalPostResult = {
  ok: boolean;
  entryId?: JournalEntryId;
  entryNo?: string;
  entryHash?: string;
  appliedRules: string[];
  errors: string[];
};

export type AccountRoleResolution =
  | { ok: true; role: AccountRole; accountNo: string; version: number; confirmedBy: string; confirmationSource: AccountRoleConfirmationSource }
  | { ok: false; role: AccountRole; error: string };

export type ClaimIncomeAccountResult =
  | { ok: true; accountNo: string }
  | { ok: false; error: string };

export type JournalEntryInput = {
  transactionDate: string;
  text: string;
  documentId?: number;
  sourceBankTransactionId?: number;
  currency?: string;
  amountForeign?: number;
  amountDkk?: number;
  fxRateToDkk?: number;
  createdBy?: string;
  createdByProgram?: string;
  lines: JournalLineInput[];
};

export type JournalLineInput = {
  accountNo: string;
  debitAmount?: number;
  creditAmount?: number;
  vatCode?: string;
  text?: string;
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type InvoiceStatusResult = {
  ok: boolean;
  invoiceDocumentId?: number;
  invoiceNumber?: string;
  grossAmount?: number;
  creditedAmount?: number;
  paidAmount?: number;
  openBalance?: number;
  claimOpenBalance?: number;
  asOfDate?: string;
  dueDate?: string;
  effectiveDueDate?: string;
  isOverdue?: boolean;
  overdueDays?: number;
  status?: "open" | "paid" | "credited" | "refunded" | "overpaid" | "written_off";
  payments?: Array<{
    paymentId: number;
    paymentDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  creditNotes?: Array<{
    documentId: number;
    creditNoteNumber: string;
    amount: number;
    issueDate: string | null;
  }>;
  refunds?: Array<{
    refundId: number;
    refundDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  claimPayments?: Array<{
    claimPaymentId: number;
    paymentDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  badDebtWriteOffs?: Array<{
    writeOffId: number;
    writeOffDate: string;
    grossAmount: number;
    netAmount: number;
    vatAmount: number;
    journalEntryId: number;
    note: string | null;
  }>;
  reminders?: Array<{
    reminderId: number;
    reminderDate: string;
    feeAmount: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  compensationClaims?: Array<{
    claimId: number;
    claimDate: string;
    amountDkk: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  interestClaims?: Array<{
    claimId: number;
    claimDate: string;
    amountDkk: number;
    referenceRatePercent: number;
    annualInterestRatePercent: number;
    overdueDays: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  interestCorrections?: Array<{
    correctionId: number;
    correctionDate: string;
    amountDkk: number;
    journalEntryId: number;
  }>;
  totalReminderFees?: number;
  totalCompensationClaims?: number;
