  claimOpenBalance?: number;
};

export type JournalPostResult = {
  ok: boolean;
  entryId?: JournalEntryId;
  entryNo?: string;
  entryHash?: string;
  appliedRules: string[];
  errors: string[];
};

export type ProposeInterestCorrectionInput = {
  invoiceDocumentId: number;
  /** Internal recursion guard for the central evidence audit. */
  skipEvidenceValidation?: boolean;
};

export type ProposeInterestCorrectionResult = {
  ok: boolean;
  invoiceDocumentId?: number;
  invoiceNumber?: string;
  hasProposal?: boolean;
  postedInterest?: number;
  lawfulInterest?: number;
  alreadyCorrected?: number;
  overClaimedAmount?: number;
  // The invoice's outstanding claim balance. A correction credits the receivable,
  // so it can only be booked against an outstanding receivable.
  outstandingClaimBalance?: number;
  possibleOutstandingInterestReceivable?: number;
  ambiguousInterestReceivable?: number;
  claimOverclaims?: Array<{
    claimId: number;
    claimDate: string;
    journalEntryId: number;
    overClaimedAmount: number;
  }>;
  // True when overClaimedAmount exceeds the outstanding balance — the excess was
  // already collected in cash and needs a REFUND, not a receivable credit.
  // postInterestCorrection refuses these.
  requiresRefund?: boolean;
  throughDate?: string;
  appliedRules: string[];
  errors: string[];
};

export type InterestCorrectionEvidencePlanResult =
  | {
      ok: true;
      receivableCredits: Array<{ accountNo: string; amountDkk: number }>;
      incomeDebits: Array<{ accountNo: string; amountDkk: number }>;
      causalClaims: Array<{
        claimId: number;
        claimDate: string;
        amountDkk: number;
        claimCeilingDkk: number;
      }>;
      earliestCorrectionDate: string | null;
    }
  | { ok: false; errors: string[] };

type CorrectionClaimBucket = {
  claimId: number;
  claimDate: string;
  ceilingOre: bigint;
  remainingOre: bigint;
  receivables: CorrectionAccountBucket[];
  incomes: CorrectionAccountBucket[];
};

export type JournalEntryInput = {
  transactionDate: string;
  text: string;
  documentId?: number;
  sourceBankTransactionId?: number;
  currency?: string;
  amountForeign?: number;
  amountDkk?: number;
  fxRateToDkk?: number;
  createdBy?: string;
  createdByProgram?: string;
  lines: JournalLineInput[];
};

export type JournalLineInput = {
  accountNo: string;
  debitAmount?: number;
  creditAmount?: number;
  vatCode?: string;
  text?: string;
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type ClaimReceivableResult =
  | { ok: true; balances: ClaimReceivableBalance[]; totalDkk: number }
  | { ok: false; errors: string[] };

export type InterestReceivableBalanceResult =
  | {
      ok: true;
      balances: ClaimReceivableBalance[];
      totalDkk: number;
      possibleTotalDkk: number;
      ambiguousDkk: number;
    }
  | { ok: false; errors: string[] };

export type InterestIncomeBalanceResult =
  | { ok: true; balances: ClaimReceivableBalance[]; totalDkk: number }
  | { ok: false; errors: string[] };

export type InvoiceStatusResult = {
  ok: boolean;
  invoiceDocumentId?: number;
  invoiceNumber?: string;
  grossAmount?: number;
  creditedAmount?: number;
  paidAmount?: number;
  openBalance?: number;
  claimOpenBalance?: number;
  asOfDate?: string;
  dueDate?: string;
  effectiveDueDate?: string;
  isOverdue?: boolean;
  overdueDays?: number;
  status?: "open" | "paid" | "credited" | "refunded" | "overpaid" | "written_off";
  payments?: Array<{
    paymentId: number;
    paymentDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  creditNotes?: Array<{
    documentId: number;
    creditNoteNumber: string;
    amount: number;
    issueDate: string | null;
  }>;
  refunds?: Array<{
    refundId: number;
    refundDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  claimPayments?: Array<{
    claimPaymentId: number;
    paymentDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  badDebtWriteOffs?: Array<{
    writeOffId: number;
    writeOffDate: string;
    grossAmount: number;
    netAmount: number;
    vatAmount: number;
    journalEntryId: number;
    note: string | null;
  }>;
  reminders?: Array<{
    reminderId: number;
    reminderDate: string;
    feeAmount: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  compensationClaims?: Array<{
    claimId: number;
    claimDate: string;
    amountDkk: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  interestClaims?: Array<{
    claimId: number;
    claimDate: string;
    amountDkk: number;
    referenceRatePercent: number;
    annualInterestRatePercent: number;
    overdueDays: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  interestCorrections?: Array<{
    correctionId: number;
    correctionDate: string;
    amountDkk: number;
    journalEntryId: number;
  }>;
  totalReminderFees?: number;
  totalCompensationClaims?: number;
  totalInterestClaims?: number;
  totalInterestCorrections?: number;
  totalClaimPayments?: number;
  totalBadDebtWrittenOff?: number;
  errors: string[];
};

