export function postInterestCorrection(db: Database, input: PostInterestCorrectionInput): PostInterestCorrectionResult {
  if (!Number.isInteger(input.invoiceDocumentId) || input.invoiceDocumentId <= 0) {
    return { ok: false, appliedRules: [BOOKKEEPING_RULE_ID], errors: ["invoiceDocumentId must be a positive integer"] };
  }
  try {
    return db.transaction(() => {
      // The proposal and both ledger allocations are mutable reads. Hold the
      // write lock before computing them so two processes cannot post the same
      // correction from one stale snapshot.
      const proposal = proposeInterestCorrection(db, { invoiceDocumentId: input.invoiceDocumentId });
      if (!proposal.ok) return { ok: false, appliedRules: [BOOKKEEPING_RULE_ID], errors: proposal.errors };
      if (!proposal.hasProposal || !(Number(proposal.overClaimedAmount ?? 0) > 0)) {
        return {
          ok: false,
          invoiceDocumentId: input.invoiceDocumentId,
          invoiceNumber: proposal.invoiceNumber,
          appliedRules: [BOOKKEEPING_RULE_ID],
          errors: ["no over-claimed late interest to correct on this invoice"],
        };
      }
      // A correcting credit reverses the receivable. If the over-claim exceeds
      // the outstanding claim balance the excess was already collected in cash.
      if (proposal.requiresRefund) {
        return {
          ok: false,
          invoiceDocumentId: input.invoiceDocumentId,
          invoiceNumber: proposal.invoiceNumber,
          appliedRules: [BOOKKEEPING_RULE_ID],
          errors: [
            `the over-claimed late interest (${roundDkk(Number(proposal.overClaimedAmount))}) exceeds the provably outstanding interest receivable (${roundDkk(Number(proposal.outstandingClaimBalance))}); it was settled in cash or shares an ambiguously allocated claim account — resolve the allocation or use a refund instead of an automatic correction`,
          ],
        };
      }

      const amount = roundDkk(Number(proposal.overClaimedAmount));
      const transactionDate = input.transactionDate ?? proposal.throughDate!;
      const invoiceNo = proposal.invoiceNumber;
      const allocationPlan = buildInterestCorrectionEvidencePlan(db, {
        invoiceDocumentId: input.invoiceDocumentId,
        nextAmount: amount,
      });
      if (!allocationPlan.ok) {
        return {
          ok: false,
          invoiceDocumentId: input.invoiceDocumentId,
          invoiceNumber: invoiceNo,
          correctedAmount: amount,
          appliedRules: [BOOKKEEPING_RULE_ID],
          errors: allocationPlan.errors,
        };
      }
      if (
        allocationPlan.earliestCorrectionDate &&
        transactionDate < allocationPlan.earliestCorrectionDate
      ) {
        return {
          ok: false,
          invoiceDocumentId: input.invoiceDocumentId,
          invoiceNumber: invoiceNo,
          correctedAmount: amount,
          appliedRules: [BOOKKEEPING_RULE_ID],
          errors: [
            `interest correction date ${transactionDate} cannot precede its latest causal interest claim ${allocationPlan.earliestCorrectionDate}`,
          ],
        };
      }
      if (
        input.receivableAccountNo &&
        (allocationPlan.receivableCredits.length !== 1 || allocationPlan.receivableCredits[0]!.accountNo !== input.receivableAccountNo)
      ) {
        return {
          ok: false,
          invoiceDocumentId: input.invoiceDocumentId,
          invoiceNumber: invoiceNo,
          correctedAmount: amount,
          appliedRules: [BOOKKEEPING_RULE_ID],
          errors: [`interest correction must credit the ledger-backed receivable allocation, not ${input.receivableAccountNo}`],
        };
      }
      if (
        input.interestIncomeAccountNo &&
        (allocationPlan.incomeDebits.length !== 1 || allocationPlan.incomeDebits[0]!.accountNo !== input.interestIncomeAccountNo)
      ) {
        return {
          ok: false,
          invoiceDocumentId: input.invoiceDocumentId,
          invoiceNumber: invoiceNo,
          correctedAmount: amount,
          appliedRules: [BOOKKEEPING_RULE_ID],
          errors: [`interest correction must debit the ledger-backed income allocation, not ${input.interestIncomeAccountNo}`],
        };
      }

      const journal = postJournalEntry(db, {
        transactionDate,
        text: `Late-interest correction ${invoiceNo}`,
        documentId: input.invoiceDocumentId,
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
        lines: [
          ...allocationPlan.incomeDebits.map((allocation) => ({
            accountNo: allocation.accountNo,
            debitAmount: allocation.amountDkk,
            text: `Late-interest income reversal ${invoiceNo}`,
          })),
          ...allocationPlan.receivableCredits.map((allocation) => ({
            accountNo: allocation.accountNo,
            creditAmount: allocation.amountDkk,
            text: `Late-interest receivable reversal ${invoiceNo}`,
          })),
        ],
      });
      if (!journal.ok) {
        return { ...journal, invoiceDocumentId: input.invoiceDocumentId, invoiceNumber: invoiceNo, correctedAmount: amount, appliedRules: [...new Set([...(journal.appliedRules ?? []), BOOKKEEPING_RULE_ID])] };
      }

      // The append-only correction row is accepted only when this exact,
      // transaction-local causal plan exists. Direct INSERTs therefore cannot
      // permanently poison the register before the TypeScript evidence audit
      // gets a chance to run. Header, causal claims, account allocations and
      // the correction itself commit or roll back together.
      runSql(db,
        `INSERT INTO invoice_interest_correction_plans
           (journal_entry_id, invoice_document_id, correction_date, amount_dkk)
         VALUES (?, ?, ?, ?)`,
        journal.entryId ?? null,
        input.invoiceDocumentId,
        transactionDate,
        amount,
      );
      for (const claim of allocationPlan.causalClaims) {
        runSql(db,
          `INSERT INTO invoice_interest_correction_plan_claims
             (journal_entry_id, interest_claim_id, claim_date, amount_dkk, claim_ceiling_dkk)
           VALUES (?, ?, ?, ?, ?)`,
          journal.entryId ?? null,
          claim.claimId,
          claim.claimDate,
          claim.amountDkk,
          claim.claimCeilingDkk,
        );
      }
      for (const allocation of allocationPlan.incomeDebits) {
        runSql(db,
          `INSERT INTO invoice_interest_correction_plan_lines
             (journal_entry_id, account_no, debit_amount, credit_amount)
           VALUES (?, ?, ?, 0)`,
          journal.entryId ?? null,
          allocation.accountNo,
          allocation.amountDkk,
        );
      }
      for (const allocation of allocationPlan.receivableCredits) {
        runSql(db,
          `INSERT INTO invoice_interest_correction_plan_lines
             (journal_entry_id, account_no, debit_amount, credit_amount)
           VALUES (?, ?, 0, ?)`,
          journal.entryId ?? null,
          allocation.accountNo,
          allocation.amountDkk,
        );
      }

      const inserted = db.query(
        `INSERT INTO invoice_interest_corrections (invoice_document_id, correction_date, amount_dkk, reason, journal_entry_id)
         VALUES (?, ?, ?, ?, ?) RETURNING id`,
      ).get(input.invoiceDocumentId, transactionDate, amount, input.reason ?? null, journal.entryId ?? null) as { id: number };

      insertAuditLog(db, {
        eventType: "invoice_interest_correction",
        entityType: "invoice_interest_correction",
        entityId: inserted.id,
        message: `Corrected over-claimed late interest ${amount} on invoice ${invoiceNo} in journal entry ${journal.entryNo}`,
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
      });

      const verifiedReceivables = calculateClaimReceivableBalances(db, {
        invoiceDocumentId: input.invoiceDocumentId,
        allowUnpostedClaims: true,
      });
      const verifiedInterestReceivables = calculateInterestReceivableBalances(db, {
        invoiceDocumentId: input.invoiceDocumentId,
        allowUnpostedClaims: true,
      });
      const verifiedIncomes = calculateInterestIncomeBalances(db, {
        invoiceDocumentId: input.invoiceDocumentId,
        allowUnpostedClaims: true,
      });
      const verifiedPlan = buildInterestCorrectionEvidencePlan(db, {
        invoiceDocumentId: input.invoiceDocumentId,
      });
      if (!verifiedReceivables.ok || !verifiedInterestReceivables.ok || !verifiedIncomes.ok || !verifiedPlan.ok) {
        throw new Error(JSON.stringify({
          appliedRules: [BOOKKEEPING_RULE_ID],
          errors: [
            ...(!verifiedReceivables.ok ? verifiedReceivables.errors : []),
            ...(!verifiedInterestReceivables.ok ? verifiedInterestReceivables.errors : []),
            ...(!verifiedIncomes.ok ? verifiedIncomes.errors : []),
            ...(!verifiedPlan.ok ? verifiedPlan.errors : []),
          ],
        }));
      }
      const statusAfter = getInvoiceStatus(db, input.invoiceDocumentId, transactionDate);
      if (!statusAfter.ok) {
        throw new Error(JSON.stringify({
          appliedRules: [BOOKKEEPING_RULE_ID],
          errors: statusAfter.errors,
        }));
      }
      return {
        ...journal,
        invoiceDocumentId: input.invoiceDocumentId,
        invoiceNumber: invoiceNo,
        correctionId: inserted.id,
        correctedAmount: amount,
        claimOpenBalance: statusAfter.claimOpenBalance,
        appliedRules: [...new Set([...(journal.appliedRules ?? []), BOOKKEEPING_RULE_ID])],
      };
    }).immediate();
  } catch (error) {
    const parsed = typeof error === "object" && error && "message" in error ? (() => {
      try { return JSON.parse(String((error as any).message)); } catch { return null; }
    })() : null;
    return {
      ok: false,
      invoiceDocumentId: input.invoiceDocumentId,
      appliedRules: [BOOKKEEPING_RULE_ID],
      errors: (parsed?.errors as string[] | undefined) ?? [String(error)],
    };
  }
}

export function proposeInterestCorrection(db: Database, input: ProposeInterestCorrectionInput): ProposeInterestCorrectionResult {
  if (!Number.isInteger(input.invoiceDocumentId) || input.invoiceDocumentId <= 0) {
    return { ok: false, appliedRules: [RULE_ID], errors: ["invoiceDocumentId must be a positive integer"] };
  }
  const status = getInvoiceStatus(
    db,
    input.invoiceDocumentId,
    undefined,
    { skipEvidenceValidation: input.skipEvidenceValidation },
  );
  if (!status.ok) return { ok: false, appliedRules: [RULE_ID], errors: status.errors };

  // ALL claims, with a posted flag. We need every claim — posted or not — to
  // anchor each posted claim's incremental window: a claim's amount_dkk covers
  // [previous claim, its own date], whichever claim precedes it, posted or not.
  const claims = db.query(
    `SELECT c.id, c.claim_date, c.reference_rate_percent, c.annual_interest_rate_percent,
            c.reference_rate_source, c.amount_dkk,
            p.journal_entry_id, (p.id IS NOT NULL) AS posted
     FROM invoice_interest_claims c
     LEFT JOIN invoice_interest_postings p ON p.interest_claim_id = c.id
     WHERE c.invoice_document_id = ?
     ORDER BY c.claim_date ASC, c.id ASC`,
  ).all(input.invoiceDocumentId) as Array<{
    id: number;
    claim_date: string;
    reference_rate_percent: number;
    annual_interest_rate_percent: number;
    reference_rate_source: "statutory-table" | "manual-override";
    amount_dkk: number;
    journal_entry_id: number | null;
    posted: number;
  }>;

  const effectiveDueDate = status.effectiveDueDate;
  // A correction may only credit the portion that is provably still attributable
  // to posted interest. Generic claim receipts can make a shared account
  // ambiguous; the conservative helper excludes that amount instead of silently
  // consuming an unrelated reminder or compensation receivable.
  const interestReceivables = calculateInterestReceivableBalances(db, {
    invoiceDocumentId: input.invoiceDocumentId,
    allowUnpostedClaims: true,
  });
  if (!interestReceivables.ok) {
    return { ok: false, appliedRules: [RULE_ID], errors: interestReceivables.errors };
  }
  const outstandingClaimBalance = interestReceivables.totalDkk;
  const base = {
    ok: true as const,
    invoiceDocumentId: input.invoiceDocumentId,
    invoiceNumber: status.invoiceNumber,
    outstandingClaimBalance,
    possibleOutstandingInterestReceivable: interestReceivables.possibleTotalDkk,
    ambiguousInterestReceivable: interestReceivables.ambiguousDkk,
    appliedRules: [RULE_ID],
    errors: [] as string[],
  };

  const lastClaimDate = claims.length ? claims[claims.length - 1]!.claim_date : undefined;
  const timeline = buildBalanceTimeline(status, effectiveDueDate ?? lastClaimDate ?? "1970-01-01");

  // Accrue each POSTED claim over its OWN incremental window [previous claim, its
  // date], anchored at the immediately preceding claim (posted or not) — exactly
  // as the claim's amount was billed. Collect every segment and round ONCE, so the
  // lawful figure matches the posted amounts window-for-window even when the posted
  // claims are NOT a contiguous run from the due date (a later claim may be posted
  // while an earlier one is left unposted).
  const postedSegments: InterestSegment[] = [];
  const rawClaimOverclaims: Array<{
    claimId: number;
    claimDate: string;
    journalEntryId: number;
    overClaimedAmount: number;
  }> = [];
  let postedInterest = 0;
  let throughDate: string | undefined;
  let prevDate = effectiveDueDate;
  for (const claim of claims) {
    if (claim.posted) {
      const claimSegments: InterestSegment[] = [];
      // Reconstruct this claim's lawful interest the SAME way it was billed
      // (JUR-7): a statutory-table claim whose window [prevDate, claim_date]
      // crossed a half-yearly rate change was billed with each half-year's own
      // rate, so it must be re-segmented here too — accruing it at the single
      // stored as-of rate would invent a phantom over- (or under-) claim. A
      // manual-override claim stays one deliberate rate for the whole window.
      if (claim.reference_rate_source === "statutory-table" && prevDate) {
        let segStart = prevDate;
        for (const w of claimRateWindows(
          prevDate,
          claim.claim_date,
          "statutory-table",
          Number(claim.annual_interest_rate_percent),
          Number(claim.reference_rate_percent),
        )) {
          claimSegments.push(...timeline.windowSegments(segStart, w.end, w.annualRatePercent));
          segStart = w.end;
        }
      } else {
        claimSegments.push(...timeline.windowSegments(prevDate, claim.claim_date, Number(claim.annual_interest_rate_percent)));
      }
      postedSegments.push(...claimSegments);
      const claimLawfulInterest = cumulativeInterestDkk(claimSegments);
      const claimOverClaimed = Math.max(0, roundDkk(Number(claim.amount_dkk) - claimLawfulInterest));
      if (claimOverClaimed > 0 && claim.journal_entry_id != null) {
        rawClaimOverclaims.push({
          claimId: claim.id,
          claimDate: claim.claim_date,
          journalEntryId: claim.journal_entry_id,
          overClaimedAmount: claimOverClaimed,
        });
      }
      postedInterest = addDkk(postedInterest, Number(claim.amount_dkk));
      throughDate = claim.claim_date;
    }
    prevDate = claim.claim_date;
  }

  if (throughDate === undefined) {
    return { ...base, hasProposal: false, postedInterest: 0, lawfulInterest: 0, alreadyCorrected: 0, overClaimedAmount: 0, requiresRefund: false, claimOverclaims: [] };
  }

  const lawfulInterest = cumulativeInterestDkk(postedSegments);
  postedInterest = roundDkk(postedInterest);
  const alreadyCorrected = roundDkk(
    Number(
      (
        db
          .query(`SELECT COALESCE(SUM(amount_dkk), 0) AS total FROM invoice_interest_corrections WHERE invoice_document_id = ?`)
          .get(input.invoiceDocumentId) as { total: number } | null
      )?.total ?? 0,
    ),
  );
  const overClaimedAmount = Math.max(
    0,
    roundDkk(subtractDkk(subtractDkk(postedInterest, lawfulInterest), alreadyCorrected)),
  );
  const grossCorrectionCeiling = Math.max(0, roundDkk(subtractDkk(postedInterest, lawfulInterest)));
  let remainingCeilingOre = toOre(grossCorrectionCeiling);
  const claimOverclaims: NonNullable<ProposeInterestCorrectionResult["claimOverclaims"]> = [];
  for (const candidate of rawClaimOverclaims) {
    if (remainingCeilingOre <= 0n) break;
    const availableOre = toOre(candidate.overClaimedAmount);
    const allocatedOre = availableOre < remainingCeilingOre ? availableOre : remainingCeilingOre;
    if (allocatedOre > 0n) {
      claimOverclaims.push({
        claimId: candidate.claimId,
        claimDate: candidate.claimDate,
        journalEntryId: candidate.journalEntryId,
        overClaimedAmount: fromOre(allocatedOre),
      });
      remainingCeilingOre -= allocatedOre;
    }
  }
  if (remainingCeilingOre > 0n && rawClaimOverclaims.length > 0) {
    const fallback = rawClaimOverclaims[rawClaimOverclaims.length - 1]!;
    const existing = claimOverclaims.find((row) => row.claimId === fallback.claimId);
    if (existing) existing.overClaimedAmount = fromOre(toOre(existing.overClaimedAmount) + remainingCeilingOre);
    else claimOverclaims.push({ ...fallback, overClaimedAmount: fromOre(remainingCeilingOre) });
    remainingCeilingOre = 0n;
  }
  // A correcting credit reverses the receivable, so it can only be booked against
  // an OUTSTANDING receivable. If the over-claim exceeds the open claim balance the
  // excess was already paid in cash and needs a refund, not a receivable credit.
  const requiresRefund = overClaimedAmount > outstandingClaimBalance;

  return {
    ...base,
    hasProposal: overClaimedAmount > 0,
    postedInterest,
    lawfulInterest,
    alreadyCorrected,
    overClaimedAmount,
    claimOverclaims,
    requiresRefund,
    throughDate,
  };
}

export function roundDkk(value: number) {
  return Number.isFinite(value) ? fromScaledInt(scaledInt(value, 2), 2) : NaN;
}

export function buildInterestCorrectionEvidencePlan(
  db: Database,
  input: { invoiceDocumentId: number; nextAmount?: number },
): InterestCorrectionEvidencePlanResult {
  const proposal = proposeInterestCorrection(db, {
    invoiceDocumentId: input.invoiceDocumentId,
    skipEvidenceValidation: true,
  });
  if (!proposal.ok) return { ok: false, errors: proposal.errors };

  const errors: string[] = [];
  const buckets: CorrectionClaimBucket[] = [];
  for (const claim of proposal.claimOverclaims ?? []) {
    const effects = db.query(
      `SELECT a.account_no, a.type AS account_type, a.normal_balance,
              SUM(jl.debit_amount) - SUM(jl.credit_amount) AS asset_effect,
              SUM(jl.credit_amount) - SUM(jl.debit_amount) AS income_effect
         FROM journal_lines jl
         JOIN accounts a ON a.id = jl.account_id
        WHERE jl.journal_entry_id = ?
        GROUP BY a.account_no, a.type, a.normal_balance
        ORDER BY a.account_no ASC`,
    ).all(claim.journalEntryId) as Array<{
      account_no: string;
      account_type: string;
      normal_balance: string;
      asset_effect: number;
      income_effect: number;
    }>;
    const authorisedOre = toOre(claim.overClaimedAmount);
    const receivableOrigins = effects
      .filter((row) => row.account_type === "asset" && row.normal_balance === "debit" && compareDkk(Number(row.asset_effect), 0) > 0)
      .map((row) => ({ accountNo: row.account_no, remainingOre: toOre(Number(row.asset_effect)) }));
    const incomeOrigins = effects
      .filter((row) => row.account_type === "income" && row.normal_balance === "credit" && compareDkk(Number(row.income_effect), 0) > 0)
      .map((row) => ({ accountNo: row.account_no, remainingOre: toOre(Number(row.income_effect)) }));
    const receivableAuthorised = takeCorrectionAccounts(receivableOrigins, authorisedOre);
    const incomeAuthorised = takeCorrectionAccounts(incomeOrigins, authorisedOre);
    if (!receivableAuthorised || !incomeAuthorised) {
      errors.push(`interest claim ${claim.claimId} does not expose ${claim.overClaimedAmount} DKK on its original receivable and income accounts`);
      continue;
    }
    buckets.push({
      claimId: claim.claimId,
      claimDate: claim.claimDate,
      ceilingOre: authorisedOre,
      remainingOre: authorisedOre,
      receivables: [...receivableAuthorised.entries()].map(([accountNo, remainingOre]) => ({ accountNo, remainingOre })),
      incomes: [...incomeAuthorised.entries()].map(([accountNo, remainingOre]) => ({ accountNo, remainingOre })),
    });
  }

  const allocate = (amountDkk: number) => {
    let remaining = toOre(amountDkk);
    const receivables = new Map<string, bigint>();
    const incomes = new Map<string, bigint>();
    const causalClaims: Array<{
      claimId: number;
      claimDate: string;
      amountOre: bigint;
      claimCeilingOre: bigint;
    }> = [];
    for (const bucket of buckets) {
      if (remaining <= 0n) break;
      const amount = bucket.remainingOre < remaining ? bucket.remainingOre : remaining;
      if (amount <= 0n) continue;
      const receivable = takeCorrectionAccounts(bucket.receivables, amount);
      const income = takeCorrectionAccounts(bucket.incomes, amount);
      if (!receivable || !income) return null;
      addCorrectionEffects(receivables, receivable);
      addCorrectionEffects(incomes, income);
      causalClaims.push({
        claimId: bucket.claimId,
        claimDate: bucket.claimDate,
        amountOre: amount,
        claimCeilingOre: bucket.ceilingOre,
      });
      bucket.remainingOre -= amount;
      remaining -= amount;
    }
    return remaining === 0n ? { receivables, incomes, causalClaims } : null;
  };

  const corrections = db.query(
    `SELECT c.id, c.correction_date, c.amount_dkk, c.journal_entry_id,
            j.transaction_date, j.document_id, j.currency,
            j.amount_foreign, j.amount_dkk AS journal_amount_dkk,
            j.fx_rate_to_dkk, j.source_bank_transaction_id,
            j.status, j.reversal_of_entry_id,
            (SELECT reversal.id FROM journal_entries reversal
              WHERE reversal.reversal_of_entry_id = j.id
              ORDER BY reversal.id ASC LIMIT 1) AS reversed_by_entry_id
       FROM invoice_interest_corrections c
       LEFT JOIN journal_entries j ON j.id = c.journal_entry_id
      WHERE c.invoice_document_id = ?
      ORDER BY c.journal_entry_id ASC, c.id ASC`,
  ).all(input.invoiceDocumentId) as Array<{
    id: number;
    correction_date: string;
    amount_dkk: number;
    journal_entry_id: number;
    transaction_date: string | null;
    document_id: number | null;
    currency: string | null;
    amount_foreign: number | null;
    journal_amount_dkk: number | null;
    fx_rate_to_dkk: number | null;
    source_bank_transaction_id: number | null;
    status: string | null;
    reversal_of_entry_id: number | null;
    reversed_by_entry_id: number | null;
  }>;
  for (const correction of corrections) {
    const amount = roundDkk(Number(correction.amount_dkk));
    const expected = allocate(amount);
    const label = `interest correction ${correction.id}`;
    if (!expected) {
      errors.push(`${label} exceeds the lawful per-claim interest-correction ceiling`);
      continue;
    }
    if (
      correction.transaction_date !== correction.correction_date ||
      correction.document_id !== input.invoiceDocumentId ||
      correction.status !== "posted" ||
      correction.reversal_of_entry_id != null ||
      correction.reversed_by_entry_id != null ||
      (correction.currency ?? "DKK").trim().toUpperCase() !== "DKK" ||
      correction.amount_foreign != null ||
      correction.journal_amount_dkk != null ||
      correction.fx_rate_to_dkk != null ||
      correction.source_bank_transaction_id != null
    ) {
      errors.push(`${label} journal ${correction.journal_entry_id} has invalid date, document, status, reversal, currency, FX, or bank context`);
      continue;
    }
    const earliestCorrectionDate = expected.causalClaims
      .map((claim) => claim.claimDate)
      .sort()
      .at(-1);
    if (earliestCorrectionDate && correction.correction_date < earliestCorrectionDate) {
      errors.push(`${label} predates its latest causal interest claim ${earliestCorrectionDate}`);
      continue;
    }
    const lines = db.query(
      `SELECT a.account_no, a.type AS account_type, a.normal_balance,
              SUM(jl.debit_amount) AS debit_dkk,
              SUM(jl.credit_amount) AS credit_dkk
         FROM journal_lines jl
         JOIN accounts a ON a.id = jl.account_id
        WHERE jl.journal_entry_id = ?
        GROUP BY a.account_no, a.type, a.normal_balance
        ORDER BY a.account_no ASC`,
    ).all(correction.journal_entry_id) as Array<{
      account_no: string;
      account_type: string;
      normal_balance: string;
      debit_dkk: number;
      credit_dkk: number;
    }>;
    const actualReceivables = new Map<string, bigint>();
    const actualIncomes = new Map<string, bigint>();
    let totalDebitOre = 0n;
    let totalCreditOre = 0n;
    let unsupported = false;
    for (const line of lines) {
      const debitOre = toOre(Number(line.debit_dkk));
      const creditOre = toOre(Number(line.credit_dkk));
      totalDebitOre += debitOre;
      totalCreditOre += creditOre;
      if (line.account_type === "income" && line.normal_balance === "credit" && debitOre > 0n && creditOre === 0n) {
        actualIncomes.set(line.account_no, debitOre);
      } else if (line.account_type === "asset" && line.normal_balance === "debit" && creditOre > 0n && debitOre === 0n) {
        actualReceivables.set(line.account_no, creditOre);
      } else {
        unsupported = true;
      }
    }
    const amountOre = toOre(amount);
    const accountKeys = new Set([
      ...expected.receivables.keys(),
      ...expected.incomes.keys(),
      ...actualReceivables.keys(),
      ...actualIncomes.keys(),
    ]);
    const accountMismatch = [...accountKeys].some((accountNo) =>
      (expected.receivables.get(accountNo) ?? 0n) !== (actualReceivables.get(accountNo) ?? 0n) ||
      (expected.incomes.get(accountNo) ?? 0n) !== (actualIncomes.get(accountNo) ?? 0n)
    );
    if (unsupported || totalDebitOre !== amountOre || totalCreditOre !== amountOre || accountMismatch) {
      errors.push(`${label} journal ${correction.journal_entry_id} does not exactly reverse its causal interest receivable and income accounts`);
    }
  }

  if (errors.length > 0) return { ok: false, errors: [...new Set(errors)] };
  if (input.nextAmount === undefined) {
    return {
      ok: true,
      receivableCredits: [],
      incomeDebits: [],
      causalClaims: [],
      earliestCorrectionDate: null,
    };
  }
  const next = allocate(input.nextAmount);
  if (!next) return { ok: false, errors: ["interest correction exceeds the lawful per-claim correction ceiling"] };
  const certainReceivables = calculateInterestReceivableBalances(db, {
    invoiceDocumentId: input.invoiceDocumentId,
    allowUnpostedClaims: true,
  });
  if (!certainReceivables.ok) return certainReceivables;
  const certainByAccount = new Map(certainReceivables.balances.map((row) => [row.accountNo, toOre(row.amountDkk)] as const));
  for (const [accountNo, ore] of next.receivables) {
    if (ore > (certainByAccount.get(accountNo) ?? 0n)) {
      return {
        ok: false,
        errors: [`interest correction on receivable ${accountNo} is not provably outstanding; resolve ambiguous claim receipts or use a refund`],
      };
    }
  }
  return {
    ok: true,
    receivableCredits: [...next.receivables.entries()].map(([accountNo, ore]) => ({ accountNo, amountDkk: fromOre(ore) })),
    incomeDebits: [...next.incomes.entries()].map(([accountNo, ore]) => ({ accountNo, amountDkk: fromOre(ore) })),
    causalClaims: next.causalClaims.map((claim) => ({
      claimId: claim.claimId,
      claimDate: claim.claimDate,
      amountDkk: fromOre(claim.amountOre),
      claimCeilingDkk: fromOre(claim.claimCeilingOre),
    })),
    earliestCorrectionDate: next.causalClaims.map((claim) => claim.claimDate).sort().at(-1) ?? null,
  };
}

export function postJournalEntry(db: Database, payload: JournalEntryInput): JournalPostResult {
  return postJournalEntryWithPolicy(db, payload, MANUAL_POSTING_POLICY);
}

const MANUAL_POSTING_POLICY: JournalPostingPolicy = {
  historicalImport: false,
  allowUncodedVatControl: false,
};

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[]
): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  bindings: SQLQueryBindings[],
): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[] | [SQLQueryBindings[]]
): ReturnType<Database["run"]> {
  const normalized = bindings.length === 1 && Array.isArray(bindings[0])
    ? bindings[0]
    : bindings as SQLQueryBindings[];
  return db.run(sql, normalized);
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

export function calculateClaimReceivableBalances(
  db: Database,
  input: {
    invoiceDocumentId: number;
    beforeJournalEntryId?: number;
    asOfDate?: string;
    allowUnpostedClaims?: boolean;
  },
): ClaimReceivableResult {
  const errors: string[] = [];
  const balances = new Map<string, bigint>();

  for (const posting of claimPostings(db, input.invoiceDocumentId)) {
    const label = `${posting.kind} claim ${posting.claim_id}`;
    if (posting.journal_entry_id == null) {
      if (!input.allowUnpostedClaims) errors.push(`${label} is not ledger-posted`);
      continue;
    }
    const journal = journalAtCutoff(db, posting.journal_entry_id, input.beforeJournalEntryId);
    if (!journal) {
      errors.push(`${label} has no posting journal active before settlement`);
      continue;
    }
    if (journal.status !== "posted") errors.push(`${label} journal ${journal.id} is ${journal.status}, not posted`);
    if (journal.reversed_by_entry_id != null) errors.push(`${label} journal ${journal.id} was reversed by journal ${journal.reversed_by_entry_id}`);
    if (journal.document_id !== input.invoiceDocumentId) {
      errors.push(`${label} journal ${journal.id} is linked to invoice document ${journal.document_id ?? "none"}`);
    }
    if (journal.status !== "posted" || journal.reversed_by_entry_id != null || journal.document_id !== input.invoiceDocumentId) continue;

    if (journal.transaction_date < posting.effective_date) {
      errors.push(
        `${label} journal ${journal.id} date ${journal.transaction_date} predates claim date ${posting.effective_date}`,
      );
      continue;
    }

    if (
      input.asOfDate &&
      (posting.effective_date > input.asOfDate || journal.transaction_date > input.asOfDate)
    ) {
      errors.push(
        `${label} is not effective by ${input.asOfDate} ` +
        `(claim date ${posting.effective_date}, journal date ${journal.transaction_date})`,
      );
      continue;
    }

    const canonical = claimPostingJournalEvidence(db, journal.id);
    const expectedOre = toOre(Number(posting.amount_dkk));
    if (
      !canonical ||
      canonical.source_bank_transaction_id != null ||
      (canonical.currency ?? "DKK").trim().toUpperCase() !== "DKK" ||
      canonical.amount_foreign != null ||
      canonical.amount_dkk != null ||
      canonical.fx_rate_to_dkk != null ||
      canonical.line_count < 2 ||
      canonical.invalid_line_count !== 0 ||
      BigInt(canonical.total_debit_ore) !== expectedOre ||
      BigInt(canonical.total_credit_ore) !== expectedOre ||
      BigInt(canonical.receivable_debit_ore) !== expectedOre ||
      BigInt(canonical.income_credit_ore) !== expectedOre
    ) {
      errors.push(
        `${label} journal ${journal.id} must debit DKK receivable assets and credit income by exactly ${roundDkk(Number(posting.amount_dkk))} DKK without VAT, FX, bank, or other account effects`,
      );
      continue;
    }

    const effects = assetEffects(db, journal.id);
    const positive = effects.filter((row) => compareDkk(Number(row.effect_dkk), 0) > 0);
    const nonPositive = effects.filter((row) => compareDkk(Number(row.effect_dkk), 0) < 0);
    const totalDebit = roundDkk(positive.reduce((sum, row) => sum + Number(row.effect_dkk), 0));
    if (nonPositive.length > 0 || compareDkk(totalDebit, Number(posting.amount_dkk)) !== 0) {
      errors.push(`${label} journal ${journal.id} does not debit receivable assets by exactly ${roundDkk(Number(posting.amount_dkk))} DKK`);
      continue;
    }
    for (const row of positive) addEffect(balances, row.account_no, Number(row.effect_dkk));
  }

  const cutoff = input.beforeJournalEntryId ?? null;
  const corrections = db.query(
    `SELECT id, amount_dkk, journal_entry_id
       FROM invoice_interest_corrections
      WHERE invoice_document_id = ?
        AND (? IS NULL OR journal_entry_id < ?)
      ORDER BY journal_entry_id ASC, id ASC`,
  ).all(input.invoiceDocumentId, cutoff, cutoff) as Array<{
    id: number;
    amount_dkk: number;
    journal_entry_id: number;
  }>;
  for (const correction of corrections) {
    const label = `interest correction ${correction.id}`;
    const journal = journalAtCutoff(db, correction.journal_entry_id, input.beforeJournalEntryId);
    if (!journal || journal.status !== "posted" || journal.reversed_by_entry_id != null || journal.document_id !== input.invoiceDocumentId) {
      errors.push(`${label} does not have active journal evidence for invoice document ${input.invoiceDocumentId}`);
      continue;
    }
    const effects = assetEffects(db, journal.id);
    const negative = effects.filter((row) => compareDkk(Number(row.effect_dkk), 0) < 0);
    const positive = effects.filter((row) => compareDkk(Number(row.effect_dkk), 0) > 0);
    const totalCredit = roundDkk(negative.reduce((sum, row) => sum + -Number(row.effect_dkk), 0));
    if (positive.length > 0 || compareDkk(totalCredit, Number(correction.amount_dkk)) !== 0) {
      errors.push(`${label} journal ${journal.id} does not credit receivable assets by exactly ${roundDkk(Number(correction.amount_dkk))} DKK`);
      continue;
    }
    for (const row of negative) addEffect(balances, row.account_no, Number(row.effect_dkk));
  }

  if (errors.length > 0) return { ok: false, errors: [...new Set(errors)] };

  const priorPayments = db.query(
    `SELECT id, amount, journal_entry_id
       FROM invoice_claim_payments
      WHERE invoice_document_id = ?
        AND journal_entry_id IS NOT NULL
        AND (? IS NULL OR journal_entry_id < ?)
      ORDER BY journal_entry_id ASC, id ASC`,
  ).all(input.invoiceDocumentId, cutoff, cutoff) as Array<{
    id: number;
    amount: number;
    journal_entry_id: number;
  }>;
  for (const payment of priorPayments) {
    const allocation = allocateClaimReceipt(
      [...balances.entries()]
        .filter(([, ore]) => ore > 0n)
        .map(([accountNo, ore]) => ({ accountNo, amountDkk: fromOre(ore) })),
      Number(payment.amount),
    );
    if (!allocation.ok) {
      return { ok: false, errors: [`claim payment ${payment.id}: ${allocation.error}`] };
    }
    for (const credit of allocation.credits) addEffect(balances, credit.accountNo, -credit.amountDkk);
  }

  const negative = [...balances.entries()].filter(([, ore]) => ore < 0n);
  if (negative.length > 0) {
    return {
      ok: false,
      errors: negative.map(([accountNo, ore]) => `claim receivable account ${accountNo} is over-cleared by ${fromOre(-ore)} DKK`),
    };
  }
  const resultBalances = [...balances.entries()]
    .filter(([, ore]) => ore > 0n)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([accountNo, ore]) => ({ accountNo, amountDkk: fromOre(ore) }));
  return {
    ok: true,
    balances: resultBalances,
    totalDkk: roundDkk(resultBalances.reduce((sum, row) => sum + row.amountDkk, 0)),
  };
}

export function calculateInterestReceivableBalances(
  db: Database,
  input: {
    invoiceDocumentId: number;
    beforeJournalEntryId?: number;
    allowUnpostedClaims?: boolean;
  },
): InterestReceivableBalanceResult {
  const aggregate = calculateClaimReceivableBalances(db, input);
  if (!aggregate.ok) return aggregate;

  const errors: string[] = [];
  const interestOrigins = new Map<string, bigint>();
  const otherOrigins = new Map<string, bigint>();
  for (const posting of claimPostings(db, input.invoiceDocumentId)) {
    if (posting.journal_entry_id == null) continue;
    const journal = journalAtCutoff(db, posting.journal_entry_id, input.beforeJournalEntryId);
    if (
      !journal ||
      journal.status !== "posted" ||
      journal.reversed_by_entry_id != null ||
      journal.document_id !== input.invoiceDocumentId
    ) continue;
    const target = posting.kind === "interest" ? interestOrigins : otherOrigins;
    for (const effect of assetEffects(db, journal.id)) {
      if (compareDkk(Number(effect.effect_dkk), 0) > 0) {
        addEffect(target, effect.account_no, Number(effect.effect_dkk));
      }
    }
  }

  const cutoff = input.beforeJournalEntryId ?? null;
  const corrections = db.query(
    `SELECT id, journal_entry_id
       FROM invoice_interest_corrections
      WHERE invoice_document_id = ?
        AND (? IS NULL OR journal_entry_id < ?)
      ORDER BY journal_entry_id ASC, id ASC`,
  ).all(input.invoiceDocumentId, cutoff, cutoff) as Array<{
    id: number;
    journal_entry_id: number;
  }>;
  for (const correction of corrections) {
    const journal = journalAtCutoff(db, correction.journal_entry_id, input.beforeJournalEntryId);
    if (!journal || journal.status !== "posted" || journal.reversed_by_entry_id != null) continue;
    for (const effect of assetEffects(db, journal.id)) {
      if (compareDkk(Number(effect.effect_dkk), 0) < 0) {
        addEffect(interestOrigins, effect.account_no, Number(effect.effect_dkk));
      }
    }
  }
  for (const [accountNo, ore] of interestOrigins) {
    if (ore < 0n) {
      errors.push(`interest receivable account ${accountNo} is over-reversed by ${fromOre(-ore)} DKK`);
    }
  }
  if (errors.length > 0) return { ok: false, errors };

  const aggregateByAccount = new Map(
    aggregate.balances.map((row) => [row.accountNo, toOre(row.amountDkk)] as const),
  );
  const balances: ClaimReceivableBalance[] = [];
  let possibleOre = 0n;
  let certainOre = 0n;
  for (const [accountNo, interestOre] of [...interestOrigins.entries()].sort(([left], [right]) => left.localeCompare(right))) {
    if (interestOre <= 0n) continue;
    const aggregateOre = aggregateByAccount.get(accountNo) ?? 0n;
    const possible = interestOre < aggregateOre ? interestOre : aggregateOre;
    const otherOre = otherOrigins.get(accountNo) ?? 0n;
    const certainCandidate = aggregateOre > otherOre ? aggregateOre - otherOre : 0n;
    const certain = interestOre < certainCandidate ? interestOre : certainCandidate;
    possibleOre += possible > 0n ? possible : 0n;
    certainOre += certain > 0n ? certain : 0n;
    if (certain > 0n) balances.push({ accountNo, amountDkk: fromOre(certain) });
  }
  return {
    ok: true,
    balances,
    totalDkk: fromOre(certainOre),
    possibleTotalDkk: fromOre(possibleOre),
    ambiguousDkk: fromOre(possibleOre - certainOre),
  };
}

export function calculateInterestIncomeBalances(
  db: Database,
  input: {
    invoiceDocumentId: number;
    beforeJournalEntryId?: number;
    allowUnpostedClaims?: boolean;
  },
): InterestIncomeBalanceResult {
  const errors: string[] = [];
  const balances = new Map<string, bigint>();
  const cutoff = input.beforeJournalEntryId ?? null;
  const claims = db.query(
    `SELECT c.id, c.amount_dkk, p.journal_entry_id
       FROM invoice_interest_claims c
       LEFT JOIN invoice_interest_postings p ON p.interest_claim_id = c.id
      WHERE c.invoice_document_id = ?
      ORDER BY c.claim_date ASC, c.id ASC`,
  ).all(input.invoiceDocumentId) as Array<{
    id: number;
    amount_dkk: number;
    journal_entry_id: number | null;
  }>;

  for (const claim of claims) {
    const label = `interest claim ${claim.id}`;
    if (claim.journal_entry_id == null) {
      if (!input.allowUnpostedClaims) errors.push(`${label} is not ledger-posted`);
      continue;
    }
    const journal = journalAtCutoff(db, claim.journal_entry_id, input.beforeJournalEntryId);
    if (!journal || journal.status !== "posted" || journal.reversed_by_entry_id != null || journal.document_id !== input.invoiceDocumentId) {
      errors.push(`${label} does not have active journal evidence for invoice document ${input.invoiceDocumentId}`);
      continue;
    }
    const effects = incomeEffects(db, journal.id);
    const positive = effects.filter((row) => compareDkk(Number(row.effect_dkk), 0) > 0);
    const negative = effects.filter((row) => compareDkk(Number(row.effect_dkk), 0) < 0);
    const totalCredit = roundDkk(positive.reduce((sum, row) => sum + Number(row.effect_dkk), 0));
    if (negative.length > 0 || compareDkk(totalCredit, Number(claim.amount_dkk)) !== 0) {
      errors.push(`${label} journal ${journal.id} does not credit income by exactly ${roundDkk(Number(claim.amount_dkk))} DKK`);
      continue;
    }
    for (const row of positive) addEffect(balances, row.account_no, Number(row.effect_dkk));
  }

  const corrections = db.query(
    `SELECT id, amount_dkk, journal_entry_id
       FROM invoice_interest_corrections
      WHERE invoice_document_id = ?
        AND (? IS NULL OR journal_entry_id < ?)
      ORDER BY journal_entry_id ASC, id ASC`,
  ).all(input.invoiceDocumentId, cutoff, cutoff) as Array<{
    id: number;
    amount_dkk: number;
    journal_entry_id: number;
  }>;
  for (const correction of corrections) {
    const label = `interest correction ${correction.id}`;
    const journal = journalAtCutoff(db, correction.journal_entry_id, input.beforeJournalEntryId);
    if (!journal || journal.status !== "posted" || journal.reversed_by_entry_id != null || journal.document_id !== input.invoiceDocumentId) {
      errors.push(`${label} does not have active journal evidence for invoice document ${input.invoiceDocumentId}`);
      continue;
    }
    const effects = incomeEffects(db, journal.id);
    const negative = effects.filter((row) => compareDkk(Number(row.effect_dkk), 0) < 0);
    const positive = effects.filter((row) => compareDkk(Number(row.effect_dkk), 0) > 0);
    const totalDebit = roundDkk(negative.reduce((sum, row) => sum + -Number(row.effect_dkk), 0));
    if (positive.length > 0 || compareDkk(totalDebit, Number(correction.amount_dkk)) !== 0) {
      errors.push(`${label} journal ${journal.id} does not debit income by exactly ${roundDkk(Number(correction.amount_dkk))} DKK`);
      continue;
    }
    for (const row of negative) addEffect(balances, row.account_no, Number(row.effect_dkk));
  }

  if (errors.length > 0) return { ok: false, errors: [...new Set(errors)] };
  const negative = [...balances.entries()].filter(([, ore]) => ore < 0n);
  if (negative.length > 0) {
    return {
      ok: false,
      errors: negative.map(([accountNo, ore]) => `interest income account ${accountNo} is over-reversed by ${fromOre(-ore)} DKK`),
    };
  }
  const resultBalances = [...balances.entries()]
    .filter(([, ore]) => ore > 0n)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([accountNo, ore]) => ({ accountNo, amountDkk: fromOre(ore) }));
  return {
    ok: true,
    balances: resultBalances,
    totalDkk: roundDkk(resultBalances.reduce((sum, row) => sum + row.amountDkk, 0)),
  };
}

export function getInvoiceStatus(
  db: Database,
  invoiceDocumentId: number,
  asOfDate?: string,
  options: { skipEvidenceValidation?: boolean } = {},
): InvoiceStatusResult {
  const invoice = getIssuedInvoice(db, invoiceDocumentId);
  if (!invoice) return { ok: false, errors: [`invoice document ${invoiceDocumentId} does not exist`] };
  if (invoice.document_type !== "issued_invoice") return { ok: false, errors: [`document ${invoiceDocumentId} is not an issued invoice`] };

  if (!options.skipEvidenceValidation) {
    const evidence = validateInvoiceJournalEvidence(db, { invoiceDocumentId });
    if (!evidence.ok) return { ok: false, errors: evidence.errors };
    const creditEvidence = validateInvoiceCreditNoteEvidence(db, { invoiceDocumentId });
    if (!creditEvidence.ok) return { ok: false, errors: creditEvidence.errors };
  }

  const payload = invoice.payload_json ? JSON.parse(invoice.payload_json) : null;

  const payments = db.query(
    `SELECT p.id, p.payment_date, p.amount, p.bank_transaction_id, p.journal_entry_id, p.note
     FROM invoice_payments p
     WHERE p.invoice_document_id = ?
     ORDER BY p.id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; payment_date: string; amount: number; bank_transaction_id: number | null; journal_entry_id: number | null; note: string | null }>;

  const creditNotes = db.query(
    `SELECT id, invoice_no, amount_inc_vat, invoice_date
     FROM documents
     WHERE document_type = 'credit_note' AND payment_details = ?
     ORDER BY id ASC`
  ).all(invoice.invoice_no) as Array<{ id: number; invoice_no: string; amount_inc_vat: number | null; invoice_date: string | null }>;

  const refunds = db.query(
    `SELECT id, refund_date, amount, bank_transaction_id, journal_entry_id, note
     FROM invoice_refunds WHERE invoice_document_id = ? ORDER BY id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; refund_date: string; amount: number; bank_transaction_id: number | null; journal_entry_id: number | null; note: string | null }>;

  const claimPayments = db.query(
    `SELECT id, payment_date, amount, bank_transaction_id, journal_entry_id, note
     FROM invoice_claim_payments WHERE invoice_document_id = ? ORDER BY id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; payment_date: string; amount: number; bank_transaction_id: number | null; journal_entry_id: number | null; note: string | null }>;

  const badDebtWriteOffs = db.query(
    `SELECT id, writeoff_date, gross_amount, net_amount, vat_amount, journal_entry_id, note
     FROM invoice_bad_debt_writeoffs WHERE invoice_document_id = ? ORDER BY id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; writeoff_date: string; gross_amount: number; net_amount: number; vat_amount: number; journal_entry_id: number; note: string | null }>;

  const reminders = db.query(
    `SELECT r.id, r.reminder_date, r.fee_amount, r.note, p.journal_entry_id
     FROM invoice_reminders r
     LEFT JOIN invoice_reminder_postings p ON p.reminder_id = r.id
     WHERE r.invoice_document_id = ? ORDER BY r.reminder_date ASC, r.id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; reminder_date: string; fee_amount: number; note: string | null; journal_entry_id: number | null }>;

  const compensationClaims = db.query(
    `SELECT c.id, c.claim_date, c.amount_dkk, c.note, p.journal_entry_id
     FROM invoice_compensation_claims c
     LEFT JOIN invoice_compensation_postings p ON p.compensation_claim_id = c.id
     WHERE c.invoice_document_id = ? ORDER BY c.claim_date ASC, c.id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; claim_date: string; amount_dkk: number; note: string | null; journal_entry_id: number | null }>;

  const interestClaims = db.query(
    `SELECT c.id, c.claim_date, c.amount_dkk, c.reference_rate_percent, c.annual_interest_rate_percent, c.overdue_days, c.note, p.journal_entry_id
     FROM invoice_interest_claims c
     LEFT JOIN invoice_interest_postings p ON p.interest_claim_id = c.id
     WHERE c.invoice_document_id = ? ORDER BY c.claim_date ASC, c.id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; claim_date: string; amount_dkk: number; reference_rate_percent: number; annual_interest_rate_percent: number; overdue_days: number; note: string | null; journal_entry_id: number | null }>;

  // Correcting reversals of over-claimed late interest (back-dated balance
  // reductions); they net DOWN the interest-claim balance.
  const interestCorrections = db.query(
    `SELECT id, correction_date, amount_dkk, journal_entry_id
     FROM invoice_interest_corrections
     WHERE invoice_document_id = ? ORDER BY id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; correction_date: string; amount_dkk: number; journal_entry_id: number }>;

  const grossAmount = roundDkk(Number(invoice.amount_inc_vat ?? 0));
  const creditedAmount = sumDkk(creditNotes.map((c) => Number(c.amount_inc_vat ?? 0)));
  const paidAmount = sumDkk(payments.map((p) => Number(p.amount)));
  const refundedAmount = sumDkk(refunds.map((r) => Number(r.amount)));
  const totalReminderFees = sumDkk(reminders.map((r) => Number(r.fee_amount)));
  const totalCompensationClaims = sumDkk(compensationClaims.map((c) => Number(c.amount_dkk)));
  const totalInterestCorrections = sumDkk(interestCorrections.map((c) => Number(c.amount_dkk)));
  const totalInterestClaims = subtractDkk(sumDkk(interestClaims.map((c) => Number(c.amount_dkk))), totalInterestCorrections);
  const totalClaimPayments = sumDkk(claimPayments.map((p) => Number(p.amount)));
  const totalBadDebtWrittenOff = sumDkk(badDebtWriteOffs.map((w) => Number(w.gross_amount)));
  const openBalance = subtractDkk(addDkk(subtractDkk(grossAmount, creditedAmount, paidAmount), refundedAmount), totalBadDebtWrittenOff);
  const claimOpenBalance = subtractDkk(addDkk(openBalance, totalReminderFees, totalCompensationClaims, totalInterestClaims), totalClaimPayments);
  const dueDate = typeof payload?.dueDate === "string" ? payload.dueDate : undefined;
  const effectiveDueDate = dueDate ?? (invoice.invoice_date ? addDays(invoice.invoice_date, 30) : undefined);
  // EJER-1: when no as-of date is given, compare against TODAY (canonical
  // Danish-time clock, RENTEMESTER_TODAY-overridable). The old default
  // compared the due date against itself, so the default path never saw an
  // invoice as overdue while the --as-of path did.
  const comparisonDate = asOfDate ?? todayIsoDate();
  const overdueDays = effectiveDueDate && openBalance > 0 ? Math.max(0, diffDays(effectiveDueDate, comparisonDate)) : 0;
  const isOverdue = overdueDays > 0;
  // Status ladder: a written-off or refunded zero-balance invoice must never be
  // mislabelled "paid". Write-off and refund take precedence over "paid", and
  // "refunded" is decoupled from creditedAmount so a refund without a credit
  // note (e.g. an overpayment returned) is still labelled "refunded".
  const status = openBalance > 0
    ? "open"
    : openBalance < 0
      ? "overpaid"
      : totalBadDebtWrittenOff > 0
        ? "written_off"
        : refundedAmount > 0
          ? "refunded"
          : creditedAmount === grossAmount && paidAmount === 0
            ? "credited"
            : "paid";

  return {
    ok: true,
    invoiceDocumentId,
    invoiceNumber: invoice.invoice_no,
    grossAmount,
    creditedAmount,
    paidAmount,
    openBalance,
    claimOpenBalance,
    asOfDate: comparisonDate,
    dueDate,
    effectiveDueDate,
    isOverdue,
    overdueDays,
    status,
    payments: payments.map((p) => ({ paymentId: p.id, paymentDate: p.payment_date, amount: roundDkk(Number(p.amount)), bankTransactionId: p.bank_transaction_id, journalEntryId: p.journal_entry_id == null ? null : Number(p.journal_entry_id), note: p.note })),
    creditNotes: creditNotes.map((c) => ({ documentId: c.id, creditNoteNumber: c.invoice_no, amount: roundDkk(Number(c.amount_inc_vat ?? 0)), issueDate: c.invoice_date })),
    refunds: refunds.map((r) => ({ refundId: r.id, refundDate: r.refund_date, amount: roundDkk(Number(r.amount)), bankTransactionId: r.bank_transaction_id, journalEntryId: r.journal_entry_id == null ? null : Number(r.journal_entry_id), note: r.note })),
    claimPayments: claimPayments.map((p) => ({ claimPaymentId: p.id, paymentDate: p.payment_date, amount: roundDkk(Number(p.amount)), bankTransactionId: p.bank_transaction_id, journalEntryId: p.journal_entry_id == null ? null : Number(p.journal_entry_id), note: p.note })),
    badDebtWriteOffs: badDebtWriteOffs.map((w) => ({ writeOffId: w.id, writeOffDate: w.writeoff_date, grossAmount: roundDkk(Number(w.gross_amount)), netAmount: roundDkk(Number(w.net_amount)), vatAmount: roundDkk(Number(w.vat_amount)), journalEntryId: Number(w.journal_entry_id), note: w.note })),
    reminders: reminders.map((r) => ({ reminderId: r.id, reminderDate: r.reminder_date, feeAmount: roundDkk(Number(r.fee_amount)), note: r.note, journalEntryId: r.journal_entry_id == null ? null : Number(r.journal_entry_id) })),
    compensationClaims: compensationClaims.map((c) => ({ claimId: c.id, claimDate: c.claim_date, amountDkk: roundDkk(Number(c.amount_dkk)), note: c.note, journalEntryId: c.journal_entry_id == null ? null : Number(c.journal_entry_id) })),
    interestClaims: interestClaims.map((c) => ({
      claimId: c.id,
      claimDate: c.claim_date,
      amountDkk: roundDkk(Number(c.amount_dkk)),
      referenceRatePercent: roundDkk(Number(c.reference_rate_percent)),
      annualInterestRatePercent: roundDkk(Number(c.annual_interest_rate_percent)),
      overdueDays: Number(c.overdue_days),
      note: c.note,
      journalEntryId: c.journal_entry_id == null ? null : Number(c.journal_entry_id),
    })),
    interestCorrections: interestCorrections.map((c) => ({ correctionId: c.id, correctionDate: c.correction_date, amountDkk: roundDkk(Number(c.amount_dkk)), journalEntryId: Number(c.journal_entry_id) })),
    totalReminderFees,
    totalCompensationClaims,
    totalInterestClaims,
    totalInterestCorrections,
    totalClaimPayments,
    totalBadDebtWrittenOff,
    errors: [],
  };
}

typeDeclarations.source:
type InvoiceResolution =
  | { kind: "found"; documentId: number }
  | { kind: "no-flag" }
  | { kind: "not-found"; flag: "--document-id" | "--invoice-number"; value: string };

export type PostInterestCorrectionInput = {
  invoiceDocumentId: number;
  transactionDate?: string;
  receivableAccountNo?: string;
  interestIncomeAccountNo?: string;
  reason?: string;
  createdBy?: string;
  createdByProgram?: string;
};

export type PostInterestCorrectionResult = JournalPostResult & {
  invoiceDocumentId?: number;
  invoiceNumber?: string;
  correctionId?: number;
  correctedAmount?: number;
  claimOpenBalance?: number;
};

export type JournalPostResult = {
  ok: boolean;
  entryId?: JournalEntryId;
  entryNo?: string;
  entryHash?: string;
  appliedRules: string[];
  errors: string[];
};

export type ProposeInterestCorrectionInput = {
  invoiceDocumentId: number;
  /** Internal recursion guard for the central evidence audit. */
  skipEvidenceValidation?: boolean;
};

export type ProposeInterestCorrectionResult = {
  ok: boolean;
  invoiceDocumentId?: number;
  invoiceNumber?: string;
  hasProposal?: boolean;
  postedInterest?: number;
  lawfulInterest?: number;
  alreadyCorrected?: number;
  overClaimedAmount?: number;
  // The invoice's outstanding claim balance. A correction credits the receivable,
  // so it can only be booked against an outstanding receivable.
  outstandingClaimBalance?: number;
  possibleOutstandingInterestReceivable?: number;
  ambiguousInterestReceivable?: number;
  claimOverclaims?: Array<{
    claimId: number;
    claimDate: string;
    journalEntryId: number;
    overClaimedAmount: number;
  }>;
  // True when overClaimedAmount exceeds the outstanding balance — the excess was
  // already collected in cash and needs a REFUND, not a receivable credit.
  // postInterestCorrection refuses these.
  requiresRefund?: boolean;
  throughDate?: string;
  appliedRules: string[];
  errors: string[];
};

export type InterestCorrectionEvidencePlanResult =
  | {
      ok: true;
      receivableCredits: Array<{ accountNo: string; amountDkk: number }>;
      incomeDebits: Array<{ accountNo: string; amountDkk: number }>;
      causalClaims: Array<{
        claimId: number;
        claimDate: string;
        amountDkk: number;
        claimCeilingDkk: number;
      }>;
      earliestCorrectionDate: string | null;
    }
  | { ok: false; errors: string[] };

type CorrectionClaimBucket = {
  claimId: number;
  claimDate: string;
  ceilingOre: bigint;
  remainingOre: bigint;
  receivables: CorrectionAccountBucket[];
  incomes: CorrectionAccountBucket[];
};

export type JournalEntryInput = {
  transactionDate: string;
  text: string;
  documentId?: number;
  sourceBankTransactionId?: number;
  currency?: string;
  amountForeign?: number;
  amountDkk?: number;
  fxRateToDkk?: number;
  createdBy?: string;
  createdByProgram?: string;
  lines: JournalLineInput[];
};

export type JournalLineInput = {
  accountNo: string;
  debitAmount?: number;
  creditAmount?: number;
  vatCode?: string;
  text?: string;
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type ClaimReceivableResult =
  | { ok: true; balances: ClaimReceivableBalance[]; totalDkk: number }
  | { ok: false; errors: string[] };

export type InterestReceivableBalanceResult =
  | {
      ok: true;
      balances: ClaimReceivableBalance[];
      totalDkk: number;
      possibleTotalDkk: number;
      ambiguousDkk: number;
    }
  | { ok: false; errors: string[] };

export type InterestIncomeBalanceResult =
  | { ok: true; balances: ClaimReceivableBalance[]; totalDkk: number }
  | { ok: false; errors: string[] };

export type InvoiceStatusResult = {
  ok: boolean;
  invoiceDocumentId?: number;
  invoiceNumber?: string;
  grossAmount?: number;
  creditedAmount?: number;
  paidAmount?: number;
  openBalance?: number;
  claimOpenBalance?: number;
  asOfDate?: string;
  dueDate?: string;
  effectiveDueDate?: string;
  isOverdue?: boolean;
  overdueDays?: number;
  status?: "open" | "paid" | "credited" | "refunded" | "overpaid" | "written_off";
  payments?: Array<{
    paymentId: number;
    paymentDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  creditNotes?: Array<{
    documentId: number;
    creditNoteNumber: string;
    amount: number;
    issueDate: string | null;
  }>;
  refunds?: Array<{
    refundId: number;
    refundDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  claimPayments?: Array<{
    claimPaymentId: number;
    paymentDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  badDebtWriteOffs?: Array<{
    writeOffId: number;
    writeOffDate: string;
    grossAmount: number;
    netAmount: number;
    vatAmount: number;
    journalEntryId: number;
    note: string | null;
  }>;
  reminders?: Array<{
    reminderId: number;
    reminderDate: string;
    feeAmount: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  compensationClaims?: Array<{
    claimId: number;
    claimDate: string;
    amountDkk: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  interestClaims?: Array<{
    claimId: number;
    claimDate: string;
    amountDkk: number;
    referenceRatePercent: number;
    annualInterestRatePercent: number;
    overdueDays: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  interestCorrections?: Array<{
    correctionId: number;
    correctionDate: string;
    amountDkk: number;
    journalEntryId: number;
  }>;
  totalReminderFees?: number;
  totalCompensationClaims?: number;
  totalInterestClaims?: number;
  totalInterestCorrections?: number;
  totalClaimPayments?: number;
  totalBadDebtWrittenOff?: number;
  errors: string[];
};

definition.handlerSpecificParsing:
(ctx) => {
    const transactionDate = ctx.arg("--date");
    const reason = ctx.arg("--reason");
    const db = openCommandDb(ctx);
    migrate(db);
    const documentId = resolveInvoiceDocumentId(db, ctx);
    const result = postInterestCorrection(db, {
      invoiceDocumentId: documentId,
      transactionDate: transactionDate ?? undefined,
      reason: reason ?? undefined,
    });
    ctx.emitResult(result as Record<string, unknown>);
    db.close();
  }

