  const senderVatOrCvr = senderIdentity.ok ? senderIdentity.identifier : metadata.sender?.vatOrCvr?.trim();
  const excluded = excludeDocumentId ?? -1;
  const existingByIdentifier = senderVatOrCvr
    ? db.query(`SELECT id, document_no FROM documents WHERE document_type = 'purchase_sale' AND sender_vat_cvr = ? AND invoice_no = ? AND id != ? LIMIT 1`).get(senderVatOrCvr, invoiceNo, excluded) as { id: number; document_no: string } | null
    : null;
  const senderName = metadata.sender?.name?.trim();
  const existingByNonEuCountryAndName = senderIdentity.ok && senderIdentity.identifierKind === "non_eu" && senderName
    ? db.query(`SELECT id, document_no FROM documents WHERE document_type = 'purchase_sale' AND supplier_country_code = ? AND lower(trim(sender_name)) = lower(trim(?)) AND invoice_no = ? AND id != ? LIMIT 1`).get(senderIdentity.country, senderName, invoiceNo, excluded) as { id: number; document_no: string } | null
    : null;
  return existingByIdentifier ?? existingByNonEuCountryAndName;
}

export function resolveActor(input: ResolveActorInput = {}): ActorContext {
  const createdBy = trimToNull(input.createdBy)
    ?? inferredActorId()
    ?? trimToNull(input.fallbackActor?.createdBy)
    ?? "system";
  const createdByProgram = trimToNull(input.createdByProgram)
    ?? trimToNull(input.fallbackActor?.createdByProgram)
    ?? inferredActorVia()
    ?? (createdBy === "system" ? "system" : "rentemester");

  const auditActor = createdBy === "system" && createdByProgram === "system"
    ? "system"
    : `${createdBy} via ${createdByProgram}`;

  return { createdBy, createdByProgram, auditActor };
}

export function strengthenGdprErasureAliasesForIdentity(
  db: Database,
  identity: { name?: string | null; cvr?: string | null },
): void {
  const subject = resolveSubject(identity);
  if (!subject.name || !subject.cvr) return;
  const nameReference = subjectAuditReference(`name:${subject.name}`);
  const priorNameErasure = db
    .query(
      `SELECT 1
         FROM gdpr_erasures
        WHERE subject_key IN (?, ?)
        LIMIT 1`,
    )
    .get(nameReference, subject.name);
  if (!priorNameErasure) return;

  const scopeResolution = resolveSubjectScope(db, subject);
  if (!scopeResolution.ok) return;
  const erasures = loadErasures(
    db,
    // The name may already have become ambiguous. It is safe to inspect its
    // old hash here because strengthenErasureAliases still requires exact CVR
    // evidence on each source row before creating a stable binding.
    [...scopeResolution.scope.erasureSubjectKeys, nameReference],
  );
  const rows = collectSourceRows(db, scopeResolution.scope);
  strengthenErasureAliases(db, scopeResolution.scope, rows, erasures);
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

