export type SetDocumentCompanyContextInput = {
  documentId: number;
  sourceReference: string;
  businessUseReason: string;
  /** Deliberate human confirmation; API adapters must require it too. */
  confirm: boolean;
  createdBy?: string;
  createdByProgram?: string;
};

export type SetDocumentCompanyContextResult = {
  ok: boolean;
  documentId?: number;
  applied?: boolean;
  errors: string[];
};

export type DocumentMetadata = {
  source: string;
  documentType?: DocumentType;
  issueDate?: string;
  invoiceNo?: string;
  deliveryDescription?: string;
  amountIncVat?: number;
  currency?: string;
  sender?: { name?: string; address?: string; vatOrCvr?: string; countryCode?: string; identifierKind?: SupplierIdentifierKind };
  recipient?: { name?: string; address?: string; vatOrCvr?: string };
  vatAmount?: number;
  /** Purchase tax bases, retained verbatim with the voucher.  Omit for legacy uniform VAT documents. */
  purchaseVatLines?: PurchaseVatLine[];
  /** Human-confirmed invoice evidence required before a non-EU service can be
   * posted with automatic reverse-charge input-VAT deduction. */
  reverseChargeWordingConfirmed?: boolean;
  /** Explicit source fact: the issuer supplied a Danish simplified purchase invoice. */
  danishSimplifiedPurchaseInvoice?: boolean;
  paymentDetails?: string;
  exemptionCode?: DocumentExemptionCode;
  /** Imported bank row that is the immutable primary evidence for an internal voucher. */
  sourceBankTransactionId?: number;
  /** Human accounting explanation for why the internal voucher is booked. */
  accountingRationale?: string;
};

export type DocumentType =
  | "purchase_sale"
  | "cash_register_receipt"
  | "issued_invoice_pdf"
  | "internal_voucher";

export type PersistedSupplierIdentity = {
  supplierCountryCode: string | null | undefined;
  supplierIdentifierKind: string | null | undefined;
  supplierIdentityStatus: string | null | undefined;
  supplierVatOrCvr: string | null | undefined;
};

export type CompanySettings = {
  id: number;
  name: string;
  country: string;
  currency: string;
  cvr: string | null;
  fiscalYearStartMonth: number;
  fiscalYearLabelStrategy: FiscalYearLabelStrategy;
  /** CVR-register stamdata, last written by `company sync-cvr`. */
  address: string | null;
  postalCode: string | null;
  city: string | null;
  companyForm: string | null;
  industryCode: string | null;
  industryText: string | null;
  cvrStatus: string | null;
  auditWaived: boolean | null;
  /** ISO timestamp the CVR stamdata above was last synced; null when never. */
  cvrSyncedAt: string | null;
  /**
   * #221: the owner's own default payment terms — days from an invoice's issue
   * date to its due date. Captured once so every issued invoice inherits it.
   */
  paymentTermsDays: number;
  /**
   * #289: the VAT settlement cadence the company is registered for with SKAT
   * (`month` / `quarter` / `half-year`). Drives VAT period windows and their
   * filing deadlines. `null` means the company is NOT VAT-registered
   * (holding ApS, frivilligt momsfritaget, mikrovirksomhed under § 48); every
   * VAT-aware surface (dashboard, obligations, momsangivelse) gates on this.
   */
  vatPeriodType: VatPeriodType | null;
};

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type ActorContext = {
  createdBy: string;
  createdByProgram: string;
  auditActor: string;
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

