export function setDocumentCompanyContext(db: Database, input: SetDocumentCompanyContextInput): SetDocumentCompanyContextResult {
  const errors: string[] = [];
  if (!Number.isInteger(input.documentId) || input.documentId <= 0) errors.push("documentId must be a positive integer");
  const sourceReference = text(input.sourceReference, "sourceReference", errors);
  const businessUseReason = text(input.businessUseReason, "businessUseReason", errors);
  if (input.confirm !== true) errors.push("document company context requires explicit confirm: true");
  if (errors.length) return { ok: false, errors };
  try {
    return db.transaction(() => {
      const document = db.query(`SELECT id, status, document_type, amount_inc_vat, vat_amount, currency, sha256_hash, payload_json,
        sender_name, sender_address, sender_vat_cvr, supplier_country_code, supplier_identifier_kind, supplier_identity_status,
        recipient_name, recipient_address, recipient_vat_cvr, invoice_date, invoice_no, delivery_description
        FROM documents WHERE id = ?`).get(input.documentId) as Record<string, unknown> | null;
      if (!document) return { ok: false, errors: [`document ${input.documentId} does not exist`] };
      if (document.status !== "ingested") return { ok: false, errors: ["document must be ingested and unposted"] };
      if (db.query("SELECT 1 FROM journal_entries WHERE document_id = ? LIMIT 1").get(input.documentId)
        || db.query("SELECT 1 FROM import_document_links WHERE document_id = ? LIMIT 1").get(input.documentId)
        || db.query("SELECT 1 FROM dinero_import_document_links WHERE document_id = ? LIMIT 1").get(input.documentId)
        || db.query("SELECT 1 FROM payables WHERE document_id = ? LIMIT 1").get(input.documentId)) return { ok: false, errors: ["document is linked to accounting evidence"] };
      let payload: DocumentMetadata;
      try { payload = JSON.parse(String(document.payload_json)) as DocumentMetadata; } catch { return { ok: false, errors: ["document payload_json is not valid JSON"] }; }
      const simplifiedErrors = validateDanishSimplifiedPurchaseInvoiceMetadata(payload);
      const supplierErrors = deductibleDanishPurchaseSupplierErrors({
        supplierVatOrCvr: document.sender_vat_cvr as string | null,
        supplierCountryCode: document.supplier_country_code as string | null,
        supplierIdentifierKind: document.supplier_identifier_kind as string | null,
        supplierIdentityStatus: document.supplier_identity_status as string | null,
      });
      if (simplifiedErrors.length || supplierErrors.length || !persistedFactsMatchPayload(document, payload)) return { ok: false, errors: ["document does not independently satisfy Danish simplified purchase invoice facts", ...simplifiedErrors, ...supplierErrors] };
      const company = getCompanySettings(db);
      if (!company.name.trim() || company.country !== "DK" || !company.cvr || !company.address?.trim() || !company.postalCode?.trim() || !company.city?.trim() || company.vatPeriodType === null) {
        return { ok: false, errors: ["a complete VAT-registered Danish company profile is required"] };
      }
      const documentHash = String(document.sha256_hash);
      const payloadHash = sha256(String(document.payload_json));
      const snapshot = { id: company.id, name: company.name, country: company.country, cvr: company.cvr, address: company.address, postalCode: company.postalCode, city: company.city, vatPeriodType: company.vatPeriodType };
      const contextJson = canonicalJson({ documentHash, payloadHash, snapshot, sourceReference, businessUseReason });
      const contextHash = sha256(contextJson);
      const existing = db.query("SELECT document_sha256, payload_sha256, context_sha256 FROM document_company_contexts WHERE document_id = ?").get(input.documentId) as ContextRow | null;
      if (existing) return existing.document_sha256 === documentHash && existing.payload_sha256 === payloadHash && existing.context_sha256 === contextHash
        ? { ok: true, documentId: input.documentId, applied: false, errors: [] }
        : { ok: false, errors: ["document company context already exists with conflicting evidence"] };
      const actor = resolveActor({ createdBy: input.createdBy, createdByProgram: input.createdByProgram });
      db.query(`INSERT INTO document_company_contexts (document_id, company_id, document_sha256, payload_sha256, company_snapshot_json, company_snapshot_sha256, source_reference, business_use_reason, context_sha256, actor, program)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`).run(input.documentId, company.id, documentHash, payloadHash, canonicalJson(snapshot), sha256(canonicalJson(snapshot)), sourceReference!, businessUseReason!, contextHash, actor.createdBy, actor.createdByProgram);
      insertAuditLog(db, { eventType: "document_company_context_set", entityType: "document", entityId: input.documentId, message: `Recorded simplified-invoice company context for document ${input.documentId} (document_sha256=${documentHash}, payload_sha256=${payloadHash})`, createdBy: actor.createdBy, createdByProgram: actor.createdByProgram });
      return { ok: true, documentId: input.documentId, applied: true, errors: [] };
    }).immediate();
  } catch (error) { return { ok: false, errors: [error instanceof Error ? error.message : String(error)] }; }
}

function text(value: unknown, name: string, errors: string[]): string | null {
  if (typeof value !== "string" || value.trim().length === 0 || value.trim().length > 2000) { errors.push(`${name} is required and must be at most 2000 characters`); return null; }
  return value.trim();
}

export function validateDanishSimplifiedPurchaseInvoiceMetadata(metadata: DocumentMetadata): string[] {
  const errors: string[] = [];
  if (metadata.danishSimplifiedPurchaseInvoice !== true) {
    return ["danishSimplifiedPurchaseInvoice must be true"];
  }
  if ((metadata.documentType ?? "purchase_sale") !== "purchase_sale") {
    errors.push("Danish simplified invoice must be a purchase_sale document");
  }
  if ((metadata.currency ?? "DKK").trim().toUpperCase() !== "DKK") {
    errors.push("Danish simplified invoice must be denominated in DKK");
  }
  if (!looksLikeIsoDate(metadata.issueDate)) errors.push("Danish simplified invoice requires issueDate in YYYY-MM-DD format");
  if (!hasText(metadata.invoiceNo)) errors.push("Danish simplified invoice requires invoiceNo");
  if (!hasText(metadata.sender?.name) || !hasText(metadata.sender?.address)) {
    errors.push("Danish simplified invoice requires sender name and address");
  }
  const suppliedIdentity = metadata.sender?.countryCode !== undefined || metadata.sender?.identifierKind !== undefined;
  const identity = suppliedIdentity
    ? resolveSupplierIdentity({ country: metadata.sender?.countryCode ?? "", identifier: metadata.sender?.vatOrCvr, identifierKind: metadata.sender?.identifierKind })
    : resolveLegacySupplierIdentity(metadata.sender?.vatOrCvr);
  if (!identity.ok || identity.country !== "DK" || identity.identifierKind !== "dk_cvr") {
    errors.push("Danish simplified invoice requires a valid Danish supplier CVR");
  }
  if (!hasText(metadata.deliveryDescription)) errors.push("Danish simplified invoice requires deliveryDescription");
  const gross = metadata.amountIncVat;
  const vat = metadata.vatAmount;
  if (typeof gross !== "number" || !Number.isFinite(gross) || compareDkk(gross, 0) <= 0 || compareDkk(gross, 3000) > 0) {
    errors.push("Danish simplified invoice gross amount must be greater than 0 and at most DKK 3000");
  }
  if (metadata.purchaseVatLines !== undefined) {
    const lineErrors = validatePurchaseVatLines(metadata);
    errors.push(...lineErrors);
    if (lineErrors.length === 0) {
      const taxableLines = metadata.purchaseVatLines?.filter((line) => line.classification === "dk_purchase_25") ?? [];
      if (taxableLines.length === 0 || taxableLines.every((line) => compareDkk(line.vatAmount ?? 0, 0) <= 0)) {
        errors.push("Danish simplified invoice requires an explicitly documented taxable purchaseVatLines amount");
      }
    }
  } else if (typeof gross === "number" && Number.isFinite(gross) && typeof vat === "number" && Number.isFinite(vat)) {
    const net = roundDkk(gross - vat);
    const expectedVat = percentOfDkk(net, 25);
    if (compareDkk(vat, 0) <= 0 || compareDkk(vat, gross) >= 0 || compareDkk(Math.abs(roundDkk(vat - expectedVat)), 0.01) > 0) {
      errors.push("Danish simplified invoice requires VAT consistent with the 25% Danish standard rate");
    }
  } else {
    errors.push("Danish simplified invoice requires vatAmount");
  }
  return [...new Set(errors)];
}

export function deductibleDanishPurchaseSupplierErrors(
  input: PersistedSupplierIdentity,
): string[] {
  const identity = resolvePersistedSupplierIdentity(input);
  if (!identity.ok) {
    return ["deductible Danish purchase VAT requires a resolved Danish supplier identity; use human resolution or non_deductible instead"];
  }
  if (identity.identifierKind !== "dk_cvr" || identity.country !== "DK") {
    return [`deductible Danish purchase VAT requires a Danish supplier CVR, but the document supplier is ${identity.identifierKind}/${identity.country}; use the applicable reverse-charge flow or non_deductible instead`];
  }
  return [];
}

function persistedFactsMatchPayload(document: Record<string, unknown>, payload: DocumentMetadata): boolean {
  const identity = payload.sender?.countryCode !== undefined || payload.sender?.identifierKind !== undefined
    ? resolveSupplierIdentity({ country: payload.sender?.countryCode ?? "", identifier: payload.sender?.vatOrCvr, identifierKind: payload.sender?.identifierKind })
    : resolveLegacySupplierIdentity(payload.sender?.vatOrCvr);
  if (!identity.ok) return false;
  const sameNumber = (persisted: unknown, source: unknown) => typeof source === "number" && Number.isFinite(source) && Number(persisted) === source;
  return document.document_type === (payload.documentType ?? "purchase_sale")
    && sameNumber(document.amount_inc_vat, payload.amountIncVat)
    && sameNumber(document.vat_amount, payload.vatAmount)
    && String(document.currency).trim().toUpperCase() === (payload.currency ?? "DKK").trim().toUpperCase()
    && nullableText(document.sender_name) === (payload.sender?.name ?? null)
    && nullableText(document.sender_address) === (payload.sender?.address ?? null)
    && nullableText(document.sender_vat_cvr) === identity.identifier
    && nullableText(document.recipient_name) === (payload.recipient?.name ?? null)
    && nullableText(document.recipient_address) === (payload.recipient?.address ?? null)
    && nullableText(document.recipient_vat_cvr) === (payload.recipient?.vatOrCvr ?? null)
    && nullableText(document.invoice_date) === (payload.issueDate ?? null)
    && nullableText(document.invoice_no) === (payload.invoiceNo ?? null)
    && nullableText(document.delivery_description) === (payload.deliveryDescription ?? null);
}

export function getCompanySettings(db: Database): CompanySettings {
  // #289: older ledgers (and the base schema.sql) may lack `vat_period_type`.
  // Read it only when present; absent → fall back to the quarterly default so
  // a pre-#289 company is unaffected.
  const vatColumn = hasVatPeriodColumn(db) ? "vat_period_type" : "NULL AS vat_period_type";
  const row = db.query(
    `SELECT id, name, country, currency, cvr, fiscal_year_start_month, fiscal_year_label_strategy,
            address, postal_code, city, company_form, industry_code, industry_text,
            cvr_status, audit_waived, cvr_synced_at, payment_terms_days, ${vatColumn}
       FROM companies
      ORDER BY id ASC
      LIMIT 1`
  ).get() as {
    id: number;
    name: string;
    country: string;
    currency: string;
    cvr: string | null;
    fiscal_year_start_month: number;
    fiscal_year_label_strategy: FiscalYearLabelStrategy;
    address: string | null;
    postal_code: string | null;
    city: string | null;
    company_form: string | null;
    industry_code: string | null;
    industry_text: string | null;
    cvr_status: string | null;
    audit_waived: number | null;
    cvr_synced_at: string | null;
    payment_terms_days: number | null;
    vat_period_type: string | null;
  } | null;

  if (!row) return DEFAULT_COMPANY_SETTINGS;
  return {
    id: row.id,
    name: row.name,
    country: row.country,
    currency: row.currency,
    cvr: normalizeCvr(row.cvr),
    fiscalYearStartMonth: normalizeFiscalYearStartMonth(row.fiscal_year_start_month) ?? 1,
    fiscalYearLabelStrategy: normalizeFiscalYearLabelStrategy(row.fiscal_year_label_strategy) ?? "end-year",
    address: row.address,
    postalCode: row.postal_code,
    city: row.city,
    companyForm: row.company_form,
    industryCode: row.industry_code,
    industryText: row.industry_text,
    cvrStatus: row.cvr_status,
    auditWaived: row.audit_waived === null ? null : row.audit_waived === 1,
    cvrSyncedAt: row.cvr_synced_at,
    paymentTermsDays:
      normalizePaymentTermsDays(row.payment_terms_days) ?? DEFAULT_PAYMENT_TERMS_DAYS,
    // `null` in the column = "not VAT-registered" — preserved verbatim. A
    // stored value that fails normalisation (corrupt cell) falls back to the
    // historical default so legacy ledgers stay readable.
    vatPeriodType:
      row.vat_period_type === null
        ? null
        : normalizeVatPeriodType(row.vat_period_type) ?? DEFAULT_VAT_PERIOD_TYPE,
  };
}

const DEFAULT_COMPANY_SETTINGS: CompanySettings = {
  id: 1,
  name: "Rentemester company",
  country: "DK",
  currency: "DKK",
  cvr: null,
  fiscalYearStartMonth: 1,
  fiscalYearLabelStrategy: "end-year",
  address: null,
  postalCode: null,
  city: null,
  companyForm: null,
  industryCode: null,
  industryText: null,
  cvrStatus: null,
  auditWaived: null,
  cvrSyncedAt: null,
  paymentTermsDays: DEFAULT_PAYMENT_TERMS_DAYS,
  // Keep the module's eager default independent of the close/VAT graph.
  // `periods.ts` imports the close-readiness graph, which eventually reads
  // company settings.  The value is the same canonical default exported from
  // that module; using the literal here prevents an ESM initialization cycle
  // from observing its export before initialization.
  vatPeriodType: "quarter",
};

function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  const record = value as Record<string, unknown>;
  return `{${Object.keys(record).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(record[key])}`).join(",")}}`;
}

export function resolveActor(input: ResolveActorInput = {}): ActorContext {
  const createdBy = trimToNull(input.createdBy)
    ?? inferredActorId()
    ?? trimToNull(input.fallbackActor?.createdBy)
    ?? "system";
  const createdByProgram = trimToNull(input.createdByProgram)
    ?? trimToNull(input.fallbackActor?.createdByProgram)
    ?? inferredActorVia()
    ?? (createdBy === "system" ? "system" : "rentemester");

  const auditActor = createdBy === "system" && createdByProgram === "system"
    ? "system"
    : `${createdBy} via ${createdByProgram}`;

  return { createdBy, createdByProgram, auditActor };
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

