  if (row.page_count !== run.pages.length || row.item_count !== itemCount || row.text_length !== textLength || row.status !== run.status || row.error_code !== run.errorCode) throw new PdfParseError("tampered_result");
  return { parse: { documentId, sourceSha256: row.source_sha256_hash, parserId:row.parser_id, parserVersion:row.parser_version, contractVersion:row.contract_version, status:run.status, errorCode:run.errorCode, pageCount:run.pages.length, itemCount, textLength, resultHash:row.result_sha256_hash }, pages: run.pages.map(p=>({pageNumber:p.pageNumber,width:p.width,height:p.height,rotation:p.rotation,text:p.text,itemCount:p.layout.length,layoutHash:hash(p.layout)})) };
