export function openLedgerReadOnly(path: string): Database {
  return openSqliteReadOnlySnapshot(path);
}

export function openSqliteReadOnlySnapshot(path: string): Database {
  let captured: SourceFile[] | null = null;
  for (let attempt = 0; attempt < 4; attempt += 1) {
    const before = readSourceState(path);
    const after = readSourceState(path);
    if (sameState(before, after)) {
      captured = before;
      break;
    }
  }
  if (!captured) throw new Error("sqlite source changed during read-only snapshot");

  const snapshotRoot = mkdtempSync(join(tmpdir(), "rentemester-sqlite-readonly-"));
  const snapshotPath = join(snapshotRoot, "snapshot.sqlite");
  try {
    for (const source of captured) {
      // SQLite rebuilds shared-memory coordination for the private copy.
      if (source.suffix === "-shm") continue;
      writeFileSync(`${snapshotPath}${source.suffix}`, source.bytes, { mode: 0o600 });
    }

    // Let the disposable copy recover/checkpoint committed sidecars. A plain
    // sidecar-free file is opened directly below so corrupt-file diagnostics
    // remain the responsibility of the normal inspection contract.
    if (captured.some((source) => source.suffix === "-wal" || source.suffix === "-journal")) {
      const recovery = new Database(snapshotPath);
      try {
        recovery.query("SELECT 1 FROM sqlite_master LIMIT 1").get();
        recovery.run("PRAGMA wal_checkpoint(TRUNCATE)");
      } finally {
        recovery.close();
      }
    }

    const db = new Database(snapshotPath, { readonly: true });
    db.exec("PRAGMA query_only = ON; PRAGMA foreign_keys = ON");
    const close = db.close.bind(db);
    let closed = false;
    Object.defineProperty(db, "close", {
      value: () => {
        if (closed) return;
        closed = true;
        try {
          close();
        } finally {
          rmSync(snapshotRoot, { recursive: true, force: true });
        }
      },
    });
    return db;
  } catch (error) {
    rmSync(snapshotRoot, { recursive: true, force: true });
    throw error;
  }
}

export function inspectOpenLedger(db: Database): LedgerInspection {
  let currentVersion = 0;
  try {
    for (const name of ["schema_migrations", "companies", "audit_log"]) {
      if (!tableExists(db, name)) return corrupt(0, `missing critical schema primitive: ${name}`);
    }
    const columns = new Set((db.query("PRAGMA table_info(schema_migrations)").all() as Array<{ name: string }>).map((r) => r.name));
    for (const column of ["id", "name", "checksum", "applied_at", "applied_by_version"]) {
      if (!columns.has(column)) return corrupt(0, `schema_migrations is missing required column: ${column}`);
    }
    const rows = db.query("SELECT id, name, checksum FROM schema_migrations ORDER BY id").all() as SchemaMigrationIdentity[];
    currentVersion = rows.at(-1)?.id ?? 0;
    const supported = supportedSchemaMigrations();
    if (currentVersion > requiredVersion) {
      return { status: "newer", currentVersion, requiredVersion, pending: [], error: "database schema is newer than this Rentemester runtime" };
    }
    for (let i = 0; i < rows.length; i += 1) {
      const actual = rows[i]!;
      const expected = supported[i];
      if (!expected || actual.id !== expected.id || actual.name !== expected.name || actual.checksum !== expected.checksum) {
        return corrupt(currentVersion, `schema migration ${actual.id} is not the required checksummed append-only prefix`);
      }
    }
    const quick = db.query("PRAGMA quick_check").all() as Array<{ quick_check: string }>;
    if (quick.some((row) => Object.values(row)[0] !== "ok")) return corrupt(currentVersion, "sqlite quick_check failed");
    const foreignKeys = db.query("PRAGMA foreign_key_check").all();
    if (foreignKeys.length > 0) return corrupt(currentVersion, "sqlite foreign_key_check failed");
    if (currentVersion < requiredVersion) {
      return { status: "pending", currentVersion, requiredVersion, pending: supported.slice(currentVersion).map(({ id, name, checksum }) => ({ id, name, checksum })) };
    }
    const views = inspectSchemaViews(db);
    if (!views.ok) return corrupt(currentVersion, views.errors.join("; "));
    return { status: "current", currentVersion, requiredVersion, pending: [] };
  } catch (error) {
    return corrupt(currentVersion, error instanceof Error ? error.message : String(error));
  }
}

function tableExists(db: Database, name: string): boolean {
  return db.query("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?").get(name) != null;
}

export function supportedSchemaMigrations(): readonly SupportedSchemaMigration[] {
  return SUPPORTED_SCHEMA_MIGRATIONS;
}

export function inspectSchemaViews(db: Database): SchemaViewInspection {
  const expected = canonicalSchemaViews();
  const actualByName = new Map((db.query("SELECT name, sql FROM sqlite_master WHERE type = 'view'").all() as Array<{ name: string; sql: string | null }>).map((row) => [row.name, row.sql]));
  const errors: string[] = [];
  const actual = expected.map((view) => {
    const sql = actualByName.get(view.name) ?? null;
    const normalizedSql = sql === null ? null : normalizeViewSql(sql);
    if (sql === null) errors.push(`SCHEMA_VIEW_DRIFT:${view.name}:missing`);
    else if (normalizedSql !== view.normalizedSql) errors.push(`SCHEMA_VIEW_DRIFT:${view.name}:definition_mismatch`);
    return [view.name, normalizedSql];
  });
  return { ok: errors.length === 0, errors, affectedNames: errors.map((error) => error.split(":")[1]!), catalogueDigest: digest(expected.map((view) => [view.name, view.normalizedSql])), actualDigest: digest(actual) };
}

export function documentPdfParsedText(db: any, companyRoot: string, documentId: number, offset = 0, limit = 10) {
  const verified=readVerifiedPdfParse(db, companyRoot, documentId); const parse=verified?.parse ?? null;
  if (!verified) return { parse, pages: [], offset, limit, nextOffset: null };
  const pages=verified.pages.slice(offset,offset+limit);
  return { parse, pages, offset, limit, nextOffset: offset + pages.length < verified.pages.length ? offset + pages.length : null };
}

export function readVerifiedPdfParse(db: Database, companyRoot: string, documentId: number): VerifiedPdfParseDto | null {
  const row = db.query("SELECT r.*, d.sha256_hash AS document_sha256_hash, d.mime_type AS document_mime_type FROM document_pdf_parse_results r JOIN documents d ON d.id=r.document_id WHERE r.document_id=? ORDER BY r.id DESC LIMIT 1").get(documentId) as any;
  if (!row) return null;
  let source: ReturnType<typeof snapshotRegisteredPdfDocument>;
  try { source=snapshotRegisteredPdfDocument(db,companyRoot,documentId); } catch { throw new PdfParseError("tampered_result"); }
  if (row.document_id!==documentId || row.document_mime_type!=="application/pdf" || row.document_sha256_hash!==row.source_sha256_hash || source.sha256!==row.source_sha256_hash) throw new PdfParseError("tampered_result");
  const run = hydrateVerified(db, row, true);
  const itemCount=run.pages.reduce((n,p)=>n+p.layout.length,0), textLength=run.pages.reduce((n,p)=>n+p.text.length,0);
  if (row.page_count !== run.pages.length || row.item_count !== itemCount || row.text_length !== textLength || row.status !== run.status || row.error_code !== run.errorCode) throw new PdfParseError("tampered_result");
  return { parse: { documentId, sourceSha256: row.source_sha256_hash, parserId:row.parser_id, parserVersion:row.parser_version, contractVersion:row.contract_version, status:run.status, errorCode:run.errorCode, pageCount:run.pages.length, itemCount, textLength, resultHash:row.result_sha256_hash }, pages: run.pages.map(p=>({pageNumber:p.pageNumber,width:p.width,height:p.height,rotation:p.rotation,text:p.text,itemCount:p.layout.length,layoutHash:hash(p.layout)})) };
}

