export type ImportBankCsvOptions = {
  /** Numeric id or slug of the target bank account (#187). */
  account?: string | number;
  /** Named CSV import profile, e.g. "danske-bank" (#186). */
  profile?: string;
};

export type BankImportResult = {
  ok: boolean;
  importBatchId?: string;
  imported?: number;
  skippedDuplicates?: number;
  /** Human-readable descriptions of rows skipped as duplicates, for review. */
  skippedDuplicateRows?: string[];
  sourceFileHash?: string;
  // ===== BANK CLUSTER (#186-189) =====
  /** Numeric id of the bank account these rows were imported into (#187). */
  bankAccountId?: number;
  /** Slug of the bank account these rows were imported into (#187). */
  bankAccountSlug?: string;
  /** Name of the CSV import profile used, when one was supplied (#186). */
  profile?: string;
  /** Running-balance continuity warnings detected after import (#189). */
  balanceWarnings?: string[];
  /** First/last running balance of the batch when a profile supplied it (#189). */
  firstBalance?: number;
  lastBalance?: number;
  // ===== END BANK CLUSTER (#186-189) =====
  errors: string[];
};

export type BankAccount = {
  id: number;
  slug: string;
  name: string;
  bankName: string | null;
  registrationNo: string | null;
  accountNo: string | null;
  iban: string | null;
  bic: string | null;
  accountOwner: string | null;
  customerNo: string | null;
  currency: string;
  ledgerAccountNo: string | null;
  active: boolean;
  createdAt: string;
};

export type BankImportProfile = {
  name: string;
  /** Human label, e.g. "Danske Bank account export". */
  label: string;
  /** Pinned field delimiter. */
  delimiter: string;
  /**
   * Source encoding. "utf8" tolerates and strips a UTF-8 BOM; "windows-1252"
   * decodes legacy Danish exports. The importer falls back gracefully.
   */
  encoding: "utf8" | "windows-1252";
  /** Declared day/month order for non-ISO dates. */
  dateOrder: ProfileDateOrder;
  /**
   * Explicit source-column -> canonical-field map. Column keys are matched
   * case-insensitively against the normalised header: lower-cased, combining
   * diacritics stripped (NFD), whitespace collapsed to single spaces. Note
   * that Danish `ø`/`å` are single code points and survive normalisation, so
   * keys keep them (e.g. `beløb`). This replaces alias guessing entirely for a
   * profiled file.
   */
  columns: Record<string, ProfileFieldName>;
};

export type BankImportRow = {
  transactionDate: string;
  bookingDate?: string;
  text: string;
  amount: number;
  currency?: string;
  reference?: string;
  amountDkk?: number;
  fxRateToDkk?: number;
  // ===== BANK CLUSTER (#188,#189) =====
  // Extra columns preserved from the source export when a profile supplies
  // them. All optional; generic CSV imports leave them undefined.
  counterpartyName?: string;
  counterpartyAccount?: string;
  message?: string;
  archiveReference?: string;
  customerReference?: string;
  balanceAfter?: number;
  raw?: Record<string, string>;
  // ===== END BANK CLUSTER (#188,#189) =====
};

type CsvParseResult = {
  rows: Record<string, string>[];
  errors: string[];
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

type BalanceContinuityResult = {
  balanceWarnings?: string[];
  firstBalance?: number;
  lastBalance?: number;
};

type BalanceRow = {
  id: number;
  transaction_date: string;
  text: string;
  amount: number;
  balance_after: number | null;
};

type CandidateBilag = {
  documentId: number;
  documentNo: string | null;
  documentType: string;
  supplierName: string | null;
  deliveryDescription: string | null;
};

export type ResolveExceptionInput = {
  id: number;
  note?: string | null;
  resolvedBy?: string | null;
};

export type RecordExceptionInput = {
  type: string;
  severity?: ExceptionSeverity;
  relatedBankTransactionId?: number | null;
  relatedDocumentId?: number | null;
  message: string;
  requiredAction?: string | null;
  sourceEvidence?: unknown;
  postingPreview?: unknown;
  /** Stable identity for a resumable machine-created exception. */
  resolutionKey?: string | null;
};

