      profile: ctx.trimToNull(ctx.arg("--profile")) ?? undefined,
    });
    const sync = result.ok
      ? syncUnmatchedBankTransactionExceptions(db)
      : { ok: true, created: 0, errors: [] };
    ctx.emitResult({
      ...(result as Record<string, unknown>),
