export function executeLocalIdempotentMutation<T>(db: Database, input: {
  key?: string; operation: keyof typeof RETRY_CLASS_BY_OPERATION;
  /** Retained only for compatible callers; never used as receipt identity. */
  workspaceScope?: string; companyScope?: string;
  principal?: StablePrincipal; payload: Record<string, unknown>; actor: { createdBy: string; createdByProgram: string }; now?: Date; execute: () => T;
}): { result: T; receipt?: IdempotencyReceipt } {
  if (!input.key) return { result: input.execute() };
  if (RETRY_CLASS_BY_OPERATION[input.operation] !== "key-idempotent") throw new IdempotencyError("IDEMPOTENCY_STORAGE_FAILURE", `operation ${input.operation} does not accept a client idempotency key`);
  if (!input.principal?.subjectId) throw new IdempotencyError("IDEMPOTENCY_AUTH_REQUIRED", "idempotency keys require an authenticated user or workspace service principal");
  const payloadHash = canonicalPayloadHash(input.payload); const now = input.now ?? new Date(); const createdAt = now.toISOString(); const expiresAt = new Date(now.getTime() + IDEMPOTENCY_RETENTION_DAYS * 86_400_000).toISOString();
  let rejectedAudit: { eventType: "idempotency_conflict" | "idempotency_outcome_expired"; entityId: number; message: string } | undefined;
  try {
    return db.transaction(() => {
      const ledger = ledgerUuid(db);
      const prior = db.query(`SELECT t.id, t.payload_hash, o.outcome_json, t.created_at, t.expires_at
        FROM mutation_idempotency_tombstones t
        LEFT JOIN mutation_idempotency_outcomes o ON o.tombstone_id = t.id
        WHERE t.client_key_hash = ? AND t.operation = ? AND t.ledger_uuid = ? AND t.principal_kind = ? AND t.principal_subject_id = ?`).get(keyHash(input.key!), input.operation, ledger, input.principal!.kind, input.principal!.subjectId) as Row | null;
      if (prior) {
        if (prior.payload_hash !== payloadHash) { rejectedAudit = { eventType: "idempotency_conflict", entityId: prior.id, message: `Rejected conflicting idempotency retry for ${input.operation}` }; throw new IdempotencyError("IDEMPOTENCY_CONFLICT", "idempotency key was already used with a different validated payload"); }
        if (prior.outcome_json === null) { rejectedAudit = { eventType: "idempotency_outcome_expired", entityId: prior.id, message: `Idempotency outcome expired for ${input.operation}; key remains reserved` }; throw new IdempotencyError("IDEMPOTENCY_OUTCOME_EXPIRED", "idempotency outcome has expired; inspect canonical state and use a new key only for a new operation"); }
        insertAuditLog(db, { eventType: "idempotency_replay", entityType: "idempotency_receipt", entityId: prior.id, message: `Replayed durable idempotency outcome for ${input.operation}`, ...input.actor });
        return { result: JSON.parse(prior.outcome_json) as T, receipt: { replayed: true, receiptId: prior.id, createdAt: prior.created_at, expiresAt: prior.expires_at } };
      }
      const result = input.execute();
      // A result-shaped validation/domain rejection must leave no business,
      // receipt or audit writes and may be retried with the same key.
      if (isBusinessRejection(result)) throw new RollbackBusinessRejection(result);
      const outcome = JSON.stringify(result);
      if (Buffer.byteLength(outcome, "utf8") > IDEMPOTENCY_PAYLOAD_MAX_BYTES) throw new IdempotencyError("IDEMPOTENCY_STORAGE_FAILURE", "mutation outcome exceeds receipt limit");
      const receiptId = Number(db.query(`INSERT INTO mutation_idempotency_tombstones (client_key_hash,ledger_uuid,operation,principal_kind,principal_subject_id,payload_hash,created_at,expires_at) VALUES (?,?,?,?,?,?,?,?)`).run(keyHash(input.key!), ledger, input.operation, input.principal!.kind, input.principal!.subjectId, payloadHash, createdAt, expiresAt).lastInsertRowid);
      db.query("INSERT INTO mutation_idempotency_outcomes(tombstone_id,outcome_json,created_at) VALUES (?,?,?)").run(receiptId, outcome, createdAt);
      insertAuditLog(db, { eventType: "idempotency_original", entityType: "idempotency_receipt", entityId: receiptId, message: `Recorded idempotent ${input.operation} outcome`, ...input.actor });
      return { result, receipt: { replayed: false, receiptId, createdAt, expiresAt } };
    }).immediate();
  } catch (error) {
    if (error instanceof RollbackBusinessRejection) return { result: error.result };
    if (rejectedAudit) insertAuditLog(db, { ...rejectedAudit, entityType: "idempotency_receipt", ...input.actor });
    throw error;
  }
}

const RETRY_CLASS_BY_OPERATION: Readonly<Record<string, RetryClass>> = Object.freeze({
  journal_post: "key-idempotent", journal_reverse: "key-idempotent", expense_book: "key-idempotent", payable_register: "key-idempotent", payable_pay: "key-idempotent",
  bookkeeping_batch_apply: "natural-idempotent", reconcile_bank: "natural-idempotent", bank_import: "natural-idempotent",
  bank_reconciliation_correction_apply: "key-idempotent",
  direct_bank_purchase_payable_correction_apply: "key-idempotent",
  efaktura_send: "external-provider-reconciled", invoice_send_email: "unsafe-read-back",
});

export function canonicalPayloadHash(value: unknown): string {
  const serialized = canonical(value);
  if (Buffer.byteLength(serialized, "utf8") > IDEMPOTENCY_PAYLOAD_MAX_BYTES) throw new IdempotencyError("IDEMPOTENCY_STORAGE_FAILURE", "validated idempotency payload exceeds receipt limit");
  return createHash("sha256").update(serialized).digest("hex");
}

function ledgerUuid(db: Database): string {
  const row = db.query("SELECT ledger_uuid FROM ledger_identity WHERE id = 1").get() as { ledger_uuid?: string } | null;
  if (!row?.ledger_uuid) throw new IdempotencyError("IDEMPOTENCY_STORAGE_FAILURE", "ledger identity is unavailable");
  return row.ledger_uuid;
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

export function isBusinessRejection(value: unknown): value is BusinessRejection {
  return typeof value === "object" && value !== null && (value as { ok?: unknown }).ok === false;
}

export function validateIdempotencyKey(value: unknown): string | undefined {
  if (value === undefined || value === null) return undefined;
  if (typeof value !== "string" || value.trim().length === 0 || value.length > IDEMPOTENCY_KEY_MAX_LENGTH) throw new IdempotencyError("IDEMPOTENCY_STORAGE_FAILURE", `idempotency key must be a non-empty string of at most ${IDEMPOTENCY_KEY_MAX_LENGTH} characters`);
  return value;
}

export function applyDirectBankPurchasePayableCorrection(db:Database,input:ApplyDirectBankPurchasePayableCorrectionInput){
  if(!input.confirm)return {ok:false as const,errors:["CONFIRMATION_REQUIRED"]}; const actor=text(input.actor,160),reason=text(input.reason);const principal=input.principal?.kind==="user"||input.principal?.kind==="service-account"?input.principal:null;
  if(!actor||!principal?.subjectId)return {ok:false as const,errors:["ACTOR_AND_PRINCIPAL_REQUIRED"]};
  if(!reason)return {ok:false as const,errors:["REASON_REQUIRED"]};
  try{return db.transaction(()=>{const old=db.query("SELECT id,payable_id,payment_id,settlement_journal_entry_id,plan_hash FROM direct_bank_purchase_payable_corrections WHERE document_id=? AND bank_transaction_id=?").get(input.documentId,input.bankTransactionId) as any;if(old){if(old.plan_hash!==input.planHash)return {ok:false as const,errors:["IDEMPOTENCY_PAYLOAD_CONFLICT"]};return {ok:true as const,idempotent:true,id:old.id,payableId:old.payable_id,paymentId:old.payment_id,settlementJournalEntryId:old.settlement_journal_entry_id,errors:[] as string[]};}
    const planned=planDirectBankPurchasePayableCorrection(db,input);if(!planned.ok)return planned;if(planned.plan.planHash!==input.planHash)return {ok:false as const,errors:["PLAN_HASH_MISMATCH"]};
    const reversal=reverseJournalEntryInCurrentTransaction(db,{entryId:planned.plan.originalJournalEntryId,transactionDate:planned.plan.originalJournalDate,reason,createdBy:actor,createdByProgram:"direct-bank-purchase-payable-correction"});if(!reversal.ok)throw new Error(reversal.errors.join("; "));
    const payable=registerPayableInCurrentTransaction(db,{documentId:input.documentId,billDate:input.billDate,dueDate:input.dueDate,expenseAccountNo:input.expenseAccountNo,vatTreatment:input.vatTreatment,vendorId:input.vendorId,note:input.note,createdBy:actor,createdByProgram:"direct-bank-purchase-payable-correction"});if(!payable.ok||!payable.payableId)throw new Error(payable.errors.join("; "));
    const payment=payPayableFromBankInCurrentTransaction(db,{payableId:payable.payableId,bankTransactionId:input.bankTransactionId,paymentDate:planned.plan.bankDate,note:input.note,createdBy:actor,createdByProgram:"direct-bank-purchase-payable-correction",allowSupersededDirectBankJournalEntryId:planned.plan.originalJournalEntryId,skipBankSourceLink:true});if(!payment.ok||!payment.paymentId||!payment.journalEntryId)throw new Error(payment.errors.join("; "));
    const reconciliation=planBankReconciliationCorrection(db,{bankTransactionId:input.bankTransactionId,replacementJournalEntryId:payment.journalEntryId});if(!reconciliation.ok)throw new Error(reconciliation.errors.join("; "));
    const corrected=applyBankReconciliationCorrection(db,{bankTransactionId:input.bankTransactionId,replacementJournalEntryId:payment.journalEntryId,expectedReconciliationId:reconciliation.plan.reconciliationId,planHash:reconciliation.plan.planHash,reason,actor,principal,confirm:true});if(!corrected.ok)throw new Error(corrected.errors.join("; "));
    const row=db.query("INSERT INTO direct_bank_purchase_payable_corrections(document_id,bank_transaction_id,original_journal_entry_id,reversal_journal_entry_id,payable_id,payment_id,settlement_journal_entry_id,document_hash,original_journal_hash,plan_hash,reason,actor,principal_kind,principal_subject_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id").get(input.documentId,input.bankTransactionId,planned.plan.originalJournalEntryId,reversal.entryId,payable.payableId,payment.paymentId,payment.journalEntryId,planned.plan.documentHash,planned.plan.originalJournalHash,input.planHash,reason,actor,principal.kind,principal.subjectId,new Date().toISOString()) as any;
    insertAuditLog(db,{eventType:"direct_bank_purchase_payable_corrected",entityType:"bank_transaction",entityId:String(input.bankTransactionId),message:`Corrected direct-bank purchase into payable ${payable.payableId} and settled it on ${planned.plan.bankDate}`,createdBy:actor,createdByProgram:"direct-bank-purchase-payable-correction"});
    return {ok:true as const,idempotent:false,id:Number(row.id),payableId:payable.payableId,paymentId:payment.paymentId,settlementJournalEntryId:payment.journalEntryId,errors:[] as string[]};
  }).immediate();}catch(error){return {ok:false as const,errors:[error instanceof Error?error.message:String(error)]};}
}

export function reverseJournalEntryInCurrentTransaction(db: Database, input: ReverseJournalInput): JournalReverseResult {
  return reverseJournalEntryInternal(db, input, undefined, true);
}

export function registerPayableInCurrentTransaction(db: Database, input: RegisterPayableInput): RegisterPayableResult {
  return registerPayable(db, input, true);
}

export function payPayableFromBankInCurrentTransaction(db: Database, input: PayPayableInput): PayPayableResult {
  return payPayableFromBank(db, input, true);
}

export function planBankReconciliationCorrection(db: Database, input: BankReconciliationCorrectionPlanInput) {
  const context = correctionContext(db, input); if ("error" in context) return { ok:false as const, errors:[context.error] };
  const plan = { schemaVersion:"rentemester-bank-reconciliation-correction-v1", ...context };
  return { ok:true as const, plan:{ ...plan, planHash:planHash(plan) }, errors:[] as string[] };
}

export function applyBankReconciliationCorrection(db: Database, input: ApplyBankReconciliationCorrectionInput) {
  if (!input.confirm) return { ok:false as const, errors:["CONFIRMATION_REQUIRED"] };
  const actor = validText(input.actor,160), reason=validText(input.reason,1000);
  const principalKind = input.principal?.kind === "user" || input.principal?.kind === "service-account" ? input.principal.kind : null;
  const principalSubjectId = validText(input.principal?.subjectId,160);
  if (!actor || !principalKind || !principalSubjectId) return { ok:false as const, errors:["ACTOR_AND_PRINCIPAL_REQUIRED"] };
  if (!reason) return { ok:false as const, errors:["REASON_REQUIRED"] };
  return db.transaction(() => {
    const planned=planBankReconciliationCorrection(db,input); if(!planned.ok)return planned;
    if(planned.plan.reconciliationId!==input.expectedReconciliationId)return {ok:false as const,errors:["CURRENT_RECONCILIATION_CONFLICT"]};
    if(planned.plan.planHash!==input.planHash)return {ok:false as const,errors:["PLAN_HASH_MISMATCH"]};
    const [supersedesKind, supersedesId] = planned.plan.reconciliationId.split(":", 2);
    const inserted=db.query(`INSERT INTO bank_reconciliation_correction_events(bank_transaction_id,supersedes_kind,supersedes_id,supersedes_reconciliation_id,superseded_journal_entry_id,replacement_journal_entry_id,bank_account_no,bank_amount_dkk,replacement_journal_hash,plan_hash,reason,actor,principal_kind,principal_subject_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id`).get(planned.plan.bankTransactionId,supersedesKind,supersedesId,planned.plan.reconciliationId,planned.plan.currentJournalEntryId,planned.plan.replacementJournalEntryId,planned.plan.bankAccountNo,planned.plan.bankAmountDkk,planned.plan.replacementJournalHash,input.planHash,reason,actor,principalKind,principalSubjectId,new Date().toISOString()) as any;
    insertAuditLog(db,{eventType:"bank_reconciliation_corrected",entityType:"bank_transaction",entityId:String(input.bankTransactionId),message:`Superseded reconciliation ${planned.plan.reconciliationId} with journal ${planned.plan.replacementJournalEntryNo}`,createdBy:actor,createdByProgram:"bank-reconciliation-correction"});
    return {ok:true as const,id:Number(inserted.id),idempotent:false,planHash:input.planHash,reconciliationId:`correction:${inserted.id}`,errors:[] as string[]};
  }).immediate();
}

