export type BankAccount = {
  id: number;
  slug: string;
  name: string;
  bankName: string | null;
  registrationNo: string | null;
  accountNo: string | null;
  iban: string | null;
  bic: string | null;
  accountOwner: string | null;
  customerNo: string | null;
  currency: string;
  ledgerAccountNo: string | null;
  active: boolean;
  createdAt: string;
};

export type BankReconciliationFilters = {
  status?: ReconciliationStatus;
  textMatch?: string;
  amount?: number;
  // ===== BANK CLUSTER (#187) =====
  /** Restrict to a single bank account (numeric id). */
  bankAccountId?: number;
  // ===== END BANK CLUSTER (#187) =====
};

export type BankReconciliationReport = {
  ok: boolean;
  appliedRules: string[];
  periodStart: string;
  periodEnd: string;
  matchedCount: number;
  unmatchedCount: number;
  matchedAmountTotal: number;
  unmatchedAmountTotal: number;
  matched: Array<{
    bankTransactionId: number;
    transactionDate: string;
    text: string;
    amount: number;
    journalEntryId: number;
    journalEntryNo: string;
  }>;
  unmatched: Array<{
    bankTransactionId: number;
    transactionDate: string;
    text: string;
    amount: number;
    importBatchId: string | null;
  }>;
  errors: string[];
};

