export function inspectLedger(path: string): LedgerInspection {
  let db: Database | undefined;
  try {
    db = openLedgerReadOnly(path);
    return inspectOpenLedger(db);
  } catch (error) {
    return unavailable(error instanceof Error ? error.message : String(error));
  } finally {
    db?.close();
  }
}

export function openLedgerReadOnly(path: string): Database {
  return openSqliteReadOnlySnapshot(path);
}

export function inspectOpenLedger(db: Database): LedgerInspection {
  let currentVersion = 0;
  try {
    for (const name of ["schema_migrations", "companies", "audit_log"]) {
      if (!tableExists(db, name)) return corrupt(0, `missing critical schema primitive: ${name}`);
    }
    const columns = new Set((db.query("PRAGMA table_info(schema_migrations)").all() as Array<{ name: string }>).map((r) => r.name));
    for (const column of ["id", "name", "checksum", "applied_at", "applied_by_version"]) {
      if (!columns.has(column)) return corrupt(0, `schema_migrations is missing required column: ${column}`);
    }
    const rows = db.query("SELECT id, name, checksum FROM schema_migrations ORDER BY id").all() as SchemaMigrationIdentity[];
    currentVersion = rows.at(-1)?.id ?? 0;
    const supported = supportedSchemaMigrations();
    if (currentVersion > requiredVersion) {
      return { status: "newer", currentVersion, requiredVersion, pending: [], error: "database schema is newer than this Rentemester runtime" };
    }
    for (let i = 0; i < rows.length; i += 1) {
      const actual = rows[i]!;
      const expected = supported[i];
      if (!expected || actual.id !== expected.id || actual.name !== expected.name || actual.checksum !== expected.checksum) {
        return corrupt(currentVersion, `schema migration ${actual.id} is not the required checksummed append-only prefix`);
      }
    }
    const quick = db.query("PRAGMA quick_check").all() as Array<{ quick_check: string }>;
    if (quick.some((row) => Object.values(row)[0] !== "ok")) return corrupt(currentVersion, "sqlite quick_check failed");
    const foreignKeys = db.query("PRAGMA foreign_key_check").all();
    if (foreignKeys.length > 0) return corrupt(currentVersion, "sqlite foreign_key_check failed");
    if (currentVersion < requiredVersion) {
      return { status: "pending", currentVersion, requiredVersion, pending: supported.slice(currentVersion).map(({ id, name, checksum }) => ({ id, name, checksum })) };
    }
    const views = inspectSchemaViews(db);
    if (!views.ok) return corrupt(currentVersion, views.errors.join("; "));
    return { status: "current", currentVersion, requiredVersion, pending: [] };
  } catch (error) {
    return corrupt(currentVersion, error instanceof Error ? error.message : String(error));
  }
}

export function inspectPurchaseVatPreflight(db: Database, documentId: number, options: { clock?: VatValidationClock } = {}): PurchaseVatPreflightInspection {
  const extracted = inspectDocumentInvoiceExtraction(db, documentId);
  if (extracted && extracted.status !== "completed") return { ok: false, documentId, classification: "CONFLICT", cached: false, evidenceExpiresAt: null, wouldCallProvider: false, errors: ["invoice extraction evidence requires human resolution before VAT preflight"] };
  const now = (options.clock ?? systemVatValidationClock).now().toISOString();
  const facts = classification(supplier(db, documentId));
  const cached = freshEvidence(db, documentId, now, facts.country, facts.identifier);
  if (facts.classification === "DK" || facts.classification === "NON_EU") return { ok: true, documentId, classification: facts.classification, cached: !!cached, evidenceExpiresAt: cached?.evidence_expires_at ?? null, wouldCallProvider: false, errors: [] };
  if (facts.classification === "CONFLICT") return { ok: false, documentId, classification: "CONFLICT", cached: false, evidenceExpiresAt: null, wouldCallProvider: false, errors: ["documented supplier evidence is incomplete or conflicting; human resolution is required"] };
  return { ok: !!cached, documentId, classification: "EU", cached: !!cached, evidenceExpiresAt: cached?.evidence_expires_at ?? null, wouldCallProvider: !cached, errors: cached ? [] : ["fresh EU VAT validation evidence is required"] };
}

export async function ensurePurchaseVatPreflight(db: Database, documentId: number, provider: VatValidationProvider, options: { clock?: VatValidationClock; actor?: string } = {}) {
  const clock = options.clock ?? systemVatValidationClock;
  const inspection = inspectPurchaseVatPreflight(db, documentId, { clock });
  const facts = classification(supplier(db, documentId));
  if (inspection.ok) return { ...inspection, reusedEvidence: inspection.cached, exceptionId: undefined };
  // The inspection also detects extraction conflicts.  Do this before any
  // provider I/O, even when the persisted supplier identity itself looks EU.
  if (inspection.classification === "CONFLICT" || facts.classification === "CONFLICT") {
    const exception = recordException(db, { type: "PURCHASE_VAT_PREFLIGHT", severity: "high", relatedDocumentId: documentId, message: inspection.errors[0]!, requiredAction: "Resolve supplier country and typed identifier, then retry VAT preflight", resolutionKey: `purchase-vat-preflight:${documentId}` });
    event(db, { documentId, eventType: "preflight_failed", classification: facts.classification, providerStatus: "conflict", actor: options.actor, detail: inspection.errors, at: clock.now().toISOString() });
    return { ...inspection, reusedEvidence: false, exceptionId: exception.exceptionId };
  }
  const parsed = normalizeEuVatNumber(facts.identifier);
  if (!parsed) throw new Error("resolved EU supplier identity must have a normalizable VAT identifier");
  event(db, { documentId, eventType: "provider_requested", classification: "EU", providerStatus: "requested", country: facts.country, identifier: facts.identifier, actor: options.actor, at: clock.now().toISOString() });
  let result: VatValidationProviderResult;
  try { result = await provider.validate(parsed); } catch (cause) { result = { status: "unavailable", rawResponse: cause instanceof Error ? cause.message : "provider failure" }; }
  const now = clock.now().toISOString(); const expiresAt = new Date(clock.now().getTime() + PURCHASE_VAT_EVIDENCE_MAX_AGE_DAYS * 86400000).toISOString();
  event(db, { documentId, eventType: "provider_result", classification: "EU", providerStatus: result.status, country: facts.country, identifier: facts.identifier, name: result.name, address: result.address, actor: options.actor, expiresAt: result.status === "valid" ? expiresAt : null, detail: result.rawResponse, at: now });
  if (result.status === "valid") {
    storeViesValidation(db, { vatOrCvr: facts.identifier, valid: true, name: result.name, address: result.address, validatedAt: now, expiresAt, rawResponse: result.rawResponse });
    event(db, { documentId, eventType: "preflight_passed", classification: "EU", providerStatus: "valid", country: facts.country, identifier: facts.identifier, name: result.name, address: result.address, actor: options.actor, expiresAt, at: now });
    return { ...inspectPurchaseVatPreflight(db, documentId, { clock }), reusedEvidence: false, exceptionId: undefined };
  }
  const message = `EU VAT provider returned ${result.status}; purchase posting is blocked until VAT preflight succeeds`;
  const exception = recordException(db, { type: "PURCHASE_VAT_PREFLIGHT", severity: "high", relatedDocumentId: documentId, message, requiredAction: "Retry VAT preflight when authoritative supplier evidence is available", resolutionKey: `purchase-vat-preflight:${documentId}`, sourceEvidence: { providerStatus: result.status } });
  event(db, { documentId, eventType: "preflight_failed", classification: "EU", providerStatus: result.status, country: facts.country, identifier: facts.identifier, actor: options.actor, detail: result.rawResponse, at: now });
  return { ok: false, documentId, classification: "EU" as const, cached: false, evidenceExpiresAt: null, wouldCallProvider: true, errors: [message], reusedEvidence: false, exceptionId: exception.exceptionId };
}

export function createOfficialEuViesProvider(options: { fetchImpl?: typeof fetch; timeoutMs?: number; baseUrl?: string; clock?: () => Date } = {}) {
  const fetchImpl = options.fetchImpl ?? fetch;
  const timeoutMs = options.timeoutMs ?? DEFAULT_VIES_TIMEOUT_MS;
  const baseUrl = (options.baseUrl ?? OFFICIAL_EU_VIES_BASE_URL).replace(/\/$/, "");
  return {
    async validate(input: NormalizedEuVat): Promise<{ status: "valid" | "invalid" | "inconclusive" | "unavailable"; name?: string | null; address?: string | null; rawResponse?: string | null }> {
      // Path components are validated again at the network boundary. This
      // avoids turning a malformed persisted identity into a request path.
      if (!/^[A-Z]{2}$/.test(input.countryCode) || !/^[A-Z0-9]{2,14}$/.test(input.vatNumber) || input.normalized !== `${input.countryCode}${input.vatNumber}` || !EU_VAT_COUNTRY_CODES.has(input.countryCode)) {
        return { status: "inconclusive", rawResponse: "invalid normalized VIES path parameters" };
      }
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeoutMs);
      const requestedAt = (options.clock ?? (() => new Date()))().toISOString();
      try {
        const response = await fetchImpl(`${baseUrl}/ms/${encodeURIComponent(input.countryCode)}/vat/${encodeURIComponent(input.vatNumber)}`, { method: "GET", headers: { accept: "application/json" }, signal: controller.signal });
        let body: any;
        try { body = await response.json(); } catch { return { status: "inconclusive", rawResponse: JSON.stringify({ requestedAt, httpStatus: response.status, providerStatus: "malformed-json" }) }; }
        const rawResponse = JSON.stringify({ requestedAt, resultAt: (options.clock ?? (() => new Date()))().toISOString(), httpStatus: response.status, providerStatus: body?.userError ?? body?.status ?? null, response: body });
        if (!response.ok) return { status: "unavailable", rawResponse };
        const validity = extractValidity(body);
        // The official service can report `userError: VALID` alongside an
        // authoritative isValid boolean. Keep that provider status in the
        // raw evidence, but do not reject the actual validation result.
        const providerStatus = typeof body?.userError === "string" ? body.userError.trim() : "";
        if (validity === undefined || (providerStatus && providerStatus !== "VALID")) return { status: "inconclusive", rawResponse };
        return { status: validity ? "valid" : "invalid", name: availableIdentityText(body.name), address: availableIdentityText(body.address), rawResponse };
      } catch (error) {
        const timedOut = controller.signal.aborted || (error instanceof Error && (error.name === "AbortError" || error.name === "TimeoutError"));
        return { status: "unavailable", rawResponse: JSON.stringify({ requestedAt, resultAt: (options.clock ?? (() => new Date()))().toISOString(), providerStatus: timedOut ? "timeout" : "network-error" }) };
      } finally { clearTimeout(timer); }
    },
  };
}

const EU_VAT_COUNTRY_CODES = new Set([
  "AT", "BE", "BG", "CY", "CZ", "DE", "DK", "EE", "EL", "ES", "FI", "FR",
  "HR", "HU", "IE", "IT", "LT", "LU", "LV", "MT", "NL", "PL", "PT", "RO",
  "SE", "SI", "SK",
]);

function extractValidity(json: unknown): boolean | undefined {
  if (!json || typeof json !== "object") return undefined;
  const body = json as { isValid?: unknown; valid?: unknown };
  const values = [body.isValid, body.valid].filter((candidate): candidate is boolean => typeof candidate === "boolean");
  // A response with two disagreeing booleans is not an authoritative answer.
  // Accepting either field preserves both the official REST payload and the
  // established local/test adapter contract without weakening fail-closed I/O.
  return values.length > 0 && values.every((value) => value === values[0]) ? values[0] : undefined;
}

function availableIdentityText(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed && trimmed !== "---" ? trimmed : null;
}

