export type ReopenAccountingPeriodInput = {
  periodStart: string;
  periodEnd: string;
  kind?: AccountingPeriodKind;
  /** Mandatory free-text justification — recorded verbatim in the audit log. */
  reason: string;
  createdBy?: string;
  createdByProgram?: string;
};

export type ReopenAccountingPeriodResult = {
  ok: boolean;
  periodId?: number;
  periodStart?: string;
  periodEnd?: string;
  kind?: AccountingPeriodKind;
  /** The period's effective state AFTER the reopen — `open` on success. */
  effectiveStatus?: EffectivePeriodState;
  /** The audit actor the reopen was attributed to. */
  reopenedBy?: string;
  reason?: string;
  appliedRules: string[];
  errors: string[];
};

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type ActorContext = {
  createdBy: string;
  createdByProgram: string;
  auditActor: string;
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

