function emitMutation(ctx: CommandContext, operation: () => unknown): void {
  try {
    ctx.emitResult({ ok: true, accountingDraft: operation() });
  } catch (error) {
    ctx.emitResult({ ok: false, errors: [error instanceof Error ? error.message : String(error)] });
  }
