.status-row:last-child { border-bottom: none; }
.status-row .label { color: var(--ink); font-weight: 500; }
.status-row .detail { color: var(--ink-muted); font-size: 13px; }
.muted { color: var(--ink-muted); }
.empty-state {
  color: var(--ink-muted);
