export function getCompanySettings(db: Database): CompanySettings {
  // #289: older ledgers (and the base schema.sql) may lack `vat_period_type`.
  // Read it only when present; absent → fall back to the quarterly default so
  // a pre-#289 company is unaffected.
  const vatColumn = hasVatPeriodColumn(db) ? "vat_period_type" : "NULL AS vat_period_type";
  const row = db.query(
    `SELECT id, name, country, currency, cvr, fiscal_year_start_month, fiscal_year_label_strategy,
            address, postal_code, city, company_form, industry_code, industry_text,
            cvr_status, audit_waived, cvr_synced_at, payment_terms_days, ${vatColumn}
       FROM companies
      ORDER BY id ASC
      LIMIT 1`
  ).get() as {
    id: number;
    name: string;
    country: string;
    currency: string;
    cvr: string | null;
    fiscal_year_start_month: number;
    fiscal_year_label_strategy: FiscalYearLabelStrategy;
    address: string | null;
    postal_code: string | null;
    city: string | null;
    company_form: string | null;
    industry_code: string | null;
    industry_text: string | null;
    cvr_status: string | null;
    audit_waived: number | null;
    cvr_synced_at: string | null;
    payment_terms_days: number | null;
    vat_period_type: string | null;
  } | null;

  if (!row) return DEFAULT_COMPANY_SETTINGS;
  return {
    id: row.id,
    name: row.name,
    country: row.country,
    currency: row.currency,
    cvr: normalizeCvr(row.cvr),
    fiscalYearStartMonth: normalizeFiscalYearStartMonth(row.fiscal_year_start_month) ?? 1,
    fiscalYearLabelStrategy: normalizeFiscalYearLabelStrategy(row.fiscal_year_label_strategy) ?? "end-year",
    address: row.address,
    postalCode: row.postal_code,
    city: row.city,
    companyForm: row.company_form,
    industryCode: row.industry_code,
    industryText: row.industry_text,
    cvrStatus: row.cvr_status,
    auditWaived: row.audit_waived === null ? null : row.audit_waived === 1,
    cvrSyncedAt: row.cvr_synced_at,
    paymentTermsDays:
      normalizePaymentTermsDays(row.payment_terms_days) ?? DEFAULT_PAYMENT_TERMS_DAYS,
    // `null` in the column = "not VAT-registered" — preserved verbatim. A
    // stored value that fails normalisation (corrupt cell) falls back to the
    // historical default so legacy ledgers stay readable.
    vatPeriodType:
      row.vat_period_type === null
        ? null
        : normalizeVatPeriodType(row.vat_period_type) ?? DEFAULT_VAT_PERIOD_TYPE,
  };
}

const DEFAULT_COMPANY_SETTINGS: CompanySettings = {
  id: 1,
  name: "Rentemester company",
  country: "DK",
  currency: "DKK",
  cvr: null,
  fiscalYearStartMonth: 1,
  fiscalYearLabelStrategy: "end-year",
  address: null,
  postalCode: null,
  city: null,
  companyForm: null,
  industryCode: null,
  industryText: null,
  cvrStatus: null,
  auditWaived: null,
  cvrSyncedAt: null,
  paymentTermsDays: DEFAULT_PAYMENT_TERMS_DAYS,
  // Keep the module's eager default independent of the close/VAT graph.
  // `periods.ts` imports the close-readiness graph, which eventually reads
  // company settings.  The value is the same canonical default exported from
  // that module; using the literal here prevents an ESM initialization cycle
  // from observing its export before initialization.
  vatPeriodType: "quarter",
};

function hasVatPeriodColumn(db: Database): boolean {
  const cols = db.query("PRAGMA table_info(companies)").all() as Array<{ name: string }>;
  return cols.some((col) => col.name === "vat_period_type");
}

export function normalizeCvr(value?: string | null): string | null {
  const trimmed = value?.trim();
  if (!trimmed) return null;
  const stripped = trimmed.toUpperCase().replace(/^DK/, "");
  if (!/^\d{8}$/.test(stripped)) {
    throw new Error(`CVR must be 8 digits (optionally prefixed with DK), got: ${value}`);
  }
  return `DK${stripped}`;
}

export function normalizeFiscalYearStartMonth(value?: number | string | null) {
  const month = typeof value === "string" ? Number(value) : value;
  if (!Number.isInteger(month) || (month ?? 0) < 1 || (month ?? 0) > 12) return null;
  return month;
}

export function normalizeFiscalYearLabelStrategy(value?: string | null): FiscalYearLabelStrategy | null {
  if (value === "end-year" || value === "start-year" || value === "span") return value;
  return null;
}

export function normalizePaymentTermsDays(value?: number | string | null): number | null {
  if (value === undefined || value === null || value === "") return null;
  const days = typeof value === "string" ? Number(value) : value;
  if (!Number.isInteger(days) || (days as number) < 0 || (days as number) > 365) return null;
  return days as number;
}

export function normalizeVatPeriodType(value?: string | null): VatPeriodType | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return VAT_PERIOD_TYPES.has(trimmed as VatPeriodType) ? (trimmed as VatPeriodType) : null;
}

export function buildInvoiceList(db: Database, filters: InvoiceListFilters = {}): InvoiceListResult {
  const status = filters.status ?? "all";
  // EJER-1: resolve "as of" ONCE, defaulting to today (canonical Danish-time
  // clock), so every row's overdue check and the reported asOfDate agree —
  // the default path and the --as-of path share one definition of "i dag".
  const asOfDate = filters.asOfDate ?? todayIsoDate();
  const rows: InvoiceListRow[] = [];
  const normalizedCustomerCvr = normalizeCode(filters.customerCvr);
  const normalizedInvoiceNumber = normalizeText(filters.invoiceNumber);
  const normalizedQuery = normalizeText(filters.query);
  const minDays = Number.isFinite(filters.minDays) ? Math.max(0, Number(filters.minDays)) : 0;

  for (const doc of issuedInvoiceDocuments(db)) {
    if (filters.from && !compareDate(doc.invoice_date, filters.from, "from")) continue;
    if (filters.to && !compareDate(doc.invoice_date, filters.to, "to")) continue;
    if (normalizedInvoiceNumber && doc.invoice_no !== normalizedInvoiceNumber) continue;

    const payload = doc.payload_json ? JSON.parse(doc.payload_json) : null;
    const customerName = normalizeText(payload?.buyer?.name) || null;
    const customerCvr = normalizeCode(payload?.buyer?.vatOrCvr);
    const buyerEanNumber = normalizeEanNumber(payload?.buyer?.eanNumber);
    const buyerPublicRecipient = payload?.buyer?.publicRecipient === true || Boolean(buyerEanNumber);
    if (normalizedCustomerCvr && customerCvr !== normalizedCustomerCvr) continue;
    if (!includesFolded(customerName, filters.customer)) continue;
    if (normalizedQuery && !includesFolded(doc.invoice_no, normalizedQuery) && !includesFolded(customerName, normalizedQuery)) continue;

    const invoiceStatus = getInvoiceStatus(db, doc.id, asOfDate);
    if (!invoiceStatus.ok) continue;
    if (filters.minAmount !== undefined && Number(invoiceStatus.grossAmount ?? 0) < filters.minAmount) continue;
    if (filters.maxAmount !== undefined && Number(invoiceStatus.grossAmount ?? 0) > filters.maxAmount) continue;

    const peppolStatus = loadLatestPeppolStatus(db, doc.id);

    const row: InvoiceListRow = {
      documentId: doc.id,
      invoiceNumber: doc.invoice_no,
      invoiceDate: doc.invoice_date,
      customerName,
      customerCvr,
      buyerEanNumber,
      buyerPublicRecipient,
      peppolStatus,
      grossAmount: Number(invoiceStatus.grossAmount ?? 0),
      currency: doc.currency ?? "DKK",
      openBalance: Number(invoiceStatus.openBalance ?? 0),
      claimOpenBalance: Number(invoiceStatus.claimOpenBalance ?? 0),
      status: invoiceStatus.status!,
      effectiveDueDate: invoiceStatus.effectiveDueDate ?? null,
      isOverdue: Boolean(invoiceStatus.isOverdue),
      overdueDays: Number(invoiceStatus.overdueDays ?? 0),
    };

    if (status === "overdue") {
      if (!row.isOverdue || row.overdueDays < minDays) continue;
    } else if (status !== "all" && row.status !== status) {
      continue;
    }

    rows.push(row);
  }

  rows.sort((a, b) => {
    if (status === "overdue") {
      if (b.overdueDays !== a.overdueDays) return b.overdueDays - a.overdueDays;
      if (b.openBalance !== a.openBalance) return b.openBalance - a.openBalance;
    }
    const dueA = a.effectiveDueDate ?? "9999-12-31";
    const dueB = b.effectiveDueDate ?? "9999-12-31";
    if (dueA !== dueB) return dueA.localeCompare(dueB);
    return a.invoiceNumber.localeCompare(b.invoiceNumber);
  });

  return {
    ok: true,
    count: rows.length,
    status,
    asOfDate,
    query: normalizedQuery || undefined,
    rows,
    errors: [],
  };
}

export function todayIsoDate(): string {
  const override = process.env.RENTEMESTER_TODAY;
  if (isValidIsoDate(override)) return override.trim();
  return isoDateInTimeZone(new Date());
}

function normalizeCode(value: string | null | undefined) {
  const trimmed = normalizeText(value);
  return trimmed ? trimmed.toUpperCase() : null;
}

function normalizeText(value: unknown) {
  return typeof value === "string" ? value.trim() : "";
}

function issuedInvoiceDocuments(db: Database) {
  return db.query(
    `SELECT id, invoice_no, invoice_date, amount_inc_vat, currency, payload_json
     FROM documents
     WHERE document_type = 'issued_invoice'
     ORDER BY invoice_date ASC, id ASC`
  ).all() as Array<{
    id: number;
    invoice_no: string;
    invoice_date: string | null;
    amount_inc_vat: number | null;
    currency: string | null;
    payload_json: string | null;
  }>;
}

function compareDate(value: string | null | undefined, boundary: string, direction: "from" | "to") {
  if (!value) return false;
  return direction === "from" ? value >= boundary : value <= boundary;
}

export function normalizeEanNumber(value: unknown) {
  const trimmed = trimToNull(value);
  if (!trimmed) return null;
  const digitsOnly = trimmed.replace(/\s+/g, "");
  return /^\d{13}$/.test(digitsOnly) ? digitsOnly : null;
}

function includesFolded(haystack: string | null | undefined, needle: string | null | undefined) {
  const left = normalizeText(haystack).toLocaleLowerCase();
  const right = normalizeText(needle).toLocaleLowerCase();
  if (!right) return true;
  return left.includes(right);
}

export function getInvoiceStatus(
  db: Database,
  invoiceDocumentId: number,
  asOfDate?: string,
  options: { skipEvidenceValidation?: boolean } = {},
): InvoiceStatusResult {
  const invoice = getIssuedInvoice(db, invoiceDocumentId);
  if (!invoice) return { ok: false, errors: [`invoice document ${invoiceDocumentId} does not exist`] };
  if (invoice.document_type !== "issued_invoice") return { ok: false, errors: [`document ${invoiceDocumentId} is not an issued invoice`] };

  if (!options.skipEvidenceValidation) {
    const evidence = validateInvoiceJournalEvidence(db, { invoiceDocumentId });
    if (!evidence.ok) return { ok: false, errors: evidence.errors };
    const creditEvidence = validateInvoiceCreditNoteEvidence(db, { invoiceDocumentId });
    if (!creditEvidence.ok) return { ok: false, errors: creditEvidence.errors };
  }

  const payload = invoice.payload_json ? JSON.parse(invoice.payload_json) : null;

  const payments = db.query(
    `SELECT p.id, p.payment_date, p.amount, p.bank_transaction_id, p.journal_entry_id, p.note
     FROM invoice_payments p
     WHERE p.invoice_document_id = ?
     ORDER BY p.id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; payment_date: string; amount: number; bank_transaction_id: number | null; journal_entry_id: number | null; note: string | null }>;

  const creditNotes = db.query(
    `SELECT id, invoice_no, amount_inc_vat, invoice_date
     FROM documents
     WHERE document_type = 'credit_note' AND payment_details = ?
     ORDER BY id ASC`
  ).all(invoice.invoice_no) as Array<{ id: number; invoice_no: string; amount_inc_vat: number | null; invoice_date: string | null }>;

  const refunds = db.query(
    `SELECT id, refund_date, amount, bank_transaction_id, journal_entry_id, note
     FROM invoice_refunds WHERE invoice_document_id = ? ORDER BY id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; refund_date: string; amount: number; bank_transaction_id: number | null; journal_entry_id: number | null; note: string | null }>;

  const claimPayments = db.query(
    `SELECT id, payment_date, amount, bank_transaction_id, journal_entry_id, note
     FROM invoice_claim_payments WHERE invoice_document_id = ? ORDER BY id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; payment_date: string; amount: number; bank_transaction_id: number | null; journal_entry_id: number | null; note: string | null }>;

  const badDebtWriteOffs = db.query(
    `SELECT id, writeoff_date, gross_amount, net_amount, vat_amount, journal_entry_id, note
     FROM invoice_bad_debt_writeoffs WHERE invoice_document_id = ? ORDER BY id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; writeoff_date: string; gross_amount: number; net_amount: number; vat_amount: number; journal_entry_id: number; note: string | null }>;

  const reminders = db.query(
    `SELECT r.id, r.reminder_date, r.fee_amount, r.note, p.journal_entry_id
     FROM invoice_reminders r
     LEFT JOIN invoice_reminder_postings p ON p.reminder_id = r.id
     WHERE r.invoice_document_id = ? ORDER BY r.reminder_date ASC, r.id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; reminder_date: string; fee_amount: number; note: string | null; journal_entry_id: number | null }>;

  const compensationClaims = db.query(
    `SELECT c.id, c.claim_date, c.amount_dkk, c.note, p.journal_entry_id
     FROM invoice_compensation_claims c
     LEFT JOIN invoice_compensation_postings p ON p.compensation_claim_id = c.id
     WHERE c.invoice_document_id = ? ORDER BY c.claim_date ASC, c.id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; claim_date: string; amount_dkk: number; note: string | null; journal_entry_id: number | null }>;

  const interestClaims = db.query(
    `SELECT c.id, c.claim_date, c.amount_dkk, c.reference_rate_percent, c.annual_interest_rate_percent, c.overdue_days, c.note, p.journal_entry_id
     FROM invoice_interest_claims c
     LEFT JOIN invoice_interest_postings p ON p.interest_claim_id = c.id
     WHERE c.invoice_document_id = ? ORDER BY c.claim_date ASC, c.id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; claim_date: string; amount_dkk: number; reference_rate_percent: number; annual_interest_rate_percent: number; overdue_days: number; note: string | null; journal_entry_id: number | null }>;

  // Correcting reversals of over-claimed late interest (back-dated balance
  // reductions); they net DOWN the interest-claim balance.
  const interestCorrections = db.query(
    `SELECT id, correction_date, amount_dkk, journal_entry_id
     FROM invoice_interest_corrections
     WHERE invoice_document_id = ? ORDER BY id ASC`
  ).all(invoiceDocumentId) as Array<{ id: number; correction_date: string; amount_dkk: number; journal_entry_id: number }>;

  const grossAmount = roundDkk(Number(invoice.amount_inc_vat ?? 0));
  const creditedAmount = sumDkk(creditNotes.map((c) => Number(c.amount_inc_vat ?? 0)));
  const paidAmount = sumDkk(payments.map((p) => Number(p.amount)));
  const refundedAmount = sumDkk(refunds.map((r) => Number(r.amount)));
  const totalReminderFees = sumDkk(reminders.map((r) => Number(r.fee_amount)));
  const totalCompensationClaims = sumDkk(compensationClaims.map((c) => Number(c.amount_dkk)));
  const totalInterestCorrections = sumDkk(interestCorrections.map((c) => Number(c.amount_dkk)));
  const totalInterestClaims = subtractDkk(sumDkk(interestClaims.map((c) => Number(c.amount_dkk))), totalInterestCorrections);
  const totalClaimPayments = sumDkk(claimPayments.map((p) => Number(p.amount)));
  const totalBadDebtWrittenOff = sumDkk(badDebtWriteOffs.map((w) => Number(w.gross_amount)));
  const openBalance = subtractDkk(addDkk(subtractDkk(grossAmount, creditedAmount, paidAmount), refundedAmount), totalBadDebtWrittenOff);
  const claimOpenBalance = subtractDkk(addDkk(openBalance, totalReminderFees, totalCompensationClaims, totalInterestClaims), totalClaimPayments);
  const dueDate = typeof payload?.dueDate === "string" ? payload.dueDate : undefined;
  const effectiveDueDate = dueDate ?? (invoice.invoice_date ? addDays(invoice.invoice_date, 30) : undefined);
  // EJER-1: when no as-of date is given, compare against TODAY (canonical
  // Danish-time clock, RENTEMESTER_TODAY-overridable). The old default
  // compared the due date against itself, so the default path never saw an
  // invoice as overdue while the --as-of path did.
  const comparisonDate = asOfDate ?? todayIsoDate();
  const overdueDays = effectiveDueDate && openBalance > 0 ? Math.max(0, diffDays(effectiveDueDate, comparisonDate)) : 0;
  const isOverdue = overdueDays > 0;
  // Status ladder: a written-off or refunded zero-balance invoice must never be
  // mislabelled "paid". Write-off and refund take precedence over "paid", and
  // "refunded" is decoupled from creditedAmount so a refund without a credit
  // note (e.g. an overpayment returned) is still labelled "refunded".
  const status = openBalance > 0
    ? "open"
    : openBalance < 0
      ? "overpaid"
      : totalBadDebtWrittenOff > 0
        ? "written_off"
        : refundedAmount > 0
          ? "refunded"
          : creditedAmount === grossAmount && paidAmount === 0
            ? "credited"
            : "paid";

  return {
    ok: true,
    invoiceDocumentId,
    invoiceNumber: invoice.invoice_no,
    grossAmount,
    creditedAmount,
    paidAmount,
    openBalance,
    claimOpenBalance,
    asOfDate: comparisonDate,
    dueDate,
    effectiveDueDate,
    isOverdue,
    overdueDays,
    status,
    payments: payments.map((p) => ({ paymentId: p.id, paymentDate: p.payment_date, amount: roundDkk(Number(p.amount)), bankTransactionId: p.bank_transaction_id, journalEntryId: p.journal_entry_id == null ? null : Number(p.journal_entry_id), note: p.note })),
    creditNotes: creditNotes.map((c) => ({ documentId: c.id, creditNoteNumber: c.invoice_no, amount: roundDkk(Number(c.amount_inc_vat ?? 0)), issueDate: c.invoice_date })),
    refunds: refunds.map((r) => ({ refundId: r.id, refundDate: r.refund_date, amount: roundDkk(Number(r.amount)), bankTransactionId: r.bank_transaction_id, journalEntryId: r.journal_entry_id == null ? null : Number(r.journal_entry_id), note: r.note })),
    claimPayments: claimPayments.map((p) => ({ claimPaymentId: p.id, paymentDate: p.payment_date, amount: roundDkk(Number(p.amount)), bankTransactionId: p.bank_transaction_id, journalEntryId: p.journal_entry_id == null ? null : Number(p.journal_entry_id), note: p.note })),
    badDebtWriteOffs: badDebtWriteOffs.map((w) => ({ writeOffId: w.id, writeOffDate: w.writeoff_date, grossAmount: roundDkk(Number(w.gross_amount)), netAmount: roundDkk(Number(w.net_amount)), vatAmount: roundDkk(Number(w.vat_amount)), journalEntryId: Number(w.journal_entry_id), note: w.note })),
    reminders: reminders.map((r) => ({ reminderId: r.id, reminderDate: r.reminder_date, feeAmount: roundDkk(Number(r.fee_amount)), note: r.note, journalEntryId: r.journal_entry_id == null ? null : Number(r.journal_entry_id) })),
    compensationClaims: compensationClaims.map((c) => ({ claimId: c.id, claimDate: c.claim_date, amountDkk: roundDkk(Number(c.amount_dkk)), note: c.note, journalEntryId: c.journal_entry_id == null ? null : Number(c.journal_entry_id) })),
    interestClaims: interestClaims.map((c) => ({
      claimId: c.id,
      claimDate: c.claim_date,
      amountDkk: roundDkk(Number(c.amount_dkk)),
      referenceRatePercent: roundDkk(Number(c.reference_rate_percent)),
      annualInterestRatePercent: roundDkk(Number(c.annual_interest_rate_percent)),
      overdueDays: Number(c.overdue_days),
      note: c.note,
      journalEntryId: c.journal_entry_id == null ? null : Number(c.journal_entry_id),
    })),
    interestCorrections: interestCorrections.map((c) => ({ correctionId: c.id, correctionDate: c.correction_date, amountDkk: roundDkk(Number(c.amount_dkk)), journalEntryId: Number(c.journal_entry_id) })),
    totalReminderFees,
    totalCompensationClaims,
    totalInterestClaims,
    totalInterestCorrections,
    totalClaimPayments,
    totalBadDebtWrittenOff,
    errors: [],
  };
}

function loadLatestPeppolStatus(db: Database, invoiceDocumentId: number): InvoicePeppolStatus | null {
  try {
    const row = db
      .query(
        `SELECT s.submission_reference,
                COALESCE(d.document_id, CASE WHEN s.status = 'acknowledged' THEN s.transmission_id END, q.document_id) AS transmission_id,
                COALESCE(d.observed_at, CASE WHEN s.status = 'acknowledged' THEN s.acknowledged_at END) AS acknowledged_at,
                CASE
                  WHEN d.id IS NOT NULL OR s.status = 'acknowledged' THEN 'acknowledged'
                  WHEN latest.event_type = 'delivery_reserved' THEN 'in_progress'
                  WHEN latest.event_type = 'delivery_failed' AND COALESCE(latest.status, '') <> 'pre-acceptance-failed' THEN 'uncertain'
                  WHEN q.id IS NOT NULL AND (
                    q.status IN ('document-not-valid', 'unable-to-deliver', 'unknown-server-error')
                    OR latest.status IN ('document-not-valid', 'unable-to-deliver', 'unknown-server-error')
                  ) THEN 'failed'
                  WHEN q.id IS NOT NULL AND latest.event_type IN ('queued', 'status_observed') THEN 'queued'
                  ELSE 'retryable'
                END AS status
         FROM peppol_submissions s
         LEFT JOIN peppol_submission_events d ON d.id = (
           SELECT id FROM peppol_submission_events
           WHERE submission_id = s.id AND event_type = 'delivered'
           ORDER BY id DESC LIMIT 1
         )
         LEFT JOIN peppol_submission_events q ON q.id = (
           SELECT id FROM peppol_submission_events
           WHERE submission_id = s.id AND event_type = 'queued'
           ORDER BY id DESC LIMIT 1
         )
         LEFT JOIN peppol_submission_events latest ON latest.id = (
           SELECT id FROM peppol_submission_events
           WHERE submission_id = s.id ORDER BY id DESC LIMIT 1
         )
         WHERE s.invoice_document_id = ?
         ORDER BY CASE WHEN d.id IS NOT NULL OR s.status = 'acknowledged' THEN 0 ELSE 1 END, s.id DESC
         LIMIT 1`,
      )
      .get(invoiceDocumentId) as
      | {
          status: "queued" | "failed" | "uncertain" | "retryable" | "in_progress" | "acknowledged";
          submission_reference: string;
          transmission_id: string | null;
          acknowledged_at: string | null;
        }
      | null;
    if (!row) return null;
    return {
      status: row.status,
      submissionReference: row.submission_reference,
      transmissionId: row.transmission_id,
      acknowledgedAt: row.acknowledged_at,
    };
  } catch {
    // Table not migrated yet (older fixture/db) → treat as "never sent".
    return null;
  }
}

export function buildOverdueInvoiceList(db: Database, filters: Omit<InvoiceListFilters, "status"> = {}) {
  return buildInvoiceList(db, { ...filters, status: "overdue" });
}

export function listBankTransactions(db: Database, filters: BankReconciliationFilters & { from?: string; to?: string } = {}): BankTransactionListResult {
  const errors: string[] = [];
  if (filters.from && !looksLikeIsoDate(filters.from)) errors.push("from must be YYYY-MM-DD when present");
  if (filters.to && !looksLikeIsoDate(filters.to)) errors.push("to must be YYYY-MM-DD when present");
  const statusError = validateStatus(filters.status);
  if (statusError) errors.push(statusError);
  if (errors.length > 0) return { ok: false, count: 0, rows: [], errors };

  const bankAccountId = filters.bankAccountId ?? null;
  const rows = db.query(
    `SELECT bt.id, bt.transaction_date, bt.booking_date, bt.text, bt.amount, bt.currency, bt.reference, bt.import_batch_id, bt.status, bt.bank_account_id,
            br.journal_entry_id, br.journal_entry_no AS entry_no,
            CASE WHEN br.journal_entry_id IS NULL THEN 'unmatched' ELSE 'matched' END as reconciliation_status
     FROM bank_transactions bt
     LEFT JOIN bank_journal_reconciliations br ON br.bank_transaction_id = bt.id
     WHERE (? IS NULL OR bt.transaction_date >= ?)
       AND (? IS NULL OR bt.transaction_date <= ?)
       AND (? IS NULL OR bt.bank_account_id = ?)
     ORDER BY bt.transaction_date DESC, bt.id DESC`
  ).all(
    filters.from ?? null, filters.from ?? null,
    filters.to ?? null, filters.to ?? null,
    bankAccountId, bankAccountId,
  ) as Array<{
    id: number;
    transaction_date: string;
    booking_date: string | null;
    text: string;
    amount: number;
    currency: string;
    reference: string | null;
    import_batch_id: string | null;
    status: string;
    bank_account_id: number | null;
    journal_entry_id: number | null;
    entry_no: string | null;
    reconciliation_status: "matched" | "unmatched";
  }>;

  const filtered = rows.filter((row) => matchesFilters(row, filters)).map((row) => ({
    id: row.id,
    transactionDate: row.transaction_date,
    bookingDate: row.booking_date,
    text: row.text,
    amount: roundDkk(Number(row.amount)),
    currency: row.currency,
    reference: row.reference,
    importBatchId: row.import_batch_id,
    bankAccountId: row.bank_account_id,
    ledgerStatus: row.status,
    reconciliationStatus: row.reconciliation_status,
    journalEntryId: row.journal_entry_id,
    journalEntryNo: row.entry_no,
  }));

  return { ok: true, count: filtered.length, rows: filtered, errors: [] };
}

export function isValidIsoDate(value: unknown): value is string {
  if (typeof value !== "string") return false;
  const trimmed = value.trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return false;
  const date = new Date(`${trimmed}T00:00:00Z`);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === trimmed;
}

function validateStatus(status?: string) {
  if (!status || status === "all" || status === "matched" || status === "unmatched") return null;
  return "status must be one of all, matched, unmatched when present";
}

function matchesFilters(row: {
  amount: number;
  text: string;
  reconciliation_status: "matched" | "unmatched";
}, filters: BankReconciliationFilters = {}) {
  const status = normalizedStatus(filters.status);
  const textMatch = normalizeTextMatch(filters.textMatch);
  if (status !== "all" && row.reconciliation_status !== status) return false;
  if (typeof filters.amount === "number" && Number.isFinite(filters.amount) && roundDkk(row.amount) !== roundDkk(filters.amount)) return false;
  if (textMatch && !row.text.toLowerCase().includes(textMatch)) return false;
  return true;
}

export function roundDkk(value: number) {
  return Number.isFinite(value) ? fromScaledInt(scaledInt(value, 2), 2) : NaN;
}

export function listExceptions(db: Database, input: ListExceptionsInput = {}) {
  const status = normalizeStatus(input.status);
  if (!status) return { ok: false, count: 0, rows: [], errors: ["status must be open, resolved, or all when present"] };

  const boundary = loadArchivedBoundary(db);
  // The subject date is the date of the bank transaction / document the
  // exception concerns — that is what places it in (or out of) an archived
  // period. An exception with no dated subject has no archived classification.
  const rawRows = db.query(
    `SELECT e.id, e.type, e.severity, e.status, e.related_bank_transaction_id, e.related_document_id,
            e.message, e.required_action, e.source_evidence, e.posting_preview,
            e.created_at, e.resolved_at, e.resolved_by, e.resolution_note,
            COALESCE(bt.transaction_date, d.invoice_date, substr(d.upload_datetime, 1, 10)) AS subject_date
     FROM exceptions e
     LEFT JOIN bank_transactions bt ON bt.id = e.related_bank_transaction_id
     LEFT JOIN documents d ON d.id = e.related_document_id
     WHERE (? = 'all' OR e.status = ?)
     ORDER BY e.id DESC`
  ).all(status, status) as Array<any>;

  const includeArchived = input.includeArchived === true;
  const rows = rawRows
    .map((row) => ({
      id: row.id,
      type: row.type,
      severity: row.severity,
      status: row.status,
      relatedBankTransactionId: row.related_bank_transaction_id,
      relatedDocumentId: row.related_document_id,
      message: row.message,
      requiredAction: row.required_action,
      sourceEvidence: parseJson(row.source_evidence),
      postingPreview: parseJson(row.posting_preview),
      createdAt: row.created_at,
      resolvedAt: row.resolved_at,
      resolvedBy: row.resolved_by,
      resolutionNote: row.resolution_note,
      /** True when the exception belongs to an archived/closed period. */
      archived: isArchivedDate(row.subject_date, boundary),
    }))
    .filter((row) => includeArchived || !row.archived);

  return { ok: true, count: rows.length, rows, errors: [] };
}

function normalizeStatus(status?: ExceptionStatus) {
  if (!status || status === "open" || status === "resolved" || status === "all") return status ?? "open";
  return null;
}

function loadArchivedBoundary(db: Database): ArchivedBoundary {
  const opening = db
    .query(`SELECT cut_over_date FROM opening_balances LIMIT 1`)
    .get() as { cut_over_date: string } | null;
  const periods = db
    .query(
      `SELECT period_start, period_end FROM accounting_periods
        WHERE status IN ('closed', 'reported')`,
    )
    .all() as Array<{ period_start: string; period_end: string }>;
  return {
    cutOverDate: opening?.cut_over_date ?? null,
    closedPeriods: periods.map((p) => ({ start: p.period_start, end: p.period_end })),
  };
}

function parseJson<T = unknown>(value: string | null) {
  if (!value) return null as T | null;
  try {
    return JSON.parse(value) as T;
  } catch {
    return value as T;
  }
}

function isArchivedDate(subjectDate: string | null, boundary: ArchivedBoundary): boolean {
  if (!subjectDate) return false;
  if (boundary.cutOverDate && subjectDate < boundary.cutOverDate) return true;
  return boundary.closedPeriods.some((p) => subjectDate >= p.start && subjectDate <= p.end);
}

export function vatPeriodsForYear(year: number, type: VatPeriodType | null): VatPeriodWindow[] {
  if (type === null) return [];
  const span = vatPeriodMonthSpan(type);
  const windows: VatPeriodWindow[] = [];
  for (let startMonth = 1; startMonth <= 12; startMonth += span) {
    windows.push(vatPeriodWindowFor(`${year}-${pad2(startMonth)}-01`, type));
  }
  return windows;
}

export function buildVatReport(db: Database, periodStart: string, periodEnd: string): VatPeriodReport {
  const errors: string[] = [];
  const vatPeriodType = getCompanySettings(db).vatPeriodType;
  if (!looksLikeIsoDate(periodStart)) errors.push("periodStart must be YYYY-MM-DD");
  if (!looksLikeIsoDate(periodEnd)) errors.push("periodEnd must be YYYY-MM-DD");
  if (errors.length === 0 && periodStart > periodEnd) errors.push("periodStart must be before or equal to periodEnd");
  const canonicalWindow =
    errors.length === 0 && vatPeriodType !== null
      ? vatPeriodWindowFor(periodStart, vatPeriodType)
      : null;
  const filingDeadline =
    canonicalWindow?.start === periodStart && canonicalWindow.end === periodEnd
      ? canonicalWindow.filingDeadline
      : null;
  if (errors.length > 0) {
    return {
      ok: false,
      appliedRules: [RULE_ID],
      periodStart,
      periodEnd,
      vatPeriodType,
      filingDeadline,
      outputVat: 0,
      inputVat: 0,
      netVatPayable: 0,
      purchaseBase25: 0,
      salesBase25: 0,
      reverseChargeSalesBase: 0,
      foreignReverseChargeSalesBase: 0,
      domesticReverseChargeSalesBase: 0,
      reverseChargePurchaseBase: 0,
      euGoodsAcquisitionPurchaseBase: 0,
      euGoodsAcquisitionOutputVat: 0,
      nonEuServiceReverseChargePurchaseBase: 0,
      reverseChargePurchaseOutputVat: 0,
      representationPurchaseBase: 0,
      badDebtReliefBase25: 0,
      exemptSalesBase: 0,
      ossConsumerSalesBase: 0,
      ossConsumerSalesEntryCount: 0,
      journalEntryCount: 0,
      reversedJournalEntryCount: 0,
      reversalJournalEntryCount: 0,
      totalJournalEntryCount: 0,
      linesConsidered: 0,
      reversedLinesConsidered: 0,
      reversalLinesConsidered: 0,
      totalLinesConsidered: 0,
      rubrikker: emptyVatRubric(),
      warnings: [],
      errors,
    };
  }

  const rows = db.query(
    `SELECT je.id as entry_id, jl.id as line_id, je.status, je.reversal_of_entry_id,
            je.currency as entry_currency, je.created_by_program,
            a.account_no, a.type as account_type, a.normal_balance,
            a.default_vat_code, jl.debit_amount, jl.credit_amount, jl.vat_code
     FROM journal_entries je
     JOIN journal_lines jl ON jl.journal_entry_id = je.id
     JOIN accounts a ON a.id = jl.account_id
     WHERE je.transaction_date >= ? AND je.transaction_date <= ?
     ORDER BY je.id ASC, jl.id ASC`
  ).all(periodStart, periodEnd) as Array<{
    entry_id: number;
    line_id: number;
    status: string;
    reversal_of_entry_id: number | null;
    entry_currency: string;
    created_by_program: string;
    account_no: string;
    account_type: string;
    normal_balance: "debit" | "credit";
    default_vat_code: string | null;
    debit_amount: number;
    credit_amount: number;
    vat_code: string | null;
  }>;
  const vatAccountSemantics = loadVatAccountSemantics(db);
  const vatAmountSideByAccountNo = new Map(
    vatAccountSemantics.amountSideByAccountNo,
  );
  const reverseChargeOutputAccountNos = new Set(
    vatAccountSemantics.reverseChargeOutputAccountNos,
  );
  const vatSettlementAccountNos = vatAccountSemantics.settlementAccountNos;

  // Account numbers are chart-local identifiers, not accounting semantics.
  // Current charts express VAT meaning through type=vat or confirmed roles.
  // Immutable pre-normalisation imports cannot be rewritten, so recover their
  // roles from exact, source-proven voucher evidence across the whole ledger.
  // Loading all trusted import rows makes later reporting periods independent
  // of whether the original role-establishing voucher falls inside the period.
  const historicalEvidenceRows = db.query(
    `SELECT je.id as entry_id, jl.id as line_id, je.status,
            a.account_no, a.type as account_type, a.default_vat_code,
            jl.debit_amount, jl.credit_amount, jl.vat_code
       FROM journal_entries je
       JOIN journal_lines jl ON jl.journal_entry_id = je.id
       JOIN accounts a ON a.id = jl.account_id
      WHERE je.created_by_program = ?
      ORDER BY je.id ASC, jl.id ASC`,
  ).all(HISTORICAL_IMPORT_PROGRAM) as LegacyVatEvidenceRow[];
  const legacyEvidence = inferLegacyVatEvidence(
    historicalEvidenceRows,
    vatAmountSideByAccountNo,
  );
  errors.push(...legacyEvidence.errors);
  for (const [accountNo, side] of legacyEvidence.amountSideByAccountNo) {
    vatAmountSideByAccountNo.set(accountNo, side);
  }
  for (const accountNo of legacyEvidence.reverseChargeOutputAccountNos) {
    reverseChargeOutputAccountNos.add(accountNo);
  }

  // Older Dinero ledgers can contain the source-native 64040/64060
  // reverse-charge control pair while Momstype was left blank on the expense
  // base. New imports persist the inferred code, but existing immutable rows
  // need the same conservative read-time interpretation. Infer only one exact
  // 25%-matching, otherwise unclassified expense line. Explicit/default codes
  // remain authoritative; ambiguous or inconsistent source patterns block the
  // report instead of becoming amount-only corrections with missing rubrik A.
  const inferredVatCodeByLineId = new Map(
    legacyEvidence.inferredVatCodeByLineId,
  );
  const trustedDineroInputLineIds = new Set<number>();
  const legacyRepresentationBaseByLineId = new Map<number, number>();
  const legacyReverseChargeToleranceByEntry = new Map(
    legacyEvidence.reverseChargeToleranceByEntry,
  );
  const historicalRowsByEntry = new Map<number, typeof rows>();
  for (const row of rows) {
    if (!isPersistedHistoricalImportProgram(row.created_by_program)) continue;
    const entryRows = historicalRowsByEntry.get(row.entry_id) ?? [];
    entryRows.push(row);
    historicalRowsByEntry.set(row.entry_id, entryRows);
  }
  for (const [entryId, entryRows] of historicalRowsByEntry) {
    const outputControls = entryRows.filter(
      (row) => row.account_no === "64040",
    );
    const inputControls = entryRows.filter(
      (row) => row.account_no === "64060",
    );
    if (outputControls.length === 0 || inputControls.length === 0) continue;
    const canonicalPair =
      outputControls.every(
        (row) => row.account_type === "vat" && row.normal_balance === "credit",
      ) &&
      inputControls.every(
        (row) => row.account_type === "vat" && row.normal_balance === "debit",
      );
    const legacyPair =
      outputControls.every(
        (row) => row.account_type === "liability" && row.normal_balance === "credit",
      ) &&
      inputControls.every(
        (row) =>
          row.account_type === "liability" &&
          (row.normal_balance === "debit" || row.normal_balance === "credit"),
      );
    if (!canonicalPair && !legacyPair) continue;

    const outputControl = roundDkk(
      outputControls.reduce(
        (sum, row) =>
          sum + Number(row.credit_amount ?? 0) - Number(row.debit_amount ?? 0),
        0,
      ),
    );
    const inputControl = roundDkk(
      inputControls.reduce(
        (sum, row) =>
          sum + Number(row.debit_amount ?? 0) - Number(row.credit_amount ?? 0),
        0,
      ),
    );
    if (
      outputControl === 0 ||
      inputControl === 0 ||
      toOre(outputControl) !== toOre(inputControl)
    ) {
      errors.push(
        `journal entry ${entryId} has an inconsistent Dinero reverse-charge control pattern on 64040/64060; human resolution is required`,
      );
      continue;
    }

    const expenseRows = entryRows.filter((row) => row.account_type === "expense");
    const explicitCode = (row: (typeof rows)[number]): string => row.vat_code?.trim() || "";
    const reverseChargeCodes = new Set([
      "EU_SERVICE_REVERSE_CHARGE",
      "NON_EU_SERVICE_REVERSE_CHARGE",
    ]);
    let baseRows = expenseRows.filter(
      (row) => reverseChargeCodes.has(explicitCode(row)),
    );
    const explicitReverseChargeCodes = new Set(
      baseRows.map((row) => explicitCode(row)),
    );
    if (explicitReverseChargeCodes.size > 1) {
      errors.push(
        `journal entry ${entryId} mixes EU and non-EU reverse-charge bases; human resolution is required`,
      );
      continue;
    }
    if (baseRows.length === 0) {
      // An explicit historical line code wins. Account defaults are not
      // source-line evidence and may be overridden only by this exact,
      // verified Dinero control pair.
      if (expenseRows.some((row) => explicitCode(row).length > 0)) {
        errors.push(
          `journal entry ${entryId} has Dinero reverse-charge controls but its expense base carries a conflicting VAT code; human resolution is required`,
        );
        continue;
      }
      baseRows = expenseRows.filter((row) => {
        const netDebit = roundDkk(
          Number(row.debit_amount ?? 0) - Number(row.credit_amount ?? 0),
        );
        return (
          netDebit !== 0 &&
          Math.sign(netDebit) === Math.sign(outputControl) &&
          oreDifference(percentOfDkk(netDebit, 25), outputControl) <= 1
        );
      });
      if (baseRows.length !== 1) {
        errors.push(
          `journal entry ${entryId} has Dinero reverse-charge controls but no single unclassified expense base matching 25%; human resolution is required`,
        );
        continue;
      }
      inferredVatCodeByLineId.set(
        baseRows[0]!.line_id,
        "EU_SERVICE_REVERSE_CHARGE",
      );
    }

    const classifiedBase = roundDkk(
      baseRows.reduce(
        (sum, row) =>
          sum + Number(row.debit_amount ?? 0) - Number(row.credit_amount ?? 0),
        0,
      ),
    );
    if (oreDifference(percentOfDkk(classifiedBase, 25), outputControl) > 1) {
      errors.push(
        `journal entry ${entryId} has Dinero reverse-charge controls that do not reconcile to its classified expense base; human resolution is required`,
      );
      continue;
    }

    // 64060 may occur as a liability/credit account in pre-normalisation
    // Dinero charts. Count it as input VAT only after the trusted provenance,
    // exact equal 64040/64060 controls and single base have all been proven.
    for (const row of inputControls) {
      trustedDineroInputLineIds.add(row.line_id);
      vatAmountSideByAccountNo.set(row.account_no, "input");
    }
    for (const row of outputControls) {
      vatAmountSideByAccountNo.set(row.account_no, "output");
      reverseChargeOutputAccountNos.add(row.account_no);
    }
    legacyReverseChargeToleranceByEntry.set(
      entryId,
      oreDifference(percentOfDkk(classifiedBase, 25), outputControl),
    );
  }

  // Dinero's historical representation vouchers can collapse the net expense
  // and the 75% non-deductible VAT into one REPRESENTATION_SPECIAL expense
  // line. Rentemester's native shape keeps those amounts on two lines. Recover
  // the net base only for the exact trusted import shape: one representation
  // expense, one input-VAT control, no other P/L line, and the statutory
  // 25%-of-VAT deduction reconciling within one øre. Anything else continues
  // through the ordinary mismatch gate instead of being guessed.
  for (const [entryId, entryRows] of historicalRowsByEntry) {
    const representationRows = entryRows.filter(
      (row) =>
        row.account_type === "expense" &&
        row.vat_code?.trim() === "REPRESENTATION_SPECIAL",
    );
    const hasSeparateNonDeductibleLine = entryRows.some(
      (row) => row.vat_code?.trim() === "REPRESENTATION_NON_DEDUCTIBLE_VAT",
    );
    if (representationRows.length === 0 || hasSeparateNonDeductibleLine) continue;
    const otherProfitLossRows = entryRows.filter(
      (row) =>
        (row.account_type === "expense" || row.account_type === "income") &&
        !representationRows.some((candidate) => candidate.line_id === row.line_id),
    );
    const inputRows = entryRows.filter(
      (row) => vatAmountSideByAccountNo.get(row.account_no) === "input",
    );
    if (
      representationRows.length !== 1 ||
      otherProfitLossRows.length > 0 ||
      inputRows.length !== 1
    ) continue;

    const expense = roundDkk(
      Number(representationRows[0]!.debit_amount ?? 0) -
        Number(representationRows[0]!.credit_amount ?? 0),
    );
    const bookedInput = roundDkk(
      Number(inputRows[0]!.debit_amount ?? 0) -
        Number(inputRows[0]!.credit_amount ?? 0),
    );
    if (expense <= 0 || bookedInput <= 0) continue;
    const recoveredNet = roundDkk(addDkk(expense, bookedInput) / 1.25);
    const fullVat = percentOfDkk(recoveredNet, 25);
    const expectedInput = percentOfDkk(fullVat, 25);
    const expectedExpense = addDkk(
      recoveredNet,
      subtractDkk(fullVat, expectedInput),
    );
    if (
      oreDifference(expectedInput, bookedInput) > 1 ||
      oreDifference(expectedExpense, expense) > 1
    ) {
      errors.push(
        `journal entry ${entryId} has a collapsed Dinero representation purchase that does not reconcile to the statutory partial VAT deduction; human resolution is required`,
      );
      continue;
    }
    legacyRepresentationBaseByLineId.set(
      representationRows[0]!.line_id,
      recoveredNet,
    );
  }

  // A pure transfer between VAT amount accounts and a confirmed settlement
  // account settles an earlier return; it is not fresh output/input VAT for
  // the transaction-date period. Identify the shape per journal before the
  // line scan so neither its amount nor its lack of a base code pollutes the
  // current report.
  const entryShapes = new Map<number, {
    touchesVatAmount: boolean;
    touchesVatSettlement: boolean;
    touchesOther: boolean;
  }>();
  for (const row of rows) {
    const shape = entryShapes.get(row.entry_id) ?? {
      touchesVatAmount: false,
      touchesVatSettlement: false,
      touchesOther: false,
    };
    if (vatAmountSideByAccountNo.has(row.account_no)) {
      shape.touchesVatAmount = true;
    } else if (vatSettlementAccountNos.has(row.account_no)) {
      shape.touchesVatSettlement = true;
    } else {
      shape.touchesOther = true;
    }
    entryShapes.set(row.entry_id, shape);
  }
  const settlementTransferEntryIds = new Set(
    [...entryShapes.entries()]
      .filter(([, shape]) =>
        shape.touchesVatAmount &&
        shape.touchesVatSettlement &&
        !shape.touchesOther)
      .map(([entryId]) => entryId),
  );

  let outputVat = 0;
  let inputVat = 0;
  let purchaseBase25 = 0;
  let salesBase25 = 0;
  let foreignReverseChargeSalesBase = 0;
  let domesticReverseChargeSalesBase = 0;
  let reverseChargePurchaseBase = 0;
  let euGoodsAcquisitionPurchaseBase = 0;
  let euGoodsAcquisitionOutputVat = 0;
  let nonEuServiceReverseChargePurchaseBase = 0;
  let representationPurchaseBase = 0;
  // Reverse-charge output VAT is booked per purchase on account 1200, øre-
  // rounded per transaction. To recover the *booked* total (which can differ
  // from 25% of the summed base by up to 1 øre per purchase), accumulate the
  // 1200 net (credit − debit) per journal entry and the set of entries that
  // carry an EU_SERVICE_REVERSE_CHARGE base line, then sum 1200 over exactly
  // those entries after the scan.
  const outputVatNetByEntry = new Map<number, number>();
  const dedicatedReverseChargeOutputNetByEntry = new Map<number, number>();
  const reverseChargeExpectedVatByEntry = new Map<number, number>();
  const inputVatNetByEntry = new Map<number, number>();
  const reverseChargeEntryIds = new Set<number>();
  let badDebtReliefBase25 = 0;
  let exemptSalesBase = 0;
  let ossConsumerSalesBase = 0;
  // OSS sales are counted per *entry*, not per line, so a multi-line OSS
  // invoice still counts as one entry.
  const ossConsumerSalesEntryIds = new Set<number>();
  // Count VAT-bearing base lines per category. 25% of a period-summed base is
  // not equal to the sum of per-line 25%-rounded VAT when amounts have odd
  // øre, so each base line can drift the aggregate by up to 1 øre. We allow a
  // (lineCount - 1)-øre tolerance on the reconciliation cross-check below.
  let outputVatBaseLines = 0;
  let inputVatBaseLines = 0;
  let foreignOutputVatBaseLines = 0;
  let foreignInputVatBaseLines = 0;
  let ordinaryOutputVatBaseLines = 0;
  let foreignOrdinaryOutputVatBaseLines = 0;
  let foreignReverseChargeOutputVatBaseLines = 0;
  const activeEntryIds = new Set<number>();
  const reversedEntryIds = new Set<number>();
  const reversalEntryIds = new Set<number>();
  const manualVatControlEntryIds = new Set<number>();
  const classifiedManualVatEntryIds = new Set<number>();
  const historicalVatControlEntryIds = new Set<number>();
  const classifiedHistoricalVatEntryIds = new Set<number>();
  const markClassified = (entryId: number, trustedHistoricalImport: boolean) => {
    (trustedHistoricalImport
      ? classifiedHistoricalVatEntryIds
      : classifiedManualVatEntryIds
    ).add(entryId);
  };
  let activeLinesConsidered = 0;
  let reversedLinesConsidered = 0;
  let reversalLinesConsidered = 0;
  const reversedByInPeriodReversal = new Set(rows.filter((row) => row.reversal_of_entry_id != null).map((row) => row.reversal_of_entry_id as number));

  for (const row of rows) {
    const isReversalEntry = row.reversal_of_entry_id != null;
    const isReversedEntry = !isReversalEntry && reversedByInPeriodReversal.has(row.entry_id);

    if (isReversalEntry) {
      reversalEntryIds.add(row.entry_id);
      reversalLinesConsidered += 1;
    } else if (isReversedEntry) {
      reversedEntryIds.add(row.entry_id);
      reversedLinesConsidered += 1;
    } else {
      activeEntryIds.add(row.entry_id);
      activeLinesConsidered += 1;
    }

    const debit = roundDkk(Number(row.debit_amount ?? 0));
    const credit = roundDkk(Number(row.credit_amount ?? 0));
    const amountSide =
      vatAmountSideByAccountNo.get(row.account_no) ??
      (trustedDineroInputLineIds.has(row.line_id) ? "input" : undefined);
    const trustedHistoricalImport = isPersistedHistoricalImportProgram(
      row.created_by_program,
    );
    // Explicit persisted line classification is authoritative. Only an exact
    // verified historical-import marker may fall back to the reviewed account
    // default; ordinary/manual entries never inherit one at report time.
    const effectiveVatCode =
      row.vat_code ??
      inferredVatCodeByLineId.get(row.line_id) ??
      (trustedHistoricalImport &&
      (row.account_type === "income" || row.account_type === "expense")
        ? row.default_vat_code
        : null);
    const isVatBaseLine =
      row.account_type === "income" || row.account_type === "expense";
    const isSettlementTransfer = settlementTransferEntryIds.has(row.entry_id);

    if (
      effectiveVatCode !== null &&
      !VAT_LINE_CODES.has(effectiveVatCode)
    ) {
      errors.push(
        `journal entry ${row.entry_id} line on account ${row.account_no} has unsupported vat_code '${effectiveVatCode}'`,
      );
    }

    if (!isSettlementTransfer && amountSide === "output") {
      outputVat += credit - debit;
      outputVatNetByEntry.set(
        row.entry_id,
        (outputVatNetByEntry.get(row.entry_id) ?? 0) + (credit - debit),
      );
      if (reverseChargeOutputAccountNos.has(row.account_no)) {
        dedicatedReverseChargeOutputNetByEntry.set(
          row.entry_id,
          (dedicatedReverseChargeOutputNetByEntry.get(row.entry_id) ?? 0) +
            (credit - debit),
        );
      }
    }
    if (!isSettlementTransfer && amountSide === "input") {
      inputVat += debit - credit;
      inputVatNetByEntry.set(
        row.entry_id,
        (inputVatNetByEntry.get(row.entry_id) ?? 0) + (debit - credit),
      );
    }
    if (!isSettlementTransfer && amountSide !== undefined && !trustedHistoricalImport) {
      manualVatControlEntryIds.add(row.entry_id);
    } else if (!isSettlementTransfer && amountSide !== undefined) {
      historicalVatControlEntryIds.add(row.entry_id);
    }

    const isForeignCurrencyEntry = row.entry_currency !== "DKK";
    if (isVatBaseLine && effectiveVatCode === "DK_PURCHASE_25") {
      markClassified(row.entry_id, trustedHistoricalImport);
      purchaseBase25 += debit - credit;
      inputVatBaseLines += 1;
      if (isForeignCurrencyEntry) foreignInputVatBaseLines += 1;
    }
    if (isVatBaseLine && effectiveVatCode === "DK_SALE_25") {
      markClassified(row.entry_id, trustedHistoricalImport);
      salesBase25 += credit - debit;
      outputVatBaseLines += 1;
      ordinaryOutputVatBaseLines += 1;
      if (isForeignCurrencyEntry) {
        foreignOutputVatBaseLines += 1;
        foreignOrdinaryOutputVatBaseLines += 1;
      }
    }
    // JUR-2/KODE-2: keep the two reverse-charge sales bases apart so the
    // momsangivelse can route foreign → rubrik B (VIES) and domestic → rubrik C.
    if (isVatBaseLine && effectiveVatCode === "REVERSE_CHARGE_EXEMPT") {
      markClassified(row.entry_id, trustedHistoricalImport);
      foreignReverseChargeSalesBase += credit - debit;
    }
    if (isVatBaseLine && effectiveVatCode === "DOMESTIC_REVERSE_CHARGE_EXEMPT") {
      markClassified(row.entry_id, trustedHistoricalImport);
      domesticReverseChargeSalesBase += credit - debit;
    }
    if (isVatBaseLine && effectiveVatCode === "EU_SERVICE_REVERSE_CHARGE") {
      markClassified(row.entry_id, trustedHistoricalImport);
      reverseChargePurchaseBase += debit - credit;
      reverseChargeEntryIds.add(row.entry_id);
      reverseChargeExpectedVatByEntry.set(
        row.entry_id,
        addDkk(
          reverseChargeExpectedVatByEntry.get(row.entry_id) ?? 0,
          percentOfDkk(debit - credit, 25),
        ),
      );
      // Reverse charge contributes to both output and input VAT.
      inputVatBaseLines += 1;
      outputVatBaseLines += 1;
      if (isForeignCurrencyEntry) {
        foreignInputVatBaseLines += 1;
        foreignOutputVatBaseLines += 1;
        foreignReverseChargeOutputVatBaseLines += 1;
      }
    }
    if (isVatBaseLine && effectiveVatCode === "EU_GOODS_ACQUISITION") {
      markClassified(row.entry_id, trustedHistoricalImport);
      euGoodsAcquisitionPurchaseBase += debit - credit;
      euGoodsAcquisitionOutputVat += percentOfDkk(debit - credit, 25);
      reverseChargeEntryIds.add(row.entry_id);
      reverseChargeExpectedVatByEntry.set(row.entry_id, addDkk(reverseChargeExpectedVatByEntry.get(row.entry_id) ?? 0, percentOfDkk(debit - credit, 25)));
      inputVatBaseLines += 1; outputVatBaseLines += 1;
      if (isForeignCurrencyEntry) { foreignInputVatBaseLines += 1; foreignOutputVatBaseLines += 1; foreignReverseChargeOutputVatBaseLines += 1; }
    }
    if (isVatBaseLine && effectiveVatCode === "NON_EU_SERVICE_REVERSE_CHARGE") {
      markClassified(row.entry_id, trustedHistoricalImport);
      nonEuServiceReverseChargePurchaseBase += debit - credit;
      reverseChargeEntryIds.add(row.entry_id);
      reverseChargeExpectedVatByEntry.set(
        row.entry_id,
        addDkk(
          reverseChargeExpectedVatByEntry.get(row.entry_id) ?? 0,
          percentOfDkk(debit - credit, 25),
        ),
      );
      inputVatBaseLines += 1;
      outputVatBaseLines += 1;
      if (isForeignCurrencyEntry) {
        foreignInputVatBaseLines += 1;
        foreignOutputVatBaseLines += 1;
        foreignReverseChargeOutputVatBaseLines += 1;
      }
    }
    if (isVatBaseLine && effectiveVatCode === "REPRESENTATION_SPECIAL") {
      markClassified(row.entry_id, trustedHistoricalImport);
      representationPurchaseBase +=
        legacyRepresentationBaseByLineId.get(row.line_id) ?? debit - credit;
      inputVatBaseLines += 1;
      if (isForeignCurrencyEntry) foreignInputVatBaseLines += 1;
    }
    if (isVatBaseLine && effectiveVatCode === "DK_BAD_DEBT_25") {
      markClassified(row.entry_id, trustedHistoricalImport);
      badDebtReliefBase25 += debit - credit;
      outputVatBaseLines += 1;
      ordinaryOutputVatBaseLines += 1;
      if (isForeignCurrencyEntry) {
        foreignOutputVatBaseLines += 1;
        foreignOrdinaryOutputVatBaseLines += 1;
      }
    }
    // VAT-exempt domestic sales (momsloven §13) and OSS consumer sales carry
    // NO Danish output VAT, so they are tracked in their own bases and are
    // deliberately NOT added to outputVatBaseLines (the output-VAT
    // reconciliation must not expect 25% of them).
    if (isVatBaseLine && effectiveVatCode === "DK_SALE_EXEMPT") {
      markClassified(row.entry_id, trustedHistoricalImport);
      exemptSalesBase += credit - debit;
    }
    if (isVatBaseLine && effectiveVatCode === "OSS_EU_CONSUMER") {
      markClassified(row.entry_id, trustedHistoricalImport);
      ossConsumerSalesBase += credit - debit;
      ossConsumerSalesEntryIds.add(row.entry_id);
    }
  }

  // #533 legacy guard: the write boundary now rejects this shape, but an old
  // ledger may already contain a manual amount-only VAT journal. Never present
  // its payable as filing-ready while the SKAT bases are empty.
  for (const entryId of manualVatControlEntryIds) {
    if (!classifiedManualVatEntryIds.has(entryId)) {
      errors.push(
        `journal entry ${entryId} changes a VAT amount account but has no explicit vat_code on a VAT base line; the VAT bases cannot be filed until the classification is corrected`,
      );
    }
  }

  outputVat = roundDkk(outputVat);
  inputVat = roundDkk(inputVat);
  purchaseBase25 = roundDkk(purchaseBase25);
  salesBase25 = roundDkk(salesBase25);
  foreignReverseChargeSalesBase = roundDkk(foreignReverseChargeSalesBase);
  domesticReverseChargeSalesBase = roundDkk(domesticReverseChargeSalesBase);
  const reverseChargeSalesBase = addDkk(foreignReverseChargeSalesBase, domesticReverseChargeSalesBase);
  reverseChargePurchaseBase = roundDkk(reverseChargePurchaseBase);
  euGoodsAcquisitionPurchaseBase = roundDkk(euGoodsAcquisitionPurchaseBase);
  euGoodsAcquisitionOutputVat = roundDkk(euGoodsAcquisitionOutputVat);
  nonEuServiceReverseChargePurchaseBase = roundDkk(nonEuServiceReverseChargePurchaseBase);
  const historicalAmountOnlyEntryIds = [...historicalVatControlEntryIds].filter(
    (entryId) => !classifiedHistoricalVatEntryIds.has(entryId),
  );
  const historicalOutputCorrection = roundDkk(
    historicalAmountOnlyEntryIds.reduce(
      (sum, entryId) => sum + (outputVatNetByEntry.get(entryId) ?? 0),
      0,
    ),
  );
  const historicalDedicatedReverseChargeCorrection = roundDkk(
    historicalAmountOnlyEntryIds.reduce(
      (sum, entryId) =>
        sum + (dedicatedReverseChargeOutputNetByEntry.get(entryId) ?? 0),
      0,
    ),
  );
  const historicalOrdinaryOutputCorrection = subtractDkk(
    historicalOutputCorrection,
    historicalDedicatedReverseChargeCorrection,
  );
  const historicalInputCorrection = roundDkk(
    historicalAmountOnlyEntryIds.reduce(
      (sum, entryId) => sum + (inputVatNetByEntry.get(entryId) ?? 0),
      0,
    ),
  );

  // A dedicated source-/role-proven control account (Dinero 64040) always
  // belongs to the foreign-service VAT category. For shared accounts (native
  // 1200), only the per-line expected reverse-charge VAT can be allocated; the
  // remaining booked output VAT stays in the ordinary sales category.
  let reverseChargePurchaseOutputVat = roundDkk(
    [...dedicatedReverseChargeOutputNetByEntry.values()].reduce(
      (sum, amount) => sum + amount,
      0,
    ),
  );
  for (const entryId of reverseChargeEntryIds) {
    if (!dedicatedReverseChargeOutputNetByEntry.has(entryId)) {
      reverseChargePurchaseOutputVat = addDkk(
        reverseChargePurchaseOutputVat,
        reverseChargeExpectedVatByEntry.get(entryId) ?? 0,
      );
    }
  }
  representationPurchaseBase = roundDkk(representationPurchaseBase);
  badDebtReliefBase25 = roundDkk(badDebtReliefBase25);
  exemptSalesBase = roundDkk(exemptSalesBase);
  ossConsumerSalesBase = roundDkk(ossConsumerSalesBase);

  const foreignServiceReverseChargeBase = addDkk(reverseChargePurchaseBase, nonEuServiceReverseChargePurchaseBase);
  const foreignPurchaseReverseChargeBase = addDkk(foreignServiceReverseChargeBase, euGoodsAcquisitionPurchaseBase);
  const expectedOutputVat = subtractDkk(addDkk(percentOfDkk(salesBase25, 25), percentOfDkk(foreignPurchaseReverseChargeBase, 25)), percentOfDkk(badDebtReliefBase25, 25));
  const expectedInputVat = addDkk(addDkk(percentOfDkk(purchaseBase25, 25), percentOfDkk(foreignPurchaseReverseChargeBase, 25)), percentOfDkk(percentOfDkk(representationPurchaseBase, 25), 25));
  const warnings: string[] = [];
  // Each VAT-bearing base line is rounded to øre independently when booked,
  // so the booked aggregate can differ from "25% of the summed base" by up to
  // 1 øre per line. Only the *first* line establishes the aggregate; the
  // remaining (n-1) lines can each drift it, so the tolerance is (n-1) øre.
  // A genuine mis-booking exceeds this small bound and blocks filing.
  // Foreign-currency entries round the stated VAT and its net base into DKK
  // independently before balancing. That conversion can add one further øre
  // of legitimate drift per foreign base line.
  const periodEntryIds = new Set(rows.map((row) => row.entry_id));
  const legacyReverseChargeTolerance = [...legacyReverseChargeToleranceByEntry]
    .filter(([entryId]) => periodEntryIds.has(entryId))
    .reduce((sum, [, tolerance]) => sum + tolerance, 0);
  const legacyOrdinaryInputTolerance = [...legacyEvidence.ordinaryInputToleranceByEntry]
    .filter(([entryId]) => periodEntryIds.has(entryId))
    .reduce((sum, [, tolerance]) => sum + tolerance, 0);
  const legacyOrdinaryOutputTolerance = [...legacyEvidence.ordinaryOutputToleranceByEntry]
    .filter(([entryId]) => periodEntryIds.has(entryId))
    .reduce((sum, [, tolerance]) => sum + tolerance, 0);
  const outputVatTolerance = Math.max(0, outputVatBaseLines - 1) + foreignOutputVatBaseLines + legacyReverseChargeTolerance + legacyOrdinaryOutputTolerance;
  const inputVatTolerance = Math.max(0, inputVatBaseLines - 1) + foreignInputVatBaseLines + legacyReverseChargeTolerance + legacyOrdinaryInputTolerance;
  const explainedOutputVat = addDkk(expectedOutputVat, historicalOutputCorrection);
  const explainedInputVat = addDkk(expectedInputVat, historicalInputCorrection);
  if (historicalOutputCorrection !== 0 || historicalInputCorrection !== 0) {
    warnings.push(
      `verified historical amount-only VAT corrections included: output ${historicalOutputCorrection}, input ${historicalInputCorrection}`,
    );
  }
  if (oreDifference(outputVat, explainedOutputVat) > outputVatTolerance) {
    errors.push(
      `output VAT mismatch: booked ${outputVat}, expected from base × rate plus verified historical corrections ${explainedOutputVat}`,
    );
  }
  if (oreDifference(inputVat, explainedInputVat) > inputVatTolerance) {
    errors.push(
      `input VAT mismatch: booked ${inputVat}, expected from base × rate plus verified historical corrections ${explainedInputVat}`,
    );
  }

  // Aggregate reconciliation is not sufficient: an overstated ordinary
  // output amount and an understated dedicated reverse-charge amount can
  // cancel each other while producing wrong SKAT rubrics. Reconcile both
  // categories independently. Shared-account reverse charge is allocated from
  // its base above, so any unexplained remainder lands in (and is checked
  // against) ordinary sales VAT.
  const expectedReverseChargeOutputVat = addDkk(
    [...reverseChargeExpectedVatByEntry.values()].reduce(
      (sum, amount) => sum + amount,
      0,
    ),
    historicalDedicatedReverseChargeCorrection,
  );
  const expectedOrdinaryOutputVat = addDkk(
    subtractDkk(
      percentOfDkk(salesBase25, 25),
      percentOfDkk(badDebtReliefBase25, 25),
    ),
    historicalOrdinaryOutputCorrection,
  );
  const bookedOrdinaryOutputVat = subtractDkk(
    outputVat,
    reverseChargePurchaseOutputVat,
  );
  const reverseChargeOutputVatTolerance =
    foreignReverseChargeOutputVatBaseLines + legacyReverseChargeTolerance;
  const ordinaryOutputVatTolerance =
    Math.max(0, ordinaryOutputVatBaseLines - 1) +
    foreignOrdinaryOutputVatBaseLines +
    legacyOrdinaryOutputTolerance;
  if (
    oreDifference(
      reverseChargePurchaseOutputVat,
      expectedReverseChargeOutputVat,
    ) > reverseChargeOutputVatTolerance
  ) {
    errors.push(
      `reverse-charge output VAT mismatch: booked ${reverseChargePurchaseOutputVat}, expected from foreign-service bases plus verified historical corrections ${expectedReverseChargeOutputVat}`,
    );
  }
  if (
    oreDifference(bookedOrdinaryOutputVat, expectedOrdinaryOutputVat) >
    ordinaryOutputVatTolerance
  ) {
    errors.push(
      `ordinary output VAT mismatch: booked ${bookedOrdinaryOutputVat}, expected from sales and bad-debt bases plus verified historical corrections ${expectedOrdinaryOutputVat}`,
    );
  }

  // Partial deduction (delvis fradragsret, momsloven §§37-38) is NOT modelled:
  // every purchase code assumes 100% deductible input VAT. When a period has
  // BOTH VAT-exempt turnover (DK_SALE_EXEMPT, §13) AND deducted input VAT, some
  // of that input VAT may be only partly deductible (a pro-rata split tied to
  // the exempt vs. taxable revenue mix). Rentemester does not compute that
  // split — warn so the user/advisor checks it. Warning only: no amount changes
  // and the netVatPayable invariant is untouched.
  if (exemptSalesBase > 0 && inputVat > 0) {
    warnings.push(
      "Delvis fradragsret (momsloven §§37-38) håndteres ikke: perioden har både " +
        "momsfri omsætning (DK_SALE_EXEMPT) og fuldt fradraget købsmoms. Noget af " +
        "købsmomsen kan være delvis fradragsberettiget (pro rata efter momspligtig " +
        "vs. momsfri omsætning). Få revisor til at vurdere fradragsprocenten — " +
        "Rentemester beregner ikke fordelingen.",
    );
  }

  const report: Omit<VatPeriodReport, "rubrikker"> = {
    ok: errors.length === 0,
    appliedRules: [RULE_ID],
    periodStart,
    periodEnd,
    vatPeriodType,
    filingDeadline,
    outputVat,
    inputVat,
    netVatPayable: subtractDkk(outputVat, inputVat),
    purchaseBase25,
    salesBase25,
    reverseChargeSalesBase,
    foreignReverseChargeSalesBase,
    domesticReverseChargeSalesBase,
    reverseChargePurchaseBase,
    euGoodsAcquisitionPurchaseBase,
    euGoodsAcquisitionOutputVat,
    nonEuServiceReverseChargePurchaseBase,
    reverseChargePurchaseOutputVat,
    representationPurchaseBase,
    badDebtReliefBase25,
    exemptSalesBase,
    ossConsumerSalesBase,
    ossConsumerSalesEntryCount: ossConsumerSalesEntryIds.size,
    journalEntryCount: activeEntryIds.size,
    reversedJournalEntryCount: reversedEntryIds.size,
    reversalJournalEntryCount: reversalEntryIds.size,
    totalJournalEntryCount: activeEntryIds.size + reversedEntryIds.size + reversalEntryIds.size,
    linesConsidered: activeLinesConsidered,
    reversedLinesConsidered,
    reversalLinesConsidered,
    totalLinesConsidered: rows.length,
    warnings,
    errors,
  };
  return { ...report, rubrikker: projectVatRubric(report as VatPeriodReport) };
}

export function vatPeriodWindowFor(isoDate: string, type: VatPeriodType): VatPeriodWindow {
  const year = Number(isoDate.slice(0, 4));
  const month = Number(isoDate.slice(5, 7)); // 1-based
  const span = vatPeriodMonthSpan(type);
  // The 1-based index of the period within the year, then its first month.
  const periodIndex = Math.floor((month - 1) / span);
  const startMonth = periodIndex * span + 1;
  const endMonth = startMonth + span - 1;
  // Day 0 of the next month is the last day of `endMonth`.
  const lastDay = new Date(Date.UTC(year, endMonth, 0)).getUTCDate();
  const end = `${year}-${pad2(endMonth)}-${pad2(lastDay)}`;
  return {
    start: `${year}-${pad2(startMonth)}-01`,
    end,
    filingDeadline: vatFilingDeadline(end, type)!,
    vatPeriodType: type,
  };
}

function vatPeriodMonthSpan(type: VatPeriodType): number {
  switch (type) {
    case "month":
      return 1;
    case "half-year":
      return 6;
    case "quarter":
    default:
      return 3;
  }
}

function pad2(n: number): string {
  return String(n).padStart(2, "0");
}

export function vatFilingDeadline(
  periodEnd: string,
  type: VatPeriodType = DEFAULT_VAT_PERIOD_TYPE,
): string | null {
  if (!looksLikeIsoDate(periodEnd)) return null;
  const year = Number(periodEnd.slice(0, 4));
  const month = Number(periodEnd.slice(5, 7));

  let unshifted: string;
  if (type === "month") {
    if (month === 6) {
      unshifted = `${year}-08-17`;
    } else {
      const next = new Date(Date.UTC(year, month, 25));
      unshifted = isoUtc(
        next.getUTCFullYear(),
        next.getUTCMonth() + 1,
        next.getUTCDate(),
      );
    }
  } else {
    const thirdMonth = new Date(Date.UTC(year, month + 2, 1));
    unshifted = isoUtc(
      thirdMonth.getUTCFullYear(),
      thirdMonth.getUTCMonth() + 1,
      1,
    );
  }
  return nextDanishBankingDay(unshifted);
}

export function effectivePeriodState(
  db: Database,
  periodId: number,
  rowStatus: AccountingPeriodStatus,
): EffectivePeriodState {
  const events = db
    .query(
      `SELECT event_type
         FROM audit_log
        WHERE entity_type = 'accounting_period'
          AND entity_id = ?
        ORDER BY id ASC`,
    )
    .all(String(periodId)) as Array<{ event_type: string }>;

  let state: EffectivePeriodState = rowStatus;
  for (const ev of events) {
    // `reported` is TERMINAL (KODE-9): once a period has been submitted to the
    // authority (SKAT / Erhvervsstyrelsen) it can never be reopened — undoing
    // an authority filing is not a bookkeeping operation, and reopenAccounting-
    // Period already refuses it. A `period_reopen` event appended AFTER a
    // `period_report` (e.g. a raw audit_log INSERT bypassing that guard) must
    // therefore be ignored, so a reported period cannot be effectively reopened
    // and have new postings land in it.
    if (state === "reported") continue;
    if (ev.event_type === "period_report") state = "reported";
    else if (ev.event_type === "period_close") state = "closed";
    else if (ev.event_type === PERIOD_REOPEN_EVENT) state = "open";
  }
  return state;
}

export function diffDaysSafe(from: string, to: string): number {
  const pf = /^(\d{4})-(\d{2})-(\d{2})/.exec(from);
  const pt = /^(\d{4})-(\d{2})-(\d{2})/.exec(to);
  if (!pf || !pt) return 0;
  const f = Date.UTC(parseInt(pf[1]!, 10), parseInt(pf[2]!, 10) - 1, parseInt(pf[3]!, 10));
  const t = Date.UTC(parseInt(pt[1]!, 10), parseInt(pt[2]!, 10) - 1, parseInt(pt[3]!, 10));
  return Math.round((t - f) / 86400000);
}

export function listRecentAuditLog(db: Database, limit = 10): AuditLogRow[] {
  if (!Number.isInteger(limit) || limit <= 0) return [];
  const rows = db.query(
    `SELECT id, event_type, entity_type, entity_id, message, actor, created_at
       FROM audit_log
      ORDER BY created_at DESC, id DESC
      LIMIT ?`,
  ).all(limit) as Array<{
    id: number;
    event_type: string;
    entity_type: string;
    entity_id: string | null;
    message: string;
    actor: string;
    created_at: string;
  }>;
  return rows.map(mapAuditRow);
}

export function getBackupComplianceStatus(db: Database, companyRoot: string, asOf?: string): BackupComplianceStatus {
  const checkedAt = resolveCreatedAt(asOf);
  if (!checkedAt) {
    return {
      ok: false,
      appliedRules: [BACKUP_RULE_ID],
      latestBackupAt: null,
      latestBackupId: null,
      backupDue: false,
      hasActivitySinceBackup: false,
      daysSinceLatestBackup: null,
      requiredBy: null,
      checkedAt: asOf ?? "",
      backupsFound: 0,
      evidence: { latestJournalEntryAt: null, latestDocumentAt: null, latestBankImportAt: null },
      errors: ["asOf must be a valid ISO-8601 datetime when provided"],
    };
  }

  const manifests = listBackupManifests(companyRoot);
  const latest = manifests.at(-1) ?? null;
  const evidence = latestActivityTimestamps(db);
  const latestBackupAt = latest?.createdAt ?? null;
  const latestBackupId = latest?.backupId ?? null;

  const activityMoments = [evidence.latestJournalEntryAt, evidence.latestDocumentAt, evidence.latestBankImportAt]
    .filter((value): value is string => Boolean(value))
    .map((value) => parseActivityMoment(value))
    .filter((value) => Number.isFinite(value));

  const latestBackupMs = latestBackupAt ? new Date(latestBackupAt).getTime() : null;
  const checkedAtMs = new Date(checkedAt).getTime();
  const latestActivityMs = activityMoments.length > 0 ? Math.max(...activityMoments) : null;
  const hasActivitySinceBackup = latestBackupMs === null ? activityMoments.length > 0 : latestActivityMs !== null && latestActivityMs > latestBackupMs;
  // money-allowed: days-since-backup math, not currency
  const daysSinceLatestBackup = latestBackupMs === null ? null : Number(((checkedAtMs - latestBackupMs) / (24 * 60 * 60 * 1000)).toFixed(2));
  const backupDue = latestBackupMs === null ? hasActivitySinceBackup : hasActivitySinceBackup && (checkedAtMs - latestBackupMs > BACKUP_INTERVAL_MS);
  const requiredBy = latestBackupMs === null ? (hasActivitySinceBackup ? checkedAt : null) : hasActivitySinceBackup ? new Date(latestBackupMs + BACKUP_INTERVAL_MS).toISOString() : null;

  return {
    ok: !backupDue,
    appliedRules: [BACKUP_RULE_ID],
    latestBackupAt,
    latestBackupId,
    backupDue,
    hasActivitySinceBackup,
    daysSinceLatestBackup,
    requiredBy,
    checkedAt,
    backupsFound: manifests.length,
    evidence,
    errors: [],
  };
}

function resolveCreatedAt(value?: string) {
  const createdAt = value ?? new Date().toISOString();
  if (Number.isNaN(Date.parse(createdAt))) return null;
  return new Date(createdAt).toISOString();
}

function listBackupManifests(companyRoot: string) {
  const p = companyPaths(companyRoot);
  if (!existsSync(p.backups)) return [] as BackupManifest[];
  return readdirSync(p.backups, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => readBackupManifest(join(p.backups, entry.name, "manifest.json")))
    .filter((manifest): manifest is BackupManifest => Boolean(manifest))
    .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
}

function latestActivityTimestamps(db: Database) {
  const latestJournalEntryAt = (db.query("SELECT MAX(registration_datetime) AS value FROM journal_entries").get() as { value: string | null }).value;
  const latestDocumentAt = (db.query("SELECT MAX(upload_datetime) AS value FROM documents").get() as { value: string | null }).value;
  const latestBankImportAt = (db.query("SELECT MAX(COALESCE(booking_date, transaction_date)) AS value FROM bank_transactions").get() as { value: string | null }).value;
  return { latestJournalEntryAt, latestDocumentAt, latestBankImportAt };
}

function parseActivityMoment(value: string) {
  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) return new Date(`${value}T23:59:59.999Z`).getTime();
  return new Date(value).getTime();
}

export function verifyAuditChain(db: Database, options: VerifyAuditChainOptions = {}) {
  const entries = db.query("SELECT id, entry_no, transaction_date, text, source_bank_transaction_id, document_id, currency, amount_foreign, amount_dkk, fx_rate_to_dkk, rule_version, created_by, created_by_program, status, reversal_of_entry_id, previous_hash, entry_hash FROM journal_entries ORDER BY id ASC").all() as any[];
  let prev = "GENESIS";
  const errors: string[] = [];
  const entriesById = new Map<number, any>(entries.map((entry) => [Number(entry.id), entry]));
  const linesByEntryId = new Map<number, any[]>();
  const reversalCounts = new Map<number, number>();
  for (const entry of entries) {
    if (entry.reversal_of_entry_id == null) continue;
    const originalId = Number(entry.reversal_of_entry_id);
    reversalCounts.set(originalId, (reversalCounts.get(originalId) ?? 0) + 1);
  }
  for (const [originalId, count] of reversalCounts) {
    if (count <= 1) continue;
    const original = entriesById.get(originalId);
    errors.push(`${original?.entry_no ?? `journal entry id ${originalId}`}: has ${count} reversal rows; exactly one is allowed`);
  }
  const companyRoot = inferredAuditCompanyRoot(db, options.companyRoot);
  const documentEvidenceCache = new Map<number, string | null>();
  const journalReferencedDocumentIds = new Set<number>();

  const foreignKeyErrors = db.query("PRAGMA foreign_key_check").all() as Array<{ table: string; rowid: number; parent: string; fkid: number }>;
  for (const fk of foreignKeyErrors) {
    errors.push(`foreign key violation: ${fk.table} row ${fk.rowid} references missing ${fk.parent}`);
  }

  const bankJournalLinks = db.query(
    `SELECT link.id, link.bank_transaction_id, link.journal_entry_id,
            bt.amount, bt.amount_dkk, bt.currency,
            ba.ledger_account_no,
            je.status, je.reversal_of_entry_id, je.source_bank_transaction_id,
            EXISTS(SELECT 1 FROM journal_entries reversal WHERE reversal.reversal_of_entry_id = je.id) AS has_reversal,
            EXISTS(SELECT 1 FROM bank_reconciliation_correction_events correction
                    WHERE correction.supersedes_kind = 'append-only'
                      AND correction.supersedes_id = link.id
                      AND correction.bank_transaction_id = link.bank_transaction_id) AS is_superseded,
            COALESCE(SUM(CASE WHEN a.account_no = ba.ledger_account_no THEN jl.debit_amount - jl.credit_amount ELSE 0 END), 0) AS journal_bank_movement,
            EXISTS(SELECT 1 FROM journal_entries direct WHERE direct.source_bank_transaction_id = bt.id) AS has_direct_link
       FROM bank_journal_reconciliation_links link
       JOIN bank_transactions bt ON bt.id = link.bank_transaction_id
       LEFT JOIN bank_accounts ba ON ba.id = bt.bank_account_id
       JOIN journal_entries je ON je.id = link.journal_entry_id
       LEFT JOIN journal_lines jl ON jl.journal_entry_id = je.id
       LEFT JOIN accounts a ON a.id = jl.account_id
      GROUP BY link.id
      ORDER BY link.id`,
  ).all() as Array<{
    id: number; bank_transaction_id: number; journal_entry_id: number;
    amount: number; amount_dkk: number | null; currency: string;
    ledger_account_no: string | null; status: string; reversal_of_entry_id: number | null;
    source_bank_transaction_id: number | null; has_reversal: number;
    journal_bank_movement: number; has_direct_link: number; is_superseded: number;
  }>;
  for (const link of bankJournalLinks) {
    const label = `bank-journal reconciliation link ${link.id}`;
    if (!link.ledger_account_no) errors.push(`${label}: bank transaction has no mapped ledger account`);
    if (!Number(link.is_superseded) && (link.status !== "posted" || link.reversal_of_entry_id != null || Number(link.has_reversal) !== 0)) {
      errors.push(`${label}: journal entry ${link.journal_entry_id} is not an active original posted entry`);
    }
    if (link.source_bank_transaction_id != null || Number(link.has_direct_link) !== 0) {
      errors.push(`${label}: conflicts with a direct bank link`);
    }
    const bankDkk = String(link.currency).trim().toUpperCase() === "DKK" ? Number(link.amount) : Number(link.amount_dkk);
    if (!Number.isFinite(bankDkk) || compareDkk(Number(link.journal_bank_movement), bankDkk) !== 0) {
      errors.push(`${label}: journal bank movement does not reconcile exactly to the bank amount in DKK`);
    }
  }

  // v33 correction evidence is append-only but deliberately richer than an
  // audit-log message: verify the complete same-bank chain and the exact
  // replacement bytes so every consumer sees one deterministic current row.
  const correctionEvents = db.query(`SELECT event.*, bt.amount,bt.amount_dkk,bt.currency,COALESCE(ba.ledger_account_no,(SELECT m.account_no FROM account_role_mappings m WHERE m.role='bank' AND m.status='confirmed' ORDER BY m.version DESC LIMIT 1)) AS ledger_account_no,je.entry_hash,je.status,je.reversal_of_entry_id,je.source_bank_transaction_id,EXISTS(SELECT 1 FROM journal_entries reversal WHERE reversal.reversal_of_entry_id=je.id) AS has_reversal,EXISTS(SELECT 1 FROM bank_reconciliation_correction_events child WHERE child.supersedes_kind='correction' AND child.supersedes_id=event.id AND child.bank_transaction_id=event.bank_transaction_id) AS is_superseded,COALESCE(SUM(CASE WHEN a.account_no=event.bank_account_no THEN jl.debit_amount-jl.credit_amount ELSE 0 END),0) AS bank_movement,EXISTS(SELECT 1 FROM audit_log audit WHERE audit.event_type='bank_reconciliation_corrected' AND audit.entity_type='bank_transaction' AND audit.entity_id=CAST(event.bank_transaction_id AS TEXT) AND (audit.actor=event.actor OR audit.actor LIKE event.actor || ' via %')) AS has_audit FROM bank_reconciliation_correction_events event JOIN bank_transactions bt ON bt.id=event.bank_transaction_id LEFT JOIN bank_accounts ba ON ba.id=bt.bank_account_id JOIN journal_entries je ON je.id=event.replacement_journal_entry_id LEFT JOIN journal_lines jl ON jl.journal_entry_id=je.id LEFT JOIN accounts a ON a.id=jl.account_id GROUP BY event.id ORDER BY event.id`).all() as any[];
  for (const event of correctionEvents) {
    const label = `bank reconciliation correction ${event.id}`;
    const amount = String(event.currency).trim().toUpperCase() === "DKK" ? Number(event.amount) : Number(event.amount_dkk);
    if (event.ledger_account_no !== event.bank_account_no || compareDkk(amount, Number(event.bank_amount_dkk)) !== 0 || compareDkk(amount, Number(event.bank_movement)) !== 0) errors.push(`${label}: bank account or amount evidence is inconsistent`);
    if (event.entry_hash !== event.replacement_journal_hash || event.status !== "posted" || event.reversal_of_entry_id != null || event.source_bank_transaction_id != null || (!Number(event.is_superseded) && Number(event.has_reversal) !== 0)) errors.push(`${label}: replacement journal hash or lifecycle is invalid`);
    if (!event.has_audit) errors.push(`${label}: missing bank_reconciliation_corrected audit event`);
    const target = `${event.supersedes_kind}:${event.supersedes_id}`;
    if (event.supersedes_reconciliation_id !== target) errors.push(`${label}: typed supersession target is inconsistent`);
  }
  const hasPurchaseCorrections = db.query("SELECT 1 FROM sqlite_master WHERE type='table' AND name='direct_bank_purchase_payable_corrections'").get();
  const purchaseCorrections = hasPurchaseCorrections ? db.query(`
    SELECT correction.*,
           document.sha256_hash AS current_document_hash,
           original.entry_hash AS current_original_hash,
           reversal.reversal_of_entry_id AS reversal_target,
           payable.document_id AS payable_document_id,
           payment.payable_id AS payment_payable_id,
           payment.bank_transaction_id AS payment_bank_id,
           payment.journal_entry_id AS payment_journal_id,
           EXISTS(SELECT 1 FROM bank_reconciliation_correction_events event
                    WHERE event.bank_transaction_id=correction.bank_transaction_id
                      AND event.replacement_journal_entry_id=correction.settlement_journal_entry_id) AS has_reconciliation_correction,
           EXISTS(SELECT 1 FROM audit_log audit
                    WHERE audit.event_type='direct_bank_purchase_payable_corrected'
                      AND audit.entity_type='bank_transaction'
                      AND audit.entity_id=CAST(correction.bank_transaction_id AS TEXT)
                      AND (audit.actor=correction.actor OR audit.actor LIKE correction.actor || ' via %')) AS has_audit
      FROM direct_bank_purchase_payable_corrections correction
      JOIN documents document ON document.id=correction.document_id
      JOIN journal_entries original ON original.id=correction.original_journal_entry_id
      JOIN journal_entries reversal ON reversal.id=correction.reversal_journal_entry_id
      JOIN payables payable ON payable.id=correction.payable_id
      JOIN payable_payments payment ON payment.id=correction.payment_id
     ORDER BY correction.id`).all() as any[] : [];
  for (const correction of purchaseCorrections) {
    const label = `direct-bank purchase payable correction ${correction.id}`;
    if (correction.current_document_hash !== correction.document_hash || correction.current_original_hash !== correction.original_journal_hash) errors.push(`${label}: immutable source hash mismatch`);
    if (Number(correction.reversal_target) !== Number(correction.original_journal_entry_id)) errors.push(`${label}: reversal linkage is invalid`);
    if (Number(correction.payable_document_id) !== Number(correction.document_id) || Number(correction.payment_payable_id) !== Number(correction.payable_id) || Number(correction.payment_bank_id) !== Number(correction.bank_transaction_id) || Number(correction.payment_journal_id) !== Number(correction.settlement_journal_entry_id)) errors.push(`${label}: payable/payment linkage is invalid`);
    if (!Number(correction.has_reconciliation_correction) || !Number(correction.has_audit)) errors.push(`${label}: reconciliation correction or audit evidence is missing`);
  }
  const badCurrent = db.query(`SELECT bank_transaction_id,COUNT(*) AS count FROM bank_journal_reconciliations GROUP BY bank_transaction_id HAVING COUNT(*)<>1`).all() as Array<{bank_transaction_id:number;count:number}>;
  for (const row of badCurrent) errors.push(`bank transaction ${row.bank_transaction_id}: has ${row.count} effective reconciliations; exactly one is required`);

  const orphanLines = db.query(
    `SELECT jl.id, jl.journal_entry_id
     FROM journal_lines jl
     LEFT JOIN journal_entries je ON je.id = jl.journal_entry_id
     WHERE je.id IS NULL
     ORDER BY jl.id ASC`
  ).all() as Array<{ id: number; journal_entry_id: number }>;
  for (const line of orphanLines) {
    errors.push(`journal_line ${line.id}: orphan journal_entry_id ${line.journal_entry_id}`);
  }

  const brokenAccountLines = db.query(
    `SELECT jl.id, jl.account_id
     FROM journal_lines jl
     LEFT JOIN accounts a ON a.id = jl.account_id
     WHERE a.id IS NULL
     ORDER BY jl.id ASC`
  ).all() as Array<{ id: number; account_id: number }>;
  for (const line of brokenAccountLines) {
    errors.push(`journal_line ${line.id}: missing account_id ${line.account_id}`);
  }

  for (const e of entries) {
    const lines = db.query(
      `SELECT a.account_no, a.type AS account_type, jl.debit_amount, jl.credit_amount, jl.vat_code, jl.text
       FROM journal_lines jl
       JOIN accounts a ON a.id = jl.account_id
       WHERE jl.journal_entry_id = ?
       ORDER BY jl.id ASC`
    ).all(e.id) as any[];
    linesByEntryId.set(Number(e.id), lines);
    if (lines.length === 0) errors.push(`${e.entry_no}: entry has no journal lines`);

    const canonicalLines = lines.map(({ account_type, ...line }) => line);
    const expected = hashEntry(canonicalEntryData(e, canonicalLines), prev);
    if (e.previous_hash !== prev) errors.push(`${e.entry_no}: previous_hash mismatch`);
    if (e.entry_hash !== expected) errors.push(`${e.entry_no}: entry_hash mismatch`);

    const debitSum = lines.reduce((sum, line) => sum + toOre(Number(line.debit_amount ?? 0)), 0n);
    const creditSum = lines.reduce((sum, line) => sum + toOre(Number(line.credit_amount ?? 0)), 0n);
    if (debitSum !== creditSum) errors.push(`${e.entry_no}: entry is unbalanced (${fromOre(debitSum)} != ${fromOre(creditSum)})`);
    if (
      (e.status === "reversed" && e.reversal_of_entry_id == null) ||
      (e.status === "posted" && e.reversal_of_entry_id != null)
    ) {
      errors.push(`${e.entry_no}: journal reversal status does not match reversal_of_entry_id`);
    }
    if (e.reversal_of_entry_id != null) {
      const originalId = Number(e.reversal_of_entry_id);
      const original = entriesById.get(originalId);
      if (!original) {
        errors.push(`${e.entry_no}: reversal target journal entry ${originalId} does not exist`);
      } else {
        if (original.status !== "posted" || original.reversal_of_entry_id != null) {
          errors.push(`${e.entry_no}: reversal target ${original.entry_no} is not an unreversed posted original`);
        }
        if (Number(original.id) >= Number(e.id)) {
          errors.push(`${e.entry_no}: reversal target ${original.entry_no} must precede the reversal row`);
        }

        const metadataMismatches: string[] = [];
        if ((e.document_id ?? null) !== (original.document_id ?? null)) metadataMismatches.push("document_id");
        if ((e.source_bank_transaction_id ?? null) !== (original.source_bank_transaction_id ?? null)) {
          metadataMismatches.push("source_bank_transaction_id");
        }
        if (String(e.currency ?? "DKK").trim().toUpperCase() !== String(original.currency ?? "DKK").trim().toUpperCase()) {
          metadataMismatches.push("currency");
        }
        const sameNullableAmount = (left: unknown, right: unknown) => {
          if (left == null || right == null) return left == null && right == null;
          return compareDkk(Number(left), Number(right)) === 0;
        };
        if (!sameNullableAmount(e.amount_foreign, original.amount_foreign)) metadataMismatches.push("amount_foreign");
        if (!sameNullableAmount(e.amount_dkk, original.amount_dkk)) metadataMismatches.push("amount_dkk");
        const sameNullableRate = (left: unknown, right: unknown) => {
          if (left == null || right == null) return left == null && right == null;
          return roundRate6(Number(left)) === roundRate6(Number(right));
        };
        if (!sameNullableRate(e.fx_rate_to_dkk, original.fx_rate_to_dkk)) metadataMismatches.push("fx_rate_to_dkk");
        if (metadataMismatches.length > 0) {
          errors.push(`${e.entry_no}: reversal metadata differs from ${original.entry_no} (${metadataMismatches.join(", ")})`);
        }

        const originalLines = linesByEntryId.get(originalId) ?? db.query(
          `SELECT a.account_no, a.type AS account_type, jl.debit_amount, jl.credit_amount, jl.vat_code, jl.text
             FROM journal_lines jl
             JOIN accounts a ON a.id = jl.account_id
            WHERE jl.journal_entry_id = ?
            ORDER BY jl.id ASC`,
        ).all(originalId) as any[];
        let exactInverse = originalLines.length === lines.length;
        if (exactInverse) {
          for (let index = 0; index < lines.length; index += 1) {
            const reversalLine = lines[index];
            const originalLine = originalLines[index];
            if (
              reversalLine.account_no !== originalLine.account_no ||
              (reversalLine.vat_code ?? null) !== (originalLine.vat_code ?? null) ||
              toOre(Number(reversalLine.debit_amount ?? 0)) !== toOre(Number(originalLine.credit_amount ?? 0)) ||
              toOre(Number(reversalLine.credit_amount ?? 0)) !== toOre(Number(originalLine.debit_amount ?? 0))
            ) {
              exactInverse = false;
              break;
            }
          }
        }
        if (!exactInverse) {
          errors.push(`${e.entry_no}: reversal lines do not exactly invert ${original.entry_no}`);
        }
      }
    }

    const requiresDocument = lines.some((line) => line.account_type === "expense" || line.account_type === "income");
    // A replayed migration posting (#195) carries no Rentemester document yet —
    // #196 attaches the original bilag. It is identified by its import
    // `created_by_program` and exempted from the document-evidence check.
    const isImportedHistorical = IMPORTED_HISTORICAL_PROGRAMS.has(e.created_by_program);
    if (requiresDocument && !isImportedHistorical && e.document_id == null) {
      errors.push(`${e.entry_no}: income/expense entry is missing document evidence`);
    }
    if (e.document_id != null) {
      const document = db.query(
        "SELECT id, document_no, sha256_hash, stored_path, document_type FROM documents WHERE id = ?",
      ).get(e.document_id) as AuditEvidenceDocument | null;
      if (!document) {
        errors.push(`${e.entry_no}: document_id ${e.document_id} is missing`);
      } else {
        journalReferencedDocumentIds.add(document.id);
        let evidenceError = documentEvidenceCache.get(document.id);
        if (evidenceError === undefined && !documentEvidenceCache.has(document.id)) {
          evidenceError = verifyRegisteredDocumentEvidence(document, companyRoot);
          documentEvidenceCache.set(document.id, evidenceError);
        }
        if (evidenceError) {
          errors.push(`${e.entry_no}: document_id ${document.id} ${evidenceError}`);
        }
      }
    }

    prev = e.entry_hash;
  }

  // The document register is itself retained bookkeeping evidence. Verify all
  // rows, including invoice PDFs, balance-only journal attachments, and
  // ingested documents that have not yet been posted. A signed backup manifest
  // authenticates the backup package, but it must not be able to replace the
  // independent hash committed in this register.
  const registeredDocuments = db.query(
    `SELECT id, document_no, sha256_hash, stored_path, document_type
       FROM documents
      ORDER BY id ASC`,
  ).all() as AuditEvidenceDocument[];
  for (const document of registeredDocuments) {
    if (journalReferencedDocumentIds.has(document.id)) continue;
    let evidenceError = documentEvidenceCache.get(document.id);
    if (evidenceError === undefined && !documentEvidenceCache.has(document.id)) {
      evidenceError = verifyRegisteredDocumentEvidence(document, companyRoot);
      documentEvidenceCache.set(document.id, evidenceError);
    }
    if (evidenceError) {
      errors.push(`document ${document.document_no ?? document.id}: ${evidenceError}`);
    }
  }

  // Tail-truncation guard: the journal_entry sequence is monotonic and protected
  // against rollback, so it records the highest entry number ever allocated for
  // a fiscal scope. Deleting the most recent entries leaves a valid but shorter
  // chain; cross-checking the count and highest entry_no against the issued
  // sequence value detects those missing entries.
  const journalSequences = db.query(
    `SELECT scope, value FROM sequences WHERE kind = 'journal_entry'`
  ).all() as Array<{ scope: string; value: number }>;
  for (const sequence of journalSequences) {
    const fiscalScope = sequence.scope.slice(sequence.scope.lastIndexOf(":") + 1);
    if (!fiscalScope) continue;
    // KODE-12: width-robust suffix match. The old fixed `[0-9]{5}` GLOB +
    // `substr(-5)` silently dropped every six-digit (>99 999) entry, so a scope
    // that grew past the boundary read MAX=0 and falsely failed "entries are
    // missing". Anchor the `${scope}-` prefix by length and require the suffix
    // to be all digits, so any width matches and parses.
    const prefix = `${fiscalScope}-`;
    const stats = db.query(
      `SELECT COUNT(*) AS n, COALESCE(MAX(CAST(substr(entry_no, ? + 1) AS INTEGER)), 0) AS max_no
         FROM journal_entries
        WHERE substr(entry_no, 1, ?) = ?
          AND length(entry_no) > ?
          AND substr(entry_no, ? + 1) NOT GLOB '*[^0-9]*'`
    ).get(prefix.length, prefix.length, prefix, prefix.length, prefix.length) as { n: number; max_no: number };
    const expected = Number(sequence.value);
    if (Number(stats.max_no) < expected) {
      errors.push(`fiscal scope ${fiscalScope}: highest journal entry ${fiscalScope}-${String(stats.max_no).padStart(ENTRY_NO_MIN_DIGITS, "0")} is below issued sequence value ${expected} — entries are missing`);
    } else if (Number(stats.n) < expected) {
      errors.push(`fiscal scope ${fiscalScope}: ${stats.n} journal entries present but sequence issued ${expected} — entries are missing`);
    }
  }

  const bankLinkedEntries = db.query(
    `SELECT id, entry_no, source_bank_transaction_id, status, reversal_of_entry_id
     FROM journal_entries
     WHERE source_bank_transaction_id IS NOT NULL
     ORDER BY id ASC`
  ).all() as { id: number; entry_no: string; source_bank_transaction_id: number; status: string; reversal_of_entry_id: number | null }[];
  const byBankTransaction = new Map<number, typeof bankLinkedEntries>();
  for (const entry of bankLinkedEntries) {
    const existing = byBankTransaction.get(entry.source_bank_transaction_id) ?? [];
    existing.push(entry);
    byBankTransaction.set(entry.source_bank_transaction_id, existing);
  }
  for (const [bankTransactionId, group] of byBankTransaction.entries()) {
    if (group.length <= 1) continue;
    const cancelled = new Set<number>();
    const idsInGroup = new Set(group.map((entry) => entry.id));
    for (const entry of group) {
      if (entry.reversal_of_entry_id != null && idsInGroup.has(entry.reversal_of_entry_id)) {
        cancelled.add(entry.id);
        cancelled.add(entry.reversal_of_entry_id);
      }
    }
    const remaining = group.filter((entry) => !cancelled.has(entry.id));
    if (remaining.length > 1) {
      errors.push(`duplicate source_bank_transaction_id ${bankTransactionId}: used by ${remaining.length} active entries (${remaining.map((entry) => entry.entry_no).join(', ')})`);
    }
  }

  const invoiceEvidence = validateInvoiceJournalEvidence(db);
  errors.push(...invoiceEvidence.errors);

  const issuedInvoices = db.query("SELECT id, invoice_no, status FROM documents WHERE document_type = 'issued_invoice' ORDER BY id ASC").all() as Array<{ id: number; invoice_no: string | null; status: string | null }>;
  const allowedStoredStatus: Record<string, string[]> = {
    open: ["issued", "open"],
    paid: ["paid", "settled"],
    credited: ["credited"],
    refunded: ["refunded"],
    overpaid: ["overpaid"],
    written_off: ["written_off"],
  };
  for (const invoice of issuedInvoices) {
    const status = getInvoiceStatus(db, invoice.id);
    if (!status.ok) {
      errors.push(`invoice ${invoice.invoice_no ?? invoice.id}: status cross-check failed (${status.errors.join('; ')})`);
      continue;
    }
    const stored = invoice.status ?? "";
    if (stored === "issued") continue;
    const allowed = allowedStoredStatus[status.status ?? ""] ?? [status.status ?? ""];
    if (!allowed.includes(stored)) {
      errors.push(`invoice ${invoice.invoice_no ?? invoice.id}: stored status ${stored} does not match ledger status ${status.status} (open balance ${status.openBalance})`);
    }
  }

  // KODE-14: defence-in-depth audit_log tamper-evidence. The audit_log has no
  // hash chain of its own, so a removed row would otherwise be invisible here.
  // Fold in the id-gap detection (a hole means a middle row was deleted). The
  // stronger journal cross-check is left to the standalone verifyAuditLog-
  // Integrity caller: it assumes every entry was posted through the normal
  // path, which manually-inserted entries (migrations, fixtures) need not be.
  const auditLogIntegrity = verifyAuditLogIntegrity(db, { journalCrossCheck: false });
  errors.push(...auditLogIntegrity.errors);

  return { ok: errors.length === 0, entries: entries.length, errors };
}

function inferredAuditCompanyRoot(db: Database, explicit?: string) {
  if (typeof explicit === "string" && explicit.trim().length > 0) {
    return resolve(explicit.trim());
  }
  const filename = (db as unknown as { filename?: string }).filename;
  if (typeof filename !== "string" || filename.length === 0 || filename === ":memory:") {
    return null;
  }
  return dirname(dirname(resolve(filename)));
}

export function compareDkk(left: number, right: number) {
  const l = toOre(left);
  const r = toOre(right);
  if (l === r) return 0;
  return l < r ? -1 : 1;
}

export function hashEntry(data: unknown, prev: string) {
  return createHash("sha256").update(JSON.stringify(data)).update(prev).digest("hex");
}

export function toOre(value: number) {
  if (!Number.isFinite(value)) throw new Error(`invalid monetary amount: ${value}`);
  return scaledInt(value, 2);
}

export function fromOre(value: Ore) {
  return fromScaledInt(value, 2);
}

const sameNullableAmount = (left: unknown, right: unknown) => {
          if (left == null || right == null) return left == null && right == null;
          return compareDkk(Number(left), Number(right)) === 0;
        };

export function roundRate6(value: number) {
  return Number.isFinite(value) ? fromScaledInt(scaledInt(value, 6), 6) : NaN;
}

const sameNullableRate = (left: unknown, right: unknown) => {
          if (left == null || right == null) return left == null && right == null;
          return roundRate6(Number(left)) === roundRate6(Number(right));
        };

function verifyRegisteredDocumentEvidence(
  document: AuditEvidenceDocument,
  companyRoot: string | null,
): string | null {
  if (!document.stored_path || document.stored_path.trim().length === 0) {
    return "has no stored_path";
  }
  if (!document.sha256_hash || !/^[0-9a-f]{64}$/i.test(document.sha256_hash.trim())) {
    return "has an invalid sha256_hash";
  }
  if (!companyRoot) return "cannot resolve the current company root";

  const expectedRelativeStore = isIssuedDocumentEvidence(document.document_type)
    ? "invoices/issued"
    : "documents/originals";
  try {
    snapshotRegisteredDocumentEvidence(companyRoot, {
      storedPath: document.stored_path,
      expectedSha256: document.sha256_hash,
      documentType: document.document_type,
    });
    return null;
  } catch (error) {
    if (error instanceof DocumentEvidenceError) {
      if (error.reason === "hash_mismatch") {
        return "stored evidence sha256 does not match the document register";
      }
      if (error.reason === "invalid_path") {
        return `stored_path is invalid or outside the ${expectedRelativeStore} evidence store`;
      }
      if (error.reason === "unsafe_store") {
        return `${expectedRelativeStore} evidence store is not a safe regular directory`;
      }
      if (error.reason === "unsafe_file" || error.reason === "invalid_size") {
        return "stored evidence path is not a safe regular file";
      }
    }
    return "stored evidence file is missing or inaccessible";
  }
}

export function validateInvoiceJournalEvidence(
  db: Database,
  options: {
    invoiceDocumentId?: number;
    candidates?: InvoiceJournalApplicationCandidate[];
  } = {},
) {
  const scopedExisting = loadApplications(db, options.invoiceDocumentId);
  const candidates: InvoiceJournalApplication[] = (options.candidates ?? []).map((candidate) => ({
    ...candidate,
    applicationId: null,
    bankTransactionId: candidate.bankTransactionId ?? null,
    journalEntryId: candidate.journalEntryId ?? null,
    currency: evidenceCurrency(candidate.currency),
  }));

  let applications: InvoiceJournalApplication[];
  if (options.invoiceDocumentId == null) {
    applications = [...scopedExisting, ...candidates];
  } else {
    const byApplication = new Map(
      scopedExisting.map((row) => [`${row.kind}:${row.applicationId}`, row] as const),
    );
    const candidateJournalIds = new Set(
      candidates.flatMap((row) => row.journalEntryId == null ? [] : [row.journalEntryId]),
    );
    for (const journalEntryId of candidateJournalIds) {
      for (const row of loadApplicationsForJournal(db, journalEntryId)) {
        byApplication.set(`${row.kind}:${row.applicationId}`, row);
      }
    }
    applications = [...byApplication.values(), ...candidates];
  }

  const errors: string[] = [];

  const unresolvedInvoiceJournals = db.query(
    `SELECT d.id AS invoice_document_id, d.invoice_no,
            j.id AS journal_entry_id, j.entry_no
       FROM documents d
       JOIN journal_entries j
         ON j.document_id = d.id
        AND j.status = 'posted'
        AND j.reversal_of_entry_id IS NULL
        AND NOT EXISTS (
          SELECT 1 FROM journal_entries reversal
           WHERE reversal.reversal_of_entry_id = j.id
        )
      WHERE d.document_type = 'issued_invoice'
        AND NOT EXISTS (
          SELECT 1 FROM issued_invoice_postings posting
           WHERE posting.journal_entry_id = j.id
        )
        AND NOT EXISTS (SELECT 1 FROM invoice_payments application WHERE application.journal_entry_id = j.id)
        AND NOT EXISTS (SELECT 1 FROM invoice_refunds application WHERE application.journal_entry_id = j.id)
        AND NOT EXISTS (SELECT 1 FROM invoice_claim_payments application WHERE application.journal_entry_id = j.id)
        AND NOT EXISTS (SELECT 1 FROM invoice_bad_debt_writeoffs application WHERE application.journal_entry_id = j.id)
        AND NOT EXISTS (SELECT 1 FROM invoice_interest_corrections application WHERE application.journal_entry_id = j.id)
        AND NOT EXISTS (SELECT 1 FROM invoice_reminder_postings application WHERE application.journal_entry_id = j.id)
        AND NOT EXISTS (SELECT 1 FROM invoice_compensation_postings application WHERE application.journal_entry_id = j.id)
        AND NOT EXISTS (SELECT 1 FROM invoice_interest_postings application WHERE application.journal_entry_id = j.id)
        AND (? IS NULL OR d.id = ?)
      ORDER BY d.id ASC, j.id ASC`,
  ).all(
    options.invoiceDocumentId ?? null,
    options.invoiceDocumentId ?? null,
  ) as Array<{
    invoice_document_id: number;
    invoice_no: string | null;
    journal_entry_id: number;
    entry_no: string;
  }>;
  const candidateApplicationJournalIds = new Set(
    candidates.flatMap((candidate) => candidate.journalEntryId == null ? [] : [candidate.journalEntryId]),
  );
  for (const row of unresolvedInvoiceJournals) {
    // Write paths validate a newly posted journal before inserting the
    // append-only application row. The explicit candidate is its temporary
    // classification inside this same transaction; global/scoped reads have no
    // candidates and therefore still flag every persisted unclassified entry.
    if (candidateApplicationJournalIds.has(row.journal_entry_id)) continue;
    errors.push(
      `invoice ${row.invoice_no ?? row.invoice_document_id} has unresolved legacy journal ${row.entry_no} without an explicit issued-invoice posting link`,
    );
  }

  const noncanonicalCreditNoteJournals = db.query(
    `SELECT credit.id AS credit_note_document_id,
            credit.invoice_no AS credit_note_no,
            journal.id AS journal_entry_id,
            journal.entry_no
       FROM documents credit
       JOIN journal_entries journal
         ON journal.document_id = credit.id
       LEFT JOIN credit_note_postings posting
         ON posting.credit_note_document_id = credit.id
       LEFT JOIN documents inferred
         ON inferred.document_type = 'issued_invoice'
        AND inferred.invoice_no = credit.payment_details
      WHERE credit.document_type = 'credit_note'
        AND (posting.journal_entry_id IS NULL OR posting.journal_entry_id <> journal.id)
        AND (
          ? IS NULL
          OR posting.original_invoice_document_id = ?
          OR inferred.id = ?
        )
      ORDER BY credit.id ASC, journal.id ASC`,
  ).all(
    options.invoiceDocumentId ?? null,
    options.invoiceDocumentId ?? null,
    options.invoiceDocumentId ?? null,
  ) as Array<{
    credit_note_document_id: number;
    credit_note_no: string | null;
    journal_entry_id: number;
    entry_no: string;
  }>;
  for (const row of noncanonicalCreditNoteJournals) {
    errors.push(
      `credit note ${row.credit_note_no ?? row.credit_note_document_id} has journal ${row.entry_no} outside its canonical credit-note posting link`,
    );
  }

  const badDebtWriteoffs = db.query(
    `SELECT writeoff.id AS writeoff_id,
            writeoff.invoice_document_id,
            invoice.invoice_no,
            writeoff.journal_entry_id,
            evidence.is_valid
       FROM invoice_bad_debt_writeoffs writeoff
       LEFT JOIN documents invoice ON invoice.id = writeoff.invoice_document_id
       LEFT JOIN invoice_bad_debt_writeoff_journal_evidence evidence
         ON evidence.writeoff_id = writeoff.id
      WHERE (? IS NULL OR writeoff.invoice_document_id = ?)
      ORDER BY writeoff.invoice_document_id ASC, writeoff.id ASC`,
  ).all(
    options.invoiceDocumentId ?? null,
    options.invoiceDocumentId ?? null,
  ) as Array<{
    writeoff_id: number;
    invoice_document_id: number;
    invoice_no: string | null;
    journal_entry_id: number;
    is_valid: number | null;
  }>;
  for (const writeoff of badDebtWriteoffs) {
    if (writeoff.is_valid === 1) continue;
    errors.push(
      `invoice ${writeoff.invoice_no ?? writeoff.invoice_document_id} bad-debt writeoff ${writeoff.writeoff_id} journal ${writeoff.journal_entry_id} does not match the exact VAT-relief expense/output-VAT/receivable evidence`,
    );
  }

  const linkedInvoiceIds = options.invoiceDocumentId == null
    ? (db.query(
      `SELECT invoice_document_id
         FROM issued_invoice_postings
        ORDER BY invoice_document_id ASC`,
    ).all() as Array<{ invoice_document_id: number }>).map((row) => row.invoice_document_id)
    : (db.query(
      "SELECT invoice_document_id FROM issued_invoice_postings WHERE invoice_document_id = ?",
    ).all(options.invoiceDocumentId) as Array<{ invoice_document_id: number }>).map((row) => row.invoice_document_id);
  for (const invoiceDocumentId of linkedInvoiceIds) {
    const booking = resolveInvoiceReceivableAccount(db, { invoiceDocumentId });
    if (!booking.ok) errors.push(booking.error);
  }

  if (options.invoiceDocumentId == null) {
    const orphanCreditDocuments = db.query(
      `SELECT c.id, c.invoice_no, c.payment_details,
              original.id AS original_invoice_document_id,
              p.original_invoice_document_id AS linked_original_invoice_document_id
         FROM documents c
         LEFT JOIN documents original
           ON original.document_type = 'issued_invoice'
          AND original.invoice_no = c.payment_details
         LEFT JOIN credit_note_postings p
           ON p.credit_note_document_id = c.id
        WHERE c.document_type = 'credit_note'
          AND (
            original.id IS NULL
            OR p.credit_note_document_id IS NULL
            OR p.original_invoice_document_id <> original.id
          )
        ORDER BY c.id ASC`,
    ).all() as Array<{
      id: number;
      invoice_no: string | null;
      payment_details: string | null;
      original_invoice_document_id: number | null;
      linked_original_invoice_document_id: number | null;
    }>;
    for (const credit of orphanCreditDocuments) {
      errors.push(
        `credit note ${credit.invoice_no ?? credit.id} has no exact issued-invoice posting evidence for ${credit.payment_details ?? "an original invoice"}`,
      );
    }
  }

  const creditInvoiceIds = options.invoiceDocumentId == null
    ? (db.query(
      `SELECT DISTINCT d.id AS invoice_document_id
         FROM documents d
        WHERE d.document_type = 'issued_invoice'
          AND (
            EXISTS (
              SELECT 1 FROM documents c
               WHERE c.document_type = 'credit_note'
                 AND c.payment_details = d.invoice_no
            )
            OR EXISTS (
              SELECT 1 FROM credit_note_postings p
               WHERE p.original_invoice_document_id = d.id
            )
          )
        ORDER BY d.id ASC`,
    ).all() as Array<{ invoice_document_id: number }>).map((row) => row.invoice_document_id)
    : [options.invoiceDocumentId];
  for (const invoiceDocumentId of creditInvoiceIds) {
    const creditEvidence = validateInvoiceCreditNoteEvidence(db, { invoiceDocumentId });
    if (!creditEvidence.ok) errors.push(...creditEvidence.errors);
  }

  const claimPostingInvoiceIds = (db.query(
    `SELECT DISTINCT invoice_document_id
       FROM (
         SELECT reminder.invoice_document_id
           FROM invoice_reminders reminder
           JOIN invoice_reminder_postings posting ON posting.reminder_id = reminder.id
         UNION ALL
         SELECT claim.invoice_document_id
           FROM invoice_compensation_claims claim
           JOIN invoice_compensation_postings posting ON posting.compensation_claim_id = claim.id
         UNION ALL
         SELECT claim.invoice_document_id
           FROM invoice_interest_claims claim
           JOIN invoice_interest_postings posting ON posting.interest_claim_id = claim.id
       ) claim_posting
      WHERE (? IS NULL OR invoice_document_id = ?)
      ORDER BY invoice_document_id ASC`,
  ).all(
    options.invoiceDocumentId ?? null,
    options.invoiceDocumentId ?? null,
  ) as Array<{ invoice_document_id: number }>).map((row) => row.invoice_document_id);
  for (const invoiceDocumentId of claimPostingInvoiceIds) {
    const claimEvidence = calculateClaimReceivableBalances(db, {
      invoiceDocumentId,
      allowUnpostedClaims: true,
    });
    if (!claimEvidence.ok) errors.push(...claimEvidence.errors);
  }

  const correctionInvoiceIds = options.invoiceDocumentId == null
    ? (db.query(
      `SELECT DISTINCT invoice_document_id
         FROM invoice_interest_corrections
        ORDER BY invoice_document_id ASC`,
    ).all() as Array<{ invoice_document_id: number }>).map((row) => row.invoice_document_id)
    : (db.query(
      `SELECT DISTINCT invoice_document_id
         FROM invoice_interest_corrections
        WHERE invoice_document_id = ?`,
    ).all(options.invoiceDocumentId) as Array<{ invoice_document_id: number }>).map((row) => row.invoice_document_id);
  for (const invoiceDocumentId of correctionInvoiceIds) {
    const receivables = calculateClaimReceivableBalances(db, {
      invoiceDocumentId,
      allowUnpostedClaims: true,
    });
    if (!receivables.ok) errors.push(...receivables.errors);
    const interestReceivables = calculateInterestReceivableBalances(db, {
      invoiceDocumentId,
      allowUnpostedClaims: true,
    });
    if (!interestReceivables.ok) errors.push(...interestReceivables.errors);
    const incomes = calculateInterestIncomeBalances(db, {
      invoiceDocumentId,
      allowUnpostedClaims: true,
    });
    if (!incomes.ok) errors.push(...incomes.errors);
    const correctionEvidence = buildInterestCorrectionEvidencePlan(db, {
      invoiceDocumentId,
    });
    if (!correctionEvidence.ok) errors.push(...correctionEvidence.errors);
  }

  const orphanCorrectionPlans = db.query(
    `SELECT plan.journal_entry_id, plan.invoice_document_id
       FROM invoice_interest_correction_plans plan
       LEFT JOIN invoice_interest_corrections correction
         ON correction.journal_entry_id = plan.journal_entry_id
      WHERE correction.id IS NULL
        AND (? IS NULL OR plan.invoice_document_id = ?)
      ORDER BY plan.journal_entry_id ASC`,
  ).all(
    options.invoiceDocumentId ?? null,
    options.invoiceDocumentId ?? null,
  ) as Array<{ journal_entry_id: number; invoice_document_id: number }>;
  for (const plan of orphanCorrectionPlans) {
    errors.push(
      `invoice ${plan.invoice_document_id} has orphan interest-correction plan for journal ${plan.journal_entry_id}`,
    );
  }

  const documentCache = new Map<number, { id: number; document_type: string; currency: string | null } | null>();
  const journalCache = new Map<number, JournalEvidence | null>();
  const bankCache = new Map<number, BankEvidence | null>();

  const getDocument = (id: number) => {
    if (!documentCache.has(id)) {
      documentCache.set(id, db.query(
        "SELECT id, document_type, currency FROM documents WHERE id = ?",
      ).get(id) as { id: number; document_type: string; currency: string | null } | null);
    }
    return documentCache.get(id) ?? null;
  };
  const getJournal = (id: number) => {
    if (!journalCache.has(id)) {
      journalCache.set(id, db.query(
        `SELECT id, document_id, source_bank_transaction_id, transaction_date,
                registration_datetime,
                currency, amount_foreign, amount_dkk, status,
                (SELECT reversal.id
                   FROM journal_entries reversal
                  WHERE reversal.reversal_of_entry_id = journal_entries.id
                  ORDER BY reversal.id ASC
                  LIMIT 1) AS reversed_by_entry_id
           FROM journal_entries WHERE id = ?`,
      ).get(id) as JournalEvidence | null);
    }
    return journalCache.get(id) ?? null;
  };
  const getBank = (id: number) => {
    if (!bankCache.has(id)) {
      bankCache.set(id, db.query(
        `SELECT bt.id, bt.amount, bt.currency, bt.amount_dkk, bt.bank_account_id,
                ba.currency AS bank_account_currency, ba.ledger_account_no
           FROM bank_transactions bt
           LEFT JOIN bank_accounts ba ON ba.id = bt.bank_account_id
          WHERE bt.id = ?`,
      ).get(id) as BankEvidence | null);
    }
    return bankCache.get(id) ?? null;
  };

  for (const application of applications) {
    const label = applicationLabel(application);
    if (!Number.isFinite(application.amount) || !(application.amount > 0)) {
      errors.push(`${label}: application amount must be a positive finite number`);
    }
    if (evidenceCurrency(application.currency).length !== 3) {
      errors.push(`${label}: application currency must be a 3-letter ISO code`);
    }
    const document = getDocument(application.invoiceDocumentId);
    if (!document) {
      errors.push(`${label}: invoice document is missing`);
    } else if (document.document_type !== "issued_invoice") {
      errors.push(`${label}: document is not an issued invoice`);
    } else if (
      application.kind === "payment" &&
      evidenceCurrency(document.currency) !== evidenceCurrency(application.currency)
    ) {
      errors.push(`${label}: application currency ${evidenceCurrency(application.currency)} does not match invoice currency ${evidenceCurrency(document.currency)}`);
    }

    if (application.journalEntryId == null) {
      errors.push(`${label}: missing journal evidence (legacy row unresolved)`);
      continue;
    }
    const journal = getJournal(application.journalEntryId);
    if (!journal) {
      errors.push(`${label}: missing journal evidence; journal entry ${application.journalEntryId} does not exist`);
      continue;
    }
    if (journal.status !== "posted") {
      errors.push(`${label}: journal entry ${journal.id} is ${journal.status}, not posted`);
    }
    if (journal.reversed_by_entry_id != null) {
      errors.push(`${label}: journal entry ${journal.id} was reversed by journal entry ${journal.reversed_by_entry_id}`);
    }
    if (journal.document_id !== application.invoiceDocumentId) {
      errors.push(`${label}: journal entry ${journal.id} references invoice document ${journal.document_id ?? "none"}`);
    }
    if (!sameNullableId(journal.source_bank_transaction_id, application.bankTransactionId)) {
      errors.push(`${label}: journal entry ${journal.id} bank transaction ${journal.source_bank_transaction_id ?? "none"} does not match application bank transaction ${application.bankTransactionId ?? "none"}`);
    }
    if (journal.transaction_date !== application.effectiveDate) {
      errors.push(`${label}: journal entry ${journal.id} date ${journal.transaction_date} does not match application date ${application.effectiveDate}`);
    }
    if (evidenceCurrency(journal.currency) !== evidenceCurrency(application.currency)) {
      errors.push(`${label}: journal entry ${journal.id} currency ${evidenceCurrency(journal.currency)} does not match application currency ${evidenceCurrency(application.currency)}`);
    }

    if (application.bankTransactionId != null) {
      const bank = getBank(application.bankTransactionId);
      if (!bank) {
        errors.push(`${label}: bank transaction ${application.bankTransactionId} does not exist`);
      } else {
        const bankAmount = Number(bank.amount);
        const requiresIncoming = application.kind === "payment" || application.kind === "claim";
        if (!Number.isFinite(bankAmount)) {
          errors.push(`${label}: bank transaction ${bank.id} amount is not a finite number`);
        } else if ((requiresIncoming && !(bankAmount > 0)) || (!requiresIncoming && !(bankAmount < 0))) {
          errors.push(`${label}: bank transaction ${bank.id} has the wrong direction for ${application.kind}`);
        }
        if (evidenceCurrency(bank.currency) !== evidenceCurrency(application.currency)) {
          errors.push(`${label}: bank transaction ${bank.id} currency ${evidenceCurrency(bank.currency)} does not match application currency ${evidenceCurrency(application.currency)}`);
        }
        if (
          bank.bank_account_id != null &&
          evidenceCurrency(bank.bank_account_currency) !== evidenceCurrency(bank.currency)
        ) {
          errors.push(`${label}: bank transaction ${bank.id} currency ${evidenceCurrency(bank.currency)} does not match source bank account currency ${evidenceCurrency(bank.bank_account_currency)}`);
        }
      }
    }
  }

  const byJournal = new Map<number, InvoiceJournalApplication[]>();
  for (const application of applications) {
    if (application.journalEntryId == null) continue;
    const group = byJournal.get(application.journalEntryId) ?? [];
    group.push(application);
    byJournal.set(application.journalEntryId, group);
  }

  for (const [journalEntryId, group] of byJournal) {
    const journal = getJournal(journalEntryId);
    if (!journal) continue;
    const kinds = group.map((row) => row.kind).sort();
    const allowed =
      (group.length === 1 && ["payment", "refund", "claim"].includes(kinds[0]!)) ||
      (group.length === 2 && kinds[0] === "claim" && kinds[1] === "payment");
    if (!allowed) {
      errors.push(`journal entry ${journalEntryId}: unsupported invoice application group (${kinds.join("+") || "none"})`);
      continue;
    }

    const first = group[0]!;
    for (const application of group.slice(1)) {
      if (
        application.invoiceDocumentId !== first.invoiceDocumentId ||
        !sameNullableId(application.bankTransactionId, first.bankTransactionId) ||
        application.effectiveDate !== first.effectiveDate ||
        evidenceCurrency(application.currency) !== evidenceCurrency(first.currency)
      ) {
        errors.push(`journal entry ${journalEntryId}: grouped invoice applications do not share invoice, bank transaction, date, and currency`);
        break;
      }
    }

    const groupAmountsAreValid = group.every((row) => Number.isFinite(row.amount) && row.amount > 0);
    const expectedApplicationAmount = groupAmountsAreValid
      ? sumDkk(group.map((row) => row.amount))
      : null;
    const lines = db.query(
      `SELECT a.account_no, jl.debit_amount, jl.credit_amount
         FROM journal_lines jl
         JOIN accounts a ON a.id = jl.account_id
        WHERE jl.journal_entry_id = ?
        ORDER BY jl.id ASC`,
    ).all(journalEntryId) as JournalLineEvidence[];
    let debitOre = 0n;
    let creditOre = 0n;
    let journalLineAmountsAreValid = true;
    for (const line of lines) {
      const debit = Number(line.debit_amount ?? 0);
      const credit = Number(line.credit_amount ?? 0);
      if (!Number.isFinite(debit) || !Number.isFinite(credit)) {
        journalLineAmountsAreValid = false;
        errors.push(`journal entry ${journalEntryId}: invoice evidence contains a non-finite journal-line amount`);
        continue;
      }
      debitOre += toOre(debit);
      creditOre += toOre(credit);
    }
    const journalDebit = fromOre(debitOre);
    const journalCredit = fromOre(creditOre);
    const currency = evidenceCurrency(first.currency);

    if (lines.length === 0) {
      errors.push(`journal entry ${journalEntryId}: invoice application evidence has no journal lines`);
    } else if (currency === "DKK" && expectedApplicationAmount != null && journalLineAmountsAreValid) {
      if (compareDkk(journalDebit, expectedApplicationAmount) !== 0 || compareDkk(journalCredit, expectedApplicationAmount) !== 0) {
        errors.push(`journal entry ${journalEntryId}: journal debit/credit ${journalDebit}/${journalCredit} does not match invoice application total ${expectedApplicationAmount} DKK`);
      }
    } else if (group.length === 1 && first.kind === "payment" && expectedApplicationAmount != null && journalLineAmountsAreValid) {
      if (journal.amount_foreign == null || !Number.isFinite(Number(journal.amount_foreign)) || compareDkk(Number(journal.amount_foreign), expectedApplicationAmount) !== 0) {
        errors.push(`journal entry ${journalEntryId}: foreign amount ${journal.amount_foreign ?? "none"} does not match invoice payment ${expectedApplicationAmount} ${currency}`);
      }
      if (journal.amount_dkk == null || !Number.isFinite(Number(journal.amount_dkk)) || !(Number(journal.amount_dkk) > 0) || debitOre !== creditOre) {
        errors.push(`journal entry ${journalEntryId}: DKK metadata/lines do not provide balanced evidence for the foreign invoice payment`);
      }
      const bank = first.bankTransactionId == null ? null : getBank(first.bankTransactionId);
      if (
        bank?.amount_dkk != null && Number.isFinite(Number(bank.amount_dkk)) &&
        journal.amount_dkk != null &&
        Number.isFinite(Number(journal.amount_dkk)) &&
        compareDkk(Math.abs(Number(bank.amount_dkk)), Number(journal.amount_dkk)) !== 0
      ) {
        errors.push(`journal entry ${journalEntryId}: DKK amount ${journal.amount_dkk} does not match bank transaction ${bank.id} DKK amount ${Math.abs(Number(bank.amount_dkk))}`);
      }
    }

    if (first.bankTransactionId != null) {
      const bank = getBank(first.bankTransactionId);
      if (bank && expectedApplicationAmount != null && Number.isFinite(Number(bank.amount)) && compareDkk(Math.abs(Number(bank.amount)), expectedApplicationAmount) !== 0) {
        errors.push(`journal entry ${journalEntryId}: bank transaction ${bank.id} amount ${Math.abs(Number(bank.amount))} does not match invoice application total ${expectedApplicationAmount} ${currency}`);
      }
    }

    errors.push(...validateAccountEffects(db, journal, group, lines, expectedApplicationAmount));
  }

  return { ok: errors.length === 0, errors: [...new Set(errors)] };
}

export function verifyAuditLogIntegrity(
  db: Database,
  options: VerifyAuditLogIntegrityOptions = {},
): VerifyAuditLogIntegrityResult {
  const journalCrossCheck = options.journalCrossCheck ?? true;
  const errors: string[] = [];

  const span = db
    .query("SELECT COUNT(*) AS n, MIN(id) AS lo, MAX(id) AS hi FROM audit_log")
    .get() as { n: number; lo: number | null; hi: number | null };
  const rows = Number(span.n ?? 0);

  if (rows > 0 && span.lo != null && span.hi != null) {
    const expectedSpan = Number(span.hi) - Number(span.lo) + 1;
    if (rows !== expectedSpan) {
      errors.push(
        `audit_log id sequence has gaps: ${rows} rows present but id range ${span.lo}..${span.hi} spans ${expectedSpan} — ${expectedSpan - rows} row(s) missing`,
      );
    }
  }

  // Journal cross-check: every journal entry must have its matching audit event.
  if (journalCrossCheck) {
    const orphanEntries = db
      .query(
        `SELECT je.id, je.entry_no
           FROM journal_entries je
          WHERE NOT EXISTS (
            SELECT 1 FROM audit_log al
             WHERE al.entity_type = 'journal_entry'
               AND al.entity_id = CAST(je.id AS TEXT)
          )
          ORDER BY je.id ASC`,
      )
      .all() as Array<{ id: number; entry_no: string }>;
    for (const entry of orphanEntries) {
      errors.push(`journal entry ${entry.entry_no} has no matching audit event — an audit_log row was removed`);
    }
  }

  return { ok: errors.length === 0, rows, errors };
}

export function buildPayablesList(db: Database, filters: PayablesListFilters = {}): PayablesListResult {
  const status = filters.status ?? "all";
  const errors: string[] = [];
  if (filters.asOfDate !== undefined && !looksLikeIsoDate(filters.asOfDate)) errors.push("asOfDate must be YYYY-MM-DD when present");
  if (filters.from !== undefined && !looksLikeIsoDate(filters.from)) errors.push("from must be YYYY-MM-DD when present");
  if (filters.to !== undefined && !looksLikeIsoDate(filters.to)) errors.push("to must be YYYY-MM-DD when present");
  if (!["open", "paid", "overdue", "all"].includes(status)) errors.push("status must be one of open, paid, overdue, all");
  if (filters.vendorId !== undefined && (!Number.isInteger(filters.vendorId) || filters.vendorId <= 0)) {
    errors.push("vendorId must be a positive integer when present");
  }
  // Default til dagens dato så et kald uden asOfDate giver et brugbart svar:
  // status="overdue" returnerer reelt forfaldne poster i stedet for at aldre
  // mod en epoch-dato hvor intet nogensinde er forfaldent.
  const asOfDate = filters.asOfDate ?? todayIsoDate();
  if (errors.length > 0) {
    return { ok: false, count: 0, status, asOfDate, totalOpenBalance: 0, overdueOpenBalance: 0, notYetDueOpenBalance: 0, rows: [], errors };
  }

  const supplierNeedle = filters.supplier?.trim().toLocaleLowerCase() ?? "";
  const minDays = Number.isFinite(filters.minDays) ? Math.max(0, Number(filters.minDays)) : 0;

  const payables = db.query(
    `SELECT id, document_id, vendor_id, supplier_name, bill_no, bill_date, due_date,
            gross_amount, net_amount, vat_amount, currency, journal_entry_id, note
     FROM payables ORDER BY due_date ASC, id ASC`,
  ).all() as PayableRow[];

  const rows: PayablesListRow[] = [];
  for (const payable of payables) {
    if (payable.bill_date > asOfDate) continue;
    if (filters.from && payable.bill_date < filters.from) continue;
    if (filters.to && payable.bill_date > filters.to) continue;
    if (filters.vendorId !== undefined && payable.vendor_id !== filters.vendorId) continue;
    if (supplierNeedle && !(payable.supplier_name ?? "").toLocaleLowerCase().includes(supplierNeedle)) continue;

    const grossAmount = roundDkk(Number(payable.gross_amount));
    const openBalance = openBalanceOf(db, payable, asOfDate);
    const itemStatus: PayableStatus = openBalance > 0 ? "open" : "paid";
    const overdueDays = openBalance > 0 ? Math.max(0, diffDays(payable.due_date, asOfDate)) : 0;
    const isOverdue = overdueDays > 0;

    if (status === "open" && itemStatus !== "open") continue;
    if (status === "paid" && itemStatus !== "paid") continue;
    if (status === "overdue" && (!isOverdue || overdueDays < minDays)) continue;

    rows.push({
      payableId: payable.id,
      documentId: payable.document_id,
      billNo: payable.bill_no,
      billDate: payable.bill_date,
      dueDate: payable.due_date,
      supplierName: payable.supplier_name,
      vendorId: payable.vendor_id,
      grossAmount,
      currency: payable.currency,
      paidAmount: subtractDkk(grossAmount, openBalance),
      openBalance,
      status: itemStatus,
      isOverdue,
      overdueDays,
      agingBucket: agingBucket(isOverdue, overdueDays),
    });
  }

  rows.sort((a, b) => {
    if (b.overdueDays !== a.overdueDays) return b.overdueDays - a.overdueDays;
    if (a.dueDate !== b.dueDate) return a.dueDate.localeCompare(b.dueDate);
    return a.payableId - b.payableId;
  });

  const totalOpenBalance = sumDkk(rows.map((r) => r.openBalance));
  const overdueOpenBalance = sumDkk(rows.filter((r) => r.isOverdue).map((r) => r.openBalance));
  const notYetDueOpenBalance = sumDkk(rows.filter((r) => !r.isOverdue).map((r) => r.openBalance));

  return {
    ok: true,
    count: rows.length,
    status,
    asOfDate,
    totalOpenBalance,
    overdueOpenBalance,
    notYetDueOpenBalance,
    rows,
    errors: [],
  };
}

function openBalanceOf(db: Database, payable: PayableRow, asOfDate?: string): number {
  const payments = db.query(
    `SELECT amount FROM payable_payments WHERE payable_id = ?${asOfDate ? " AND payment_date <= ?" : ""}`,
  ).all(...(asOfDate ? [payable.id, asOfDate] : [payable.id])) as Array<{ amount: number }>;
  const paid = sumDkk(payments.map((p) => Number(p.amount)));
  return subtractDkk(roundDkk(Number(payable.gross_amount)), paid);
}

export function diffDays(fromDate: string, toDate: string): number {
  const from = new Date(`${fromDate}T00:00:00.000Z`).getTime();
  const to = new Date(`${toDate}T00:00:00.000Z`).getTime();
  return Math.round((to - from) / 86400000);
}

export function subtractDkk(left: number, ...rights: number[]) {
  let total = toOre(left);
  for (const value of rights) total -= toOre(value);
  return fromOre(total);
}

function agingBucket(isOverdue: boolean, overdueDays: number): PayableAgingBucket {
  if (!isOverdue) return "not-due";
  if (overdueDays <= 30) return "0-30";
  if (overdueDays <= 60) return "31-60";
  if (overdueDays <= 90) return "61-90";
  return "90+";
}

export function sumDkk(values: Array<number | null | undefined>) {
  let total = 0n;
  for (const value of values) {
    if (value == null) continue;
    total += toOre(value);
  }
  return fromOre(total);
}

export function buildAccrualRegisterReport(db: Database): AccrualRegisterReport {
  const rows = db.query(
    `SELECT a.id, a.accrual_type, a.description, a.total_amount, a.recognition_periods,
            a.balance_account_no, a.result_account_no, a.first_recognition_date, a.period_step_months,
            COUNT(p.id) AS recognized_periods,
            COALESCE(SUM(p.amount), 0) AS recognized_amount
     FROM accruals a
     LEFT JOIN accrual_schedule_postings p ON p.accrual_id = a.id
     GROUP BY a.id
     ORDER BY a.id ASC`,
  ).all() as Array<{
    id: number;
    accrual_type: AccrualType;
    description: string;
    total_amount: number;
    recognition_periods: number;
    balance_account_no: string;
    result_account_no: string;
    first_recognition_date: string;
    period_step_months: number;
    recognized_periods: number;
    recognized_amount: number;
  }>;

  let totalOre = 0n;
  let recognizedOre = 0n;
  const accruals: AccrualRegisterRow[] = rows.map((row) => {
    const totalAmount = roundDkk(Number(row.total_amount));
    const recognizedAmount = roundDkk(Number(row.recognized_amount));
    const remainingAmount = fromOre(toOre(totalAmount) - toOre(recognizedAmount));
    totalOre += toOre(totalAmount);
    recognizedOre += toOre(recognizedAmount);
    return {
      accrualId: row.id,
      accrualType: row.accrual_type,
      description: row.description,
      totalAmount,
      recognitionPeriods: row.recognition_periods,
      recognizedPeriods: Number(row.recognized_periods),
      recognizedAmount,
      remainingAmount,
      fullyRecognized: Number(row.recognized_periods) === row.recognition_periods,
      balanceAccountNo: row.balance_account_no,
      resultAccountNo: row.result_account_no,
      firstRecognitionDate: row.first_recognition_date,
      periodStepMonths: row.period_step_months,
    };
  });

  return {
    ok: true,
    accruals,
    totals: {
      totalAmount: fromOre(totalOre),
      recognizedAmount: fromOre(recognizedOre),
      remainingAmount: fromOre(totalOre - recognizedOre),
    },
    errors: [],
  };
}

export function listDueAccrualRecognitionPeriods(
  db: Database,
  asOfDate: string,
): DueAccrualRecognitionResult {
  if (!looksLikeIsoDate(asOfDate)) {
    return { ok: false, asOfDate, periods: [], totalDueAmount: 0, errors: ["asOfDate must be YYYY-MM-DD"] };
  }

  const headers = db.query(
    `SELECT id, accrual_type, description, total_amount, recognition_periods,
            first_recognition_date, period_step_months
     FROM accruals ORDER BY id ASC`,
  ).all() as Array<{
    id: number;
    accrual_type: AccrualType;
    description: string;
    total_amount: number;
    recognition_periods: number;
    first_recognition_date: string;
    period_step_months: number;
  }>;

  const periods: DueAccrualRecognitionPeriod[] = [];
  for (const header of headers) {
    const postedIndexes = new Set(
      (
        db.query(
          "SELECT period_index FROM accrual_schedule_postings WHERE accrual_id = ?",
        ).all(header.id) as Array<{ period_index: number }>
      ).map((r) => r.period_index),
    );
    const schedule = computeAccrualSchedule({
      totalAmount: Number(header.total_amount),
      recognitionPeriods: header.recognition_periods,
      firstRecognitionDate: header.first_recognition_date,
      periodStepMonths: header.period_step_months,
    });
    for (const period of schedule) {
      if (postedIndexes.has(period.periodIndex)) continue;
      if (period.recognitionDate > asOfDate) continue;
      periods.push({
        accrualId: header.id,
        accrualType: header.accrual_type,
        description: header.description,
        periodIndex: period.periodIndex,
        totalPeriods: schedule.length,
        recognitionDate: period.recognitionDate,
        amount: period.amount,
        overdueDays: Math.max(0, diffDays(period.recognitionDate, asOfDate)),
      });
    }
  }

  // Stable order: oldest recognition date first, then accrual id / period.
  periods.sort((a, b) => {
    if (a.recognitionDate !== b.recognitionDate) {
      return a.recognitionDate < b.recognitionDate ? -1 : 1;
    }
    if (a.accrualId !== b.accrualId) return a.accrualId - b.accrualId;
    return a.periodIndex - b.periodIndex;
  });

  return {
    ok: true,
    asOfDate,
    periods,
    totalDueAmount: sumDkk(periods.map((p) => p.amount)),
    errors: [],
  };
}

export function computeAccrualSchedule(
  input: ComputeAccrualScheduleInput,
): AccrualSchedulePeriod[] {
  const periods = input.recognitionPeriods;
  if (!Number.isInteger(periods) || periods <= 0) {
    throw new Error("recognitionPeriods must be a positive integer");
  }
  const stepMonths = input.periodStepMonths ?? 1;
  if (!Number.isInteger(stepMonths) || stepMonths <= 0) {
    throw new Error("periodStepMonths must be a positive integer");
  }
  if (!looksLikeIsoDate(input.firstRecognitionDate)) {
    throw new Error("firstRecognitionDate must be YYYY-MM-DD");
  }
  const totalOre = toOre(roundDkk(input.totalAmount));
  if (totalOre <= 0n) throw new Error("totalAmount must be positive");

  const periodsBig = BigInt(periods);
  const baseOre = totalOre / periodsBig;
  const remainderOre = totalOre - baseOre * periodsBig;

  const schedule: AccrualSchedulePeriod[] = [];
  for (let i = 0; i < periods; i += 1) {
    // The remainder is concentrated in the final period so every period before
    // it gets an identical amount and the total reconciles exactly.
    const periodOre = i === periods - 1 ? baseOre + remainderOre : baseOre;
    schedule.push({
      periodIndex: i + 1,
      recognitionDate: addMonthsClamped(input.firstRecognitionDate, i * stepMonths),
      amount: fromOre(periodOre),
    });
  }
  return schedule;
}

export function buildBudgetVsActual(
  db: Database,
  periodStart: BudgetPeriod,
  periodEnd: BudgetPeriod,
): BudgetVsActualReport {
  const errors: string[] = [];
  if (!isValidBudgetPeriod(periodStart)) errors.push("periodStart must be a YYYY-MM calendar month");
  if (!isValidBudgetPeriod(periodEnd)) errors.push("periodEnd must be a YYYY-MM calendar month");
  if (errors.length === 0 && periodStart > periodEnd) {
    errors.push("periodStart must be before or equal to periodEnd");
  }
  if (errors.length > 0) {
    return {
      ok: false,
      appliedRules: [BUDGET_VS_ACTUAL_REPORT_ID],
      periodStart,
      periodEnd,
      lines: [],
      totalBudget: 0,
      totalActual: 0,
      totalVariance: 0,
      errors,
    };
  }

  const rangeStartDate = periodStartDate(periodStart);
  const rangeEndDate = periodEndDate(periodEnd);

  // Per (account, month) actual movement, summed in integer øre. The month is
  // derived from the entry's transaction_date (first 7 chars, YYYY-MM).
  const actualRows = db
    .query(
      `SELECT a.account_no AS account_no,
              a.name       AS account_name,
              a.type       AS account_type,
              substr(je.transaction_date, 1, 7) AS period,
              jl.debit_amount  AS debit_amount,
              jl.credit_amount AS credit_amount
         FROM journal_entries je
         JOIN journal_lines jl ON jl.journal_entry_id = je.id
         JOIN accounts a       ON a.id = jl.account_id
        WHERE je.transaction_date >= ? AND je.transaction_date <= ?
        ORDER BY a.account_no ASC, je.id ASC, jl.id ASC`,
    )
    .all(rangeStartDate, rangeEndDate) as Array<{
    account_no: string;
    account_name: string;
    account_type: string;
    period: string;
    debit_amount: number | null;
    credit_amount: number | null;
  }>;

  type Cell = {
    accountNo: string;
    accountName: string | null;
    accountType: string | null;
    period: string;
    debitOre: bigint;
    creditOre: bigint;
    budgetOre: bigint;
    /** True once a budget line has been attached to this cell. */
    hasBudget: boolean;
  };
  const cells = new Map<string, Cell>();
  const keyOf = (accountNo: string, period: string) => `${accountNo}\u001f${period}`;

  for (const row of actualRows) {
    const key = keyOf(row.account_no, row.period);
    let cell = cells.get(key);
    if (!cell) {
      cell = {
        accountNo: row.account_no,
        accountName: row.account_name,
        accountType: row.account_type,
        period: row.period,
        debitOre: 0n,
        creditOre: 0n,
        budgetOre: 0n,
        hasBudget: false,
      };
      cells.set(key, cell);
    }
    cell.debitOre += toOre(Number(row.debit_amount ?? 0));
    cell.creditOre += toOre(Number(row.credit_amount ?? 0));
  }

  // Effective budget lines whose period falls inside the range.
  const budgetRows = db
    .query(
      `SELECT b.account_no AS account_no,
              a.name       AS account_name,
              a.type       AS account_type,
              b.period     AS period,
              b.amount     AS amount
         FROM budget_lines b
         LEFT JOIN accounts a ON a.account_no = b.account_no
        WHERE b.id IN (
          SELECT MAX(id) FROM budget_lines GROUP BY account_no, period
        )
          AND b.period >= ? AND b.period <= ?`,
    )
    .all(periodStart, periodEnd) as Array<{
    account_no: string;
    account_name: string | null;
    account_type: string | null;
    period: string;
    amount: number;
  }>;

  for (const row of budgetRows) {
    const key = keyOf(row.account_no, row.period);
    let cell = cells.get(key);
    if (!cell) {
      cell = {
        accountNo: row.account_no,
        accountName: row.account_name,
        accountType: row.account_type,
        period: row.period,
        debitOre: 0n,
        creditOre: 0n,
        budgetOre: 0n,
        hasBudget: false,
      };
      cells.set(key, cell);
    } else {
      // An actual-derived cell carries the live account name/type already.
      if (cell.accountName == null) cell.accountName = row.account_name;
      if (cell.accountType == null) cell.accountType = row.account_type;
    }
    cell.budgetOre += toOre(Number(row.amount ?? 0));
    cell.hasBudget = true;
  }

  let totalBudgetOre = 0n;
  let totalActualOre = 0n;
  const lines: BudgetVsActualLine[] = [...cells.values()]
    // A budget is a P&L concept: keep every income/expense account, plus any
    // account that actually carries a budget line — drop balance-sheet cash
    // movement (a credit to the bank account, etc.) that no one budgeted.
    .filter(
      (cell) =>
        cell.hasBudget || cell.accountType === "income" || cell.accountType === "expense",
    )
    .sort((a, b) => {
      if (a.period !== b.period) return a.period < b.period ? -1 : 1;
      return a.accountNo < b.accountNo ? -1 : a.accountNo > b.accountNo ? 1 : 0;
    })
    .map((cell) => {
      // Expense accounts are debit-normal; everything else surfaces credit-net.
      const isExpense = cell.accountType === "expense";
      const actualOre = isExpense
        ? cell.debitOre - cell.creditOre
        : cell.creditOre - cell.debitOre;
      const varianceOre = isExpense
        ? cell.budgetOre - actualOre
        : actualOre - cell.budgetOre;
      totalBudgetOre += cell.budgetOre;
      totalActualOre += actualOre;
      return {
        accountNo: cell.accountNo,
        accountName: cell.accountName,
        accountType: cell.accountType,
        period: cell.period,
        budget: fromOre(cell.budgetOre),
        actual: fromOre(actualOre),
        variance: fromOre(varianceOre),
      };
    });

  return {
    ok: true,
    appliedRules: [BUDGET_VS_ACTUAL_REPORT_ID],
    periodStart,
    periodEnd,
    lines,
    totalBudget: fromOre(totalBudgetOre),
    totalActual: fromOre(totalActualOre),
    totalVariance: fromOre(totalActualOre - totalBudgetOre),
    errors: [],
  };
}

export function isValidBudgetPeriod(value: unknown): value is BudgetPeriod {
  if (typeof value !== "string") return false;
  const match = /^(\d{4})-(\d{2})$/.exec(value.trim());
  if (!match) return false;
  const month = Number(match[2]);
  return month >= 1 && month <= 12;
}

export function periodStartDate(period: BudgetPeriod): string {
  return `${period}-01`;
}

export function periodEndDate(period: BudgetPeriod): string {
  const year = Number(period.slice(0, 4));
  const month = Number(period.slice(5, 7));
  const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
  return `${period}-${String(lastDay).padStart(2, "0")}`;
}

export function buildLiquidityForecast(
  db: Database,
  input: LiquidityForecastInput,
): LiquidityForecastResult {
  const errors: string[] = [];
  if (!isValidIsoDate(input.startDate)) {
    errors.push("startDate must be a YYYY-MM-DD date");
  }
  const months = Number(input.months);
  if (!Number.isInteger(months) || months <= 0) {
    errors.push("months must be a positive integer");
  } else if (months > MAX_FORECAST_MONTHS) {
    errors.push(`months must not exceed ${MAX_FORECAST_MONTHS}`);
  }
  if (errors.length > 0) {
    return {
      ok: false,
      appliedRules: [LIQUIDITY_FORECAST_REPORT_ID],
      openingBalance: 0,
      closingBalance: 0,
      periods: [],
      errors,
    };
  }

  const startDate = input.startDate.trim();
  // The first forecast month is the calendar month containing startDate.
  const firstPeriod: BudgetPeriod = startDate.slice(0, 7);
  // Defensive: a YYYY-MM-DD start always yields a valid YYYY-MM month.
  if (!isValidBudgetPeriod(firstPeriod)) {
    return {
      ok: false,
      appliedRules: [LIQUIDITY_FORECAST_REPORT_ID],
      openingBalance: 0,
      closingBalance: 0,
      periods: [],
      errors: ["startDate does not resolve to a valid calendar month"],
    };
  }

  // Enumerate the consecutive YYYY-MM periods to project.
  const periods: BudgetPeriod[] = [];
  let cursor = firstPeriod;
  for (let i = 0; i < months; i += 1) {
    periods.push(cursor);
    cursor = nextPeriod(cursor);
  }
  const lastPeriod = periods[periods.length - 1]!;
  const windowStart = periodStartDate(firstPeriod);
  const windowEnd = periodEndDate(lastPeriod);

  // Opening balance: the booked bank balance the day before the window opens,
  // so a posting dated on the window start counts as a forecast-period event,
  // not as part of the baseline.
  const openingBalanceOre = toOre(bookedBankBalance(db, addDays(windowStart, -1)));

  const invoiceInflow = invoiceInflowByPeriod(db, windowStart, windowEnd);
  const recurringInflow = recurringInflowByPeriod(db, windowStart, windowEnd);
  const budgetedCost = budgetedCostByPeriod(db, firstPeriod, lastPeriod);

  const out: LiquidityForecastPeriod[] = [];
  let runningOre = openingBalanceOre;
  for (const period of periods) {
    const inflowOre = invoiceInflow.get(period) ?? 0n;
    const recurringOre = recurringInflow.get(period) ?? 0n;
    const costOre = budgetedCost.get(period) ?? 0n;
    const netOre = inflowOre + recurringOre - costOre;
    const openingOre = runningOre;
    const closingOre = openingOre + netOre;
    runningOre = closingOre;
    out.push({
      period,
      openingBalance: fromOre(openingOre),
      invoiceInflow: fromOre(inflowOre),
      recurringInflow: fromOre(recurringOre),
      budgetedCostOutflow: fromOre(costOre),
      netChange: fromOre(netOre),
      closingBalance: fromOre(closingOre),
    });
  }

  return {
    ok: true,
    appliedRules: [LIQUIDITY_FORECAST_REPORT_ID],
    startDate,
    months,
    openingBalance: fromOre(openingBalanceOre),
    closingBalance: fromOre(runningOre),
    periods: out,
    errors: [],
  };
}

export function nextPeriod(period: BudgetPeriod): BudgetPeriod {
  const year = Number(period.slice(0, 4));
  const month = Number(period.slice(5, 7));
  const total = year * 12 + (month - 1) + 1;
  const ny = Math.floor(total / 12);
  const nm = total - ny * 12 + 1;
  return `${ny}-${String(nm).padStart(2, "0")}`;
}

function bookedBankBalance(db: Database, asOfDate: string): number {
  const accountNos = bankAccountNumbers(db);
  if (accountNos.length === 0) return 0;
  const placeholders = accountNos.map(() => "?").join(", ");
  const row = db
    .query(
      `SELECT COALESCE(SUM(jl.debit_amount - jl.credit_amount), 0) AS bal
         FROM journal_entries je
         JOIN journal_lines jl ON jl.journal_entry_id = je.id
         JOIN accounts a       ON a.id = jl.account_id
        WHERE je.status = 'posted'
          AND je.transaction_date <= ?
          AND a.account_no IN (${placeholders})`,
    )
    .get(asOfDate, ...accountNos) as { bal: number };
  return fromOre(toOre(Number(row.bal ?? 0)));
}

export function addDays(isoDate: string, days: number): string {
  const date = new Date(`${isoDate}T00:00:00.000Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

function invoiceInflowByPeriod(
  db: Database,
  windowStart: string,
  windowEnd: string,
): Map<string, bigint> {
  const byPeriod = new Map<string, bigint>();
  // `asOfDate` only affects overdue flags, not the open balance — pass the
  // window start so the list is computed deterministically.
  const list = buildInvoiceList(db, { status: "all", asOfDate: windowStart });
  for (const row of list.rows) {
    if (row.openBalance <= 0) continue;
    const due = row.effectiveDueDate;
    if (!due || due < windowStart || due > windowEnd) continue;
    const period = due.slice(0, 7);
    byPeriod.set(period, (byPeriod.get(period) ?? 0n) + toOre(row.openBalance));
  }
  return byPeriod;
}

function recurringInflowByPeriod(
  db: Database,
  windowStart: string,
  windowEnd: string,
): Map<string, bigint> {
  const byPeriod = new Map<string, bigint>();
  const templates = db
    .query(
      `SELECT id, interval, first_issue_date, payment_terms_days, payload_json
         FROM recurring_invoice_templates
        WHERE active = 1
        ORDER BY id ASC`,
    )
    .all() as RecurringTemplateRow[];

  for (const template of templates) {
    const intervalMonths = INTERVAL_MONTHS[template.interval];
    if (!intervalMonths) continue;
    const payload = JSON.parse(template.payload_json) as {
      totals?: { grossAmount?: number };
    };
    const gross = Number(payload.totals?.grossAmount ?? 0);
    if (!Number.isFinite(gross) || gross <= 0) continue;
    const grossOre = toOre(gross);

    // Walk period indices forward; the due date is monotonically increasing,
    // so once it passes windowEnd we can stop.
    for (let index = 0; index < 1000; index += 1) {
      const issueDate = addMonths(template.first_issue_date, intervalMonths * index);
      const dueDate = addDays(issueDate, template.payment_terms_days);
      if (dueDate > windowEnd) break;
      if (dueDate < windowStart) continue;
      // Skip a period already generated — its real invoice is counted by the
      // invoice inflow, so the template projection must not double-count it.
      const alreadyGenerated = db
        .query(
          `SELECT 1 FROM recurring_invoice_generations
            WHERE template_id = ? AND period_index = ? LIMIT 1`,
        )
        .get(template.id, index);
      if (alreadyGenerated) continue;
      const period = dueDate.slice(0, 7);
      byPeriod.set(period, (byPeriod.get(period) ?? 0n) + grossOre);
    }
  }
  return byPeriod;
}

const INTERVAL_MONTHS: Record<"monthly" | "quarterly" | "yearly", number> = {
  monthly: 1,
  quarterly: 3,
  yearly: 12,
};

function budgetedCostByPeriod(
  db: Database,
  firstPeriod: BudgetPeriod,
  lastPeriod: BudgetPeriod,
): Map<string, bigint> {
  const byPeriod = new Map<string, bigint>();
  const rows = db
    .query(
      `SELECT b.period AS period, b.amount AS amount
         FROM budget_lines b
         JOIN accounts a ON a.account_no = b.account_no
        WHERE b.id IN (
          SELECT MAX(id) FROM budget_lines GROUP BY account_no, period
        )
          AND a.type = 'expense'
          AND b.period >= ? AND b.period <= ?`,
    )
    .all(firstPeriod, lastPeriod) as Array<{ period: string; amount: number }>;
  for (const row of rows) {
    byPeriod.set(
      row.period,
      (byPeriod.get(row.period) ?? 0n) + toOre(Number(row.amount ?? 0)),
    );
  }
  return byPeriod;
}

export function fiscalYearForDate(
  dateText: string,
  startMonth: number,
  strategy: FiscalYearLabelStrategy,
): FiscalYear {
  if (!isValidIsoDate(dateText)) throw new Error(`invalid ISO date: ${dateText}`);
  const year = Number(dateText.slice(0, 4));
  const month = Number(dateText.slice(5, 7));
  const normalizedStartMonth = Number.isInteger(startMonth) && startMonth >= 1 && startMonth <= 12 ? startMonth : 1;
  const startYear = normalizedStartMonth === 1 || month >= normalizedStartMonth ? year : year - 1;
  const endYear = normalizedStartMonth === 1 ? startYear : startYear + 1;
  const displayLabel = strategy === "start-year"
    ? `${startYear}`
    : strategy === "span" && normalizedStartMonth !== 1
      ? `${startYear}/${String(endYear).slice(-2)}`
      : `${endYear}`;

  return {
    startYear,
    endYear,
    start: `${startYear}-${pad2(normalizedStartMonth)}-01`,
    end: normalizedStartMonth === 1
      ? `${endYear}-12-31`
      : lastDayOfMonth(endYear, normalizedStartMonth - 1),
    displayLabel,
    identifierLabel: displayLabel.replaceAll("/", "-"),
  };
}

export function buildTaxReturn(
  db: Database,
  fiscalYearStart: string,
  fiscalYearEnd: string,
): TaxReturn {
  // 1. Date validation up front so a bad date never reaches the annual report
  // or VAT queries.
  if (!looksLikeIsoDate(fiscalYearStart) || !looksLikeIsoDate(fiscalYearEnd)) {
    return failure(fiscalYearStart, fiscalYearEnd, "", [
      "fiscalYearStart and fiscalYearEnd must be YYYY-MM-DD",
    ]);
  }
  if (fiscalYearStart > fiscalYearEnd) {
    return failure(fiscalYearStart, fiscalYearEnd, "", [
      "fiscalYearStart must be before or equal to fiscalYearEnd",
    ]);
  }

  const formRow = db
    .query(`SELECT company_form FROM companies ORDER BY id ASC LIMIT 1`)
    .get() as CompanyFormRow | null;
  const companyForm = formRow?.company_form ?? "";

  // 2. The taxable income rests on a final, locked annual report. Reuse the
  // #177 prerequisites (locked year, registered CVR, balanced books) rather
  // than re-deriving them — a failing annual report fails the tax return.
  const annualReport: AnnualReport = buildAnnualReport(db, fiscalYearStart, fiscalYearEnd);
  if (!annualReport.ok) {
    return failure(fiscalYearStart, fiscalYearEnd, companyForm, [...annualReport.errors]);
  }

  const bookkeptResult = roundDkk(annualReport.aretsResultat);

  // 3. Deterministic skattemæssig regulering: non-deductible representation
  // (ligningsloven § 8, stk. 4 — representation costs are only 25% tax-
  // deductible). postRepresentationPurchase books the net base PLUS the
  // non-deductible 75% of the VAT as the P&L expense (account 3070), so the
  // bookkept representation cost is base + base × 25% × 75%. Of that entire
  // booked cost only 25% is deductible — the remaining 75% is added back:
  //   booked cost     = base + (base × 25% (full VAT) × 75% (non-deductible share))
  //   add-back        = booked cost × 75%.
  const adjustments: TaxAdjustment[] = [];
  const vatReport = buildVatReport(db, fiscalYearStart, fiscalYearEnd);
  if (vatReport.ok && vatReport.representationPurchaseBase > 0) {
    const fullVat = percentOfDkk(vatReport.representationPurchaseBase, 25);
    // Mirror postRepresentationPurchase exactly (TAX-1): the non-deductible VAT
    // booked to the P&L is fullVat − deductibleVat where deductibleVat =
    // round(fullVat × 25%). Computing it the same way (rather than a separately
    // rounded round(fullVat × 75%)) keeps the booked cost — and the add-back
    // derived from it — øre-identical to what actually hit account 3070.
    const deductibleVat = percentOfDkk(fullVat, 25);
    const nonDeductibleVat = subtractDkk(fullVat, deductibleVat);
    const bookedRepresentationCost = addDkk(vatReport.representationPurchaseBase, nonDeductibleVat);
    const nonDeductibleShare = roundDkk(percentOfDkk(bookedRepresentationCost, 75));
    if (nonDeductibleShare > 0) {
      adjustments.push({
        kind: "non_deductible_representation",
        label: "Ikke-fradragsberettiget andel af repraesentation (75%, ligningsloven § 8, stk. 4)",
        amount: nonDeductibleShare,
        explanation:
          "Repraesentationsudgifter er kun 25% skattemaessigt fradragsberettigede " +
          "(ligningsloven § 8, stk. 4). 75% af den bogfoerte repraesentationsomkostning " +
          "(netto-beloeb plus ikke-fradragsberettiget moms) laegges derfor til den " +
          "skattepligtige indkomst.",
      });
    }
  }

  const totalAdjustments = roundDkk(addDkk(...adjustments.map((a) => a.amount)));
  const taxableIncome = roundDkk(addDkk(bookkeptResult, totalAdjustments));

  // 4. Needs-review items — things the slice deliberately does not compute.
  const needsReview: TaxNeedsReview[] = [];

  // 4a. Depreciation difference. Book depreciation is deterministic linear
  // (#124); tax depreciation is saldoafskrivning (declining-balance, up to
  // 25%, the company's choice). The difference cannot be derived from data the
  // system holds — flag it when any book depreciation was posted.
  const assetRegister = buildAssetRegisterReport(db);
  const bookDepreciation = assetRegister.ok
    ? roundDkk(
        assetRegister.assets
          .filter((a) => a.postedPeriods > 0)
          .reduce((sum, a) => sum + a.accumulatedDepreciation, 0),
      )
    : 0;
  if (bookDepreciation > 0) {
    needsReview.push({
      kind: "depreciation_difference",
      label: "Forskel mellem regnskabsmæssige og skattemæssige afskrivninger",
      requiredAction:
        "Opgør de skattemæssige afskrivninger (saldoafskrivning) og reguler for " +
        "forskellen til de regnskabsmæssige (lineære) afskrivninger.",
      bookDepreciation,
    });
  }

  // 4b. Tax loss carry-forward. A loss this year (or fremført underskud from
  // earlier years) is not computed here — the slice only prepares the current
  // year's figures.
  if (taxableIncome < 0) {
    needsReview.push({
      kind: "tax_loss_carry_forward",
      label: "Fremfoert skattemaessigt underskud",
      requiredAction:
        "Aarets skattepligtige indkomst er negativ. Underskuddet fremfoeres til " +
        "modregning i senere aars positive indkomst — afklar fremfoerslen i oplysningsskemaet.",
    });
  }

  // 4c. Company form. This slice handles the micro-ApS case only. Any other
  // form (or an unknown form) is flagged and no corporate tax is computed.
  const isAps = APS_FORMS.has(companyForm.trim().toLowerCase());
  if (!isAps) {
    needsReview.push({
      kind: "company_form_out_of_scope",
      label: "Selskabsform uden for dette slice",
      requiredAction:
        "Dette slice beregner kun selskabsskat (22%) for et anpartsselskab (ApS). " +
        `Den registrerede selskabsform er "${companyForm || "ukendt"}" — ` +
        "afklar den korrekte skatteberegning med revisor.",
    });
  }

  // 5. Corporate tax — 22% of a non-negative taxable income, micro-ApS only.
  const corporateTax = isAps
    ? roundDkk(percentOfDkk(Math.max(0, taxableIncome), CORPORATE_TAX_RATE * 100))
    : null;

  return {
    ok: true,
    appliedRules: [TAX_RETURN_RULE_ID],
    fiscalYearStart,
    fiscalYearEnd,
    companyForm,
    bookkeptResult,
    adjustments,
    totalAdjustments,
    taxableIncome,
    corporateTaxRate: CORPORATE_TAX_RATE,
    corporateTax,
    needsReview,
    acontoTaxDeadlines: acontoTaxDeadlinesForIncomeYear(fiscalYearEnd),
    preparedBy: "Rentemester",
    disclaimer: DISCLAIMER,
    errors: [],
  };
}

const DISCLAIMER =
  "Rentemester forbereder tallene til oplysningsskemaet (selskabets skattepligtige " +
  "indkomst) ud fra det lukkede regnskabsår og de skattemæssige reguleringer " +
  "systemet kan se deterministisk. Ejer eller revisor gennemgår tallene, afklarer " +
  "needs-review-punkterne og indberetter selv via TastSelv Erhverv. Dette er ikke " +
  "en fuldstændig skatteberegning.";

export function buildViesRecapitulativeStatement(
  db: Database,
  periodStart: string,
  periodEnd: string,
): ViesRecapitulativeStatement {
  const errors: string[] = [];
  if (!looksLikeIsoDate(periodStart)) errors.push("periodStart must be YYYY-MM-DD");
  if (!looksLikeIsoDate(periodEnd)) errors.push("periodEnd must be YYYY-MM-DD");
  if (errors.length === 0 && periodStart > periodEnd) {
    errors.push("periodStart must be before or equal to periodEnd");
  }
  if (errors.length > 0) return failure(periodStart, periodEnd, errors);

  // Cross-border B2B sales without Danish VAT are exactly the issued invoices
  // with vatTreatment "foreign_reverse_charge". The treatment lives in
  // payload_json; filtering happens in JS so a missing/odd payload cannot make
  // an invoice silently disappear.
  const rows = db.query(
    `SELECT invoice_no, invoice_date, recipient_name, recipient_vat_cvr,
            amount_inc_vat, vat_amount, currency, payload_json
       FROM documents
      WHERE document_type = 'issued_invoice'
        AND invoice_date >= ? AND invoice_date <= ?
      ORDER BY invoice_date ASC, id ASC`,
  ).all(periodStart, periodEnd) as IssuedInvoiceRow[];

  const warnings: string[] = [];
  const byCustomer = new Map<string, ViesRecapitulativeCustomer>();
  let invoiceCount = 0;
  let totalValue = 0;

  for (const row of rows) {
    const payload = row.payload_json ? safeParse(row.payload_json) : null;
    if (payload?.vatTreatment !== "foreign_reverse_charge") continue;

    const parsedVat = normalizeEuVatNumber(row.recipient_vat_cvr);
    if (!parsedVat) {
      warnings.push(
        `invoice ${row.invoice_no} is a foreign reverse-charge sale but has no parseable EU VAT number — excluded from the EU sales list`,
      );
      continue;
    }
    if (parsedVat.countryCode === "DK") {
      warnings.push(
        `invoice ${row.invoice_no} is marked foreign reverse-charge but the buyer VAT number is Danish — excluded from the EU sales list`,
      );
      continue;
    }

    const { value, warning } = invoiceNetValueDkk(row);
    if (warning) warnings.push(warning);

    invoiceCount += 1;
    totalValue = addDkk(totalValue, value);

    const existing = byCustomer.get(parsedVat.normalized);
    if (existing) {
      existing.invoiceCount += 1;
      existing.totalValue = addDkk(existing.totalValue, value);
      existing.invoiceNumbers.push(row.invoice_no);
      // The latest invoice's recipient name wins (rows are issue-date sorted).
      if (row.recipient_name) existing.customerName = row.recipient_name;
    } else {
      byCustomer.set(parsedVat.normalized, {
        vatNumber: parsedVat.normalized,
        countryCode: parsedVat.countryCode,
        customerName: row.recipient_name,
        invoiceCount: 1,
        totalValue: value,
        invoiceNumbers: [row.invoice_no],
      });
    }
  }

  const customers = [...byCustomer.values()].sort((a, b) =>
    a.vatNumber < b.vatNumber ? -1 : a.vatNumber > b.vatNumber ? 1 : 0,
  );

  return {
    ok: true,
    appliedRules: [EU_SALES_LIST_RULE_ID],
    periodStart,
    periodEnd,
    customers,
    totalValue: roundDkk(totalValue),
    invoiceCount,
    warnings,
    errors: [],
  };
}

export function buildOssReport(db: Database, periodStart: string, periodEnd: string): OssReport {
  const vatReport = buildVatReport(db, periodStart, periodEnd);
  if (!vatReport.ok) {
    return {
      ok: false,
      appliedRules: [OSS_RULE_ID],
      periodStart,
      periodEnd,
      ossConsumerSalesBase: 0,
      entryCount: 0,
      submission: false,
      vatReport,
      warnings: [],
      errors: [...vatReport.errors],
    };
  }

  const warnings: string[] = [...vatReport.warnings];
  if (vatReport.ossConsumerSalesBase > 0) {
    warnings.push(
      "OSS first slice: this report shows the total OSS consumer-sales base only. " +
        "It does not split the base per destination member state or per rate, and it does not " +
        "file an OSS return — that remains your responsibility.",
    );
  }

  return {
    ok: true,
    appliedRules: [OSS_RULE_ID],
    periodStart,
    periodEnd,
    ossConsumerSalesBase: vatReport.ossConsumerSalesBase,
    entryCount: vatReport.ossConsumerSalesEntryCount,
    submission: false,
    vatReport,
    warnings,
    errors: [],
  };
}

export function currentRuleBundleVersion() {
  return readRuleBundleMetadata()
    .map((bundle) => `${bundle.name}=${bundle.version}`)
    .join(";");
}

export function readRuleBundleMetadata(): RuleBundleMetadata[] {
  return readdirSync(rulesDir)
    .filter((file) => file.endsWith(".yaml"))
    .sort()
    .map((file) => {
      const path = join(rulesDir, file);
      const text = readFileSync(path, "utf8");
      return {
        name: file.replace(/\.yaml$/, ""),
        path,
        version: extractVersion(text, file),
        ruleIds: [...text.matchAll(/^\s*-\s*rule_id:\s*(\S+)$/gm)].map((match) => match[1]),
        sourceIds: [...text.matchAll(/^\s*source_id:\s*(\S+)$/gm)].map((match) => match[1]),
        declaredSources: extractSectionValues(text, "sources", /^\s*-\s*(DK-[A-Z0-9-]+)$/),
        vatCodes: extractSectionValues(text, "vat_codes", /^\s*-\s*code:\s*(\S+)$/),
      };
    });
}

export function renderDashboard(input: DashboardInput, _options: RenderOptions = {}): string {
  const company = input.company;
  const title = `Rentemester — ${company.name} — ${input.asOfDate}`;

  const sections = [
    header(input),
    metricsSection(input),
    `<section class="section"><h2>Åbne exceptions</h2>${exceptionsSection(input)}</section>`,
    `<section class="section"><h2>Næste deadline</h2>${deadlineSection(input)}</section>`,
    `<section class="section"><h2>Åbne fakturaer</h2>${invoiceTable(input.invoices)}</section>`,
  ];

  // Creditor card — symmetric to the open-invoices (debitor) view above.
  if (input.payables) {
    sections.push(
      `<section class="section"><h2>Åbne kreditorposter</h2>${payablesSection(input.payables)}</section>`,
    );
  }
  // Accruals — open balance-sheet exposure + due recognition periods.
  if (input.accrualRegister || input.accrualsDue) {
    sections.push(
      `<section class="section"><h2>Periodeafgrænsningsposter</h2>${accrualsSection(input.accrualRegister, input.accrualsDue)}</section>`,
    );
  }
  // Budget & liquidity — budget-vs-actual + the forward forecast.
  if (input.budgetVsActual || input.liquidity) {
    sections.push(
      `<section class="section"><h2>Budget &amp; likviditet</h2>${budgetLiquiditySection(input.budgetVsActual, input.liquidity)}</section>`,
    );
  }
  // Tax — estimated selskabsskat, or the "awaiting year-end" state.
  if (input.tax) {
    sections.push(
      `<section class="section"><h2>Skat</h2>${taxSection(input.tax)}</section>`,
    );
  }
  // EU sales / OSS — a light indicator: only surfaced when there is activity
  // that needs a separate filing.
  if (hasEuSalesOssActivity(input.euSalesOss)) {
    sections.push(
      `<section class="section"><h2>EU-salg &amp; OSS</h2>${euSalesOssSection(input.euSalesOss!)}</section>`,
    );
  }

  sections.push(
    `<section class="section"><h2>Seneste aktivitet</h2>${activityList(input.recentActivity)}</section>`,
    statusSection(input),
    footer(input),
  );

  const rendered = sections.join("\n");

  return `<!DOCTYPE html>
<html lang="da">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
${fontLink()}
<style>
${buildStyle()}
</style>
</head>
<body>
<main class="page">
${rendered}
</main>
</body>
</html>
`;
}

export function header(input: DashboardInput): string {
  const company = input.company;
  const dateLong = formatDateLong(input.asOfDate);
  const backupDays = input.backup.daysSinceLatestBackup;
  const backupLabel = input.backup.backupsFound === 0
    ? "Backup: ingen registreret"
    : `Backup: ${daysAgoLabel(backupDays)}`;
  const cvrLine = company.cvr
    ? `<div class="cvr">CVR ${escapeHtml(company.cvr)}</div>`
    : "";
  return `<header class="header">
  <div>
    <h1>${escapeHtml(company.name)}</h1>
    <div class="meta">Dashboard · ${escapeHtml(dateLong)} · ${escapeHtml(backupLabel)}</div>
  </div>
  ${cvrLine}
</header>`;
}

export function metricsSection(input: DashboardInput): string {
  const openSum = input.invoices.rows.reduce((acc, r) => acc + r.openBalance, 0);
  const overdueOldest = input.overdueInvoices.rows.reduce((acc, r) => Math.max(acc, r.overdueDays), 0);
  return `<section class="metrics">
${metricCard("ÅBNE FAKTURAER", String(input.invoices.count), `${formatDkk(openSum)}`, null)}
${metricCard("OVERFORFALDNE", String(input.overdueInvoices.count), input.overdueInvoices.count > 0 ? `ældste ${overdueOldest} d` : "0 dage", input.overdueInvoices.count > 0 ? "accent" : null)}
${metricCard("BANKPOSTER UDEN BILAG", String(input.unlinkedBank.count), undefined, null)}
${metricCard("ÅBNE EXCEPTIONS", String(input.exceptions.count), undefined, input.exceptions.count > 0 ? "danger" : null)}
</section>`;
}

export function exceptionsSection(input: DashboardInput): string {
  const result = input.exceptions;
  if (result.count === 0 || result.rows.length === 0) {
    return `<div class="empty-state">Ingen åbne exceptions</div>`;
  }
  // Stable order: highest severity first, then by id so the render is
  // deterministic regardless of the row order the CLI passes in.
  const severityRank: Record<string, number> = { critical: 0, high: 1, medium: 2, low: 3 };
  const sorted = [...result.rows].sort((a, b) => {
    const ra = severityRank[a.severity] ?? 9;
    const rb = severityRank[b.severity] ?? 9;
    if (ra !== rb) return ra - rb;
    return a.id - b.id;
  });
  const maxRows = 12;
  const visible = sorted.slice(0, maxRows);
  const overflow = sorted.length - visible.length;
  const items = visible.map((row) => {
    const pillClass = EXCEPTION_SEVERITY_PILL[row.severity] ?? "neutral";
    // The full message — not a mid-sentence-truncated fragment. The Cockpit
    // SPA shows the whole message; the static dashboard must too. (#270)
    const action = (row.requiredAction ?? "").trim();
    const actionHtml = action
      ? `\n      <div class="detail"><strong>Sådan løser du den:</strong> ${escapeHtml(action)}</div>`
      : "";
    return `  <div class="status-row">
    <div>
      <div class="label">${escapeHtml(exceptionTypeDa(row.type))}</div>
      <div class="detail">${escapeHtml(row.message)}</div>${actionHtml}
    </div>
    <div><span class="pill ${pillClass}">${escapeHtml(severityDa(row.severity, "title"))}</span></div>
  </div>`;
  }).join("\n");
  const overflowRow = overflow > 0
    ? `<div class="muted" style="margin-top: var(--space-xs); font-size: 13px;">… og ${overflow} yderligere</div>`
    : "";
  return `<div class="section">
${items}
</div>
${overflowRow}`;
}

const EXCEPTION_SEVERITY_PILL: Record<string, "danger" | "warning" | "neutral"> = {
  high: "danger",
  critical: "danger",
  medium: "warning",
  low: "neutral",
};

export function deadlineSection(input: DashboardInput): string {
  // The "Næste momsfrist" box must describe the VAT period the CLI selected —
  // the earliest unreported period that carries activity — NOT the calendar
  // period today falls in. The CLI delivers that period as `vatPeriod`; the
  // render-engine keys the label/deadline off `vatPeriod.periodStart` so the
  // box always agrees with the figure shown beside it. (#281)
  //
  // #299: the period window + label + filing deadline follow the company's
  // real VAT cadence (`vatPeriodType`) — a half-yearly filer sees "1. halvår
  // 2026" with the half-year deadline, not a quarter. For a `quarter` company
  // the window/label/deadline are byte-identical to the historical behaviour.
  // When the company is not VAT-registered the card explains so instead of
  // inventing a period from a non-existent cadence.
  if (input.company.vatPeriodType === null) {
    return `<div class="deadline-card">
  <div>
    <div class="label-sm">Næste momsfrist</div>
    <div class="headline" style="font-size: 18px;">Ikke momsregistreret</div>
    <div class="muted" style="font-size: 13px; margin-top: var(--space-xxs);"><span class="pill success">Ingen pligt</span> Selskabet er ikke momsregistreret — ingen momsangivelse eller frist.</div>
  </div>
  <div style="text-align: right;">
    <div class="label-sm">Est. nettomoms</div>
    <div class="amount-lg">—</div>
  </div>
</div>`;
  }
  const vatType: VatPeriodType = input.company.vatPeriodType;
  const validStart = /^(\d{4})-(\d{2})-(\d{2})/.test(input.vatPeriod.periodStart);
  const window = validStart
    ? vatPeriodWindowFor(input.vatPeriod.periodStart, vatType)
    : null;
  const period = {
    label: window ? vatPeriodLabel(window) : "—",
  };
  // The countdown targets the canonical SKAT filing/payment deadline for the
  // company's actual cadence (including monthly special dates and bank days).
  const deadline = window ? window.filingDeadline : null;
  const daysRemaining = deadline ? signedDaysBetween(input.asOfDate, deadline) : 0;
  const errors = input.vatPeriod.errors ?? [];
  let pill: string;
  let detail: string;
  if (errors.length > 0) {
    pill = `<span class="pill warning">Kan ikke beregne</span>`;
    detail = truncate(errors[0]!, 80);
  } else if (!deadline) {
    pill = `<span class="pill warning">Kan ikke beregne</span>`;
    detail = "";
  } else if (daysRemaining < 0) {
    pill = `<span class="pill danger">Forfalden</span>`;
    detail = `${Math.abs(daysRemaining)} dage over`;
  } else if (daysRemaining <= 14) {
    pill = `<span class="pill warning">${daysRemaining} dage tilbage</span>`;
    detail = "";
  } else {
    pill = `<span class="pill success">${daysRemaining} dage tilbage</span>`;
    detail = "";
  }
  const deadlineLine = deadline
    ? `<div class="muted" style="font-size: 13px; margin-top: var(--space-xxs);">SKAT-frist: <span class="mono">${escapeHtml(deadline)}</span></div>`
    : "";
  const net = input.vatPeriod.netVatPayable;
  const netLabel = net < 0 ? "Til gode" : "Est. nettomoms";
  const netValue = formatDkk(net);
  return `<div class="deadline-card">
  <div>
    <div class="label-sm">Næste momsfrist</div>
    <div class="headline" style="font-size: 18px;">${escapeHtml(period.label)}</div>
    ${deadlineLine}
    <div class="muted" style="font-size: 13px; margin-top: var(--space-xxs);">${pill} ${escapeHtml(detail)}</div>
  </div>
  <div style="text-align: right;">
    <div class="label-sm">${escapeHtml(netLabel)}</div>
    <div class="amount-lg">${escapeHtml(netValue)}</div>
  </div>
</div>`;
}

export function invoiceTable(result: InvoiceListResult, maxRows = 10): string {
  if (result.rows.length === 0) {
    return `<div class="empty-state">Ingen åbne fakturaer</div>`;
  }
  const sorted = [...result.rows].sort((a, b) => {
    const ad = a.effectiveDueDate ?? "9999-99-99";
    const bd = b.effectiveDueDate ?? "9999-99-99";
    if (ad < bd) return -1;
    if (ad > bd) return 1;
    return a.invoiceNumber.localeCompare(b.invoiceNumber);
  });
  const visible = sorted.slice(0, maxRows);
  const overflow = sorted.length - visible.length;
  const rows = visible.map((row) => {
    const customer = row.customerName ?? row.customerCvr ?? "—";
    return `<tr>
  <td class="mono">${escapeHtml(row.invoiceNumber)}</td>
  <td>${escapeHtml(customer)}</td>
  <td class="amount">${escapeHtml(formatDkk(row.openBalance))}</td>
  <td class="amount mono">${escapeHtml(formatDateShort(row.effectiveDueDate))}</td>
  <td class="center">${invoiceStatusPill(row)}</td>
</tr>`;
  }).join("\n");
  const overflowRow = overflow > 0
    ? `<div class="muted" style="margin-top: var(--space-xs); font-size: 13px;">… og ${overflow} yderligere</div>`
    : "";
  return `<table class="dash-table">
  <thead>
    <tr>
      <th>Fakturanr.</th>
      <th>Kunde</th>
      <th class="amount">Beløb</th>
      <th class="amount">Forfald</th>
      <th class="center">Status</th>
    </tr>
  </thead>
  <tbody>
${rows}
  </tbody>
</table>
${overflowRow}`;
}

export function payablesSection(payables: PayablesListResult): string {
  if (payables.count === 0 || payables.rows.length === 0) {
    return `<div class="empty-state">Ingen åbne kreditorposter</div>`;
  }
  const maxRows = 10;
  // buildPayablesList already sorts most-overdue first.
  const visible = payables.rows.slice(0, maxRows);
  const overflow = payables.rows.length - visible.length;
  const rows = visible.map((row) => {
    const supplier = row.supplierName ?? "—";
    const pill = row.isOverdue
      ? `<span class="pill danger">forfalden${row.overdueDays > 0 ? ` (${row.overdueDays} d)` : ""}</span>`
      : `<span class="pill success">åben</span>`;
    return `<tr>
  <td class="mono">${escapeHtml(row.billNo ?? `#${row.payableId}`)}</td>
  <td>${escapeHtml(supplier)}</td>
  <td class="amount">${escapeHtml(formatDkk(row.openBalance))}</td>
  <td class="amount mono">${escapeHtml(formatDateShort(row.dueDate))}</td>
  <td class="center">${pill}</td>
</tr>`;
  }).join("\n");
  const overflowRow = overflow > 0
    ? `<div class="muted" style="margin-top: var(--space-xs); font-size: 13px;">… og ${overflow} yderligere</div>`
    : "";
  const summary =
    `<div class="muted" style="margin-bottom: var(--space-sm); font-size: 13px;">` +
    `Åben kreditorgæld i alt <span class="mono">${escapeHtml(formatDkk(payables.totalOpenBalance))}</span>` +
    (payables.overdueOpenBalance > 0
      ? ` · heraf overforfalden <span class="mono">${escapeHtml(formatDkk(payables.overdueOpenBalance))}</span>`
      : "") +
    `</div>`;
  return `${summary}<table class="dash-table">
  <thead>
    <tr>
      <th>Bilagsnr.</th>
      <th>Leverandør</th>
      <th class="amount">Åben saldo</th>
      <th class="amount">Forfald</th>
      <th class="center">Status</th>
    </tr>
  </thead>
  <tbody>
${rows}
  </tbody>
</table>
${overflowRow}`;
}

export function accrualsSection(
  register: AccrualRegisterReport | undefined,
  due: DueAccrualRecognitionResult | undefined,
): string {
  const remainingExposure = register?.totals.remainingAmount ?? 0;
  const accruals = register?.accruals ?? [];
  if (accruals.length === 0) {
    return `<div class="empty-state">Ingen periodeafgrænsningsposter</div>`;
  }
  // "Aktive" = not fully recognised — a fully-recognised accrual no longer
  // carries balance-sheet exposure, so counting it would overstate the card.
  const activeCount = accruals.filter((a) => !a.fullyRecognized).length;
  const dueCount = due?.periods.length ?? 0;
  const dueAmount = due?.totalDueAmount ?? 0;
  const duePill = dueCount > 0
    ? `<span class="pill danger">${dueCount} forfalden${dueCount === 1 ? "" : "e"}</span>`
    : `<span class="pill success">✔ ingen forfaldne</span>`;
  return `<div class="status-row">
    <div>
      <div class="label">Resterende balanceeksponering</div>
      <div class="detail">${activeCount} aktiv${activeCount === 1 ? "" : "e"} periodeafgrænsningsposter</div>
    </div>
    <div class="amount-lg">${escapeHtml(formatDkk(remainingExposure))}</div>
  </div>
  <div class="status-row">
    <div>
      <div class="label">Recognition-perioder der skal bogføres</div>
      <div class="detail">${dueCount > 0 ? `${escapeHtml(formatDkk(dueAmount))} skal indtægts-/omkostningsføres` : "alle forfaldne perioder er bogført"}</div>
    </div>
    <div>${duePill}</div>
  </div>`;
}

export function budgetLiquiditySection(
  budget: BudgetVsActualReport | undefined,
  liquidity: LiquidityForecastResult | undefined,
): string {
  const parts: string[] = [];

  const hasBudget = budget && budget.ok && budget.lines.length > 0;
  if (hasBudget) {
    // The raw `totalVariance` (= totalActual − totalBudget) is NOT a
    // favourability signal — its sign depends on the account mix, so an
    // over-budget expense month yields a POSITIVE total. The per-line
    // `BudgetVsActualLine.variance` already encodes "positive = favourable"
    // for every account type (expense: budget − actual; income/other: actual
    // − budget). Their sum is therefore the correct favourability figure.
    const favourability = budget!.lines.reduce((sum, line) => sum + line.variance, 0);
    const pill = favourability >= 0
      ? `<span class="pill success">budget overholdt</span>`
      : `<span class="pill warning">budgetafvigelse</span>`;
    parts.push(`<div class="status-row">
    <div>
      <div class="label">Budget vs. faktisk · ${escapeHtml(budget!.periodStart)}</div>
      <div class="detail">budget <span class="mono">${escapeHtml(formatDkk(budget!.totalBudget))}</span> · faktisk <span class="mono">${escapeHtml(formatDkk(budget!.totalActual))}</span></div>
    </div>
    <div>${pill} <span class="muted">${escapeHtml(formatDkk(favourability))}</span></div>
  </div>`);
  } else {
    parts.push(`<div class="status-row">
    <div>
      <div class="label">Budget vs. faktisk</div>
      <div class="detail">Intet budget sat for perioden</div>
    </div>
    <div><span class="pill neutral">—</span></div>
  </div>`);
  }

  const hasForecast = liquidity && liquidity.ok && liquidity.periods.length > 0;
  if (hasForecast) {
    const final = liquidity!.periods[liquidity!.periods.length - 1]!;
    const lowest = liquidity!.periods.reduce(
      (min, p) => (p.closingBalance < min ? p.closingBalance : min),
      liquidity!.periods[0]!.closingBalance,
    );
    // A projected balance dipping below zero is the one thing the owner must
    // see — surface it as a danger pill.
    const pill = lowest < 0
      ? `<span class="pill danger">negativ likviditet</span>`
      : `<span class="pill success">positiv</span>`;
    parts.push(`<div class="status-row">
    <div>
      <div class="label">Likviditetsprognose · ${liquidity!.periods.length} måneder</div>
      <div class="detail">projiceret saldo ${escapeHtml(final.period)} <span class="mono">${escapeHtml(formatDkk(final.closingBalance))}</span>${lowest < 0 ? ` · laveste <span class="mono">${escapeHtml(formatDkk(lowest))}</span>` : ""}</div>
    </div>
    <div>${pill}</div>
  </div>`);
  } else {
    parts.push(`<div class="status-row">
    <div>
      <div class="label">Likviditetsprognose</div>
      <div class="detail">Ingen prognosedata</div>
    </div>
    <div><span class="pill neutral">—</span></div>
  </div>`);
  }

  return parts.join("\n");
}

export function taxSection(tax: DashboardTaxStatus): string {
  if (!tax.available) {
    return `<div class="status-row">
    <div>
      <div class="label">Selskabsskat · regnskabsår ${escapeHtml(tax.fiscalYearLabel)}</div>
      <div class="detail">Forberedelse er klar, når regnskabsåret er lukket</div>
    </div>
    <div><span class="pill neutral">afventer årsafslutning</span></div>
  </div>`;
  }
  const corporateTax = tax.corporateTax ?? null;
  const taxValue = corporateTax == null ? "—" : formatDkk(corporateTax);
  const reviewCount = tax.needsReviewCount ?? 0;
  const reviewPill = reviewCount > 0
    ? `<span class="pill warning">${reviewCount} til gennemgang</span>`
    : `<span class="pill success">✔ ingen åbne punkter</span>`;
  return `<div class="status-row">
    <div>
      <div class="label">Estimeret selskabsskat · regnskabsår ${escapeHtml(tax.fiscalYearLabel)}</div>
      <div class="detail">årets resultat <span class="mono">${escapeHtml(formatDkk(tax.bookkeptResult ?? 0))}</span></div>
    </div>
    <div class="amount-lg">${escapeHtml(taxValue)}</div>
  </div>
  <div class="status-row">
    <div>
      <div class="label">Needs-review</div>
      <div class="detail">${reviewCount > 0 ? "poster Rentemester ikke beregner deterministisk" : "oplysningsskemaet kan forberedes"}</div>
    </div>
    <div>${reviewPill}</div>
  </div>`;
}

export function hasEuSalesOssActivity(status: DashboardEuSalesOssStatus | undefined): boolean {
  if (!status) return false;
  return (
    status.euSalesValue > 0 ||
    status.euCustomerCount > 0 ||
    status.ossConsumerSalesBase > 0
  );
}

export function euSalesOssSection(status: DashboardEuSalesOssStatus): string {
  const rows: string[] = [];
  if (status.euSalesValue > 0 || status.euCustomerCount > 0) {
    rows.push(`<div class="status-row">
    <div>
      <div class="label">EU-salg uden moms (VIES)</div>
      <div class="detail">${status.euCustomerCount} EU-kunde${status.euCustomerCount === 1 ? "" : "r"} — separat liste til SKAT</div>
    </div>
    <div class="amount-lg">${escapeHtml(formatDkk(status.euSalesValue))}</div>
  </div>`);
  }
  if (status.ossConsumerSalesBase > 0) {
    rows.push(`<div class="status-row">
    <div>
      <div class="label">OSS — salg til EU-forbrugere</div>
      <div class="detail">grundlag for separat OSS-angivelse</div>
    </div>
    <div class="amount-lg">${escapeHtml(formatDkk(status.ossConsumerSalesBase))}</div>
  </div>`);
  }
  return rows.join("\n");
}

export function activityList(rows: AuditLogRow[]): string {
  if (rows.length === 0) {
    return `<div class="empty-state">Ingen aktivitet endnu</div>`;
  }
  const items = rows.slice(0, 10).map((row) =>
    `  <div class="time">${escapeHtml(formatTimestampShort(row.createdAt))}</div>
  <div class="actor">${escapeHtml(row.actor)}</div>
  <div class="event">${escapeHtml(activityEventLabel(row.eventType))}</div>
  <div class="message">${escapeHtml(activityMessageDanish(row.message))}</div>`
  ).join("\n");
  return `<div class="activity-log">
${items}
</div>`;
}

export function footer(input: DashboardInput): string {
  const generated = formatTimestampShort(input.generatedAt);
  // The footer faces the owner, not a developer. The raw commit hash and the
  // long rule-bundle-version string are build provenance — kept for support
  // traceability but tucked into a small <details>, never dumped on the calm
  // cockpit surface. The visible line is just "genereret <tid>". (#246)
  const provenance =
    `<details class="provenance"><summary>Teknisk version</summary>` +
    `<span class="mono">commit ${escapeHtml(input.commitSha)}</span> · ` +
    `<span class="mono">regelsæt ${escapeHtml(input.ruleBundleVersion)}</span></details>`;
  return `<footer class="footer">
  <div class="row">
    <div>Genereret <span class="mono">${escapeHtml(generated)}</span> · Rentemester</div>
    <div class="mono">github.com/mikkelkrogsholm/rentemester</div>
  </div>
  ${provenance}
</footer>`;
}

export function escapeHtml(value: string | number | null | undefined): string {
  if (value == null) return "";
  const str = String(value);
  let out = "";
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    switch (ch) {
      case 38: out += "&amp;"; break;
      case 60: out += "&lt;"; break;
      case 62: out += "&gt;"; break;
      case 34: out += "&quot;"; break;
      case 39: out += "&#39;"; break;
      default: out += str[i];
    }
  }
  return out;
}

export function fontLink(): string {
  // Single deterministic Google Fonts URL. HTML still renders if blocked.
  const families = [
    "family=Source+Serif+4:wght@400;600",
    "family=IBM+Plex+Sans:wght@400;500",
    "family=IBM+Plex+Mono:wght@400;500",
  ].join("&");
  return `<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link rel="stylesheet" href="https://fonts.googleapis.com/css2?${families}&display=swap">`;
}

