export async function runWorkspaceRecurringInvoices(workspaceRoot: string, options: WorkspaceRecurringRunOptions): Promise<WorkspaceRecurringRunResult> {
  const selected = targets(workspaceRoot);
  const companies: WorkspaceRecurringCompanyResult[] = [...selected.skipped];
  for (const target of selected.active) {
    // A bad policy/backup state is confined to this company; the next
    // manifest target still runs. No database is opened read-write first.
    if (!preflightTarget(target, options.actor.createdBy ?? "")) {
      companies.push({ slug: target.slug, status: "failed", reason: "run failed" });
      continue;
    }
    const db = openDb(companyPaths(target.root).db);
    try {
      migrate(db);
      const result = options.runCompany
        ? await options.runCompany({ db, companyRoot: target.root, slug: target.slug })
        : await runRecurringInvoices(db, {
            companyRoot: target.root,
            asOfDate: options.asOfDate,
            adapter: options.adapterForCompany
              ? options.adapterForCompany({ db, companyRoot: target.root, slug: target.slug })
              : resolveRecurringDeliveryAdapter(db, target.root),
            createdBy: options.actor.createdBy ?? undefined,
            createdByProgram: options.actor.createdByProgram ?? undefined,
            maxGenerations: options.maxGenerations,
          });
      companies.push(result.ok
        ? { slug: target.slug, status: "processed", generated: result.generated, attempted: result.attempted, hasMore: result.hasMore ?? false, remainingGenerations: result.remainingGenerations ?? 0, ...(result.continuation ? { continuation: result.continuation } : {}) }
        : { slug: target.slug, status: "failed", reason: "run failed", generated: result.generated, attempted: result.attempted, hasMore: result.hasMore ?? false, remainingGenerations: result.remainingGenerations ?? 0, ...(result.continuation ? { continuation: result.continuation } : {}) });
    } catch { companies.push({ slug: target.slug, status: "failed", reason: "run failed" }); }
    finally { db.close(); }
  }
  const failed = companies.filter((company) => company.status === "failed");
  const continuations = companies
    .filter((company) => company.hasMore && (company.remainingGenerations ?? 0) > 0)
    .map((company) => ({ slug: company.slug, remainingGenerations: company.remainingGenerations! }));
  const remainingGenerations = continuations.reduce((sum, company) => sum + company.remainingGenerations, 0);
  return {
    ok: failed.length === 0,
    companies,
    errors: failed.map((company) => `recurring run failed for company ${company.slug}`),
    hasMore: remainingGenerations > 0,
    remainingGenerations,
    ...(remainingGenerations > 0 ? { continuation: { remainingGenerations, companies: continuations } } : {}),
  };
}

function targets(workspaceRoot: string): { active: Target[]; skipped: WorkspaceRecurringCompanyResult[] } {
  const active: Target[] = [];
  const skipped: WorkspaceRecurringCompanyResult[] = [];
  for (const entry of [...listWorkspaceCompanies(workspaceRoot)].sort((a, b) => a.slug.localeCompare(b.slug))) {
    if (entry.archived) { skipped.push({ slug: entry.slug, status: "skipped", reason: "archived" }); continue; }
    const root = companyRootForSlug(workspaceRoot, entry.slug);
    if (!existsSync(companyPaths(root).db)) { skipped.push({ slug: entry.slug, status: "skipped", reason: "not initialized" }); continue; }
    active.push({ slug: entry.slug, root });
  }
  return { active, skipped };
}

function preflightTarget(target: Target, actor: string): boolean {
  if (!isCanonicalActorId(actor)) return false;
  const allowed = checkActorAllowlist(target.root, actor);
  if (!allowed.allowed) return false;
  const db = new Database(companyPaths(target.root).db, { readonly: true });
  try {
    db.exec("PRAGMA query_only = ON; PRAGMA foreign_keys = ON; PRAGMA busy_timeout = 30000;");
    const lock = evaluateBackupLock(db, target.root);
    return lock.errors.length === 0 && !lock.locked;
  } catch { return false; }
  finally { db.close(); }
}

export async function runRecurringInvoices(db: Database, input: RunRecurringInvoicesInput) {
  if (!isValidIsoDate(input.asOfDate)) {
    return { ok: false, errors: ["asOfDate must be a YYYY-MM-DD date"], generated: 0, attempted: 0, hasMore: false, remainingGenerations: 0 };
  }
  const maxGenerations = input.maxGenerations ?? DEFAULT_MAX_GENERATIONS;
  if (!Number.isInteger(maxGenerations) || maxGenerations < 1 || maxGenerations > MAX_MAX_GENERATIONS) {
    return { ok: false, errors: [`maxGenerations must be an integer between 1 and ${MAX_MAX_GENERATIONS}`], generated: 0, attempted: 0, hasMore: false, remainingGenerations: 0 };
  }

  const templates = db.query(
    `SELECT id, interval, interval_count, first_issue_date, delivery_channel
       FROM recurring_invoice_templates WHERE active = 1 ORDER BY id`,
  ).all() as TemplateRow[];
  const dueTemplates: DueTemplate[] = templates.map((template) => {
    const latestPeriodIndex = latestPeriod(template, input.asOfDate);
    const existingDue = latestPeriodIndex < 0 ? 0 : (db.query(
      `SELECT COUNT(*) AS count FROM recurring_invoice_generations
        WHERE template_id = ? AND period_index <= ?`,
    ).get(template.id, latestPeriodIndex) as { count: number }).count;
    return { ...template, latestPeriodIndex, missingCount: Math.max(0, latestPeriodIndex + 1 - existingDue) };
  });

  // Plan only the bounded work for this invocation. No array proportional to
  // the template's historical age is ever created.
  const selectedMissing: Array<{ template: DueTemplate; periodIndex: number }> = [];
  for (const template of dueTemplates) {
    let cursor = nextMissingPeriod(db, template.id, 0, template.latestPeriodIndex);
    while (cursor !== null && selectedMissing.length < maxGenerations) {
      selectedMissing.push({ template, periodIndex: cursor });
      if (selectedMissing.length >= maxGenerations) break;
      cursor = nextMissingPeriod(db, template.id, cursor + 1, template.latestPeriodIndex);
    }
    if (selectedMissing.length >= maxGenerations) break;
  }

  let generated = 0;
  let resolvedMissing = 0;
  let attempted = 0;
  const errors: string[] = [];
  for (const item of selectedMissing) {
    const result = generateRecurringInvoice(db, input.companyRoot, {
      templateId: item.template.id,
      asOfDate: input.asOfDate,
      periodIndex: item.periodIndex,
      createdBy: input.createdBy,
      createdByProgram: input.createdByProgram,
    });
    if (!result.ok) {
      errors.push(...result.errors.map(sanitizeRecurringDeliveryError));
      continue;
    }
    resolvedMissing += 1;
    if (result.created) generated += 1;
  }

  for (const generation of deliveryCandidates(db, dueTemplates, maxGenerations)) {
    if (generation.latest_event === "attempted") {
      errors.push(sanitizeRecurringDeliveryError(
        "delivery attempt has no recorded outcome; manual provider reconciliation is required before retry",
      ));
      continue;
    }
    if (generation.latest_event === "terminal_failed" || generation.latest_event === "uncertain") {
      errors.push(sanitizeRecurringDeliveryError(generation.latest_message ?? "delivery requires manual reconciliation"));
      continue;
    }
    if (!input.adapter) {
      const message = "delivery adapter is not configured";
      appendDeliveryEvent(db, generation.id, generation.delivery_channel, "preflight_failed", message);
      errors.push(`template ${generation.template_id} requires a ${generation.delivery_channel} delivery adapter`);
      continue;
    }

    if (generation.latest_event === "accepted_pending") {
      if (!generation.provider_id || !input.adapter.observePending) {
        errors.push("accepted delivery cannot be status-observed with the configured adapter");
        continue;
      }
      try {
        const outcome = await input.adapter.observePending({
          documentId: generation.document_id,
          channel: generation.delivery_channel,
          providerId: generation.provider_id,
        });
        const message = outcomeMessage(outcome);
        appendDeliveryEvent(db, generation.id, generation.delivery_channel, outcome.status, message, outcome.providerId ?? generation.provider_id);
        if (outcome.observationFailed || outcome.status === "terminal_failed" || outcome.status === "uncertain") errors.push(message);
      } catch (error) {
        const message = sanitizeRecurringDeliveryError(error);
        appendDeliveryEvent(db, generation.id, generation.delivery_channel, "accepted_pending", message, generation.provider_id);
        errors.push(message);
      }
      continue;
    }

    let preflight: { ok: boolean; error?: string };
    try {
      preflight = await input.adapter.preflight({ documentId: generation.document_id, channel: generation.delivery_channel });
    } catch (error) {
      preflight = { ok: false, error: sanitizeRecurringDeliveryError(error) };
    }
    if (!preflight.ok) {
      const message = sanitizeRecurringDeliveryError(preflight.error ?? "preflight failed");
      appendDeliveryEvent(db, generation.id, generation.delivery_channel, "preflight_failed", message);
      errors.push(message);
      continue;
    }

    const reserved = db.transaction(() => db.query(
      `INSERT INTO recurring_invoice_delivery_events (generation_id, channel, event_type)
       VALUES (?, ?, 'attempted') ON CONFLICT DO NOTHING`,
    ).run(generation.id, generation.delivery_channel).changes > 0).immediate();
    if (!reserved) continue;
    attempted += 1;
    try {
      const outcome = await input.adapter.deliver({ documentId: generation.document_id, channel: generation.delivery_channel });
      const message = outcomeMessage(outcome);
      appendDeliveryEvent(db, generation.id, generation.delivery_channel, outcome.status, message, outcome.providerId);
      if (outcome.status === "terminal_failed" || outcome.status === "uncertain") errors.push(message);
    } catch (error) {
      const message = sanitizeRecurringDeliveryError(error);
      appendDeliveryEvent(db, generation.id, generation.delivery_channel, "uncertain", message);
      errors.push(message);
    }
  }

  const initialMissing = dueTemplates.reduce((sum, template) => sum + template.missingCount, 0);
  const remainingGenerations = Math.max(0, initialMissing - resolvedMissing);
  return {
    ok: errors.length === 0,
    errors,
    generated,
    attempted,
    hasMore: remainingGenerations > 0,
    remainingGenerations,
    continuation: remainingGenerations > 0 ? { remainingGenerations } : undefined,
  };
}

export function resolveRecurringDeliveryAdapter(
  db: Database,
  companyRoot: string,
  dependencies: AdapterDependencies = {},
): RecurringDeliveryAdapter {
  const resolveTransmitter = dependencies.resolveTransmitter ?? resolveDigisenseTransmitter;
  const resolveStatusChecker = dependencies.resolveStatusChecker ?? resolveDigisenseStatusChecker;
  const transmit = dependencies.transmit ?? transmitPublicEInvoicePeppol;
  const resume = dependencies.resume ?? resumePublicEInvoicePeppolSubmission;
  let smtp: LoadedSmtp | undefined;
  let digisense: ReturnType<typeof resolveDigisenseTransmitter> | undefined;
  return {
    async preflight({ documentId, channel }) {
      if (channel === "email") {
        smtp ??= loadSmtpConfig(companyRoot);
        if (!smtp.ok) return { ok: false, error: smtp.error };
        if (smtp.config.dryRun !== true) {
          return {
            ok: false,
            error: "live email transport is unavailable; inject a reviewed production delivery adapter",
          };
        }
        return emailPreflight(db, documentId);
      }
      digisense ??= resolveTransmitter(db, companyRoot);
      return digisense.ok ? { ok: true } : { ok: false, error: digisense.errors.join("; ") };
    },
    async deliver({ documentId, channel }) {
      if (channel === "email") {
        smtp ??= loadSmtpConfig(companyRoot);
        if (!smtp.ok || smtp.config.dryRun !== true) {
          return { status: "uncertain", message: "live email transport is unavailable" };
        }
        const result = sendInvoiceEmail(db, companyRoot, {
          invoiceDocumentId: documentId,
          kind: "invoice",
          smtp: smtp.config,
          transport: createSmtpTransport(smtp.config),
        });
        return result.ok
          ? { status: "acknowledged", message: result.duplicate ? "email already acknowledged" : "email acknowledged" }
          : { status: "uncertain", message: result.errors.join("; ") };
      }

      digisense ??= resolveTransmitter(db, companyRoot);
      if (!digisense.ok) return { status: "uncertain", message: digisense.errors.join("; ") };
      const result = await transmit(db, {
        invoiceDocumentId: documentId,
        accessPoint: digisenseAccessPointIdentity(digisense.companyKey),
      }, digisense.transmitter);
      return mapPeppolResult(result);
    },
    async observePending({ documentId, channel, providerId }) {
      if (channel !== "digisense") {
        return { status: "uncertain", providerId, message: "email delivery has no status-only observation contract" };
      }
      const resolved = resolveStatusChecker(db, companyRoot);
      if (!resolved.ok) return {
        status: "accepted_pending",
        providerId,
        observationFailed: true,
        message: resolved.errors.join("; "),
      };
      const result = await resume(db, {
        invoiceDocumentId: documentId,
        accessPoint: digisenseAccessPointIdentity(resolved.companyKey),
      }, async (documentId) => {
        const status = await resolved.client.documentStatus(documentId, resolved.companyKey);
        return status.ok
          ? {
              ok: true,
              status: status.data.documentStatus,
              message: status.data.message,
              publicUrl: status.data.publicUrl,
            }
          : { ok: false, error: `digisense document-status failed: ${status.error.message}` };
      });
      return mapPeppolResult(result, providerId);
    },
  };
}

export function resolveWorkspaceRoot(raw: string): string {
  if (raw.split(/[\\/]+/).includes("..")) {
    throw new Error("workspace root must not contain parent-directory ('..') segments");
  }
  const resolved = resolve(raw);
  if (!isAbsolute(resolved) || resolved.split(sep).includes("..")) {
    throw new Error("workspace root resolved to an unsafe path");
  }
  return resolved;
}

