export function generateRecurringInvoice(
  db: Database,
  companyRoot: string,
  input: GenerateRecurringInvoiceInput,
): GenerateRecurringInvoiceResult {
  const appliedRules = [GENERATE_RULE_ID];

  if (!Number.isInteger(input.templateId) || input.templateId <= 0) {
    return { ok: false, appliedRules, errors: ["templateId must be a positive integer"] };
  }
  if (!isValidIsoDate(input.asOfDate)) {
    return { ok: false, appliedRules, errors: ["asOfDate must be a YYYY-MM-DD date"] };
  }

  const template = db.query(
    `SELECT id, name, interval, interval_count, delivery_channel, first_issue_date, next_issue_date, payment_terms_days,
            delivery_period_mode, payload_json, notes, active, created_at
       FROM recurring_invoice_templates WHERE id = ? LIMIT 1`,
  ).get(input.templateId) as TemplateRow | null;
  if (!template) {
    return { ok: false, appliedRules, errors: [`recurring invoice template ${input.templateId} does not exist`] };
  }
  if (!template.active) {
    return { ok: false, appliedRules, errors: [`recurring invoice template ${input.templateId} is inactive`] };
  }

  const intervalMonths = INTERVAL_MONTHS[template.interval];
  const latestPeriodIndex = periodIndexAsOf(template.first_issue_date, intervalMonths, input.asOfDate, template.interval_count, template.interval);
  if (latestPeriodIndex < 0) {
    return {
      ok: false,
      appliedRules,
      errors: [
        `recurring invoice template ${template.id} is not yet due as of ${input.asOfDate} (first issue date ${template.first_issue_date})`,
      ],
    };
  }
  const periodIndex = input.periodIndex ?? latestPeriodIndex;
  if (!Number.isInteger(periodIndex) || periodIndex < 0 || periodIndex > latestPeriodIndex) {
    return { ok: false, appliedRules, errors: ["periodIndex must be a due non-negative integer"] };
  }

  const issueDate = periodIssueDate(template.first_issue_date, template.interval, template.interval_count, periodIndex);
  const window = deliveryWindow(template.delivery_period_mode, issueDate, intervalMonths * template.interval_count, template.interval === "weekly" ? template.interval_count : 0);
  const dueDate = addDays(issueDate, template.payment_terms_days);

  // Idempotency gate: if this template/period was already generated, return
  // the existing invoice instead of issuing a duplicate.
  const existing = db.query(
    `SELECT id, template_id, period_index, document_id, invoice_number, issue_date,
            delivery_period_start, delivery_period_end, created_at
       FROM recurring_invoice_generations
      WHERE template_id = ? AND period_index = ? LIMIT 1`,
  ).get(template.id, periodIndex) as GenerationRow | null;
  if (existing) {
    return {
      ok: true,
      created: false,
      templateId: template.id,
      periodIndex,
      documentId: existing.document_id,
      invoiceNumber: existing.invoice_number,
      issueDate: existing.issue_date,
      dueDate,
      deliveryPeriodStart: existing.delivery_period_start ?? undefined,
      deliveryPeriodEnd: existing.delivery_period_end ?? undefined,
      appliedRules,
      errors: [],
    };
  }

  const basePayload: InvoicePayload = JSON.parse(template.payload_json);
  const payload: InvoicePayload = {
    ...basePayload,
    issueDate,
    invoiceNumber: undefined,
    dueDate,
    deliveryDate: undefined,
    deliveryPeriodStart: window.start,
    deliveryPeriodEnd: window.end,
  };

  // Claim, legal-document issuance and the generation link are one immediate
  // SQLite transaction. A business rejection throws an internal rollback
  // marker, so neither the claim nor an invoice-number reservation can strand
  // the period. A later run can therefore succeed once the repairable
  // precondition (for example VIES evidence) has been fixed.
  const rollback = Symbol("recurring generation rollback");
  let rejected: GenerateRecurringInvoiceResult | undefined;
  let issuedArtifacts: { storedPath?: string; pdfStoredPath?: string } | undefined;
  try {
    return db.transaction(() => {
      const generated = db.query(
        `SELECT id, template_id, period_index, document_id, invoice_number, issue_date,
                delivery_period_start, delivery_period_end, created_at
           FROM recurring_invoice_generations WHERE template_id = ? AND period_index = ? LIMIT 1`,
      ).get(template.id, periodIndex) as GenerationRow | null;
      if (generated) {
        return { ok: true, created: false, templateId: template.id, periodIndex,
          documentId: generated.document_id, invoiceNumber: generated.invoice_number,
          issueDate: generated.issue_date, dueDate,
          deliveryPeriodStart: generated.delivery_period_start ?? undefined,
          deliveryPeriodEnd: generated.delivery_period_end ?? undefined,
          appliedRules, errors: [] };
      }

      const claimed = db.query(
        `INSERT INTO recurring_invoice_generation_claims (template_id, period_index)
         VALUES (?, ?) ON CONFLICT(template_id, period_index) DO NOTHING`,
      ).run(template.id, periodIndex);
      if (claimed.changes === 0) {
        rejected = { ok: false, templateId: template.id, periodIndex, appliedRules,
          errors: [`recurring invoice template ${template.id} period ${periodIndex} is pending recovery after an interrupted issuance`] };
        throw rollback;
      }

      const issued = issueInvoice(db, companyRoot, payload, {
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
      });
      issuedArtifacts = issued.ok
        ? { storedPath: issued.storedPath, pdfStoredPath: issued.pdfStoredPath }
        : undefined;
      const mergedRules = [...new Set([...appliedRules, ...issued.appliedRules])];
      if (!issued.ok || issued.documentId === undefined || issued.invoiceNumber === undefined) {
        rejected = { ok: false, appliedRules: mergedRules, errors: issued.errors };
        throw rollback;
      }

      const documentId: DocumentId = asDocumentId(Number(issued.documentId));
      const invoiceNumber = String(issued.invoiceNumber);

      db.query(
      `INSERT INTO recurring_invoice_generations (
        template_id, period_index, document_id, invoice_number, issue_date,
        delivery_period_start, delivery_period_end
      ) VALUES (?, ?, ?, ?, ?, ?, ?)`,
    ).run(
      template.id,
      periodIndex,
      documentId,
      invoiceNumber,
      issueDate,
      window.start ?? null,
      window.end ?? null,
    );

    const nextIssueDate = periodIssueDate(template.first_issue_date, template.interval, template.interval_count, periodIndex + 1);
    if (nextIssueDate > template.next_issue_date) {
      runSql(db,
        `UPDATE recurring_invoice_templates SET next_issue_date = ? WHERE id = ?`,
        nextIssueDate,
        template.id,
      );
    }

      insertAuditLog(db, {
        eventType: "recurring_invoice_generate",
        entityType: "document",
        entityId: documentId,
        message: `Generated invoice ${invoiceNumber} from recurring template ${template.id} period ${periodIndex}`,
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
      });

      return {
        ok: true, created: true, templateId: template.id, periodIndex,
        documentId, invoiceNumber, issueDate, dueDate,
        deliveryPeriodStart: window.start, deliveryPeriodEnd: window.end,
        appliedRules: mergedRules, errors: [],
      };
    }).immediate();
  } catch (error) {
    // issueInvoice publishes immutable files before its nested transaction
    // returns. If a later generation-link write aborts the outer transaction,
    // its document rows disappear but those exact new files must be removed by
    // the outer transaction owner as well.
    if (issuedArtifacts?.pdfStoredPath) removeIfExists(issuedArtifacts.pdfStoredPath);
    if (issuedArtifacts?.storedPath) removeIfExists(issuedArtifacts.storedPath);
    if (error === rollback && rejected) return rejected;
    throw error;
  }
}

const INTERVAL_MONTHS: Record<RecurringInterval, number> = {
  weekly: 0,
  monthly: 1,
  quarterly: 3,
  yearly: 12,
};

export function isValidIsoDate(value: unknown): value is string {
  if (typeof value !== "string") return false;
  const trimmed = value.trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return false;
  const date = new Date(`${trimmed}T00:00:00Z`);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === trimmed;
}

export function periodIndexAsOf(
  firstIssueDate: string,
  intervalMonths: number,
  asOfDate: string,
  intervalCount = 1,
  interval: RecurringInterval = "monthly",
  issueDateAt: typeof periodIssueDate = periodIssueDate,
): number {
  if (asOfDate < firstIssueDate) return -1;
  if (interval === "weekly") {
    const first = Date.parse(`${firstIssueDate}T00:00:00.000Z`);
    const asOf = Date.parse(`${asOfDate}T00:00:00.000Z`);
    return Math.floor((asOf - first) / (intervalCount * 7 * 24 * 60 * 60 * 1000));
  }
  const [firstYear, firstMonth] = firstIssueDate.split("-").map(Number);
  const [asOfYear, asOfMonth] = asOfDate.split("-").map(Number);
  const stepMonths = Math.max(1, intervalMonths * intervalCount);
  const estimatedUpper = Math.max(1, Math.floor((((asOfYear! - firstYear!) * 12) + asOfMonth! - firstMonth!) / stepMonths) + 2);
  let low = 0;
  let high = estimatedUpper;
  // Greatest due boundary <= asOfDate. Month-end and leap-day clamping stay
  // delegated to periodIssueDate, while evaluations grow logarithmically with
  // template age rather than once per historical period.
  while (low < high) {
    const middle = Math.ceil((low + high) / 2);
    if (issueDateAt(firstIssueDate, interval, intervalCount, middle) <= asOfDate) low = middle;
    else high = middle - 1;
  }
  return low;
}

export function periodIssueDate(firstIssueDate: string, interval: RecurringInterval, intervalCount: number, periodIndex: number): string {
  return interval === "weekly"
    ? addDays(firstIssueDate, 7 * intervalCount * periodIndex)
    : addMonths(firstIssueDate, INTERVAL_MONTHS[interval] * intervalCount * periodIndex);
}

function deliveryWindow(
  mode: DeliveryPeriodMode,
  issueDate: string,
  intervalMonths: number,
  intervalWeeks = 0,
): { start?: string; end?: string } {
  if (mode === "issue_month") {
    return { start: startOfMonth(issueDate), end: endOfMonth(issueDate) };
  }
  if (mode === "interval_window") {
    // The delivery period is the interval window beginning on the issue date.
    return { start: issueDate, end: intervalWeeks > 0 ? addDays(issueDate, intervalWeeks * 7) : addMonths(issueDate, intervalMonths) };
  }
  return {};
}

export function addDays(isoDate: string, days: number): string {
  const date = new Date(`${isoDate}T00:00:00.000Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

export function issueInvoice(
  db: Database,
  companyRoot: string,
  rawPayload: InvoicePayload,
  actor: ResolveActorInput = {},
): IssueInvoiceResult {
  // #221: fill the seller identity + due date from the stored company profile
  // before validation, so the owner never re-types their own master data.
  const payload = enrichInvoiceFromCompany(db, rawPayload);
  const validation = validateInvoice(payload);
  const appliedRules = [...new Set([...(validation.appliedRules ?? []), RULE_ID, LOCK_RULE_ID])];
  if (!validation.ok) return { ok: false, appliedRules, errors: validation.errors };

  // #221: resolve the company's payment details once, so the customer-facing
  // PDF built at issue time always carries the BETALING block (where to pay).
  const invoiceCurrency = (payload.currency ?? "DKK").trim().toUpperCase();
  const paymentDetails = resolveCompanyPaymentDetails(db, invoiceCurrency);

  let viesValidation: ReturnType<typeof requireCachedViesValidation>["validation"] | undefined;
  if (payload.vatTreatment === "foreign_reverse_charge") {
    const viesCheck = requireCachedViesValidation(db, payload.buyer?.vatOrCvr, "buyer.vatOrCvr");
    if (!viesCheck.ok) return { ok: false, appliedRules: [...new Set([...appliedRules, ...viesCheck.appliedRules])], errors: viesCheck.errors };
    viesValidation = viesCheck.validation;
  }

  const explicitInvoiceNumber = payload.invoiceNumber?.trim();
  if (explicitInvoiceNumber) {
    const scopeError = validateManualInvoiceNumberScope(db, payload.issueDate!, explicitInvoiceNumber);
    if (scopeError) return { ok: false, appliedRules, errors: [scopeError] };
  }
  const paths = companyPaths(companyRoot);
  mkdirSync(paths.invoicesIssued, { recursive: true });

  let tempPath: string | undefined;
  let storedPath: string | undefined;
  let pdfTempPath: string | undefined;
  let pdfStoredPath: string | undefined;
  let storedPathPromoted = false;
  let pdfStoredPathPromoted = false;

  // Calculate advisory-only output before any irreversible publication. A
  // warning lookup failure must never make a committed legal document look as
  // though issuance failed to its caller.
  const warnings = closedPeriodIssueWarnings(db, payload.issueDate);

  try {
    const result = db.transaction(() => {
      let invoiceNumber: InvoiceNumber;
      if (explicitInvoiceNumber !== undefined) {
        const reserved = reserveManualInvoiceNumber(db, payload.issueDate!, explicitInvoiceNumber);
        if (!reserved.ok) return { ok: false as const, error: reserved.error };
        // #251: use the canonicalised four-digit number, not the verbatim
        // input, so the persisted snapshot, PDF and documents row all carry the
        // same consistent format as an auto-numbered invoice.
        invoiceNumber = asInvoiceNumber(reserved.invoiceNumber);
      } else {
        invoiceNumber = nextIssuedInvoiceNumber(db, payload.issueDate!);
      }

      const issuedAt = new Date().toISOString();
      const issuedPayload = {
        ...payload,
        invoiceNumber,
        issuedAt,
        status: "issued",
        ...(viesValidation ? { viesValidation } : {}),
        // #221: persist the resolved payment details into the snapshot so the
        // at-issue PDF — and any later `invoice render` — show where to pay.
        ...(paymentDetails ? { payment: paymentDetails } : {}),
      };
      const serialized = JSON.stringify(issuedPayload, null, 2);
      const hash = sha256(serialized);
      const pdfBytes = buildIssuedInvoicePdf(issuedPayload);
      const pdfHash = createHash("sha256").update(pdfBytes).digest("hex");
      storedPath = join(paths.invoicesIssued, `${invoiceNumber}.json`);
      pdfStoredPath = join(paths.invoicesIssued, `${invoiceNumber}.pdf`);
      tempPath = writeTempFileFor(storedPath, serialized);
      pdfTempPath = writeTempFileFor(pdfStoredPath, pdfBytes);

      const grossAmount = payload.totals?.grossAmount ?? null;
      const vatAmount = payload.totals?.vatAmount ?? null;
      const inserted = db.query(
      `INSERT INTO documents (
        document_no, source, original_filename, stored_path, mime_type, sha256_hash,
        supplier_name, invoice_no, invoice_date, amount_inc_vat, currency, status,
        document_type, delivery_description, sender_name, sender_address, sender_vat_cvr,
        recipient_name, recipient_address, recipient_vat_cvr, vat_amount, payment_details, exemption_code, payload_json, retain_until
      ) VALUES (?, 'rentemester', ?, ?, 'application/json', ?, ?, ?, ?, ?, ?, 'issued', 'issued_invoice', ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?)
      RETURNING id`
    ).get(
      invoiceNumber,
      `${invoiceNumber}.json`,
      storedPath,
      hash,
      payload.seller?.name ?? null,
      invoiceNumber,
      payload.issueDate ?? null,
      grossAmount,
      invoiceCurrency,
      deliveryDescription(payload),
      payload.seller?.name ?? null,
      payload.seller?.address ?? null,
      payload.seller?.vatOrCvr ?? null,
      payload.buyer?.name ?? null,
      payload.buyer?.address ?? null,
      payload.buyer?.vatOrCvr ?? null,
      vatAmount,
      payload.reverseChargeBasis ?? null,
      serialized,
      retainUntilForDate(db, payload.issueDate!),
    ) as { id: number };

      const pdfInserted = db.query(
      `INSERT INTO documents (
        document_no, source, original_filename, stored_path, mime_type, sha256_hash,
        supplier_name, invoice_no, invoice_date, amount_inc_vat, currency, status,
        document_type, sender_name, sender_address, sender_vat_cvr,
        recipient_name, recipient_address, recipient_vat_cvr, vat_amount, payload_json, retain_until
      ) VALUES (?, 'rentemester', ?, ?, 'application/pdf', ?, ?, ?, ?, ?, ?, 'issued', 'issued_invoice_pdf', ?, ?, ?, ?, ?, ?, ?, ?, ?)
      RETURNING id`
    ).get(
      `${invoiceNumber}-pdf`,
      `${invoiceNumber}.pdf`,
      pdfStoredPath,
      pdfHash,
      payload.seller?.name ?? null,
      invoiceNumber,
      payload.issueDate ?? null,
      grossAmount,
      invoiceCurrency,
      payload.seller?.name ?? null,
      payload.seller?.address ?? null,
      payload.seller?.vatOrCvr ?? null,
      payload.buyer?.name ?? null,
      payload.buyer?.address ?? null,
      payload.buyer?.vatOrCvr ?? null,
      vatAmount,
      serialized,
      retainUntilForDate(db, payload.issueDate!),
      ) as { id: number };

      strengthenGdprErasureAliasesForIdentity(db, {
        name: payload.seller?.name,
        cvr: payload.seller?.vatOrCvr,
      });
      strengthenGdprErasureAliasesForIdentity(db, {
        name: payload.buyer?.name,
        cvr: payload.buyer?.vatOrCvr,
      });

      insertAuditLog(db, {
        eventType: "invoice_issue",
        entityType: "document",
        entityId: inserted.id,
        message: `Issued invoice ${invoiceNumber}`,
        createdBy: actor.createdBy,
        createdByProgram: actor.createdByProgram,
      });
      insertAuditLog(db, {
        eventType: "invoice_render_pdf",
        entityType: "document",
        entityId: pdfInserted.id,
        message: `Rendered invoice PDF ${invoiceNumber}`,
        createdBy: actor.createdBy,
        createdByProgram: actor.createdByProgram,
      });

      // Publish both immutable artifacts while the database transaction is
      // still open. A publication failure throws and rolls every document,
      // audit, and sequence row back. If COMMIT itself then fails, the outer
      // catch removes the already-published paths.
      promoteTempFileExclusive(tempPath!, storedPath!);
      storedPathPromoted = true;
      promoteTempFileExclusive(pdfTempPath!, pdfStoredPath!);
      pdfStoredPathPromoted = true;

      return { ok: true as const, documentId: asDocumentId(inserted.id), invoiceNumber, sha256: hash, pdfDocumentId: asDocumentId(pdfInserted.id), pdfSha256: pdfHash };
    }).immediate();

    if (!result.ok) return { ok: false, appliedRules, errors: [result.error] };
    return {
      ok: true,
      documentId: result.documentId,
      invoiceNumber: result.invoiceNumber,
      storedPath,
      sha256: result.sha256,
      pdfDocumentId: result.pdfDocumentId,
      pdfStoredPath,
      pdfSha256: result.pdfSha256,
      appliedRules,
      errors: [],
      ...(warnings.length > 0 ? { warnings } : {}),
    };
  } catch (error) {
    if (tempPath) removeIfExists(tempPath);
    if (pdfTempPath) removeIfExists(pdfTempPath);
    if (
      pdfStoredPathPromoted &&
      pdfStoredPath &&
      hasCommittedDocumentAtPath(db, pdfStoredPath) === false
    ) removeIfExists(pdfStoredPath);
    if (
      storedPathPromoted &&
      storedPath &&
      hasCommittedDocumentAtPath(db, storedPath) === false
    ) removeIfExists(storedPath);
    throw error;
  }
}

export function asDocumentId(value: number): DocumentId {
  return value as DocumentId;
}

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[]
): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  bindings: SQLQueryBindings[],
): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[] | [SQLQueryBindings[]]
): ReturnType<Database["run"]> {
  const normalized = bindings.length === 1 && Array.isArray(bindings[0])
    ? bindings[0]
    : bindings as SQLQueryBindings[];
  return db.run(sql, normalized);
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

export function removeIfExists(path: string) {
  try {
    unlinkSync(path);
  } catch {
    // best effort cleanup
  }
}

