export function ingestMailDrop(
  db: Database,
  companyRoot: string,
  inputPath: string,
  options: IngestMailDropOptions = {},
): IngestMailDropResult {
  const result: IngestMailDropResult = {
    ok: true,
    messagesProcessed: 0,
    attachmentsIngested: 0,
    attachmentsSkipped: 0,
    exceptionsCreated: 0,
    documents: [],
    errors: [],
  };

  if (!existsSync(inputPath)) {
    return { ...result, ok: false, errors: [`mail intake source does not exist: ${inputPath}`] };
  }

  let emlFiles: string[];
  try {
    emlFiles = resolveEmlFiles(inputPath);
  } catch (error) {
    return { ...result, ok: false, errors: [error instanceof Error ? error.message : String(error)] };
  }

  const maxSize = options.maxEmlSizeBytes ?? DEFAULT_MAX_EML_SIZE_BYTES;
  // SEC-9: normalise the optional sender allowlist once (case-insensitive bare
  // addresses). An empty/undefined list disables the check entirely.
  const senderAllowlist = new Set(
    (options.senderAllowlist ?? [])
      .map((entry) => extractSenderAddress(entry) ?? entry.trim().toLowerCase())
      .filter((entry) => entry.length > 0),
  );
  const maxMessages =
    typeof options.maxMessagesPerRun === "number" && options.maxMessagesPerRun > 0
      ? options.maxMessagesPerRun
      : null;

  for (const emlFile of emlFiles) {
    // SEC-9: stop before processing more than the per-run quota; the remaining
    // files stay in the maildrop and are picked up on the next run.
    if (maxMessages !== null && result.messagesProcessed >= maxMessages) {
      result.quotaReached = true;
      break;
    }
    result.messagesProcessed += 1;
    const raw = readFileSync(emlFile);
    // #352 — refuse over-large mails BEFORE we parse them. A 200 MB
    // ".eml" is almost always a bug (giant signed-image attachment, or a
    // dump-of-everything) and parsing it can OOM the daemon.
    if (raw.length > maxSize) {
      const ex = recordException(db, {
        type: "MAIL_INTAKE_TOO_LARGE",
        severity: "medium",
        message: `Mail message in ${emlFile} is ${raw.length} bytes (> ${maxSize}); refused to parse`,
        requiredAction:
          "Forward only the receipt itself or raise the maxEmlSizeBytes limit.",
        sourceEvidence: {
          rule: MAIL_INTAKE_RULES.EXCEPTION,
          file: emlFile,
          rawByteSize: raw.length,
          maxEmlSizeBytes: maxSize,
        },
        postingPreview: { nextStep: "documents ingest" },
      });
      if (ex.ok && !ex.duplicate) result.exceptionsCreated += 1;
      continue;
    }
    const parsed = parseEml(raw);

    // SEC-9: when a sender allowlist is configured, refuse any message whose
    // From address is not on it BEFORE touching the attachment pipeline. The
    // raw sender is echoed back through `markUntrusted` (SEC-8) since it is
    // attacker-controlled.
    if (senderAllowlist.size > 0) {
      const senderAddress = extractSenderAddress(parsed.from);
      if (!senderAddress || !senderAllowlist.has(senderAddress)) {
        const ex = recordException(db, {
          type: "MAIL_INTAKE_SENDER_NOT_ALLOWED",
          severity: "medium",
          message: `Mail message in ${markUntrusted(emlFile)} is from a sender not on the intake allowlist (from: ${markUntrusted(parsed.from)})`,
          requiredAction:
            "Add the sender to the mail-intake allowlist, or ingest the attachment manually via 'documents ingest' after verifying it.",
          sourceEvidence: {
            rule: MAIL_INTAKE_RULES.EXCEPTION,
            file: emlFile,
            from: markUntrusted(parsed.from),
            subject: markUntrusted(parsed.subject),
          },
          postingPreview: { nextStep: "documents ingest" },
        });
        if (ex.ok && !ex.duplicate) result.exceptionsCreated += 1;
        continue;
      }
    }

    // Ambiguous metadata: without a stable message-id we cannot dedup.
    if (!parsed.messageId || parsed.messageId.trim().length === 0) {
      const ex = recordException(db, {
        type: "MAIL_INTAKE_AMBIGUOUS_METADATA",
        severity: "medium",
        message: `Mail message in ${markUntrusted(emlFile)} has no Message-ID and cannot be ingested deterministically`,
        requiredAction: "Add a Message-ID header to the .eml or ingest the attachment manually via 'documents ingest'.",
        sourceEvidence: {
          rule: MAIL_INTAKE_RULES.EXCEPTION,
          file: emlFile,
          // SEC-8: sender/subject are attacker-controlled — flag as untrusted.
          from: markUntrusted(parsed.from),
          subject: markUntrusted(parsed.subject),
          date: parsed.date,
          attachmentCount: parsed.attachments.length,
        },
        postingPreview: { nextStep: "documents ingest" },
      });
      if (ex.ok && !ex.duplicate) result.exceptionsCreated += 1;
      continue;
    }

    const messageId = parsed.messageId.trim();
    const usable = parsed.attachments.filter((att) =>
      SUPPORTED_ATTACHMENT_EXTENSIONS.has(extname(att.filename).toLowerCase()),
    );

    if (usable.length === 0) {
      const ex = recordException(db, {
        type: "MAIL_INTAKE_NO_ATTACHMENT",
        severity: "medium",
        message: `Mail message ${markUntrusted(messageId)} has no usable PDF/JPG/PNG attachment`,
        requiredAction: "Forward the message with the receipt attached, or ingest the document manually.",
        sourceEvidence: {
          rule: MAIL_INTAKE_RULES.EXCEPTION,
          file: emlFile,
          messageId,
          // SEC-8: sender/subject are attacker-controlled — flag as untrusted.
          from: markUntrusted(parsed.from),
          subject: markUntrusted(parsed.subject),
          date: parsed.date,
        },
        postingPreview: { nextStep: "documents ingest" },
      });
      if (ex.ok && !ex.duplicate) result.exceptionsCreated += 1;
      continue;
    }

    const metadata = options.metadataPerMessage?.[messageId] ?? options.metadata;

    for (const attachment of usable) {
      const alreadySeen = db
        .query("SELECT id FROM mail_intake_messages WHERE message_id = ? AND attachment_sha256 = ? LIMIT 1")
        .get(messageId, attachment.sha256) as { id: number } | null;
      if (alreadySeen) {
        result.attachmentsSkipped += 1;
        continue;
      }

      if (!metadata) {
        const ex = recordException(db, {
          type: "MAIL_INTAKE_AMBIGUOUS_METADATA",
          severity: "medium",
          message: `Mail message ${markUntrusted(messageId)} attachment ${markUntrusted(attachment.filename)} has no metadata for ingest`,
          requiredAction: "Provide --metadata (or per-message metadata) so the attachment can be booked.",
          sourceEvidence: {
            rule: MAIL_INTAKE_RULES.EXCEPTION,
            file: emlFile,
            messageId,
            // SEC-8: the attachment filename comes from the sender — untrusted.
            attachmentFilename: markUntrusted(attachment.filename),
            attachmentSha256: attachment.sha256,
          },
          postingPreview: { nextStep: "documents ingest" },
        });
        if (ex.ok && !ex.duplicate) result.exceptionsCreated += 1;
        continue;
      }

      const ingestResult = ingestAttachment(db, companyRoot, messageId, parsed, attachment, metadata, options.ingestOptions);
      if (ingestResult.ingested) {
        result.attachmentsIngested += 1;
        result.documents.push({
          messageId,
          documentNo: ingestResult.documentNo!,
          sha256: ingestResult.sha256!,
        });
      } else if (ingestResult.exceptionCreated) {
        result.exceptionsCreated += 1;
      }
    }
  }

  return result;
}

const MAIL_INTAKE_RULES = {
  TRANSPORT: "DK-MAIL-INTAKE-TRANSPORT-001",
  DEDUP: "DK-MAIL-INTAKE-DEDUP-001",
  EXCEPTION: "DK-MAIL-INTAKE-EXCEPTION-001",
} as const;

function resolveEmlFiles(inputPath: string): string[] {
  const stat = statSync(inputPath);
  if (stat.isFile()) return [inputPath];
  if (stat.isDirectory()) {
    return readdirSync(inputPath)
      .filter((name) => name.toLowerCase().endsWith(".eml"))
      .sort()
      .map((name) => join(inputPath, name));
  }
  throw new Error(`mail intake source is neither a file nor a directory: ${inputPath}`);
}

function extractSenderAddress(from: string | null): string | null {
  if (!from) return null;
  const angle = /<([^>]+)>/.exec(from);
  const candidate = (angle ? angle[1] : from).trim().toLowerCase();
  return /^[^\s@]+@[^\s@]+$/.test(candidate) ? candidate : null;
}

export function recordException(db: Database, input: RecordExceptionInput) {
  const errors: string[] = [];
  const severity = input.severity ?? "medium";
  if (!["low", "medium", "high"].includes(severity)) errors.push("severity must be low, medium, or high");
  if (!input.type?.trim()) errors.push("type is required");
  if (!input.message?.trim()) errors.push("message is required");
  if (errors.length > 0) return { ok: false, exceptionId: undefined, duplicate: false, errors };

  const message = input.message.trim();
  const requiredAction = input.requiredAction?.trim() || null;
  const sourceEvidence = serializeJson(input.sourceEvidence);
  const postingPreview = serializeJson(input.postingPreview);
  const resolutionKey = input.resolutionKey?.trim() || null;

  const existing = db.query(
    `SELECT id
     FROM exceptions
     WHERE status = 'open'
       AND (resolution_key = ? OR (resolution_key IS NULL AND ? IS NULL))
       AND type = ?
       AND COALESCE(related_bank_transaction_id, 0) = COALESCE(?, 0)
       AND COALESCE(related_document_id, 0) = COALESCE(?, 0)
       AND message = ?
       AND COALESCE(required_action, '') = COALESCE(?, '')
     LIMIT 1`
  ).get(
    resolutionKey,
    resolutionKey,
    input.type.trim(),
    input.relatedBankTransactionId ?? null,
    input.relatedDocumentId ?? null,
    message,
    requiredAction,
  ) as { id: number } | null;

  if (existing) return { ok: true, exceptionId: existing.id, duplicate: true, errors: [] };

  const row = db.query(
    `INSERT INTO exceptions (
      type, severity, status, related_bank_transaction_id, related_document_id,
      message, required_action, source_evidence, posting_preview, resolution_key
    ) VALUES (?, ?, 'open', ?, ?, ?, ?, ?, ?, ?)
    RETURNING id`
  ).get(
    input.type.trim(),
    severity,
    input.relatedBankTransactionId ?? null,
    input.relatedDocumentId ?? null,
    message,
    requiredAction,
    sourceEvidence,
    postingPreview,
    resolutionKey,
  ) as { id: number };

  return { ok: true, exceptionId: row.id, duplicate: false, errors: [] };
}

export function parseEml(raw: Buffer | string): ParsedEml {
  const text = typeof raw === "string" ? raw : raw.toString("binary");
  const rawByteSize =
    typeof raw === "string" ? Buffer.byteLength(raw, "binary") : raw.length;
  const { headers } = splitHeadersAndBody(text);
  const attachments = collectAttachments(text).sort((a, b) => {
    if (a.filename !== b.filename) return a.filename < b.filename ? -1 : 1;
    return a.sha256 < b.sha256 ? -1 : a.sha256 > b.sha256 ? 1 : 0;
  });
  return {
    messageId: headers.get("message-id") ?? null,
    from: decodeHeaderText(headers.get("from")) ?? null,
    // #352 — bevar oprindelig afsender på forwardede mails. Reply-To
    // bruges af de fleste mail-klienter når man trykker "Videresend";
    // X-Forwarded-For / Resent-From fortæller specifikt at det ER en
    // videresendt mail.
    replyTo: decodeHeaderText(headers.get("reply-to")) ?? null,
    forwardedFrom:
      decodeHeaderText(headers.get("x-forwarded-for")) ??
      decodeHeaderText(headers.get("resent-from")) ??
      null,
    subject: decodeHeaderText(headers.get("subject")) ?? null,
    date: headers.get("date") ?? null,
    rawByteSize,
    attachments,
  };
}

export function markUntrusted(value: string | null | undefined): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    return "«untrusted: (empty)»";
  }
  const sanitisedBoundary = value.replace(/[«»]/g, "");
  return `«untrusted: ${sanitisedBoundary}»`;
}

function ingestAttachment(
  db: Database,
  companyRoot: string,
  messageId: string,
  parsed: ParsedEml,
  attachment: MailAttachment,
  metadataInput: MailIntakeMetadataInput,
  ingestOptions?: IngestDocumentOptions,
): { ingested: boolean; exceptionCreated: boolean; documentNo?: string; sha256?: string } {
  const scratchDir = mkdtempSync(join(tmpdir(), "rentemester-mail-attachment-"));
  const ext = extname(attachment.filename).toLowerCase() || extensionForMime(attachment.mimeType);
  const scratchFile = join(scratchDir, `attachment${ext}`);
  writeFileSync(scratchFile, attachment.content);

  try {
    const metadata: DocumentMetadata = {
      ...metadataInput,
      source: `mail-intake:${messageId}`,
    };
    const ingest = ingestDocument(db, companyRoot, scratchFile, metadata, ingestOptions ?? {});
    if (!ingest.ok) {
      const ex = recordException(db, {
        type: "MAIL_INTAKE_INGEST_BLOCKED",
        severity: "medium",
        message: `Mail intake ingest blocked for ${markUntrusted(attachment.filename)} from ${markUntrusted(messageId)}`,
        requiredAction: "Fix the attachment metadata or duplicate handling, then re-run mail-intake.",
        sourceEvidence: {
          rule: MAIL_INTAKE_RULES.EXCEPTION,
          messageId,
          // SEC-8: sender/subject/filename are attacker-controlled — untrusted.
          from: markUntrusted(parsed.from),
          subject: markUntrusted(parsed.subject),
          attachmentFilename: markUntrusted(attachment.filename),
          attachmentSha256: attachment.sha256,
          errors: ingest.errors ?? [],
        },
        postingPreview: { retryCommand: "mail-intake ingest --company <path> --source <eml> --metadata <file.json>" },
      });
      return { ingested: false, exceptionCreated: ex.ok && !ex.duplicate };
    }

    // Record the dedup row only after a successful ingest so a blocked
    // attachment can be retried after the metadata is fixed.
    db.query(
      `INSERT INTO mail_intake_messages (
        message_id, attachment_sha256, attachment_filename, document_id,
        sender, subject, mail_date
      ) VALUES (?, ?, ?, ?, ?, ?, ?)`,
    ).run(
      messageId,
      attachment.sha256,
      attachment.filename,
      ingest.documentId ?? null,
      parsed.from,
      parsed.subject,
      parsed.date,
    );

    return { ingested: true, exceptionCreated: false, documentNo: ingest.documentNo, sha256: ingest.sha256 };
  } finally {
    removePathWithRetry(scratchDir);
  }
}

