     FROM exceptions
     WHERE status = 'open'
       AND (resolution_key = ? OR (resolution_key IS NULL AND ? IS NULL))
       AND type = ?
       AND COALESCE(related_bank_transaction_id, 0) = COALESCE(?, 0)
       AND COALESCE(related_document_id, 0) = COALESCE(?, 0)
       AND message = ?
       AND COALESCE(required_action, '') = COALESCE(?, '')
     LIMIT 1`
  ).get(
    resolutionKey,
    resolutionKey,
    input.type.trim(),
    input.relatedBankTransactionId ?? null,
    input.relatedDocumentId ?? null,
    message,
    requiredAction,
  ) as { id: number } | null;

  if (existing) return { ok: true, exceptionId: existing.id, duplicate: true, errors: [] };

  const row = db.query(
    `INSERT INTO exceptions (
      type, severity, status, related_bank_transaction_id, related_document_id,
      message, required_action, source_evidence, posting_preview, resolution_key
    ) VALUES (?, ?, 'open', ?, ?, ?, ?, ?, ?, ?)
    RETURNING id`
  ).get(
    input.type.trim(),
    severity,
    input.relatedBankTransactionId ?? null,
    input.relatedDocumentId ?? null,
    message,
    requiredAction,
    sourceEvidence,
    postingPreview,
    resolutionKey,
  ) as { id: number };

  return { ok: true, exceptionId: row.id, duplicate: false, errors: [] };
}

export function parseEml(raw: Buffer | string): ParsedEml {
  const text = typeof raw === "string" ? raw : raw.toString("binary");
  const rawByteSize =
    typeof raw === "string" ? Buffer.byteLength(raw, "binary") : raw.length;
  const { headers } = splitHeadersAndBody(text);
  const attachments = collectAttachments(text).sort((a, b) => {
    if (a.filename !== b.filename) return a.filename < b.filename ? -1 : 1;
    return a.sha256 < b.sha256 ? -1 : a.sha256 > b.sha256 ? 1 : 0;
  });
  return {
    messageId: headers.get("message-id") ?? null,
    from: decodeHeaderText(headers.get("from")) ?? null,
    // #352 — bevar oprindelig afsender på forwardede mails. Reply-To
    // bruges af de fleste mail-klienter når man trykker "Videresend";
    // X-Forwarded-For / Resent-From fortæller specifikt at det ER en
    // videresendt mail.
    replyTo: decodeHeaderText(headers.get("reply-to")) ?? null,
    forwardedFrom:
      decodeHeaderText(headers.get("x-forwarded-for")) ??
      decodeHeaderText(headers.get("resent-from")) ??
      null,
    subject: decodeHeaderText(headers.get("subject")) ?? null,
    date: headers.get("date") ?? null,
    rawByteSize,
    attachments,
  };
}

export function markUntrusted(value: string | null | undefined): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    return "«untrusted: (empty)»";
  }
  const sanitisedBoundary = value.replace(/[«»]/g, "");
  return `«untrusted: ${sanitisedBoundary}»`;
}

function ingestAttachment(
  db: Database,
  companyRoot: string,
  messageId: string,
  parsed: ParsedEml,
  attachment: MailAttachment,
  metadataInput: MailIntakeMetadataInput,
  ingestOptions?: IngestDocumentOptions,
): { ingested: boolean; exceptionCreated: boolean; documentNo?: string; sha256?: string } {
  const scratchDir = mkdtempSync(join(tmpdir(), "rentemester-mail-attachment-"));
  const ext = extname(attachment.filename).toLowerCase() || extensionForMime(attachment.mimeType);
  const scratchFile = join(scratchDir, `attachment${ext}`);
  writeFileSync(scratchFile, attachment.content);

  try {
    const metadata: DocumentMetadata = {
      ...metadataInput,
      source: `mail-intake:${messageId}`,
    };
    const ingest = ingestDocument(db, companyRoot, scratchFile, metadata, ingestOptions ?? {});
    if (!ingest.ok) {
      const ex = recordException(db, {
        type: "MAIL_INTAKE_INGEST_BLOCKED",
        severity: "medium",
        message: `Mail intake ingest blocked for ${markUntrusted(attachment.filename)} from ${markUntrusted(messageId)}`,
        requiredAction: "Fix the attachment metadata or duplicate handling, then re-run mail-intake.",
        sourceEvidence: {
          rule: MAIL_INTAKE_RULES.EXCEPTION,
          messageId,
          // SEC-8: sender/subject/filename are attacker-controlled — untrusted.
          from: markUntrusted(parsed.from),
          subject: markUntrusted(parsed.subject),
          attachmentFilename: markUntrusted(attachment.filename),
          attachmentSha256: attachment.sha256,
          errors: ingest.errors ?? [],
        },
        postingPreview: { retryCommand: "mail-intake ingest --company <path> --source <eml> --metadata <file.json>" },
      });
      return { ingested: false, exceptionCreated: ex.ok && !ex.duplicate };
    }

    // Record the dedup row only after a successful ingest so a blocked
    // attachment can be retried after the metadata is fixed.
    db.query(
      `INSERT INTO mail_intake_messages (
        message_id, attachment_sha256, attachment_filename, document_id,
        sender, subject, mail_date
      ) VALUES (?, ?, ?, ?, ?, ?, ?)`,
    ).run(
      messageId,
      attachment.sha256,
      attachment.filename,
      ingest.documentId ?? null,
      parsed.from,
      parsed.subject,
      parsed.date,
    );

    return { ingested: true, exceptionCreated: false, documentNo: ingest.documentNo, sha256: ingest.sha256 };
  } finally {
    removePathWithRetry(scratchDir);
  }
}

typeDeclarations.source:
export type IngestMailDropOptions = {
  /** Metadata applied to every ingested attachment. */
  metadata?: MailIntakeMetadataInput;
  /** Per-message metadata keyed on message-id; overrides `metadata`. */
  metadataPerMessage?: Record<string, MailIntakeMetadataInput>;
  /** Forwarded to ingestDocument for forced logical-duplicate scans. */
  ingestOptions?: IngestDocumentOptions;
  /**
   * #352 — Maks-størrelse pr. eml-fil i bytes. Default
   * `DEFAULT_MAX_EML_SIZE_BYTES`. Mails over grænsen får en
   * MAIL_INTAKE_TOO_LARGE-eksception i stedet for at blive parset.
   */
  maxEmlSizeBytes?: number;
  /**
   * SEC-9 (Audit 2026-06-11): OPTIONAL per-company sender allowlist. When
   * provided (and non-empty), a message whose `From:` address is not in the
   * list is refused with a `MAIL_INTAKE_SENDER_NOT_ALLOWED` exception instead of
   * being ingested — anyone who learns the company's intake address can no
   * longer drop arbitrary attachments into the ledger pipeline. Comparison is
   * case-insensitive on the bare `local@domain`. Default (undefined/empty) keeps
   * today's behaviour: every sender is accepted.
   */
  senderAllowlist?: string[];
  /**
   * SEC-9 (Audit 2026-06-11): OPTIONAL ceiling on how many messages a single
   * run will process. A flood of mail to the intake address cannot exhaust the
   * exception queue / disk in one pass; the remainder simply stay in the
   * maildrop for the next run. Default (undefined) keeps today's behaviour: the
   * whole maildrop is processed.
   */
  maxMessagesPerRun?: number;
};

export type DocumentMetadata = {
  source: string;
  documentType?: DocumentType;
  issueDate?: string;
  invoiceNo?: string;
  deliveryDescription?: string;
  amountIncVat?: number;
  currency?: string;
  sender?: { name?: string; address?: string; vatOrCvr?: string; countryCode?: string; identifierKind?: SupplierIdentifierKind };
  recipient?: { name?: string; address?: string; vatOrCvr?: string };
  vatAmount?: number;
  /** Purchase tax bases, retained verbatim with the voucher.  Omit for legacy uniform VAT documents. */
  purchaseVatLines?: PurchaseVatLine[];
  /** Human-confirmed invoice evidence required before a non-EU service can be
   * posted with automatic reverse-charge input-VAT deduction. */
  reverseChargeWordingConfirmed?: boolean;
  /** Explicit source fact: the issuer supplied a Danish simplified purchase invoice. */
  danishSimplifiedPurchaseInvoice?: boolean;
  paymentDetails?: string;
  exemptionCode?: DocumentExemptionCode;
  /** Imported bank row that is the immutable primary evidence for an internal voucher. */
  sourceBankTransactionId?: number;
  /** Human accounting explanation for why the internal voucher is booked. */
  accountingRationale?: string;
};

export type DocumentType =
  | "purchase_sale"
  | "cash_register_receipt"
  | "issued_invoice_pdf"
  | "internal_voucher";

export type IngestDocumentOptions = {
  forceDuplicateLogicalIdentity?: boolean;
  createdBy?: string;
  createdByProgram?: string;
  /** Internal bulk-import use only: the enclosing import writes one audit event. */
  suppressAudit?: boolean;
  /** Scanner policy is off unless a caller explicitly requires it. */
  scannerPolicy?: "off" | "required";
  /** Upper bound for a single scanner decision. Required scanners fail closed on expiry. */
  scannerTimeoutMs?: number;
  /** A vendor-neutral async seam. It receives immutable snapshot bytes only. */
  scanner?: DocumentScanner;
};

export type DocumentScanner = {
  scan(input: { bytes: Buffer; sha256: string; mimeType: string; filename: string; signal: AbortSignal }): Promise<
    | { ok: true; scannerId: string; scannerVersion?: string; evidenceRef?: string }
    | { ok: false; error?: string }
  >;
};

export type IngestMailDropResult = {
  ok: boolean;
  messagesProcessed: number;
  attachmentsIngested: number;
  attachmentsSkipped: number;
  exceptionsCreated: number;
  documents: Array<{ messageId: string; documentNo: string; sha256: string }>;
  errors: string[];
  /**
   * SEC-9: true when processing stopped because `maxMessagesPerRun` was reached
   * before the maildrop was exhausted. Unprocessed messages remain for the next
   * run. Absent/false when no quota was configured or the whole drop fit.
   */
  quotaReached?: boolean;
};

export type RecordExceptionInput = {
  type: string;
  severity?: ExceptionSeverity;
  relatedBankTransactionId?: number | null;
  relatedDocumentId?: number | null;
  message: string;
  requiredAction?: string | null;
  sourceEvidence?: unknown;
  postingPreview?: unknown;
  /** Stable identity for a resumable machine-created exception. */
  resolutionKey?: string | null;
};

export type ParsedEml = {
  messageId: string | null;
  from: string | null;
  /** #352 — Reply-To bevarer ofte den oprindelige afsender på en forwardet mail. */
  replyTo: string | null;
  /**
   * #352 — X-Forwarded-For (eller den klassiske "Resent-From") afslører at
   * mailen er forwardet; cockpittet kan vise det som "videresendt fra <x>".
   */
  forwardedFrom: string | null;
  subject: string | null;
  date: string | null;
  /**
   * #352 — Den samlede rå-størrelse i bytes inden parsing. Bruges af
   * MAX_EML_SIZE_BYTES-checket så vi kan rejse en eksception før vi parser
   * et helt 200 MB attached-PDF-monster.
   */
  rawByteSize: number;
  attachments: MailAttachment[];
};

export type MailAttachment = {
  filename: string;
  mimeType: string;
  content: Buffer;
  /** sha256 of the decoded attachment bytes — stable across reparses. */
  sha256: string;
};

