export type ImmediateWriteOffInput = {
  name: string;
  category: string;
  acquisitionDate: string;
  cost: number;
  purchaseDocumentId: number;
  expenseAccountNo: string;
  transactionDate: string;
  confirmImmediateWriteOff: boolean;
  thresholdRuleSource: string;
  paymentAccountNo?: string;
  note?: string;
  createdBy?: string;
  createdByProgram?: string;
};

export type ImmediateWriteOffResult = JournalPostResult & {
  writeOffId?: number;
  cost?: number;
  thresholdDkk?: number;
};

export type JournalPostResult = {
  ok: boolean;
  entryId?: JournalEntryId;
  entryNo?: string;
  entryHash?: string;
  appliedRules: string[];
  errors: string[];
};

export type RecordExceptionInput = {
  type: string;
  severity?: ExceptionSeverity;
  relatedBankTransactionId?: number | null;
  relatedDocumentId?: number | null;
  message: string;
  requiredAction?: string | null;
  sourceEvidence?: unknown;
  postingPreview?: unknown;
  /** Stable identity for a resumable machine-created exception. */
  resolutionKey?: string | null;
};

export type AccountRoleResolution =
  | { ok: true; role: AccountRole; accountNo: string; version: number; confirmedBy: string; confirmationSource: AccountRoleConfirmationSource }
  | { ok: false; role: AccountRole; error: string };

export type JournalEntryInput = {
  transactionDate: string;
  text: string;
  documentId?: number;
  sourceBankTransactionId?: number;
  currency?: string;
  amountForeign?: number;
  amountDkk?: number;
  fxRateToDkk?: number;
