           name, category, acquisition_date, writeoff_date, cost, purchase_document_id,
           expense_account_no, confirmed, threshold_dkk, threshold_rule_source, note, journal_entry_id
         ) VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?)
         RETURNING id`,
      ).get(
        input.name.trim(),
        input.category.trim(),
        input.acquisitionDate,
        input.transactionDate,
        cost,
        input.purchaseDocumentId,
        input.expenseAccountNo.trim(),
        thresholdDkk,
        thresholdRuleSource,
        input.note?.trim() || null,
        journal.entryId!,
      ) as { id: number };

      insertAuditLog(db, {
        eventType: "asset_immediate_writeoff",
        entityType: "asset_writeoff",
        entityId: writeOff.id,
        message: `Immediate write-off ${cost} for ${input.name.trim()}`,
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
      });

      return {
        ...journal,
        writeOffId: writeOff.id,
        cost,
        thresholdDkk,
        appliedRules: [...new Set([WRITEOFF_RULE_ID, ...(journal.appliedRules ?? [])])],
      };
    })();
    return result;
  } catch (error) {
    const parsed = typeof error === "object" && error && "message" in error ? (() => {
      try { return JSON.parse(String((error as any).message)); } catch { return null; }
    })() : null;
    return {
      ok: false,
      appliedRules: [...new Set([WRITEOFF_RULE_ID, ...((parsed?.appliedRules as string[] | undefined) ?? [])])],
      errors: (parsed?.errors as string[] | undefined) ?? [String(error)],
    };
  }
}

export function isValidIsoDate(value: unknown): value is string {
  if (typeof value !== "string") return false;
  const trimmed = value.trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return false;
  const date = new Date(`${trimmed}T00:00:00Z`);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === trimmed;
}

export function roundDkk(value: number) {
  return Number.isFinite(value) ? fromScaledInt(scaledInt(value, 2), 2) : NaN;
}

export function straksafskrivningThresholdForYear(year: number): number {
  const table = STRAKSAFSKRIVNING_THRESHOLDS_BY_YEAR;
  const first = table[0]!;
  const last = table[table.length - 1]!;
  if (year <= first.year) return first.thresholdDkk;
  if (year >= last.year) return last.thresholdDkk;
  // Pick the entry for the exact year, or the most recent entry on/before it.
  let chosen = first.thresholdDkk;
  for (const row of table) {
    if (row.year <= year) chosen = row.thresholdDkk;
    else break;
  }
  return chosen;
}

const STRAKSAFSKRIVNING_THRESHOLDS_BY_YEAR: ReadonlyArray<{ year: number; thresholdDkk: number }> = [
  { year: 2024, thresholdDkk: 33100 },
  { year: 2025, thresholdDkk: 34400 },
  { year: 2026, thresholdDkk: 36000 },
];

export function recordException(db: Database, input: RecordExceptionInput) {
  const errors: string[] = [];
  const severity = input.severity ?? "medium";
  if (!["low", "medium", "high"].includes(severity)) errors.push("severity must be low, medium, or high");
  if (!input.type?.trim()) errors.push("type is required");
  if (!input.message?.trim()) errors.push("message is required");
  if (errors.length > 0) return { ok: false, exceptionId: undefined, duplicate: false, errors };

  const message = input.message.trim();
  const requiredAction = input.requiredAction?.trim() || null;
  const sourceEvidence = serializeJson(input.sourceEvidence);
  const postingPreview = serializeJson(input.postingPreview);
  const resolutionKey = input.resolutionKey?.trim() || null;

  const existing = db.query(
    `SELECT id
     FROM exceptions
     WHERE status = 'open'
       AND (resolution_key = ? OR (resolution_key IS NULL AND ? IS NULL))
       AND type = ?
       AND COALESCE(related_bank_transaction_id, 0) = COALESCE(?, 0)
       AND COALESCE(related_document_id, 0) = COALESCE(?, 0)
       AND message = ?
       AND COALESCE(required_action, '') = COALESCE(?, '')
     LIMIT 1`
  ).get(
    resolutionKey,
    resolutionKey,
    input.type.trim(),
    input.relatedBankTransactionId ?? null,
    input.relatedDocumentId ?? null,
    message,
    requiredAction,
  ) as { id: number } | null;

  if (existing) return { ok: true, exceptionId: existing.id, duplicate: true, errors: [] };

  const row = db.query(
    `INSERT INTO exceptions (
      type, severity, status, related_bank_transaction_id, related_document_id,
      message, required_action, source_evidence, posting_preview, resolution_key
    ) VALUES (?, ?, 'open', ?, ?, ?, ?, ?, ?, ?)
    RETURNING id`
  ).get(
    input.type.trim(),
    severity,
    input.relatedBankTransactionId ?? null,
    input.relatedDocumentId ?? null,
    message,
    requiredAction,
    sourceEvidence,
    postingPreview,
    resolutionKey,
  ) as { id: number };

  return { ok: true, exceptionId: row.id, duplicate: false, errors: [] };
}

function accountExists(db: Database, accountNo: string): boolean {
  return db.query("SELECT 1 FROM accounts WHERE account_no = ? AND active = 1").get(accountNo) != null;
}

export function resolveAccountRole(db: Database, role: AccountRole): AccountRoleResolution {
  const row = db.query(`SELECT m.account_no, m.version, m.confirmed_by, m.confirmation_source, a.type, a.normal_balance, a.active
    FROM account_role_mappings m JOIN accounts a ON a.account_no = m.account_no
    WHERE m.role = ? AND m.status = 'confirmed'`).get(role) as { account_no: string; version: number; confirmed_by: string; confirmation_source: AccountRoleConfirmationSource; type: string; normal_balance: string; active: number } | null;
  if (!row) return { ok: false, role, error: `account role '${role}' has no active confirmed mapping` };
  if (row.active !== 1) return { ok: false, role, error: `account role '${role}' maps to inactive account ${row.account_no}` };
  const expected = expectations[role];
  if (row.type !== expected.type || row.normal_balance !== expected.normalBalance) {
    return { ok: false, role, error: `account role '${role}' maps to semantically incompatible account ${row.account_no}` };
  }
  return { ok: true, role, accountNo: row.account_no, version: row.version, confirmedBy: row.confirmed_by, confirmationSource: row.confirmation_source };
}

const expectations: Record<AccountRole, { type: string; normalBalance: string }> = {
  bank: { type: "asset", normalBalance: "debit" },
  debtors: { type: "asset", normalBalance: "debit" },
  creditors: { type: "liability", normalBalance: "credit" },
  output_vat: { type: "vat", normalBalance: "credit" },
  input_vat: { type: "vat", normalBalance: "debit" },
  reverse_charge_vat: { type: "vat", normalBalance: "credit" },
  vat_settlement: { type: "liability", normalBalance: "credit" },
  operational_default: { type: "expense", normalBalance: "debit" },
};

export function postJournalEntry(db: Database, payload: JournalEntryInput): JournalPostResult {
  return postJournalEntryWithPolicy(db, payload, MANUAL_POSTING_POLICY);
}

const MANUAL_POSTING_POLICY: JournalPostingPolicy = {
  historicalImport: false,
  allowUncodedVatControl: false,
};

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

