  /** Summed credit movement in the period, DKK. */
  credit: number;
  /** Net movement, signed debit − credit, DKK. */
  balance: number;
};

type Acc = {
    accountNo: string;
    name: string;
    type: AccountType;
    normalBalance: "debit" | "credit";
    debitOre: bigint;
    creditOre: bigint;
  };

