producerDefinitions.source:
export function buildVatFiling(db: Database, periodStart: string, periodEnd: string): VatFilingReport {
  const vatReport = buildVatReport(db, periodStart, periodEnd);
  const vatPeriodType = getCompanySettings(db).vatPeriodType;

  if (!looksLikeIsoDate(periodStart) || !looksLikeIsoDate(periodEnd)) {
    return failure(periodStart, periodEnd, "open", ["periodStart and periodEnd must be YYYY-MM-DD"], vatReport, vatPeriodType);
  }

  if (vatPeriodType === null) {
    return failure(
      periodStart,
      periodEnd,
      "open",
      ["selskabet er ikke momsregistreret og har derfor ingen momsangivelsesperiode"],
      vatReport,
      null,
    );
  }

  const canonicalWindow = vatPeriodWindowFor(periodStart, vatPeriodType);
  if (
    canonicalWindow.start !== periodStart ||
    canonicalWindow.end !== periodEnd
  ) {
    return failure(
      periodStart,
      periodEnd,
      "open",
      [
        `VAT period ${periodStart}..${periodEnd} does not match the company's registered ${vatPeriodType} cadence; the canonical period containing ${periodStart} is ${canonicalWindow.start}..${canonicalWindow.end}`,
      ],
      vatReport,
      vatPeriodType,
    );
  }

  // A momsangivelse may only be produced for a finalised VAT period. The
  // period bounds must exactly match a closed or reported VAT period
  // accounting period; anything else means the period is still open or
  // incomplete and must not be filed.
  const period = db.query(
    `SELECT id, status, reference
       FROM accounting_periods
      WHERE period_start = ? AND period_end = ? AND kind IN ('vat_period', 'vat_quarter')
      ORDER BY CASE kind WHEN 'vat_period' THEN 0 ELSE 1 END, id DESC
      LIMIT 1`
  ).get(periodStart, periodEnd) as {
    id: number;
    status: "open" | "closed" | "reported";
    reference: string | null;
  } | null;

  const periodStatus = period
    ? effectivePeriodState(db, period.id, period.status)
    : "open";

  // Resolve lifecycle before surfacing report-integrity failures. A closed
  // period with malformed legacy VAT data is still closed; labelling it open
  // would send the user down the wrong recovery path. The report's own
  // canonical deadline is used, so arbitrary bounds never gain a fake date.
  if (!vatReport.ok) {
    const reportErrors = [...vatReport.errors];
    if (!period || periodStatus === "open") {
      reportErrors.push(
        `VAT period ${periodStart}..${periodEnd} is not closed: a momsangivelse requires a closed or reported vat_period accounting period covering exactly this period — run 'period close --kind vat_period' first`,
      );
    }
    return failure(
      periodStart,
      periodEnd,
      periodStatus,
      reportErrors,
      vatReport,
      vatPeriodType,
      period?.reference ?? null,
    );
  }

  if (!period || periodStatus === "open") {
    return failure(
      periodStart,
      periodEnd,
      "open",
      [
        `VAT period ${periodStart}..${periodEnd} is not closed: a momsangivelse requires a closed or reported vat_period accounting period covering exactly this period — run 'period close --kind vat_period' first`,
      ],
      vatReport,
      vatPeriodType,
    );
  }

  // The shared projection keeps CLI/MCP/report/cockpit/export figures alike.
  const rubrikker = vatReport.rubrikker;
  // Moms af ydelseskøb i udlandet: reverse charge on EU service purchases.
  // Use the VAT *actually booked* on account 1200 per purchase, not
  // percentOfDkk(summed base, 25). Each purchase's VAT is øre-rounded when
  // booked, so the booked total can differ from 25%-of-aggregate by up to 1
  // øre per purchase. Using the booked figure keeps this rubrik equal to what
  // hit the ledger AND lets salgsmoms below come out as the exact own-sale VAT.
  const momsAfYdelseskobUdland = rubrikker.momsAfYdelseskobUdland;

  // Salgsmoms: output VAT on own sales only. buildVatReport.outputVat is
  // account-based (1200) and therefore includes the reverse-charge output VAT
  // booked by postEuServiceReverseChargePurchase — but on TastSelv that VAT
  // belongs exclusively in "Moms af ydelseskøb i udlandet" (momsloven §46 jf.
  // §37). Subtract the exact same ydelseskøb figure so the two rubrikker never
  // double-count and momstilsvar stays equal to the raw report's netVatPayable.
  // buildVatReport.outputVat already nets bad-debt relief out of output VAT.
  const salgsmoms = rubrikker.salgsmoms;

  // Moms af varekøb i udlandet: booked §11 EU-goods acquisition VAT. The
  // shared projection removes this exact amount from salgsmoms, so it appears
  // once and only once in the filing while momstilsvar remains the booked net.
  const momsAfVarekobUdland = rubrikker.momsAfVarekobUdland;

  // Købsmoms: total deductible input VAT (domestic + reverse-charge +
  // representation), already aggregated by buildVatReport.
  const kobsmoms = rubrikker.kobsmoms;

  // Momstilsvar = salgsmoms + udenlandsk moms − købsmoms.
  // Positive = payable to SKAT; negative = refund (negativt momstilsvar).
  const momstilsvar = rubrikker.momstilsvar;

  // Rubrik A: value of goods/services purchased abroad without Danish VAT.
  const rubrikA = rubrikker.rubrikA;
  // Rubrik B (JUR-2/KODE-2): value of goods/services SOLD ABROAD without Danish
  // VAT — cross-border EU B2B reverse-charge sales ONLY. This is the figure
  // cross-checked against the EU sales list (VIES), so only the FOREIGN reverse-
  // charge base belongs here. Domestic §46 omvendt betalingspligt is explicitly
  // excluded (it would otherwise inflate rubrik B and break the VIES reconciliation).
  const rubrikB = rubrikker.rubrikB;
  // Rubrik C: value of other VAT-exempt sales. Two sources, both derived from
  // real ledger data:
  //   1. §13-exempt domestic sales (DK_SALE_EXEMPT), and
  //   2. domestic §46 omvendt betalingspligt sales (DOMESTIC_REVERSE_CHARGE_EXEMPT,
  //      e.g. mobiltelefoner, CPU'er, metalskrot). SKAT Den juridiske vejledning
  //      A.B.3.3.1.5 places these in rubrik C ("værdi af andet salg uden moms"),
  //      NOT rubrik B.
  // OSS consumer sales (OSS_EU_CONSUMER) are deliberately NOT part of rubrik C:
  // they belong on the separate OSS return, so buildVatReport keeps them in their
  // own base and they never reach this momsangivelse.
  const rubrikC = rubrikker.rubrikC;

  return {
    ok: true,
    appliedRules: [FILING_RULE_ID],
    periodStart,
    periodEnd,
    vatPeriodType,
    periodStatus,
    periodReference: period.reference,
    filingDeadline: canonicalWindow.filingDeadline,
    rubrikker: {
      salgsmoms,
      momsAfVarekobUdland,
      momsAfYdelseskobUdland,
      kobsmoms,
      momstilsvar,
      rubrikA,
      rubrikB,
      rubrikC,
    },
    vatReport,
    warnings: [...vatReport.warnings],
    errors: [],
  };
}

export function getCompanySettings(db: Database): CompanySettings {
  // #289: older ledgers (and the base schema.sql) may lack `vat_period_type`.
  // Read it only when present; absent → fall back to the quarterly default so
  // a pre-#289 company is unaffected.
  const vatColumn = hasVatPeriodColumn(db) ? "vat_period_type" : "NULL AS vat_period_type";
  const row = db.query(
    `SELECT id, name, country, currency, cvr, fiscal_year_start_month, fiscal_year_label_strategy,
            address, postal_code, city, company_form, industry_code, industry_text,
            cvr_status, audit_waived, cvr_synced_at, payment_terms_days, ${vatColumn}
       FROM companies
      ORDER BY id ASC
      LIMIT 1`
  ).get() as {
    id: number;
    name: string;
    country: string;
    currency: string;
    cvr: string | null;
    fiscal_year_start_month: number;
    fiscal_year_label_strategy: FiscalYearLabelStrategy;
    address: string | null;
    postal_code: string | null;
    city: string | null;
    company_form: string | null;
    industry_code: string | null;
    industry_text: string | null;
    cvr_status: string | null;
    audit_waived: number | null;
    cvr_synced_at: string | null;
    payment_terms_days: number | null;
    vat_period_type: string | null;
  } | null;

  if (!row) return DEFAULT_COMPANY_SETTINGS;
  return {
    id: row.id,
    name: row.name,
    country: row.country,
    currency: row.currency,
    cvr: normalizeCvr(row.cvr),
    fiscalYearStartMonth: normalizeFiscalYearStartMonth(row.fiscal_year_start_month) ?? 1,
    fiscalYearLabelStrategy: normalizeFiscalYearLabelStrategy(row.fiscal_year_label_strategy) ?? "end-year",
    address: row.address,
    postalCode: row.postal_code,
    city: row.city,
    companyForm: row.company_form,
    industryCode: row.industry_code,
    industryText: row.industry_text,
    cvrStatus: row.cvr_status,
    auditWaived: row.audit_waived === null ? null : row.audit_waived === 1,
    cvrSyncedAt: row.cvr_synced_at,
    paymentTermsDays:
      normalizePaymentTermsDays(row.payment_terms_days) ?? DEFAULT_PAYMENT_TERMS_DAYS,
    // `null` in the column = "not VAT-registered" — preserved verbatim. A
    // stored value that fails normalisation (corrupt cell) falls back to the
    // historical default so legacy ledgers stay readable.
    vatPeriodType:
      row.vat_period_type === null
        ? null
        : normalizeVatPeriodType(row.vat_period_type) ?? DEFAULT_VAT_PERIOD_TYPE,
  };
}

const DEFAULT_COMPANY_SETTINGS: CompanySettings = {
  id: 1,
  name: "Rentemester company",
  country: "DK",
  currency: "DKK",
  cvr: null,
  fiscalYearStartMonth: 1,
  fiscalYearLabelStrategy: "end-year",
  address: null,
  postalCode: null,
  city: null,
  companyForm: null,
  industryCode: null,
  industryText: null,
  cvrStatus: null,
  auditWaived: null,
  cvrSyncedAt: null,
  paymentTermsDays: DEFAULT_PAYMENT_TERMS_DAYS,
  // Keep the module's eager default independent of the close/VAT graph.
  // `periods.ts` imports the close-readiness graph, which eventually reads
  // company settings.  The value is the same canonical default exported from
  // that module; using the literal here prevents an ESM initialization cycle
  // from observing its export before initialization.
  vatPeriodType: "quarter",
};

function hasVatPeriodColumn(db: Database): boolean {
  const cols = db.query("PRAGMA table_info(companies)").all() as Array<{ name: string }>;
  return cols.some((col) => col.name === "vat_period_type");
}

export function normalizeCvr(value?: string | null): string | null {
  const trimmed = value?.trim();
  if (!trimmed) return null;
  const stripped = trimmed.toUpperCase().replace(/^DK/, "");
  if (!/^\d{8}$/.test(stripped)) {
    throw new Error(`CVR must be 8 digits (optionally prefixed with DK), got: ${value}`);
  }
  return `DK${stripped}`;
}

export function normalizeFiscalYearStartMonth(value?: number | string | null) {
  const month = typeof value === "string" ? Number(value) : value;
  if (!Number.isInteger(month) || (month ?? 0) < 1 || (month ?? 0) > 12) return null;
  return month;
}

export function normalizeFiscalYearLabelStrategy(value?: string | null): FiscalYearLabelStrategy | null {
  if (value === "end-year" || value === "start-year" || value === "span") return value;
  return null;
}

export function normalizePaymentTermsDays(value?: number | string | null): number | null {
  if (value === undefined || value === null || value === "") return null;
  const days = typeof value === "string" ? Number(value) : value;
  if (!Number.isInteger(days) || (days as number) < 0 || (days as number) > 365) return null;
  return days as number;
}

export function normalizeVatPeriodType(value?: string | null): VatPeriodType | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return VAT_PERIOD_TYPES.has(trimmed as VatPeriodType) ? (trimmed as VatPeriodType) : null;
}

humanAndLocalHelpers.source:
emitVatFiling = (ctx: CommandContext) => {
    const from = ctx.arg("--from");
    const to = ctx.arg("--to");
    if (!from || !to) {
      console.error("Missing required --from <YYYY-MM-DD> or --to <YYYY-MM-DD>");
      process.exit(2);
    }
    const db = openCommandDb(ctx);
    migrate(db);
    ensureVatRegistered(ctx, db);
    const result = buildVatFiling(db, from, to);
    emitHumanReport("vat-filing", result as Record<string, unknown>, ctx.outputFormat);
    db.close();
  }

function ensureVatRegistered(ctx: CommandContext, db: Database): void {
  const settings = getCompanySettings(db);
  if (settings.vatPeriodType !== null) return;
  ctx.emitResult({
    ok: false,
    errors: ["selskabet er ikke momsregistreret"],
  });
  db.close();
  process.exit(1);
}

