    reference: string | null;
  } | null;

  const periodStatus = period
    ? effectivePeriodState(db, period.id, period.status)
    : "open";

  // Resolve lifecycle before surfacing report-integrity failures. A closed
  // period with malformed legacy VAT data is still closed; labelling it open
  // would send the user down the wrong recovery path. The report's own
  // canonical deadline is used, so arbitrary bounds never gain a fake date.
  if (!vatReport.ok) {
    const reportErrors = [...vatReport.errors];
    if (!period || periodStatus === "open") {
      reportErrors.push(
        `VAT period ${periodStart}..${periodEnd} is not closed: a momsangivelse requires a closed or reported vat_period accounting period covering exactly this period — run 'period close --kind vat_period' first`,
      );
    }
    return failure(
      periodStart,
      periodEnd,
      periodStatus,
      reportErrors,
      vatReport,
      vatPeriodType,
      period?.reference ?? null,
    );
  }

  if (!period || periodStatus === "open") {
    return failure(
      periodStart,
      periodEnd,
      "open",
      [
        `VAT period ${periodStart}..${periodEnd} is not closed: a momsangivelse requires a closed or reported vat_period accounting period covering exactly this period — run 'period close --kind vat_period' first`,
      ],
      vatReport,
      vatPeriodType,
    );
  }

  // The shared projection keeps CLI/MCP/report/cockpit/export figures alike.
  const rubrikker = vatReport.rubrikker;
  // Moms af ydelseskøb i udlandet: reverse charge on EU service purchases.
  // Use the VAT *actually booked* on account 1200 per purchase, not
  // percentOfDkk(summed base, 25). Each purchase's VAT is øre-rounded when
  // booked, so the booked total can differ from 25%-of-aggregate by up to 1
  // øre per purchase. Using the booked figure keeps this rubrik equal to what
  // hit the ledger AND lets salgsmoms below come out as the exact own-sale VAT.
  const momsAfYdelseskobUdland = rubrikker.momsAfYdelseskobUdland;

  // Salgsmoms: output VAT on own sales only. buildVatReport.outputVat is
  // account-based (1200) and therefore includes the reverse-charge output VAT
  // booked by postEuServiceReverseChargePurchase — but on TastSelv that VAT
  // belongs exclusively in "Moms af ydelseskøb i udlandet" (momsloven §46 jf.
  // §37). Subtract the exact same ydelseskøb figure so the two rubrikker never
  // double-count and momstilsvar stays equal to the raw report's netVatPayable.
  // buildVatReport.outputVat already nets bad-debt relief out of output VAT.
  const salgsmoms = rubrikker.salgsmoms;

  // Moms af varekøb i udlandet: booked §11 EU-goods acquisition VAT. The
  // shared projection removes this exact amount from salgsmoms, so it appears
  // once and only once in the filing while momstilsvar remains the booked net.
  const momsAfVarekobUdland = rubrikker.momsAfVarekobUdland;

  // Købsmoms: total deductible input VAT (domestic + reverse-charge +
  // representation), already aggregated by buildVatReport.
  const kobsmoms = rubrikker.kobsmoms;

  // Momstilsvar = salgsmoms + udenlandsk moms − købsmoms.
  // Positive = payable to SKAT; negative = refund (negativt momstilsvar).
  const momstilsvar = rubrikker.momstilsvar;

  // Rubrik A: value of goods/services purchased abroad without Danish VAT.
  const rubrikA = rubrikker.rubrikA;
  // Rubrik B (JUR-2/KODE-2): value of goods/services SOLD ABROAD without Danish
  // VAT — cross-border EU B2B reverse-charge sales ONLY. This is the figure
  // cross-checked against the EU sales list (VIES), so only the FOREIGN reverse-
  // charge base belongs here. Domestic §46 omvendt betalingspligt is explicitly
  // excluded (it would otherwise inflate rubrik B and break the VIES reconciliation).
  const rubrikB = rubrikker.rubrikB;
  // Rubrik C: value of other VAT-exempt sales. Two sources, both derived from
  // real ledger data:
  //   1. §13-exempt domestic sales (DK_SALE_EXEMPT), and
  //   2. domestic §46 omvendt betalingspligt sales (DOMESTIC_REVERSE_CHARGE_EXEMPT,
  //      e.g. mobiltelefoner, CPU'er, metalskrot). SKAT Den juridiske vejledning
  //      A.B.3.3.1.5 places these in rubrik C ("værdi af andet salg uden moms"),
  //      NOT rubrik B.
  // OSS consumer sales (OSS_EU_CONSUMER) are deliberately NOT part of rubrik C:
  // they belong on the separate OSS return, so buildVatReport keeps them in their
  // own base and they never reach this momsangivelse.
  const rubrikC = rubrikker.rubrikC;

  return {
    ok: true,
    appliedRules: [FILING_RULE_ID],
    periodStart,
    periodEnd,
    vatPeriodType,
    periodStatus,
    periodReference: period.reference,
    filingDeadline: canonicalWindow.filingDeadline,
    rubrikker: {
      salgsmoms,
      momsAfVarekobUdland,
      momsAfYdelseskobUdland,
      kobsmoms,
      momstilsvar,
      rubrikA,
      rubrikB,
      rubrikC,
    },
    vatReport,
    warnings: [...vatReport.warnings],
    errors: [],
  };
}

export function getCompanySettings(db: Database): CompanySettings {
  // #289: older ledgers (and the base schema.sql) may lack `vat_period_type`.
  // Read it only when present; absent → fall back to the quarterly default so
  // a pre-#289 company is unaffected.
  const vatColumn = hasVatPeriodColumn(db) ? "vat_period_type" : "NULL AS vat_period_type";
  const row = db.query(
    `SELECT id, name, country, currency, cvr, fiscal_year_start_month, fiscal_year_label_strategy,
            address, postal_code, city, company_form, industry_code, industry_text,
            cvr_status, audit_waived, cvr_synced_at, payment_terms_days, ${vatColumn}
       FROM companies
      ORDER BY id ASC
      LIMIT 1`
  ).get() as {
    id: number;
    name: string;
    country: string;
    currency: string;
    cvr: string | null;
    fiscal_year_start_month: number;
    fiscal_year_label_strategy: FiscalYearLabelStrategy;
    address: string | null;
    postal_code: string | null;
    city: string | null;
    company_form: string | null;
    industry_code: string | null;
    industry_text: string | null;
    cvr_status: string | null;
    audit_waived: number | null;
    cvr_synced_at: string | null;
    payment_terms_days: number | null;
    vat_period_type: string | null;
  } | null;

  if (!row) return DEFAULT_COMPANY_SETTINGS;
  return {
    id: row.id,
    name: row.name,
    country: row.country,
    currency: row.currency,
    cvr: normalizeCvr(row.cvr),
    fiscalYearStartMonth: normalizeFiscalYearStartMonth(row.fiscal_year_start_month) ?? 1,
    fiscalYearLabelStrategy: normalizeFiscalYearLabelStrategy(row.fiscal_year_label_strategy) ?? "end-year",
    address: row.address,
    postalCode: row.postal_code,
    city: row.city,
    companyForm: row.company_form,
    industryCode: row.industry_code,
    industryText: row.industry_text,
    cvrStatus: row.cvr_status,
    auditWaived: row.audit_waived === null ? null : row.audit_waived === 1,
    cvrSyncedAt: row.cvr_synced_at,
    paymentTermsDays:
      normalizePaymentTermsDays(row.payment_terms_days) ?? DEFAULT_PAYMENT_TERMS_DAYS,
    // `null` in the column = "not VAT-registered" — preserved verbatim. A
    // stored value that fails normalisation (corrupt cell) falls back to the
    // historical default so legacy ledgers stay readable.
    vatPeriodType:
      row.vat_period_type === null
        ? null
        : normalizeVatPeriodType(row.vat_period_type) ?? DEFAULT_VAT_PERIOD_TYPE,
  };
}

const DEFAULT_COMPANY_SETTINGS: CompanySettings = {
  id: 1,
  name: "Rentemester company",
  country: "DK",
  currency: "DKK",
  cvr: null,
  fiscalYearStartMonth: 1,
  fiscalYearLabelStrategy: "end-year",
  address: null,
  postalCode: null,
  city: null,
  companyForm: null,
  industryCode: null,
  industryText: null,
  cvrStatus: null,
  auditWaived: null,
  cvrSyncedAt: null,
  paymentTermsDays: DEFAULT_PAYMENT_TERMS_DAYS,
  // Keep the module's eager default independent of the close/VAT graph.
  // `periods.ts` imports the close-readiness graph, which eventually reads
  // company settings.  The value is the same canonical default exported from
  // that module; using the literal here prevents an ESM initialization cycle
  // from observing its export before initialization.
  vatPeriodType: "quarter",
};

function hasVatPeriodColumn(db: Database): boolean {
  const cols = db.query("PRAGMA table_info(companies)").all() as Array<{ name: string }>;
  return cols.some((col) => col.name === "vat_period_type");
}

export function normalizeCvr(value?: string | null): string | null {
  const trimmed = value?.trim();
  if (!trimmed) return null;
  const stripped = trimmed.toUpperCase().replace(/^DK/, "");
  if (!/^\d{8}$/.test(stripped)) {
    throw new Error(`CVR must be 8 digits (optionally prefixed with DK), got: ${value}`);
  }
  return `DK${stripped}`;
}

export function normalizeFiscalYearStartMonth(value?: number | string | null) {
  const month = typeof value === "string" ? Number(value) : value;
  if (!Number.isInteger(month) || (month ?? 0) < 1 || (month ?? 0) > 12) return null;
  return month;
}

export function normalizeFiscalYearLabelStrategy(value?: string | null): FiscalYearLabelStrategy | null {
  if (value === "end-year" || value === "start-year" || value === "span") return value;
  return null;
}

export function normalizePaymentTermsDays(value?: number | string | null): number | null {
  if (value === undefined || value === null || value === "") return null;
  const days = typeof value === "string" ? Number(value) : value;
  if (!Number.isInteger(days) || (days as number) < 0 || (days as number) > 365) return null;
  return days as number;
}

export function normalizeVatPeriodType(value?: string | null): VatPeriodType | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return VAT_PERIOD_TYPES.has(trimmed as VatPeriodType) ? (trimmed as VatPeriodType) : null;
}

typeDeclarations.source:
export type VatFilingReport = {
  ok: boolean;
  appliedRules: string[];
  periodStart: string;
  periodEnd: string;
  /** Company's registered VAT cadence used for bounds and deadline. */
  vatPeriodType: VatPeriodType | null;
  /** Status of the matching accounting period: "open" when no final VAT period covers it exactly. */
  periodStatus: "open" | "closed" | "reported";
  /** Reference recorded on the closed accounting period, if any. */
  periodReference: string | null;
  /**
   * Cadence-aware SKAT filing/payment deadline (YYYY-MM-DD). `null` only for
   * a non-registered company or an invalid period end.
   */
  filingDeadline: string | null;
  rubrikker: VatFilingRubrikker;
  /** The underlying raw VAT report, for traceability. */
  vatReport: VatPeriodReport;
  warnings: string[];
  errors: string[];
};

export type VatRubric = {
  salgsmoms: number;
  momsAfVarekobUdland: number;
  momsAfYdelseskobUdland: number;
  kobsmoms: number;
  momstilsvar: number;
  rubrikA: number;
  rubrikB: number;
  rubrikC: number;
};

export type VatPeriodReport = {
  ok: boolean;
  appliedRules: string[];
  periodStart: string;
  periodEnd: string;
  /** Registered cadence, null for a non-registered company. */
  vatPeriodType: VatPeriodType | null;
  /** Deadline only when the requested bounds equal one canonical VAT period. */
  filingDeadline: string | null;
  outputVat: number;
  inputVat: number;
  netVatPayable: number;
  purchaseBase25: number;
  salesBase25: number;
  /**
   * Combined value of all VAT-exempt reverse-charge sales (domestic + foreign).
   * Kept for backwards compatibility and human display ("Salg med omvendt
   * betalingspligt"). For the momsangivelse the two must be split — see
   * foreignReverseChargeSalesBase / domesticReverseChargeSalesBase below.
   */
  reverseChargeSalesBase: number;
  /**
   * JUR-2/KODE-2: value of FOREIGN reverse-charge sales — cross-border EU B2B
   * sales without Danish VAT (vat_code REVERSE_CHARGE_EXEMPT). These feed rubrik
   * B of the momsangivelse and are cross-checked against the EU sales list (VIES).
   */
  foreignReverseChargeSalesBase: number;
  /**
   * JUR-2/KODE-2: value of DOMESTIC reverse-charge sales — Danish §46 omvendt
   * betalingspligt (mobiltelefoner, CPU'er, metalskrot; vat_code
   * DOMESTIC_REVERSE_CHARGE_EXEMPT). These carry no Danish output VAT and feed
   * rubrik C ("værdi af andet salg uden moms"), NOT rubrik B, and must never
   * appear on the VIES EU sales list. Source: SKAT Den juridiske vejledning
   * A.B.3.3.1.5.
   */
  domesticReverseChargeSalesBase: number;
  /** EU service reverse-charge purchase base only. This feeds rubrik A;
   * non-EU services are kept separate below. */
  reverseChargePurchaseBase: number;
  /** EU goods acquisitions (§11), kept separate from service purchases (§46). */
  euGoodsAcquisitionPurchaseBase: number;
  /** Output VAT arising from §11 goods acquisitions, for the goods rubric. */
  euGoodsAcquisitionOutputVat: number;
  /** Service-purchase base from suppliers outside the EU. It contributes to
   * foreign-service reverse-charge VAT, but never to EU-only rubrik A. */
  nonEuServiceReverseChargePurchaseBase: number;
  /**
   * Output VAT allocated to foreign-service reverse charge (EU and non-EU).
   * A dedicated, source-proven VAT account supplies its booked amount; ledgers
   * where ordinary and reverse-charge output VAT share one account use the
   * øre-rounded VAT expected from each reverse-charge base line. The report
   * reconciles this category independently before it can be filed.
   */
  reverseChargePurchaseOutputVat: number;
  representationPurchaseBase: number;
  badDebtReliefBase25: number;
  /**
   * Value of VAT-exempt domestic sales (momsloven §13 — vat_code
   * DK_SALE_EXEMPT). These carry no output VAT and feed rubrik C of the
   * momsangivelse; they are kept out of the standard 25% sales base.
   */
  exemptSalesBase: number;
  /**
   * Value of digital-service sales to EU consumers handled under the OSS
   * scheme (vat_code OSS_EU_CONSUMER). These carry no Danish output VAT and
   * are reported via a separate OSS return — they are kept out of every
   * standard momsangivelse rubrik. See src/core/vat-oss.ts.
   */
  ossConsumerSalesBase: number;
  /** Number of journal entries that include an OSS_EU_CONSUMER line. */
  ossConsumerSalesEntryCount: number;
  journalEntryCount: number;
  reversedJournalEntryCount: number;
  reversalJournalEntryCount: number;
  totalJournalEntryCount: number;
  linesConsidered: number;
  reversedLinesConsidered: number;
  reversalLinesConsidered: number;
  totalLinesConsidered: number;
  /** Canonical SKAT rubric projection shared by report, filing and exports. */
  rubrikker: VatRubric;
  warnings: string[];
  errors: string[];
};

export type CompanySettings = {
  id: number;
  name: string;
  country: string;
  currency: string;
  cvr: string | null;
  fiscalYearStartMonth: number;
  fiscalYearLabelStrategy: FiscalYearLabelStrategy;
  /** CVR-register stamdata, last written by `company sync-cvr`. */
  address: string | null;
  postalCode: string | null;
  city: string | null;
  companyForm: string | null;
  industryCode: string | null;
  industryText: string | null;
  cvrStatus: string | null;
  auditWaived: boolean | null;
  /** ISO timestamp the CVR stamdata above was last synced; null when never. */
  cvrSyncedAt: string | null;
  /**
   * #221: the owner's own default payment terms — days from an invoice's issue
   * date to its due date. Captured once so every issued invoice inherits it.
   */
  paymentTermsDays: number;
  /**
   * #289: the VAT settlement cadence the company is registered for with SKAT
   * (`month` / `quarter` / `half-year`). Drives VAT period windows and their
   * filing deadlines. `null` means the company is NOT VAT-registered
   * (holding ApS, frivilligt momsfritaget, mikrovirksomhed under § 48); every
   * VAT-aware surface (dashboard, obligations, momsangivelse) gates on this.
   */
  vatPeriodType: VatPeriodType | null;
};

definition.exactParser:
const BOOLEAN_FLAGS = new Set([
  "--force",
  "--help",
  "--example",
  "--json",
  "--sign-with-ed25519",
  "--archive",
  "--enrich-cvr",
  "--include-archived",
  "--ixbrl-taxonomy",
  "--after-retention-expiry",
  "--no-vat",
  "--no-open",
]);

export type ParsedCliArgs = {
  positionals: string[];
  flags: Map<string, string | true>;
  errors: string[];
};

export function parseCliArgs(argv: string[]): ParsedCliArgs {
  const tokens = argv.slice(2);
  const positionals: string[] = [];
  const flags = new Map<string, string | true>();
  const errors: string[] = [];

  let optionsTerminated = false;

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i]!;

    if (!optionsTerminated && token === "--") {
      optionsTerminated = true;
      continue;
    }

    if (optionsTerminated || !token.startsWith("--")) {
      positionals.push(token);
      continue;
    }

    // `--flag=value` form: value is attached, so it may begin with dashes
    // or be empty without being confused for a missing-value error.
    const eq = token.indexOf("=");
    if (eq !== -1) {
      const name = token.slice(0, eq);
      const value = token.slice(eq + 1);
      if (BOOLEAN_FLAGS.has(name)) {
        errors.push(`Flag ${name} does not take a value`);
        continue;
      }
      flags.set(name, value);
      continue;
    }

    if (BOOLEAN_FLAGS.has(token)) {
      const next = tokens[i + 1];
      if (next && next !== "--" && !next.startsWith("--")) {
        errors.push(`Flag ${token} does not take a value`);
        i += 1;
        continue;
      }
      flags.set(token, true);
      continue;
    }

    const value = tokens[i + 1];
    if (value === undefined || value === "--" || value.startsWith("--")) {
      errors.push(`Flag ${token} requires a value`);
      continue;
    }
    flags.set(token, value);
    i += 1;
  }

  return { positionals, flags, errors };
}

