    "",
  ];

  return { to, from, subject, messageId, rawMessage: lines.join("\r\n") };
}

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[]
): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  bindings: SQLQueryBindings[],
): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[] | [SQLQueryBindings[]]
): ReturnType<Database["run"]> {
  const normalized = bindings.length === 1 && Array.isArray(bindings[0])
    ? bindings[0]
    : bindings as SQLQueryBindings[];
  return db.run(sql, normalized);
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

export function createSmtpTransport(config: SmtpConfig): EmailTransport {
  return {
    send(message: EmailMessage): EmailTransportResult {
      if (config.dryRun) {
        return { ok: true, messageId: message.messageId };
      }
      // A real network send is intentionally out of scope for this slice —
      // the injected transport is the supported production seam. Callers that
      // need live delivery wire their own transport against `EmailTransport`.
      return {
        ok: false,
        error:
          "the built-in SMTP transport runs in dryRun only; inject a live EmailTransport for real delivery",
      };
    },
  };
}

