function readSubject(ctx: CommandContext): {
  cvr: string | null;
  name: string | null;
  asOf: string | null;
} {
  // `--subject` is the ROADMAP-facing alias; `--cvr` is the legacy name.
  return {
    cvr: ctx.arg("--cvr") ?? ctx.arg("--subject") ?? null,
    name: ctx.arg("--name") ?? null,
    asOf: ctx.arg("--as-of") ?? null,
  };
}

function cliAuditActor(ctx: CommandContext): {
  createdBy: string;
  createdByProgram: string;
} {
  const createdBy =
    ctx.cliActor ?? process.env.RENTEMESTER_ACTOR ?? ctx.inferredMutationActor();
  if (!createdBy) ctx.fatal("actor required for mutations");
  return {
    createdBy,
    createdByProgram:
      ctx.cliActorVia ??
      process.env.RENTEMESTER_ACTOR_VIA ??
      "rentemester-cli",
  };
}

definition.handler:
(ctx) => {
    const db = openCommandDb(ctx);
    migrate(db);
    const result = findGdprSubject(db, readSubject(ctx), cliAuditActor(ctx));
    ctx.emitResult(result as unknown as Record<string, unknown>);
    db.close();
    if (!result.ok) process.exit(1);
  }

