export function buildAnnualReport(
  db: Database,
  fiscalYearStart: string,
  fiscalYearEnd: string,
): AnnualReport {
  const profitAndLoss = buildProfitAndLoss(db, fiscalYearStart, fiscalYearEnd);
  const balanceSheet = buildBalanceSheet(db, fiscalYearEnd);

  // 1. Date validation. Surface the underlying report errors verbatim.
  if (!looksLikeIsoDate(fiscalYearStart) || !looksLikeIsoDate(fiscalYearEnd)) {
    return failure(
      fiscalYearStart,
      fiscalYearEnd,
      emptyCompany(),
      ["fiscalYearStart and fiscalYearEnd must be YYYY-MM-DD"],
      profitAndLoss,
      balanceSheet,
    );
  }
  if (fiscalYearStart > fiscalYearEnd) {
    return failure(
      fiscalYearStart,
      fiscalYearEnd,
      emptyCompany(),
      ["fiscalYearStart must be before or equal to fiscalYearEnd"],
      profitAndLoss,
      balanceSheet,
    );
  }

  const errors: string[] = [];

  // 2. Company master data: a registered CVR is mandatory for an arsrapport.
  const companyRow = db
    .query(`SELECT name, country, currency, cvr FROM companies ORDER BY id ASC LIMIT 1`)
    .get() as CompanyRow | null;
  const company: AnnualReportCompany = {
    name: companyRow?.name ?? "",
    cvr: companyRow?.cvr ?? "",
    country: companyRow?.country ?? "DK",
    currency: companyRow?.currency ?? "DKK",
  };
  if (!companyRow) {
    errors.push("virksomhedens stamdata mangler — initialisér virksomheden først");
  } else if (!companyRow.cvr || !/^DK\d{8}$/.test(companyRow.cvr)) {
    errors.push(
      "virksomhedens CVR-nummer mangler eller er ugyldigt — en årsrapport kræver et registreret 8-cifret CVR-nummer",
    );
  }

  // 3. The fiscal year must be fully locked: a single closed or reported
  // accounting period whose bounds cover the requested year exactly or wider.
  // A still-open year, or a year only partially covered by locked periods,
  // must not be turned into a reportable arsrapport.
  const lockingPeriod = db
    .query(
      `SELECT period_start, period_end, kind, status
         FROM accounting_periods
        WHERE period_start <= ? AND period_end >= ?
          AND status IN ('closed', 'reported')
        ORDER BY period_end ASC, id ASC
        LIMIT 1`,
    )
    .get(fiscalYearStart, fiscalYearEnd) as PeriodRow | null;
  if (!lockingPeriod) {
    errors.push(
      `regnskabsåret ${fiscalYearStart}..${fiscalYearEnd} er ikke låst: en årsrapport ` +
        "kræver en lukket eller indberettet regnskabsperiode, der dækker hele " +
        "regnskabsåret — kør 'period close' først",
    );
  }

  // 4. Books must balance for the fiscal year (double-entry integrity).
  const trialBalance = buildTrialBalance(db, fiscalYearStart, fiscalYearEnd);
  if (trialBalance.ok && !trialBalance.balanced) {
    errors.push(
      `bøgerne balancerer ikke for ${fiscalYearStart}..${fiscalYearEnd}: ` +
        `samlet debet ${trialBalance.totalDebit} != samlet kredit ${trialBalance.totalCredit}`,
    );
  }
  if (!profitAndLoss.ok) errors.push(...profitAndLoss.errors);
  if (!balanceSheet.ok) errors.push(...balanceSheet.errors);

  if (errors.length > 0) {
    return failure(fiscalYearStart, fiscalYearEnd, company, errors, profitAndLoss, balanceSheet);
  }

  return {
    ok: true,
    appliedRules: [ANNUAL_REPORT_RULE_ID],
    regnskabsklasse: "B",
    fiscalYearStart,
    fiscalYearEnd,
    company,
    profitAndLoss,
    balanceSheet,
    aretsResultat: profitAndLoss.result,
    comparison: buildComparison(db, fiscalYearStart, fiscalYearEnd),
    notes: buildNotesSkeleton(),
    ledelsespategning: buildLedelsespategning(fiscalYearEnd),
    preparedBy: "Rentemester",
    disclaimer: DISCLAIMER,
    errors: [],
  };
}

const DISCLAIMER =
  "Rentemester forbereder denne arsrapport ud fra det lukkede regnskabsaar. " +
  "Ejer eller revisor gennemgar og er ansvarlig for indberetning til Erhvervsstyrelsen.";

export function buildProfitAndLoss(
  db: Database,
  periodStart: string,
  periodEnd: string,
): ProfitAndLossReport {
  const errors = validatePeriod(periodStart, periodEnd);
  if (errors.length > 0) {
    return {
      ok: false,
      appliedRules: [PROFIT_AND_LOSS_REPORT_ID],
      periodStart,
      periodEnd,
      income: [],
      expense: [],
      totalIncome: 0,
      totalExpense: 0,
      result: 0,
      errors,
    };
  }

  const tb = buildTrialBalance(db, periodStart, periodEnd);

  const income: StatementLine[] = [];
  const expense: StatementLine[] = [];
  let totalIncomeOre = 0n;
  let totalExpenseOre = 0n;

  for (const acc of tb.accounts) {
    if (acc.type === "income") {
      // credit − debit (negate the debit-signed trial-balance balance).
      const amountOre = -toOre(acc.balance);
      totalIncomeOre += amountOre;
      income.push({ accountNo: acc.accountNo, name: acc.name, type: acc.type, amount: fromOre(amountOre) });
    } else if (acc.type === "expense") {
      // debit − credit (already the trial-balance balance sign).
      const amountOre = toOre(acc.balance);
      totalExpenseOre += amountOre;
      expense.push({ accountNo: acc.accountNo, name: acc.name, type: acc.type, amount: fromOre(amountOre) });
    }
  }

  return {
    ok: true,
    appliedRules: [PROFIT_AND_LOSS_REPORT_ID],
    periodStart,
    periodEnd,
    income,
    expense,
    totalIncome: fromOre(totalIncomeOre),
    totalExpense: fromOre(totalExpenseOre),
    result: fromOre(totalIncomeOre - totalExpenseOre),
    errors: [],
  };
}

export function buildBalanceSheet(db: Database, asOfDate: string): BalanceSheetReport {
  const errors: string[] = [];
  if (!looksLikeIsoDate(asOfDate)) errors.push("asOfDate must be YYYY-MM-DD");
  if (errors.length > 0) {
    return {
      ok: false,
      appliedRules: [BALANCE_SHEET_REPORT_ID],
      asOfDate,
      assets: { lines: [], total: 0 },
      liabilities: { lines: [], total: 0 },
      equity: { lines: [], total: 0 },
      periodResult: 0,
      totalAssets: 0,
      totalLiabilitiesAndEquity: 0,
      balanced: false,
      errors,
    };
  }

  // The earliest possible ISO date as an inclusive lower bound; the trial
  // balance helper handles the upper bound and the per-account aggregation.
  const tb = buildTrialBalance(db, "0000-01-01", asOfDate);

  const assets: StatementLine[] = [];
  const liabilities: StatementLine[] = [];
  const equity: StatementLine[] = [];
  let totalAssetsOre = 0n;
  let totalLiabilitiesOre = 0n;
  let totalEquityOre = 0n;
  let periodResultOre = 0n;

  for (const acc of tb.accounts) {
    const debitSignedOre = toOre(acc.balance); // debit − credit
    // The statement section an account belongs to — the shared classification
    // (#321), so the live sheet and the archive-aware views never disagree.
    const section = classifyAccountSection(acc.type, acc.normalBalance);
    if (section === "asset") {
      totalAssetsOre += debitSignedOre;
      assets.push({ accountNo: acc.accountNo, name: acc.name, type: acc.type, amount: fromOre(debitSignedOre) });
    } else if (section === "liability") {
      const creditSignedOre = -debitSignedOre;
      totalLiabilitiesOre += creditSignedOre;
      liabilities.push({ accountNo: acc.accountNo, name: acc.name, type: acc.type, amount: fromOre(creditSignedOre) });
    } else if (section === "equity") {
      const creditSignedOre = -debitSignedOre;
      totalEquityOre += creditSignedOre;
      equity.push({ accountNo: acc.accountNo, name: acc.name, type: acc.type, amount: fromOre(creditSignedOre) });
    } else if (section === "income") {
      // credit − debit contributes positively to the result.
      periodResultOre += -debitSignedOre;
    } else if (section === "expense") {
      periodResultOre -= debitSignedOre;
    }
  }

  const totalAssets = fromOre(totalAssetsOre);
  const totalLiabilitiesAndEquityOre = totalLiabilitiesOre + totalEquityOre + periodResultOre;
  const totalLiabilitiesAndEquity = fromOre(totalLiabilitiesAndEquityOre);

  return {
    ok: true,
    appliedRules: [BALANCE_SHEET_REPORT_ID],
    asOfDate,
    assets: { lines: assets, total: totalAssets },
    liabilities: { lines: liabilities, total: fromOre(totalLiabilitiesOre) },
    equity: { lines: equity, total: fromOre(totalEquityOre) },
    periodResult: fromOre(periodResultOre),
    totalAssets,
    totalLiabilitiesAndEquity,
    balanced: equalsOre(totalAssets, totalLiabilitiesAndEquity),
    errors: [],
  };
}

export function isValidIsoDate(value: unknown): value is string {
  if (typeof value !== "string") return false;
  const trimmed = value.trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return false;
  const date = new Date(`${trimmed}T00:00:00Z`);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === trimmed;
}

function emptyCompany(): AnnualReportCompany {
  return { name: "", cvr: "", country: "DK", currency: "DKK" };
}

export function buildTrialBalance(
  db: Database,
  periodStart: string,
  periodEnd: string,
): TrialBalanceReport {
  const errors = validatePeriod(periodStart, periodEnd);
  if (errors.length > 0) {
    return {
      ok: false,
      appliedRules: [TRIAL_BALANCE_REPORT_ID],
      periodStart,
      periodEnd,
      accounts: [],
      totalDebit: 0,
      totalCredit: 0,
      balanced: false,
      linesConsidered: 0,
      journalEntryCount: 0,
      errors,
    };
  }

  const rows = selectLinesInPeriod(db, periodStart, periodEnd);

  // Accumulate debit/credit per account in integer øre to avoid float drift.
  type Acc = {
    accountNo: string;
    name: string;
    type: AccountType;
    normalBalance: "debit" | "credit";
    debitOre: bigint;
    creditOre: bigint;
  };
  const byAccount = new Map<string, Acc>();
  const entryIds = new Set<number>();
  let totalDebitOre = 0n;
  let totalCreditOre = 0n;

  for (const row of rows) {
    entryIds.add(row.entry_id);
    let acc = byAccount.get(row.account_no);
    if (!acc) {
      acc = {
        accountNo: row.account_no,
        name: row.account_name,
        type: row.account_type,
        normalBalance: row.normal_balance,
        debitOre: 0n,
        creditOre: 0n,
      };
      byAccount.set(row.account_no, acc);
    }
    const debitOre = toOre(Number(row.debit_amount ?? 0));
    const creditOre = toOre(Number(row.credit_amount ?? 0));
    acc.debitOre += debitOre;
    acc.creditOre += creditOre;
    totalDebitOre += debitOre;
    totalCreditOre += creditOre;
  }

  const accounts: TrialBalanceAccount[] = [...byAccount.values()]
    .sort((a, b) => (a.accountNo < b.accountNo ? -1 : a.accountNo > b.accountNo ? 1 : 0))
    .map((acc) => ({
      accountNo: acc.accountNo,
      name: acc.name,
      type: acc.type,
      normalBalance: acc.normalBalance,
      debit: fromOre(acc.debitOre),
      credit: fromOre(acc.creditOre),
      balance: fromOre(acc.debitOre - acc.creditOre),
    }));

  return {
    ok: true,
    appliedRules: [TRIAL_BALANCE_REPORT_ID],
    periodStart,
    periodEnd,
    accounts,
    totalDebit: fromOre(totalDebitOre),
    totalCredit: fromOre(totalCreditOre),
    balanced: totalDebitOre === totalCreditOre,
    linesConsidered: rows.length,
    journalEntryCount: entryIds.size,
    errors: [],
  };
}

function buildComparison(db: Database, start: string, end: string): AnnualReportComparison {
  const prior = priorFiscalYear(start, end);
  const pl = buildProfitAndLoss(db, prior.start, prior.end);
  const bs = buildBalanceSheet(db, prior.end);
  if (!pl.ok || !bs.ok) return ZERO_COMPARISON(prior.start, prior.end);
  const equity = bs.equity.total + bs.periodResult;
  const available =
    pl.totalIncome !== 0 ||
    pl.totalExpense !== 0 ||
    bs.totalAssets !== 0 ||
    bs.totalLiabilitiesAndEquity !== 0;
  return {
    fiscalYearStart: prior.start,
    fiscalYearEnd: prior.end,
    available,
    totalIncome: pl.totalIncome,
    totalExpense: pl.totalExpense,
    aretsResultat: pl.result,
    totalAssets: bs.totalAssets,
    totalLiabilitiesAndEquity: bs.totalLiabilitiesAndEquity,
    equity,
  };
}

function buildNotesSkeleton(): AnnualReportNote[] {
  return [
    {
      id: "accounting-policies",
      title: "Anvendt regnskabspraksis",
      body:
        "Arsrapporten er aflagt efter arsregnskabslovens bestemmelser for " +
        "regnskabsklasse B. Udfyldes/gennemgas af ejer eller revisor.",
      placeholder: true,
    },
    {
      id: "staff-costs",
      title: "Personaleomkostninger",
      body: "Note-skelet. Udfyldes af ejer eller revisor.",
      placeholder: true,
    },
    {
      // ÅRL §24/§24a: a class-B arsrapport states the average number of
      // employees for the financial year. Rentemester holds no payroll data,
      // so this is a placeholder the owner/advisor fills in.
      id: "average-employees",
      title: "Gennemsnitligt antal beskæftigede",
      body:
        "Oplys det gennemsnitlige antal beskæftigede i regnskabsåret " +
        "(årsregnskabslovens §24). Rentemester har ingen løndata — udfyldes af " +
        "ejer eller revisor.",
      placeholder: true,
    },
    {
      id: "equity",
      title: "Egenkapital",
      body: "Note-skelet for egenkapitalens bevaegelser. Udfyldes af ejer eller revisor.",
      placeholder: true,
    },
    {
      id: "subsequent-events",
      title: "Begivenheder efter balancedagen",
      body: "Note-skelet. Udfyldes af ejer eller revisor.",
      placeholder: true,
    },
  ];
}

function buildLedelsespategning(fiscalYearEnd: string): AnnualReportLedelsespategning {
  return {
    placeholder: true,
    text:
      "Ledelsen har dags dato behandlet og godkendt årsrapporten for " +
      `regnskabsåret, der slutter ${fiscalYearEnd}. Dette er en skabelon — ` +
      "ledelsen indsætter dato, sted og underskrifter inden indberetning.",
  };
}

export function generateIxbrl(report: AnnualReport): GenerateIxbrlResult {
  const taxonomy = {
    name: IXBRL_TAXONOMY_SUBSET.name,
    version: IXBRL_TAXONOMY_SUBSET.version,
  };
  const fail = (errors: string[]): GenerateIxbrlResult => ({
    ok: false,
    appliedRules: [IXBRL_RULE_ID],
    xhtml: "",
    sha256: "",
    facts: [],
    taxonomy,
    errors,
  });

  if (!report.ok) {
    return fail([
      "cannot generate iXBRL: the annual report did not pass its prerequisites",
      ...report.errors,
    ]);
  }

  const cvrDigits = report.company.cvr.replace(/^DK/, "");
  if (!/^\d{8}$/.test(cvrDigits)) {
    return fail([
      "cannot generate iXBRL: a registered 8-digit CVR is required for the xbrli context",
    ]);
  }

  const { facts, errors } = resolveFacts(report);
  if (errors.length > 0) {
    return fail(errors);
  }

  const ns = IXBRL_TAXONOMY_SUBSET.namespace;

  // Render the declared facts grouped by section, in the fixed SECTION_ORDER.
  // Each section is a self-contained <table> under a Danish <h2> heading.
  const sectionBlocks = SECTION_ORDER.map(({ section, heading }) => {
    const rows = facts
      .filter((f) => f.element.section === section)
      .map(renderFactRow)
      .join("\n");
    return [`    <h2>${escapeXml(heading)}</h2>`, "    <table>", rows, "    </table>"].join("\n");
  }).join("\n");

  const noteRows = report.notes
    .map(
      (note) =>
        `    <tr><th>${escapeXml(note.title)}</th><td>${escapeXml(note.body)}</td></tr>`,
    )
    .join("\n");

  // Prior-year comparison figures (ÅRL §24). Rendered as a plain human-readable
  // table — they are NOT emitted as ix: facts because the bounded taxonomy
  // subset declares only the current-year context. A "—" is shown when the
  // preceding year had no activity (a genuine first-year report).
  const cmp = report.comparison;
  const m = (value: number): string => formatAmount(value) ?? "0.00";
  const cmpCell = (value: number): string => (cmp.available ? escapeXml(m(value)) : "—");
  const comparisonBlock = [
    `    <h2>Sammenligningstal (foregaaende regnskabsaar ${escapeXml(cmp.fiscalYearStart)} — ${escapeXml(cmp.fiscalYearEnd)})</h2>`,
    "    <table>",
    `    <tr><th>Nettoomsaetning</th><td>${cmpCell(cmp.totalIncome)}</td></tr>`,
    `    <tr><th>Omkostninger</th><td>${cmpCell(cmp.totalExpense)}</td></tr>`,
    `    <tr><th>Aarets resultat</th><td>${cmpCell(cmp.aretsResultat)}</td></tr>`,
    `    <tr><th>Aktiver i alt</th><td>${cmpCell(cmp.totalAssets)}</td></tr>`,
    `    <tr><th>Egenkapital i alt</th><td>${cmpCell(cmp.equity)}</td></tr>`,
    `    <tr><th>Passiver i alt</th><td>${cmpCell(cmp.totalLiabilitiesAndEquity)}</td></tr>`,
    "    </table>",
  ].join("\n");

  // The average-employees note (ÅRL §24) surfaced explicitly. Sourced from the
  // notes skeleton so the iXBRL stays in lock-step with the assembled report.
  const employeesNote = report.notes.find((n) => n.id === "average-employees");
  const employeesBlock = [
    "    <h2>Gennemsnitligt antal beskaeftigede</h2>",
    "    <table>",
    `    <tr><th>${escapeXml(employeesNote?.title ?? "Gennemsnitligt antal beskaeftigede")}</th>` +
      `<td>${escapeXml(employeesNote?.body ?? "Udfyldes af ejer eller revisor.")}</td></tr>`,
    "    </table>",
  ].join("\n");

  // The iXBRL hidden header carries the two xbrli contexts and the DKK unit:
  //  - `duration` spans the fiscal year (income statement, company info);
  //  - `instant` is the balance-sheet date (the fiscal-year end).
  // The context dates come straight from the (already final) fiscal year, so
  // the document is fully determined by its input.
  const xhtml = [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<html xmlns="http://www.w3.org/1999/xhtml"',
    '      xmlns:ix="http://www.xbrl.org/2013/inlineXBRL"',
    '      xmlns:xbrli="http://www.xbrl.org/2003/instance"',
    `      xmlns:ar="${escapeXml(ns)}">`,
    "  <head>",
    "    <title>Arsrapport (regnskabsklasse B) — forberedt af Rentemester</title>",
    `    <meta name="rentemester-ixbrl-taxonomy" content="${escapeXml(taxonomy.name)} v${escapeXml(taxonomy.version)}"/>`,
    "  </head>",
    "  <body>",
    '    <div style="display:none">',
    '      <ix:header>',
    '        <ix:references/>',
    '        <ix:resources>',
    '          <xbrli:context id="duration">',
    "            <xbrli:entity>",
    `              <xbrli:identifier scheme="http://www.cvr.dk">${escapeXml(cvrDigits)}</xbrli:identifier>`,
    "            </xbrli:entity>",
    "            <xbrli:period>",
    `              <xbrli:startDate>${escapeXml(report.fiscalYearStart)}</xbrli:startDate>`,
    `              <xbrli:endDate>${escapeXml(report.fiscalYearEnd)}</xbrli:endDate>`,
    "            </xbrli:period>",
    "          </xbrli:context>",
    '          <xbrli:context id="instant">',
    "            <xbrli:entity>",
    `              <xbrli:identifier scheme="http://www.cvr.dk">${escapeXml(cvrDigits)}</xbrli:identifier>`,
    "            </xbrli:entity>",
    "            <xbrli:period>",
    `              <xbrli:instant>${escapeXml(report.fiscalYearEnd)}</xbrli:instant>`,
    "            </xbrli:period>",
    "          </xbrli:context>",
    '          <xbrli:unit id="DKK">',
    "            <xbrli:measure>iso4217:DKK</xbrli:measure>",
    "          </xbrli:unit>",
    "        </ix:resources>",
    "      </ix:header>",
    "    </div>",
    `    <h1>Arsrapport ${escapeXml(report.fiscalYearStart)} — ${escapeXml(report.fiscalYearEnd)}</h1>`,
    "    <p>Regnskabsklasse B (micro/small). Forberedt af Rentemester; " +
      "ejer eller revisor gennemgar og indberetter.</p>",
    `    <p>iXBRL-taksonomi: ${escapeXml(taxonomy.name)} v${escapeXml(taxonomy.version)} ` +
      "— et afgraenset udsnit under det rentemester-lokale `ar:`-namespace, IKKE " +
      "Erhvervsstyrelsens officielle taksonomi. Dokumentet kan derfor IKKE " +
      "indberettes digitalt til Erhvervsstyrelsen/Virk endnu; det er en forberedt " +
      "arsrapport til gennemsyn.</p>",
    sectionBlocks,
    comparisonBlock,
    employeesBlock,
    "    <h2>Noter (skelet)</h2>",
    "    <table>",
    noteRows,
    "    </table>",
    "  </body>",
    "</html>",
    "",
  ].join("\n");

  return {
    ok: true,
    appliedRules: [IXBRL_RULE_ID],
    xhtml,
    sha256: createHash("sha256").update(xhtml).digest("hex"),
    facts,
    taxonomy,
    errors: [],
  };
}

const fail = (errors: string[]): GenerateIxbrlResult => ({
    ok: false,
    appliedRules: [IXBRL_RULE_ID],
    xhtml: "",
    sha256: "",
    facts: [],
    taxonomy,
    errors,
  });

function resolveFacts(report: AnnualReport): { facts: ResolvedFact[]; errors: string[] } {
  const errors: string[] = [];
  // Money is rendered via the integer-ore formatter, never raw floats.
  const m = (value: number): string => formatAmount(value) ?? "0.00";

  const pl = report.profitAndLoss;
  const bs = report.balanceSheet;
  // The balance sheet splits equity into a carried-in part (`equity.total`) and
  // the un-closed period result (`periodResult`). Total equity is their sum;
  // it must reconcile to assets − liabilities on a balanced sheet.
  const totalEquity = bs.equity.total + bs.periodResult;
  // Gross result = revenue − other external costs (the only P&L lines this
  // micro/small slice models). Ordinary operating result mirrors it: the slice
  // has no financial items, so both equal the year's result here. They are
  // still distinct declared elements so the document keeps the class-B shape.
  const grossResult = pl.totalIncome - pl.totalExpense;

  // The accounting-policies fact is sourced from the notes skeleton so the
  // iXBRL stays in lock-step with the assembled report. Falls back to a clear
  // placeholder if the (bounded) skeleton ever drops the note.
  const policiesNote = report.notes.find((n) => n.id === "accounting-policies");
  const accountingPolicies =
    policiesNote?.body ??
    "Anvendt regnskabspraksis udfyldes af ejer eller revisor.";

  const values: Record<string, string> = {
    "ar:CompanyName": report.company.name,
    "ar:RegistreredCvr": report.company.cvr,
    "ar:ReportingPeriodStartDate": report.fiscalYearStart,
    "ar:ReportingPeriodEndDate": report.fiscalYearEnd,
    "ar:ReportingClass": report.regnskabsklasse,
    "ar:Revenue": m(pl.totalIncome),
    "ar:OtherOperatingExpenses": m(pl.totalExpense),
    "ar:GrossResult": m(grossResult),
    "ar:ProfitLossFromOrdinaryOperatingActivities": m(grossResult),
    "ar:ProfitLossForYear": m(report.aretsResultat),
    "ar:NoncurrentAssets": m(noncurrentAssets(bs)),
    "ar:CurrentAssets": m(currentAssets(bs)),
    "ar:Assets": m(bs.totalAssets),
    "ar:ContributedCapital": m(bs.equity.total),
    "ar:RetainedEarnings": m(bs.periodResult),
    "ar:Equity": m(totalEquity),
    "ar:Liabilities": m(bs.liabilities.total),
    "ar:LiabilitiesAndEquity": m(bs.totalLiabilitiesAndEquity),
    "ar:ManagementStatement": report.ledelsespategning.text,
    "ar:AccountingPolicies": accountingPolicies,
  };

  const facts: ResolvedFact[] = [];
  // Iterate the declared subset so the fact order is fixed and bounded.
  for (const element of IXBRL_TAXONOMY_SUBSET.elements) {
    const value = values[element.name];
    if (value === undefined) {
      errors.push(`iXBRL: declared element ${element.name} has no mapping`);
      continue;
    }
    facts.push({ element, value });
  }
  return { facts, errors };
}

function escapeXml(value: string | number | null | undefined): string {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

export function formatAmount(value: number | string | bigint | null | undefined): string | null {
  if (value == null || value === "") return null;
  let ore: bigint;
  if (typeof value === "bigint") {
    ore = value;
  } else {
    const num = typeof value === "number" ? value : Number(value);
    if (!Number.isFinite(num)) return null;
    ore = toOre(num);
  }
  const negative = ore < 0n;
  const abs = negative ? -ore : ore;
  const whole = abs / 100n;
  const fraction = abs % 100n;
  const fractionText = fraction.toString().padStart(2, "0");
  return `${negative ? "-" : ""}${whole.toString()}.${fractionText}`;
}

typeDeclarations.source:
export type AnnualReport = {
  ok: boolean;
  appliedRules: string[];
  /** Always "B" — this slice only covers regnskabsklasse B (micro/small). */
  regnskabsklasse: "B";
  fiscalYearStart: string;
  fiscalYearEnd: string;
  company: AnnualReportCompany;
  /** Resultatopgorelse for the fiscal year (reused from #176). */
  profitAndLoss: ProfitAndLossReport;
  /** Balance as of the fiscal-year end (reused from #176). */
  balanceSheet: BalanceSheetReport;
  /** Aarets resultat — the year's net result, DKK. Mirrors profitAndLoss.result. */
  aretsResultat: number;
  /**
   * Prior-year comparison figures (ÅRL §24). Present whenever the report is
   * assembled so the resultatopgorelse and balance can show both years.
   */
  comparison: AnnualReportComparison;
  /** Notes skeleton — placeholders the owner/advisor completes. */
  notes: AnnualReportNote[];
  ledelsespategning: AnnualReportLedelsespategning;
  /** Conservative claim: who prepared the report. */
  preparedBy: "Rentemester";
  /** Conservative-language disclaimer (Danish). */
  disclaimer: string;
  errors: string[];
};

export type AnnualReportCompany = {
  name: string;
  cvr: string;
  country: string;
  currency: string;
};

export type ProfitAndLossReport = {
  ok: boolean;
  appliedRules: string[];
  periodStart: string;
  periodEnd: string;
  income: StatementLine[];
  expense: StatementLine[];
  totalIncome: number;
  totalExpense: number;
  /** totalIncome − totalExpense, DKK. Positive is a profit. */
  result: number;
  errors: string[];
};

export type StatementLine = {
  accountNo: string;
  name: string;
  type: AccountType;
  /** Amount in the statement's natural sign convention, DKK. */
  amount: number;
};

export type BalanceSheetReport = {
  ok: boolean;
  appliedRules: string[];
  asOfDate: string;
  assets: BalanceSheetSection;
  liabilities: BalanceSheetSection;
  /** Equity excluding the un-closed period result. */
  equity: BalanceSheetSection;
  /** Income − expense up to and including asOfDate, carried into equity. */
  periodResult: number;
  totalAssets: number;
  /** liabilities + equity + periodResult. */
  totalLiabilitiesAndEquity: number;
  /** True when totalAssets equals totalLiabilitiesAndEquity. */
  balanced: boolean;
  errors: string[];
};

export type BalanceSheetSection = {
  lines: StatementLine[];
  total: number;
};

export type AnnualReportComparison = {
  fiscalYearStart: string;
  fiscalYearEnd: string;
  /** True when the preceding year contained any ledger activity. */
  available: boolean;
  totalIncome: number;
  totalExpense: number;
  aretsResultat: number;
  totalAssets: number;
  totalLiabilitiesAndEquity: number;
  equity: number;
};

export type AnnualReportNote = {
  /** Stable note identifier, e.g. "accounting-policies". */
  id: string;
  /** Danish note heading. */
  title: string;
  /** Placeholder body — the owner/advisor completes the wording. */
  body: string;
  /** True while the note is an un-reviewed placeholder. */
  placeholder: boolean;
};

export type AnnualReportLedelsespategning = {
  text: string;
  placeholder: boolean;
};

type CompanyRow = {
  name: string;
  country: string;
  currency: string;
  cvr: string | null;
};

type PeriodRow = {
  period_start: string;
  period_end: string;
  kind: string;
  status: string;
};

export type TrialBalanceReport = {
  ok: boolean;
  appliedRules: string[];
  periodStart: string;
  periodEnd: string;
  accounts: TrialBalanceAccount[];
  totalDebit: number;
  totalCredit: number;
  /** True when totalDebit equals totalCredit (a well-formed double-entry set). */
  balanced: boolean;
  linesConsidered: number;
  journalEntryCount: number;
  errors: string[];
};

export type TrialBalanceAccount = {
  accountNo: string;
  name: string;
  type: AccountType;
  normalBalance: "debit" | "credit";
  /** Summed debit movement in the period, DKK. */
  debit: number;
  /** Summed credit movement in the period, DKK. */
  credit: number;
  /** Net movement, signed debit − credit, DKK. */
  balance: number;
};

type Acc = {
    accountNo: string;
    name: string;
    type: AccountType;
    normalBalance: "debit" | "credit";
    debitOre: bigint;
    creditOre: bigint;
  };

export type GenerateIxbrlResult = {
  ok: boolean;
  appliedRules: string[];
  /** The full XHTML+iXBRL document. Empty string on failure. */
  xhtml: string;
  /** sha256 of `xhtml`, for byte-stability checks and manifests. */
  sha256: string;
  /**
   * The resolved facts, in declared subset order. Exposed so callers (and the
   * golden test) can round-trip the document against the values that produced
   * it without re-parsing. Empty on failure.
   */
  facts: ResolvedFact[];
  /** The taxonomy subset name + version this document was generated against. */
  taxonomy: { name: string; version: string };
  errors: string[];
};

export type ResolvedFact = {
  element: IxbrlTaxonomyElement;
  /** Already-stringified value (formatted money or text). */
  value: string;
};

export type IxbrlTaxonomyElement = {
  /** Namespaced element name, e.g. "ar:Revenue". */
  name: string;
  /** "monetary" -> ix:nonFraction; "text" -> ix:nonNumeric. */
  kind: "monetary" | "text";
  /** Human-readable Danish label rendered next to the fact. */
  label: string;
  /** Which class-B statement section this element belongs to. */
  section: IxbrlSection;
  /** The xbrli context the fact is reported against. */
  context: IxbrlContext;
};

export type IxbrlSection =
  | "company-info"
  | "income-statement"
  | "balance-sheet"
  | "management-statement"
  | "accounting-policies";

definition.handlerSpecificParsing:
(ctx) => {
    // `--ixbrl-taxonomy` is a pure-introspection mode: it neither touches the
    // ledger nor needs --from/--to. It prints the bounded, versioned subset so
    // an owner/advisor can see exactly which class-B elements are covered.
    if (ctx.hasFlag("--ixbrl-taxonomy")) {
      emitHumanReport(
        "report-annual-ixbrl-taxonomy",
        {
          ok: true,
          name: IXBRL_TAXONOMY_SUBSET.name,
          version: IXBRL_TAXONOMY_SUBSET.version,
          scope: IXBRL_TAXONOMY_SUBSET.scope,
          prefix: IXBRL_TAXONOMY_SUBSET.prefix,
          namespace: IXBRL_TAXONOMY_SUBSET.namespace,
          elementCount: IXBRL_TAXONOMY_SUBSET.elements.length,
          elements: IXBRL_TAXONOMY_SUBSET.elements,
        },
        ctx.outputFormat,
      );
      return;
    }

    const from = ctx.arg("--from");
    const to = ctx.arg("--to");
    if (!from || !to) {
      console.error("Missing required --from <YYYY-MM-DD> or --to <YYYY-MM-DD>");
      process.exit(2);
    }
    const ixbrlOut = ctx.trimToNull(ctx.arg("--ixbrl-out"));

    const db = openCommandDb(ctx);
    migrate(db);
    const report = buildAnnualReport(db, from, to);

    // The JSON result is the assembled arsrapport plus, when requested and the
    // report passed its prerequisites, the iXBRL file metadata.
    const result: Record<string, unknown> = { ...report };
    if (ixbrlOut) {
      const ixbrl = generateIxbrl(report);
      if (ixbrl.ok) {
        writeFileSync(ixbrlOut, ixbrl.xhtml);
        result.ixbrl = {
          ok: true,
          path: ixbrlOut,
          sha256: ixbrl.sha256,
          taxonomy: ixbrl.taxonomy,
          appliedRules: ixbrl.appliedRules,
        };
      } else {
        // Surface the iXBRL failure without overriding a passing report:
        // the arsrapport JSON is still useful even if no file was written.
        result.ixbrl = { ok: false, path: null, sha256: "", errors: ixbrl.errors };
      }
    }

    emitHumanReport("report-annual", result, ctx.outputFormat);
    db.close();
  }

definition.exactParser:
const BOOLEAN_FLAGS = new Set([
  "--force",
  "--help",
  "--example",
  "--json",
  "--sign-with-ed25519",
  "--archive",
  "--enrich-cvr",
  "--include-archived",
  "--ixbrl-taxonomy",
  "--after-retention-expiry",
  "--no-vat",
  "--no-open",
]);

export type ParsedCliArgs = {
  positionals: string[];
  flags: Map<string, string | true>;
  errors: string[];
};

export function parseCliArgs(argv: string[]): ParsedCliArgs {
  const tokens = argv.slice(2);
  const positionals: string[] = [];
  const flags = new Map<string, string | true>();
  const errors: string[] = [];

  let optionsTerminated = false;

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i]!;

    if (!optionsTerminated && token === "--") {
      optionsTerminated = true;
      continue;
    }

    if (optionsTerminated || !token.startsWith("--")) {
      positionals.push(token);
      continue;
    }

    // `--flag=value` form: value is attached, so it may begin with dashes
    // or be empty without being confused for a missing-value error.
    const eq = token.indexOf("=");
    if (eq !== -1) {
      const name = token.slice(0, eq);
      const value = token.slice(eq + 1);
      if (BOOLEAN_FLAGS.has(name)) {
        errors.push(`Flag ${name} does not take a value`);
        continue;
      }
      flags.set(name, value);
      continue;
    }

    if (BOOLEAN_FLAGS.has(token)) {
      const next = tokens[i + 1];
      if (next && next !== "--" && !next.startsWith("--")) {
        errors.push(`Flag ${token} does not take a value`);
        i += 1;
        continue;
      }
      flags.set(token, true);
      continue;
    }

    const value = tokens[i + 1];
    if (value === undefined || value === "--" || value.startsWith("--")) {
      errors.push(`Flag ${token} requires a value`);
      continue;
    }
    flags.set(token, value);
    i += 1;
  }

  return { positionals, flags, errors };
}

stdout.genericRenderer:
import { formatKronerDa } from "../core/money";

export type OutputFormat = "json" | "human";

export function resolveOutputFormat(flags: Map<string, string | true>): OutputFormat | null {
  if (flags.has("--json")) return "json";
  const format = flags.get("--format");
  if (format === undefined) return process.stdout.isTTY ? "human" : "json";
  if (format === "json" || format === "human") return format;
  return null;
}

export function printStructuredResult(commandLabel: string, result: Record<string, unknown>, format: OutputFormat) {
  const ok = result.ok !== false;
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  const lines = ok ? buildHumanSuccess(commandLabel, result) : buildHumanError(commandLabel, result);
  const text = lines.join("\n");
  if (ok) console.log(text);
  else console.error(text);
}

/**
 * A command's `description` in `cli-meta.ts` is a full sentence (often two)
 * meant for help text — never a heading. #268: a write command that falls
 * through to the generic human renderer used to print that whole description
 * as the `✔` heading. `headingFromLabel` collapses such a label to a short
 * heading: the first clause before an em dash / period, capped in length.
 */
function headingFromLabel(commandLabel: string): string {
  const firstClause = commandLabel.split(/\s+[—–-]\s+|\.\s/)[0]?.trim() ?? commandLabel;
  const short = firstClause.length > 0 ? firstClause : commandLabel;
  return short.length > 60 ? `${short.slice(0, 57).trimEnd()}…` : short;
}

function buildHumanSuccess(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✔ ${headingFromLabel(commandLabel)}`];
  for (const line of collectSummaryLines(result)) lines.push(`  ${line}`);
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  return lines;
}

export function buildHumanError(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✘ ${commandLabel} failed`];
  const errors = asStringArray(result.errors);
  if (errors.length > 0) {
    for (const error of errors) lines.push(`  → ${error}`);
  } else {
    lines.push("  → Kommandoen fejlede uden en specifik fejlbesked.");
  }
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  appendPeriodCloseGuidance(lines, errors);
  return lines;
}

/**
 * `vat momsangivelse` and `report annual` reject an unfinalised period with a
 * terse "... is not closed ... run 'period close' first". For an owner near a
 * deadline that is cryptic, so when we recognise that failure we append a
 * plain-Danish explanation of what closing a period means and the exact
 * command to run. (#227)
 */
function appendPeriodCloseGuidance(lines: string[], errors: string[]): void {
  const closeError = errors.find(
    (e) => /is not closed/i.test(e) && /period close/i.test(e),
  );
  if (!closeError) return;
  const range = closeError.match(/(\d{4}-\d{2}-\d{2})\.\.(\d{4}-\d{2}-\d{2})/);
  const isFiscalYear = /fiscal|regnskabsår|annual/i.test(closeError);
  const kind = isFiscalYear ? "fiscal_year" : "vat_period";
  const fromTo = range ? `--from ${range[1]} --to ${range[2]}` : "--from <YYYY-MM-DD> --to <YYYY-MM-DD>";
  lines.push("");
  lines.push("  Sådan kommer du videre:");
  lines.push(
    "    En momsangivelse/årsrapport kan kun bygges på en LUKKET periode — det sikrer,",
  );
  lines.push(
    "    at tallene ikke ændrer sig efter indberetning. Du lukker perioden med:",
  );
  lines.push(`      rentemester period close --company <path> ${fromTo} --kind ${kind}`);
  lines.push(
    "    Luk først perioden når alle bilag for perioden er bogført — en lukket periode",
  );
  lines.push(
    "    blokerer ny bogføring med dato i perioden. Brug --status reported i stedet for",
  );
  lines.push(
    "    standard 'closed', hvis du allerede har indberettet til SKAT/Erhvervsstyrelsen.",
  );
}

/**
 * Danish labels for the result keys a write command commonly returns. The
 * generic human fallback (`collectSummaryLines`) used to English-ify keys via
 * `humanizeKey` ("Invoice Number", "Document Id"); for a Danish-facing tool
 * that is wrong. Any key without an entry here keeps the humanized form, but
 * the common write-result fields are now translated. (#268)
 *
 * Round-2 review (Batch E-1) expanded the set so read commands that return
 * single objects (audit verify, company profile, gdpr export/forget,
 * customer create, invoice post) actually render meaningful content under
 * `--format human` instead of just echoing the command description.
 */
const WRITE_RESULT_LABEL_DA: Record<string, string> = {
  message: "Besked",
  invoiceNumber: "Fakturanummer",
  invoiceNo: "Fakturanummer",
  entryNo: "Posteringsnummer",
  entryNumber: "Posteringsnummer",
  documentId: "Bilags-id",
  journalEntryId: "Finanspostering-id",
  importBatchId: "Import-batch-id",
  imported: "Importeret",
  skippedDuplicates: "Sprunget over (dubletter)",
  backupId: "Backup-id",
  exportDir: "Eksportmappe",
  latestBackupId: "Seneste backup-id",
  expiredCount: "Udløbne",
  totalCount: "I alt",
  storedPath: "Gemt fil",
  pdfStoredPath: "PDF-fil",
  // Batch E-1: read-command friendly labels.
  entries: "Posteringer kontrolleret",
  chainOk: "Kæden er hel",
  erasedCount: "Anonymiseret",
  skippedCount: "Sprunget over",
  alreadyErasedCount: "Allerede anonymiseret",
  recordCount: "Rækker fundet",
  count: "Antal",
  total: "I alt",
  // Profile / contact fields (company profile, customer/vendor create).
  name: "Navn",
  cvr: "CVR",
  email: "E-mail",
  address: "Adresse",
  postalCode: "Postnummer",
  city: "By",
  country: "Land",
  currency: "Valuta",
  paymentTermsDays: "Betalingsfrist (dage)",
  vatPeriodType: "Momsperiode",
  vatPeriodLabel: "Momsstatus",
  vatRegistered: "Momsregistreret",
  companyForm: "Selskabsform",
  industryText: "Branche",
  cvrStatus: "CVR-status",
  auditWaived: "Revision fravalgt",
  fiscalYearStartMonth: "Regnskabsår starter (måned)",
  customerId: "Kunde-id",
  vendorId: "Leverandør-id",
  slug: "Slug",
};

/**
 * Top-level keys whose VALUE is a nested object that should be drilled into
 * — every scalar field inside becomes its own labelled line. Lets commands
 * like `company profile` (returns `{ ok, profile: {...} }`) emit each profile
 * field without per-command renderers. Batch E-1.
 */
const NESTED_DRILL_KEYS = new Set<string>([
  "profile",
  "customer",
  "vendor",
  "company",
  "settings",
  "depreciation",
  "writeOff",
  "reminder",
  "credit",
  "suggestion",
  "summary",
]);

function collectSummaryLines(result: Record<string, unknown>) {
  const preferredKeys = [
    "message",
    "invoiceNumber",
    "invoiceNo",
    "entryNo",
    "entryNumber",
    "documentId",
    "journalEntryId",
    "importBatchId",
    "imported",
    "skippedDuplicates",
    "backupId",
    "exportDir",
    "latestBackupId",
    "expiredCount",
    "totalCount",
    "entries",
    "chainOk",
    "erasedCount",
    "skippedCount",
    "alreadyErasedCount",
    "recordCount",
    "count",
    "total",
    "name",
    "cvr",
    "email",
    "address",
    "postalCode",
    "city",
    "country",
    "currency",
    "paymentTermsDays",
    "vatPeriodType",
    "vatPeriodLabel",
    "vatRegistered",
    "companyForm",
    "industryText",
    "cvrStatus",
    "auditWaived",
    "fiscalYearStartMonth",
    "customerId",
    "vendorId",
    "slug",
  ];
  const lines: string[] = [];
  const seen = new Set<string>();
  for (const key of preferredKeys) {
    if (seen.has(key)) continue;
    const value = result[key];
    const rendered = renderScalar(value);
    if (rendered === null) continue;
    // #268: never emit an English key on a Danish-facing tool — use the Danish
    // label when one exists, falling back to the humanized form otherwise.
    lines.push(
      `${WRITE_RESULT_LABEL_DA[key] ?? humanizeKey(key)}: ${translateValueForKey(key, rendered)}`,
    );
    seen.add(key);
  }
  // Batch E-1: drill one level into well-known nested-object keys. Lets
  // `company profile` (returns `{ ok, profile: {...} }`) actually render
  // each profile field instead of showing only "✔ <command description>".
  for (const [key, value] of Object.entries(result)) {
    if (!NESTED_DRILL_KEYS.has(key)) continue;
    if (value == null || typeof value !== "object" || Array.isArray(value)) continue;
    const inner = value as Record<string, unknown>;
    for (const [innerKey, innerValue] of Object.entries(inner)) {
      if (seen.has(innerKey)) continue;
      const rendered = renderScalar(innerValue);
      if (rendered === null) continue;
      lines.push(
        `${WRITE_RESULT_LABEL_DA[innerKey] ?? humanizeKey(innerKey)}: ${translateValueForKey(innerKey, rendered)}`,
      );
      seen.add(innerKey);
    }
  }
  return lines;
}

function renderScalar(value: unknown): string | null {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return null;
}

/**
 * Danish display values for the handful of enum-valued profile fields whose raw
 * stored form is an English token (e.g. `quarter`, `end-year`). #268 already
 * translates the key (label) into Danish; this translates the VALUE so an owner
 * never sees "Momsperiode: quarter". Keyed by field, then by raw value; unknown
 * fields/values pass through unchanged.
 */
const VALUE_LABEL_DA: Record<string, Record<string, string>> = {
  vatPeriodType: {
    month: "måned",
    quarter: "kvartal",
    "half-year": "halvår",
  },
  vatRegistered: {
    true: "Ja",
    false: "Nej",
  },
  fiscalYearLabelStrategy: {
    "end-year": "slutår",
    "start-year": "startår",
  },
};

function translateValueForKey(key: string, rendered: string): string {
  return VALUE_LABEL_DA[key]?.[rendered] ?? rendered;
}

function humanizeKey(key: string) {
  return key
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/_/g, " ")
    .replace(/^./, (c) => c.toUpperCase());
}

export function asStringArray(value: unknown) {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

/**
 * Format a DKK amount as Danish kroner-og-øre, e.g. 38.3 -> "38,30 kr.",
 * -1234.5 -> "-1.234,50 kr.". Non-finite/missing input yields "—".
 *
 * Thin re-export of the single canonical formatter `formatKronerDa` in
 * `core/money.ts` — kept under the historical name so the many call sites in
 * this file stay unchanged. (#314)
 */
export function formatKroner(value: unknown): string {
  return formatKronerDa(value);
}

/** Render an integer count, falling back to 0 for missing values. */
export function asCount(value: unknown): number {
  const num = typeof value === "number" ? value : Number(value);
  return Number.isFinite(num) ? num : 0;
}

export function asText(value: unknown, fallback = "—"): string {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  return fallback;
}

export function asArray(value: unknown): Array<Record<string, unknown>> {
  return Array.isArray(value)
    ? value.filter((item): item is Record<string, unknown> => typeof item === "object" && item !== null)
    : [];
}

/**
 * Format a percentage with Danish decimal comma, e.g. 8.05 -> "8,05 %".
 * Non-finite/missing input yields "—".
 */
export function formatPercent(value: unknown): string {
  const num = typeof value === "number" ? value : Number(value);
  if (value == null || value === "" || !Number.isFinite(num)) return "—";
  const text = (Math.round(num * 100) / 100)
    .toString()
    .replace(".", ",");
  return `${text} %`;
}

export function appendWarnings(lines: string[], result: Record<string, unknown>): void {
  const warnings = asStringArray(result.warnings);
  if (warnings.length === 0) return;
  lines.push("");
  lines.push("Advarsler:");
  for (const warning of warnings) lines.push(`  - ${warning}`);
}

stdout.reportDispatch:
import { type OutputFormat, buildHumanError, printStructuredResult } from "./common";
import { renderVatReport, renderVatFiling, renderAnnualReport, renderTaxReturn } from "./vat";
import {
  renderInvoiceStatus,
  renderInvoiceInterest,
  renderInvoiceCompensation,
  renderInvoiceValidate,
  renderInvoiceCreate,
} from "./invoice";
import {
  renderBackupStatus,
  renderExceptionsList,
  renderTrialBalance,
  renderProfitAndLoss,
  renderBalanceSheet,
  renderRetentionStatus,
} from "./dashboard";
import { renderBankReconciliation } from "./bank";

// ===========================================================================
// HUMAN-READABLE REPORT RENDERING — DISPATCH (#211)
// ---------------------------------------------------------------------------
// Read/report commands emit deterministic JSON with English field names for
// agents. When a human runs them (`--format human` / a TTY) that JSON is
// unreadable. `renderHumanReport` renders the same payloads in clear Danish
// with money in kroner-og-øre. The `--format json` path is untouched: handlers
// keep calling `ctx.emitResult` for JSON and only branch into this renderer
// for the human format.
// ===========================================================================

/** Report kinds with a dedicated Danish human renderer. */
export type HumanReportKind =
  | "vat-report"
  | "vat-filing"
  | "report-annual"
  | "report-tax"
  | "invoice-status"
  | "invoice-interest"
  | "invoice-compensation"
  | "invoice-validate"
  | "exceptions-list"
  | "report-trial-balance"
  | "report-profit-loss"
  | "report-balance"
  | "retention-status"
  | "reconcile-bank"
  | "backup-status"
  // #177: `report annual --ixbrl-taxonomy` prints the bounded iXBRL subset.
  // No dedicated renderer — it falls back to the generic structured output.
  | "report-annual-ixbrl-taxonomy";

/**
 * Render a read/report `result` payload as Danish human-readable text.
 *
 * Returns `null` when there is no dedicated renderer for `kind` or the payload
 * does not look renderable, so callers can fall back to the generic
 * `printStructuredResult` rendering.
 */
export function renderHumanReport(
  kind: HumanReportKind,
  result: Record<string, unknown>,
): string | null {
  // `backup-status` reports `ok: false` when the weekly backup duty is NOT met
  // — that is a valid compliance status to render, not a command failure. Its
  // renderer handles both states, so it must run before the generic
  // ok-false-as-error path. (#240)
  if (kind === "backup-status") {
    return renderBackupStatus(result);
  }
  // `invoice validate` reports `ok: false` when the payload is INVALID — that
  // is a valid validation verdict to render in full (the figures and every
  // rejection reason), not a command crash. Its renderer covers both the
  // valid and invalid verdict, so it must run before the generic
  // ok-false-as-error path. (#250)
  if (kind === "invoice-validate") {
    return renderInvoiceValidate(result);
  }
  if (result.ok === false) {
    return buildHumanError(humanReportTitle(kind), result).join("\n");
  }
  switch (kind) {
    case "vat-report":
      return renderVatReport(result);
    case "vat-filing":
      return renderVatFiling(result);
    case "report-annual":
      return renderAnnualReport(result);
    case "report-tax":
      return renderTaxReturn(result);
    case "invoice-status":
      return renderInvoiceStatus(result);
    case "invoice-interest":
      return renderInvoiceInterest(result);
    case "invoice-compensation":
      return renderInvoiceCompensation(result);
    case "exceptions-list":
      return renderExceptionsList(result);
    case "report-trial-balance":
      return renderTrialBalance(result);
    case "report-profit-loss":
      return renderProfitAndLoss(result);
    case "report-balance":
      return renderBalanceSheet(result);
    case "retention-status":
      return renderRetentionStatus(result);
    case "reconcile-bank":
      return renderBankReconciliation(result);
    default:
      // `backup-status` and `invoice-validate` are handled before this switch
      // (their renderers cover the ok:false state too), so they never reach
      // here.
      return null;
  }
}

/**
 * Emit a read/report `result` either as the byte-stable agent JSON or as the
 * Danish human rendering, depending on `format`. The `--format json` path is
 * exactly `JSON.stringify(result, null, 2)` — unchanged from `emitResult` —
 * so agents see no difference. Only the human rendering is new.
 *
 * Returns the process exit code to apply (1 when `result.ok === false`).
 */
export function emitHumanReport(
  kind: HumanReportKind,
  result: Record<string, unknown>,
  format: OutputFormat,
): void {
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    const human = renderHumanReport(kind, result);
    if (human !== null) {
      if (result.ok === false) console.error(human);
      else console.log(human);
    } else {
      printStructuredResult(humanReportTitle(kind), result, format);
    }
  }
  if (result.ok === false) process.exitCode = 1;
}

function humanReportTitle(kind: HumanReportKind): string {
  switch (kind) {
    case "vat-report":
      return "Momsrapport";
    case "vat-filing":
      return "Momsangivelse";
    case "report-annual":
      return "Årsrapport";
    case "report-tax":
      return "Skattemæssig indkomst";
    case "invoice-status":
      return "Fakturastatus";
    case "invoice-interest":
      return "Morarente";
    case "invoice-compensation":
      return "Kompensation for sen betaling";
    case "invoice-validate":
      return "Fakturavalidering";
    case "exceptions-list":
      return "Undtagelser";
    case "report-trial-balance":
      return "Saldobalance";
    case "report-profit-loss":
      return "Resultatopgørelse";
    case "report-balance":
      return "Balance";
    case "retention-status":
      return "Opbevaringsstatus";
    case "reconcile-bank":
      return "Bankafstemning";
    case "backup-status":
      return "Backup-status";
    case "report-annual-ixbrl-taxonomy":
      return "iXBRL-taksonomi (afgrænset udsnit)";
  }
}

/** Write-command kinds with a dedicated Danish human renderer. (#266, #268) */
export type HumanWriteKind = "invoice-create";

/**
 * Emit a write-command `result` either as the byte-stable agent JSON or as a
 * Danish human rendering, depending on `format`. The `--format json` path is
 * exactly `JSON.stringify(result, null, 2)` — unchanged from `emitResult` — so
 * agents see no difference. Sets `process.exitCode = 1` on `ok: false`. (#268)
 */
export function emitHumanWrite(
  kind: HumanWriteKind,
  result: Record<string, unknown>,
  format: OutputFormat,
): void {
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    const human = kind === "invoice-create" ? renderInvoiceCreate(result) : null;
    if (human !== null) {
      if (result.ok === false) console.error(human);
      else console.log(human);
    } else {
      printStructuredResult(kind, result, format);
    }
  }
  if (result.ok === false) process.exitCode = 1;
}

