      name: normalizeEntryPath(name),
      path,
      bytes,
      text: stripBom(new TextDecoder("utf-8").decode(bytes)),
    },
  };
  return {
    rootDir: path.slice(0, path.length - name.length).replace(/[/\\]$/, "") || ".",
    files,
    sourceEvidence: inventoryEvidence("file", files),
  };
}

const failParse = (errors: string[], resolved?: MultiArtifactSource): ImportResult => ({
    ok: false,
    sourceSystem: parser.system,
    openingBalanceLineCount: 0,
    historicalEntriesSkipped: 0,
    auditTrail: [`Import started from source system '${parser.system}'`],
    appliedRules: [IMPORT_RULE],
    errors,
    ...(resolved?.archiveIntegrity ? { archiveIntegrity: resolved.archiveIntegrity } : {}),
  });

function preflightDineroArchive(
  db: Database,
  resolved: MultiArtifactSource,
  source: ImportSource,
): { errors: string[]; rollForward?: RollForwardResult } {
  const parsed = parseArchiveYears(resolved);
  if (!parsed.ok) return { errors: parsed.errors.map((error) => `archive integrity failure: ${error}`) };
  const closingBalances = new Map<number, Map<string, number>>(
    parsed.years.map((year) => [
      year.fiscalYear,
      new Map(year.balances.map((balance) => [balance.accountNo, balance.amount])),
    ]),
  );
  const accountTypes = new Map(
    source.chartOfAccounts
      .filter((account) => account.normalizedType)
      .map((account) => [account.accountNo, account.normalizedType!] as const),
  );
  const accountNames = new Map(
    source.chartOfAccounts.map((account) => [account.accountNo, account.name] as const),
  );
  const rollForward = checkRollForward(db, resolved, {
    closingBalances,
    accountTypes,
    accountNames,
    accountRoleProposals: source.accountRoleProposals,
  });
  if (rollForward.ok) return { errors: [], rollForward };
  return { rollForward, errors: [
    ...rollForward.errors.map((error) => `roll-forward integrity failure: ${error}`),
    ...rollForward.breaks.map(
      (item) =>
        `roll-forward integrity failure: account ${item.accountNo} ${item.fromYear}->${item.toYear} closing ${item.closingAmount} != opening ${item.openingAmount}`,
    ),
  ] };
}

function runDineroV4(db: Database, resolved: MultiArtifactSource, source: ImportSource, options: ImportOptions): ImportResult {
  const preflight = preflightDineroArchive(db, resolved, source);
  const bilagErrors = planDineroBilag(resolved, (source.historicalEntries ?? []).map((entry) => entry.voucherRef ?? "").filter(Boolean));
  const hasReceipts = Object.keys(resolved.files).some((name) =>
    /^(\d{4}\/(?:Bilag|Faktura)|Ikke-bogførte-bilag)\//i.test(name),
  );
  const root = companyRootFor(db, options);
  if (preflight.errors.length || bilagErrors.length || (hasReceipts && !root)) {
    return { ok: false, sourceSystem: "dinero", cutOverDate: source.cutOverDate, openingBalanceLineCount: source.openingBalances.length, historicalEntriesSkipped: source.historicalEntries?.length ?? 0, auditTrail: ["Dinero v4 planning rejected before mutation"], appliedRules: [IMPORT_RULE], errors: [...preflight.errors, ...bilagErrors, ...(hasReceipts && !root ? ["receipt-bearing Dinero import requires a resolvable company root"] : [])] };
  }
  const raw = resolved.sourceEvidence.rawSha256 ?? resolved.sourceEvidence.canonicalInventorySha256;
  const existingAccepted = db.query("SELECT id FROM dinero_import_attempts WHERE source_raw_sha256 = ? AND outcome = 'accepted' LIMIT 1").get(raw);
  if (existingAccepted) return { ok: false, sourceSystem: "dinero", cutOverDate: source.cutOverDate, openingBalanceLineCount: source.openingBalances.length, historicalEntriesSkipped: source.historicalEntries?.length ?? 0, auditTrail: ["Dinero v4 import already accepted for this immutable source"], appliedRules: [IMPORT_RULE], errors: ["already-imported"] };

  // A legacy archive has no immutable v4 ownership. Never silently attach new
  // evidence to it: that would make changed history look accepted.
  const years = parseArchiveYears(resolved);
  if (years.ok) {
    for (const year of years.years) {
      const legacy = db.query("SELECT id FROM import_archive_years WHERE source_system = 'dinero' AND fiscal_year = ?").get(year.fiscalYear);
      if (legacy) return { ok: false, sourceSystem: "dinero", cutOverDate: source.cutOverDate, openingBalanceLineCount: source.openingBalances.length, historicalEntriesSkipped: source.historicalEntries?.length ?? 0, auditTrail: ["Dinero v4 planning rejected legacy archive collision"], appliedRules: [IMPORT_RULE], errors: [`legacy archive already exists for fiscal year ${year.fiscalYear}`] };
    }
  }
  const createdPaths: string[] = [];
  let bilagOutcome: ReturnType<typeof ingestDineroBilag> | undefined;
  let result: ImportResult | undefined;
  try {
    result = db.transaction(() => {
      const landed = runImportImpl(db, source, options);
      if (!landed.ok) throw new ImportRollback(landed);
      const openItems = planMigrationOpenItemControls(db, source);
      if (openItems.errors.length > 0) throw new Error(openItems.errors.join("; "));
      if (source.importedReceivableSchedule) {
        const schedule = validateImportedReceivableSchedule(source.importedReceivableSchedule);
        if (!schedule.ok) throw new Error(schedule.errors.join("; "));
        const receivableControls=openItems.balances.filter(balance=>balance.kind==="receivable");
        const controlDate=(source.historicalEntries??[]).reduce((latest,entry)=>entry.transactionDate>latest?entry.transactionDate:latest,source.cutOverDate);
        for (const balance of receivableControls) {
          if (importedScheduleBalanceOre(schedule.schedule,controlDate,balance.accountNo)!==toOre(balance.amount)) throw new Error(`imported receivable schedule does not reconcile exactly to control ${balance.accountNo} at ${controlDate}`);
        }
        const scheduledControls=new Set(schedule.schedule.invoices.map(invoice=>invoice.controlAccountNo));
        for (const accountNo of scheduledControls) if (!receivableControls.some(balance=>balance.accountNo===accountNo)) throw new Error(`imported receivable schedule control ${accountNo} has no authoritative receivable control balance`);
      }
      if (openItems.balances.length > 0) {
        landed.migrationOpenItems = {
          batchCount: openItems.balances.length,
          receivableAmount: openItems.receivableAmount,
          payableAmount: openItems.payableAmount,
        };
        for (const balance of openItems.balances) {
          landed.auditTrail.push(`Preserve unallocated ${balance.kind} control ${balance.accountNo} from ${balance.sourceReference}: ${balance.amount}`);
        }
      }
      if (options.dryRun) throw new ImportRollback({ ...landed, dryRun: true });
      dineroFault("archive");
      const archive = archiveDineroYears(db, resolved);
      if (!archive.ok) throw new Error(archive.errors.join("; "));
      landed.auditTrail.push(...archive.auditTrail, ...describeRollForward(preflight.rollForward!));
      if (root) {
        dineroFault("document");
        dineroFault("publish");
        const bilag = ingestDineroBilag(db, root, resolved, landed);
        bilagOutcome = bilag;
        createdPaths.push(...bilag.publishedPaths);
        if (!bilag.ok) throw new Error(bilag.errors.join("; "));
        dineroFault("link");
        landed.bilag = { linkedCount: bilag.linked.length, unmatchedCount: bilag.unmatched.length, duplicateCount: bilag.duplicates.length, unbookedCount: bilag.unbooked.length };
      }
      const provenance = persistDineroEvidence(db, resolved, source, options, "accepted", landed);
      if (source.importedReceivableSchedule) {
        const recordedSchedule = recordImportedReceivableSchedule(db, provenance.attemptId, source.importedReceivableSchedule);
        if (!recordedSchedule.ok) throw new Error(recordedSchedule.errors.join("; "));
        landed.auditTrail.push(`Recorded immutable imported receivable schedule ${recordedSchedule.scheduleHash}`);
      }
      for (const balance of openItems.balances) {
        const recorded = recordMigrationOpenItemBatch(db, {
          dineroImportAttemptId: provenance.attemptId,
          controlAccountNo: balance.accountNo,
          kind: balance.kind,
          sourceControlAmount: balance.amount,
          items: [{
            externalRef: `UNALLOCATED:${balance.accountNo}`,
            originalAmount: balance.amount,
            openAmountAtImport: balance.amount,
            sourceKind: "control_balance",
            resolutionStatus: "unallocated",
          }],
        });
        if (!recorded.ok) throw new Error(recorded.errors.join("; "));
      }
      if (bilagOutcome) {
        const addLink = db.query("INSERT INTO dinero_import_document_links (attempt_id, inventory_id, entry_path, entry_sha256, document_id, journal_entry_id, voucher_reference, disposition) VALUES (?, ?, ?, ?, ?, ?, ?, ?)");
        for (const item of bilagOutcome.linked) addLink.run(provenance.attemptId, provenance.inventoryId, item.fileName, item.sha256, item.documentId, item.journalEntryId, item.voucherRef, "linked");
        for (const item of bilagOutcome.unmatched) {
          const artifact = resolved.files[item.fileName]!;
          const document = db.query("SELECT id, sha256_hash FROM documents WHERE sha256_hash = ?").get(createHash("sha256").update(artifact.bytes).digest("hex")) as { id: number; sha256_hash: string };
          addLink.run(provenance.attemptId, provenance.inventoryId, item.fileName, document.sha256_hash, document.id, null, item.voucherRef, "unmatched");
        }
        for (const item of bilagOutcome.unbooked) addLink.run(provenance.attemptId, provenance.inventoryId, item.fileName, item.sha256, item.documentId, null, null, "excluded");
      }
      for (const year of years.years) {
        const yearEntries = resolved.sourceEvidence.entries.filter((entry) => entry.path.startsWith(`${year.fiscalYear}/`));
        db.query("INSERT INTO dinero_import_archive_evidence (attempt_id, inventory_id, source_id, source_raw_sha256, fiscal_year, archive_sha256, archive_size_bytes) VALUES (?, ?, ?, ?, ?, ?, ?)")
          .run(provenance.attemptId, provenance.inventoryId, provenance.sourceId, raw, year.fiscalYear, digest(yearEntries), yearEntries.reduce((sum, entry) => sum + entry.size, 0));
      }
      dineroFault("audit");
      insertAuditLog(db, { eventType: "dinero_import_accepted", entityType: "import", entityId: provenance.attemptId, message: `Accepted immutable Dinero v4 import ${raw}`, createdBy: options.createdBy, createdByProgram: options.createdByProgram });
      dineroFault("verify");
      // Provenance is per source artifact, not per newly-created document.
      // A pre-existing content-addressed receipt still needs its immutable
      // evidence row and must not make this verifier undercount.
      const expectedDocs = landed.bilag ? landed.bilag.linkedCount + landed.bilag.unmatchedCount + landed.bilag.unbookedCount : 0;
      if (expectedDocs > 0 && (db.query("SELECT COUNT(*) AS n FROM dinero_import_document_links WHERE attempt_id = ?").get(provenance.attemptId) as { n: number }).n !== expectedDocs) throw new Error("Dinero v4 verifier: provenance document-link count mismatch");
      if ((db.query("SELECT COUNT(*) AS n FROM migration_open_item_batches WHERE dinero_import_attempt_id = ?").get(provenance.attemptId) as { n: number }).n !== openItems.balances.length) throw new Error("Dinero v4 verifier: migration open-item batch count mismatch");
      return landed;
    }).immediate();
    return result;
  } catch (error) {
    for (const path of createdPaths) { try { if (existsSync(path)) unlinkSync(path); } catch {} }
    if (error instanceof ImportRollback) return error.result;
    const rejected: ImportResult = { ok: false, sourceSystem: "dinero", cutOverDate: source.cutOverDate, openingBalanceLineCount: source.openingBalances.length, historicalEntriesSkipped: source.historicalEntries?.length ?? 0, auditTrail: ["Dinero v4 transaction rolled back"], appliedRules: [IMPORT_RULE], errors: [error instanceof Error ? error.message : String(error)] };
    try { db.transaction(() => { persistDineroEvidence(db, resolved, source, options, "rejected", rejected); }).immediate(); } catch (recordError) { rejected.errors.push(`rejected-attempt evidence could not be recorded: ${recordError instanceof Error ? recordError.message : String(recordError)}`); }
    return rejected;
  }
}

export function runImport(db: Database, source: ImportSource, options: ImportOptions = {}): ImportResult {
  try {
    return db.transaction(() => {
      const result = runImportImpl(db, source, options);
      const withProposals: ImportResult = {
        ...result,
        ...(source.accountRoleProposals?.length ? { accountRoleProposals: source.accountRoleProposals } : {}),
      };
      if (!withProposals.ok) throw new ImportRollback(withProposals);
      if (options.dryRun) throw new ImportRollback({ ...withProposals, dryRun: true });
      return withProposals;
    }).immediate();
  } catch (error) {
    if (error instanceof ImportRollback) return error.result;
    throw error;
  }
}

typeDeclarations.source:
export type SourceParser = {
  /** Stable identifier, e.g. "synthetic-csv". Mirrors `ImportSource.sourceSystem`. */
  readonly system: string;
  /** Human-readable label for help text / audit trail. */
  readonly label: string;
  /**
   * Parse a raw export (file contents as a string) into an `ImportSource`.
   * Pure and deterministic: the same input always yields the same output.
   */
  parse?(raw: string): ParseResult;
  /**
   * Export-root-relative, forward-slash file names a multi-file parser needs.
   * Missing required files are a clear, named error before `parseSource` runs.
   */
  readonly requiredFiles?: readonly string[];
  /**
   * Parse a resolved multi-file export into an `ImportSource`. Pure and
   * deterministic with respect to `input`.
   */
  parseSource?(input: MultiArtifactSource): ParseResult;
};

export type ParseResult = {
  ok: boolean;
  source?: ImportSource;
  errors: string[];
};

export type ImportSource = {
  /** Identifier of the source system, e.g. "synthetic-csv", "dinero". */
  sourceSystem: string;
  /** Cut-over date (YYYY-MM-DD) — the day the opening balances are as of. */
  cutOverDate: string;
  /** The source system's chart of accounts. */
  chartOfAccounts: ImportAccount[];
  /** Explainable, unconfirmed semantic role candidates from chart evidence. */
  accountRoleProposals?: Array<{ role: import("../account-roles").AccountRole; accountNo: string; source: string }>;
  /** Per-account opening balances (the primobalance to be posted). */
  openingBalances: ImportOpeningBalanceLine[];
  /** Optional historical entries — captured but not posted by `runImport`. */
  historicalEntries?: ImportHistoricalEntry[];
  /** Aggregate open-item controls when the source has no item-level schedule. */
  openItemControlBalances?: ImportOpenItemControlBalance[];
  /** Explicit, versioned item-level receivable schedule. Never inferred from postings. */
  importedReceivableSchedule?: import("../imported-receivables").ImportedReceivableSchedule;
  /** Optional company master data (name, CVR, ...) from the export. */
  companyMasterData?: ImportCompanyMasterData;
  /**
   * Optional list of source VAT-code labels the parser could NOT map onto a
   * Rentemester VAT code. Surfaced by the import flow — never silently dropped.
   */
  unmappedVatCodes?: string[];
  /** Optional free-text note carried into the primobalance entry. */
  note?: string;
};

export type ImportAccount = {
  accountNo: string;
  name: string;
  /** Optional source-system account type label, kept for the audit trail. */
  type?: string;
  /** Rentemester account type, when the parser has classified the account. */
  normalizedType?: ImportAccountType;
  /** Rentemester normal balance, when the parser has classified the account. */
  normalBalance?: ImportNormalBalance;
  /** Resolved Rentemester VAT code (`accounts.default_vat_code`), when mapped. */
  defaultVatCode?: string | null;
};

export type ImportOpeningBalanceLine = {
  accountNo: string;
  debitAmount?: number;
  creditAmount?: number;
  /** Optional per-line text; defaults to the account name when omitted. */
  text?: string;
  /** Optional source-system VAT code/label carried for the audit trail. */
  vatCode?: string;
};

export type ImportHistoricalEntry = {
  transactionDate: string;
  text: string;
  lines: ImportOpeningBalanceLine[];
  /** Source-system voucher number (Dinero `Bilag`); links receipts in #196. */
  voucherRef?: string;
  /** Source-system entry classification (Dinero `Bilagstype`). */
  entryType?: string;
};

export type ImportOpenItemControlBalance = {
  accountNo: string;
  kind: "receivable" | "payable";
  /** Unsigned balance in kroner. */
  amount: number;
  /** Export-relative source reference, e.g. `2026/SaldoBalance.csv`. */
  sourceReference: string;
};

export type ImportCompanyMasterData = {
  name?: string;
  cvr?: string;
  address?: string;
  postalCode?: string;
  city?: string;
  country?: string;
  email?: string;
  phone?: string;
  website?: string;
};

export type MultiArtifactSource = {
  rootDir: string;
  files: Record<string, ImportArtifact>;
  /** Immutable, canonical evidence for the exact resolved input. */
  sourceEvidence: SourceEvidence;
  /**
   * Present for a ZIP source after its complete archive listing and extraction
   * have been verified. The three counts must agree before parsing can begin.
   */
  archiveIntegrity?: ArchiveIntegrityEvidence;
};

export type ImportArtifact = {
  /** Export-root-relative, forward-slash file name, e.g. "2025/Kontoplan.csv". */
  name: string;
  /** Absolute path on disk. */
  path: string;
  /** Raw file bytes. */
  bytes: Uint8Array;
  /** BOM-stripped UTF-8 decode of `bytes`. */
  text: string;
};

export type SourceEvidence = {
  sourceKind: "zip" | "directory" | "file";
  canonicalInventorySha256: string;
  entries: SourceEvidenceEntry[];
  importedEntryCount: number;
  totalUncompressedBytes: number;
  /** Present only for a ZIP's private immutable snapshot. */
  rawSha256?: string;
  /** Present only for a ZIP's private immutable snapshot. */
  rawSize?: number;
  /** Present only for ZIP file entries after strict path normalization. */
  canonicalListingSha256?: string;
  /** Present only for ZIP file entries after strict path normalization. */
  listingEntryCount?: number;
  /** Present only for ZIP sources. */
  extractedEntryCount?: number;
};

export type SourceEvidenceEntry = {
  path: string;
  size: number;
  sha256: string;
};

export type ArchiveIntegrityEvidence = {
  archiveSha256: string;
  archiveEntryCount: number;
  extractedEntryCount: number;
  importedEntryCount: number;
  archiveListingSha256: string;
  extractedManifestSha256: string;
};

export type ImportOptions = {
  createdBy?: string;
  createdByProgram?: string;
  /** Execute the complete DB path inside a transaction and always roll it back. */
  dryRun?: boolean;
  /**
   * The company root directory — where `ingestDocument` stores receipt
   * originals (#196). When omitted, `runImportFromSource` derives it from the
   * open database's path. Pass it explicitly for an in-memory ledger.
   */
  companyRoot?: string;
};

export type ImportResult = {
  ok: boolean;
  /** True when all database mutations were deliberately rolled back. */
  dryRun?: boolean;
  sourceSystem: string;
  cutOverDate?: string;
  entryId?: number;
  entryNo?: string;
  entryHash?: string;
  openingBalanceLineCount: number;
  /** Count of historical entries seen but intentionally not posted. */
  historicalEntriesSkipped: number;
  /**
   * Year-to-date vouchers (#195) replayed as journal entries after the
   * primobalance. Each carries the source voucher reference (Dinero `Bilag`)
   * and the journal entry it landed as — the handle #196 uses to link a
   * receipt to its voucher's journal entry.
   */
  historicalEntriesPosted?: Array<{
    voucherRef: string;
    entryId: number;
    entryNo: string;
    transactionDate: string;
  }>;
  /** Chart-of-accounts reconciliation outcome, when the source carried one. */
  chart?: ChartReconciliationResult;
  /** Company-master-data reconciliation outcome, when the source carried one. */
  company?: CompanyReconciliationResult;
  /** Pure importer suggestions shown for explicit review; never confirmations. */
  accountRoleProposals?: ImportSource["accountRoleProposals"];
  /**
   * Bilag (receipt) ingest outcome (#196), when the export shipped receipts:
   * how many were ingested and linked to their voucher's journal entry, and
   * how many unbooked receipts were flagged in the exception queue.
   */
  bilag?: {
    linkedCount: number;
    unmatchedCount: number;
    duplicateCount: number;
    unbookedCount: number;
  };
  /** Aggregate balances preserved without claiming item-level allocation. */
  migrationOpenItems?: {
    batchCount: number;
    receivableAmount: number;
    payableAmount: number;
  };
  /** ZIP archive evidence, when the source was a verified ZIP export. */
  archiveIntegrity?: ArchiveIntegrityEvidence;
  /** Ordered, deterministic human-readable description of what happened. */
  auditTrail: string[];
  appliedRules: string[];
  errors: string[];
};

export type ChartReconciliationResult = {
  /** Account numbers created in the `accounts` table by this import. */
  created: string[];
  /** Account numbers that already existed and were left untouched. */
  existing: string[];
  /** Account numbers reclassified to the source definition (had no postings). */
  updated: string[];
  /**
   * Human-readable differences applied: each describes how an existing
   * postings-free account was reclassified to match the source.
   */
  differences: string[];
  /**
   * Account numbers that differ from the source but already carry journal
   * lines, so they could NOT be reclassified — human-readable conflict lines.
   */
  conflicts: string[];
  /** Source VAT-code labels that could not be mapped to a Rentemester code. */
  unmappedVatCodes: string[];
};

export type CompanyReconciliationResult = {
  /** `companies` column names that were populated by this import. */
  updatedFields: string[];
  /** Human-readable notes — e.g. a field skipped because it was already set. */
  notes: string[];
};

export type RollForwardResult = {
  ok: boolean;
  steps: RollForwardStep[];
  /** Flat list of every break across all steps, for a concise summary. */
  breaks: RollForwardBreak[];
  errors: string[];
};

export type RollForwardStep = {
  fromYear: number;
  toYear: number;
  /** True when the "to" year is the cut-over year (posted opening balance). */
  toIsCutOver: boolean;
  ok: boolean;
  breaks: RollForwardBreak[];
  /** VAT-account totals give the operator a second, grouped reconciliation view. */
  vatGroups: RollForwardVatGroup[];
  /** Source-evidenced fixed-asset groups consolidated onto their primo account. */
  sourceConsolidations?: RollForwardSourceConsolidation[];
};

export type RollForwardBreak = {
  /** The closing year whose SaldoBalance is the "from" side of the comparison. */
  fromYear: number;
  /** The next year (or the cut-over year) whose Primobeholdning is the "to" side. */
  toYear: number;
  accountNo: string;
  /** The archived closing balance (kroner). */
  closingAmount: number;
  /** The opening balance the next year actually carries (kroner). */
  openingAmount: number;
};

export type RollForwardVatGroup = {
  group: "vat";
  closingAmount: number;
  openingAmount: number;
  difference: number;
  accountNos: string[];
  status: "continuous" | "explained_reclassification" | "explained_source_consolidation" | "unexplained";
  explanation?: {
    fiscalYear: number;
    voucher: string;
    transactionDate: string;
    voucherType: string;
    text: string;
    perAccountDeltas: Array<{ accountNo: string; closingAmount: number; openingAmount: number; voucherAmount: number }>;
    sourceAccountNos: string[];
    destinationAccountNo: string;
    transferAmount: number;
  };
  sourceConsolidation?: {
    fromYear: number;
    toYear: number;
    destinationAccountNo: string;
    perAccountDeltas: Array<{ accountNo: string; closingAmount: number; openingAmount: number }>;
  };
};

export type RollForwardSourceConsolidation = {
  group: "fixed_asset";
  accountNos: string[];
  destinationAccountNo: string;
  closingAmount: number;
  openingAmount: number;
  perAccountDeltas: Array<{ accountNo: string; closingAmount: number; openingAmount: number }>;
};

definition.handlerSpecificParsing:
(ctx) => {
    const file = ctx.arg("--file");
    if (!file) {
      console.error("Missing required --file <export-file-or-directory>");
      process.exit(2);
    }
    if (!existsSync(file)) {
      console.error(`Export path does not exist: ${file}`);
      process.exit(2);
    }
    const system = ctx.trimToNull(ctx.arg("--system")) ?? "synthetic-csv";
    const parser = PARSERS[system];
    if (!parser) {
      console.error(
        `Unknown --system '${system}'. Available: ${Object.keys(PARSERS).join(", ")}`,
      );
      process.exit(2);
    }

    const db = openCommandDb(ctx);
    migrate(db);
    const result = runImportFromSource(db, parser, file, {
      createdBy: ctx.cliActor ?? process.env.RENTEMESTER_ACTOR ?? ctx.inferredMutationActor() ?? undefined,
      createdByProgram: "rentemester-import-cli",
      dryRun: ctx.hasFlag("--dry-run"),
    });
    ctx.emitResult(result as unknown as Record<string, unknown>);
    db.close();
    if (!result.ok) process.exit(1);
  }

definition.exactParser:
const BOOLEAN_FLAGS = new Set([
  "--force",
  "--help",
  "--example",
  "--json",
  "--sign-with-ed25519",
  "--archive",
  "--enrich-cvr",
  "--include-archived",
  "--ixbrl-taxonomy",
  "--after-retention-expiry",
  "--no-vat",
  "--no-open",
]);

export type ParsedCliArgs = {
  positionals: string[];
  flags: Map<string, string | true>;
  errors: string[];
};

export function parseCliArgs(argv: string[]): ParsedCliArgs {
  const tokens = argv.slice(2);
  const positionals: string[] = [];
  const flags = new Map<string, string | true>();
  const errors: string[] = [];

  let optionsTerminated = false;

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i]!;

    if (!optionsTerminated && token === "--") {
      optionsTerminated = true;
      continue;
    }

    if (optionsTerminated || !token.startsWith("--")) {
      positionals.push(token);
      continue;
    }

    // `--flag=value` form: value is attached, so it may begin with dashes
    // or be empty without being confused for a missing-value error.
    const eq = token.indexOf("=");
    if (eq !== -1) {
      const name = token.slice(0, eq);
      const value = token.slice(eq + 1);
      if (BOOLEAN_FLAGS.has(name)) {
        errors.push(`Flag ${name} does not take a value`);
        continue;
      }
      flags.set(name, value);
      continue;
    }

    if (BOOLEAN_FLAGS.has(token)) {
      const next = tokens[i + 1];
      if (next && next !== "--" && !next.startsWith("--")) {
        errors.push(`Flag ${token} does not take a value`);
        i += 1;
        continue;
      }
      flags.set(token, true);
      continue;
    }

    const value = tokens[i + 1];
    if (value === undefined || value === "--" || value.startsWith("--")) {
      errors.push(`Flag ${token} requires a value`);
      continue;
    }
    flags.set(token, value);
    i += 1;
  }

  return { positionals, flags, errors };
}

stdout.genericRenderer:
import { formatKronerDa } from "../core/money";

export type OutputFormat = "json" | "human";

export function resolveOutputFormat(flags: Map<string, string | true>): OutputFormat | null {
  if (flags.has("--json")) return "json";
  const format = flags.get("--format");
  if (format === undefined) return process.stdout.isTTY ? "human" : "json";
  if (format === "json" || format === "human") return format;
  return null;
}

export function printStructuredResult(commandLabel: string, result: Record<string, unknown>, format: OutputFormat) {
  const ok = result.ok !== false;
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  const lines = ok ? buildHumanSuccess(commandLabel, result) : buildHumanError(commandLabel, result);
  const text = lines.join("\n");
  if (ok) console.log(text);
  else console.error(text);
}

/**
 * A command's `description` in `cli-meta.ts` is a full sentence (often two)
 * meant for help text — never a heading. #268: a write command that falls
 * through to the generic human renderer used to print that whole description
 * as the `✔` heading. `headingFromLabel` collapses such a label to a short
 * heading: the first clause before an em dash / period, capped in length.
 */
function headingFromLabel(commandLabel: string): string {
  const firstClause = commandLabel.split(/\s+[—–-]\s+|\.\s/)[0]?.trim() ?? commandLabel;
  const short = firstClause.length > 0 ? firstClause : commandLabel;
  return short.length > 60 ? `${short.slice(0, 57).trimEnd()}…` : short;
}

function buildHumanSuccess(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✔ ${headingFromLabel(commandLabel)}`];
  for (const line of collectSummaryLines(result)) lines.push(`  ${line}`);
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  return lines;
}

export function buildHumanError(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✘ ${commandLabel} failed`];
  const errors = asStringArray(result.errors);
  if (errors.length > 0) {
    for (const error of errors) lines.push(`  → ${error}`);
  } else {
    lines.push("  → Kommandoen fejlede uden en specifik fejlbesked.");
  }
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  appendPeriodCloseGuidance(lines, errors);
  return lines;
}

/**
 * `vat momsangivelse` and `report annual` reject an unfinalised period with a
 * terse "... is not closed ... run 'period close' first". For an owner near a
 * deadline that is cryptic, so when we recognise that failure we append a
 * plain-Danish explanation of what closing a period means and the exact
 * command to run. (#227)
 */
function appendPeriodCloseGuidance(lines: string[], errors: string[]): void {
  const closeError = errors.find(
    (e) => /is not closed/i.test(e) && /period close/i.test(e),
  );
  if (!closeError) return;
  const range = closeError.match(/(\d{4}-\d{2}-\d{2})\.\.(\d{4}-\d{2}-\d{2})/);
  const isFiscalYear = /fiscal|regnskabsår|annual/i.test(closeError);
  const kind = isFiscalYear ? "fiscal_year" : "vat_period";
  const fromTo = range ? `--from ${range[1]} --to ${range[2]}` : "--from <YYYY-MM-DD> --to <YYYY-MM-DD>";
  lines.push("");
  lines.push("  Sådan kommer du videre:");
  lines.push(
    "    En momsangivelse/årsrapport kan kun bygges på en LUKKET periode — det sikrer,",
  );
  lines.push(
    "    at tallene ikke ændrer sig efter indberetning. Du lukker perioden med:",
  );
  lines.push(`      rentemester period close --company <path> ${fromTo} --kind ${kind}`);
  lines.push(
    "    Luk først perioden når alle bilag for perioden er bogført — en lukket periode",
  );
  lines.push(
    "    blokerer ny bogføring med dato i perioden. Brug --status reported i stedet for",
  );
  lines.push(
    "    standard 'closed', hvis du allerede har indberettet til SKAT/Erhvervsstyrelsen.",
  );
}

/**
 * Danish labels for the result keys a write command commonly returns. The
 * generic human fallback (`collectSummaryLines`) used to English-ify keys via
 * `humanizeKey` ("Invoice Number", "Document Id"); for a Danish-facing tool
 * that is wrong. Any key without an entry here keeps the humanized form, but
 * the common write-result fields are now translated. (#268)
 *
 * Round-2 review (Batch E-1) expanded the set so read commands that return
 * single objects (audit verify, company profile, gdpr export/forget,
 * customer create, invoice post) actually render meaningful content under
 * `--format human` instead of just echoing the command description.
 */
const WRITE_RESULT_LABEL_DA: Record<string, string> = {
  message: "Besked",
  invoiceNumber: "Fakturanummer",
  invoiceNo: "Fakturanummer",
  entryNo: "Posteringsnummer",
  entryNumber: "Posteringsnummer",
  documentId: "Bilags-id",
  journalEntryId: "Finanspostering-id",
  importBatchId: "Import-batch-id",
  imported: "Importeret",
  skippedDuplicates: "Sprunget over (dubletter)",
  backupId: "Backup-id",
  exportDir: "Eksportmappe",
  latestBackupId: "Seneste backup-id",
  expiredCount: "Udløbne",
  totalCount: "I alt",
  storedPath: "Gemt fil",
  pdfStoredPath: "PDF-fil",
  // Batch E-1: read-command friendly labels.
  entries: "Posteringer kontrolleret",
  chainOk: "Kæden er hel",
  erasedCount: "Anonymiseret",
  skippedCount: "Sprunget over",
  alreadyErasedCount: "Allerede anonymiseret",
  recordCount: "Rækker fundet",
  count: "Antal",
  total: "I alt",
  // Profile / contact fields (company profile, customer/vendor create).
  name: "Navn",
  cvr: "CVR",
  email: "E-mail",
  address: "Adresse",
  postalCode: "Postnummer",
  city: "By",
  country: "Land",
  currency: "Valuta",
  paymentTermsDays: "Betalingsfrist (dage)",
  vatPeriodType: "Momsperiode",
  vatPeriodLabel: "Momsstatus",
  vatRegistered: "Momsregistreret",
  companyForm: "Selskabsform",
  industryText: "Branche",
  cvrStatus: "CVR-status",
  auditWaived: "Revision fravalgt",
  fiscalYearStartMonth: "Regnskabsår starter (måned)",
  customerId: "Kunde-id",
  vendorId: "Leverandør-id",
  slug: "Slug",
};

/**
 * Top-level keys whose VALUE is a nested object that should be drilled into
 * — every scalar field inside becomes its own labelled line. Lets commands
 * like `company profile` (returns `{ ok, profile: {...} }`) emit each profile
 * field without per-command renderers. Batch E-1.
 */
const NESTED_DRILL_KEYS = new Set<string>([
  "profile",
  "customer",
  "vendor",
  "company",
  "settings",
  "depreciation",
  "writeOff",
  "reminder",
  "credit",
  "suggestion",
  "summary",
]);

function collectSummaryLines(result: Record<string, unknown>) {
  const preferredKeys = [
    "message",
    "invoiceNumber",
    "invoiceNo",
    "entryNo",
    "entryNumber",
    "documentId",
    "journalEntryId",
    "importBatchId",
    "imported",
    "skippedDuplicates",
    "backupId",
    "exportDir",
    "latestBackupId",
    "expiredCount",
    "totalCount",
    "entries",
    "chainOk",
    "erasedCount",
    "skippedCount",
    "alreadyErasedCount",
    "recordCount",
    "count",
    "total",
    "name",
    "cvr",
    "email",
    "address",
    "postalCode",
    "city",
    "country",
    "currency",
    "paymentTermsDays",
    "vatPeriodType",
    "vatPeriodLabel",
    "vatRegistered",
    "companyForm",
    "industryText",
    "cvrStatus",
    "auditWaived",
    "fiscalYearStartMonth",
    "customerId",
    "vendorId",
    "slug",
  ];
  const lines: string[] = [];
  const seen = new Set<string>();
  for (const key of preferredKeys) {
    if (seen.has(key)) continue;
    const value = result[key];
    const rendered = renderScalar(value);
    if (rendered === null) continue;
    // #268: never emit an English key on a Danish-facing tool — use the Danish
    // label when one exists, falling back to the humanized form otherwise.
    lines.push(
      `${WRITE_RESULT_LABEL_DA[key] ?? humanizeKey(key)}: ${translateValueForKey(key, rendered)}`,
    );
    seen.add(key);
  }
  // Batch E-1: drill one level into well-known nested-object keys. Lets
  // `company profile` (returns `{ ok, profile: {...} }`) actually render
  // each profile field instead of showing only "✔ <command description>".
  for (const [key, value] of Object.entries(result)) {
    if (!NESTED_DRILL_KEYS.has(key)) continue;
    if (value == null || typeof value !== "object" || Array.isArray(value)) continue;
    const inner = value as Record<string, unknown>;
    for (const [innerKey, innerValue] of Object.entries(inner)) {
      if (seen.has(innerKey)) continue;
      const rendered = renderScalar(innerValue);
      if (rendered === null) continue;
      lines.push(
        `${WRITE_RESULT_LABEL_DA[innerKey] ?? humanizeKey(innerKey)}: ${translateValueForKey(innerKey, rendered)}`,
      );
      seen.add(innerKey);
    }
  }
  return lines;
}

function renderScalar(value: unknown): string | null {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return null;
}

/**
 * Danish display values for the handful of enum-valued profile fields whose raw
 * stored form is an English token (e.g. `quarter`, `end-year`). #268 already
 * translates the key (label) into Danish; this translates the VALUE so an owner
 * never sees "Momsperiode: quarter". Keyed by field, then by raw value; unknown
 * fields/values pass through unchanged.
 */
const VALUE_LABEL_DA: Record<string, Record<string, string>> = {
  vatPeriodType: {
    month: "måned",
    quarter: "kvartal",
    "half-year": "halvår",
  },
  vatRegistered: {
    true: "Ja",
    false: "Nej",
  },
  fiscalYearLabelStrategy: {
    "end-year": "slutår",
    "start-year": "startår",
  },
};

function translateValueForKey(key: string, rendered: string): string {
  return VALUE_LABEL_DA[key]?.[rendered] ?? rendered;
}

function humanizeKey(key: string) {
  return key
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/_/g, " ")
    .replace(/^./, (c) => c.toUpperCase());
}

export function asStringArray(value: unknown) {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

/**
 * Format a DKK amount as Danish kroner-og-øre, e.g. 38.3 -> "38,30 kr.",
 * -1234.5 -> "-1.234,50 kr.". Non-finite/missing input yields "—".
 *
 * Thin re-export of the single canonical formatter `formatKronerDa` in
 * `core/money.ts` — kept under the historical name so the many call sites in
 * this file stay unchanged. (#314)
 */
export function formatKroner(value: unknown): string {
  return formatKronerDa(value);
}

/** Render an integer count, falling back to 0 for missing values. */
export function asCount(value: unknown): number {
  const num = typeof value === "number" ? value : Number(value);
  return Number.isFinite(num) ? num : 0;
}

export function asText(value: unknown, fallback = "—"): string {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  return fallback;
}

export function asArray(value: unknown): Array<Record<string, unknown>> {
  return Array.isArray(value)
    ? value.filter((item): item is Record<string, unknown> => typeof item === "object" && item !== null)
    : [];
}

/**
 * Format a percentage with Danish decimal comma, e.g. 8.05 -> "8,05 %".
 * Non-finite/missing input yields "—".
 */
export function formatPercent(value: unknown): string {
  const num = typeof value === "number" ? value : Number(value);
  if (value == null || value === "" || !Number.isFinite(num)) return "—";
  const text = (Math.round(num * 100) / 100)
    .toString()
    .replace(".", ",");
  return `${text} %`;
}

export function appendWarnings(lines: string[], result: Record<string, unknown>): void {
  const warnings = asStringArray(result.warnings);
  if (warnings.length === 0) return;
  lines.push("");
  lines.push("Advarsler:");
  for (const warning of warnings) lines.push(`  - ${warning}`);
}

stdout.reportDispatch:
import { type OutputFormat, buildHumanError, printStructuredResult } from "./common";
import { renderVatReport, renderVatFiling, renderAnnualReport, renderTaxReturn } from "./vat";
import {
  renderInvoiceStatus,
  renderInvoiceInterest,
  renderInvoiceCompensation,
  renderInvoiceValidate,
  renderInvoiceCreate,
} from "./invoice";
import {
  renderBackupStatus,
  renderExceptionsList,
  renderTrialBalance,
  renderProfitAndLoss,
  renderBalanceSheet,
  renderRetentionStatus,
} from "./dashboard";
import { renderBankReconciliation } from "./bank";

// ===========================================================================
// HUMAN-READABLE REPORT RENDERING — DISPATCH (#211)
// ---------------------------------------------------------------------------
// Read/report commands emit deterministic JSON with English field names for
// agents. When a human runs them (`--format human` / a TTY) that JSON is
// unreadable. `renderHumanReport` renders the same payloads in clear Danish
// with money in kroner-og-øre. The `--format json` path is untouched: handlers
// keep calling `ctx.emitResult` for JSON and only branch into this renderer
// for the human format.
// ===========================================================================

/** Report kinds with a dedicated Danish human renderer. */
export type HumanReportKind =
  | "vat-report"
  | "vat-filing"
  | "report-annual"
  | "report-tax"
  | "invoice-status"
  | "invoice-interest"
  | "invoice-compensation"
  | "invoice-validate"
  | "exceptions-list"
  | "report-trial-balance"
  | "report-profit-loss"
  | "report-balance"
  | "retention-status"
  | "reconcile-bank"
  | "backup-status"
  // #177: `report annual --ixbrl-taxonomy` prints the bounded iXBRL subset.
  // No dedicated renderer — it falls back to the generic structured output.
  | "report-annual-ixbrl-taxonomy";

/**
 * Render a read/report `result` payload as Danish human-readable text.
 *
 * Returns `null` when there is no dedicated renderer for `kind` or the payload
 * does not look renderable, so callers can fall back to the generic
 * `printStructuredResult` rendering.
 */
export function renderHumanReport(
  kind: HumanReportKind,
  result: Record<string, unknown>,
): string | null {
  // `backup-status` reports `ok: false` when the weekly backup duty is NOT met
  // — that is a valid compliance status to render, not a command failure. Its
  // renderer handles both states, so it must run before the generic
  // ok-false-as-error path. (#240)
  if (kind === "backup-status") {
    return renderBackupStatus(result);
  }
  // `invoice validate` reports `ok: false` when the payload is INVALID — that
  // is a valid validation verdict to render in full (the figures and every
  // rejection reason), not a command crash. Its renderer covers both the
  // valid and invalid verdict, so it must run before the generic
  // ok-false-as-error path. (#250)
  if (kind === "invoice-validate") {
    return renderInvoiceValidate(result);
  }
  if (result.ok === false) {
    return buildHumanError(humanReportTitle(kind), result).join("\n");
  }
  switch (kind) {
    case "vat-report":
      return renderVatReport(result);
    case "vat-filing":
      return renderVatFiling(result);
    case "report-annual":
      return renderAnnualReport(result);
    case "report-tax":
      return renderTaxReturn(result);
    case "invoice-status":
      return renderInvoiceStatus(result);
    case "invoice-interest":
      return renderInvoiceInterest(result);
    case "invoice-compensation":
      return renderInvoiceCompensation(result);
    case "exceptions-list":
      return renderExceptionsList(result);
    case "report-trial-balance":
      return renderTrialBalance(result);
    case "report-profit-loss":
      return renderProfitAndLoss(result);
    case "report-balance":
      return renderBalanceSheet(result);
    case "retention-status":
      return renderRetentionStatus(result);
    case "reconcile-bank":
      return renderBankReconciliation(result);
    default:
      // `backup-status` and `invoice-validate` are handled before this switch
      // (their renderers cover the ok:false state too), so they never reach
      // here.
      return null;
  }
}

/**
 * Emit a read/report `result` either as the byte-stable agent JSON or as the
 * Danish human rendering, depending on `format`. The `--format json` path is
 * exactly `JSON.stringify(result, null, 2)` — unchanged from `emitResult` —
 * so agents see no difference. Only the human rendering is new.
 *
 * Returns the process exit code to apply (1 when `result.ok === false`).
 */
export function emitHumanReport(
  kind: HumanReportKind,
  result: Record<string, unknown>,
  format: OutputFormat,
): void {
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    const human = renderHumanReport(kind, result);
    if (human !== null) {
      if (result.ok === false) console.error(human);
      else console.log(human);
    } else {
      printStructuredResult(humanReportTitle(kind), result, format);
    }
  }
  if (result.ok === false) process.exitCode = 1;
}

function humanReportTitle(kind: HumanReportKind): string {
  switch (kind) {
    case "vat-report":
      return "Momsrapport";
    case "vat-filing":
      return "Momsangivelse";
    case "report-annual":
      return "Årsrapport";
    case "report-tax":
      return "Skattemæssig indkomst";
    case "invoice-status":
      return "Fakturastatus";
    case "invoice-interest":
      return "Morarente";
    case "invoice-compensation":
      return "Kompensation for sen betaling";
    case "invoice-validate":
      return "Fakturavalidering";
    case "exceptions-list":
      return "Undtagelser";
    case "report-trial-balance":
      return "Saldobalance";
    case "report-profit-loss":
      return "Resultatopgørelse";
    case "report-balance":
      return "Balance";
    case "retention-status":
      return "Opbevaringsstatus";
    case "reconcile-bank":
      return "Bankafstemning";
    case "backup-status":
      return "Backup-status";
    case "report-annual-ixbrl-taxonomy":
      return "iXBRL-taksonomi (afgrænset udsnit)";
  }
}

/** Write-command kinds with a dedicated Danish human renderer. (#266, #268) */
export type HumanWriteKind = "invoice-create";

/**
 * Emit a write-command `result` either as the byte-stable agent JSON or as a
 * Danish human rendering, depending on `format`. The `--format json` path is
 * exactly `JSON.stringify(result, null, 2)` — unchanged from `emitResult` — so
 * agents see no difference. Sets `process.exitCode = 1` on `ok: false`. (#268)
 */
export function emitHumanWrite(
  kind: HumanWriteKind,
  result: Record<string, unknown>,
  format: OutputFormat,
): void {
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    const human = kind === "invoice-create" ? renderInvoiceCreate(result) : null;
    if (human !== null) {
      if (result.ok === false) console.error(human);
      else console.log(human);
    } else {
      printStructuredResult(kind, result, format);
    }
  }
  if (result.ok === false) process.exitCode = 1;
}

