export type AgentRunInput = {
  /** Absolute path to an initialised company directory. */
  companyRoot: string;
  /** The explicit "now" for the run. YYYY-MM-DD. The only clock the agent has. */
  asOf: string;
  /**
   * Directory holding bilag (one document file per bilag). Each file must
   * have a sibling `<stem>.json` in `metadataDir`. This is the maildrop the
   * agent ingests from. Optional — omit it for a deadline-only run.
   */
  inboxDir?: string;
  /** Directory holding the parallel metadata JSON files. Defaults to inboxDir. */
  metadataDir?: string;
  /** Absolute path to a bank-statement CSV to import. Optional. */
  bankCsvPath?: string;
};

export type AgentRunReport = {
  ok: boolean;
  /** Canonical actor the agent booked under. */
  actor: string;
  asOf: string;
  company: string;
  /** Phases the loop executed, in order. */
  phases: string[];
  documentsIngested: number;
  documentsRejected: number;
  bankTransactionsImported: number;
  expensesBooked: BookedExpense[];
  /**
   * Creditor items the agent settled automatically from an exact-match
   * outgoing bank payment. Additive field — empty on a run with no payables.
   */
  payablesMatched: PayableMatch[];
  /**
   * Count of accrual recognition periods that are due/overdue and not yet
   * posted, surfaced as `AGENT_ACCRUAL_RECOGNITION_DUE` exceptions. The agent
   * never posts the recognition entry — it surfaces the pending work.
   */
  accrualRecognitionsDue: number;
  /** Exceptions left open at end of run — the human's work list. */
  openExceptions: RoutedException[];
  upcomingDeadlines: DeadlineNotice[];
  /** Plain-language lines describing what was done and what needs the human. */
  summary: string[];
  errors: string[];
};

export type BookedExpense = {
  documentNo: string;
  documentId: number;
  bankTransactionId: number;
  supplier: string;
  amount: number;
  currency: string;
  expenseAccount: string;
  vatTreatment: SupplierRule["vatTreatment"];
  label: string;
  journalEntryNo: string | null;
};

export type SupplierRule = {
  token: string;
  expenseAccount: string;
  vatTreatment: "standard" | "reverse_charge" | "representation" | "exempt";
  label: string;
  /**
   * True when the rule's category buys *physical equipment* — hardware,
   * machinery, inventory — i.e. the kind of purchase that may be a
   * capitalisable fixed asset rather than an operating expense (#223). A
   * materially sized purchase in an asset-like category is never auto-booked:
   * it is routed to the exception queue for a human/asset decision.
   */
  assetLike?: boolean;
};

export type PayableMatch = {
  payableId: number;
  documentId: number;
  bankTransactionId: number;
  supplier: string;
  amount: number;
  /** The settlement journal entry number, or `null` if unavailable. */
  journalEntryNo: string | null;
};

export type RoutedException = {
  exceptionId: number;
  type: string;
  severity: string;
  message: string;
  requiredAction: string | null;
};

export type DeadlineNotice = {
  kind: "vat_period" | "fiscal_year";
  periodStart: string;
  periodEnd: string;
  /** Statutory filing/finalisation deadline. */
  dueDate: string;
  daysRemaining: number;
  /** Whether the period is already closed/reported and ready to file. */
  ready: boolean;
  note: string;
};

type InboxBilag = {
  stem: string;
  filePath: string;
  metadata: DocumentMetadata;
};

export type DocumentMetadata = {
  source: string;
  documentType?: DocumentType;
  issueDate?: string;
  invoiceNo?: string;
  deliveryDescription?: string;
  amountIncVat?: number;
  currency?: string;
  sender?: { name?: string; address?: string; vatOrCvr?: string; countryCode?: string; identifierKind?: SupplierIdentifierKind };
  recipient?: { name?: string; address?: string; vatOrCvr?: string };
  vatAmount?: number;
  /** Purchase tax bases, retained verbatim with the voucher.  Omit for legacy uniform VAT documents. */
  purchaseVatLines?: PurchaseVatLine[];
  /** Human-confirmed invoice evidence required before a non-EU service can be
   * posted with automatic reverse-charge input-VAT deduction. */
  reverseChargeWordingConfirmed?: boolean;
  /** Explicit source fact: the issuer supplied a Danish simplified purchase invoice. */
  danishSimplifiedPurchaseInvoice?: boolean;
  paymentDetails?: string;
  exemptionCode?: DocumentExemptionCode;
  /** Imported bank row that is the immutable primary evidence for an internal voucher. */
  sourceBankTransactionId?: number;
  /** Human accounting explanation for why the internal voucher is booked. */
  accountingRationale?: string;
};

export type DocumentType =
  | "purchase_sale"
  | "cash_register_receipt"
  | "issued_invoice_pdf"
  | "internal_voucher";

