    for (const err of report.errors) lines.push(`  ✗ ${err}`);
    return lines.join("\n");
  }

  lines.push("");
  lines.push("— Bogført automatisk —");
  if (report.expensesBooked.length === 0) {
    lines.push("  (ingen)");
  } else {
    for (const e of report.expensesBooked) {
      lines.push(
        `  ✓ ${e.supplier} ${fmtAmount(e.amount, e.currency)} → konto ${e.expenseAccount} ` +
          `(${e.label}, moms=${e.vatTreatment})` +
          (e.journalEntryNo ? ` [${e.journalEntryNo}]` : ""),
      );
    }
  }

  lines.push("");
  lines.push("— Kreditorposter afregnet automatisk —");
  if (report.payablesMatched.length === 0) {
    lines.push("  (ingen)");
  } else {
    for (const p of report.payablesMatched) {
      lines.push(
        `  ✓ ${p.supplier} ${formatKronerDa(p.amount)} → kreditorpost #${p.payableId}` +
          (p.journalEntryNo ? ` [${p.journalEntryNo}]` : ""),
      );
    }
  }

  lines.push("");
  lines.push("— Exception-kø (kræver et menneske) —");
  if (report.openExceptions.length === 0) {
    lines.push("  ✓ ingen åbne exceptions");
  } else {
    for (const ex of report.openExceptions) {
      lines.push(`  ! [${ex.severity}] #${ex.exceptionId} ${ex.type}: ${ex.message}`);
      if (ex.requiredAction) lines.push(`      → ${ex.requiredAction}`);
    }
  }

  lines.push("");
  lines.push("— Kommende deadlines —");
  if (report.upcomingDeadlines.length === 0) {
    lines.push("  ✓ ingen deadlines inden for horisonten");
  } else {
    for (const d of report.upcomingDeadlines) {
      const label = d.kind === "vat_period" ? "Momsangivelse" : "Årsrapport";
      lines.push(
        `  ${d.ready ? "✓" : "!"} ${label} ${d.periodStart}..${d.periodEnd} — ` +
          `forfalder ${d.dueDate} (${d.daysRemaining} dage)`,
      );
      lines.push(`      ${d.note}`);
    }
  }

  lines.push("");
  lines.push("=== Kørsel afsluttet ===");
  for (const s of report.summary) lines.push(`  • ${s}`);

  return lines.join("\n");
}

function fmtAmount(n: number, ccy: string): string {
  if (normalizeCurrency(ccy) === "DKK") return formatKronerDa(n);
  const sign = n < 0 ? "-" : "";
  const abs = Math.abs(n);
  return `${sign}${abs.toLocaleString("da-DK", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })} ${normalizeCurrency(ccy)}`;
}

export function formatKronerDa(value: unknown): string {
  const num = typeof value === "number" ? value : Number(value);
  if (value == null || value === "" || !Number.isFinite(num)) return "—";
  // Round through integer øre (the same half-up BigInt path as `formatAmount`
  // and `roundDkk`) rather than float `Math.round(num * 100)`, which drifts one
  // øre on exact halves (1.005 → "1,00" instead of "1,01"). The sign is taken
  // from the ROUNDED øre, so a sub-øre negative that rounds to zero renders
  // "0,00 kr." and never a misleading "-0,00 kr.". The browser copy in
  // app/src/lib/format.ts mirrors this with its own BigInt rounding. (#314)
  const ore = toOre(num);
  const negative = ore < 0n;
  const abs = negative ? -ore : ore;
  const whole = abs / 100n;
  const fraction = (abs % 100n).toString().padStart(2, "0");
  const wholeText = whole.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return `${negative ? "-" : ""}${wholeText},${fraction} kr.`;
}

typeDeclarations.source:
export type AgentRunInput = {
  /** Absolute path to an initialised company directory. */
  companyRoot: string;
  /** The explicit "now" for the run. YYYY-MM-DD. The only clock the agent has. */
  asOf: string;
  /**
   * Directory holding bilag (one document file per bilag). Each file must
   * have a sibling `<stem>.json` in `metadataDir`. This is the maildrop the
   * agent ingests from. Optional — omit it for a deadline-only run.
   */
  inboxDir?: string;
  /** Directory holding the parallel metadata JSON files. Defaults to inboxDir. */
  metadataDir?: string;
  /** Absolute path to a bank-statement CSV to import. Optional. */
  bankCsvPath?: string;
};

export type AgentRunReport = {
  ok: boolean;
  /** Canonical actor the agent booked under. */
  actor: string;
  asOf: string;
  company: string;
  /** Phases the loop executed, in order. */
  phases: string[];
  documentsIngested: number;
  documentsRejected: number;
  bankTransactionsImported: number;
  expensesBooked: BookedExpense[];
  /**
   * Creditor items the agent settled automatically from an exact-match
   * outgoing bank payment. Additive field — empty on a run with no payables.
   */
  payablesMatched: PayableMatch[];
  /**
   * Count of accrual recognition periods that are due/overdue and not yet
   * posted, surfaced as `AGENT_ACCRUAL_RECOGNITION_DUE` exceptions. The agent
   * never posts the recognition entry — it surfaces the pending work.
   */
  accrualRecognitionsDue: number;
  /** Exceptions left open at end of run — the human's work list. */
  openExceptions: RoutedException[];
  upcomingDeadlines: DeadlineNotice[];
  /** Plain-language lines describing what was done and what needs the human. */
  summary: string[];
  errors: string[];
};

export type BookedExpense = {
  documentNo: string;
  documentId: number;
  bankTransactionId: number;
  supplier: string;
  amount: number;
  currency: string;
  expenseAccount: string;
  vatTreatment: SupplierRule["vatTreatment"];
  label: string;
  journalEntryNo: string | null;
};

export type SupplierRule = {
  token: string;
  expenseAccount: string;
  vatTreatment: "standard" | "reverse_charge" | "representation" | "exempt";
  label: string;
  /**
   * True when the rule's category buys *physical equipment* — hardware,
