export function renderRegulatoryCitationsReview(
  rootDir: string = repoRoot(),
): string {
  const provisionsBySource = loadAllProvisions(rootDir);
  const rules = readRuleMetadata()
    .filter((rule) => rule.provisions.length > 0)
    .sort((a, b) => compareStrings(a.ruleId, b.ruleId));

  const lines: string[] = [];
  lines.push("# Regulatory citation review");
  lines.push("");
  lines.push(
    "Generated by `rentemester reg citations`. For every rule that cites a " +
      "statutory provision, this lists the rule and the verbatim legislation " +
      "text it is mapped to, so the mapping can be reviewed by eye. " +
      "Deterministic — no timestamps.",
  );
  lines.push("");

  for (const rule of rules) {
    lines.push(`## ${rule.ruleId}`);
    lines.push("");
    lines.push(`- Source: ${rule.sourceId}`);
    if (rule.name) lines.push(`- Name: ${rule.name}`);
    if (rule.explanation) lines.push(`- Explanation: ${rule.explanation}`);
    lines.push("");
    const sourceProvisions = provisionsBySource.get(rule.sourceId) ?? [];
    for (const citation of rule.provisions) {
      lines.push(`### \`${citation.ref}\``);
      lines.push("");
      const resolved = findProvision(sourceProvisions, citation.ref);
      if (!resolved) {
        lines.push("_Does not resolve in the declared source (closure error)._");
      } else {
        lines.push("> " + (resolved.text.length > 0 ? resolved.text : "(empty)"));
      }
      lines.push("");
    }
  }

  return lines.join("\n").replace(/\n+$/, "\n");
}

function repoRoot(): string {
  return fileURLToPath(new URL("../../", import.meta.url));
}

export function loadAllProvisions(rootDir: string = repoRoot()): Map<string, Provision[]> {
  const downloadedDir = join(rootDir, "sources", "downloaded");
  const indexPath = join(downloadedDir, "index.json");
  const index = JSON.parse(readFileSync(indexPath, "utf8")) as Array<{ id: string; localPath: string }>;
  const sorted = [...index].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  const result = new Map<string, Provision[]>();
  for (const entry of sorted) {
    const xmlPath = join(rootDir, entry.localPath);
    const xmlText = readFileSync(xmlPath, "utf8");
    result.set(entry.id, extractProvisions(xmlText, entry.id));
  }
  return result;
}

export function readRuleMetadata(): RuleMetadata[] {
  const rules: RuleMetadata[] = [];
  for (const file of readdirSync(rulesDir).filter((f) => f.endsWith(".yaml")).sort()) {
    const bundle = file.replace(/\.yaml$/, "");
    rules.push(...parseRuleBundle(readFileSync(join(rulesDir, file), "utf8"), bundle));
  }
  rules.sort((a, b) => (a.ruleId < b.ruleId ? -1 : a.ruleId > b.ruleId ? 1 : 0));
  return rules;
}

function compareStrings(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

export function findProvision(provisions: Provision[], ref: string): Provision | undefined {
  const path = parseProvisionRef(ref);
  if (!path) return undefined;
  return provisions.find((provision) =>
    provision.path.length === path.length
    && provision.path.every((segment, index) => segment === path[index]));
}

