export type CompanySettings = {
  id: number;
  name: string;
  country: string;
  currency: string;
  cvr: string | null;
  fiscalYearStartMonth: number;
  fiscalYearLabelStrategy: FiscalYearLabelStrategy;
  /** CVR-register stamdata, last written by `company sync-cvr`. */
  address: string | null;
  postalCode: string | null;
  city: string | null;
  companyForm: string | null;
  industryCode: string | null;
  industryText: string | null;
  cvrStatus: string | null;
  auditWaived: boolean | null;
  /** ISO timestamp the CVR stamdata above was last synced; null when never. */
  cvrSyncedAt: string | null;
  /**
   * #221: the owner's own default payment terms — days from an invoice's issue
   * date to its due date. Captured once so every issued invoice inherits it.
   */
  paymentTermsDays: number;
  /**
   * #289: the VAT settlement cadence the company is registered for with SKAT
   * (`month` / `quarter` / `half-year`). Drives VAT period windows and their
   * filing deadlines. `null` means the company is NOT VAT-registered
   * (holding ApS, frivilligt momsfritaget, mikrovirksomhed under § 48); every
   * VAT-aware surface (dashboard, obligations, momsangivelse) gates on this.
   */
  vatPeriodType: VatPeriodType | null;
};

export type VerifyAuditChainOptions = {
  /**
   * Root whose on-disk evidence is being verified. Restore must pass its
   * staging root explicitly; normal live callers can rely on DB-path inference.
   */
  companyRoot?: string;
};

type AuditEvidenceDocument = {
  id: number;
  document_no?: string | null;
  sha256_hash: string | null;
  stored_path: string | null;
  document_type: string;
};

export type InvoiceJournalApplicationCandidate = {
  kind: InvoiceJournalApplicationKind;
  invoiceDocumentId: number;
  bankTransactionId: number | null;
  journalEntryId: number | null;
  effectiveDate: string;
  amount: number;
  currency: string;
};

type InvoiceJournalApplication = InvoiceJournalApplicationCandidate & {
  applicationId: number | null;
};

type JournalEvidence = {
  id: number;
  document_id: number | null;
  source_bank_transaction_id: number | null;
  transaction_date: string;
  registration_datetime: string;
  currency: string | null;
  amount_foreign: number | null;
  amount_dkk: number | null;
  status: string;
  reversed_by_entry_id: number | null;
};

type BankEvidence = {
  id: number;
  amount: number;
  currency: string | null;
  amount_dkk: number | null;
  bank_account_id: number | null;
  bank_account_currency: string | null;
  ledger_account_no: string | null;
};

type JournalLineEvidence = {
  account_no: string;
  debit_amount: number;
  credit_amount: number;
};

export type InvoiceStatusResult = {
  ok: boolean;
  invoiceDocumentId?: number;
  invoiceNumber?: string;
  grossAmount?: number;
  creditedAmount?: number;
  paidAmount?: number;
  openBalance?: number;
  claimOpenBalance?: number;
  asOfDate?: string;
  dueDate?: string;
  effectiveDueDate?: string;
  isOverdue?: boolean;
  overdueDays?: number;
  status?: "open" | "paid" | "credited" | "refunded" | "overpaid" | "written_off";
  payments?: Array<{
    paymentId: number;
    paymentDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  creditNotes?: Array<{
    documentId: number;
    creditNoteNumber: string;
    amount: number;
    issueDate: string | null;
  }>;
  refunds?: Array<{
    refundId: number;
    refundDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  claimPayments?: Array<{
    claimPaymentId: number;
    paymentDate: string;
    amount: number;
    bankTransactionId: number | null;
    journalEntryId: number | null;
    note: string | null;
  }>;
  badDebtWriteOffs?: Array<{
    writeOffId: number;
    writeOffDate: string;
    grossAmount: number;
    netAmount: number;
    vatAmount: number;
    journalEntryId: number;
    note: string | null;
  }>;
  reminders?: Array<{
    reminderId: number;
    reminderDate: string;
    feeAmount: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  compensationClaims?: Array<{
    claimId: number;
    claimDate: string;
    amountDkk: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  interestClaims?: Array<{
    claimId: number;
    claimDate: string;
    amountDkk: number;
    referenceRatePercent: number;
    annualInterestRatePercent: number;
    overdueDays: number;
    note: string | null;
    journalEntryId: number | null;
  }>;
  interestCorrections?: Array<{
    correctionId: number;
    correctionDate: string;
    amountDkk: number;
    journalEntryId: number;
  }>;
  totalReminderFees?: number;
  totalCompensationClaims?: number;
  totalInterestClaims?: number;
  totalInterestCorrections?: number;
  totalClaimPayments?: number;
  totalBadDebtWrittenOff?: number;
  errors: string[];
};

export type VerifyAuditLogIntegrityOptions = {
  /**
   * Cross-check every journal entry against its `journal_post` /
   * `journal_reverse` audit event. Strong, but it assumes every journal entry
   * was written through the normal posting path (ledger.applyJournalEntry /
   * reverseJournalEntry), which always logs that event in the same transaction.
   * Entries inserted by a raw INSERT that deliberately bypasses audit logging
   * (test fixtures, low-level migrations) would false-positive, so the caller
   * opts in. Defaults to true for the standalone integrity check.
   */
  journalCrossCheck?: boolean;
};

export type VerifyAuditLogIntegrityResult = {
  ok: boolean;
  /** Number of audit_log rows inspected. */
  rows: number;
  errors: string[];
};

export type RetentionStatusReport = {
  ok: boolean;
  asOf: string;
  appliedRules: string[];
  rows: RetentionStatusRow[];
  errors: string[];
};

export type RetentionStatusRow = {
  table: "documents" | "journal_entries" | "bank_transactions";
  total: number;
  expired: number;
  nextExpiry: string | null;
  oldestExpired: string | null;
};

export type BackupGovernanceStatus = {
  ok: boolean;
  appliedRules: string[];
  compliance: BackupComplianceStatus;
  lock: BackupLockEvaluation;
  destinations: BackupDestination[];
  destinationCount: number;
  compliantDestinationCount: number;
  hasCompliantDestination: boolean;
  // Whether the most recent backup has a verified placement at a
  // §4-compliant (EU/EEA, non-related, IT-secure) destination.
  latestBackupPlacedOffsite: boolean;
  latestBackupPlacementCount: number;
  checkedAt: string;
  errors: string[];
};

export type BackupComplianceStatus = {
  ok: boolean;
  appliedRules: string[];
  latestBackupAt: string | null;
  latestBackupId: string | null;
  backupDue: boolean;
