export type RegisterAccrualInput = {
  accrualType: AccrualType;
  description: string;
  totalAmount: number;
  recognitionPeriods: number;
  firstRecognitionDate: string;
  /** Posting date of the registration entry (default: firstRecognitionDate). */
  registrationDate?: string;
  periodStepMonths?: number;
  /**
   * The income-statement account each period is recognised on — an expense
   * account for prepaid/accrued expenses, an income account for deferred
   * revenue.
   */
  resultAccountNo: string;
  /** Balance-sheet parking account; defaults per accrual type. */
  balanceAccountNo?: string;
  /**
   * The settlement/payment account used on the registration entry's other
   * leg (default 2000 Bank).
   */
  settlementAccountNo?: string;
  documentId?: number;
  note?: string;
  createdBy?: string;
  createdByProgram?: string;
};

export type RegisterAccrualResult = JournalPostResult & {
  accrualId?: number;
  accrualType?: AccrualType;
  totalPeriods?: number;
  periodAmount?: number;
};

export type JournalPostResult = {
  ok: boolean;
  entryId?: JournalEntryId;
  entryNo?: string;
  entryHash?: string;
  appliedRules: string[];
  errors: string[];
};

export type AccountRoleResolution =
  | { ok: true; role: AccountRole; accountNo: string; version: number; confirmedBy: string; confirmationSource: AccountRoleConfirmationSource }
  | { ok: false; role: AccountRole; error: string };

export type ComputeAccrualScheduleInput = {
  totalAmount: number;
  recognitionPeriods: number;
  firstRecognitionDate: string;
  /** Calendar months between consecutive recognition periods (default 1). */
  periodStepMonths?: number;
};

export type AccrualSchedulePeriod = {
  periodIndex: number;
  recognitionDate: string;
  amount: number;
};

export type JournalEntryInput = {
  transactionDate: string;
  text: string;
  documentId?: number;
  sourceBankTransactionId?: number;
  currency?: string;
  amountForeign?: number;
  amountDkk?: number;
  fxRateToDkk?: number;
  createdBy?: string;
  createdByProgram?: string;
  lines: JournalLineInput[];
};

export type JournalLineInput = {
  accountNo: string;
  debitAmount?: number;
  creditAmount?: number;
  vatCode?: string;
  text?: string;
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

