export function listBudget(
  db: Database,
  filters: { period?: string; accountNo?: string } = {},
): ListBudgetResult {
  if (filters.period !== undefined && !isValidBudgetPeriod(filters.period)) {
    return { ok: false, count: 0, rows: [], errors: ["period filter must be a YYYY-MM calendar month"] };
  }

  // The effective line for each (account, period) pair is the row with the
  // highest id — append-only revisions, latest wins.
  const rows = db
    .query(
      `SELECT b.id        AS id,
              b.account_no AS account_no,
              a.name       AS account_name,
              b.period     AS period,
              b.amount     AS amount,
              b.notes      AS notes,
              b.created_at AS created_at
         FROM budget_lines b
         LEFT JOIN accounts a ON a.account_no = b.account_no
        WHERE b.id IN (
          SELECT MAX(id) FROM budget_lines GROUP BY account_no, period
        )
          AND (? IS NULL OR b.period = ?)
          AND (? IS NULL OR b.account_no = ?)
        ORDER BY b.period ASC, b.account_no ASC`,
    )
    .all(
      filters.period ?? null,
      filters.period ?? null,
      filters.accountNo ?? null,
      filters.accountNo ?? null,
    ) as EffectiveBudgetRow[];

  return {
    ok: true,
    count: rows.length,
    rows: rows.map((row) => ({
      id: row.id,
      accountNo: row.account_no,
      accountName: row.account_name,
      period: row.period,
      amount: fromOre(toOre(Number(row.amount ?? 0))),
      notes: row.notes,
      createdAt: row.created_at,
    })),
    errors: [],
  };
}

export function isValidBudgetPeriod(value: unknown): value is BudgetPeriod {
  if (typeof value !== "string") return false;
  const match = /^(\d{4})-(\d{2})$/.exec(value.trim());
  if (!match) return false;
  const month = Number(match[2]);
  return month >= 1 && month <= 12;
}

export function fromOre(value: Ore) {
  return fromScaledInt(value, 2);
}

export function toOre(value: number) {
  if (!Number.isFinite(value)) throw new Error(`invalid monetary amount: ${value}`);
  return scaledInt(value, 2);
}

export function formatKronerDa(value: unknown): string {
  const num = typeof value === "number" ? value : Number(value);
  if (value == null || value === "" || !Number.isFinite(num)) return "—";
  // Round through integer øre (the same half-up BigInt path as `formatAmount`
  // and `roundDkk`) rather than float `Math.round(num * 100)`, which drifts one
  // øre on exact halves (1.005 → "1,00" instead of "1,01"). The sign is taken
  // from the ROUNDED øre, so a sub-øre negative that rounds to zero renders
  // "0,00 kr." and never a misleading "-0,00 kr.". The browser copy in
  // app/src/lib/format.ts mirrors this with its own BigInt rounding. (#314)
  const ore = toOre(num);
  const negative = ore < 0n;
  const abs = negative ? -ore : ore;
  const whole = abs / 100n;
  const fraction = (abs % 100n).toString().padStart(2, "0");
  const wholeText = whole.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return `${negative ? "-" : ""}${wholeText},${fraction} kr.`;
}

