(ctx) => {
    const startDate = ctx.arg("--start");
    const weeksText = ctx.arg("--weeks");
    if (!startDate) {
      console.error("Missing required --start <YYYY-MM-DD>");
      process.exit(2);
    }
    const weeks = weeksText === undefined ? undefined : Number(weeksText);
    if (weeksText !== undefined && (!Number.isInteger(weeks) || weeks! < 1 || weeks! > 13)) {
      console.error("--weeks must be an integer from 1 to 13");
      process.exit(2);
    }
    // This command is deliberately read-only: unlike older CLI reads it does
    // not run migrations before opening the ledger.
    const root = ctx.companyRoot();
    const db = openLedgerReadOnly(companyPaths(root).db);
    try {
      const workspace = resolveConfiguredWorkspaceRoot();
      const entry = workspace
        ? listWorkspaceCompanies(workspace).find((item) => item.slug === ctx.arg("--company") || companyRootForSlug(workspace, item.slug) === root)
        : undefined;
      const result = workspace && entry
        ? (() => { const control = existsSync(workspaceControlPaths(workspace).db) ? openWorkspaceControlReadOnlyDb(workspace) : null; try { return buildWorkspaceThirteenWeekLiquidityForecast(control, db, entry.slug, startDate, weeks); } finally { control?.close(); } })()
        : buildThirteenWeekLiquidityForecast(db, { startDate, weeks });
      if (ctx.outputFormat === "json") ctx.emitResult(result as unknown as Record<string, unknown>);
      else if (!result.ok) { console.error(result.errors.join("\n")); process.exitCode = 1; }
      else {
        console.log(`13 ugers likviditetsprognose fra ${result.startDate}`);
        console.table(result.periods.map((period) => ({
          uge: period.weekStart,
          baseUltimo: formatKronerDa(period.closingCash),
          scenarioUltimo: formatKronerDa(period.scenarioClosingCash),
          udateretBudget: formatKronerDa(period.undatedBudgetAssumptions),
        })));
      }
    } finally { db.close(); }
  }

payloadTypes.source:
export type WorkspaceCompanyEntry = {
  /** Filesystem-safe identifier; the subdirectory name under the workspace. */
  slug: string;
  /** Human-readable display name. */
  name: string;
  /** ISO-8601 timestamp of when the entry was first registered. */
  createdAt: string;
  /** Soft-deletion flag; archived companies stay on disk. */
  archived: boolean;
};

export type WorkspaceManifest = {
  version: typeof MANIFEST_VERSION;
  companies: WorkspaceCompanyEntry[];
};

export type ThirteenWeekLiquidityInput = {
  startDate: string;
  weeks?: number;
  /** Read-only reviewed items from the same legal company only. */
  supplements?: readonly ReviewedLiquiditySupplement[];
  /** Required before workspace supplements can affect this company. */
  companySlug?: string;
};

export type ReviewedLiquiditySupplement = {
  kind:
    | "legally_due_obligation"
    | "approved_budget_assumption"
    | "approved_scenario_assumption"
    | "approved_intercompany_disposition";
  /** Workspace-unique legal-company identity. Never a ledger-local numeric id. */
  companySlug: string;
  dueDate: string;
  /** Positive absolute amount in the stated currency. */
  amount: number;
  currency: string;
  direction: "inflow" | "outflow";
  /** Stable canonical record id, not a free-text description. */
  reference: string;
  /** Immutable review/audit reference proving that this assumption is approved. */
  approvalReference: string;
};

export type WeeklyLiquidityPeriod = {
  weekStart:string;
  openingCash:number;
  receivables:number;
  payables:number;
  commitments:number;
  /** Approved budget assumptions, never booked facts. */
  budgets:number;
  /** Account-level monthly budgets with no cash date. Informational only. */
  undatedBudgetAssumptions:number;
  /** Approved scenario assumptions, never booked facts. */
  scenarios:number;
  /** VAT, tax and other legally due canonical obligations. */
  obligations:number;
  /** Explicit, reviewed company-scoped intercompany dispositions. */
  intercompany:number;
  excluded:Array<{source:string;amount:number;currency:string;reason?:string}>;
  /** Forecast from observed/canonical cash sources, excluding reviewed assumptions. */
  closingCash:number;
  /** `closingCash` plus dated reviewed scenario/budget/intercompany assumptions. */
  scenarioClosingCash:number;
  sources:Array<{source:string;amount:number;reference:string;assumption?:boolean;settlementStatus?:"unknown"}>;
};

