export function registerPayable(db: Database, input: RegisterPayableInput, inCurrentTransaction = false): RegisterPayableResult {
  const errors: string[] = [];
  if (!Number.isInteger(input.documentId) || input.documentId <= 0) errors.push("documentId must be a positive integer");
  if (!looksLikeIsoDate(input.billDate)) errors.push("billDate must be YYYY-MM-DD");
  if (!looksLikeIsoDate(input.dueDate)) errors.push("dueDate must be YYYY-MM-DD");
  if (typeof input.expenseAccountNo !== "string" || input.expenseAccountNo.trim().length === 0) errors.push("expenseAccountNo is required");
  if (input.vatTreatment && !["standard", "exempt", "non_deductible"].includes(input.vatTreatment)) {
    errors.push("vatTreatment must be one of standard, exempt, non_deductible when present");
  }
  if (input.vendorId !== undefined && (!Number.isInteger(input.vendorId) || input.vendorId <= 0)) {
    errors.push("vendorId must be a positive integer when present");
  }
  if (errors.length === 0 && input.dueDate < input.billDate) errors.push("dueDate must not be before billDate");
  if (errors.length > 0) return { ok: false, appliedRules: [RULE_ID], errors };

  const expenseAccountNo = input.expenseAccountNo.trim();
  const account = db.query(
    `SELECT account_no, type, active FROM accounts WHERE account_no = ?`,
  ).get(expenseAccountNo) as { account_no: string; type: string; active: number } | null;
  if (!account) return { ok: false, appliedRules: [RULE_ID], errors: [`expense account ${expenseAccountNo} does not exist`] };
  if (account.type !== "expense") return { ok: false, appliedRules: [RULE_ID], errors: [`account ${expenseAccountNo} is not an expense account`] };
  if (!account.active) return { ok: false, appliedRules: [RULE_ID], errors: [`account ${expenseAccountNo} is inactive`] };

  const document = db.query(
    `SELECT id, document_type, invoice_no, invoice_date, amount_inc_vat, vat_amount, currency, sender_name, payload_json,
            sender_vat_cvr, recipient_vat_cvr, supplier_country_code, supplier_identifier_kind, supplier_identity_status
     FROM documents WHERE id = ?`,
  ).get(input.documentId) as {
    id: number;
    document_type: string;
    invoice_no: string | null;
    invoice_date: string | null;
    amount_inc_vat: number | null;
    vat_amount: number | null;
    currency: string;
    sender_name: string | null;
    payload_json: string | null;
    sender_vat_cvr: string | null;
    recipient_vat_cvr: string | null;
    supplier_country_code: string | null;
    supplier_identifier_kind: string | null;
    supplier_identity_status: string | null;
  } | null;
  if (!document) return { ok: false, appliedRules: [RULE_ID], errors: [`document ${input.documentId} does not exist`] };
  // The evidence-bearing document date is the accounting and VAT date. A
  // caller may repeat it for an explicit review, but may never move a bill to
  // another period by supplying a different date.
  if (document.document_type === "purchase_sale" && (!document.invoice_date || !looksLikeIsoDate(document.invoice_date))) {
    return { ok: false, appliedRules: [RULE_ID], errors: [`document ${input.documentId} has no valid immutable invoice_date`] };
  }
  if (document.invoice_date && input.billDate !== document.invoice_date) {
    return { ok: false, appliedRules: [RULE_ID], errors: [`billDate ${input.billDate} must match document invoice_date ${document.invoice_date}`] };
  }
  if (document.document_type !== "purchase_sale" && document.document_type !== "cash_register_receipt") {
    return { ok: false, appliedRules: [RULE_ID], errors: [`document ${input.documentId} is not a purchase document`] };
  }
  if ((document.currency ?? "DKK").trim().toUpperCase() !== "DKK") {
    return { ok: false, appliedRules: [RULE_ID], errors: [`document ${input.documentId} is not in DKK — foreign-currency payables are out of scope for this slice`] };
  }

  const grossAmount = roundDkk(Number(document.amount_inc_vat ?? 0));
  const vatAmount = roundDkk(Number(document.vat_amount ?? 0));
  const parsedPurchaseVatLines = parsePurchaseVatLinesPayload(document.payload_json, {
    amountIncVat: document.amount_inc_vat,
    vatAmount: document.vat_amount,
  });
  if (parsedPurchaseVatLines.status === "invalid") {
    return { ok: false, appliedRules: [RULE_ID], errors: parsedPurchaseVatLines.errors.map((error) => `document ${input.documentId} has invalid persisted purchaseVatLines: ${error}`) };
  }
  const purchaseVatLines = parsedPurchaseVatLines.lines;
  if (!(grossAmount > 0)) return { ok: false, appliedRules: [RULE_ID], errors: [`document ${input.documentId} must have amount_inc_vat > 0`] };
  if (vatAmount < 0 || vatAmount > grossAmount) return { ok: false, appliedRules: [RULE_ID], errors: [`document ${input.documentId} has invalid vat_amount ${vatAmount}`] };

  const existing = db.query(`SELECT id FROM payables WHERE document_id = ? LIMIT 1`).get(input.documentId) as { id: number } | null;
  if (existing) return { ok: false, appliedRules: [RULE_ID], errors: [`document ${input.documentId} is already registered as payable ${existing.id}`] };

  // A NOT VAT-registered company cannot deduct input VAT (§ 37), so a charged
  // VAT amount defaults to non_deductible (absorbed into the cost) rather than
  // standard; a registered company keeps the historical standard default.
  const companyIsRegistered = getCompanySettings(db).vatPeriodType !== null;
  const vatTreatment =
    input.vatTreatment ?? (vatAmount > 0 ? (companyIsRegistered ? "standard" : "non_deductible") : "exempt");
  if (vatTreatment === "standard" && !companyIsRegistered) {
    return {
      ok: false,
      appliedRules: [RULE_ID],
      errors: [
        "selskabet er ikke momsregistreret — brug vatTreatment 'non_deductible', så den fakturerede moms absorberes i udgiften (momsloven § 37)",
      ],
    };
  }
  if (vatTreatment === "standard") {
    const supplierErrors = deductiblePurchaseSupplierErrors(document);
    if (supplierErrors.length > 0) return { ok: false, appliedRules: [RULE_ID], errors: supplierErrors };
    const contextErrors = standardPurchaseCompanyContextErrors(db, input.documentId, document);
    if (contextErrors.length > 0) return { ok: false, appliedRules: [RULE_ID], errors: contextErrors };
  }
  if (vatTreatment === "exempt" && vatAmount !== 0) {
    return { ok: false, appliedRules: [RULE_ID], errors: ["exempt payable registration requires document vat_amount = 0"] };
  }
  if (vatTreatment === "standard" && !purchaseVatLines) {
    if (!(vatAmount > 0)) return { ok: false, appliedRules: [RULE_ID], errors: ["standard payable registration requires document vat_amount > 0"] };
    // The document vat_amount becomes deductible input VAT — it must be
    // consistent with the 25 % rate rather than trusted blindly (a garbled or
    // OCR-extracted amount would otherwise be booked verbatim). 1 øre slack.
    const vatErrors = uniformDanishPurchaseVatErrors(input.documentId, grossAmount, vatAmount);
    if (vatErrors.length > 0) return { ok: false, appliedRules: [RULE_ID], errors: vatErrors };
  }

  const netAmount = subtractDkk(grossAmount, vatAmount);
  const creditor = resolveAccountRole(db, "creditors");
  if (!creditor.ok) return { ok: false, appliedRules: [RULE_ID], errors: [creditor.error] };
  let inputVatAccountNo: string | null = null;
  if (vatTreatment === "standard") {
    const inputVat = input.vatAccountNo?.trim() ? { ok: true as const, accountNo: input.vatAccountNo.trim() } : resolveAccountRole(db, "input_vat");
    if (!inputVat.ok) return { ok: false, appliedRules: [RULE_ID], errors: [inputVat.error] };
    inputVatAccountNo = inputVat.accountNo;
  }
  const supplierName = document.sender_name?.trim() || null;
  const text = supplierName
    ? `Kreditorpost: bilag fra ${supplierName} (bilag ${input.documentId})`
    : `Kreditorpost (bilag ${input.documentId})`;

  const lines = purchaseVatLines && vatTreatment === "standard"
    ? [
        ...purchaseVatLines.map((line) => ({ accountNo: expenseAccountNo, debitAmount: line.netAmount, vatCode: line.classification === "dk_purchase_25" ? "DK_PURCHASE_25" : "DK_PURCHASE_EXEMPT", text: document.invoice_no ?? (line.classification === "dk_purchase_25" ? "Udgift, momspligtigt grundbeløb" : "Udgift, momsfrit grundbeløb") })),
        { accountNo: inputVatAccountNo!, debitAmount: vatAmount, text: "Købsmoms" },
        { accountNo: creditor.accountNo, creditAmount: grossAmount, text: supplierName ? `Leverandørgæld ${supplierName}` : "Leverandørgæld" },
      ]
    : vatTreatment === "standard"
    ? [
        { accountNo: expenseAccountNo, debitAmount: netAmount, vatCode: "DK_PURCHASE_25", text: document.invoice_no ?? "Udgift, grundbeløb" },
        { accountNo: inputVatAccountNo!, debitAmount: vatAmount, text: "Købsmoms" },
        { accountNo: creditor.accountNo, creditAmount: grossAmount, text: supplierName ? `Leverandørgæld ${supplierName}` : "Leverandørgæld" },
      ]
    : [
        {
          accountNo: expenseAccountNo,
          debitAmount: grossAmount,
          text:
            document.invoice_no ??
            (vatTreatment === "non_deductible" ? "Udgift inkl. moms (ikke-fradragsberettiget)" : "Udgift"),
        },
        { accountNo: creditor.accountNo, creditAmount: grossAmount, text: supplierName ? `Leverandørgæld ${supplierName}` : "Leverandørgæld" },
      ];

  try {
    const apply = () => {
      const journal = (inCurrentTransaction ? postJournalEntryInCurrentTransaction : postJournalEntry)(db, {
        transactionDate: input.billDate,
        text,
        documentId: input.documentId,
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
        lines,
      });
      if (!journal.ok || journal.entryId == null) {
        throw new Error(JSON.stringify({ appliedRules: journal.appliedRules, errors: journal.errors }));
      }

      const inserted = db.query(
        `INSERT INTO payables
           (document_id, vendor_id, supplier_name, bill_no, bill_date, due_date,
            gross_amount, net_amount, vat_amount, currency, journal_entry_id, note)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'DKK', ?, ?)
         RETURNING id`,
      ).get(
        input.documentId,
        input.vendorId ?? null,
        supplierName,
        document.invoice_no ?? null,
        input.billDate,
        input.dueDate,
        grossAmount,
        netAmount,
        vatAmount,
        journal.entryId,
        input.note ?? null,
      ) as { id: number };

      insertAuditLog(db, {
        eventType: "payable_register",
        entityType: "payable",
        entityId: inserted.id,
        message: `Registered payable ${grossAmount} DKK${supplierName ? ` to ${supplierName}` : ""} (due ${input.dueDate})`,
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
      });

      return {
        ok: true,
        payableId: inserted.id,
        documentId: input.documentId,
        supplierName,
        billNo: document.invoice_no ?? null,
        grossAmount,
        netAmount,
        vatAmount,
        dueDate: input.dueDate,
        entryId: journal.entryId,
        entryNo: journal.entryNo,
        entryHash: journal.entryHash,
        appliedRules: [RULE_ID, ...journal.appliedRules],
        errors: [],
      } satisfies RegisterPayableResult;
    };
    return inCurrentTransaction ? apply() : db.transaction(apply).immediate();
  } catch (error) {
    // The #583 receipt executor owns the outer transaction. It must see a
    // post-write failure as an exception so it can roll back journal,
    // payable/payment, receipt and audit together.
    if (inCurrentTransaction) throw error;
    const parsed = parseTransactionError(error);
    return {
      ok: false,
      appliedRules: [...new Set([RULE_ID, ...(parsed?.appliedRules ?? [])])],
      errors: parsed?.errors ?? [String(error)],
    };
  }
}

export function isValidIsoDate(value: unknown): value is string {
  if (typeof value !== "string") return false;
  const trimmed = value.trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return false;
  const date = new Date(`${trimmed}T00:00:00Z`);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === trimmed;
}

export function roundDkk(value: number) {
  return Number.isFinite(value) ? fromScaledInt(scaledInt(value, 2), 2) : NaN;
}

export function parsePurchaseVatLinesPayload(
  payloadJson: string | null | undefined,
  canonicalTotals?: CanonicalPurchaseVatTotals,
): PurchaseVatLinesPayloadResult {
  if (!payloadJson) return { status: "absent", lines: null, errors: [] };
  try {
    const parsed = JSON.parse(payloadJson) as unknown;
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return { status: "invalid", lines: null, errors: ["document payload_json must contain a metadata object"] };
    }
    if (!Object.prototype.hasOwnProperty.call(parsed, "purchaseVatLines")) {
      return { status: "absent", lines: null, errors: [] };
    }
    const metadata = parsed as DocumentMetadata;
    const errors: string[] = [];
    if (canonicalTotals) {
      if (!hasNonNegativeNumber(canonicalTotals.amountIncVat)) {
        errors.push("persisted purchaseVatLines requires canonical documents.amount_inc_vat");
      }
      if (!hasNonNegativeNumber(canonicalTotals.vatAmount)) {
        errors.push("persisted purchaseVatLines requires canonical documents.vat_amount");
      }
      if (!hasNonNegativeNumber(metadata.amountIncVat)) {
        errors.push("persisted purchaseVatLines payload requires amountIncVat");
      } else if (hasNonNegativeNumber(canonicalTotals.amountIncVat) && compareDkk(metadata.amountIncVat, canonicalTotals.amountIncVat) !== 0) {
        errors.push(`payload amountIncVat ${roundDkk(metadata.amountIncVat)} must equal canonical documents.amount_inc_vat ${roundDkk(canonicalTotals.amountIncVat)}`);
      }
      if (!hasNonNegativeNumber(metadata.vatAmount)) {
        errors.push("persisted purchaseVatLines payload requires vatAmount");
      } else if (hasNonNegativeNumber(canonicalTotals.vatAmount) && compareDkk(metadata.vatAmount, canonicalTotals.vatAmount) !== 0) {
        errors.push(`payload vatAmount ${roundDkk(metadata.vatAmount)} must equal canonical documents.vat_amount ${roundDkk(canonicalTotals.vatAmount)}`);
      }
    }
    errors.push(...validatePurchaseVatLines(canonicalTotals
      ? { ...metadata, amountIncVat: canonicalTotals.amountIncVat ?? undefined, vatAmount: canonicalTotals.vatAmount ?? undefined }
      : metadata));
    if (errors.length > 0) return { status: "invalid", lines: null, errors };
    return { status: "valid", lines: metadata.purchaseVatLines!, errors: [] };
  } catch {
    return { status: "invalid", lines: null, errors: ["document payload_json is not valid JSON"] };
  }
}

export function getCompanySettings(db: Database): CompanySettings {
  // #289: older ledgers (and the base schema.sql) may lack `vat_period_type`.
  // Read it only when present; absent → fall back to the quarterly default so
  // a pre-#289 company is unaffected.
  const vatColumn = hasVatPeriodColumn(db) ? "vat_period_type" : "NULL AS vat_period_type";
  const row = db.query(
    `SELECT id, name, country, currency, cvr, fiscal_year_start_month, fiscal_year_label_strategy,
            address, postal_code, city, company_form, industry_code, industry_text,
            cvr_status, audit_waived, cvr_synced_at, payment_terms_days, ${vatColumn}
       FROM companies
      ORDER BY id ASC
      LIMIT 1`
  ).get() as {
    id: number;
    name: string;
    country: string;
    currency: string;
    cvr: string | null;
    fiscal_year_start_month: number;
    fiscal_year_label_strategy: FiscalYearLabelStrategy;
    address: string | null;
    postal_code: string | null;
    city: string | null;
    company_form: string | null;
    industry_code: string | null;
    industry_text: string | null;
    cvr_status: string | null;
    audit_waived: number | null;
    cvr_synced_at: string | null;
    payment_terms_days: number | null;
    vat_period_type: string | null;
  } | null;

  if (!row) return DEFAULT_COMPANY_SETTINGS;
  return {
    id: row.id,
    name: row.name,
    country: row.country,
    currency: row.currency,
    cvr: normalizeCvr(row.cvr),
    fiscalYearStartMonth: normalizeFiscalYearStartMonth(row.fiscal_year_start_month) ?? 1,
    fiscalYearLabelStrategy: normalizeFiscalYearLabelStrategy(row.fiscal_year_label_strategy) ?? "end-year",
    address: row.address,
    postalCode: row.postal_code,
    city: row.city,
    companyForm: row.company_form,
    industryCode: row.industry_code,
    industryText: row.industry_text,
    cvrStatus: row.cvr_status,
    auditWaived: row.audit_waived === null ? null : row.audit_waived === 1,
    cvrSyncedAt: row.cvr_synced_at,
    paymentTermsDays:
      normalizePaymentTermsDays(row.payment_terms_days) ?? DEFAULT_PAYMENT_TERMS_DAYS,
    // `null` in the column = "not VAT-registered" — preserved verbatim. A
    // stored value that fails normalisation (corrupt cell) falls back to the
    // historical default so legacy ledgers stay readable.
    vatPeriodType:
      row.vat_period_type === null
        ? null
        : normalizeVatPeriodType(row.vat_period_type) ?? DEFAULT_VAT_PERIOD_TYPE,
  };
}

const DEFAULT_COMPANY_SETTINGS: CompanySettings = {
  id: 1,
  name: "Rentemester company",
  country: "DK",
  currency: "DKK",
  cvr: null,
  fiscalYearStartMonth: 1,
  fiscalYearLabelStrategy: "end-year",
  address: null,
  postalCode: null,
  city: null,
  companyForm: null,
  industryCode: null,
  industryText: null,
  cvrStatus: null,
  auditWaived: null,
  cvrSyncedAt: null,
  paymentTermsDays: DEFAULT_PAYMENT_TERMS_DAYS,
  // Keep the module's eager default independent of the close/VAT graph.
  // `periods.ts` imports the close-readiness graph, which eventually reads
  // company settings.  The value is the same canonical default exported from
  // that module; using the literal here prevents an ESM initialization cycle
  // from observing its export before initialization.
  vatPeriodType: "quarter",
};

export function deductiblePurchaseSupplierErrors(document: {
  sender_vat_cvr: string | null;
  supplier_country_code: string | null;
  supplier_identifier_kind: string | null;
  supplier_identity_status: string | null;
}): string[] {
  return deductibleDanishPurchaseSupplierErrors({
    supplierVatOrCvr: document.sender_vat_cvr,
    supplierCountryCode: document.supplier_country_code,
    supplierIdentifierKind: document.supplier_identifier_kind,
    supplierIdentityStatus: document.supplier_identity_status,
  });
}

export function standardPurchaseCompanyContextErrors(db: Database, documentId: number, document: {
  document_type: string;
  recipient_vat_cvr: string | null;
  payload_json: string | null;
}): string[] {
  try {
    const payload = document.payload_json ? JSON.parse(document.payload_json) as Record<string, unknown> : {};
    const invoiceStatesCompany = typeof document.recipient_vat_cvr === "string" && document.recipient_vat_cvr.trim().length > 0;
    const contextIsValid = payload.danishSimplifiedPurchaseInvoice === true && validSimplifiedPurchaseCompanyContext(db, documentId);
    if (document.document_type === "purchase_sale" && !invoiceStatesCompany && !contextIsValid) {
      return ["standard purchase VAT requires invoice-stated recipient identity or a valid hash-bound simplified-invoice company context"];
    }
    return [];
  } catch {
    return ["document payload_json is not valid JSON"];
  }
}

export function uniformDanishPurchaseVatErrors(documentId: number, grossAmount: number, vatAmount: number): string[] {
  const documentNetAmount = subtractDkk(grossAmount, vatAmount);
  const expectedVatAmount = percentOfDkk(documentNetAmount, 25);
  if (compareDkk(absDkk(subtractDkk(vatAmount, expectedVatAmount)), 0.01) > 0) {
    return [`document ${documentId} vat_amount ${vatAmount} is inconsistent with the 25% rate (expected ~${expectedVatAmount} for net ${documentNetAmount})`];
  }
  return [];
}

export function subtractDkk(left: number, ...rights: number[]) {
  let total = toOre(left);
  for (const value of rights) total -= toOre(value);
  return fromOre(total);
}

export function resolveAccountRole(db: Database, role: AccountRole): AccountRoleResolution {
  const row = db.query(`SELECT m.account_no, m.version, m.confirmed_by, m.confirmation_source, a.type, a.normal_balance, a.active
    FROM account_role_mappings m JOIN accounts a ON a.account_no = m.account_no
    WHERE m.role = ? AND m.status = 'confirmed'`).get(role) as { account_no: string; version: number; confirmed_by: string; confirmation_source: AccountRoleConfirmationSource; type: string; normal_balance: string; active: number } | null;
  if (!row) return { ok: false, role, error: `account role '${role}' has no active confirmed mapping` };
  if (row.active !== 1) return { ok: false, role, error: `account role '${role}' maps to inactive account ${row.account_no}` };
  const expected = expectations[role];
  if (row.type !== expected.type || row.normal_balance !== expected.normalBalance) {
    return { ok: false, role, error: `account role '${role}' maps to semantically incompatible account ${row.account_no}` };
  }
  return { ok: true, role, accountNo: row.account_no, version: row.version, confirmedBy: row.confirmed_by, confirmationSource: row.confirmation_source };
}

const expectations: Record<AccountRole, { type: string; normalBalance: string }> = {
  bank: { type: "asset", normalBalance: "debit" },
  debtors: { type: "asset", normalBalance: "debit" },
  creditors: { type: "liability", normalBalance: "credit" },
  output_vat: { type: "vat", normalBalance: "credit" },
  input_vat: { type: "vat", normalBalance: "debit" },
  reverse_charge_vat: { type: "vat", normalBalance: "credit" },
  vat_settlement: { type: "liability", normalBalance: "credit" },
  operational_default: { type: "expense", normalBalance: "debit" },
};

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

const apply = () => {
      const journal = (inCurrentTransaction ? postJournalEntryInCurrentTransaction : postJournalEntry)(db, {
        transactionDate: input.billDate,
        text,
        documentId: input.documentId,
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
        lines,
      });
      if (!journal.ok || journal.entryId == null) {
        throw new Error(JSON.stringify({ appliedRules: journal.appliedRules, errors: journal.errors }));
      }

      const inserted = db.query(
        `INSERT INTO payables
           (document_id, vendor_id, supplier_name, bill_no, bill_date, due_date,
            gross_amount, net_amount, vat_amount, currency, journal_entry_id, note)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'DKK', ?, ?)
         RETURNING id`,
      ).get(
        input.documentId,
        input.vendorId ?? null,
        supplierName,
        document.invoice_no ?? null,
        input.billDate,
        input.dueDate,
        grossAmount,
        netAmount,
        vatAmount,
        journal.entryId,
        input.note ?? null,
      ) as { id: number };

      insertAuditLog(db, {
        eventType: "payable_register",
        entityType: "payable",
        entityId: inserted.id,
        message: `Registered payable ${grossAmount} DKK${supplierName ? ` to ${supplierName}` : ""} (due ${input.dueDate})`,
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
      });

      return {
        ok: true,
        payableId: inserted.id,
        documentId: input.documentId,
        supplierName,
        billNo: document.invoice_no ?? null,
        grossAmount,
        netAmount,
        vatAmount,
        dueDate: input.dueDate,
        entryId: journal.entryId,
        entryNo: journal.entryNo,
        entryHash: journal.entryHash,
        appliedRules: [RULE_ID, ...journal.appliedRules],
        errors: [],
      } satisfies RegisterPayableResult;
    };

function parseTransactionError(error: unknown): { appliedRules?: string[]; errors?: string[] } | null {
  if (typeof error === "object" && error && "message" in error) {
    try {
      return JSON.parse(String((error as { message: unknown }).message));
    } catch {
      return null;
    }
  }
  return null;
}

