export function resolveDigisenseReceiver(
  db: Database,
  companyRoot: string,
  options: { companyKey?: string } = {},
): ResolveDigisenseReceiver {
  const secret = loadDigisenseSecretConfig(companyRoot);
  if (!secret) {
    return { ok: false, errors: [digisenseNotConfiguredError("modtages")] };
  }

  const companyKey = resolveBoundDigisenseCompanyKey(db, options.companyKey);
  if (!companyKey.ok) return { ok: false, errors: companyKey.errors };

  const client = createDigisenseClient({
    apiLicenseKey: secret.apiLicenseKey,
    environment: secret.environment,
  });
  return {
    ok: true,
    client,
    downloader: defaultDocumentDownloader(),
    companyKey: companyKey.value,
  };
}

export function loadDigisenseSecretConfig(
  companyRoot: string,
): DigisenseSecretConfig | null {
  const path = digisenseConfigPath(companyRoot);
  if (!existsSync(path)) return null;
  const raw = readFileSync(path, "utf8");
  return JSON.parse(raw) as DigisenseSecretConfig;
}

function digisenseNotConfiguredError(action: string): string {
  return (
    `Digisense er ikke konfigureret: gem en API license-key først med ` +
    `\`rentemester efaktura konfigurer --company <path> --api-license-key <secret> ` +
    `--environment test|production\` (eller MCP-tool'et efaktura_konfigurer). Det skriver ` +
    `config/digisense.json (0600) før der kan ${action} e-fakturaer.`
  );
}

export function resolveBoundDigisenseCompanyKey(
  db: Database,
  explicit?: string,
): { ok: true; value: string } | { ok: false; errors: string[] } {
  const identity = resolveDigisenseIdentity(db);
  if (!identity.ok) return identity;
  const own = getDigisenseCompanyByParticipantId(db, identity.value.cvr);
  const key = explicit?.trim();
  if (key) {
    if (!own || own.companyKey !== key) return { ok: false, errors: ["The supplied DigiSense companyKey is not bound to this ledger's profile CVR."] };
    return { ok: true, value: key };
  }
  if (own) return { ok: true, value: own.companyKey };
  const count = listDigisenseCompanies(db).length;
  return { ok: false, errors: [count ? "DigiSense company state belongs to a different legal company; registration is required for this profile CVR." : "No DigiSense company is registered for this ledger's profile CVR." ] };
}

export function createDigisenseClient(
  config: DigisenseClientConfig,
  deps: DigisenseClientDeps = {},
): DigisenseClient {
  if (!config.apiLicenseKey?.trim()) {
    throw new Error("digisense client: apiLicenseKey is required");
  }
  const baseUrl = digisenseBaseUrl(config.environment);
  const httpFetch = deps.fetch ?? defaultHttpFetch();

  // Fælles headers. Authorization bærer license-key'en (én nøgle pr. licens).
  function authHeaders(contentType?: string): Record<string, string> {
    const headers: Record<string, string> = {
      Authorization: config.apiLicenseKey,
      Accept: "application/json",
    };
    if (contentType) headers["Content-Type"] = contentType;
    return headers;
  }

  // Udfør et kald og parse JSON-svaret. Ikke-2xx mappes til en tydelig
  // DigisenseError; transport-/parse-fejl bliver status 0 så kaldere altid får
  // et Result i stedet for en throw der lækker stack-traces til envelopen.
  async function requestJson<T>(request: HttpRequest): Promise<DigisenseResult<T>> {
    let response: HttpResponse;
    try {
      response = await httpFetch(request);
    } catch (error) {
      return {
        ok: false,
        error: {
          status: 0,
          message: `digisense transport error: ${error instanceof Error ? error.message : String(error)}`,
        },
      };
    }

    const rawBody = await response.text();

    if (response.status < 200 || response.status >= 300) {
      return {
        ok: false,
        error: {
          status: response.status,
          message: `digisense responded ${response.status}`,
          body: rawBody,
        },
      };
    }

    if (rawBody.trim().length === 0) {
      // Tomt 2xx-svar => tomt objekt (fx endpoints der kun signalerer succes).
      return { ok: true, status: response.status, data: {} as T };
    }

    try {
      return { ok: true, status: response.status, data: JSON.parse(rawBody) as T };
    } catch (error) {
      return {
        ok: false,
        error: {
          status: response.status,
          message: `digisense returned unparseable JSON: ${error instanceof Error ? error.message : String(error)}`,
          body: rawBody,
        },
      };
    }
  }

  return {
    validateAuth() {
      return requestJson<ValidateAuthResponse>({
        method: "GET",
        url: `${baseUrl}/validate-auth`,
        headers: authHeaders(),
      });
    },

    registerCompany(body) {
      return requestJson<RegisterCompanyResponse>({
        method: "POST",
        url: `${baseUrl}/register-company`,
        headers: authHeaders("application/json"),
        body: JSON.stringify(body),
      });
    },

    registerParticipant(network, body) {
      return requestJson<RegisterParticipantResponse>({
        method: "POST",
        // v1 is deprecated. v2 remains under the configured REST base URL.
        url: `${baseUrl}/v2/register-participant/${network}`,
        headers: authHeaders("application/json"),
        body: JSON.stringify(body),
      });
    },

    validateDocument(xml) {
      // Schematron-validering: XML-body som string, application/xml.
      return requestJson<ValidateDocumentResponse>({
        method: "POST",
        url: `${baseUrl}/validate-document`,
        headers: authHeaders("application/xml"),
        body: xml,
      });
    },

    lookupParticipant(query) {
      return requestJson<LookupParticipantResponse>({
        method: "GET",
        url: `${baseUrl}/lookup-participant${buildQuery({
          networkType: query.networkType,
          documentType: query.documentType,
          participantScheme: query.participantScheme,
          participantValue: query.participantValue,
        })}`,
        headers: authHeaders(),
      });
    },

    deliverDocument(xml, query) {
      // XML-faktura (<=10MB). companyKey + valgfrit ksefEnvironment i query.
      return requestJson<DeliverDocumentResponse>({
        method: "POST",
        url: `${baseUrl}/deliver-document${buildQuery({
          companyKey: query.companyKey,
          ksefEnvironment: query.ksefEnvironment,
        })}`,
        headers: authHeaders("application/xml"),
        body: xml,
      });
    },

    documentStatus(documentId, companyKey) {
      return requestJson<DocumentStatusResponse>({
        method: "GET",
        url: `${baseUrl}/document-status/${encodeURIComponent(documentId)}${buildQuery({ companyKey })}`,
        headers: authHeaders(),
      });
    },

    listReceivedDocuments(query) {
      return requestJson<ListReceivedDocumentsResponse>({
        method: "GET",
        url: `${baseUrl}/list-received-documents${buildQuery({
          limit: query.limit,
          offset: query.offset,
          maxTimestamp: query.maxTimestamp,
          companyKey: query.companyKey,
          networkType: query.networkType,
          participantType: query.participantType,
          participantId: query.participantId,
        })}`,
        headers: authHeaders(),
      });
    },
  };
}

export function defaultDocumentDownloader(): DigisenseDocumentDownloader {
  return async (url) => {
    try {
      const response = await fetch(url);
      const xml = await response.text();
      if (response.status < 200 || response.status >= 300) {
        return { ok: false, error: `download responded ${response.status}` };
      }
      return { ok: true, xml };
    } catch (error) {
      return { ok: false, error: `download transport error: ${error instanceof Error ? error.message : String(error)}` };
    }
  };
}

export async function pollDigisenseReceived(
  db: Database,
  companyRoot: string,
  client: DigisenseClient,
  downloader: DigisenseDocumentDownloader,
  options: PollDigisenseReceivedOptions,
): Promise<PollDigisenseReceivedResult> {
  const result: PollDigisenseReceivedResult = {
    ok: true,
    pagesFetched: 0,
    documentsListed: 0,
    documentsIngested: 0,
    documentsSkipped: 0,
    documentsQuarantined: 0,
    documents: [],
    errors: [],
  };

  const companyKey = options.companyKey?.trim();
  if (!companyKey) {
    return { ...result, ok: false, errors: ["companyKey is required to poll received documents"] };
  }

  const limit = Math.min(Math.max(1, options.limit ?? DEFAULT_LIMIT), MAX_LIMIT);
  const maxPages = options.maxPages ?? DEFAULT_MAX_PAGES;

  // Pagination: vi følger nextPageUrl ved at avancere offset med antallet af
  // sete dokumenter. (API'et returnerer nextPageUrl=null på sidste side; offset
  // er den robuste, server-uafhængige markør.)
  let offset = 0;
  for (let pageNo = 0; pageNo < maxPages; pageNo += 1) {
    const query: ListReceivedDocumentsQuery = {
      limit,
      offset,
      companyKey,
      maxTimestamp: options.maxTimestamp,
    };
    const listed = await client.listReceivedDocuments(query);
    if (!listed.ok) {
      result.ok = false;
      result.errors.push(`list-received-documents failed: ${listed.error.message}`);
      return result;
    }
    result.pagesFetched += 1;

    const documents = listed.data.documents ?? [];
    result.documentsListed += documents.length;

    for (const doc of documents) {
      const outcome = await ingestReceivedDocument(db, companyRoot, downloader, companyKey, doc, options);
      result.documents.push(outcome);
      // En pr.-dokument-fejl må ALDRIG kaste hele pollen: 49 rene fakturaer +
      // 1 dårlig skal ikke give exit 1 / en error-envelope der kasserer de 49.
      // `ok` afspejler kun BATCH-niveau (list-received-documents). Pr.-dokument-
      // udfald rapporteres via tællerne + documents[] + errors[].
      if (outcome.status === "ingested") {
        result.documentsIngested += 1;
      } else if (outcome.status === "skipped-duplicate") {
        result.documentsSkipped += 1;
      } else if (outcome.status === "quarantined") {
        // TERMINAL fejl (validering/dublet): en quarantine-række er skrevet, så
        // dokumentet ikke down­loades + fejler igen i det uendelige. Tæller som
        // håndteret-skip, men fejl-grunden bevares til diagnostik.
        result.documentsQuarantined += 1;
        result.documentsSkipped += 1;
        if (outcome.errors) result.errors.push(...outcome.errors);
      } else {
        // TRANSIENT fejl (download-transport): INGEN række skrevet — næste poll
        // prøver igen. Noteres i errors, men fælder ikke batch-`ok`.
        if (outcome.errors) result.errors.push(...outcome.errors);
      }
    }

    // Stop når der ikke er flere sider. Vi stoler primært på nextPageUrl; en
    // kortere-end-limit side er en sekundær terminering hvis nextPageUrl mangler.
    const hasNext = listed.data.nextPageUrl != null && documents.length > 0;
    if (!hasNext || documents.length < limit) break;
    offset += documents.length;
  }

  return result;
}

listReceivedDocuments(
    query: ListReceivedDocumentsQuery,
  ): Promise<DigisenseResult<ListReceivedDocumentsResponse>>;

