export async function pollWorkspaceDigisenseInbound(
  workspaceRoot: string,
  options: WorkspaceDigisensePollOptions,
): Promise<WorkspaceDigisensePollResult> {
  const { targets, skipped } = activeInitializedTargets(workspaceRoot);
  preflightWorkspaceTargets(targets, options.actor.createdBy ?? "");
  const companies: WorkspaceDigisensePollResult["companies"] = [...skipped];
  for (const target of targets) {
    const db = openDb(companyPaths(target.root).db);
    try {
      migrate(db);
      if (options.pollCompany) {
        const result = await options.pollCompany(db, target.root, options.actor);
        companies.push(result.ok
          ? { slug: target.slug, status: "polled", documentsIngested: result.documentsIngested }
          : { slug: target.slug, status: "failed", reason: "poll failed" });
        continue;
      }
      const resolved = resolveDigisenseReceiver(db, target.root);
      // This is a workspace surface: do not echo company bindings, config
      // paths, or provider errors from an individual ledger.
      if (!resolved.ok) { companies.push({ slug: target.slug, status: "skipped", reason: "not configured" }); continue; }
      const result = await pollDigisenseReceived(db, target.root, resolved.client, resolved.downloader, {
        companyKey: resolved.companyKey,
        actor: options.actor,
      });
      companies.push(result.ok ? { slug: target.slug, status: "polled", documentsIngested: result.documentsIngested } : { slug: target.slug, status: "failed", reason: "poll failed" });
    } catch { companies.push({ slug: target.slug, status: "failed", reason: "poll failed" }); }
    finally { db.close(); }
  }
  return { ok: true, companies };
}

function activeInitializedTargets(workspaceRoot: string): {
  targets: WorkspaceTarget[];
  skipped: WorkspaceDigisensePollResult["companies"];
} {
  const targets: WorkspaceTarget[] = [];
  const skipped: WorkspaceDigisensePollResult["companies"] = [];
  for (const entry of listWorkspaceCompanies(workspaceRoot)) {
    if (entry.archived) {
      skipped.push({ slug: entry.slug, status: "skipped", reason: "archived" });
      continue;
    }
    const root = companyRootForSlug(workspaceRoot, entry.slug);
    if (!existsSync(companyPaths(root).db)) {
      skipped.push({ slug: entry.slug, status: "skipped", reason: "not initialized" });
      continue;
    }
    targets.push({ slug: entry.slug, root });
  }
  return { targets, skipped };
}

function preflightWorkspaceTargets(targets: WorkspaceTarget[], actor: string): void {
  // This entire pass completes before the first migration, network call, or
  // ledger write, so a later company cannot leave an earlier one mutated.
  if (!isCanonicalActorId(actor)) {
    throw new Error(`workspace DigiSense polling requires a canonical actor id (user:..., agent:..., or system:...)`);
  }
  for (const target of targets) {
    const decision = checkActorAllowlist(target.root, actor);
    if (!decision.allowed) throw new Error(`${target.slug}: ${decision.reason}`);
  }
  for (const target of targets) {
    // `openDb` changes persistent journal mode to WAL. A preflight must be
    // byte/state read-only until every target has passed, so use SQLite's
    // readonly handle directly and defer openDb/migrate to the execution pass.
    const db = new Database(companyPaths(target.root).db, { readonly: true });
    try {
      let lock: ReturnType<typeof evaluateBackupLock>;
      try {
        lock = evaluateBackupLock(db, target.root);
      } catch {
        throw new Error(`${target.slug}: backup status could not be evaluated`);
      }
      if (lock.errors.length > 0) throw new Error(`${target.slug}: ${lock.reason}`);
      if (lock.locked) throw new Error(`${target.slug}: ${lock.reason}`);
    } finally {
      db.close();
    }
  }
}

const pollCompany?: (
    db: ReturnType<typeof openDb>,
    companyRoot: string,
    actor: Required<Pick<ResolveActorInput, "createdBy" | "createdByProgram">>,
  ) => Promise<{ ok: boolean; documentsIngested: number }>;;

export function resolveDigisenseReceiver(
  db: Database,
  companyRoot: string,
  options: { companyKey?: string } = {},
): ResolveDigisenseReceiver {
  const secret = loadDigisenseSecretConfig(companyRoot);
  if (!secret) {
    return { ok: false, errors: [digisenseNotConfiguredError("modtages")] };
  }

  const companyKey = resolveBoundDigisenseCompanyKey(db, options.companyKey);
  if (!companyKey.ok) return { ok: false, errors: companyKey.errors };

  const client = createDigisenseClient({
    apiLicenseKey: secret.apiLicenseKey,
    environment: secret.environment,
  });
  return {
    ok: true,
    client,
    downloader: defaultDocumentDownloader(),
    companyKey: companyKey.value,
  };
}

export async function pollDigisenseReceived(
  db: Database,
  companyRoot: string,
  client: DigisenseClient,
  downloader: DigisenseDocumentDownloader,
  options: PollDigisenseReceivedOptions,
): Promise<PollDigisenseReceivedResult> {
  const result: PollDigisenseReceivedResult = {
    ok: true,
    pagesFetched: 0,
    documentsListed: 0,
    documentsIngested: 0,
    documentsSkipped: 0,
    documentsQuarantined: 0,
    documents: [],
    errors: [],
  };

  const companyKey = options.companyKey?.trim();
  if (!companyKey) {
    return { ...result, ok: false, errors: ["companyKey is required to poll received documents"] };
  }

  const limit = Math.min(Math.max(1, options.limit ?? DEFAULT_LIMIT), MAX_LIMIT);
  const maxPages = options.maxPages ?? DEFAULT_MAX_PAGES;

  // Pagination: vi følger nextPageUrl ved at avancere offset med antallet af
  // sete dokumenter. (API'et returnerer nextPageUrl=null på sidste side; offset
  // er den robuste, server-uafhængige markør.)
  let offset = 0;
  for (let pageNo = 0; pageNo < maxPages; pageNo += 1) {
    const query: ListReceivedDocumentsQuery = {
      limit,
      offset,
      companyKey,
      maxTimestamp: options.maxTimestamp,
    };
    const listed = await client.listReceivedDocuments(query);
    if (!listed.ok) {
      result.ok = false;
      result.errors.push(`list-received-documents failed: ${listed.error.message}`);
      return result;
    }
    result.pagesFetched += 1;

    const documents = listed.data.documents ?? [];
    result.documentsListed += documents.length;

    for (const doc of documents) {
      const outcome = await ingestReceivedDocument(db, companyRoot, downloader, companyKey, doc, options);
      result.documents.push(outcome);
      // En pr.-dokument-fejl må ALDRIG kaste hele pollen: 49 rene fakturaer +
      // 1 dårlig skal ikke give exit 1 / en error-envelope der kasserer de 49.
      // `ok` afspejler kun BATCH-niveau (list-received-documents). Pr.-dokument-
      // udfald rapporteres via tællerne + documents[] + errors[].
      if (outcome.status === "ingested") {
        result.documentsIngested += 1;
      } else if (outcome.status === "skipped-duplicate") {
        result.documentsSkipped += 1;
      } else if (outcome.status === "quarantined") {
        // TERMINAL fejl (validering/dublet): en quarantine-række er skrevet, så
        // dokumentet ikke down­loades + fejler igen i det uendelige. Tæller som
        // håndteret-skip, men fejl-grunden bevares til diagnostik.
        result.documentsQuarantined += 1;
        result.documentsSkipped += 1;
        if (outcome.errors) result.errors.push(...outcome.errors);
      } else {
        // TRANSIENT fejl (download-transport): INGEN række skrevet — næste poll
        // prøver igen. Noteres i errors, men fælder ikke batch-`ok`.
        if (outcome.errors) result.errors.push(...outcome.errors);
      }
    }

    // Stop når der ikke er flere sider. Vi stoler primært på nextPageUrl; en
    // kortere-end-limit side er en sekundær terminering hvis nextPageUrl mangler.
    const hasNext = listed.data.nextPageUrl != null && documents.length > 0;
    if (!hasNext || documents.length < limit) break;
    offset += documents.length;
  }

  return result;
}

export function resolveWorkspaceRoot(raw: string): string {
  if (raw.split(/[\\/]+/).includes("..")) {
    throw new Error("workspace root must not contain parent-directory ('..') segments");
  }
  const resolved = resolve(raw);
  if (!isAbsolute(resolved) || resolved.split(sep).includes("..")) {
    throw new Error("workspace root resolved to an unsafe path");
  }
  return resolved;
}

