  db: Database,
  companyRoot: string,
  client: DigisenseClient,
  downloader: DigisenseDocumentDownloader,
  options: PollDigisenseReceivedOptions,
): Promise<PollDigisenseReceivedResult> {
  const result: PollDigisenseReceivedResult = {
    ok: true,
    pagesFetched: 0,
    documentsListed: 0,
    documentsIngested: 0,
    documentsSkipped: 0,
    documentsQuarantined: 0,
    documents: [],
    errors: [],
  };

  const companyKey = options.companyKey?.trim();
  if (!companyKey) {
    return { ...result, ok: false, errors: ["companyKey is required to poll received documents"] };
  }

  const limit = Math.min(Math.max(1, options.limit ?? DEFAULT_LIMIT), MAX_LIMIT);
  const maxPages = options.maxPages ?? DEFAULT_MAX_PAGES;

  // Pagination: vi følger nextPageUrl ved at avancere offset med antallet af
  // sete dokumenter. (API'et returnerer nextPageUrl=null på sidste side; offset
  // er den robuste, server-uafhængige markør.)
  let offset = 0;
  for (let pageNo = 0; pageNo < maxPages; pageNo += 1) {
    const query: ListReceivedDocumentsQuery = {
      limit,
      offset,
      companyKey,
      maxTimestamp: options.maxTimestamp,
    };
    const listed = await client.listReceivedDocuments(query);
    if (!listed.ok) {
      result.ok = false;
      result.errors.push(`list-received-documents failed: ${listed.error.message}`);
      return result;
    }
    result.pagesFetched += 1;

    const documents = listed.data.documents ?? [];
    result.documentsListed += documents.length;

    for (const doc of documents) {
      const outcome = await ingestReceivedDocument(db, companyRoot, downloader, companyKey, doc, options);
      result.documents.push(outcome);
      // En pr.-dokument-fejl må ALDRIG kaste hele pollen: 49 rene fakturaer +
      // 1 dårlig skal ikke give exit 1 / en error-envelope der kasserer de 49.
      // `ok` afspejler kun BATCH-niveau (list-received-documents). Pr.-dokument-
      // udfald rapporteres via tællerne + documents[] + errors[].
      if (outcome.status === "ingested") {
        result.documentsIngested += 1;
      } else if (outcome.status === "skipped-duplicate") {
        result.documentsSkipped += 1;
      } else if (outcome.status === "quarantined") {
        // TERMINAL fejl (validering/dublet): en quarantine-række er skrevet, så
        // dokumentet ikke down­loades + fejler igen i det uendelige. Tæller som
        // håndteret-skip, men fejl-grunden bevares til diagnostik.
        result.documentsQuarantined += 1;
        result.documentsSkipped += 1;
        if (outcome.errors) result.errors.push(...outcome.errors);
      } else {
        // TRANSIENT fejl (download-transport): INGEN række skrevet — næste poll
        // prøver igen. Noteres i errors, men fælder ikke batch-`ok`.
        if (outcome.errors) result.errors.push(...outcome.errors);
      }
    }

    // Stop når der ikke er flere sider. Vi stoler primært på nextPageUrl; en
    // kortere-end-limit side er en sekundær terminering hvis nextPageUrl mangler.
    const hasNext = listed.data.nextPageUrl != null && documents.length > 0;
    if (!hasNext || documents.length < limit) break;
    offset += documents.length;
  }

  return result;
}

export function resolveWorkspaceRoot(raw: string): string {
  if (raw.split(/[\\/]+/).includes("..")) {
    throw new Error("workspace root must not contain parent-directory ('..') segments");
  }
  const resolved = resolve(raw);
  if (!isAbsolute(resolved) || resolved.split(sep).includes("..")) {
    throw new Error("workspace root resolved to an unsafe path");
  }
  return resolved;
}

typeDeclarations.source:
export type WorkspaceDigisensePollOptions = {
  actor: Required<Pick<ResolveActorInput, "createdBy" | "createdByProgram">>;
  /** Test seam after all policy/backup preflights have succeeded. */
  pollCompany?: (
    db: ReturnType<typeof openDb>,
    companyRoot: string,
    actor: Required<Pick<ResolveActorInput, "createdBy" | "createdByProgram">>,
  ) => Promise<{ ok: boolean; documentsIngested: number }>;
};

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type WorkspaceDigisensePollResult = {
  ok: true;
  companies: Array<{ slug: string; status: "polled" | "skipped" | "failed"; reason?: string; documentsIngested?: number }>;
};

export type ResolveDigisenseReceiver =
  | { ok: true; client: DigisenseClient; downloader: DigisenseDocumentDownloader; companyKey: string }
  | { ok: false; errors: string[] };

export type DigisenseClient = {
  validateAuth(): Promise<DigisenseResult<ValidateAuthResponse>>;
  registerCompany(
    body: RegisterCompanyRequest,
  ): Promise<DigisenseResult<RegisterCompanyResponse>>;
  registerParticipant(
    network: DigisenseNetwork,
    body: RegisterParticipantRequest,
  ): Promise<DigisenseResult<RegisterParticipantResponse>>;
  /** Schematron-validér FØR send. XML-body som string. */
  validateDocument(
    xml: string,
  ): Promise<DigisenseResult<ValidateDocumentResponse>>;
  lookupParticipant(
    query: LookupParticipantQuery,
  ): Promise<DigisenseResult<LookupParticipantResponse>>;
  /** Lever XML-faktura. XML-body som string. 202 => poll status. */
  deliverDocument(
    xml: string,
    query: DeliverDocumentQuery,
  ): Promise<DigisenseResult<DeliverDocumentResponse>>;
  documentStatus(
    documentId: string,
    companyKey: string,
  ): Promise<DigisenseResult<DocumentStatusResponse>>;
  listReceivedDocuments(
    query: ListReceivedDocumentsQuery,
  ): Promise<DigisenseResult<ListReceivedDocumentsResponse>>;
};

export type DigisenseResult<T> =
  | { ok: true; status: number; data: T }
  | { ok: false; error: DigisenseError };

export type DigisenseError = {
  /** HTTP-status fra access point (eller 0 ved transport-/parse-fejl). */
  status: number;
  /** Kort, sikker besked egnet til at lægge i en envelope. */
  message: string;
  /** Rå svar-body, hvis tilgængelig (til diagnostik/audit). */
  body?: string;
};

export type ValidateAuthResponse = {
  apiLicenseKey: string;
  label: string;
  /** UUID — HMAC-secret til webhook-signaturer. */
  signatureSecret: string;
  testGlnNumber: string;
  /** Begrænsning på companyKey, eller null hvis ubegrænset. */
  companyKeyConstraint: string | null;
};

export type RegisterCompanyRequest = {
  companyType: DigisenseCompanyType;
  companyName: string;
};

export type DigisenseCompanyType =
  | { type: "DK:CVR"; id: string }
  | { type: "NIP"; id: string };

export type RegisterCompanyResponse = {
  /** base64url — scoper næsten alle efterfølgende kald. */
  companyKey: string;
  message: string;
};

export type RegisterParticipantRequest = {
  direction: ParticipantDirection;
  participantType: ParticipantType;
  participantId: string;
  companyKey: string;
  /** null => ingen webhook; man poller selv (bekræftet designvalg). */
  webhookUrl: string | null;
  documentProfiles: string;
};

export type RegisterParticipantResponse = {
  registeredOnNetwork: boolean;
  webhookRegistered: boolean;
};

export type ValidateDocumentResponse = {
  statusCode: number;
  success: boolean;
  errors: ValidateDocumentError[];
};

export type ValidateDocumentError = {
  context: string;
  pattern: string;
  description: string;
  xpath: string;
  type: "error" | "warning";
};

export type LookupParticipantQuery = {
  networkType: LookupNetworkType;
  documentType?: string;
  /** fx "DK:CVR", "0184", "0088", "GLN". */
  participantScheme: string;
  participantValue: string;
};

export type LookupParticipantResponse = {
  participantAbleToReceive: boolean;
  matchedServiceEndpointUrls: string[];
  matchedDocumentTypes: string[];
};

export type DeliverDocumentQuery = {
  companyKey: string;
  ksefEnvironment?: KsefEnvironment;
};

export type DeliverDocumentResponse = {
  /** 200 delivered | 202 queued | 4xx/5xx. */
  statusCode: number;
  documentStatus: DigisenseDocumentStatus;
  documentId: string;
  message: string;
  publicUrl: string;
};

export type DocumentStatusResponse = {
  statusCode: number;
  documentStatus: DigisenseDocumentStatus;
  documentId: string;
  message: string;
  publicUrl: string;
};

export type ListReceivedDocumentsQuery = {
  /** <=100. */
  limit: number;
  offset?: number;
  maxTimestamp?: string;
  companyKey?: string;
  networkType?: string;
  participantType?: ParticipantType;
  participantId?: string;
};

export type ListReceivedDocumentsResponse = {
  documents: ReceivedDocument[];
  participants: unknown[];
  licenseKey: string;
  searchParams: Record<string, unknown>;
  nextPageUrl: string | null;
};

export type ReceivedDocument = {
  documentId: string;
  documentType: string;
  documentTypeUrn: string;
  profileId: string;
  customizationId: string;
  receivedAt: string;
  senderParticipantType: string;
  senderParticipantId: string;
  senderName: string;
  destinationParticipantType: string;
  destinationParticipantId: string;
  destinationName: string;
  sourceNetwork: string;
  /** STABIL dedup-nøgle. */
  internalId: string;
  downloadUrlExpiresAt: string;
  /** Signeret URL, udløber. */
  downloadUrl: string;
};

export type DownloadXmlResult =
  | { ok: true; xml: string }
  | { ok: false; error: string };

export type PollDigisenseReceivedOptions = {
  /** companyKey der scoper list-received-documents (fra digisense_companies). */
  companyKey: string;
  /** Side-størrelse (<=100). Default 100. */
  limit?: number;
  /** Valgfrit øvre tidsstempel (maxTimestamp) videresendt til API'et. */
  maxTimestamp?: string;
  /**
   * Caller-leverede booking-felter der OVERSTYRER de UBL-/listning-afledte
   * (samme konvention som mail-intake's --metadata). `source` sættes altid af
   * pipelinen og kan ikke overstyres.
   */
  metadata?: Omit<DocumentMetadata, "source">;
  /** Videresendt til ingestDocument (fx --force ved logisk dublet-scan). */
  ingestOptions?: IngestDocumentOptions;
  /** Hård øvre grænse på antal sider, så et fejlende nextPageUrl ikke looper. */
  maxPages?: number;
  /** Explicit actor propagated to every document and DigiSense audit event. */
  actor?: ResolveActorInput;
};

export type DocumentMetadata = {
  source: string;
  documentType?: DocumentType;
  issueDate?: string;
  invoiceNo?: string;
  deliveryDescription?: string;
  amountIncVat?: number;
  currency?: string;
  sender?: { name?: string; address?: string; vatOrCvr?: string; countryCode?: string; identifierKind?: SupplierIdentifierKind };
  recipient?: { name?: string; address?: string; vatOrCvr?: string };
  vatAmount?: number;
  /** Purchase tax bases, retained verbatim with the voucher.  Omit for legacy uniform VAT documents. */
  purchaseVatLines?: PurchaseVatLine[];
  /** Human-confirmed invoice evidence required before a non-EU service can be
   * posted with automatic reverse-charge input-VAT deduction. */
  reverseChargeWordingConfirmed?: boolean;
  /** Explicit source fact: the issuer supplied a Danish simplified purchase invoice. */
  danishSimplifiedPurchaseInvoice?: boolean;
  paymentDetails?: string;
  exemptionCode?: DocumentExemptionCode;
  /** Imported bank row that is the immutable primary evidence for an internal voucher. */
  sourceBankTransactionId?: number;
  /** Human accounting explanation for why the internal voucher is booked. */
  accountingRationale?: string;
};

export type DocumentType =
  | "purchase_sale"
  | "cash_register_receipt"
  | "issued_invoice_pdf"
  | "internal_voucher";

export type IngestDocumentOptions = {
  forceDuplicateLogicalIdentity?: boolean;
  createdBy?: string;
  createdByProgram?: string;
  /** Internal bulk-import use only: the enclosing import writes one audit event. */
  suppressAudit?: boolean;
  /** Scanner policy is off unless a caller explicitly requires it. */
  scannerPolicy?: "off" | "required";
  /** Upper bound for a single scanner decision. Required scanners fail closed on expiry. */
  scannerTimeoutMs?: number;
  /** A vendor-neutral async seam. It receives immutable snapshot bytes only. */
  scanner?: DocumentScanner;
};

export type DocumentScanner = {
  scan(input: { bytes: Buffer; sha256: string; mimeType: string; filename: string; signal: AbortSignal }): Promise<
    | { ok: true; scannerId: string; scannerVersion?: string; evidenceRef?: string }
    | { ok: false; error?: string }
  >;
};

export type PollDigisenseReceivedResult = {
  ok: boolean;
  /** Antal sider hentet fra list-received-documents. */
  pagesFetched: number;
  /** Antal dokumenter set på tværs af alle sider. */
  documentsListed: number;
  /** Antal NYE dokumenter ingested denne poll. */
  documentsIngested: number;
  /** Antal sprunget over (allerede ingested / dedup / quarantine). */
  documentsSkipped: number;
  /** Antal TERMINALE fejl denne poll (uingesterbare; nu quarantined). */
  documentsQuarantined: number;
  documents: ReceivedDocumentOutcome[];
  errors: string[];
};

export type ReceivedDocumentOutcome = {
  internalId: string;
  status: "ingested" | "skipped-duplicate" | "quarantined" | "error";
  documentNo?: string;
  errors?: string[];
};

