async (ctx) => {
    const confirmValue = (ctx.arg("--confirm") ?? "").trim().toLowerCase();
    if (confirmValue !== "yes") {
      ctx.emitResult({ ok: false, errors: ["--confirm yes required to record Digisense delivery status evidence"] });
      process.exit(1);
    }
    const documentId = Number(ctx.arg("--document-id"));
    if (!Number.isSafeInteger(documentId) || documentId <= 0) {
      ctx.emitResult({ ok: false, errors: ["Missing required --document-id <positive integer>"] });
      process.exit(2);
    }
    const root = ctx.companyRoot();
    const db = openCommandDb(ctx);
    migrate(db);
    try {
      const resolved = resolveDigisenseStatusChecker(db, root, { companyKey: ctx.trimToNull(ctx.arg("--digisense-company-key") ?? null) ?? undefined });
      if (!resolved.ok) { ctx.emitResult({ ok: false, errors: resolved.errors }); process.exit(1); }
      const result = await resumePublicEInvoicePeppolSubmission(db, { invoiceDocumentId: documentId, accessPoint: digisenseAccessPointIdentity(resolved.companyKey) }, async (queuedDocumentId) => {
        const status = await resolved.client.documentStatus(queuedDocumentId, resolved.companyKey);
        return status.ok ? { ok: true, status: status.data.documentStatus, message: status.data.message, publicUrl: status.data.publicUrl } : { ok: false, error: `digisense document-status failed: ${status.error.message}` };
      });
      ctx.emitResult(result as unknown as Record<string, unknown>);
      if (!result.ok || result.status === "failed" || result.status === "uncertain") process.exit(1);
    } finally { db.close(); }
  }

payloadTypes.source:
export type ResolveDigisenseStatusChecker =
  | { ok: true; client: DigisenseClient; companyKey: string }
  | { ok: false; errors: string[] };

export type DigisenseClient = {
  validateAuth(): Promise<DigisenseResult<ValidateAuthResponse>>;
  registerCompany(
    body: RegisterCompanyRequest,
  ): Promise<DigisenseResult<RegisterCompanyResponse>>;
  registerParticipant(
    network: DigisenseNetwork,
    body: RegisterParticipantRequest,
  ): Promise<DigisenseResult<RegisterParticipantResponse>>;
  /** Schematron-validér FØR send. XML-body som string. */
  validateDocument(
    xml: string,
  ): Promise<DigisenseResult<ValidateDocumentResponse>>;
  lookupParticipant(
    query: LookupParticipantQuery,
  ): Promise<DigisenseResult<LookupParticipantResponse>>;
  /** Lever XML-faktura. XML-body som string. 202 => poll status. */
  deliverDocument(
    xml: string,
    query: DeliverDocumentQuery,
  ): Promise<DigisenseResult<DeliverDocumentResponse>>;
  documentStatus(
    documentId: string,
    companyKey: string,
  ): Promise<DigisenseResult<DocumentStatusResponse>>;
  listReceivedDocuments(
    query: ListReceivedDocumentsQuery,
  ): Promise<DigisenseResult<ListReceivedDocumentsResponse>>;
};

export type DigisenseResult<T> =
  | { ok: true; status: number; data: T }
  | { ok: false; error: DigisenseError };

export type DigisenseError = {
  /** HTTP-status fra access point (eller 0 ved transport-/parse-fejl). */
  status: number;
  /** Kort, sikker besked egnet til at lægge i en envelope. */
  message: string;
  /** Rå svar-body, hvis tilgængelig (til diagnostik/audit). */
  body?: string;
};

export type ValidateAuthResponse = {
  apiLicenseKey: string;
  label: string;
  /** UUID — HMAC-secret til webhook-signaturer. */
  signatureSecret: string;
  testGlnNumber: string;
  /** Begrænsning på companyKey, eller null hvis ubegrænset. */
  companyKeyConstraint: string | null;
};

export type RegisterCompanyRequest = {
  companyType: DigisenseCompanyType;
  companyName: string;
};

export type DigisenseCompanyType =
  | { type: "DK:CVR"; id: string }
  | { type: "NIP"; id: string };

export type RegisterCompanyResponse = {
  /** base64url — scoper næsten alle efterfølgende kald. */
  companyKey: string;
  message: string;
};

export type RegisterParticipantRequest = {
  direction: ParticipantDirection;
  participantType: ParticipantType;
  participantId: string;
  companyKey: string;
  /** null => ingen webhook; man poller selv (bekræftet designvalg). */
  webhookUrl: string | null;
  documentProfiles: string;
};

export type RegisterParticipantResponse = {
  registeredOnNetwork: boolean;
  webhookRegistered: boolean;
};

export type ValidateDocumentResponse = {
  statusCode: number;
  success: boolean;
  errors: ValidateDocumentError[];
};

export type ValidateDocumentError = {
  context: string;
  pattern: string;
  description: string;
  xpath: string;
  type: "error" | "warning";
};

export type LookupParticipantQuery = {
  networkType: LookupNetworkType;
  documentType?: string;
  /** fx "DK:CVR", "0184", "0088", "GLN". */
  participantScheme: string;
  participantValue: string;
};

export type LookupParticipantResponse = {
  participantAbleToReceive: boolean;
  matchedServiceEndpointUrls: string[];
  matchedDocumentTypes: string[];
};

export type DeliverDocumentQuery = {
  companyKey: string;
  ksefEnvironment?: KsefEnvironment;
};

export type DeliverDocumentResponse = {
  /** 200 delivered | 202 queued | 4xx/5xx. */
  statusCode: number;
  documentStatus: DigisenseDocumentStatus;
  documentId: string;
  message: string;
  publicUrl: string;
};

export type DocumentStatusResponse = {
  statusCode: number;
  documentStatus: DigisenseDocumentStatus;
  documentId: string;
  message: string;
  publicUrl: string;
};

export type ListReceivedDocumentsQuery = {
  /** <=100. */
  limit: number;
  offset?: number;
  maxTimestamp?: string;
  companyKey?: string;
  networkType?: string;
  participantType?: ParticipantType;
  participantId?: string;
};

export type ListReceivedDocumentsResponse = {
  documents: ReceivedDocument[];
  participants: unknown[];
  licenseKey: string;
  searchParams: Record<string, unknown>;
  nextPageUrl: string | null;
};

export type ReceivedDocument = {
  documentId: string;
  documentType: string;
  documentTypeUrn: string;
  profileId: string;
  customizationId: string;
  receivedAt: string;
  senderParticipantType: string;
  senderParticipantId: string;
  senderName: string;
  destinationParticipantType: string;
  destinationParticipantId: string;
  destinationName: string;
  sourceNetwork: string;
  /** STABIL dedup-nøgle. */
  internalId: string;
  downloadUrlExpiresAt: string;
  /** Signeret URL, udløber. */
  downloadUrl: string;
};

export type DigisenseSecretConfig = {
  /** API license-key — én nøgle for hele licensen. Aldrig i ledgeren. */
  apiLicenseKey: string;
  /** prod/test base-URL switch. Default 'test' når udeladt ved skrivning. */
  environment: DigisenseEnvironment;
};

export type DigisenseClientConfig = {
  /** API license-key — sendes i Authorization-header. Aldrig i ledgeren. */
  apiLicenseKey: string;
  /** prod/test base-URL switch. */
  environment: DigisenseEnvironment;
};

export type DigisenseClientDeps = {
  /** Injicérbar transport. Default wrapper om global fetch når udeladt. */
  fetch?: HttpFetch;
};

export type HttpRequest = {
  method: "GET" | "POST";
  url: string;
  headers: Record<string, string>;
  body?: string;
};

export type HttpResponse = {
  status: number;
  /** Rå svar-body (JSON eller XML som tekst). */
  text(): Promise<string>;
};

export type TransmitPublicEInvoicePeppolInput = {
  invoiceDocumentId: number;
  accessPoint: PeppolAccessPointConfig;
};

export type PeppolAccessPointConfig = {
  accessPointId: string;
  endpointUrl: string;
  senderEndpointId: string;
};

export type PeppolSubmissionStatusChecker = (documentId: string) => Promise<{
  ok: boolean;
  status?: string;
  observedAt?: string;
  message?: string;
  publicUrl?: string;
  error?: string;
}> | {
  ok: boolean;
  status?: string;
  observedAt?: string;
  message?: string;
  publicUrl?: string;
  error?: string;
};

export type SubmitPublicEInvoicePeppolResult = {
  ok: boolean;
  invoiceNumber?: string;
  /** Stable reference for this submission attempt. */
  submissionReference?: string;
  /** Derived idempotency key — duplicates collapse onto the same record. */
  idempotencyKey?: string;
  /** sha256 of the underlying OIOUBL handoff artifact. */
  oioublSha256?: string;
  /** sha256 of the generated submission envelope. */
  envelopeSha256?: string;
  /** The deterministic submission envelope XML. */
  envelope?: string;
  /** queued/prepared, terminally failed after provider acceptance, or delivered. */
  status?: "prepared" | "failed" | "uncertain" | "acknowledged";
  /** True when an existing submission record was reused (idempotent re-run). */
  duplicate?: boolean;
  outPath?: string;
  /** Transport transmission id, set once the invoice has actually been transmitted. */
  transmissionId?: string;
  appliedRules: string[];
  errors: string[];
};

export type ExportPublicEInvoiceInput = {
  invoiceDocumentId: number;
  outPath?: string;
};

export type ExportPublicEInvoiceResult = {
  ok: boolean;
  invoiceNumber?: string;
  outPath?: string;
  sha256?: string;
  xml?: string;
  appliedRules: string[];
  errors: string[];
};

export type InvoicePayload = {
  invoiceType: InvoiceType;
  vatTreatment?: VatTreatment;
  issueDate?: string;
  invoiceNumber?: string;
  seller?: { name?: string; address?: string; vatOrCvr?: string };
  buyer?: InvoiceBuyer;
  /**
   * Peppol cbc:InvoicedQuantity/@unitCode (UN/ECE Rec 20). Defaults to H87
   * ("piece") in the e-invoice export; set per payload to override.
   */
  unitCode?: string;
  lines?: Array<{ description?: string; quantity?: number; unitPriceExVat?: number; lineTotalExVat?: number; unitCode?: string; taxClassification?: VatLineClassification; vatRate?: number; reverseChargeBasis?: string }>;
  totals?: {
    netAmount?: number;
    vatRate?: number;
    vatAmount?: number;
    grossAmount?: number;
    fxRateToDkk?: number;
    netAmountDkk?: number;
    vatAmountDkk?: number;
    grossAmountDkk?: number;
    vatComputationBasis?: "VAT_20_OF_GROSS" | string;
  };
  reverseChargeBasis?: ReverseChargeBasis;
  reverseChargeNote?: string;
  currency?: string;
  dueDate?: string;
  deliveryDate?: string;
  deliveryPeriodStart?: string;
  deliveryPeriodEnd?: string;
};

export type InvoiceBuyer = {
  name?: string;
  address?: string;
  vatOrCvr?: string;
  eanNumber?: string;
  publicRecipient?: boolean;
  /**
   * Peppol BIS 3.0 cbc:BuyerReference (BT-10). Mandatory for a public-recipient
   * e-invoice (PEPPOL-EN16931-R003) — the public authority's own reference
   * (often an "EAN-/ordrereference"). Without it the access point rejects the
   * invoice.
   */
  buyerReference?: string;
  /** Optional Peppol cac:OrderReference/cbc:ID (BT-13), the buyer's order id. */
  orderReference?: string;
};

export type ReverseChargeBasis =
  | "DK_MOMSLOVEN_§46_STK_1_NR_3"
  | "DK_MOMSLOVEN_§46_STK_1_NR_6"
  | "DK_MOMSLOVEN_§46_STK_1_NR_7"
  | "EU_MOMSDIREKTIV_ART_196"
  | "EU_MOMSDIREKTIV_ART_199";

type PeppolSubmissionRow = {
  id: number;
  invoice_document_id: number;
  invoice_no: string | null;
  idempotency_key: string;
  submission_reference: string;
  access_point_id: string;
  receiver_endpoint_id: string;
  oioubl_sha256: string;
  envelope_sha256: string;
  envelope_xml: string;
  status: "prepared" | "acknowledged";
  transmission_id: string | null;
  acknowledged_at: string | null;
};

type PeppolSubmissionEventRow = {
  event_type: "delivery_reserved" | "delivery_failed" | "queued" | "status_observed" | "delivered";
  document_id: string;
  observed_at: string;
  status: string | null;
};

export type AuditLogInput = {
  eventType: string;
  entityType: string;
  entityId?: string | number | null;
  message: string;
} & ResolveActorInput;

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

