): ReturnType<Database["run"]>;

export function runSql(
  db: Database,
  sql: string,
  ...bindings: SQLQueryBindings[] | [SQLQueryBindings[]]
): ReturnType<Database["run"]> {
  const normalized = bindings.length === 1 && Array.isArray(bindings[0])
    ? bindings[0]
    : bindings as SQLQueryBindings[];
  return db.run(sql, normalized);
}

export function insertAuditLog(db: Database, input: AuditLogInput) {
  const actor = resolveActor(input);
  runSql(db,
    "INSERT INTO audit_log (event_type, entity_type, entity_id, message, actor) VALUES (?, ?, ?, ?, ?)",
    input.eventType,
    input.entityType,
    input.entityId == null ? null : String(input.entityId),
    input.message,
    actor.auditActor,
  );
}

function recordSubmissionEvent(
  db: Database,
  submissionId: number,
  eventType: PeppolSubmissionEventRow["event_type"],
  args: { documentId?: string; status?: string; observedAt?: string; message?: string; publicUrl?: string | null } = {},
): void {
  runSql(db,
    `INSERT INTO peppol_submission_events
       (submission_id, event_type, document_id, status, observed_at, message, public_url)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    submissionId, eventType, args.documentId ?? null, args.status ?? null,
    args.observedAt ?? new Date().toISOString(), args.message ?? "", args.publicUrl ?? null,
  );
}

function isTerminalAcceptedFailure(status: string | null | undefined): boolean {
  return Boolean(status && TERMINAL_ACCEPTED_FAILURE_STATUSES.has(status));
}

const TERMINAL_ACCEPTED_FAILURE_STATUSES = new Set([
  "document-not-valid",
  "unable-to-deliver",
  "unknown-server-error",
]);

export function digisenseAccessPointIdentity(companyKey: string): PeppolAccessPointConfig {
  const key = companyKey.trim();
  return {
    accessPointId: "digisense",
    endpointUrl: "digisense:access-point",
    senderEndpointId: key,
  };
}

