export function resolveWorkspaceRoot(raw: string): string {
  if (raw.split(/[\\/]+/).includes("..")) {
    throw new Error("workspace root must not contain parent-directory ('..') segments");
  }
  const resolved = resolve(raw);
  if (!isAbsolute(resolved) || resolved.split(sep).includes("..")) {
    throw new Error("workspace root resolved to an unsafe path");
  }
  return resolved;
}

export function findWorkspaceCompany(
  workspaceRoot: string,
  slug: string,
): WorkspaceCompanyEntry | null {
  return listWorkspaceCompanies(workspaceRoot).find((c) => c.slug === slug) ?? null;
}

export function listWorkspaceCompanies(workspaceRoot: string): WorkspaceCompanyEntry[] {
  return loadWorkspaceManifest(workspaceRoot).companies;
}

export function resolveServerConfig(
  options: ResolveServerConfigOptions = {},
): ServerConfig {
  const env = options.env ?? process.env;

  const host =
    options.host?.trim() ||
    (env.RENTEMESTER_APP_HOST?.trim() ?? "") ||
    DEFAULT_APP_HOST;

  const port =
    options.port ?? parsePort(env.RENTEMESTER_APP_PORT, DEFAULT_APP_PORT);
  const deploymentProfile = readDeploymentProfile(env);

  let workspaceRoot = options.workspaceRoot?.trim() || null;
  if (!workspaceRoot) {
    // resolveConfiguredWorkspaceRoot reads RENTEMESTER_WORKSPACE from
    // process.env; honour an injected env map for testability.
    const fromEnv = env.RENTEMESTER_WORKSPACE;
    if (typeof fromEnv === "string" && fromEnv.trim().length > 0) {
      const prev = process.env.RENTEMESTER_WORKSPACE;
      process.env.RENTEMESTER_WORKSPACE = fromEnv;
      try {
        workspaceRoot = resolveConfiguredWorkspaceRoot();
      } finally {
        if (prev === undefined) delete process.env.RENTEMESTER_WORKSPACE;
        else process.env.RENTEMESTER_WORKSPACE = prev;
      }
    } else {
      workspaceRoot = resolveConfiguredWorkspaceRoot();
    }
  }
  if (!workspaceRoot) {
    throw new Error(
      "no workspace configured: set RENTEMESTER_WORKSPACE or pass --workspace <dir>",
    );
  }

  const authToken = env.RENTEMESTER_APP_TOKEN?.trim() || null;
  const authRequired =
    (env.RENTEMESTER_APP_AUTH?.trim().toLowerCase() ?? "") === "required";

  if (deploymentProfile === "local" && !isLoopbackBindAddress(host)) {
    throw new Error(
      "local deployment profile may only bind a loopback address; use RENTEMESTER_DEPLOYMENT_PROFILE=hosted",
    );
  }
  if (deploymentProfile === "local-container" && host.trim() !== "0.0.0.0") {
    throw new Error(
      "local-container deployment profile must bind 0.0.0.0 inside the container and be published on host loopback only",
    );
  }
  const hostedBetterAuth = deploymentProfile === "hosted" ? resolveHostedBetterAuth(env) : undefined;
  const hostedDocumentScanning = deploymentProfile === "hosted" ? resolveHostedDocumentScanning(env) : undefined;
  if (deploymentProfile !== "hosted" && [
    HOSTED_AUTH_ENV.secret, HOSTED_AUTH_ENV.secrets, HOSTED_AUTH_ENV.baseURL, HOSTED_AUTH_ENV.trustedOrigins,
    HOSTED_AUTH_ENV.emailProvider, HOSTED_AUTH_ENV.emailUrl,
    HOSTED_AUTH_ENV.emailBearerToken, HOSTED_AUTH_ENV.emailFrom,
    HOSTED_AUTH_ENV.rateLimitIpHeader, HOSTED_AUTH_ENV.rateLimitProxyContract,
    DOCUMENT_SCANNER_ENV.policy, DOCUMENT_SCANNER_ENV.provider, DOCUMENT_SCANNER_ENV.url,
    DOCUMENT_SCANNER_ENV.bearerToken, DOCUMENT_SCANNER_ENV.timeoutMs,
  ].some((name) => Boolean(env[name]?.trim()))) {
    throw new Error("local deployment profiles must not configure Better Auth; use RENTEMESTER_DEPLOYMENT_PROFILE=hosted");
  }

  return {
    deploymentProfile,
    host,
    port,
    workspaceRoot,
    // Hosted access is Better Auth-only regardless of the legacy bearer flag.
    authRequired: deploymentProfile === "hosted" ? true : authRequired,
    authToken,
    hostedBetterAuth,
    hostedDocumentScanning,
    documentScannerPolicy: hostedDocumentScanning?.policy ?? "off",
    staticRoot: resolveStaticRoot(env),
  };
}

const DOCUMENT_SCANNER_ENV = {
  policy: "RENTEMESTER_DOCUMENT_SCANNER_POLICY",
  provider: "RENTEMESTER_DOCUMENT_SCANNER_PROVIDER",
  url: "RENTEMESTER_DOCUMENT_SCANNER_URL",
  bearerToken: "RENTEMESTER_DOCUMENT_SCANNER_BEARER_TOKEN",
  timeoutMs: "RENTEMESTER_DOCUMENT_SCANNER_TIMEOUT_MS",
} as const;

function parsePort(raw: string | undefined, fallback: number): number {
  if (raw === undefined || raw.trim().length === 0) return fallback;
  const port = Number(raw);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error(
      `RENTEMESTER_APP_PORT must be an integer between 1 and 65535, got: ${raw}`,
    );
  }
  return port;
}

function readDeploymentProfile(env: Record<string, string | undefined>): DeploymentProfile {
  const raw = (env[HOSTED_AUTH_ENV.profile] ?? "local").trim().toLowerCase();
  if ((DEPLOYMENT_PROFILES as readonly string[]).includes(raw)) return raw as DeploymentProfile;
  throw new Error(`${HOSTED_AUTH_ENV.profile} must be 'local', 'local-container', or 'hosted'`);
}

export function resolveConfiguredWorkspaceRoot(): string | null {
  const raw = process.env.RENTEMESTER_WORKSPACE;
  if (typeof raw !== "string" || raw.trim().length === 0) return null;
  return resolveWorkspaceRoot(raw.trim());
}

export function isLoopbackBindAddress(host: string): boolean {
  const normalized = host.trim().toLowerCase();
  return normalized === "localhost" ||
    normalized === "127.0.0.1" ||
    normalized === "::1" ||
    normalized === "[::1]" ||
    normalized === "0:0:0:0:0:0:0:1" ||
    normalized === "[0:0:0:0:0:0:0:1]";
}

function resolveHostedBetterAuth(env: Record<string, string | undefined>): HostedBetterAuthConfig {
  const secretConfig = parseVersionedHostedSecrets(env);
  const baseURL = parseHostedOrigin(env[HOSTED_AUTH_ENV.baseURL]?.trim() ?? "", HOSTED_AUTH_ENV.baseURL);
  const trustedOrigins = (env[HOSTED_AUTH_ENV.trustedOrigins] ?? "")
    .split(",")
    .map((origin) => origin.trim())
    .filter(Boolean)
    .map((origin) => parseHostedOrigin(origin, HOSTED_AUTH_ENV.trustedOrigins));
  if (trustedOrigins.length === 0) {
    throw new Error(`${HOSTED_AUTH_ENV.trustedOrigins} requires at least one explicit HTTPS origin`);
  }
  if (!trustedOrigins.includes(baseURL)) {
    throw new Error(`${HOSTED_AUTH_ENV.trustedOrigins} must include ${HOSTED_AUTH_ENV.baseURL}`);
  }
  const provider = (env[HOSTED_AUTH_ENV.emailProvider] ?? "disabled").trim().toLowerCase();
  if (provider !== "http-json-v1") {
    throw new Error(`${HOSTED_AUTH_ENV.emailProvider} must be 'http-json-v1' for hosted deployments`);
  }
  const authEmail: HostedAuthEmailConfig = {
    provider,
    url: env[HOSTED_AUTH_ENV.emailUrl]?.trim() ?? "",
    bearerToken: env[HOSTED_AUTH_ENV.emailBearerToken]?.trim() ?? "",
    from: env[HOSTED_AUTH_ENV.emailFrom]?.trim() ?? "",
  };
  // Validate before the app binds. Configuration errors name only fields, not values.
  validateAuthEmailHttpJsonV1Config({ ...authEmail, idempotencySecret: secretConfig.secret });
  return {
    ...secretConfig,
    baseURL,
    trustedOrigins: [...new Set(trustedOrigins)],
    authEmail,
    rateLimitIpHeader: parseHostedRateLimitIpHeader(env),
  };
}

function resolveHostedDocumentScanning(env: Record<string, string | undefined>): HostedDocumentScanningConfig {
  const policy = (env[DOCUMENT_SCANNER_ENV.policy] ?? "off").trim().toLowerCase();
  if (policy !== "off" && policy !== "required") {
    throw new Error(`${DOCUMENT_SCANNER_ENV.policy} must be 'off' or 'required'`);
  }
  const provider = (env[DOCUMENT_SCANNER_ENV.provider] ?? "disabled").trim().toLowerCase();
  if (policy === "off") {
    if (provider !== "disabled" || [DOCUMENT_SCANNER_ENV.url, DOCUMENT_SCANNER_ENV.bearerToken, DOCUMENT_SCANNER_ENV.timeoutMs].some((name) => Boolean(env[name]?.trim()))) {
      throw new Error(`${DOCUMENT_SCANNER_ENV.policy}=off must not configure a document scanner provider`);
    }
    return { policy: "off" };
  }
  if (provider !== "http-json-v1") {
    throw new Error(`${DOCUMENT_SCANNER_ENV.provider} must be 'http-json-v1' when scanning is required`);
  }
  let url: URL;
  try {
    url = new URL(env[DOCUMENT_SCANNER_ENV.url]?.trim() ?? "");
  } catch {
    throw new Error(`${DOCUMENT_SCANNER_ENV.url} must be an absolute HTTPS URL`);
  }
  if (url.protocol !== "https:" || isLoopbackHostname(url.hostname) || !url.hostname) {
    throw new Error(`${DOCUMENT_SCANNER_ENV.url} must be a non-loopback HTTPS URL`);
  }
  const bearerToken = env[DOCUMENT_SCANNER_ENV.bearerToken]?.trim() ?? "";
  if (!bearerToken) throw new Error(`${DOCUMENT_SCANNER_ENV.bearerToken} is required when scanning is required`);
  return {
    policy: "required",
    provider: {
      provider: "http-json-v1",
      url: url.toString(),
      bearerToken,
      timeoutMs: parseScannerTimeout(env[DOCUMENT_SCANNER_ENV.timeoutMs]),
    },
  };
}

function resolveStaticRoot(env: Record<string, string | undefined>): string {
  const override = env.RENTEMESTER_APP_STATIC?.trim();
  if (override) return override;
  const here = dirname(fileURLToPath(import.meta.url));
  return join(here, "..", "..", "app", "dist");
}

export function createHttpJsonV1AuthEmailSender(
  config: AuthEmailHttpJsonV1Config,
  dependencies: AuthEmailHttpJsonV1Dependencies = {},
): AuthEmailSender {
  validateAuthEmailHttpJsonV1Config(config);
  const endpoint = parseGatewayUrl(config.url).toString();
  const doFetch = dependencies.fetch ?? ((request) => fetch(request));
  const sleep = dependencies.sleep ?? defaultSleep;
  const clock = dependencies.clock ?? Date.now;

  return {
    async send(message): Promise<void> {
      const deadline = clock() + TOTAL_DEADLINE_MS;
      const key = idempotencyKey(config, message);
      const content = subjectAndText(message.kind);
      const body = JSON.stringify({
        version: DELIVERY_VERSION,
        kind: message.kind,
        to: message.recipient,
        from: config.from.trim(),
        subject: content.subject,
        text: content.text,
        actionUrl: message.url,
      });

      for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
        const remaining = deadline - clock();
        if (remaining <= 0) throw new AuthEmailDeliveryError();
        const abort = new AbortController();
        const timeoutAbort = new AbortController();
        let timedOut = false;
        const timeout = sleep(remaining, timeoutAbort.signal).then(() => {
          timedOut = true;
          abort.abort();
          return null;
        });
        let response: Response | null = null;
        let retryable = false;
        try {
          response = await Promise.race([
            doFetch(new Request(endpoint, {
              method: "POST",
              headers: {
                authorization: `Bearer ${config.bearerToken}`,
                "content-type": "application/json",
                "idempotency-key": key,
                "x-rentemester-auth-event": message.kind,
              },
              body,
              signal: abort.signal,
            })),
            timeout,
          ]);
          timeoutAbort.abort();
          if (response && response.status >= 200 && response.status < 300) return;
          retryable = response?.status === 429 || (response?.status ?? 0) >= 500 || timedOut;
        } catch {
          timeoutAbort.abort();
          retryable = true;
        }
        if (!retryable || attempt === MAX_ATTEMPTS || deadline - clock() <= 0) {
          throw new AuthEmailDeliveryError();
        }
        const delay = Math.min(retryDelay(attempt), Math.max(0, deadline - clock()));
        if (delay <= 0) throw new AuthEmailDeliveryError();
        await sleep(delay);
      }
      throw new AuthEmailDeliveryError();
    },
  };
}

export function validateAuthEmailHttpJsonV1Config(config: AuthEmailHttpJsonV1Config): void {
  parseGatewayUrl(config.url);
  if (!config.bearerToken?.trim()) throw new Error("auth email gateway bearer token is required");
  if (!looksLikeEmail(config.from)) throw new Error("auth email gateway from address is invalid");
  if (!config.idempotencySecret?.trim()) throw new Error("auth email idempotency secret is required");
}

function parseGatewayUrl(value: string): URL {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw new Error("auth email gateway URL must be an absolute HTTPS URL");
  }
  if (url.protocol !== "https:" || url.username || url.password || url.hash) {
    throw new Error("auth email gateway URL must be HTTPS without userinfo or fragment");
  }
  return url;
}

function idempotencyKey(config: AuthEmailHttpJsonV1Config, message: AuthEmailMessage): string {
  return createHmac("sha256", config.idempotencySecret)
    .update(`${DELIVERY_VERSION}\0${message.kind}\0${message.token}`)
    .digest("hex");
}

function subjectAndText(kind: AuthEmailKind): { subject: string; text: string } {
  if (kind === "verification") {
    return {
      subject: "Bekræft din e-mailadresse i Rentemester",
      text: "Bekræft din e-mailadresse ved at åbne linket.",
    };
  }
  if (kind === "workspace-invitation") {
    return {
      subject: "Du er inviteret til Rentemester",
      text: "Åbn invitationen for at oprette eller forbinde din bruger.",
    };
  }
  return {
    subject: "Nulstil din adgangskode til Rentemester",
    text: "Nulstil din adgangskode ved at åbne linket.",
  };
}

function retryDelay(attempt: number): number {
  return 100 * (2 ** (attempt - 1));
}

export function createPrivateBootstrapService(
  db: Database,
  options: BetterAuthRuntimeOptions,
): PrivateBootstrapService {
  const auth = createBetterAuth(db, options, false);
  const lookup = (email: string): { userId: string } | null => {
    const row = db.query('SELECT id FROM "user" WHERE email = ?').get(canonicalBootstrapEmail(email)) as { id: string } | null;
    return row?.id ? { userId: row.id } : null;
  };
  return {
    canonicalEmailHash(email) {
      return createHmac("sha256", options.secret)
        .update(`rentemester-workspace-bootstrap-email-v1\0${canonicalBootstrapEmail(email)}`)
        .digest("hex");
    },
    async findIdentityByCanonicalEmail(email) {
      return lookup(email);
    },
    async createFirstIdentity(input) {
      const email = canonicalBootstrapEmail(input.email);
      const before = lookup(email);
      if (before) return { ...before, created: false };
      const result = await auth.api.signUpEmail({
        body: {
          name: bootstrapText(input.name, "name"),
          email,
          password: bootstrapText(input.password, "password"),
        },
      });
      // `autoSignIn: false` makes a token/session a security regression.
      const actual = lookup(email);
      if (!result?.user?.id || result.token !== null || !actual) {
        throw new Error("private bootstrap did not create a credential-only identity");
      }
      // Better Auth intentionally returns a generic synthetic id for duplicate
      // email sign-ups. Only the read-only canonical lookup is authoritative.
      return { userId: actual.userId, created: actual.userId === result.user.id };
    },
    async resendVerification(email) {
      await auth.api.sendVerificationEmail({ body: { email: canonicalBootstrapEmail(email) } });
    },
  };
}

function createBetterAuth(
  db: Database,
  options: BetterAuthRuntimeOptions,
  disableSignUp: boolean,
): Auth<any> {
  assertInjectedBetterAuthSecret(options.secret);
  const secrets = normalizedVersionedSecrets(options);
  const trustedOrigins = normalizeTrustedOrigins(options.trustedOrigins);
  const baseURL = assertSecureUrl(options.baseURL, "Better Auth baseURL").origin;
  const emailSender = options.emailSender ?? createDisabledAuthEmailSender();

  // Better Auth's documented endpoint after-hook is the only stable surface
  // that observes both public handler and server-API endpoint dispatches.
  const auditAfterHook = async (ctx: any) => {
    const path = String(ctx.path ?? "");
    const endpoint: AuthTelemetryEndpoint | null = ({
      "/send-verification-email": "send-verification-email",
      "/verify-email": "verify-email", "/request-password-reset": "request-password-reset",
      "/reset-password": "reset-password", "/sign-out": "sign-out",
      "/revoke-session": "revoke-session", "/revoke-other-sessions": "revoke-other-sessions",
      "/two-factor/enable": "two-factor-enable", "/two-factor/verify-totp": "two-factor-verify",
    } as Record<string, AuthTelemetryEndpoint>)[path] ?? null;
    if (!endpoint) return { headers: new Headers() };
    const session = ctx.context?.newSession?.session ?? ctx.context?.session?.session;
    const user = ctx.context?.newSession?.user ?? ctx.context?.session?.user;
    const body = ctx.body as { email?: string } | undefined;
    // BA after-hooks lack a stable status for every APIError. Never infer that
    // a first factor, MFA challenge, sign-out, or revoke *completed* here.
    // SQLite triggers below are the authoritative lifecycle evidence.
    const returned = ctx.context?.returned;
    const status = returned instanceof Response ? returned.status : typeof returned?.status === "number" ? returned.status : null;
    const outcome = status === null ? "unknown" : status >= 200 && status < 300 ? "accepted" : "rejected";
    try {
      appendAuthTelemetryEvent(db, { endpoint, outcome, userId: user?.id ?? null, sessionId: session?.id ?? null, identityHash: authAuditIdentityHash(options.secret, body?.email), identityKeyVersion: secrets[0]!.version });
    } catch {
      // An after-hook cannot roll back a completed BA state mutation. Suppress
      // detail; the caller keeps BA's truthful original response.
      console.error('{"component":"auth-audit","event":"auth_telemetry_write_failed","level":"error"}');
    }
    return { headers: new Headers() };
  };
  const useSecureCookies = secureCookieSetting(options);
  const rateLimitIpHeader = hostedRateLimitIpHeader(options);

  const auth = betterAuth({
    database: db,
    // Always pass `secrets` so Better Auth never falls back to a process-wide
    // BETTER_AUTH_SECRETS value outside Rentemester's validated configuration.
    secrets,
    // Better Auth 1.7.1 uses this only to decrypt pre-envelope legacy data.
    secret: options.legacySecret ?? options.secret,
    baseURL,
    appName: "Rentemester",
    trustedOrigins,
    logger: createBetterAuthLogger(options),
    emailAndPassword: {
      enabled: true,
      disableSignUp,
      // A bootstrap identity must never accidentally establish a usable
      // browser session. The normal runtime is explicit too.
      autoSignIn: false,
      minPasswordLength: 12,
      requireEmailVerification: true,
      revokeSessionsOnPasswordReset: true,
      async sendResetPassword({ user, url, token }: BetterAuthEmailCallbackData) {
        await emailSender.send({ kind: "password-reset", recipient: user.email, url, token });
      },
    },
    emailVerification: {
      async sendVerificationEmail({ user, url, token }: BetterAuthEmailCallbackData) {
        await emailSender.send({ kind: "verification", recipient: user.email, url, token });
      },
    },
    session: {
      expiresIn: AUTH_SESSION_EXPIRES_IN_SECONDS,
      freshAge: AUTH_SESSION_FRESH_AGE_SECONDS,
      disableSessionRefresh: true,
      cookieCache: { enabled: false },
    },
    rateLimit: {
      enabled: true,
      storage: "database",
      window: 60,
      max: 10,
    },
    hooks: { after: auditAfterHook },
    advanced: {
      // Better Auth 1.7 reads this setting from `advanced`; keeping it here
      // makes the hosted Secure-cookie requirement effective, not decorative.
      useSecureCookies,
      // Better Auth otherwise skips the origin check in its own test runtime.
      // Explicit false is an enablement assertion, never a security bypass.
      disableOriginCheck: false,
      disableCSRFCheck: false,
      ...(rateLimitIpHeader ? {
        // A single proxy-overwritten header avoids Better Auth's default
        // X-Forwarded-For handling. trustedProxies cannot verify the direct
        // sender, so it is intentionally not configured here.
        ipAddress: { ipAddressHeaders: [rateLimitIpHeader] },
      } : {}),
    },
    plugins: [
      twoFactor({
        issuer: "Rentemester",
        skipVerificationOnEnable: false,
        backupCodeOptions: { storeBackupCodes: "encrypted" },
        accountLockout: { enabled: true, maxFailedAttempts: 10, durationSeconds: 900 },
      }),
      // Service credentials are intentionally separate from browser sessions.
      // Their only authority is the existing workspace/company membership
      // event model; a key itself never carries a role or actor identity.
      apiKey({
        configId: WORKSPACE_SERVICE_PRINCIPAL_CONFIG_ID,
        apiKeyHeaders: WORKSPACE_SERVICE_PRINCIPAL_HEADER,
        defaultPrefix: "rms_",
        requireName: true,
        keyExpiration: {
          // Better Auth takes seconds, not milliseconds.
          defaultExpiresIn: 90 * 24 * 60 * 60,
          disableCustomExpiresTime: false,
          minExpiresIn: 1,
          maxExpiresIn: 365,
        },
        rateLimit: { enabled: true, timeWindow: 60_000, maxRequests: 600 },
        enableSessionForAPIKeys: false,
        references: "user",
      }),
    ],
  }) as Auth<any>;

  // Better Auth's after-hook does not expose a stable result status for these
  // endpoints. Audit them at the HTTP Response boundary instead, so accepted
  // and rejected first-factor/recovery attempts are truthful rather than
  // guessed. Only the sign-in email is pseudonymised; passwords and recovery
  // codes are never retained or forwarded.
  const rawHandler = auth.handler.bind(auth);
  const responseAuditedHandler = async (request: Request): Promise<Response> => {
    const path = new URL(request.url).pathname.replace(/^\/api\/auth/, "");
    const endpoint: AuthTelemetryEndpoint | null = path === "/sign-in/email"
      ? "sign-in-email"
      : path === "/two-factor/verify-backup-code"
        ? "two-factor-verify-backup-code"
        : null;
    if (!endpoint) return await rawHandler(request);

    let identityHash: string | null = null;
    if (endpoint === "sign-in-email") {
      try {
        const body = await request.clone().json() as { email?: unknown };
        identityHash = authAuditIdentityHash(
          options.secret,
          typeof body.email === "string" ? body.email : null,
        );
      } catch {
        // Malformed input remains Better Auth's responsibility; no raw body is logged.
      }
    }

    let response: Response;
    try {
      response = await rawHandler(request);
    } catch (error) {
      try {
        appendAuthTelemetryEvent(db, {
          endpoint,
          outcome: "unknown",
          identityHash,
          identityKeyVersion: secrets[0]!.version,
        });
      } catch {
        console.error('{"component":"auth-audit","event":"auth_telemetry_write_failed","level":"error"}');
      }
      throw error;
    }
    try {
      appendAuthTelemetryEvent(db, {
        endpoint,
        outcome: response.status >= 200 && response.status < 300 ? "accepted" : "rejected",
        identityHash,
        identityKeyVersion: secrets[0]!.version,
      });
    } catch {
      console.error('{"component":"auth-audit","event":"auth_telemetry_write_failed","level":"error"}');
    }
    return response;
  };

  return Object.assign(auth, { handler: responseAuditedHandler });
}

function canonicalBootstrapEmail(email: string): string {
  const normalized = bootstrapText(email, "email").toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized)) throw new Error("email is invalid");
  return normalized;
}

const lookup = (email: string): { userId: string } | null => {
    const row = db.query('SELECT id FROM "user" WHERE email = ?').get(canonicalBootstrapEmail(email)) as { id: string } | null;
    return row?.id ? { userId: row.id } : null;
  };

function bootstrapText(value: string, label: string): string {
  const normalized = typeof value === "string" ? value.trim() : "";
  if (!normalized) throw new Error(`${label} is required`);
  return normalized;
}

export async function runFirstWorkspaceBootstrap(
  db: Database,
  workspaceRoot: string,
  service: WorkspaceBootstrapIdentityService,
  input: BootstrapInput,
): Promise<BootstrapReservation> {
  const ready = await createOrResumeBootstrapIdentity(db, workspaceRoot, service, input);
  return completeFirstWorkspaceBootstrap(db, workspaceRoot, { reservationHash: ready.reservationHash, ...input });
}

export async function createOrResumeBootstrapIdentity(
  db: Database,
  workspaceRoot: string,
  service: WorkspaceBootstrapIdentityService,
  input: BootstrapInput,
): Promise<BootstrapReservation> {
  const email = nonBlank(input.email, "email");
  const reservationHash = service.canonicalEmailHash(email);
  // Company validation happens before the durable singleton reservation, so a
  // typo/archived target cannot permanently consume first-user bootstrap.
  assertReservationCompany(workspaceRoot, input.companySlug);
  let reservation = reserveFirstWorkspaceBootstrap(db, { ...input, reservationHash, companySlug: input.companySlug });
  assertReservationCompany(workspaceRoot, reservation.companySlug);
  if (reservation.phase === "access_completed") return reservation;

  let userId = reservation.userId;
  if (!userId) {
    const existing = await service.findIdentityByCanonicalEmail(email);
    if (existing) userId = existing.userId;
    else {
      try {
        const created = await service.createFirstIdentity({ name: input.name, email, password: input.password });
        userId = created.userId;
        // Better Auth may run sign-up delivery in the background. Do not infer
        // delivery from a credential result; the explicit resend endpoint is
        // the authoritative mail-confirmation step below.
      } catch (error) {
        // Deliberately do not surface provider/credential detail. A subsequent
        // invocation with the same email HMAC can recover a persisted user.
        throw new WorkspaceBootstrapError("identity creation or verification delivery did not complete; retry the same identity");
      }
    }
    assertIdentity(db, userId);
    db.transaction(() => {
      const current = reservationFromEvents(events(db, reservationHash));
      if (!current) throw new WorkspaceBootstrapError("workspace bootstrap reservation is inconsistent");
      if (!current.userId) {
        appendEvent(db, { reservationHash, eventType: "identity_created", userId, ...input, companySlug: null });
        insertWorkspaceAudit(db, { eventType: "workspace_identity_bootstrap_identity_created", entityType: "workspace_bootstrap", entityId: reservationHash, ...input });
      }
    }).immediate();
    reservation = reservationFromEvents(events(db, reservationHash))!;
  }

  if (reservation.phase === "identity_created") {
    try {
      await service.resendVerification(email);
    } catch {
      throw new WorkspaceBootstrapError("verification delivery did not complete; retry the same identity");
    }
    db.transaction(() => {
      const current = reservationFromEvents(events(db, reservationHash));
      if (!current || !current.userId) throw new WorkspaceBootstrapError("workspace bootstrap identity is inconsistent");
      if (current.phase === "identity_created") {
        appendEvent(db, { reservationHash, eventType: "mail_confirmed", userId: current.userId, ...input, companySlug: null });
        insertWorkspaceAudit(db, { eventType: "workspace_identity_bootstrap_mail_confirmed", entityType: "workspace_bootstrap", entityId: reservationHash, ...input });
      }
    }).immediate();
  }
  return reservationFromEvents(events(db, reservationHash))!;
}

export function completeFirstWorkspaceBootstrap(
  db: Database,
  workspaceRoot: string,
  input: { reservationHash: string } & ResolveActorInput,
): BootstrapReservation {
  const reservationHash = assertHash(input.reservationHash);
  return db.transaction((): BootstrapReservation => {
    const current = reservationFromEvents(events(db, reservationHash));
    if (!current || !current.userId) throw new WorkspaceBootstrapError("bootstrap identity is not ready for access completion");
    if (current.phase === "access_completed") return current;
    if (current.phase !== "mail_confirmed") throw new WorkspaceBootstrapError("bootstrap verification delivery is not confirmed");
    assertReservationCompany(workspaceRoot, current.companySlug);
    assertIdentity(db, current.userId);
    const actor = resolveActor(input);
    const access = db.query(
      `SELECT event_type, workspace_role FROM rm_workspace_user_access_events
       WHERE user_id = ? ORDER BY id DESC LIMIT 1`,
    ).get(current.userId) as { event_type: string; workspace_role: string | null } | null;
    const membership = db.query(
      `SELECT event_type, company_role FROM rm_company_membership_events
       WHERE user_id = ? AND company_slug = ? ORDER BY id DESC LIMIT 1`,
    ).get(current.userId, current.companySlug) as { event_type: string; company_role: string | null } | null;
    if (access && (access.event_type !== "activate" || access.workspace_role !== "workspace_owner")) {
      throw new WorkspaceBootstrapError("bootstrap identity already has incompatible workspace access");
    }
    if (membership && (membership.event_type !== "grant" || membership.company_role !== "owner")) {
      throw new WorkspaceBootstrapError("bootstrap identity already has incompatible company access");
    }
    if (!access) db.query(
      `INSERT INTO rm_workspace_user_access_events (user_id, event_type, workspace_role, actor)
       VALUES (?, 'activate', 'workspace_owner', ?)`,
    ).run(current.userId, actor.auditActor);
    if (!membership) db.query(
      `INSERT INTO rm_company_membership_events (user_id, company_slug, event_type, company_role, actor)
       VALUES (?, ?, 'grant', 'owner', ?)`,
    ).run(current.userId, current.companySlug, actor.auditActor);
    appendEvent(db, { ...input, reservationHash, eventType: "access_completed", userId: current.userId, companySlug: current.companySlug });
    insertWorkspaceAudit(db, { eventType: "workspace_identity_bootstrap_access_completed", entityType: "workspace_bootstrap", entityId: reservationHash, ...input });
    return reservationFromEvents(events(db, reservationHash))!;
  }).immediate();
}

typeDeclarations.source:
export type WorkspaceCompanyEntry = {
  /** Filesystem-safe identifier; the subdirectory name under the workspace. */
  slug: string;
  /** Human-readable display name. */
  name: string;
  /** ISO-8601 timestamp of when the entry was first registered. */
  createdAt: string;
  /** Soft-deletion flag; archived companies stay on disk. */
  archived: boolean;
};

export type ResolveServerConfigOptions = {
  /** Explicit overrides (e.g. from CLI flags) take precedence over env. */
  host?: string;
  port?: number;
  workspaceRoot?: string;
  /** Read environment from here instead of `process.env` (testability). */
  env?: Record<string, string | undefined>;
};

export type ServerConfig = {
  /** Explicit deployment boundary. `local` may never expose Better Auth. */
  deploymentProfile?: DeploymentProfile;
  /** Interface to bind. Defaults to 127.0.0.1 (localhost-only). */
  host: string;
  /** TCP port to listen on. */
  port: number;
  /** Workspace root the API serves. */
  workspaceRoot: string;
  /**
   * When true, the auth middleware enforces a shared-secret check via the
   * `RENTEMESTER_APP_TOKEN` env var. Phase 1 leaves this off (localhost-trusted)
   * — it exists so the seam can be exercised by tests and flipped on later.
   */
  authRequired: boolean;
  /** Optional shared secret consulted only when `authRequired` is true. */
  authToken: string | null;
  /** Present only for a validated hosted deployment; never serialised. */
  hostedBetterAuth?: HostedBetterAuthConfig;
  /** Hosted ingress policy and, when required, a validated provider config. */
  hostedDocumentScanning?: HostedDocumentScanningConfig;
  /** Runtime scanner seam. Local deployments intentionally leave this absent. */
  documentScanner?: DocumentScanner;
  documentScannerPolicy?: "off" | "required";
  /** Optional explicit extraction provider; absence means extraction is unavailable. */
  invoiceExtractor?: InvoiceExtractor;
  /**
   * Hosted identity provider. Its presence selects Better Auth sessions for
   * protected API routes; public routes remain anonymous. This is injected by
   * the serving composition root, never constructed from a fallback secret.
   */
  betterAuthProvider?: BetterAuthRequestProvider;
  /** Test/composition seam; production derives it from the validated hosted mail configuration. */
  authEmailSender?: AuthEmailSender;
  /** Test/composition seam for private invitation identity creation. */
  invitationIdentityService?: PrivateInvitationIdentityService;
  /**
   * Per-request authentication result. `handleRequest` creates an immutable
   * config copy carrying this value after its one auth evaluation; it is never
   * populated by environment/config resolution.
   */
  requestPrincipal?: Principal;
  /** Validated request correlation ID, attached only by the server edge. */
  requestId?: string;
  /** Test/provider seam; never resolved from environment and invoked only by the router. */
  authenticateRequest?: (request: Request, config: ServerConfig) => Principal | Promise<Principal>;
  /** Test/composition seam for allowlisted request-completion records. Never env-derived. */
  requestLogSink?: RequestLogSink;
  /** Test seam for deterministic, validated response correlation IDs. */
  requestIdFactory?: () => string;
  /** Test seam for deterministic request timestamps and durations. */
  requestLogClock?: () => number;
  /**
   * Absolute path to the built cockpit SPA (`app/dist`). When the directory
   * exists, the server serves it for every non-`/api` route. Resolved here so
   * the rest of the server stays pure. Optional: when absent the server is a
   * pure JSON API (the shape used by API-only tests).
   */
  staticRoot?: string;
};

export type HostedBetterAuthConfig = {
  /** Active key; never emit it in health, CLI, logs, or error responses. */
  secret: string;
  /** First entry is active, following entries are Better Auth decryption-only. */
  secrets: readonly BetterAuthVersionedSecret[];
