export type WorkspaceCompanyEntry = {
  /** Filesystem-safe identifier; the subdirectory name under the workspace. */
  slug: string;
  /** Human-readable display name. */
  name: string;
  /** ISO-8601 timestamp of when the entry was first registered. */
  createdAt: string;
  /** Soft-deletion flag; archived companies stay on disk. */
  archived: boolean;
};

export type WorkspaceManifest = {
  version: typeof MANIFEST_VERSION;
  companies: WorkspaceCompanyEntry[];
};

export type CreateWorkspaceSnapshotResult = {
  ok: boolean;
  snapshotPath?: string;
  sha256?: string;
  sha256Path?: string;
  companyCount?: number;
  accessIdentityCount?: number;
  appliedRules: string[];
  errors: string[];
};

type SnapshotAccessPlan = {
  version: 1;
  recovery: "bootstrap-owner-then-reinvite";
  users: Array<{
    name: string;
    email: string;
    workspaceRole: WorkspaceRole;
    memberships: Array<{ companySlug: string; role: CompanyRole }>;
  }>;
};

export type WorkspaceMember = {
  userId: string;
  name: string;
  email: string;
  emailVerified: boolean;
  twoFactorEnabled: boolean;
  accessReady: boolean;
  workspaceRole: WorkspaceRole;
  memberships: Array<{
    companySlug: string;
    companyName: string;
    role: CompanyRole;
    archived: boolean;
  }>;
};

export type WorkspaceSnapshotManifestV1 = {
  version: 1;
  createdAt: string;
  provenance: ReleaseProvenance;
  credentialPolicy: "omit-all-auth-and-operational-credentials-v1";
  workspaceManifest: ManifestFile;
  accessPlan: ManifestFile;
  /** Non-credential operating knowledge is portable; auth state remains omitted. */
  companyKnowledge?: ManifestFile;
  /** Source-backed legal ownership history is portable; credentials remain omitted. */
  ownershipGraph?: ManifestFile;
  /** Canonical party provenance and immutable corporate evidence; no auth data. */
  workspaceRegistry?: ManifestFile;
  /** Append-only, workspace-only intercompany evidence lifecycle; no credentials. */
  intercompanyDispositions?: ManifestFile;
  workspaceInbox?: ManifestFile;
  companies: Array<{
    slug: string;
    name: string;
    archived: boolean;
    backup: ManifestFile;
  }>;
};

export type ReleaseProvenance = {
  product: ReturnType<typeof getBuildIdentity>;
  schema: {
    version: number;
    baselineChecksum: string;
  };
  rules: {
    digest: string;
  };
};

export type CreateSystemBackupInput = {
  createdAt?: string;
  debugHoldMs?: number;
  signWithEd25519?: boolean;
  /** Portable workspace snapshots omit operational credentials and destinations. */
  credentialFree?: boolean;
  createdBy?: string;
  createdByProgram?: string;
};

export type CreateSystemBackupResult = {
  ok: boolean;
  backupId?: string;
  backupDir?: string;
  manifestPath?: string;
  dbSnapshotPath?: string;
  appliedRules: string[];
  errors: string[];
};

export type BackupAsymmetricSignature = {
  algorithm: "ed25519";
  publicKeyHint: string;
  publicKeyPath: string;
  signaturePath: string;
};

export type BackupManifestV2 = BackupManifestBody & {
  manifestVersion: 2;
  provenance: ReleaseProvenance;
};

type BackupManifestBody = {
  backupId: string;
  createdAt: string;
  ruleIds: string[];
  manifestSignature: {
    algorithm: "hmac-sha256";
    keyHint: string;
    signaturePath: string;
  };
  asymmetricSignature?: BackupAsymmetricSignature;
  dbSnapshot: ManifestFile;
  copiedFiles: {
    documentsOriginals: ManifestFile[];
    invoicesIssued: ManifestFile[];
    config: ManifestFile[];
  };
  ledgerStats: {
    journalEntries: number;
    documents: number;
    bankTransactions: number;
  };
};

export type PackBackupArchiveResult = {
  ok: boolean;
  backupId?: string;
  archivePath?: string;
  archiveSha256?: string;
  archiveSizeBytes?: number;
  sha256Path?: string;
  appliedRules: string[];
  errors: string[];
};

export type TarInputEntry = {
  // POSIX-style relative path inside the archive (always uses "/").
  path: string;
  content: Uint8Array;
  // Octal file mode. Defaults to 0o644; only the low 12 bits are kept.
  mode?: number;
};

