export function resolveWorkspaceRoot(raw: string): string {
  if (raw.split(/[\\/]+/).includes("..")) {
    throw new Error("workspace root must not contain parent-directory ('..') segments");
  }
  const resolved = resolve(raw);
  if (!isAbsolute(resolved) || resolved.split(sep).includes("..")) {
    throw new Error("workspace root resolved to an unsafe path");
  }
  return resolved;
}

export function listWorkspaceCompanies(workspaceRoot: string): WorkspaceCompanyEntry[] {
  return loadWorkspaceManifest(workspaceRoot).companies;
}

export function loadWorkspaceManifest(workspaceRoot: string): WorkspaceManifest {
  const path = manifestPath(workspaceRoot);
  if (!existsSync(path)) return emptyManifest();
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(path, "utf8"));
  } catch {
    throw new Error(`workspace manifest at ${path} is not valid JSON`);
  }
  if (!parsed || typeof parsed !== "object" || !Array.isArray((parsed as any).companies)) {
    throw new Error(`workspace manifest at ${path} is malformed`);
  }
  if ((parsed as any).version !== MANIFEST_VERSION) {
    throw new Error(
      `workspace manifest at ${path} has unsupported version ${(parsed as any).version}; expected ${MANIFEST_VERSION}`,
    );
  }
  const companies: WorkspaceCompanyEntry[] = (parsed as any).companies.map((raw: any) => ({
    slug: String(raw.slug),
    name: String(raw.name),
    createdAt: String(raw.createdAt),
    archived: Boolean(raw.archived),
  }));
  return { version: MANIFEST_VERSION, companies };
}

export function companyRootForSlug(workspaceRoot: string, slug: string): string {
  assertValidSlug(slug);
  return join(workspaceRoot, slug);
}

function assertValidSlug(slug: string): void {
  if (!isValidSlug(slug)) {
    throw new Error(
      `invalid company slug '${slug}': use lowercase letters, digits and dashes`,
    );
  }
}

export function createWorkspaceSnapshot(
  workspaceRoot: string,
  input: { outPath: string; createdAt?: string; createdBy?: string; createdByProgram?: string },
): CreateWorkspaceSnapshotResult {
  const createdAt = validInstant(input.createdAt);
  const outPath = input.outPath?.trim();
  if (!createdAt || !outPath) {
    return { ok: false, appliedRules: [SNAPSHOT_RULE_ID], errors: ["outPath and a valid createdAt are required"] };
  }
  if (existsSync(outPath)) {
    return { ok: false, appliedRules: [SNAPSHOT_RULE_ID], errors: ["snapshot destination already exists"] };
  }
  const companies = listWorkspaceCompanies(workspaceRoot);
  if (companies.length === 0) {
    return { ok: false, appliedRules: [SNAPSHOT_RULE_ID], errors: ["workspace has no registered companies"] };
  }
  const staging = mkdtempSync(join(tmpdir(), "rentemester-workspace-snapshot-"));
  try {
    const workspaceManifestPath = join(staging, "workspace.json");
    saveWorkspaceManifest(staging, loadWorkspaceManifest(workspaceRoot));
    const controlDbPath = workspaceControlPaths(workspaceRoot).db;
    const accessPlan: SnapshotAccessPlan = { version: 1, recovery: "bootstrap-owner-then-reinvite", users: [] };
    if (existsSync(controlDbPath)) {
      const controlDb = openWorkspaceControlDb(workspaceRoot);
      try {
        accessPlan.users = listWorkspaceMembers(controlDb, workspaceRoot).map((member) => ({
          name: member.name,
          email: member.email,
          workspaceRole: member.workspaceRole,
          memberships: member.memberships.map(({ companySlug, role }) => ({ companySlug, role })),
        }));
      } finally { controlDb.close(); }
    }
    const accessPlanPath = join(staging, "access-plan.json");
    writeFileAtomic(accessPlanPath, `${JSON.stringify(accessPlan, null, 2)}\n`);
    let companyKnowledge: ManifestFile | undefined;
    let ownershipGraph: ManifestFile | undefined;
    let workspaceRegistry: ManifestFile | undefined;
    let intercompanyDispositions: ManifestFile | undefined;
    let workspaceInbox: ManifestFile | undefined;
    if (existsSync(controlDbPath)) {
      const controlDb = openWorkspaceControlDb(workspaceRoot);
      try {
        const assertions = controlDb.query("SELECT assertion_id,company_slug,predicate,value_json,value_hash,source_kind,source_ref,valid_from,valid_to_exclusive,certainty,actor,principal_kind,principal_id,created_at FROM rm_company_knowledge_assertions ORDER BY id").all();
        const events = controlDb.query("SELECT assertion_id,event_type,reason,supersedes_assertion_id,actor,principal_kind,principal_id,created_at FROM rm_company_knowledge_events ORDER BY id").all();
        if (assertions.length > 0 || events.length > 0) {
          const path = join(staging, "company-knowledge.json");
          writeFileAtomic(path, `${JSON.stringify({ version: 1, assertions, events })}\n`);
          companyKnowledge = fileEvidence(staging, path);
        }
      } finally { controlDb.close(); }
    }
    if (existsSync(controlDbPath)) {
      const controlDb = openWorkspaceControlDb(workspaceRoot);
      try {
        const dispositions = controlDb.query("SELECT disposition_id,canonical_payload,payload_hash,created_at FROM rm_intercompany_dispositions ORDER BY disposition_id").all();
        const events = controlDb.query("SELECT disposition_id,event_type,payload_hash,canonical_payload,actor,principal_kind,principal_id,previous_hash,event_hash,created_at FROM rm_intercompany_disposition_events ORDER BY id").all();
        const links = controlDb.query("SELECT disposition_id,side,company_slug,journal_entry_id,journal_entry_no,journal_entry_hash,ledger_head_hash,linked_at,actor,principal_kind,principal_id FROM rm_intercompany_disposition_journal_links ORDER BY disposition_id,side").all();
        const lifecycleEvents = controlDb.query("SELECT disposition_id,event_type,payload_hash,canonical_payload,actor,principal_kind,principal_id,previous_hash,event_hash,created_at FROM rm_intercompany_disposition_lifecycle_events ORDER BY id").all();
        if ([dispositions, events, links, lifecycleEvents].some((rows) => rows.length > 0)) {
          const path = join(staging, "intercompany-dispositions.json");
          writeFileAtomic(path, `${JSON.stringify({ version: 1, dispositions, events, links, lifecycleEvents })}\n`);
          intercompanyDispositions = fileEvidence(staging, path);
        }
      } finally { controlDb.close(); }
    }
    if (existsSync(controlDbPath)) { const controlDb=openWorkspaceControlDb(workspaceRoot);try{const sources=(controlDb.query("SELECT source_id,visibility_anchor_slug,idempotency_key,original_bytes,sha256,filename,mime_type,transport,transport_identity,received_at,metadata_json,created_by,created_at FROM rm_workspace_inbox_sources ORDER BY source_id").all() as any[]).map(row=>({...row,original_bytes_base64:Buffer.from(row.original_bytes).toString("base64"),original_bytes:undefined})),events=controlDb.query("SELECT source_id,event_type,payload_hash,canonical_payload,actor,created_at FROM rm_workspace_inbox_events ORDER BY id").all(),assignments=controlDb.query("SELECT source_id,company_slug,state,document_id,document_no,assigned_by,assigned_at,completed_at FROM rm_workspace_inbox_assignments ORDER BY source_id,company_slug").all(),exceptions=controlDb.query("SELECT source_id,code,required_action,opened_at,resolved_at FROM rm_workspace_inbox_exceptions ORDER BY source_id").all(),claims=controlDb.query("SELECT source_id,company_slug,source_hash,state,claim_id,lease_expires_at,document_id,document_no,created_at,updated_at FROM rm_workspace_inbox_handoff_claims ORDER BY source_id,company_slug").all();if([sources,events,assignments,exceptions,claims].some(x=>x.length)){const path=join(staging,"workspace-inbox.json");writeFileAtomic(path,`${JSON.stringify({version:1,sources,events,assignments,exceptions,claims})}\n`);workspaceInbox=fileEvidence(staging,path);}}finally{controlDb.close();}}
    if (existsSync(controlDbPath)) {
      const controlDb = openWorkspaceControlDb(workspaceRoot);
      try {
        const parties = controlDb.query("SELECT party_id,event_type,canonical_kind,payload_hash,canonical_payload,actor,created_at FROM rm_party_events ORDER BY id").all();
        const aliases = controlDb.query("SELECT party_id,alias,source,observed_at,review_state,payload_hash,actor,created_at FROM rm_party_alias_assertions ORDER BY id").all();
        const assertions = controlDb.query("SELECT party_id,field,value,source,observed_at,review_state,payload_hash,actor,created_at FROM rm_party_field_assertions ORDER BY id").all();
        const roles = controlDb.query("SELECT party_id,company_slug,role,defaults_json FROM rm_party_company_roles ORDER BY party_id,company_slug,role").all();
        const legacyLinks = controlDb.query("SELECT company_slug,legacy_kind,legacy_id,party_id,actor,created_at FROM rm_party_legacy_links ORDER BY company_slug,legacy_kind,legacy_id").all();
        const identifiers = controlDb.query("SELECT party_id,jurisdiction,identifier_kind,identifier FROM rm_party_identifiers ORDER BY party_id,jurisdiction,identifier_kind,identifier").all();
        const bytes = (controlDb.query("SELECT record_id,original_bytes,sha256,filename,source,received_at,record_date,retention_until,uploader,sensitivity FROM rm_corporate_record_bytes ORDER BY record_id").all() as any[]).map(row => ({...row, original_bytes_base64: Buffer.from(row.original_bytes).toString("base64"), original_bytes: undefined}));
        const events = controlDb.query("SELECT record_id,event_type,record_type,payload_hash,canonical_payload,actor,created_at FROM rm_corporate_record_events ORDER BY id").all();
        const links = controlDb.query("SELECT record_id,link_type,link_id FROM rm_corporate_record_links ORDER BY record_id,link_type,link_id").all();
        const scopes = controlDb.query("SELECT record_id,scope_kind,scope_id,actor,created_at FROM rm_corporate_record_scope_assertions ORDER BY id").all();
        if ([parties,aliases,assertions,roles,legacyLinks,identifiers,bytes,events,links,scopes].some(rows => rows.length)) {
          const path = join(staging, "workspace-registry.json");
          writeFileAtomic(path, `${JSON.stringify({version:1,parties,aliases,assertions,roles,legacyLinks,identifiers,corporate:{bytes,events,links,scopes}})}\n`);
          workspaceRegistry = fileEvidence(staging, path);
        }
      } finally { controlDb.close(); }
    }
    if (existsSync(controlDbPath)) {
      const controlDb = openWorkspaceControlDb(workspaceRoot);
      try {
        const snapshots = controlDb.query("SELECT snapshot_id,source,observed_at,snapshot_hash,diff_hash,canonical_facts,diff_json,actor,principal_kind,principal_id,created_at FROM rm_ownership_source_snapshots ORDER BY id").all();
        const events = controlDb.query("SELECT snapshot_id,event_type,actor,principal_kind,principal_id,created_at FROM rm_ownership_snapshot_events ORDER BY id").all();
        const facts = controlDb.query("SELECT fact_id,snapshot_id,fact_hash,canonical_fact,owner_kind,owner_id,owned_company_slug,valid_from,valid_to_exclusive,economic_exact_bp,economic_min_bp,economic_max_bp,voting_bp,control_type,share_class,jurisdiction,review_state,created_at FROM rm_ownership_facts ORDER BY id").all();
        const factEvents = controlDb.query("SELECT fact_hash,event_type,effective_to_exclusive,successor_fact_hash,snapshot_id,actor,principal_kind,principal_id,created_at FROM rm_ownership_fact_events ORDER BY id").all();
        if (snapshots.length > 0 || events.length > 0 || facts.length > 0 || factEvents.length > 0) {
          const path = join(staging, "ownership-graph.json");
          writeFileAtomic(path, `${JSON.stringify({ version: 2, snapshots, events, facts, factEvents })}\n`);
          ownershipGraph = fileEvidence(staging, path);
        }
      } finally { controlDb.close(); }
    }

    const companyEntries: WorkspaceSnapshotManifestV1["companies"] = [];
    for (const company of companies) {
      const companyRoot = companyRootForSlug(workspaceRoot, company.slug);
      const db = openDb(companyPaths(companyRoot).db);
      try {
        migrate(db);
        const backup = createSystemBackup(db, companyRoot, {
          createdAt,
          signWithEd25519: true,
          credentialFree: true,
          createdBy: input.createdBy,
          createdByProgram: input.createdByProgram,
        });
        if (!backup.ok || !backup.backupId) throw new Error(backup.errors.join("; "));
        const archivePath = join(staging, "companies", `${company.slug}.tar`);
        mkdirSync(dirname(archivePath), { recursive: true });
        const packed = packBackupArchive(db, companyRoot, {
          backupId: backup.backupId,
          outPath: archivePath,
          createdBy: input.createdBy,
          createdByProgram: input.createdByProgram,
        });
        if (!packed.ok) throw new Error(packed.errors.join("; "));
        removePathWithRetry(`${archivePath}.sha256`);
        companyEntries.push({
          slug: company.slug,
          name: company.name,
          archived: company.archived,
          backup: fileEvidence(staging, archivePath),
        });
      } finally { db.close(); }
    }

    const manifest: WorkspaceSnapshotManifestV1 = {
      version: 1,
      createdAt,
      provenance: getReleaseProvenance(),
      credentialPolicy: "omit-all-auth-and-operational-credentials-v1",
      workspaceManifest: fileEvidence(staging, workspaceManifestPath),
      accessPlan: fileEvidence(staging, accessPlanPath),
      ...(companyKnowledge ? { companyKnowledge } : {}),
      ...(ownershipGraph ? { ownershipGraph } : {}),
      ...(workspaceRegistry ? { workspaceRegistry } : {}),
      ...(intercompanyDispositions ? { intercompanyDispositions } : {}),
      ...(workspaceInbox ? { workspaceInbox } : {}),
      companies: companyEntries.sort((a, b) => a.slug.localeCompare(b.slug)),
    };
    writeFileAtomic(join(staging, "manifest.json"), `${JSON.stringify(manifest, null, 2)}\n`);
    const archive = createTar(dirToTarEntries(staging));
    const digest = sha256(archive);
    mkdirSync(dirname(resolve(outPath)), { recursive: true });
    const temp = writeTempFileFor(outPath, archive);
    promoteTempFileExclusive(temp, outPath);
    const sha256Path = `${outPath}.sha256`;
    writeFileAtomic(sha256Path, `${digest}  ${basename(outPath)}\n`);
    return {
      ok: true,
      snapshotPath: outPath,
      sha256: digest,
      sha256Path,
      companyCount: companyEntries.length,
      accessIdentityCount: accessPlan.users.length,
      appliedRules: [SNAPSHOT_RULE_ID],
      errors: [],
    };
  } catch (error) {
    return { ok: false, appliedRules: [SNAPSHOT_RULE_ID], errors: [`workspace snapshot failed: ${snapshotError(error)}`] };
  } finally {
    removePathWithRetry(staging);
  }
}

function validInstant(value?: string): string | null {
  const instant = value ?? new Date().toISOString();
  return Number.isNaN(Date.parse(instant)) ? null : new Date(instant).toISOString();
}

export function saveWorkspaceManifest(
  workspaceRoot: string,
  manifest: WorkspaceManifest,
): void {
  mkdirSync(workspaceRoot, { recursive: true });
  const ordered = sortedManifest(manifest);
  assertLegacyWorkspaceActive(workspaceRoot);
  writeFileAtomic(manifestPath(workspaceRoot), `${JSON.stringify(ordered, null, 2)}\n`);
}

export function listWorkspaceMembers(
  db: Database,
  workspaceRoot: string,
): WorkspaceMember[] {
  const users = db.query(
    `SELECT u.id, u.name, u.email, u.emailVerified, u.twoFactorEnabled,
            access.workspace_role
       FROM "user" AS u
       JOIN rm_workspace_user_access_events AS access ON access.user_id = u.id
       JOIN (
         SELECT user_id, MAX(id) AS latest_id
           FROM rm_workspace_user_access_events
          GROUP BY user_id
       ) AS latest ON latest.latest_id = access.id
      WHERE access.event_type = 'activate'
      ORDER BY lower(u.email), u.id`,
  ).all() as Array<{
    id: string;
    name: string;
    email: string;
    emailVerified: number;
    twoFactorEnabled: number | null;
    workspace_role: WorkspaceRole;
  }>;
  const companies = new Map(listWorkspaceCompanies(workspaceRoot).map((company) => [company.slug, company]));

  return users.map((user) => {
    const memberships = db.query(
      `SELECT membership.company_slug, membership.company_role
         FROM rm_company_membership_events AS membership
         JOIN (
           SELECT company_slug, MAX(id) AS latest_id
             FROM rm_company_membership_events
            WHERE user_id = ?
            GROUP BY company_slug
         ) AS latest ON latest.latest_id = membership.id
        WHERE membership.user_id = ? AND membership.event_type = 'grant'
        ORDER BY membership.company_slug`,
    ).all(user.id, user.id) as Array<{ company_slug: string; company_role: CompanyRole }>;
    return {
      userId: user.id,
      name: user.name,
      email: user.email,
      emailVerified: user.emailVerified === 1,
      twoFactorEnabled: user.twoFactorEnabled === 1,
      accessReady: user.emailVerified === 1 && user.twoFactorEnabled === 1,
      workspaceRole: user.workspace_role,
      memberships: memberships.flatMap((membership) => {
        const company = companies.get(membership.company_slug);
        return company ? [{
          companySlug: company.slug,
          companyName: company.name,
          role: membership.company_role,
          archived: company.archived,
        }] : [];
      }),
    };
  });
}

export function writeFileAtomic(finalPath: string, content: string | Uint8Array) {
  const tempPath = writeTempFileFor(finalPath, content);
  try {
    promoteTempFile(tempPath, finalPath);
  } catch (error) {
    removeIfExists(tempPath);
    throw error;
  }
}

function fileEvidence(root: string, path: string): ManifestFile {
  const content = readFileSync(path);
  return {
    path: path.slice(root.length + 1).replaceAll("\\", "/"),
    sha256: sha256(content),
    sizeBytes: content.byteLength,
  };
}

export function createSystemBackup(db: Database, companyRoot: string, input: CreateSystemBackupInput = {}): CreateSystemBackupResult {
  const createdAt = resolveCreatedAt(input.createdAt);
  if (!createdAt) return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: ["createdAt must be a valid ISO-8601 datetime when provided"] };
  if (input.debugHoldMs !== undefined && (!Number.isFinite(input.debugHoldMs) || input.debugHoldMs < 0)) {
    return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: ["debugHoldMs must be a non-negative number when provided"] };
  }

  const paths = companyPaths(companyRoot);
  mkdirSync(paths.backups, { recursive: true });
  const backupId = backupIdFromIso(createdAt);
  const backupDir = join(paths.backups, backupId);
  if (existsSync(backupDir)) {
    return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: [`backup already exists: ${backupId}`] };
  }

  mkdirSync(backupDir, { recursive: true });
  const dbSnapshotPath = join(backupDir, "ledger.sqlite");
  const documentsBackupDir = join(backupDir, "documents-originals");
  const invoicesBackupDir = join(backupDir, "invoices-issued");
  const configBackupDir = join(backupDir, "config");

  try {
    buildLockedSnapshot(db, paths.db, dbSnapshotPath, input.debugHoldMs ?? 0);
  } catch (error) {
    return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: [`failed to create locked backup snapshot: ${String(error)}`] };
  }

  const snapshotDb = new Database(dbSnapshotPath, { readonly: true });
  const ledgerStats = {
    journalEntries: (snapshotDb.query("SELECT COUNT(*) AS n FROM journal_entries").get() as { n: number }).n,
    documents: (snapshotDb.query("SELECT COUNT(*) AS n FROM documents").get() as { n: number }).n,
    bankTransactions: (snapshotDb.query("SELECT COUNT(*) AS n FROM bank_transactions").get() as { n: number }).n,
  };
  snapshotDb.close();

  const manifestKey = ensureBackupManifestKey(companyRoot);

  // If asymmetric signing is requested, generate the keypair BEFORE we copy
  // config/, so the freshly-created public key ends up inside the backup as
  // part of the standard config copy. The private key stays at
  // <companyRoot>/.backup-signing-key.pem (mode 0o600) and is never copied.
  let asymmetricKeypair: ReturnType<typeof ensureEd25519Keypair> | null = null;
  if (input.signWithEd25519) {
    try {
      asymmetricKeypair = ensureEd25519Keypair(companyRoot);
    } catch (error) {
      return { ok: false, appliedRules: [BACKUP_RULE_ID], errors: [`failed to resolve ed25519 signing key: ${String(error)}`] };
    }
  }

  const copiedConfig = copyDirWithManifest(
    paths.config,
    configBackupDir,
    backupDir,
    input.credentialFree ? (name) => PORTABLE_CONFIG_ALLOWLIST.has(name) : undefined,
  );

  const asymmetricSignature: BackupAsymmetricSignature | undefined = asymmetricKeypair
    ? {
        algorithm: "ed25519",
        publicKeyHint: publicKeyHint(asymmetricKeypair.publicKeyPem),
        publicKeyPath: relativeBackupPath(backupDir, join(configBackupDir, "backup-manifest.pub")),
        signaturePath: relativeBackupPath(backupDir, backupAsymmetricSignaturePath(backupDir)),
      }
    : undefined;

  const manifest: BackupManifestV2 = {
    manifestVersion: 2,
    provenance: getReleaseProvenance(),
    backupId,
    createdAt,
    ruleIds: [BACKUP_RULE_ID],
    manifestSignature: {
      algorithm: "hmac-sha256",
      keyHint: backupManifestKeyHint(manifestKey),
      signaturePath: relativeBackupPath(backupDir, backupManifestSignaturePath(backupDir)),
    },
    ...(asymmetricSignature ? { asymmetricSignature } : {}),
    dbSnapshot: {
      path: relativeBackupPath(backupDir, dbSnapshotPath),
      sha256: sha256File(dbSnapshotPath),
      sizeBytes: statSync(dbSnapshotPath).size,
    },
    copiedFiles: {
      documentsOriginals: copyDirWithManifest(paths.documentsOriginals, documentsBackupDir, backupDir),
      invoicesIssued: copyDirWithManifest(paths.invoicesIssued, invoicesBackupDir, backupDir),
      config: copiedConfig,
    },
    ledgerStats,
  };

  // Atomic, crash-safe ordering (issue #151): write every signature to disk
  // FIRST, then promote the manifest LAST. A crash before the manifest rename
  // leaves an unreferenced manifest-less directory (ignored by listing); a
  // crash after it leaves a manifest whose signatures are already durable.
  const manifestPath = join(backupDir, "manifest.json");
  const manifestText = `${JSON.stringify(manifest, null, 2)}\n`;
  writeFileAtomic(backupManifestSignaturePath(backupDir), `${signManifestText(manifestText, manifestKey)}\n`);
  if (asymmetricKeypair) {
    writeFileAtomic(backupAsymmetricSignaturePath(backupDir), `${signManifestEd25519(manifestText, asymmetricKeypair.privateKeyPem)}\n`);
  }
  const manifestTemp = writeTempFileFor(manifestPath, manifestText);
  promoteTempFile(manifestTemp, manifestPath);

  insertAuditLog(db, {
    eventType: "system_backup",
    entityType: "company",
    entityId: 1,
    message: `Created full backup ${backupId}`,
    createdBy: input.createdBy,
    createdByProgram: input.createdByProgram,
    fallbackActor: { createdBy: "scheduled:system_backup", createdByProgram: "rentemester-cron" },
  });

  return { ok: true, backupId, backupDir, manifestPath, dbSnapshotPath, appliedRules: [BACKUP_RULE_ID], errors: [] };
}

const PORTABLE_CONFIG_ALLOWLIST = new Set([
  "backup-lock.json",
  "backup-manifest.pub",
  "policy.yaml",
]);

export function packBackupArchive(
  db: Database,
  companyRoot: string,
  input: { backupId?: string; outPath?: string; createdBy?: string; createdByProgram?: string } = {},
): PackBackupArchiveResult {
  const paths = companyPaths(companyRoot);
  let backupId = input.backupId?.trim();
  if (!backupId) {
    const latest = listBackupManifests(companyRoot).at(-1);
    if (!latest) {
      return {
        ok: false,
        appliedRules: [BACKUP_RULE_ID],
        errors: ["no backup found to archive; run 'system backup' first"],
      };
    }
    backupId = latest.backupId;
  }

  const backupDir = join(paths.backups, backupId);
  if (!existsSync(join(backupDir, "manifest.json"))) {
    return {
      ok: false,
      appliedRules: [BACKUP_RULE_ID],
      errors: [`backup not found or has no manifest: ${backupId}`],
    };
  }

  const archivePath = input.outPath?.trim() || join(paths.backups, `${backupId}.tar`);
  let archive: Buffer;
  try {
    archive = createTar(dirToTarEntries(backupDir));
  } catch (error) {
    return {
      ok: false,
      appliedRules: [BACKUP_RULE_ID],
      errors: [`failed to pack backup archive: ${String(error)}`],
    };
  }

  const sha256 = createHash("sha256").update(archive).digest("hex");
  const sha256Path = `${archivePath}.sha256`;
  try {
    writeFileAtomic(archivePath, archive);
    writeFileAtomic(sha256Path, `${sha256}  ${basename(archivePath)}\n`);
  } catch (error) {
    return {
      ok: false,
      appliedRules: [BACKUP_RULE_ID],
      errors: [`failed to write backup archive: ${String(error)}`],
    };
  }

  insertAuditLog(db, {
    eventType: "backup_archive_created",
    entityType: "company",
    entityId: 1,
    message: `Packed backup ${backupId} into single-file archive ${basename(archivePath)} (sha256:${sha256})`,
    createdBy: input.createdBy,
    createdByProgram: input.createdByProgram,
  });

  return {
    ok: true,
    backupId,
    archivePath,
    archiveSha256: sha256,
    archiveSizeBytes: archive.length,
    sha256Path,
    appliedRules: [BACKUP_RULE_ID],
    errors: [],
  };
}

export function removePathWithRetry(path: string, options: RmOptions = { recursive: true, force: true }): void {
  retryTransientCleanup(() => rmSync(path, options));
}

export function getReleaseProvenance(): ReleaseProvenance {
  return {
    product: getBuildIdentity(),
    schema: {
      version: CURRENT_SCHEMA_VERSION,
      baselineChecksum: BASELINE_MIGRATION_CHECKSUM,
    },
    rules: {
      digest: computeRuleSetDigest(),
    },
  };
}

export function createTar(entries: TarInputEntry[]): Buffer {
  const sorted = [...entries].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  for (let i = 1; i < sorted.length; i += 1) {
    if (sorted[i]!.path === sorted[i - 1]!.path) {
      throw new Error(`tar: duplicate entry path: ${sorted[i]!.path}`);
    }
  }
  const chunks: Buffer[] = [];
  for (const entry of sorted) {
    if (entry.path.length === 0 || entry.path.startsWith("/") || entry.path.includes("\0")) {
      throw new Error(`tar: invalid entry path: ${entry.path}`);
    }
    const content = Buffer.from(entry.content);
    chunks.push(buildHeader({ path: entry.path, size: content.length, mode: entry.mode ?? 0o644 }));
    chunks.push(content);
    const padding = pad512(content.length);
    if (padding > 0) chunks.push(Buffer.alloc(padding));
  }
  chunks.push(Buffer.alloc(BLOCK * 2)); // two zero blocks terminate the archive
  return Buffer.concat(chunks);
}

export function dirToTarEntries(rootDir: string): TarInputEntry[] {
  const entries: TarInputEntry[] = [];
  const walk = (dir: string): void => {
    for (const item of readdirSync(dir, { withFileTypes: true })) {
      const abs = join(dir, item.name);
      if (item.isDirectory()) {
        walk(abs);
      } else if (item.isFile()) {
        const rel = relative(rootDir, abs).split(sep).join("/");
        entries.push({ path: rel, content: readFileSync(abs) });
      }
    }
  };
  walk(rootDir);
  return entries;
}

function sha256(content: Uint8Array): string {
  return createHash("sha256").update(content).digest("hex");
}

export function writeTempFileFor(finalPath: string, content: string | Uint8Array) {
  // Retry on the (vanishingly rare) random-name collision; never follow or
  // clobber an existing entry.
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const tempPath = randomTempPath(finalPath);
    let fd: number;
    try {
      fd = openSync(tempPath, EXCL_CREATE_FLAGS, 0o600);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "EEXIST") continue;
      throw error;
    }
    try {
      writeAllSync(fd, content);
      // KODE-7: flush the file's data+metadata to stable storage BEFORE close,
      // so a power loss after the subsequent rename cannot resurrect a
      // zero-length or partially-written file. Without this, write()+rename()
      // only orders the operations in the page cache — the bytes may still be
      // in flight when the crash hits, leaving an empty manifest/signature/tar.
      fsyncSync(fd);
    } finally {
      closeSync(fd);
    }
    return tempPath;
  }
  throw new Error(`failed to create exclusive temp file for ${finalPath}`);
}

export function promoteTempFileExclusive(tempPath: string, finalPath: string) {
  linkSync(tempPath, finalPath);
  removeIfExists(tempPath);
  fsyncDir(finalPath);
}

function snapshotError(error: unknown): string {
  const message = error instanceof Error ? error.message : String(error);
  return message.replace(/[\r\n]+/g, " ").slice(0, 500);
}

