export type RestoreWorkspaceSnapshotResult = {
  ok: boolean;
  targetWorkspaceRoot?: string;
  companyCount?: number;
  accessRecoveryPlanPath?: string;
  nextStep?: "bootstrap-owner-then-reinvite";
  appliedRules: string[];
  errors: string[];
};

export type WorkspaceSnapshotManifestV1 = {
  version: 1;
  createdAt: string;
  provenance: ReleaseProvenance;
  credentialPolicy: "omit-all-auth-and-operational-credentials-v1";
  workspaceManifest: ManifestFile;
  accessPlan: ManifestFile;
  /** Non-credential operating knowledge is portable; auth state remains omitted. */
  companyKnowledge?: ManifestFile;
  /** Source-backed legal ownership history is portable; credentials remain omitted. */
  ownershipGraph?: ManifestFile;
  /** Canonical party provenance and immutable corporate evidence; no auth data. */
  workspaceRegistry?: ManifestFile;
  /** Append-only, workspace-only intercompany evidence lifecycle; no credentials. */
  intercompanyDispositions?: ManifestFile;
  workspaceInbox?: ManifestFile;
  companies: Array<{
    slug: string;
    name: string;
    archived: boolean;
    backup: ManifestFile;
  }>;
};

export type ReleaseProvenance = {
  product: ReturnType<typeof getBuildIdentity>;
  schema: {
    version: number;
    baselineChecksum: string;
  };
  rules: {
    digest: string;
  };
};

export type WorkspaceManifest = {
  version: typeof MANIFEST_VERSION;
  companies: WorkspaceCompanyEntry[];
};

export type WorkspaceCompanyEntry = {
  /** Filesystem-safe identifier; the subdirectory name under the workspace. */
  slug: string;
  /** Human-readable display name. */
  name: string;
  /** ISO-8601 timestamp of when the entry was first registered. */
  createdAt: string;
  /** Soft-deletion flag; archived companies stay on disk. */
  archived: boolean;
};

type SnapshotAccessPlan = {
  version: 1;
  recovery: "bootstrap-owner-then-reinvite";
  users: Array<{
    name: string;
    email: string;
    workspaceRole: WorkspaceRole;
    memberships: Array<{ companySlug: string; role: CompanyRole }>;
  }>;
};

export type RestoreSystemBackupInput = {
  backupDir: string;
  targetCompanyRoot: string;
  verificationKeyPath?: string;
  publicKeyPath?: string;
  // Optional out-of-band public-key hint. When set, an ed25519 public key
  // resolved from inside the backup must match it or restore fails closed
  // (issue #132). Backward-compatible: omitted -> previous behaviour.
  publicKeyHint?: string;
  // KODE-8: explicit opt-in to overwrite a target directory that already exists
  // and is NOT empty (but holds no ledger db). Without it, restore refuses to
  // recursively delete a non-empty ledger-less directory — it might be the
  // user's own files, pointed at by mistake. An empty or non-existent target is
  // always fine and needs no flag.
  allowNonEmptyTarget?: boolean;
  /** Internal portable-workspace mode: no HMAC secret ships; Ed25519 must verify. */
  credentialFreePortableMode?: boolean;
  createdBy?: string;
  createdByProgram?: string;
};

export type RestoreSystemBackupResult = {
  ok: boolean;
  backupId?: string;
  restoredAt?: string;
  targetCompanyRoot?: string;
  restoredDbPath?: string;
  restoredFiles?: {
    documentsOriginals: number;
    invoicesIssued: number;
    config: number;
  };
  appliedRules: string[];
  errors: string[];
};

