export function resolveWorkspaceRoot(raw: string): string {
  if (raw.split(/[\\/]+/).includes("..")) {
    throw new Error("workspace root must not contain parent-directory ('..') segments");
  }
  const resolved = resolve(raw);
  if (!isAbsolute(resolved) || resolved.split(sep).includes("..")) {
    throw new Error("workspace root resolved to an unsafe path");
  }
  return resolved;
}

export function readCurrentGroupManifest(db: Database, workspaceRoot: string): { manifest: GroupManifest; manifestHash: string; eventId: number } | null {
  const row = readAndVerifyGroupManifestEvents(db).at(-1) ?? null;
  if (!row) return null;
  const manifest = parseGroupManifest(JSON.parse(row.canonical_manifest), listWorkspaceCompanies(workspaceRoot).map((company) => company.slug));
  return { manifest, manifestHash: row.manifest_hash, eventId: row.id };
}

function readAndVerifyGroupManifestEvents(db: Database): GroupManifestEvent[] {
  const rows = db.query("SELECT id, manifest_hash, previous_hash, canonical_manifest, actor, created_at FROM rm_group_manifest_events ORDER BY id").all() as GroupManifestEvent[];
  let previous: string | null = null;
  for (const row of rows) {
    const expected = chainHash(previous, row.canonical_manifest, row);
    if (row.id < 1 || row.previous_hash !== previous || expected !== row.manifest_hash) {
      throw new Error("group manifest hash-chain is invalid");
    }
    previous = row.manifest_hash;
  }
  return rows;
}

export function parseGroupManifest(input: unknown, registeredSlugs: readonly string[]): GroupManifest {
  const root = record(input, "group manifest");
  if (root.version !== GROUP_MANIFEST_VERSION) throw new Error(`group manifest version must be ${GROUP_MANIFEST_VERSION}`);
  if (!Array.isArray(root.groups) || root.groups.length === 0 || root.groups.length > MAX_GROUPS) throw new Error(`group manifest must contain 1 through ${MAX_GROUPS} groups`);
  const registered = new Set(registeredSlugs);
  const groups = root.groups.map((raw, index): GroupDefinition => {
    const group = record(raw, `groups[${index}]`);
    const id = identifier(group.id, `groups[${index}].id`);
    const name = safeName(group.name, `groups[${index}].name`);
    if (!Array.isArray(group.memberships) || group.memberships.length === 0 || group.memberships.length > MAX_ROWS_PER_GROUP) throw new Error(`groups[${index}].memberships must contain 1 through ${MAX_ROWS_PER_GROUP} rows`);
    const memberships = group.memberships.map((entry, membershipIndex): GroupMembership => {
      const row = record(entry, `groups[${index}].memberships[${membershipIndex}]`);
      const companySlug = string(row.companySlug, `groups[${index}].memberships[${membershipIndex}].companySlug`);
      if (!isValidSlug(companySlug) || !registered.has(companySlug)) throw new Error("group membership references an unregistered company");
      return { id: identifier(row.id, `groups[${index}].memberships[${membershipIndex}].id`), companySlug, ...interval(row, `groups[${index}].memberships[${membershipIndex}]`) };
    });
    unique(memberships.map((membership) => membership.id), `groups[${index}].membership ids`);
    for (let left = 0; left < memberships.length; left += 1) for (let right = left + 1; right < memberships.length; right += 1) {
      if (memberships[left]!.companySlug === memberships[right]!.companySlug && overlaps(memberships[left]!, memberships[right]!)) throw new Error("a company may have only one active membership in a group at a time");
    }
    if (!Array.isArray(group.ownership) || group.ownership.length > MAX_ROWS_PER_GROUP) throw new Error(`groups[${index}].ownership must contain at most ${MAX_ROWS_PER_GROUP} rows`);
    const ownership = group.ownership.map((entry, ownershipIndex): GroupOwnership => {
      const row = record(entry, `groups[${index}].ownership[${ownershipIndex}]`);
      const parentCompanySlug = string(row.parentCompanySlug, `groups[${index}].ownership[${ownershipIndex}].parentCompanySlug`);
      const childCompanySlug = string(row.childCompanySlug, `groups[${index}].ownership[${ownershipIndex}].childCompanySlug`);
      if (!isValidSlug(parentCompanySlug) || !isValidSlug(childCompanySlug) || !registered.has(parentCompanySlug) || !registered.has(childCompanySlug)) throw new Error("group ownership references an unregistered company");
      if (parentCompanySlug === childCompanySlug) throw new Error("group ownership cannot be self-referential");
      if (!Number.isInteger(row.basisPoints) || (row.basisPoints as number) < 1 || (row.basisPoints as number) > 10000) throw new Error("group ownership basisPoints must be an integer from 1 through 10000");
      const effective = interval(row, `groups[${index}].ownership[${ownershipIndex}]`);
      const parentCovered = memberships.some((membership) => membership.companySlug === parentCompanySlug && covers(membership, effective));
      const childCovered = memberships.some((membership) => membership.companySlug === childCompanySlug && covers(membership, effective));
      if (!parentCovered || !childCovered) throw new Error("group ownership must be fully covered by active memberships");
      return { id: identifier(row.id, `groups[${index}].ownership[${ownershipIndex}].id`), parentCompanySlug, childCompanySlug, basisPoints: row.basisPoints as number, evidenceRefs: evidenceRefs(row.evidenceRefs, `groups[${index}].ownership[${ownershipIndex}].evidenceRefs`), ...effective };
    });
    unique(ownership.map((edge) => edge.id), `groups[${index}].ownership ids`);
    assertOwnershipIntervalsAndTotals(ownership);
    assertNoEffectiveCycles(ownership);
    return { id, name, memberships, ownership };
  });
  unique(groups.map((group) => group.id), "group ids");
  const manifest = { version: GROUP_MANIFEST_VERSION, groups };
  if (Buffer.byteLength(canonicalizeGroupManifestUnchecked(manifest), "utf8") > MAX_MANIFEST_BYTES) throw new Error(`group manifest exceeds ${MAX_MANIFEST_BYTES} bytes`);
  return manifest;
}

export function listWorkspaceCompanies(workspaceRoot: string): WorkspaceCompanyEntry[] {
  return loadWorkspaceManifest(workspaceRoot).companies;
}

export function parseIntercompanyMapping(input: unknown, groupManifest: GroupManifest): IntercompanyMapping {
  if (!input || typeof input !== "object" || Array.isArray(input)) throw new Error("intercompany mapping must be an object");
  const row = input as Record<string, unknown>;
  const id = identifier(row.id, "mapping.id");
  const groupId = identifier(row.groupId, "mapping.groupId");
  const group = groupManifest.groups.find((candidate) => candidate.id === groupId);
  if (!group) throw new Error("intercompany mapping references an unknown group");
  const leftCompanySlug = requiredString(row.leftCompanySlug, "mapping.leftCompanySlug");
  const rightCompanySlug = requiredString(row.rightCompanySlug, "mapping.rightCompanySlug");
  if (leftCompanySlug === rightCompanySlug) throw new Error("intercompany mapping must bind two distinct companies");
  const validFrom = date(row.validFrom, "mapping.validFrom");
  const validToExclusive = row.validToExclusive == null ? undefined : date(row.validToExclusive, "mapping.validToExclusive");
  if (validToExclusive && validToExclusive <= validFrom) throw new Error("intercompany mapping must have a non-empty half-open interval");
  const effective = { validFrom, ...(validToExclusive ? { validToExclusive } : {}) };
  for (const slug of [leftCompanySlug, rightCompanySlug]) {
    if (!group.memberships.some((membership) => membership.companySlug === slug && covers(membership, effective))) {
      throw new Error("intercompany mapping must be fully covered by active group memberships");
    }
  }
  const leftPosition = requiredString(row.leftPosition, "mapping.leftPosition") as IntercompanyPosition;
  const rightPosition = requiredString(row.rightPosition, "mapping.rightPosition") as IntercompanyPosition;
  if (!(["receivable", "payable"] as const).includes(leftPosition) || !(["receivable", "payable"] as const).includes(rightPosition) || leftPosition === rightPosition) {
    throw new Error("intercompany mapping positions must be complementary receivable and payable");
  }
  return {
    id,
    groupId,
    leftCompanySlug,
    rightCompanySlug,
    leftAccountNos: stringList(row.leftAccountNos, "mapping.leftAccountNos", MAX_ACCOUNTS, ACCOUNT),
    rightAccountNos: stringList(row.rightAccountNos, "mapping.rightAccountNos", MAX_ACCOUNTS, ACCOUNT),
    leftPosition,
    rightPosition,
    evidenceRefs: stringList(row.evidenceRefs, "mapping.evidenceRefs", MAX_EVIDENCE_REFS),
    ...effective,
  };
}

function identifier(value: unknown, label: string): string {
  const result = requiredString(value, label);
  if (!IDENTIFIER.test(result)) throw new Error(`${label} must be a lowercase stable identifier`);
  return result;
}

function requiredString(value: unknown, label: string): string {
  if (typeof value !== "string" || !value.trim()) throw new Error(`${label} is required`);
  return value.trim().normalize("NFC");
}

function date(value: unknown, label: string): string {
  try { return parseGroupAsOf(value); }
  catch { throw new Error(`${label} must be a real ISO date`); }
}

function covers(container: EffectiveInterval, target: EffectiveInterval): boolean {
  return container.validFrom <= target.validFrom &&
    (container.validToExclusive == null || (target.validToExclusive != null && container.validToExclusive >= target.validToExclusive));
}

function stringList(value: unknown, label: string, max: number, pattern?: RegExp): string[] {
  if (!Array.isArray(value) || value.length === 0 || value.length > max) throw new Error(`${label} must contain 1 through ${max} values`);
  const rows = value.map((entry, index) => {
    const result = requiredString(entry, `${label}[${index}]`);
    if (result.length > 256 || (pattern && !pattern.test(result))) throw new Error(`${label}[${index}] is invalid`);
    return result;
  });
  if (new Set(rows).size !== rows.length) throw new Error(`${label} must be unique`);
  return rows.sort(compare);
}

export function companyRootForSlug(workspaceRoot: string, slug: string): string {
  assertValidSlug(slug);
  return join(workspaceRoot, slug);
}

function assertValidSlug(slug: string): void {
  if (!isValidSlug(slug)) {
    throw new Error(
      `invalid company slug '${slug}': use lowercase letters, digits and dashes`,
    );
  }
}

export function proposeIntercompanyMapping(db: Database, workspaceRoot: string, input: unknown, audit: ResolveActorInput): { mappingId: string; mappingHash: string; status: "proposed" } {
  return db.transaction(() => {
    const group = readCurrentGroupManifest(db, workspaceRoot);
    if (!group) throw new Error("group structure must be configured before intercompany mappings");
    const mapping = parseIntercompanyMapping(input, group.manifest);
    const state = currentEvents(readEvents(db)).get(mapping.id);
    if (state && state.event_type !== "revoked") throw new Error("intercompany mapping id already has an active lifecycle");
    const event = appendEvent(db, "proposed", mapping, audit);
    return { mappingId: mapping.id, mappingHash: event.mapping_hash, status: "proposed" as const };
  }).immediate();
}

function currentEvents(events: readonly MappingEvent[]): Map<string, MappingEvent> {
  const current = new Map<string, MappingEvent>();
  for (const event of events) current.set(event.mapping_id, event);
  return current;
}

function readEvents(db: Database): MappingEvent[] {
  const rows = db.query("SELECT id,mapping_id,event_type,mapping_hash,canonical_mapping,previous_hash,event_hash,actor,created_at FROM rm_intercompany_mapping_events ORDER BY id").all() as MappingEvent[];
  let previous: string | null = null;
  for (const row of rows) {
    if (row.previous_hash !== previous || row.event_hash !== eventHash(previous, row)) throw new Error("intercompany mapping event hash-chain is invalid");
    previous = row.event_hash;
  }
  return rows;
}

function appendEvent(db: Database, eventType: MappingEvent["event_type"], mapping: IntercompanyMapping, audit: ResolveActorInput): MappingEvent {
  const rows = readEvents(db);
  const previous = rows.at(-1)?.event_hash ?? null;
  const canonical = canonicalizeIntercompanyMapping(mapping);
  const actor = resolveActor(audit).auditActor;
  const event = { id: (rows.at(-1)?.id ?? 0) + 1, mapping_id: mapping.id, event_type: eventType, mapping_hash: sha(canonical), canonical_mapping: canonical, previous_hash: previous, actor, created_at: new Date().toISOString() };
  const complete: MappingEvent = { ...event, event_hash: eventHash(previous, event) };
  db.query("INSERT INTO rm_intercompany_mapping_events (id,mapping_id,event_type,mapping_hash,canonical_mapping,previous_hash,event_hash,actor,created_at) VALUES (?,?,?,?,?,?,?,?,?)").run(complete.id, complete.mapping_id, complete.event_type, complete.mapping_hash, complete.canonical_mapping, complete.previous_hash, complete.event_hash, complete.actor, complete.created_at);
  insertWorkspaceAudit(db, { ...audit, eventType: `intercompany_mapping_${eventType}`, entityType: "intercompany_mapping", entityId: mapping.id });
  return complete;
}

typeDeclarations.source:
export type IntercompanyMapping = EffectiveInterval & {
  id: string;
  groupId: string;
  leftCompanySlug: string;
  rightCompanySlug: string;
  leftAccountNos: string[];
  rightAccountNos: string[];
  leftPosition: IntercompanyPosition;
  rightPosition: IntercompanyPosition;
  evidenceRefs: string[];
};

export type GroupDefinition = {
  id: string;
  name: string;
  memberships: GroupMembership[];
  ownership: GroupOwnership[];
};

export type GroupOwnership = EffectiveInterval & {
  id: string;
  parentCompanySlug: string;
  childCompanySlug: string;
  basisPoints: number;
  /** Immutable external evidence identifiers; no accounting semantics here. */
  evidenceRefs: string[];
};

export type WorkspaceCompanyEntry = {
  /** Filesystem-safe identifier; the subdirectory name under the workspace. */
  slug: string;
  /** Human-readable display name. */
  name: string;
  /** ISO-8601 timestamp of when the entry was first registered. */
  createdAt: string;
  /** Soft-deletion flag; archived companies stay on disk. */
  archived: boolean;
};

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

type MappingEvent = {
  id: number;
  mapping_id: string;
  event_type: "proposed" | "approved" | "revoked";
  mapping_hash: string;
  canonical_mapping: string;
  previous_hash: string | null;
  event_hash: string;
  actor: string;
  created_at: string;
};

