export type IntercompanyMapping = EffectiveInterval & {
  id: string;
  groupId: string;
  leftCompanySlug: string;
  rightCompanySlug: string;
  leftAccountNos: string[];
  rightAccountNos: string[];
  leftPosition: IntercompanyPosition;
  rightPosition: IntercompanyPosition;
  evidenceRefs: string[];
};

type MappingEvent = {
  id: number;
  mapping_id: string;
  event_type: "proposed" | "approved" | "revoked";
  mapping_hash: string;
  canonical_mapping: string;
  previous_hash: string | null;
  event_hash: string;
  actor: string;
  created_at: string;
};

export type GroupDefinition = {
  id: string;
  name: string;
  memberships: GroupMembership[];
  ownership: GroupOwnership[];
};

export type GroupOwnership = EffectiveInterval & {
  id: string;
  parentCompanySlug: string;
  childCompanySlug: string;
  basisPoints: number;
  /** Immutable external evidence identifiers; no accounting semantics here. */
  evidenceRefs: string[];
};

export type WorkspaceCompanyEntry = {
  /** Filesystem-safe identifier; the subdirectory name under the workspace. */
  slug: string;
  /** Human-readable display name. */
  name: string;
  /** ISO-8601 timestamp of when the entry was first registered. */
  createdAt: string;
  /** Soft-deletion flag; archived companies stay on disk. */
  archived: boolean;
};

export type WorkspaceManifest = {
  version: typeof MANIFEST_VERSION;
  companies: WorkspaceCompanyEntry[];
};

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

