export type BalanceEliminationPayload = {
  version: 1;
  id: string;
  kind: "intercompany-balance";
  groupId: string;
  mappingId: string;
  mappingHash: string;
  asOf: string;
  currency: string;
  amountOre: string;
  left: { companySlug: string; accountNos: string[]; selectionHash: string; ledgerHeadHash: string | null; entryCount: number; creditOre: string };
  right: { companySlug: string; accountNos: string[]; selectionHash: string; ledgerHeadHash: string | null; entryCount: number; debitOre: string };
  evidenceRefs: string[];
};

type EliminationEvent = {
  id: number;
  elimination_id: string;
  event_type: "proposed" | "approved" | "rejected" | "applied" | "reversed";
  payload_hash: string;
  canonical_payload: string;
  previous_hash: string | null;
  event_hash: string;
  actor: string;
  created_at: string;
};

export type WorkspaceCompanyEntry = {
  /** Filesystem-safe identifier; the subdirectory name under the workspace. */
  slug: string;
  /** Human-readable display name. */
  name: string;
  /** ISO-8601 timestamp of when the entry was first registered. */
  createdAt: string;
  /** Soft-deletion flag; archived companies stay on disk. */
  archived: boolean;
};

export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type ActorContext = {
  createdBy: string;
  createdByProgram: string;
  auditActor: string;
};

