export type GroupDefinition = {
  id: string;
  name: string;
  memberships: GroupMembership[];
  ownership: GroupOwnership[];
};

export type GroupOwnership = EffectiveInterval & {
  id: string;
  parentCompanySlug: string;
  childCompanySlug: string;
  basisPoints: number;
  /** Immutable external evidence identifiers; no accounting semantics here. */
  evidenceRefs: string[];
};

export type WorkspaceCompanyEntry = {
  /** Filesystem-safe identifier; the subdirectory name under the workspace. */
  slug: string;
  /** Human-readable display name. */
  name: string;
  /** ISO-8601 timestamp of when the entry was first registered. */
  createdAt: string;
  /** Soft-deletion flag; archived companies stay on disk. */
  archived: boolean;
};

