export function planBookkeepingBatch(db: Database, input: BookkeepingBatchScope): BookkeepingBatchPlan {
  const s = scope(db, input);
  const banks = db.query(`SELECT bt.id
    FROM bank_transactions bt
    WHERE bt.transaction_date BETWEEN ? AND ?
      AND NOT EXISTS (
        SELECT 1
        FROM bank_journal_reconciliations reconciliation
        WHERE reconciliation.bank_transaction_id = bt.id
      )
    ORDER BY bt.id`).all(s.bankFrom, s.bankTo) as Array<{ id: number }>;
  const pairs = banks.flatMap((bank) => { const suggested = suggestBankMatches(db, { bankTransactionId: bank.id, max: 2 }); const match = suggested.ok ? suggested.rows[0]?.suggestions[0] : undefined; return match?.documentId ? [{ bankId: bank.id, documentId: match.documentId, suggestion: match }] : []; });
  const perDocument = new Map<number, number>(); for (const pair of pairs) perDocument.set(pair.documentId, (perDocument.get(pair.documentId) ?? 0) + 1);
  const items: BookkeepingBatchItem[] = [];
  for (const pair of pairs) {
    const evidence = loadPurchaseEvidence(db, s.companyId, pair.documentId, pair.bankId); if (!evidence) continue;
    const rule = evaluatePostingRules(db, evidence.context, { at: evidence.document.invoice_date ?? s.accountingTo });
    const unambiguous = perDocument.get(pair.documentId) === 1;
    const vat = inspectPurchaseVatPreflight(db, pair.documentId);
    const ready = unambiguous && rule.decision === "proposed" && typeof rule.outcome.account === "string" && vat?.ok === true;
    const partyDefaults=partyDefaultSuggestion(db,pair.documentId);
    items.push({ actionKey: `purchase:${pair.documentId}:bank:${pair.bankId}`, evidenceHash: evidenceHash(evidence), partition: ready ? "ready" : "humanDecision", documentId: pair.documentId, bankTransactionId: pair.bankId, ruleApplication: rule.decision === "proposed" ? { ruleVersionId: rule.ruleVersionId, payloadHash: rule.payloadHash } : undefined, detail: { suggestion: pair.suggestion, unambiguous, vatReady: vat?.ok === true, partyDefaults: partyDefaults ? { ...partyDefaults, advisoryOnly:true, neverOverrides:{postingRule:true,vatEvidence:true} } : null, rule: rule.decision === "proposed" ? { ruleVersionId: rule.ruleVersionId, payloadHash: rule.payloadHash, outcome: rule.outcome } : { reasons: rule.reasons } } });
  }
  for (const bank of banks) if (!pairs.some(pair => pair.bankId === bank.id)) items.push({ actionKey: `bank:${bank.id}`, evidenceHash: hash({ bankId: bank.id }), partition: "missingDocument", bankTransactionId: bank.id, detail: {} });
  items.sort((a, b) => a.actionKey.localeCompare(b.actionKey));
  const draft = { ...s, items };
  const identities = sourceIdentities(db, draft);
  const candidateSetHash = hash(identities.candidateUniverse);
  return { ...draft, sourceIdentities: identities, candidateSetHash, planHash: hash({ ...draft, sourceIdentities: identities, candidateSetHash }) };
}

export function suggestBankMatches(db: Database, input: SuggestBankMatchesInput = {}): SuggestBankMatchesResult {
  const errors: string[] = [];
  if (input.bankTransactionId !== undefined && (!Number.isInteger(input.bankTransactionId) || input.bankTransactionId <= 0)) {
    errors.push("bankTransactionId must be a positive integer when present");
  }
  const max = input.max ?? 5;
  if (!Number.isInteger(max) || max <= 0) errors.push("max must be a positive integer when present");
  if (errors.length > 0) return { ok: false, count: 0, rows: [], errors };

  const bankRows = unmatchedBankTransactions(db, input.bankTransactionId);
  if (input.bankTransactionId !== undefined && bankRows.length === 0) {
    return { ok: false, count: 0, rows: [], errors: [`unmatched bank transaction ${input.bankTransactionId} does not exist`] };
  }

  const invoiceDocs = openIssuedInvoices(db);
  const purchaseDocs = openPurchaseDocuments(db);
  // ===== BANK CLUSTER (#182) =====
  const creditNoteDocs = creditNoteDocuments(db);
  const allPurchaseDocs = allPurchaseDocuments(db);
  // ===== END BANK CLUSTER (#182) =====

  const rows: BankMatchSuggestionRow[] = bankRows.map((bank) => {
    const suggestions = [
      ...invoiceDocs.map((doc) => invoiceSuggestion(db, bank, doc)).filter((value): value is BankMatchSuggestion => Boolean(value)),
      ...purchaseDocs.map((doc) => purchaseSuggestion(bank, doc)).filter((value): value is BankMatchSuggestion => Boolean(value)),
      // ===== BANK CLUSTER (#182) =====
      ...creditNoteDocs.map((doc) => creditNoteRefundSuggestion(db, bank, doc)).filter((value): value is BankMatchSuggestion => Boolean(value)),
      ...allPurchaseDocs.map((doc) => supplierCreditRefundSuggestion(bank, doc)).filter((value): value is BankMatchSuggestion => Boolean(value)),
      // ===== END BANK CLUSTER (#182) =====
    ]
      .sort((a, b) => b.confidence - a.confidence || a.documentId - b.documentId)
      .slice(0, max);

    // EJER-7: only when there is no safe suggestion do we look for the
    // exact-amount near-miss the exceptions queue would name — so the two
    // surfaces never contradict each other.
    const unsafeMatchReason =
      suggestions.length === 0 ? amountOnlyNearMiss(db, Number(bank.amount)) : null;

    return {
      bankTransactionId: bank.id,
      date: bank.transaction_date,
      text: bank.text,
      amount: roundDkk(Number(bank.amount)),
      currency: bank.currency,
      reference: bank.reference,
      suggestions,
      unsafeMatchReason,
    };
  });

  return { ok: true, count: rows.length, rows, errors: [] };
}

function loadPurchaseEvidence(db: Database, companyId: number, documentId: number, bankTransactionId: number): PurchaseEvidence | null {
  const document = db.query("SELECT id,invoice_date,sender_name,sender_vat_cvr,supplier_country_code,document_type,currency,amount_inc_vat,vat_amount,sha256_hash FROM documents WHERE id=?").get(documentId) as PurchaseEvidence["document"] | null;
  const bank = db.query("SELECT id,transaction_date,amount,currency,transaction_hash,text FROM bank_transactions WHERE id=?").get(bankTransactionId) as PurchaseEvidence["bank"] | null;
  if (!document || !bank) return null;
  return { document, bank, context: { company: companyId, documentId, supplierIdentity: document.sender_name ?? undefined, supplierCountry: document.supplier_country_code ?? undefined, supplierVat: document.sender_vat_cvr ?? undefined, documentType: document.document_type, currency: document.currency, amount: Number(document.amount_inc_vat ?? 0), vatAmount: Number(document.vat_amount ?? 0) } };
}

export function evaluatePostingRules(db: Database, context: PostingRuleContext, options: { at?: string } = {}) {
  const at = options.at ?? new Date().toISOString();
  const extracted = context.documentId ? inspectDocumentInvoiceExtraction(db, context.documentId) : null;
  // No extraction is normal for documents that were not routed through that
  // optional processor.  Only an extraction that actually exists and needs
  // resolution is contradictory evidence; absence is never a contradiction.
  const evidence = ["changedBuyer", "changedSupplier", "changedVat", "changedCurrency", "unusualAmount", "contradictoryEvidence"].filter((k) => context[k as keyof PostingRuleContext] === true || (k === "contradictoryEvidence" && extracted !== null && extracted.status !== "completed"));
  const rows = db.query("SELECT * FROM posting_rule_versions WHERE company_id=? AND effective_from<=? AND (effective_to IS NULL OR effective_to>=?) ORDER BY rule_id ASC,version ASC").all(context.company, at, at) as any[];
  const explanations = rows.map((row) => { const state = stateAt(db, row.id, at); const reasons = state === "approved" ? mismatch(JSON.parse(row.conditions_json), context) : [`state is ${state ?? "not yet effective"}`]; return { ruleId: row.rule_id, version: row.version, payloadHash: row.payload_hash, state, matched: reasons.length === 0, reasons }; });
  const matches = explanations.filter((x) => x.matched);
  if (evidence.length || matches.length !== 1) return { decision: "human_decision" as const, outcome: undefined, matched: matches, explanations, reasons: evidence.length ? evidence.map((x) => `${x} requires human decision`) : [matches.length === 0 ? "no approved rule matched" : "multiple approved rules matched"] };
  const match = matches[0]!; const row = rows.find((x) => x.rule_id === match.ruleId && x.version === match.version)!;
  return { decision: "proposed" as const, outcome: JSON.parse(row.outcome_json) as PostingRuleOutcome, matched: matches, explanations, reasons: [] as string[], ruleVersionId: row.id, payloadHash: row.payload_hash };
}

export function inspectPurchaseVatPreflight(db: Database, documentId: number, options: { clock?: VatValidationClock } = {}): PurchaseVatPreflightInspection {
  const extracted = inspectDocumentInvoiceExtraction(db, documentId);
  if (extracted && extracted.status !== "completed") return { ok: false, documentId, classification: "CONFLICT", cached: false, evidenceExpiresAt: null, wouldCallProvider: false, errors: ["invoice extraction evidence requires human resolution before VAT preflight"] };
  const now = (options.clock ?? systemVatValidationClock).now().toISOString();
  const facts = classification(supplier(db, documentId));
  const cached = freshEvidence(db, documentId, now, facts.country, facts.identifier);
  if (facts.classification === "DK" || facts.classification === "NON_EU") return { ok: true, documentId, classification: facts.classification, cached: !!cached, evidenceExpiresAt: cached?.evidence_expires_at ?? null, wouldCallProvider: false, errors: [] };
  if (facts.classification === "CONFLICT") return { ok: false, documentId, classification: "CONFLICT", cached: false, evidenceExpiresAt: null, wouldCallProvider: false, errors: ["documented supplier evidence is incomplete or conflicting; human resolution is required"] };
  return { ok: !!cached, documentId, classification: "EU", cached: !!cached, evidenceExpiresAt: cached?.evidence_expires_at ?? null, wouldCallProvider: !cached, errors: cached ? [] : ["fresh EU VAT validation evidence is required"] };
}

function partyDefaultSuggestion(db: Database, documentId: number) {
  const row=db.query("SELECT party_id,party_role,party_snapshot_json FROM current_document_party_links WHERE document_id=? ORDER BY CASE party_role WHEN 'supplier' THEN 0 WHEN 'vendor' THEN 1 ELSE 2 END,id DESC LIMIT 1").get(documentId) as {party_id:string;party_role:string;party_snapshot_json:string}|null;
  if(!row)return null;
  try { const snapshot=JSON.parse(row.party_snapshot_json) as {roles?:Array<{role?:string;defaults?:unknown}>}; const role=snapshot.roles?.find(item=>item.role===row.party_role); const defaults=role?.defaults; if(!defaults||typeof defaults!=="object"||Array.isArray(defaults))return null; const d=defaults as Record<string,unknown>; return {partyId:row.party_id,role:row.party_role,account:typeof d.account==="string"?d.account:null,vat:typeof d.vat==="string"?d.vat:null,currency:typeof d.currency==="string"?d.currency:null}; } catch { return null; }
}

function sourceIdentities(db: Database, plan: Omit<BookkeepingBatchPlan, "sourceIdentities" | "candidateSetHash" | "planHash">, ignoreRunId?: number) {
  const ready = plan.items.filter((item) => item.partition === "ready").map((item) => {
    // A receipt is the immutable effect of this exact reviewed revision. Its
    // own rule/VAT/journal evidence must not make a resumable run stale.
    const prior = ignoreRunId && db.query("SELECT 1 FROM bookkeeping_batch_item_receipts WHERE run_id=? AND action_key=?").get(ignoreRunId, item.actionKey);
    const planned = ((plan as BookkeepingBatchPlan).sourceIdentities as any)?.ready?.find((row: any) => row.actionKey === item.actionKey);
    if (prior && planned) return planned;
    const evidence = item.documentId && item.bankTransactionId ? loadPurchaseEvidence(db, plan.companyId, item.documentId, item.bankTransactionId) : null;
    const rule = evidence ? evaluatePostingRules(db, evidence.context, { at: evidence.document.invoice_date ?? plan.accountingTo }) : null;
    const vat = item.documentId ? inspectPurchaseVatPreflight(db, item.documentId) : null;
    const vatEvent = item.documentId ? db.query(`SELECT id,event_type,supplier_country_code,supplier_identifier,classification,provider_status,evidence_expires_at,detail_json,created_at
      FROM vat_validation_events WHERE document_id=? AND event_type='preflight_passed' ORDER BY id DESC LIMIT 1`).get(item.documentId) : null;
    const reconciliation = item.bankTransactionId ? db.query("SELECT bank_transaction_id FROM bank_journal_reconciliations WHERE bank_transaction_id=? LIMIT 1").get(item.bankTransactionId) : null;
    const requestedDimensions=rule?.decision==="proposed" ? Object.entries(rule.outcome.dimensions??{}).sort(([a],[b])=>a.localeCompare(b)).map(([dimensionId,memberId])=>({dimensionId,memberId,current:db.query("SELECT status FROM current_accounting_dimension_members WHERE dimension_id=? AND member_id=?").get(dimensionId,memberId)??null})) : [];
    return { actionKey: item.actionKey, evidenceHash: evidence ? evidenceHash(evidence) : null, reconciliation: reconciliation ? "reconciled" : "unreconciled", rule: rule?.decision === "proposed" ? { ruleVersionId: rule.ruleVersionId, payloadHash: rule.payloadHash, dimensions:requestedDimensions } : { decision: rule?.decision ?? "missing" }, vat: vat ? { ok: vat.ok, classification: vat.classification, evidenceExpiresAt: vat.evidenceExpiresAt, event: vatEvent ? { id: (vatEvent as any).id, hash: hash(vatEvent) } : null } : null };
  });
  // Candidate universe is intentionally broader than executable items.  A new
  // eligible document/bank row must stale a reviewed plan instead of silently
  // being omitted on apply. Reconciliations and in-scope journal links are
  // included because they change both eligibility and the legal evidence.
  const banks = db.query(`SELECT bt.id,bt.transaction_date,bt.amount,bt.currency,bt.transaction_hash,bt.text,
    CASE WHEN EXISTS(SELECT 1 FROM bank_journal_reconciliations r WHERE r.bank_transaction_id=bt.id)
      AND NOT EXISTS(SELECT 1 FROM bookkeeping_batch_applied_links l WHERE l.run_id=? AND l.bank_transaction_id=bt.id)
      THEN 1 ELSE 0 END AS reconciled
    FROM bank_transactions bt WHERE bt.transaction_date BETWEEN ? AND ? ORDER BY bt.id`).all(ignoreRunId ?? -1, plan.bankFrom, plan.bankTo);
  // Mirror `openPurchaseDocuments` exactly. It deliberately has no invoice
  // date filter: an undated or older still-open DKK purchase can become the
  // best suggestion for an in-scope bank line.
  const documents = db.query(`SELECT d.id,d.sha256_hash,d.invoice_date,d.document_type,d.currency,d.amount_inc_vat,d.vat_amount,
    d.sender_name,d.sender_vat_cvr,d.supplier_country_code,
    (SELECT e.enriched_metadata_sha256 FROM document_metadata_enrichments e WHERE e.document_id=d.id) AS enrichments,
    (SELECT c.context_sha256 FROM document_company_contexts c WHERE c.document_id=d.id) AS contexts
    FROM documents d LEFT JOIN journal_entries je ON je.document_id=d.id AND je.status='posted'
    WHERE d.document_type='purchase_sale' AND d.currency='DKK'
      AND (je.id IS NULL OR EXISTS(SELECT 1 FROM bookkeeping_batch_applied_links l WHERE l.run_id=? AND l.document_id=d.id AND l.journal_entry_id=je.id)) ORDER BY d.id`).all(ignoreRunId ?? -1);
  const ledger = db.query(`SELECT id,entry_hash,previous_hash,transaction_date,source_bank_transaction_id
    FROM journal_entries WHERE transaction_date BETWEEN ? AND ? OR source_bank_transaction_id IN
      (SELECT id FROM bank_transactions WHERE transaction_date BETWEEN ? AND ?) ORDER BY id`).all(plan.accountingFrom, plan.accountingTo, plan.bankFrom, plan.bankTo)
    .filter((row: any) => !ignoreRunId || !db.query("SELECT 1 FROM bookkeeping_batch_applied_links WHERE run_id=? AND journal_entry_id=?").get(ignoreRunId,row.id));
  return { ready, candidateUniverse: { banks, documents, ledger } };
}

export function createBookkeepingBatchRun(db: Database, input: BookkeepingBatchPlan & BatchActor & { principal?: BatchPrincipal; runKey?: string }) {
  if (!validActor(input.actor) || !input.runKey?.trim()) throw new Error("actor and runKey are required");
  const runKey = input.runKey;
  const plan = { companyId: input.companyId, accountingFrom: input.accountingFrom, accountingTo: input.accountingTo, bankFrom: input.bankFrom, bankTo: input.bankTo, items: input.items, sourceIdentities: input.sourceIdentities, candidateSetHash: input.candidateSetHash, planHash: input.planHash };
  const stored = canonical(plan); if (hash({ companyId:plan.companyId, accountingFrom:plan.accountingFrom, accountingTo:plan.accountingTo, bankFrom:plan.bankFrom, bankTo:plan.bankTo, items:plan.items, sourceIdentities:plan.sourceIdentities, candidateSetHash:plan.candidateSetHash }) !== input.planHash) throw new Error("invalid canonical plan JSON or planHash");
  const principal = batchPrincipal(db, input);
  return db.transaction(() => { const old = db.query("SELECT id,plan_hash,plan_json FROM bookkeeping_batch_runs WHERE run_key=?").get(runKey) as any; if (old) { if (old.plan_hash !== input.planHash) throw new Error("runKey already binds another plan"); return { runId: old.id, duplicate: true, plan: JSON.parse(old.plan_json) as BookkeepingBatchPlan }; } const row = db.query("INSERT INTO bookkeeping_batch_runs(run_key,company_id,accounting_from,accounting_to,bank_from,bank_to,plan_hash,plan_json,created_at) VALUES(?,?,?,?,?,?,?,?,?) RETURNING id").get(runKey, input.companyId, input.accountingFrom, input.accountingTo, input.bankFrom, input.bankTo, input.planHash, stored, new Date().toISOString()) as { id: number }; db.query("INSERT INTO bookkeeping_batch_revisions(run_id,revision_hash,candidate_set_hash,plan_json,planner_kind,planner_subject_id,planner_actor,created_at) VALUES(?,?,?,?,?,?,?,?)").run(row.id,input.planHash,input.candidateSetHash,stored,principal.kind,principal.subjectId,input.actor,new Date().toISOString()); event(db, row.id, "planned", input.planHash, input.actor, { candidateSetHash: input.candidateSetHash }); return { runId: row.id, duplicate: false, plan }; }).immediate();
}

function batchPrincipal(db: Database, input: { principal?: BatchPrincipal }): BatchPrincipal {
  const supplied = input.principal;
  if (supplied && ["user", "service-account", "local-trusted"].includes(supplied.kind) && supplied.subjectId.trim()) return supplied;
  // CLI/direct-core compatibility: this is a stable ledger-local subject, not
  // caller supplied actor text. Hosted adapters always provide an authenticated
  // user/service-account principal.
  return { kind: "local-trusted", subjectId: `ledger-company:${selectedCompanyId(db)}` };
}

typeDeclarations.source:
export type SuggestBankMatchesInput = {
  bankTransactionId?: number;
  max?: number;
};

export type SuggestBankMatchesResult = {
  ok: boolean;
  count: number;
  rows: BankMatchSuggestionRow[];
  errors: string[];
};

export type BankMatchSuggestionRow = {
  bankTransactionId: number;
  date: string;
  text: string;
  amount: number;
  currency: string;
  reference: string | null;
  suggestions: BankMatchSuggestion[];
  /**
   * EJER-7: when a row has NO safe (>= 0.5) suggestion but a document's gross
   * amount nonetheless EXACTLY matches the bank line, this names that document
   * and says why the match is not "safe" on its own. Without it, `bank
   * suggest-matches` printed "Ingen sikre forslag" while the exceptions queue —
   * which finds the very same bilag by exact amount (`findCandidateBilag`) —
   * said "passer til bilag DOC-…", a direct self-contradiction. Surfacing the
   * amount-only near-miss here makes the two surfaces tell one story: there IS
   * a candidate, it just lacks the invoice-number / name corroboration an
   * auto-apply would need. Null when no exact-amount candidate exists.
   */
  unsafeMatchReason: string | null;
};

export type BankMatchSuggestion = {
  // ===== BANK CLUSTER (#182) =====
  // issued_invoice        — incoming customer payment -> issued invoice
  // purchase_sale         — outgoing supplier payment -> purchase document
  // credit_note_refund    — outgoing customer refund  -> its credit note
  // supplier_credit_refund — incoming supplier refund -> the purchase it reverses
  kind: "issued_invoice" | "purchase_sale" | "credit_note_refund" | "supplier_credit_refund";
  // ===== END BANK CLUSTER (#182) =====
  documentId: number;
  invoiceNo: string | null;
  supplierName?: string | null;
  customerName?: string | null;
  confidence: number;
  reasons: string[];
};

export type PostingRuleContext = {
  company: number;
  documentId?: number;
  supplierIdentity?: string;
  documentType?: string;
  supplierCountry?: string;
  supplierVat?: string;
  currency?: string;
  vatAmount?: number;
  amount?: number;
  reverseChargeWording?: boolean;
  attributes?: Record<string, string>;
  /** Evidence changes always fail closed, even if a rule otherwise matches. */
  changedBuyer?: boolean;
  changedSupplier?: boolean;
  changedVat?: boolean;
  changedCurrency?: boolean;
  unusualAmount?: boolean;
  contradictoryEvidence?: boolean;
};

export type PostingRuleOutcome = {
  account?: string;
  vatTreatment?: string;
  textTemplate?: string;
  dimensions?: Record<string, string>;
};

definition.exactParser:
const BOOLEAN_FLAGS = new Set([
  "--force",
  "--help",
  "--example",
  "--json",
  "--sign-with-ed25519",
  "--archive",
  "--enrich-cvr",
  "--include-archived",
  "--ixbrl-taxonomy",
  "--after-retention-expiry",
  "--no-vat",
  "--no-open",
]);

export type ParsedCliArgs = {
  positionals: string[];
  flags: Map<string, string | true>;
  errors: string[];
};

export function parseCliArgs(argv: string[]): ParsedCliArgs {
  const tokens = argv.slice(2);
  const positionals: string[] = [];
  const flags = new Map<string, string | true>();
  const errors: string[] = [];

  let optionsTerminated = false;

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i]!;

    if (!optionsTerminated && token === "--") {
      optionsTerminated = true;
      continue;
    }

    if (optionsTerminated || !token.startsWith("--")) {
      positionals.push(token);
      continue;
    }

    // `--flag=value` form: value is attached, so it may begin with dashes
    // or be empty without being confused for a missing-value error.
    const eq = token.indexOf("=");
    if (eq !== -1) {
      const name = token.slice(0, eq);
      const value = token.slice(eq + 1);
      if (BOOLEAN_FLAGS.has(name)) {
        errors.push(`Flag ${name} does not take a value`);
        continue;
      }
      flags.set(name, value);
      continue;
    }

    if (BOOLEAN_FLAGS.has(token)) {
      const next = tokens[i + 1];
      if (next && next !== "--" && !next.startsWith("--")) {
        errors.push(`Flag ${token} does not take a value`);
        i += 1;
        continue;
      }
      flags.set(token, true);
      continue;
    }

    const value = tokens[i + 1];
    if (value === undefined || value === "--" || value.startsWith("--")) {
      errors.push(`Flag ${token} requires a value`);
      continue;
    }
    flags.set(token, value);
    i += 1;
  }

  return { positionals, flags, errors };
}

stdout.genericRenderer:
import { formatKronerDa } from "../core/money";

export type OutputFormat = "json" | "human";

export function resolveOutputFormat(flags: Map<string, string | true>): OutputFormat | null {
  if (flags.has("--json")) return "json";
  const format = flags.get("--format");
  if (format === undefined) return process.stdout.isTTY ? "human" : "json";
  if (format === "json" || format === "human") return format;
  return null;
}

export function printStructuredResult(commandLabel: string, result: Record<string, unknown>, format: OutputFormat) {
  const ok = result.ok !== false;
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  const lines = ok ? buildHumanSuccess(commandLabel, result) : buildHumanError(commandLabel, result);
  const text = lines.join("\n");
  if (ok) console.log(text);
  else console.error(text);
}

/**
 * A command's `description` in `cli-meta.ts` is a full sentence (often two)
 * meant for help text — never a heading. #268: a write command that falls
 * through to the generic human renderer used to print that whole description
 * as the `✔` heading. `headingFromLabel` collapses such a label to a short
 * heading: the first clause before an em dash / period, capped in length.
 */
function headingFromLabel(commandLabel: string): string {
  const firstClause = commandLabel.split(/\s+[—–-]\s+|\.\s/)[0]?.trim() ?? commandLabel;
  const short = firstClause.length > 0 ? firstClause : commandLabel;
  return short.length > 60 ? `${short.slice(0, 57).trimEnd()}…` : short;
}

function buildHumanSuccess(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✔ ${headingFromLabel(commandLabel)}`];
  for (const line of collectSummaryLines(result)) lines.push(`  ${line}`);
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  return lines;
}

export function buildHumanError(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✘ ${commandLabel} failed`];
  const errors = asStringArray(result.errors);
  if (errors.length > 0) {
    for (const error of errors) lines.push(`  → ${error}`);
  } else {
    lines.push("  → Kommandoen fejlede uden en specifik fejlbesked.");
  }
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  appendPeriodCloseGuidance(lines, errors);
  return lines;
}

/**
 * `vat momsangivelse` and `report annual` reject an unfinalised period with a
 * terse "... is not closed ... run 'period close' first". For an owner near a
 * deadline that is cryptic, so when we recognise that failure we append a
 * plain-Danish explanation of what closing a period means and the exact
 * command to run. (#227)
 */
function appendPeriodCloseGuidance(lines: string[], errors: string[]): void {
  const closeError = errors.find(
    (e) => /is not closed/i.test(e) && /period close/i.test(e),
  );
  if (!closeError) return;
  const range = closeError.match(/(\d{4}-\d{2}-\d{2})\.\.(\d{4}-\d{2}-\d{2})/);
  const isFiscalYear = /fiscal|regnskabsår|annual/i.test(closeError);
  const kind = isFiscalYear ? "fiscal_year" : "vat_period";
  const fromTo = range ? `--from ${range[1]} --to ${range[2]}` : "--from <YYYY-MM-DD> --to <YYYY-MM-DD>";
  lines.push("");
  lines.push("  Sådan kommer du videre:");
  lines.push(
    "    En momsangivelse/årsrapport kan kun bygges på en LUKKET periode — det sikrer,",
  );
  lines.push(
    "    at tallene ikke ændrer sig efter indberetning. Du lukker perioden med:",
  );
  lines.push(`      rentemester period close --company <path> ${fromTo} --kind ${kind}`);
  lines.push(
    "    Luk først perioden når alle bilag for perioden er bogført — en lukket periode",
  );
  lines.push(
    "    blokerer ny bogføring med dato i perioden. Brug --status reported i stedet for",
  );
  lines.push(
    "    standard 'closed', hvis du allerede har indberettet til SKAT/Erhvervsstyrelsen.",
  );
}

/**
 * Danish labels for the result keys a write command commonly returns. The
 * generic human fallback (`collectSummaryLines`) used to English-ify keys via
 * `humanizeKey` ("Invoice Number", "Document Id"); for a Danish-facing tool
 * that is wrong. Any key without an entry here keeps the humanized form, but
 * the common write-result fields are now translated. (#268)
 *
 * Round-2 review (Batch E-1) expanded the set so read commands that return
 * single objects (audit verify, company profile, gdpr export/forget,
 * customer create, invoice post) actually render meaningful content under
 * `--format human` instead of just echoing the command description.
 */
const WRITE_RESULT_LABEL_DA: Record<string, string> = {
  message: "Besked",
  invoiceNumber: "Fakturanummer",
  invoiceNo: "Fakturanummer",
  entryNo: "Posteringsnummer",
  entryNumber: "Posteringsnummer",
  documentId: "Bilags-id",
  journalEntryId: "Finanspostering-id",
  importBatchId: "Import-batch-id",
  imported: "Importeret",
  skippedDuplicates: "Sprunget over (dubletter)",
  backupId: "Backup-id",
  exportDir: "Eksportmappe",
  latestBackupId: "Seneste backup-id",
  expiredCount: "Udløbne",
  totalCount: "I alt",
  storedPath: "Gemt fil",
  pdfStoredPath: "PDF-fil",
  // Batch E-1: read-command friendly labels.
  entries: "Posteringer kontrolleret",
  chainOk: "Kæden er hel",
  erasedCount: "Anonymiseret",
  skippedCount: "Sprunget over",
  alreadyErasedCount: "Allerede anonymiseret",
  recordCount: "Rækker fundet",
  count: "Antal",
  total: "I alt",
  // Profile / contact fields (company profile, customer/vendor create).
  name: "Navn",
  cvr: "CVR",
  email: "E-mail",
  address: "Adresse",
  postalCode: "Postnummer",
  city: "By",
  country: "Land",
  currency: "Valuta",
  paymentTermsDays: "Betalingsfrist (dage)",
  vatPeriodType: "Momsperiode",
  vatPeriodLabel: "Momsstatus",
  vatRegistered: "Momsregistreret",
  companyForm: "Selskabsform",
  industryText: "Branche",
  cvrStatus: "CVR-status",
  auditWaived: "Revision fravalgt",
  fiscalYearStartMonth: "Regnskabsår starter (måned)",
  customerId: "Kunde-id",
  vendorId: "Leverandør-id",
  slug: "Slug",
};

/**
 * Top-level keys whose VALUE is a nested object that should be drilled into
 * — every scalar field inside becomes its own labelled line. Lets commands
 * like `company profile` (returns `{ ok, profile: {...} }`) emit each profile
 * field without per-command renderers. Batch E-1.
 */
const NESTED_DRILL_KEYS = new Set<string>([
  "profile",
  "customer",
  "vendor",
  "company",
  "settings",
  "depreciation",
  "writeOff",
  "reminder",
  "credit",
  "suggestion",
  "summary",
]);

function collectSummaryLines(result: Record<string, unknown>) {
  const preferredKeys = [
    "message",
    "invoiceNumber",
    "invoiceNo",
    "entryNo",
    "entryNumber",
    "documentId",
    "journalEntryId",
    "importBatchId",
    "imported",
    "skippedDuplicates",
    "backupId",
    "exportDir",
    "latestBackupId",
    "expiredCount",
    "totalCount",
    "entries",
    "chainOk",
    "erasedCount",
    "skippedCount",
    "alreadyErasedCount",
    "recordCount",
    "count",
    "total",
    "name",
    "cvr",
    "email",
    "address",
    "postalCode",
    "city",
    "country",
    "currency",
    "paymentTermsDays",
    "vatPeriodType",
    "vatPeriodLabel",
    "vatRegistered",
    "companyForm",
    "industryText",
    "cvrStatus",
    "auditWaived",
    "fiscalYearStartMonth",
    "customerId",
    "vendorId",
    "slug",
  ];
  const lines: string[] = [];
  const seen = new Set<string>();
  for (const key of preferredKeys) {
    if (seen.has(key)) continue;
    const value = result[key];
    const rendered = renderScalar(value);
    if (rendered === null) continue;
    // #268: never emit an English key on a Danish-facing tool — use the Danish
    // label when one exists, falling back to the humanized form otherwise.
    lines.push(
      `${WRITE_RESULT_LABEL_DA[key] ?? humanizeKey(key)}: ${translateValueForKey(key, rendered)}`,
    );
    seen.add(key);
  }
  // Batch E-1: drill one level into well-known nested-object keys. Lets
  // `company profile` (returns `{ ok, profile: {...} }`) actually render
  // each profile field instead of showing only "✔ <command description>".
  for (const [key, value] of Object.entries(result)) {
    if (!NESTED_DRILL_KEYS.has(key)) continue;
    if (value == null || typeof value !== "object" || Array.isArray(value)) continue;
    const inner = value as Record<string, unknown>;
    for (const [innerKey, innerValue] of Object.entries(inner)) {
      if (seen.has(innerKey)) continue;
      const rendered = renderScalar(innerValue);
      if (rendered === null) continue;
      lines.push(
        `${WRITE_RESULT_LABEL_DA[innerKey] ?? humanizeKey(innerKey)}: ${translateValueForKey(innerKey, rendered)}`,
      );
      seen.add(innerKey);
    }
  }
  return lines;
}

function renderScalar(value: unknown): string | null {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return null;
}

/**
 * Danish display values for the handful of enum-valued profile fields whose raw
 * stored form is an English token (e.g. `quarter`, `end-year`). #268 already
 * translates the key (label) into Danish; this translates the VALUE so an owner
 * never sees "Momsperiode: quarter". Keyed by field, then by raw value; unknown
 * fields/values pass through unchanged.
 */
const VALUE_LABEL_DA: Record<string, Record<string, string>> = {
  vatPeriodType: {
    month: "måned",
    quarter: "kvartal",
    "half-year": "halvår",
  },
  vatRegistered: {
    true: "Ja",
    false: "Nej",
  },
  fiscalYearLabelStrategy: {
    "end-year": "slutår",
    "start-year": "startår",
  },
};

function translateValueForKey(key: string, rendered: string): string {
  return VALUE_LABEL_DA[key]?.[rendered] ?? rendered;
}

function humanizeKey(key: string) {
  return key
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/_/g, " ")
    .replace(/^./, (c) => c.toUpperCase());
}

export function asStringArray(value: unknown) {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

/**
 * Format a DKK amount as Danish kroner-og-øre, e.g. 38.3 -> "38,30 kr.",
 * -1234.5 -> "-1.234,50 kr.". Non-finite/missing input yields "—".
 *
 * Thin re-export of the single canonical formatter `formatKronerDa` in
 * `core/money.ts` — kept under the historical name so the many call sites in
 * this file stay unchanged. (#314)
 */
export function formatKroner(value: unknown): string {
  return formatKronerDa(value);
}

/** Render an integer count, falling back to 0 for missing values. */
export function asCount(value: unknown): number {
  const num = typeof value === "number" ? value : Number(value);
  return Number.isFinite(num) ? num : 0;
}

export function asText(value: unknown, fallback = "—"): string {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  return fallback;
}

export function asArray(value: unknown): Array<Record<string, unknown>> {
  return Array.isArray(value)
    ? value.filter((item): item is Record<string, unknown> => typeof item === "object" && item !== null)
    : [];
}

/**
 * Format a percentage with Danish decimal comma, e.g. 8.05 -> "8,05 %".
 * Non-finite/missing input yields "—".
 */
export function formatPercent(value: unknown): string {
  const num = typeof value === "number" ? value : Number(value);
  if (value == null || value === "" || !Number.isFinite(num)) return "—";
  const text = (Math.round(num * 100) / 100)
    .toString()
    .replace(".", ",");
  return `${text} %`;
}

export function appendWarnings(lines: string[], result: Record<string, unknown>): void {
  const warnings = asStringArray(result.warnings);
  if (warnings.length === 0) return;
  lines.push("");
  lines.push("Advarsler:");
  for (const warning of warnings) lines.push(`  - ${warning}`);
}

stdout.reportDispatch:
import { type OutputFormat, buildHumanError, printStructuredResult } from "./common";
import { renderVatReport, renderVatFiling, renderAnnualReport, renderTaxReturn } from "./vat";
import {
  renderInvoiceStatus,
  renderInvoiceInterest,
  renderInvoiceCompensation,
  renderInvoiceValidate,
  renderInvoiceCreate,
} from "./invoice";
import {
  renderBackupStatus,
  renderExceptionsList,
  renderTrialBalance,
  renderProfitAndLoss,
  renderBalanceSheet,
  renderRetentionStatus,
} from "./dashboard";
import { renderBankReconciliation } from "./bank";

// ===========================================================================
// HUMAN-READABLE REPORT RENDERING — DISPATCH (#211)
// ---------------------------------------------------------------------------
// Read/report commands emit deterministic JSON with English field names for
// agents. When a human runs them (`--format human` / a TTY) that JSON is
// unreadable. `renderHumanReport` renders the same payloads in clear Danish
// with money in kroner-og-øre. The `--format json` path is untouched: handlers
// keep calling `ctx.emitResult` for JSON and only branch into this renderer
// for the human format.
// ===========================================================================

/** Report kinds with a dedicated Danish human renderer. */
export type HumanReportKind =
  | "vat-report"
  | "vat-filing"
  | "report-annual"
  | "report-tax"
  | "invoice-status"
  | "invoice-interest"
  | "invoice-compensation"
  | "invoice-validate"
  | "exceptions-list"
  | "report-trial-balance"
  | "report-profit-loss"
  | "report-balance"
  | "retention-status"
  | "reconcile-bank"
  | "backup-status"
  // #177: `report annual --ixbrl-taxonomy` prints the bounded iXBRL subset.
  // No dedicated renderer — it falls back to the generic structured output.
  | "report-annual-ixbrl-taxonomy";

/**
 * Render a read/report `result` payload as Danish human-readable text.
 *
 * Returns `null` when there is no dedicated renderer for `kind` or the payload
 * does not look renderable, so callers can fall back to the generic
 * `printStructuredResult` rendering.
 */
export function renderHumanReport(
  kind: HumanReportKind,
  result: Record<string, unknown>,
): string | null {
  // `backup-status` reports `ok: false` when the weekly backup duty is NOT met
  // — that is a valid compliance status to render, not a command failure. Its
  // renderer handles both states, so it must run before the generic
  // ok-false-as-error path. (#240)
  if (kind === "backup-status") {
    return renderBackupStatus(result);
  }
  // `invoice validate` reports `ok: false` when the payload is INVALID — that
  // is a valid validation verdict to render in full (the figures and every
  // rejection reason), not a command crash. Its renderer covers both the
  // valid and invalid verdict, so it must run before the generic
  // ok-false-as-error path. (#250)
  if (kind === "invoice-validate") {
    return renderInvoiceValidate(result);
  }
  if (result.ok === false) {
    return buildHumanError(humanReportTitle(kind), result).join("\n");
  }
  switch (kind) {
    case "vat-report":
      return renderVatReport(result);
    case "vat-filing":
      return renderVatFiling(result);
    case "report-annual":
      return renderAnnualReport(result);
    case "report-tax":
      return renderTaxReturn(result);
    case "invoice-status":
      return renderInvoiceStatus(result);
    case "invoice-interest":
      return renderInvoiceInterest(result);
    case "invoice-compensation":
      return renderInvoiceCompensation(result);
    case "exceptions-list":
      return renderExceptionsList(result);
    case "report-trial-balance":
      return renderTrialBalance(result);
    case "report-profit-loss":
      return renderProfitAndLoss(result);
    case "report-balance":
      return renderBalanceSheet(result);
    case "retention-status":
      return renderRetentionStatus(result);
    case "reconcile-bank":
      return renderBankReconciliation(result);
    default:
      // `backup-status` and `invoice-validate` are handled before this switch
      // (their renderers cover the ok:false state too), so they never reach
      // here.
      return null;
  }
}

/**
 * Emit a read/report `result` either as the byte-stable agent JSON or as the
 * Danish human rendering, depending on `format`. The `--format json` path is
 * exactly `JSON.stringify(result, null, 2)` — unchanged from `emitResult` —
 * so agents see no difference. Only the human rendering is new.
 *
 * Returns the process exit code to apply (1 when `result.ok === false`).
 */
export function emitHumanReport(
  kind: HumanReportKind,
  result: Record<string, unknown>,
  format: OutputFormat,
): void {
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    const human = renderHumanReport(kind, result);
    if (human !== null) {
      if (result.ok === false) console.error(human);
      else console.log(human);
    } else {
      printStructuredResult(humanReportTitle(kind), result, format);
    }
  }
  if (result.ok === false) process.exitCode = 1;
}

function humanReportTitle(kind: HumanReportKind): string {
  switch (kind) {
    case "vat-report":
      return "Momsrapport";
    case "vat-filing":
      return "Momsangivelse";
    case "report-annual":
      return "Årsrapport";
    case "report-tax":
      return "Skattemæssig indkomst";
    case "invoice-status":
      return "Fakturastatus";
    case "invoice-interest":
      return "Morarente";
    case "invoice-compensation":
      return "Kompensation for sen betaling";
    case "invoice-validate":
      return "Fakturavalidering";
    case "exceptions-list":
      return "Undtagelser";
    case "report-trial-balance":
      return "Saldobalance";
    case "report-profit-loss":
      return "Resultatopgørelse";
    case "report-balance":
      return "Balance";
    case "retention-status":
      return "Opbevaringsstatus";
    case "reconcile-bank":
      return "Bankafstemning";
    case "backup-status":
      return "Backup-status";
    case "report-annual-ixbrl-taxonomy":
      return "iXBRL-taksonomi (afgrænset udsnit)";
  }
}

/** Write-command kinds with a dedicated Danish human renderer. (#266, #268) */
export type HumanWriteKind = "invoice-create";

/**
 * Emit a write-command `result` either as the byte-stable agent JSON or as a
 * Danish human rendering, depending on `format`. The `--format json` path is
 * exactly `JSON.stringify(result, null, 2)` — unchanged from `emitResult` — so
 * agents see no difference. Sets `process.exitCode = 1` on `ok: false`. (#268)
 */
export function emitHumanWrite(
  kind: HumanWriteKind,
  result: Record<string, unknown>,
  format: OutputFormat,
): void {
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    const human = kind === "invoice-create" ? renderInvoiceCreate(result) : null;
    if (human !== null) {
      if (result.ok === false) console.error(human);
      else console.log(human);
    } else {
      printStructuredResult(kind, result, format);
    }
  }
  if (result.ok === false) process.exitCode = 1;
}

