(ctx) => {
    if (!ctx.hasFlag("--confirm")) ctx.fatal("--confirm is required for apply");
    const runId = Number(ctx.arg("--run-id")); const planHash = ctx.arg("--plan-hash"); if (!Number.isInteger(runId) || !planHash) ctx.fatal("--run-id and --plan-hash are required for apply");
    const db = openCommandDb(ctx); try { migrate(db); const applied = applyBookkeepingBatch(db, { runId, planHash: planHash!, actor: actor(ctx) }); ctx.emitResult({ ...applied, runId, planHash, state: runState(db, runId) }); } finally { db.close(); }
  }

definition.exactParser:
const BOOLEAN_FLAGS = new Set([
  "--force",
  "--help",
  "--example",
  "--json",
  "--sign-with-ed25519",
  "--archive",
  "--enrich-cvr",
  "--include-archived",
  "--ixbrl-taxonomy",
  "--after-retention-expiry",
  "--no-vat",
  "--no-open",
]);

export type ParsedCliArgs = {
  positionals: string[];
  flags: Map<string, string | true>;
  errors: string[];
};

export function parseCliArgs(argv: string[]): ParsedCliArgs {
  const tokens = argv.slice(2);
  const positionals: string[] = [];
  const flags = new Map<string, string | true>();
  const errors: string[] = [];

  let optionsTerminated = false;

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i]!;

    if (!optionsTerminated && token === "--") {
      optionsTerminated = true;
      continue;
    }

    if (optionsTerminated || !token.startsWith("--")) {
      positionals.push(token);
      continue;
    }

    // `--flag=value` form: value is attached, so it may begin with dashes
    // or be empty without being confused for a missing-value error.
    const eq = token.indexOf("=");
    if (eq !== -1) {
      const name = token.slice(0, eq);
      const value = token.slice(eq + 1);
      if (BOOLEAN_FLAGS.has(name)) {
        errors.push(`Flag ${name} does not take a value`);
        continue;
      }
      flags.set(name, value);
      continue;
    }

    if (BOOLEAN_FLAGS.has(token)) {
      const next = tokens[i + 1];
      if (next && next !== "--" && !next.startsWith("--")) {
        errors.push(`Flag ${token} does not take a value`);
        i += 1;
        continue;
      }
      flags.set(token, true);
      continue;
    }

    const value = tokens[i + 1];
    if (value === undefined || value === "--" || value.startsWith("--")) {
      errors.push(`Flag ${token} requires a value`);
      continue;
    }
    flags.set(token, value);
    i += 1;
  }

  return { positionals, flags, errors };
}

stdout.genericRenderer:
import { formatKronerDa } from "../core/money";

export type OutputFormat = "json" | "human";

export function resolveOutputFormat(flags: Map<string, string | true>): OutputFormat | null {
  if (flags.has("--json")) return "json";
  const format = flags.get("--format");
  if (format === undefined) return process.stdout.isTTY ? "human" : "json";
  if (format === "json" || format === "human") return format;
  return null;
}

export function printStructuredResult(commandLabel: string, result: Record<string, unknown>, format: OutputFormat) {
  const ok = result.ok !== false;
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  const lines = ok ? buildHumanSuccess(commandLabel, result) : buildHumanError(commandLabel, result);
  const text = lines.join("\n");
  if (ok) console.log(text);
  else console.error(text);
}

/**
 * A command's `description` in `cli-meta.ts` is a full sentence (often two)
 * meant for help text — never a heading. #268: a write command that falls
 * through to the generic human renderer used to print that whole description
 * as the `✔` heading. `headingFromLabel` collapses such a label to a short
 * heading: the first clause before an em dash / period, capped in length.
 */
function headingFromLabel(commandLabel: string): string {
  const firstClause = commandLabel.split(/\s+[—–-]\s+|\.\s/)[0]?.trim() ?? commandLabel;
  const short = firstClause.length > 0 ? firstClause : commandLabel;
  return short.length > 60 ? `${short.slice(0, 57).trimEnd()}…` : short;
}

function buildHumanSuccess(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✔ ${headingFromLabel(commandLabel)}`];
  for (const line of collectSummaryLines(result)) lines.push(`  ${line}`);
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  return lines;
}

export function buildHumanError(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✘ ${commandLabel} failed`];
  const errors = asStringArray(result.errors);
  if (errors.length > 0) {
    for (const error of errors) lines.push(`  → ${error}`);
  } else {
    lines.push("  → Kommandoen fejlede uden en specifik fejlbesked.");
  }
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  appendPeriodCloseGuidance(lines, errors);
  return lines;
}

/**
 * `vat momsangivelse` and `report annual` reject an unfinalised period with a
 * terse "... is not closed ... run 'period close' first". For an owner near a
 * deadline that is cryptic, so when we recognise that failure we append a
 * plain-Danish explanation of what closing a period means and the exact
 * command to run. (#227)
 */
function appendPeriodCloseGuidance(lines: string[], errors: string[]): void {
  const closeError = errors.find(
    (e) => /is not closed/i.test(e) && /period close/i.test(e),
  );
  if (!closeError) return;
  const range = closeError.match(/(\d{4}-\d{2}-\d{2})\.\.(\d{4}-\d{2}-\d{2})/);
  const isFiscalYear = /fiscal|regnskabsår|annual/i.test(closeError);
  const kind = isFiscalYear ? "fiscal_year" : "vat_period";
  const fromTo = range ? `--from ${range[1]} --to ${range[2]}` : "--from <YYYY-MM-DD> --to <YYYY-MM-DD>";
  lines.push("");
  lines.push("  Sådan kommer du videre:");
  lines.push(
    "    En momsangivelse/årsrapport kan kun bygges på en LUKKET periode — det sikrer,",
  );
  lines.push(
    "    at tallene ikke ændrer sig efter indberetning. Du lukker perioden med:",
  );
  lines.push(`      rentemester period close --company <path> ${fromTo} --kind ${kind}`);
  lines.push(
    "    Luk først perioden når alle bilag for perioden er bogført — en lukket periode",
  );
  lines.push(
    "    blokerer ny bogføring med dato i perioden. Brug --status reported i stedet for",
  );
  lines.push(
    "    standard 'closed', hvis du allerede har indberettet til SKAT/Erhvervsstyrelsen.",
  );
}

/**
 * Danish labels for the result keys a write command commonly returns. The
 * generic human fallback (`collectSummaryLines`) used to English-ify keys via
 * `humanizeKey` ("Invoice Number", "Document Id"); for a Danish-facing tool
 * that is wrong. Any key without an entry here keeps the humanized form, but
 * the common write-result fields are now translated. (#268)
 *
 * Round-2 review (Batch E-1) expanded the set so read commands that return
 * single objects (audit verify, company profile, gdpr export/forget,
 * customer create, invoice post) actually render meaningful content under
 * `--format human` instead of just echoing the command description.
 */
const WRITE_RESULT_LABEL_DA: Record<string, string> = {
  message: "Besked",
  invoiceNumber: "Fakturanummer",
  invoiceNo: "Fakturanummer",
  entryNo: "Posteringsnummer",
  entryNumber: "Posteringsnummer",
  documentId: "Bilags-id",
  journalEntryId: "Finanspostering-id",
  importBatchId: "Import-batch-id",
  imported: "Importeret",
  skippedDuplicates: "Sprunget over (dubletter)",
  backupId: "Backup-id",
  exportDir: "Eksportmappe",
  latestBackupId: "Seneste backup-id",
  expiredCount: "Udløbne",
  totalCount: "I alt",
  storedPath: "Gemt fil",
  pdfStoredPath: "PDF-fil",
  // Batch E-1: read-command friendly labels.
  entries: "Posteringer kontrolleret",
  chainOk: "Kæden er hel",
  erasedCount: "Anonymiseret",
  skippedCount: "Sprunget over",
  alreadyErasedCount: "Allerede anonymiseret",
  recordCount: "Rækker fundet",
  count: "Antal",
  total: "I alt",
  // Profile / contact fields (company profile, customer/vendor create).
  name: "Navn",
  cvr: "CVR",
  email: "E-mail",
  address: "Adresse",
  postalCode: "Postnummer",
  city: "By",
  country: "Land",
  currency: "Valuta",
  paymentTermsDays: "Betalingsfrist (dage)",
  vatPeriodType: "Momsperiode",
  vatPeriodLabel: "Momsstatus",
  vatRegistered: "Momsregistreret",
  companyForm: "Selskabsform",
  industryText: "Branche",
  cvrStatus: "CVR-status",
  auditWaived: "Revision fravalgt",
  fiscalYearStartMonth: "Regnskabsår starter (måned)",
  customerId: "Kunde-id",
  vendorId: "Leverandør-id",
  slug: "Slug",
};

/**
 * Top-level keys whose VALUE is a nested object that should be drilled into
 * — every scalar field inside becomes its own labelled line. Lets commands
 * like `company profile` (returns `{ ok, profile: {...} }`) emit each profile
 * field without per-command renderers. Batch E-1.
 */
const NESTED_DRILL_KEYS = new Set<string>([
  "profile",
  "customer",
  "vendor",
  "company",
  "settings",
  "depreciation",
  "writeOff",
  "reminder",
  "credit",
  "suggestion",
  "summary",
]);

function collectSummaryLines(result: Record<string, unknown>) {
  const preferredKeys = [
    "message",
    "invoiceNumber",
    "invoiceNo",
    "entryNo",
    "entryNumber",
    "documentId",
    "journalEntryId",
    "importBatchId",
    "imported",
    "skippedDuplicates",
    "backupId",
    "exportDir",
    "latestBackupId",
    "expiredCount",
    "totalCount",
    "entries",
    "chainOk",
    "erasedCount",
    "skippedCount",
    "alreadyErasedCount",
    "recordCount",
    "count",
    "total",
    "name",
    "cvr",
    "email",
    "address",
    "postalCode",
    "city",
    "country",
    "currency",
    "paymentTermsDays",
    "vatPeriodType",
    "vatPeriodLabel",
    "vatRegistered",
    "companyForm",
    "industryText",
    "cvrStatus",
    "auditWaived",
    "fiscalYearStartMonth",
    "customerId",
    "vendorId",
    "slug",
  ];
  const lines: string[] = [];
  const seen = new Set<string>();
  for (const key of preferredKeys) {
    if (seen.has(key)) continue;
    const value = result[key];
    const rendered = renderScalar(value);
    if (rendered === null) continue;
    // #268: never emit an English key on a Danish-facing tool — use the Danish
    // label when one exists, falling back to the humanized form otherwise.
    lines.push(
      `${WRITE_RESULT_LABEL_DA[key] ?? humanizeKey(key)}: ${translateValueForKey(key, rendered)}`,
    );
    seen.add(key);
  }
  // Batch E-1: drill one level into well-known nested-object keys. Lets
  // `company profile` (returns `{ ok, profile: {...} }`) actually render
  // each profile field instead of showing only "✔ <command description>".
  for (const [key, value] of Object.entries(result)) {
    if (!NESTED_DRILL_KEYS.has(key)) continue;
    if (value == null || typeof value !== "object" || Array.isArray(value)) continue;
    const inner = value as Record<string, unknown>;
    for (const [innerKey, innerValue] of Object.entries(inner)) {
      if (seen.has(innerKey)) continue;
      const rendered = renderScalar(innerValue);
      if (rendered === null) continue;
      lines.push(
        `${WRITE_RESULT_LABEL_DA[innerKey] ?? humanizeKey(innerKey)}: ${translateValueForKey(innerKey, rendered)}`,
      );
      seen.add(innerKey);
    }
  }
  return lines;
}

function renderScalar(value: unknown): string | null {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return null;
}

/**
 * Danish display values for the handful of enum-valued profile fields whose raw
 * stored form is an English token (e.g. `quarter`, `end-year`). #268 already
 * translates the key (label) into Danish; this translates the VALUE so an owner
 * never sees "Momsperiode: quarter". Keyed by field, then by raw value; unknown
 * fields/values pass through unchanged.
 */
const VALUE_LABEL_DA: Record<string, Record<string, string>> = {
  vatPeriodType: {
    month: "måned",
    quarter: "kvartal",
    "half-year": "halvår",
  },
  vatRegistered: {
    true: "Ja",
    false: "Nej",
  },
  fiscalYearLabelStrategy: {
    "end-year": "slutår",
    "start-year": "startår",
  },
};

function translateValueForKey(key: string, rendered: string): string {
  return VALUE_LABEL_DA[key]?.[rendered] ?? rendered;
}

function humanizeKey(key: string) {
  return key
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/_/g, " ")
    .replace(/^./, (c) => c.toUpperCase());
}

export function asStringArray(value: unknown) {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

/**
 * Format a DKK amount as Danish kroner-og-øre, e.g. 38.3 -> "38,30 kr.",
 * -1234.5 -> "-1.234,50 kr.". Non-finite/missing input yields "—".
 *
 * Thin re-export of the single canonical formatter `formatKronerDa` in
 * `core/money.ts` — kept under the historical name so the many call sites in
 * this file stay unchanged. (#314)
 */
export function formatKroner(value: unknown): string {
  return formatKronerDa(value);
}

/** Render an integer count, falling back to 0 for missing values. */
export function asCount(value: unknown): number {
  const num = typeof value === "number" ? value : Number(value);
  return Number.isFinite(num) ? num : 0;
}

export function asText(value: unknown, fallback = "—"): string {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  return fallback;
}

export function asArray(value: unknown): Array<Record<string, unknown>> {
  return Array.isArray(value)
    ? value.filter((item): item is Record<string, unknown> => typeof item === "object" && item !== null)
    : [];
}

/**
 * Format a percentage with Danish decimal comma, e.g. 8.05 -> "8,05 %".
 * Non-finite/missing input yields "—".
 */
export function formatPercent(value: unknown): string {
  const num = typeof value === "number" ? value : Number(value);
  if (value == null || value === "" || !Number.isFinite(num)) return "—";
  const text = (Math.round(num * 100) / 100)
    .toString()
    .replace(".", ",");
  return `${text} %`;
}

export function appendWarnings(lines: string[], result: Record<string, unknown>): void {
  const warnings = asStringArray(result.warnings);
  if (warnings.length === 0) return;
  lines.push("");
  lines.push("Advarsler:");
  for (const warning of warnings) lines.push(`  - ${warning}`);
}

stdout.reportDispatch:
import { type OutputFormat, buildHumanError, printStructuredResult } from "./common";
import { renderVatReport, renderVatFiling, renderAnnualReport, renderTaxReturn } from "./vat";
import {
  renderInvoiceStatus,
  renderInvoiceInterest,
  renderInvoiceCompensation,
  renderInvoiceValidate,
  renderInvoiceCreate,
} from "./invoice";
import {
  renderBackupStatus,
  renderExceptionsList,
  renderTrialBalance,
  renderProfitAndLoss,
  renderBalanceSheet,
  renderRetentionStatus,
} from "./dashboard";
import { renderBankReconciliation } from "./bank";

// ===========================================================================
// HUMAN-READABLE REPORT RENDERING — DISPATCH (#211)
// ---------------------------------------------------------------------------
// Read/report commands emit deterministic JSON with English field names for
// agents. When a human runs them (`--format human` / a TTY) that JSON is
// unreadable. `renderHumanReport` renders the same payloads in clear Danish
// with money in kroner-og-øre. The `--format json` path is untouched: handlers
// keep calling `ctx.emitResult` for JSON and only branch into this renderer
// for the human format.
// ===========================================================================

/** Report kinds with a dedicated Danish human renderer. */
export type HumanReportKind =
  | "vat-report"
  | "vat-filing"
  | "report-annual"
  | "report-tax"
  | "invoice-status"
  | "invoice-interest"
  | "invoice-compensation"
  | "invoice-validate"
  | "exceptions-list"
  | "report-trial-balance"
  | "report-profit-loss"
  | "report-balance"
  | "retention-status"
  | "reconcile-bank"
  | "backup-status"
  // #177: `report annual --ixbrl-taxonomy` prints the bounded iXBRL subset.
  // No dedicated renderer — it falls back to the generic structured output.
  | "report-annual-ixbrl-taxonomy";

/**
 * Render a read/report `result` payload as Danish human-readable text.
 *
 * Returns `null` when there is no dedicated renderer for `kind` or the payload
 * does not look renderable, so callers can fall back to the generic
 * `printStructuredResult` rendering.
 */
export function renderHumanReport(
  kind: HumanReportKind,
  result: Record<string, unknown>,
): string | null {
  // `backup-status` reports `ok: false` when the weekly backup duty is NOT met
  // — that is a valid compliance status to render, not a command failure. Its
  // renderer handles both states, so it must run before the generic
  // ok-false-as-error path. (#240)
  if (kind === "backup-status") {
    return renderBackupStatus(result);
  }
  // `invoice validate` reports `ok: false` when the payload is INVALID — that
  // is a valid validation verdict to render in full (the figures and every
  // rejection reason), not a command crash. Its renderer covers both the
  // valid and invalid verdict, so it must run before the generic
  // ok-false-as-error path. (#250)
  if (kind === "invoice-validate") {
    return renderInvoiceValidate(result);
  }
  if (result.ok === false) {
    return buildHumanError(humanReportTitle(kind), result).join("\n");
  }
  switch (kind) {
    case "vat-report":
      return renderVatReport(result);
    case "vat-filing":
      return renderVatFiling(result);
    case "report-annual":
      return renderAnnualReport(result);
    case "report-tax":
      return renderTaxReturn(result);
    case "invoice-status":
      return renderInvoiceStatus(result);
    case "invoice-interest":
      return renderInvoiceInterest(result);
    case "invoice-compensation":
      return renderInvoiceCompensation(result);
    case "exceptions-list":
      return renderExceptionsList(result);
    case "report-trial-balance":
      return renderTrialBalance(result);
    case "report-profit-loss":
      return renderProfitAndLoss(result);
    case "report-balance":
      return renderBalanceSheet(result);
    case "retention-status":
      return renderRetentionStatus(result);
    case "reconcile-bank":
      return renderBankReconciliation(result);
    default:
      // `backup-status` and `invoice-validate` are handled before this switch
      // (their renderers cover the ok:false state too), so they never reach
      // here.
      return null;
  }
}

/**
 * Emit a read/report `result` either as the byte-stable agent JSON or as the
 * Danish human rendering, depending on `format`. The `--format json` path is
 * exactly `JSON.stringify(result, null, 2)` — unchanged from `emitResult` —
 * so agents see no difference. Only the human rendering is new.
 *
 * Returns the process exit code to apply (1 when `result.ok === false`).
 */
export function emitHumanReport(
  kind: HumanReportKind,
  result: Record<string, unknown>,
  format: OutputFormat,
): void {
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    const human = renderHumanReport(kind, result);
    if (human !== null) {
      if (result.ok === false) console.error(human);
      else console.log(human);
    } else {
      printStructuredResult(humanReportTitle(kind), result, format);
    }
  }
  if (result.ok === false) process.exitCode = 1;
}

function humanReportTitle(kind: HumanReportKind): string {
  switch (kind) {
    case "vat-report":
      return "Momsrapport";
    case "vat-filing":
      return "Momsangivelse";
    case "report-annual":
      return "Årsrapport";
    case "report-tax":
      return "Skattemæssig indkomst";
    case "invoice-status":
      return "Fakturastatus";
    case "invoice-interest":
      return "Morarente";
    case "invoice-compensation":
      return "Kompensation for sen betaling";
    case "invoice-validate":
      return "Fakturavalidering";
    case "exceptions-list":
      return "Undtagelser";
    case "report-trial-balance":
      return "Saldobalance";
    case "report-profit-loss":
      return "Resultatopgørelse";
    case "report-balance":
      return "Balance";
    case "retention-status":
      return "Opbevaringsstatus";
    case "reconcile-bank":
      return "Bankafstemning";
    case "backup-status":
      return "Backup-status";
    case "report-annual-ixbrl-taxonomy":
      return "iXBRL-taksonomi (afgrænset udsnit)";
  }
}

/** Write-command kinds with a dedicated Danish human renderer. (#266, #268) */
export type HumanWriteKind = "invoice-create";

/**
 * Emit a write-command `result` either as the byte-stable agent JSON or as a
 * Danish human rendering, depending on `format`. The `--format json` path is
 * exactly `JSON.stringify(result, null, 2)` — unchanged from `emitResult` — so
 * agents see no difference. Sets `process.exitCode = 1` on `ok: false`. (#268)
 */
export function emitHumanWrite(
  kind: HumanWriteKind,
  result: Record<string, unknown>,
  format: OutputFormat,
): void {
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    const human = kind === "invoice-create" ? renderInvoiceCreate(result) : null;
    if (human !== null) {
      if (result.ok === false) console.error(human);
      else console.log(human);
    } else {
      printStructuredResult(kind, result, format);
    }
  }
  if (result.ok === false) process.exitCode = 1;
}

definition.exactParser:
const BOOLEAN_FLAGS = new Set([
  "--force",
  "--help",
  "--example",
  "--json",
  "--sign-with-ed25519",
  "--archive",
  "--enrich-cvr",
  "--include-archived",
  "--ixbrl-taxonomy",
  "--after-retention-expiry",
  "--no-vat",
  "--no-open",
]);

export type ParsedCliArgs = {
  positionals: string[];
  flags: Map<string, string | true>;
  errors: string[];
};

export function parseCliArgs(argv: string[]): ParsedCliArgs {
  const tokens = argv.slice(2);
  const positionals: string[] = [];
  const flags = new Map<string, string | true>();
  const errors: string[] = [];

  let optionsTerminated = false;

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i]!;

    if (!optionsTerminated && token === "--") {
      optionsTerminated = true;
      continue;
    }

    if (optionsTerminated || !token.startsWith("--")) {
      positionals.push(token);
      continue;
    }

    // `--flag=value` form: value is attached, so it may begin with dashes
    // or be empty without being confused for a missing-value error.
    const eq = token.indexOf("=");
    if (eq !== -1) {
      const name = token.slice(0, eq);
      const value = token.slice(eq + 1);
      if (BOOLEAN_FLAGS.has(name)) {
        errors.push(`Flag ${name} does not take a value`);
        continue;
      }
      flags.set(name, value);
      continue;
    }

    if (BOOLEAN_FLAGS.has(token)) {
      const next = tokens[i + 1];
      if (next && next !== "--" && !next.startsWith("--")) {
        errors.push(`Flag ${token} does not take a value`);
        i += 1;
        continue;
      }
      flags.set(token, true);
      continue;
    }

    const value = tokens[i + 1];
    if (value === undefined || value === "--" || value.startsWith("--")) {
      errors.push(`Flag ${token} requires a value`);
      continue;
    }
    flags.set(token, value);
    i += 1;
  }

  return { positionals, flags, errors };
}

stdout.genericRenderer:
import { formatKronerDa } from "../core/money";

export type OutputFormat = "json" | "human";

export function resolveOutputFormat(flags: Map<string, string | true>): OutputFormat | null {
  if (flags.has("--json")) return "json";
  const format = flags.get("--format");
  if (format === undefined) return process.stdout.isTTY ? "human" : "json";
  if (format === "json" || format === "human") return format;
  return null;
}

export function printStructuredResult(commandLabel: string, result: Record<string, unknown>, format: OutputFormat) {
  const ok = result.ok !== false;
  if (format === "json") {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  const lines = ok ? buildHumanSuccess(commandLabel, result) : buildHumanError(commandLabel, result);
  const text = lines.join("\n");
  if (ok) console.log(text);
  else console.error(text);
}

/**
 * A command's `description` in `cli-meta.ts` is a full sentence (often two)
 * meant for help text — never a heading. #268: a write command that falls
 * through to the generic human renderer used to print that whole description
 * as the `✔` heading. `headingFromLabel` collapses such a label to a short
 * heading: the first clause before an em dash / period, capped in length.
 */
function headingFromLabel(commandLabel: string): string {
  const firstClause = commandLabel.split(/\s+[—–-]\s+|\.\s/)[0]?.trim() ?? commandLabel;
  const short = firstClause.length > 0 ? firstClause : commandLabel;
  return short.length > 60 ? `${short.slice(0, 57).trimEnd()}…` : short;
}

function buildHumanSuccess(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✔ ${headingFromLabel(commandLabel)}`];
  for (const line of collectSummaryLines(result)) lines.push(`  ${line}`);
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  return lines;
}

export function buildHumanError(commandLabel: string, result: Record<string, unknown>) {
  const lines = [`✘ ${commandLabel} failed`];
  const errors = asStringArray(result.errors);
  if (errors.length > 0) {
    for (const error of errors) lines.push(`  → ${error}`);
  } else {
    lines.push("  → Kommandoen fejlede uden en specifik fejlbesked.");
  }
  const warnings = asStringArray(result.warnings);
  if (warnings.length > 0) {
    lines.push("  Advarsler:");
    for (const warning of warnings) lines.push(`    - ${warning}`);
  }
  appendPeriodCloseGuidance(lines, errors);
  return lines;
}

/**
 * `vat momsangivelse` and `report annual` reject an unfinalised period with a
 * terse "... is not closed ... run 'period close' first". For an owner near a
 * deadline that is cryptic, so when we recognise that failure we append a
 * plain-Danish explanation of what closing a period means and the exact
 * command to run. (#227)
 */
function appendPeriodCloseGuidance(lines: string[], errors: string[]): void {
  const closeError = errors.find(
    (e) => /is not closed/i.test(e) && /period close/i.test(e),
  );
  if (!closeError) return;
  const range = closeError.match(/(\d{4}-\d{2}-\d{2})\.\.(\d{4}-\d{2}-\d{2})/);
  const isFiscalYear = /fiscal|regnskabsår|annual/i.test(closeError);
  const kind = isFiscalYear ? "fiscal_year" : "vat_period";
  const fromTo = range ? `--from ${range[1]} --to ${range[2]}` : "--from <YYYY-MM-DD> --to <YYYY-MM-DD>";
  lines.push("");
  lines.push("  Sådan kommer du videre:");
  lines.push(
    "    En momsangivelse/årsrapport kan kun bygges på en LUKKET periode — det sikrer,",
  );
  lines.push(
    "    at tallene ikke ændrer sig efter indberetning. Du lukker perioden med:",
  );
  lines.push(`      rentemester period close --company <path> ${fromTo} --kind ${kind}`);
  lines.push(
    "    Luk først perioden når alle bilag for perioden er bogført — en lukket periode",
  );
  lines.push(
    "    blokerer ny bogføring med dato i perioden. Brug --status reported i stedet for",
  );
  lines.push(
    "    standard 'closed', hvis du allerede har indberettet til SKAT/Erhvervsstyrelsen.",
  );
}

/**
 * Danish labels for the result keys a write command commonly returns. The
 * generic human fallback (`collectSummaryLines`) used to English-ify keys via
 * `humanizeKey` ("Invoice Number", "Document Id"); for a Danish-facing tool
 * that is wrong. Any key without an entry here keeps the humanized form, but
 * the common write-result fields are now translated. (#268)
 *
 * Round-2 review (Batch E-1) expanded the set so read commands that return
 * single objects (audit verify, company profile, gdpr export/forget,
 * customer create, invoice post) actually render meaningful content under
 * `--format human` instead of just echoing the command description.
 */
const WRITE_RESULT_LABEL_DA: Record<string, string> = {
  message: "Besked",
  invoiceNumber: "Fakturanummer",
  invoiceNo: "Fakturanummer",
  entryNo: "Posteringsnummer",
  entryNumber: "Posteringsnummer",
  documentId: "Bilags-id",
  journalEntryId: "Finanspostering-id",
  importBatchId: "Import-batch-id",
  imported: "Importeret",
  skippedDuplicates: "Sprunget over (dubletter)",
  backupId: "Backup-id",
  exportDir: "Eksportmappe",
  latestBackupId: "Seneste backup-id",
  expiredCount: "Udløbne",
  totalCount: "I alt",
  storedPath: "Gemt fil",
  pdfStoredPath: "PDF-fil",
  // Batch E-1: read-command friendly labels.
  entries: "Posteringer kontrolleret",
  chainOk: "Kæden er hel",
  erasedCount: "Anonymiseret",
  skippedCount: "Sprunget over",
  alreadyErasedCount: "Allerede anonymiseret",
  recordCount: "Rækker fundet",
  count: "Antal",
  total: "I alt",
  // Profile / contact fields (company profile, customer/vendor create).
  name: "Navn",
  cvr: "CVR",
  email: "E-mail",
  address: "Adresse",
  postalCode: "Postnummer",
  city: "By",
  country: "Land",
  currency: "Valuta",
  paymentTermsDays: "Betalingsfrist (dage)",
  vatPeriodType: "Momsperiode",
  vatPeriodLabel: "Momsstatus",
  vatRegistered: "Momsregistreret",
  companyForm: "Selskabsform",
  industryText: "Branche",
  cvrStatus: "CVR-status",
  auditWaived: "Revision fravalgt",
  fiscalYearStartMonth: "Regnskabsår starter (måned)",
  customerId: "Kunde-id",
  vendorId: "Leverandør-id",
  slug: "Slug",
};

/**
 * Top-level keys whose VALUE is a nested object that should be drilled into
 * — every scalar field inside becomes its own labelled line. Lets commands
 * like `company profile` (returns `{ ok, profile: {...} }`) emit each profile
 * field without per-command renderers. Batch E-1.
 */
const NESTED_DRILL_KEYS = new Set<string>([
  "profile",
  "customer",
  "vendor",
  "company",
  "settings",
  "depreciation",
  "writeOff",
  "reminder",
  "credit",
  "suggestion",
  "summary",
]);

function collectSummaryLines(result: Record<string, unknown>) {
  const preferredKeys = [
    "message",
    "invoiceNumber",
    "invoiceNo",
    "entryNo",
    "entryNumber",
    "documentId",
    "journalEntryId",
    "importBatchId",
    "imported",
    "skippedDuplicates",
    "backupId",
    "exportDir",
    "latestBackupId",
    "expiredCount",
    "totalCount",
    "entries",
    "chainOk",
    "erasedCount",
    "skippedCount",
    "alreadyErasedCount",
    "recordCount",
    "count",
    "total",
    "name",
    "cvr",
    "email",
    "address",
    "postalCode",
    "city",
    "country",
    "currency",
    "paymentTermsDays",
    "vatPeriodType",
    "vatPeriodLabel",
    "vatRegistered",
    "companyForm",
    "industryText",
    "cvrStatus",
    "auditWaived",
    "fiscalYearStartMonth",
    "customerId",
    "vendorId",
    "slug",
  ];
  const lines: string[] = [];
  const seen = new Set<string>();
  for (const key of preferredKeys) {
    if (seen.has(key)) continue;
    const value = result[key];
    const rendered = renderScalar(value);
    if (rendered === null) continue;
    // #268: never emit an English key on a Danish-facing tool — use the Danish
    // label when one exists, falling back to the humanized form otherwise.
    lines.push(
      `${WRITE_RESULT_LABEL_DA[key] ?? humanizeKey(key)}: ${translateValueForKey(key, rendered)}`,
    );
    seen.add(key);
  }
  // Batch E-1: drill one level into well-known nested-object keys. Lets
  // `company profile` (returns `{ ok, profile: {...} }`) actually render
  // each profile field instead of showing only "✔ <command description>".
  for (const [key, value] of Object.entries(result)) {
    if (!NESTED_DRILL_KEYS.has(key)) continue;
    if (value == null || typeof value !== "object" || Array.isArray(value)) continue;
    const inner = value as Record<string, unknown>;
    for (const [innerKey, innerValue] of Object.entries(inner)) {
      if (seen.has(innerKey)) continue;
      const rendered = renderScalar(innerValue);
      if (rendered === null) continue;
      lines.push(
        `${WRITE_RESULT_LABEL_DA[innerKey] ?? humanizeKey(innerKey)}: ${translateValueForKey(innerKey, rendered)}`,
      );
      seen.add(innerKey);
    }
  }
  return lines;
}

function renderScalar(value: unknown): string | null {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return null;
}

/**
 * Danish display values for the handful of enum-valued profile fields whose raw
 * stored form is an English token (e.g. `quarter`, `end-year`). #268 already
 * translates the key (label) into Danish; this translates the VALUE so an owner
 * never sees "Momsperiode: quarter". Keyed by field, then by raw value; unknown
 * fields/values pass through unchanged.
 */
const VALUE_LABEL_DA: Record<string, Record<string, string>> = {
  vatPeriodType: {
    month: "måned",
    quarter: "kvartal",
    "half-year": "halvår",
  },
  vatRegistered: {
    true: "Ja",
    false: "Nej",
  },
  fiscalYearLabelStrategy: {
    "end-year": "slutår",
    "start-year": "startår",
  },
};

function translateValueForKey(key: string, rendered: string): string {
  return VALUE_LABEL_DA[key]?.[rendered] ?? rendered;
}

function humanizeKey(key: string) {
  return key
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/_/g, " ")
    .replace(/^./, (c) => c.toUpperCase());
}

export function asStringArray(value: unknown) {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

/**
 * Format a DKK amount as Danish kroner-og-øre, e.g. 38.3 -> "38,30 kr.",
 * -1234.5 -> "-1.234,50 kr.". Non-finite/missing input yields "—".
 *
 * Thin re-export of the single canonical formatter `formatKronerDa` in
 * `core/money.ts` — kept under the historical name so the many call sites in
 * this file stay unchanged. (#314)
 */
export function formatKroner(value: unknown): string {
  return formatKronerDa(value);
}

/** Render an integer count, falling back to 0 for missing values. */
export function asCount(value: unknown): number {
  const num = typeof value === "number" ? value : Number(value);
  return Number.isFinite(num) ? num : 0;
}

export function asText(value: unknown, fallback = "—"): string {
  if (typeof value === "string" && value.length > 0) return value;
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  return fallback;
}

export function asArray(value: unknown): Array<Record<string, unknown>> {
  return Array.isArray(value)
    ? value.filter((item): item is Record<string, unknown> => typeof item === "object" && item !== null)
    : [];
}

/**
 * Format a percentage with Danish decimal comma, e.g. 8.05 -> "8,05 %".
 * Non-finite/missing input yields "—".
 */
export function formatPercent(value: unknown): string {
  const num = typeof value === "number" ? value : Number(value);
  if (value == null || value === "" || !Number.isFinite(num)) return "—";
  const text = (Math.round(num * 100) / 100)
    .toString()
    .replace(".", ",");
  return `${text} %`;
}

export function appendWarnings(lines: string[], result: Record<string, unknown>): void {
  const warnings = asStringArray(result.warnings);
  if (warnings.length === 0) return;
  lines.push("");
  lines.push("Advarsler:");
  for (const warning of warnings) lines.push(`  - ${warning}`);
}

